function handleAiFloatingControlClick(event) {
  if (event.__narrativeCanvasClickHandled) return;
  // A drag that just ended must not toggle the window.
  if (state.aiButtonClickSuppressed) {
    state.aiButtonClickSuppressed = false;
    event.preventDefault();
    event.stopPropagation();
    return;
  }
  const action = event.currentTarget?.dataset?.action;
  if (action !== "toggle-ai-window" && action !== "close-ai-window") return;
  event.preventDefault();
  event.stopPropagation();
  event.__narrativeCanvasClickHandled = true;
  toggleAiWindow(action === "close-ai-window" ? false : null);
}

// The AI launcher is a draggable floating ball: drag moves it anywhere in its
// container, a plain click still toggles the assistant window.
function handleAiButtonPointerDown(event) {
  if (event.button !== undefined && event.button !== 0) return;
  const button = dom.aiFloatingButton;
  if (!button) return;
  const rect = button.getBoundingClientRect();
  state.aiButtonDrag = {
    startX: event.clientX,
    startY: event.clientY,
    offsetX: event.clientX - rect.left,
    offsetY: event.clientY - rect.top,
    active: false
  };
}

function handleAiButtonPointerMove(event) {
  const drag = state.aiButtonDrag;
  if (!drag) return;
  if (!drag.active && Math.hypot(event.clientX - drag.startX, event.clientY - drag.startY) < 5) return;
  drag.active = true;
  setAiButtonPosition(event.clientX - drag.offsetX, event.clientY - drag.offsetY);
  event.preventDefault();
}

function handleAiButtonPointerUp() {
  const drag = state.aiButtonDrag;
  state.aiButtonDrag = null;
  if (drag?.active) state.aiButtonClickSuppressed = true;
}

function setAiButtonPosition(clientLeft, clientTop) {
  const button = dom.aiFloatingButton;
  const parent = button?.offsetParent;
  if (!button || !parent) return;
  const parentRect = parent.getBoundingClientRect();
  const left = clamp(clientLeft - parentRect.left, 0, Math.max(0, parentRect.width - button.offsetWidth));
  const top = clamp(clientTop - parentRect.top, 0, Math.max(0, parentRect.height - button.offsetHeight));
  state.aiButtonPos = { left, top };
  applyAiButtonPosition();
}

function applyAiButtonPosition() {
  const button = dom.aiFloatingButton;
  if (!button) return;
  const pos = state.aiButtonPos;
  if (!pos || !Number.isFinite(pos.left) || !Number.isFinite(pos.top)) return;
  // Only clamp against a laid-out container; a hidden leaf reports zero sizes and
  // would jam the ball into the corner.
  const parent = button.offsetParent;
  const hasLayout = parent && parent.clientWidth > 60 && parent.clientHeight > 60;
  const maxLeft = hasLayout ? Math.max(0, parent.clientWidth - button.offsetWidth) : Infinity;
  const maxTop = hasLayout ? Math.max(0, parent.clientHeight - button.offsetHeight) : Infinity;
  button.style.left = `${clamp(pos.left, 0, maxLeft)}px`;
  button.style.top = `${clamp(pos.top, 0, maxTop)}px`;
  button.style.right = "auto";
  button.style.bottom = "auto";
}

function destroyNarrativeCanvas() {
  eventController?.abort();
  eventController = null;
  closeVisionBoardLayerMenu();
  state.rootResizeObserver?.disconnect?.();
  state.rootResizeObserver = null;
  if (state.rootResizeTimer) {
    window.clearTimeout(state.rootResizeTimer);
    state.rootResizeTimer = null;
  }
  if (state.canvasViewportRenderFrame) {
    window.cancelAnimationFrame(state.canvasViewportRenderFrame);
    state.canvasViewportRenderFrame = null;
  }
  if (state.playRefreshTimer) {
    window.clearTimeout(state.playRefreshTimer);
    state.playRefreshTimer = null;
  }
  clearPlayChoiceTimer();
  clearAutoSaveTimer();
  clearStatusTimer();
  clearStoryPanelRenderTimer();
  clearDocumentApplyTimer();
  state.sidebar.resizing = null;
  state.immersiveFullscreen = false;
  closeFloatingInspector({ restoreFocus: false });
  state.frameCanvasId = "";
  state.frameCanvasReturnView = null;
  dom.root?.classList.remove("sidebar-resizing");
  dom.root?.removeAttribute("data-sidebar-resizing");
  dom.root?.removeAttribute("data-immersive");
  dom.root?.removeAttribute("data-frame-canvas");
  hideNodeContextMenu();
  initialized = false;
  resetRuntimeState();
  resetDomRefs();
  if (window.NarrativeCanvasApp?.destroy === destroyNarrativeCanvas) {
    delete window.NarrativeCanvasApp;
  }
}

function setLanguage(language, options = {}) {
  const nextLanguage = normalizeUiLanguage(language);
  if (state.language === nextLanguage && !options.force) return true;
  state.language = nextLanguage;
  if (!window.NarrativeCanvasHost && options.persist !== false) {
    try {
      getWebProjectStorage()?.setItem(WEB_LANGUAGE_STORAGE_KEY, nextLanguage);
    } catch (error) {
      // Browser storage can be unavailable in restrictive embeds.
    }
  }
  // Surfaces cache rendered output by version; bump both so open and inactive
  // panels re-render their baked-in UI strings in the new language.
  invalidateCanvasSurface();
  invalidateDocumentSurfaces();
  invalidateCharacterRenderContext();
  if (initialized) renderAll();
  return true;
}

function resetRuntimeState() {
  const nextState = createInitialRuntimeState();
  Object.keys(state).forEach((key) => delete state[key]);
  Object.assign(state, nextState);
}

function resetDomRefs() {
  Object.keys(dom).forEach((key) => delete dom[key]);
}

// The back-to-top button only appears after real scrolling, so it never sits on top
// of interactive rows while the reader is at the top of a document page. Any scroller
// inside a document-style panel counts (the document editor scrolls an inner element).
function handleWorkspacePanelScroll(event) {
  const scroller = event.target;
  if (!(scroller instanceof Element) || !scroller.closest?.(".document-panel")) return;
  if (scroller.closest("[data-vault-file-suggestions], .cast-entry-suggestions")) return;
  dom.root?.classList.toggle("workspace-scrolled", scroller.scrollTop > 240);
}

function handleWindowResize() {
  hideNodeContextMenu();
  renderSidebarState();
  constrainFloatingWindow("play");
  constrainFloatingWindow("inspector");
  constrainFloatingWindow("ai");
  applyAiButtonPosition();
  scheduleCanvasViewportRender();
  if (state.activeFileId === "characters") scheduleCharacterMasonryLayout();
}

function getFloatingWindowElement(kind) {
  if (kind === "play") return dom.playDialog;
  if (kind === "inspector") return dom.inspectorFloatOverlay?.querySelector(".inspector-float-window") || null;
  if (kind === "ai") return dom.aiFloatingWindow;
  return null;
}

function isFloatingWindowActive(kind) {
  if (kind === "play") return Boolean(state.playFloating && dom.root?.hasAttribute("data-play-panel"));
  if (kind === "inspector") return Boolean(state.floatingInspectorPanel && !dom.inspectorFloatOverlay?.hidden);
  return kind === "ai" && Boolean(state.aiOpen && !dom.aiFloatingWindow?.hidden);
}

function isFloatingWindowPinned(kind) {
  return Boolean(state.floatingWindowPinned?.[kind]);
}

function renderFloatingWindowPinState(kind) {
  const pinned = isFloatingWindowPinned(kind);
  const label = t(pinned ? "Unpin window" : "Pin window");
  const button = dom.scope?.querySelector?.(`[data-floating-window-pin="${kind}"]`);
  const surface = kind === "inspector" ? dom.inspectorFloatOverlay : getFloatingWindowElement(kind);
  if (surface) surface.dataset.pinned = String(pinned);
  if (!button) return;
  button.setAttribute("aria-pressed", String(pinned));
  button.setAttribute("aria-label", label);
  button.setAttribute("title", label);
}

function renderFloatingWindowPinStates() {
  ["inspector", "play", "ai"].forEach(renderFloatingWindowPinState);
}

function setFloatingWindowPinned(kind, pinned) {
  if (!["inspector", "play", "ai"].includes(kind)) return;
  if (!state.floatingWindowPinned || typeof state.floatingWindowPinned !== "object") {
    state.floatingWindowPinned = { play: false, inspector: false, ai: false };
  }
  state.floatingWindowPinned[kind] = Boolean(pinned);
  renderFloatingWindowPinState(kind);
}

function toggleFloatingWindowPin(kind) {
  if (kind === "play" && !state.playFloating) {
    // Docked preview: float and pin in one action.
    if (!dom.root?.hasAttribute("data-play-panel")) return;
    state.playFloating = true;
    setFloatingWindowPinned("play", true);
    applyPlayFloatState();
    return;
  }
  if (!isFloatingWindowActive(kind)) return;
  setFloatingWindowPinned(kind, !isFloatingWindowPinned(kind));
}

function dockFloatingWindow(kind) {
  if (kind === "inspector") {
    closeFloatingInspector({ restoreFocus: false });
    return;
  }
  if (kind === "play") {
    state.playFloating = false;
    setFloatingWindowPinned("play", false);
    applyPlayFloatState();
    return;
  }
  if (kind === "ai") toggleAiWindow(false);
}

function handleFloatingWindowOutsideClick(event) {
  const target = getComposedEventTarget(event);
  if (!(target instanceof Element)) return;
  const clickGuard = state.floatingWindowClickGuard;
  if (clickGuard && Date.now() <= clickGuard.until && event.detail > 0) {
    const distance = Math.hypot(event.clientX - clickGuard.x, event.clientY - clickGuard.y);
    if (distance <= 4) {
      state.floatingWindowClickGuard = null;
      return;
    }
  }
  state.floatingWindowClickGuard = null;
  const path = typeof event.composedPath === "function" ? event.composedPath() : [];
  const eventIsInside = (element) => Boolean(element && (
    path.includes(element)
    || element.contains(target)
  ));
  const inside = {
    inspector: eventIsInside(getFloatingWindowElement("inspector")),
    play: eventIsInside(getFloatingWindowElement("play")),
    ai: eventIsInside(getFloatingWindowElement("ai"))
  };
  const inspectorLauncher = target.closest("[data-action='float-inspector-panel']");
  const aiLauncher = target.closest("#aiFloatingButton");
  ["inspector", "play", "ai"].forEach((kind) => {
    if (!isFloatingWindowActive(kind) || isFloatingWindowPinned(kind) || inside[kind]) return;
    if (kind === "inspector" && inspectorLauncher) return;
    if (kind === "ai" && aiLauncher) return;
    dockFloatingWindow(kind);
  });
}

function getFloatingWindowBounds(kind) {
  if (kind === "inspector") {
    const rect = dom.inspectorFloatOverlay?.getBoundingClientRect();
    if (rect) return { left: rect.left, top: rect.top, width: rect.width, height: rect.height };
  }
  if (kind === "ai") {
    // The AI surface belongs to .app-shell so it can cross the canvas, sidebars,
    // and document panels while remaining inside the NarrativeCanvas view.
    const containingBlock = dom.root;
    if (containingBlock?.getBoundingClientRect) {
      const rect = containingBlock.getBoundingClientRect();
      return {
        left: rect.left + containingBlock.clientLeft,
        top: rect.top + containingBlock.clientTop,
        width: containingBlock.clientWidth,
        height: containingBlock.clientHeight
      };
    }
  }
  return { left: 0, top: 0, width: window.innerWidth, height: window.innerHeight };
}

function readFloatingWindowGeometry(kind) {
  const element = getFloatingWindowElement(kind);
  if (!element) return null;
  const rect = element.getBoundingClientRect();
  const bounds = getFloatingWindowBounds(kind);
  return {
    x: rect.left - bounds.left,
    y: rect.top - bounds.top,
    width: rect.width,
    height: rect.height
  };
}

function clampFloatingWindowGeometry(kind, geometry) {
  const bounds = getFloatingWindowBounds(kind);
  const minWidth = Math.min(360, bounds.width);
  const minHeight = Math.min(280, bounds.height);
  const width = Math.min(Math.max(minWidth, geometry.width), bounds.width);
  const height = Math.min(Math.max(minHeight, geometry.height), bounds.height);
  return {
    x: Math.min(Math.max(0, geometry.x), Math.max(0, bounds.width - width)),
    y: Math.min(Math.max(0, geometry.y), Math.max(0, bounds.height - height)),
    width,
    height
  };
}

function applyFloatingWindowGeometry(kind) {
  if (!isFloatingWindowActive(kind)) return;
  const element = getFloatingWindowElement(kind);
  const geometry = state.floatingWindowGeometry?.[kind];
  if (!element || !geometry) return;
  const next = clampFloatingWindowGeometry(kind, geometry);
  state.floatingWindowGeometry[kind] = next;
  element.style.left = `${next.x}px`;
  element.style.top = `${next.y}px`;
  element.style.width = `${next.width}px`;
  element.style.height = `${next.height}px`;
  element.style.transform = "none";
}

function clearFloatingWindowStyles(kind) {
  const element = getFloatingWindowElement(kind);
  if (!element) return;
  ["left", "top", "width", "height", "transform"].forEach((name) => element.style.removeProperty(name));
}

function constrainFloatingWindow(kind) {
  if (!isFloatingWindowActive(kind) || !state.floatingWindowGeometry?.[kind]) return;
  applyFloatingWindowGeometry(kind);
}

function handleFloatingWindowPointerDown(event) {
  if (event.button !== 0) return;
  const resizeHandle = event.target?.closest?.("[data-floating-window-resize]");
  const dragHandle = event.target?.closest?.("[data-floating-window-drag]");
  const kind = resizeHandle?.dataset.floatingWindow || dragHandle?.dataset.floatingWindowDrag;
  if (!kind || !isFloatingWindowActive(kind)) return;
  if (!resizeHandle && event.target.closest("button, input, textarea, select, a")) return;
  const geometry = state.floatingWindowGeometry[kind] || readFloatingWindowGeometry(kind);
  if (!geometry) return;
  state.floatingWindowGeometry[kind] = geometry;
  applyFloatingWindowGeometry(kind);
  state.floatingWindowInteraction = {
    kind,
    direction: resizeHandle?.dataset.floatingWindowResize || "move",
    pointerId: event.pointerId,
    startX: event.clientX,
    startY: event.clientY,
    start: { ...state.floatingWindowGeometry[kind] },
    moved: false,
    captureTarget: event.target
  };
  try { event.target?.setPointerCapture?.(event.pointerId); } catch (_error) { /* Pointer capture is optional in embedded hosts. */ }
  getFloatingWindowElement(kind)?.classList.add("is-moving");
  event.preventDefault();
  event.stopPropagation();
}

function handleFloatingWindowPointerMove(event) {
  const interaction = state.floatingWindowInteraction;
  if (!interaction || interaction.pointerId !== event.pointerId) return;
  const dx = event.clientX - interaction.startX;
  const dy = event.clientY - interaction.startY;
  if (Math.hypot(dx, dy) >= 3) interaction.moved = true;
  const next = { ...interaction.start };
  const direction = interaction.direction;
  if (direction === "move") {
    next.x += dx;
    next.y += dy;
  } else {
    if (direction.includes("e")) next.width += dx;
    if (direction.includes("s")) next.height += dy;
    if (direction.includes("w")) {
      next.x += dx;
      next.width -= dx;
    }
    if (direction.includes("n")) {
      next.y += dy;
      next.height -= dy;
    }
  }
  state.floatingWindowGeometry[interaction.kind] = clampFloatingWindowGeometry(interaction.kind, next);
  applyFloatingWindowGeometry(interaction.kind);
  event.preventDefault();
}

function handleFloatingWindowPointerUp(event) {
  const interaction = state.floatingWindowInteraction;
  if (!interaction || interaction.pointerId !== event.pointerId) return;
  getFloatingWindowElement(interaction.kind)?.classList.remove("is-moving");
  try { interaction.captureTarget?.releasePointerCapture?.(event.pointerId); } catch (_error) { /* The browser may already have released capture. */ }
  if (interaction.moved && interaction.kind === "ai") {
    state.floatingWindowClickGuard = {
      x: event.clientX,
      y: event.clientY,
      until: Date.now() + 500
    };
  }
  state.floatingWindowInteraction = null;
}

function normalizeDialogSpeakerRatio(value) {
  const ratio = Number(value);
  return Number.isFinite(ratio) ? Math.min(68, Math.max(18, ratio)) : 34;
}

function handleDialogColumnResizePointerDown(event) {
  if (event.button !== 0) return;
  const handle = event.target?.closest?.("[data-dialog-column-resize][data-dialog-node-id]");
  if (!handle) return;
  const node = getNode(handle.dataset.dialogNodeId);
  const surface = handle.closest(".node-dialog-preview, .dialog-turns-editor");
  if (!node || !isDialogNode(node) || !surface) return;
  state.dialogColumnResize = {
    nodeId: node.id,
    pointerId: event.pointerId,
    startX: event.clientX,
    startRatio: normalizeDialogSpeakerRatio(node.dialogSpeakerRatio),
    previewWidth: Math.max(1, surface.getBoundingClientRect().width),
    historyBefore: getHistorySnapshot(),
    active: false
  };
  dom.root?.classList.add("dialog-column-resizing");
  safeSetPointerCapture(handle, event.pointerId);
  event.preventDefault();
  event.stopPropagation();
}

function handleDialogColumnResizePointerMove(event) {
  const drag = state.dialogColumnResize;
  if (!drag || drag.pointerId !== event.pointerId) return;
  const delta = event.clientX - drag.startX;
  if (Math.abs(delta) < 2 && !drag.active) return;
  drag.active = true;
  const ratio = normalizeDialogSpeakerRatio(drag.startRatio + delta / drag.previewWidth * 100);
  const node = getNode(drag.nodeId);
  if (!node) return;
  node.dialogSpeakerRatio = ratio;
  const element = getNodeElementById(node.id);
  element?.querySelector(".node-dialog-preview")?.style.setProperty("--dialog-speaker-ratio", `${ratio}%`);
  dom.nodePanel?.querySelector(".dialog-turns-editor")?.style.setProperty("--dialog-speaker-ratio", `${ratio}%`);
  event.preventDefault();
}

function handleDialogColumnResizePointerUp(event) {
  const drag = state.dialogColumnResize;
  if (!drag || drag.pointerId !== event.pointerId) return;
  state.dialogColumnResize = null;
  dom.root?.classList.remove("dialog-column-resizing");
  if (!drag.active) return;
  setProjectDirty(true);
  commitHistoryFromSnapshot(drag.historyBefore);
  updateStatus();
}

function handleFullscreenChange() {
  const active = Boolean(document.fullscreenElement || document.webkitFullscreenElement);
  if (active) {
    if (!state.immersiveFullscreen) {
      state.immersiveFullscreen = true;
      renderShellState();
      handleWindowResize();
    }
    return;
  }
  if (state.immersiveFullscreen) {
    state.immersiveFullscreen = false;
    renderShellState();
    handleWindowResize();
  }
}

function renderImmersiveFullscreenState() {
  const active = Boolean(state.immersiveFullscreen);
  if (active) dom.root?.setAttribute("data-immersive", "true");
  else dom.root?.removeAttribute("data-immersive");
  if (!dom.fullscreenButton) return;
  const label = t(active ? "Exit immersive fullscreen" : "Enter immersive fullscreen");
  dom.fullscreenButton.innerHTML = getImmersiveFullscreenIcon(active);
  dom.fullscreenButton.title = label;
  dom.fullscreenButton.setAttribute("aria-label", label);
  dom.fullscreenButton.setAttribute("aria-pressed", String(active));
}

function getImmersiveFullscreenIcon(active) {
  const path = active
    ? "M9 3v6H3M15 3v6h6M21 15h-6v6M3 15h6v6"
    : "M8 3H3v5M16 3h5v5M21 16v5h-5M3 16v5h5";
  return `<svg class="history-icon immersive-icon" viewBox="0 0 24 24" aria-hidden="true" focusable="false"><path d="${path}"></path></svg>`;
}

async function toggleImmersiveFullscreen() {
  const next = !state.immersiveFullscreen;
  state.immersiveFullscreen = next;
  renderShellState();
  handleWindowResize();
  if (next) {
    await requestNativeFullscreen(dom.root || document.documentElement);
    setStatus(t("Enter immersive fullscreen"));
    return;
  }
  await exitNativeFullscreen();
  setStatus(t("Exit immersive fullscreen"));
}

async function requestNativeFullscreen(element) {
  const request = element?.requestFullscreen || element?.webkitRequestFullscreen;
  if (!request) return false;
  try {
    await request.call(element);
    return true;
  } catch (error) {
    return false;
  }
}

async function exitNativeFullscreen() {
  const fullscreenElement = document.fullscreenElement || document.webkitFullscreenElement;
  if (!fullscreenElement) return false;
  const exit = document.exitFullscreen || document.webkitExitFullscreen;
  if (!exit) return false;
  try {
    await exit.call(document);
    return true;
  } catch (error) {
    return false;
  }
}

function getActiveFrameCanvas() {
  const node = getNode(state.frameCanvasId);
  return node && isFrameNode(node) ? node : null;
}

function isFrameCanvasActive() {
  return Boolean(getActiveFrameCanvas());
}

function clearInvalidFrameCanvas() {
  if (!state.frameCanvasId) return false;
  if (getActiveFrameCanvas()) return false;
  state.frameCanvasId = "";
  state.frameCanvasReturnView = null;
  return true;
}

function renderFrameCanvasScopeState() {
  clearInvalidFrameCanvas();
  const frame = getActiveFrameCanvas();
  const active = Boolean(frame && isCanvasFileActive());
  if (dom.root) {
    if (active) dom.root.setAttribute("data-frame-canvas", "true");
    else dom.root.removeAttribute("data-frame-canvas");
  }
  if (!dom.frameCanvasScope) return;
  dom.frameCanvasScope.hidden = !active;
  if (dom.frameCanvasTitle) {
    dom.frameCanvasTitle.textContent = active ? getNodeDisplayTitle(frame, t("Frame")) : "";
    dom.frameCanvasTitle.title = active ? getNodeDisplayTitle(frame, t("Frame")) : "";
  }
}

function enterFrameCanvas(frameId) {
  const frame = getNode(frameId);
  if (!frame || !isFrameNode(frame)) return;
  hideNodeContextMenu();
  state.frameCanvasReturnView = {
    view: { ...state.view },
    scrollLeft: dom.viewport?.scrollLeft || 0,
    scrollTop: dom.viewport?.scrollTop || 0
  };
  state.frameCanvasId = frame.id;
  state.activeFileId = "adventure";
  state.selectedNodeId = frame.id;
  state.selectedNodeIds = [];
  state.selectedLinkId = null;
  state.characterFocusId = null;
  state.connectingFrom = null;
  state.connectingTo = null;
  state.reconnectingLinkId = null;
  state.reconnectingEnd = null;
  invalidateCanvasSurface();
  renderAll();
  requestAnimationFrame(() => {
    centerView(false);
    setStatus(t("Frame canvas opened."));
  });
}

function exitFrameCanvas(options = {}) {
  if (!state.frameCanvasId) return;
  hideNodeContextMenu();
  if (expandFrameCanvasFramesToFit(state.frameCanvasId)) setProjectDirty(true);
  const previousView = state.frameCanvasReturnView;
  state.frameCanvasId = "";
  state.frameCanvasReturnView = null;
  state.connectingFrom = null;
  state.connectingTo = null;
  state.reconnectingLinkId = null;
  state.reconnectingEnd = null;
  invalidateCanvasSurface();
  if (previousView?.view) {
    state.view = normalizeView(previousView.view);
    if (dom.viewport) {
      dom.viewport.scrollLeft = Number(previousView.scrollLeft) || 0;
      dom.viewport.scrollTop = Number(previousView.scrollTop) || 0;
    }
  }
  if (options.render !== false) {
    renderAll();
    setStatus(t("Frame canvas closed."));
  }
}

function getFrameCanvasNodeIdSet(frameId = state.frameCanvasId) {
  const frame = getNode(frameId);
  if (!frame || !isFrameNode(frame)) return null;
  return new Set(getFrameDescendantNodes(frame.id).map((node) => node.id));
}

function isNodeWithinFrameCanvas(node, frameId = state.frameCanvasId) {
  if (!node || !frameId) return false;
  return node.id === frameId || isFrameDescendantOf(node, frameId);
}

function renderSidebarState() {
  if (!dom.root) return;
  updateCompactSidebarMode();
  const normalized = normalizeSidebarState(state.sidebar);
  state.sidebar.leftWidth = normalized.leftWidth;
  state.sidebar.rightWidth = normalized.rightWidth;
  state.sidebar.leftCollapsed = normalized.leftCollapsed;
  state.sidebar.rightCollapsed = normalized.rightCollapsed;

  dom.root.style.setProperty("--sidebar-left-width", `${normalized.leftWidth}px`);
  dom.root.style.setProperty("--sidebar-right-width", `${normalized.rightWidth}px`);
  dom.root.setAttribute("data-sidebar-left", normalized.leftCollapsed ? "collapsed" : "expanded");
  dom.root.setAttribute("data-sidebar-right", normalized.rightCollapsed ? "collapsed" : "expanded");

  dom.sidebarToggles?.forEach((button) => {
    const side = getValidSidebarSide(button.dataset.sidebarToggle);
    if (!side) return;
    const collapsed = side === "left" ? normalized.leftCollapsed : normalized.rightCollapsed;
    const labelKey = `${collapsed ? "Expand" : "Collapse"} ${side} sidebar`;
    const label = t(labelKey);
    button.title = label;
    button.setAttribute("aria-label", label);
    button.setAttribute("aria-expanded", String(!collapsed));
  });
}

function updateCompactSidebarMode() {
  const compact = (dom.root?.clientWidth || window.innerWidth || 0) <= 640;
  if (compact === Boolean(state.sidebar.compactMode)) return;
  if (compact) {
    state.sidebar.preCompactCollapsed = {
      left: Boolean(state.sidebar.leftCollapsed),
      right: Boolean(state.sidebar.rightCollapsed)
    };
    state.sidebar.leftCollapsed = true;
    state.sidebar.rightCollapsed = true;
  } else if (state.sidebar.preCompactCollapsed) {
    state.sidebar.leftCollapsed = Boolean(state.sidebar.preCompactCollapsed.left);
    state.sidebar.rightCollapsed = Boolean(state.sidebar.preCompactCollapsed.right);
    state.sidebar.preCompactCollapsed = null;
  }
  state.sidebar.compactMode = compact;
  dom.root?.toggleAttribute("data-compact-layout", compact);
}

function normalizeSidebarState(sidebar) {
  const source = sidebar && typeof sidebar === "object" ? sidebar : {};
  return {
    leftWidth: normalizeSidebarWidth("left", source.leftWidth),
    rightWidth: normalizeSidebarWidth("right", source.rightWidth),
    leftCollapsed: Boolean(source.leftCollapsed),
    rightCollapsed: Boolean(source.rightCollapsed)
  };
}

function normalizeSidebarWidth(side, width) {
  const config = SIDEBAR_CONFIG[side];
  const value = Number(width);
  const fallback = config.defaultWidth;
  return Math.round(clamp(Number.isFinite(value) ? value : fallback, config.minWidth, config.maxWidth));
}

function getValidSidebarSide(side) {
  return SIDEBAR_SIDES.has(side) ? side : "";
}

function getSidebarWidth(side) {
  const validSide = getValidSidebarSide(side);
  if (!validSide) return 0;
  return normalizeSidebarWidth(validSide, state.sidebar?.[`${validSide}Width`]);
}

function isSidebarCollapsed(side) {
  const validSide = getValidSidebarSide(side);
  return validSide ? Boolean(state.sidebar?.[`${validSide}Collapsed`]) : false;
}

function setSidebarWidth(side, width) {
  const validSide = getValidSidebarSide(side);
  if (!validSide) return;
  const config = SIDEBAR_CONFIG[validSide];
  const maxWidth = getSidebarResizeMaxWidth(validSide);
  state.sidebar[`${validSide}Width`] = Math.round(clamp(width, config.minWidth, maxWidth));
}

function getSidebarResizeMaxWidth(side) {
  const config = SIDEBAR_CONFIG[side];
  const shellWidth = dom.root?.clientWidth || 0;
  if (!shellWidth) return config.maxWidth;
  const oppositeSide = side === "left" ? "right" : "left";
  const oppositeWidth = isSidebarCollapsed(oppositeSide)
    ? SIDEBAR_COLLAPSED_WIDTH
    : getSidebarWidth(oppositeSide);
  const activeResizerWidth = SIDEBAR_RESIZER_WIDTH + (isSidebarCollapsed(oppositeSide) ? 0 : SIDEBAR_RESIZER_WIDTH);
  const availableWidth = shellWidth - oppositeWidth - activeResizerWidth - SIDEBAR_MIN_WORKSPACE_WIDTH;
  return Math.max(config.minWidth, Math.min(config.maxWidth, availableWidth));
}

function getSavedSidebarState() {
  const sidebar = normalizeSidebarState(state.sidebar);
  const compactRestore = state.sidebar.compactMode && state.sidebar.preCompactCollapsed
    ? state.sidebar.preCompactCollapsed
    : null;
  return {
    leftWidth: sidebar.leftWidth,
    rightWidth: sidebar.rightWidth,
    leftCollapsed: compactRestore ? Boolean(compactRestore.left) : sidebar.leftCollapsed,
    rightCollapsed: compactRestore ? Boolean(compactRestore.right) : sidebar.rightCollapsed
  };
}

function applySavedSidebarState(sidebar) {
  const normalized = normalizeSidebarState(sidebar);
  state.sidebar.leftWidth = normalized.leftWidth;
  state.sidebar.rightWidth = normalized.rightWidth;
  state.sidebar.leftCollapsed = normalized.leftCollapsed;
  state.sidebar.rightCollapsed = normalized.rightCollapsed;
  state.sidebar.resizing = null;
}

function toggleSidebar(side) {
  const validSide = getValidSidebarSide(side);
  if (!validSide) return;
  const collapsedKey = `${validSide}Collapsed`;
  state.sidebar[collapsedKey] = !state.sidebar[collapsedKey];
  if (state.sidebar.compactMode && !state.sidebar[collapsedKey]) {
    const oppositeSide = validSide === "left" ? "right" : "left";
    state.sidebar[`${oppositeSide}Collapsed`] = true;
  }
  renderSidebarState();
  handleWindowResize();
  setStatus(`${titleCase(validSide)} sidebar ${state.sidebar[collapsedKey] ? "collapsed" : "expanded"}.`);
}

function safeSetPointerCapture(element, pointerId) {
  try {
    element?.setPointerCapture?.(pointerId);
  } catch (error) {
    // Pointer capture can be unavailable in synthetic tests or after a pointer is already gone.
  }
}

function safeReleasePointerCapture(element, pointerId) {
  try {
    element?.releasePointerCapture?.(pointerId);
  } catch (error) {
    // Pointer capture is already gone.
  }
}

function handleSidebarPointerDown(event) {
  if (event.button !== 0) return;
  const resizer = event.target?.closest?.("[data-sidebar-resizer]");
  if (!resizer || !dom.root?.contains(resizer)) return;
  const side = getValidSidebarSide(resizer.dataset.sidebarResizer);
  if (!side || isSidebarCollapsed(side)) return;

  state.sidebar.resizing = {
    side,
    startX: event.clientX,
    startWidth: getSidebarWidth(side),
    pointerId: event.pointerId,
    resizer
  };
  dom.root.classList.add("sidebar-resizing");
  dom.root.setAttribute("data-sidebar-resizing", side);
  hideNodeContextMenu();
  safeSetPointerCapture(resizer, event.pointerId);
  event.preventDefault();
  event.stopPropagation();
}

function handleSidebarPointerMove(event) {
  const resizing = state.sidebar?.resizing;
  if (!resizing) return;
  const deltaX = event.clientX - resizing.startX;
  const nextWidth = resizing.side === "left"
    ? resizing.startWidth + deltaX
    : resizing.startWidth - deltaX;
  setSidebarWidth(resizing.side, nextWidth);
  renderSidebarState();
  handleWindowResize();
  event.preventDefault();
}

function handleSidebarPointerUp(event) {
  const resizing = state.sidebar?.resizing;
  if (!resizing) return;
  safeReleasePointerCapture(resizing.resizer, resizing.pointerId ?? event.pointerId);
  const side = resizing.side;
  state.sidebar.resizing = null;
  dom.root?.classList.remove("sidebar-resizing");
  dom.root?.removeAttribute("data-sidebar-resizing");
  renderSidebarState();
  handleWindowResize();
  setStatus(`${titleCase(side)} sidebar resized.`);
}

function cloneProject(project) {
  return JSON.parse(JSON.stringify(project));
}

function defaultVariables() {
  return {};
}

function normalizeWorkflowMode(value) {
  const text = String(value || "").trim();
  if (WORKFLOW_MODES.has(text)) return text;
  const normalized = text.toLowerCase().replace(/[\s_-]+/g, "");
  if (["textsource", "storysource", "storymd", "storymarkdown", "markdown"].includes(normalized)) return WORKFLOW_MODE_TEXT_SOURCE;
  return WORKFLOW_MODE_CANVAS;
}

function normalizeProjectCharacters(project) {
  return Array.isArray(project.characters)
    ? normalizeCharacters(project.characters)
    : inferCharacters(project);
}

function getHistorySnapshot() {
  return JSON.stringify({
    project: state.project,
    selectedNodeId: state.selectedNodeId,
    selectedNodeIds: state.selectedNodeIds || [],
    selectedLinkId: state.selectedLinkId,
    panel: state.panel,
    activeFileId: state.activeFileId,
    view: state.view,
    characterFocusId: state.characterFocusId,
    characterSearch: state.characterSearch,
    codexKindFilter: state.codexKindFilter,
    codexTagFilter: state.codexTagFilter,
    eventSearch: state.eventSearch,
    playbookSearch: state.playbookSearch,
    playbookJsonOpen: state.playbookJsonOpen,
    search: state.search
  });
}

function resetHistory() {
  state.history = {
    undo: [],
    redo: [],
    current: getHistorySnapshot(),
    pending: null,
    applying: false
  };
  state.editHistoryTarget = null;
  renderHistoryButtons();
}

function commitHistoryCapture() {
  if (!state.history?.pending) return false;
  const before = state.history.pending;
  state.history.pending = null;
  return commitHistoryFromSnapshot(before);
}

function commitHistoryFromSnapshot(before) {
  if (state.history?.applying || !before) return false;
  const after = getHistorySnapshot();
  if (after === before) {
    state.history.current = after;
    renderHistoryButtons();
    return false;
  }
  state.history.undo.push(before);
  if (state.history.undo.length > HISTORY_LIMIT) state.history.undo.shift();
  state.history.redo = [];
  state.history.current = after;
  setProjectDirty(true);
  renderHistoryButtons();
  return true;
}

function captureNodeGeometry(node) {
  return {
    id: node.id,
    x: node.x,
    y: node.y,
    width: node.width,
    height: node.height,
    hasWidth: Object.prototype.hasOwnProperty.call(node, "width"),
    hasHeight: Object.prototype.hasOwnProperty.call(node, "height"),
    frameId: normalizeOptionalString(node.frameId).trim(),
    hasFrameId: Object.prototype.hasOwnProperty.call(node, "frameId")
  };
}

function beginGeometryHistoryCapture(node) {
  if (!node || state.history?.applying) return null;
  const nodes = Array.isArray(node) ? node.filter(Boolean) : [node];
  state.geometryHistoryTarget = {
    before: nodes.map(captureNodeGeometry)
  };
  return state.geometryHistoryTarget;
}

function commitGeometryHistoryCapture() {
  const target = state.geometryHistoryTarget;
  state.geometryHistoryTarget = null;
  if (!target?.before?.length) return false;
  const after = target.before
    .map((entry) => getNode(entry.id))
    .filter(Boolean)
    .map(captureNodeGeometry);
  if (!after.length || sameGeometrySnapshots(target.before, after)) return false;
  return pushGeometryHistoryEntry({ kind: "geometry", before: target.before, after });
}

function sameGeometrySnapshots(before, after) {
  if (!Array.isArray(before) || !Array.isArray(after) || before.length !== after.length) return false;
  return before.every((entry, index) => {
    const next = after[index];
    return next
      && entry.id === next.id
      && entry.x === next.x
      && entry.y === next.y
      && entry.width === next.width
      && entry.height === next.height
      && entry.hasWidth === next.hasWidth
      && entry.hasHeight === next.hasHeight
      && entry.frameId === next.frameId
      && entry.hasFrameId === next.hasFrameId;
  });
}

function pushGeometryHistoryEntry(entry) {
  if (state.history?.applying) return false;
  if (!state.history) resetHistory();
  state.history.undo.push(entry);
  if (state.history.undo.length > HISTORY_LIMIT) state.history.undo.shift();
  state.history.redo = [];
  state.history.pending = null;
  state.history.current = "";
  setProjectDirty(true);
  renderHistoryButtons();
  return true;
}

function isGeometryHistoryEntry(entry) {
  return Boolean(entry && typeof entry === "object" && entry.kind === "geometry");
}

function applyGeometryHistoryEntry(entry, side, label) {
  const snapshots = Array.isArray(entry?.[side]) ? entry[side] : [];
  state.history.applying = true;
  snapshots.forEach(applyNodeGeometry);
  state.history.applying = false;
  state.history.current = "";
  setProjectDirty(true);
  markProjectStructureChanged();
  renderAll();
  renderHistoryButtons();
  setStatus(`${label} applied.`);
}

function applyNodeGeometry(snapshot) {
  const node = getNode(snapshot.id);
  if (!node) return;
  node.x = snapshot.x;
  node.y = snapshot.y;
  if (snapshot.hasWidth) node.width = snapshot.width;
  else delete node.width;
  if (snapshot.hasHeight) node.height = snapshot.height;
  else delete node.height;
  if (snapshot.hasFrameId) node.frameId = normalizeOptionalString(snapshot.frameId).trim();
  else delete node.frameId;
}

function undoHistory() {
  commitHistoryCapture();
  const history = state.history;
  if (!history?.undo?.length) return;
  const previous = history.undo.pop();
  if (isGeometryHistoryEntry(previous)) {
    history.redo.push(previous);
    applyGeometryHistoryEntry(previous, "before", "Undo");
    return;
  }
  const current = getHistorySnapshot();
  history.redo.push(current);
  if (history.redo.length > HISTORY_LIMIT) history.redo.shift();
  restoreHistorySnapshot(previous, "Undo");
}

function redoHistory() {
  const history = state.history;
  if (!history?.redo?.length) return;
  const next = history.redo.pop();
  if (isGeometryHistoryEntry(next)) {
    history.undo.push(next);
    applyGeometryHistoryEntry(next, "after", "Redo");
    return;
  }
  const current = getHistorySnapshot();
  history.undo.push(current);
  if (history.undo.length > HISTORY_LIMIT) history.undo.shift();
  restoreHistorySnapshot(next, "Redo");
}

function restoreHistorySnapshot(snapshot, label) {
  if (!snapshot) return;
  let payload;
  try {
    payload = JSON.parse(snapshot);
  } catch (error) {
    console.error(error);
    setStatus(`${label} failed.`);
    return;
  }
  state.history.applying = true;
  state.project = normalizeProject(payload.project || {});
  markProjectStructureChanged({ nodeTypes: true });
  state.selectedNodeId = getValidSavedNodeId(payload.selectedNodeId);
  state.selectedNodeIds = Array.isArray(payload.selectedNodeIds)
    ? payload.selectedNodeIds.filter((id) => getNode(id))
    : [];
  state.selectedLinkId = getValidSavedLinkId(payload.selectedLinkId);
  state.panel = getValidSavedPanel(payload.panel, state.selectedNodeId);
  state.activeFileId = fileViews[payload.activeFileId] ? payload.activeFileId : "adventure";
  state.view = normalizeView(payload.view);
  state.characterFocusId = payload.characterFocusId && getCharacterById(payload.characterFocusId) ? payload.characterFocusId : null;
  state.characterSearch = typeof payload.characterSearch === "string" ? payload.characterSearch : "";
  state.codexKindFilter = normalizeCodexKindFilter(payload.codexKindFilter);
  state.codexTagFilter = normalizeOptionalString(payload.codexTagFilter).trim();
  state.eventSearch = typeof payload.eventSearch === "string" ? payload.eventSearch : "";
  state.playbookSearch = typeof payload.playbookSearch === "string" ? payload.playbookSearch : "";
  state.playbookJsonOpen = Boolean(payload.playbookJsonOpen);
  state.search = typeof payload.search === "string" ? payload.search : "";
  state.searchIndex = -1;
  state.characterSearchIndex = -1;
  state.eventSearchIndex = -1;
  state.playbookSearchIndex = -1;
  state.connectingFrom = null;
  state.reconnectingLinkId = null;
  state.reconnectingEnd = null;
  state.history.current = snapshot;
  state.history.pending = null;
  state.history.applying = false;
  setProjectDirty(true);
  renderAll();
  setStatus(`${label} applied.`);
}

function renderHistoryButtons() {
  if (!dom.undoButton || !dom.redoButton || !state.history) return;
  dom.undoButton.disabled = !state.history.undo.length;
  dom.redoButton.disabled = !state.history.redo.length;
}

