function renderAll() {
  hideNodeContextMenu();
  renderShellState();
  renderPalette();
  if (isCanvasFileActive()) {
    renderCanvasSurface({ force: true });
  }
  renderWorkspaceFile();
  renderInspector();
  updateStatus();
  renderHistoryButtons();
}

function isCanvasFileActive() {
  return state.activeFileId === "adventure";
}

function renderCanvasSurface(options = {}) {
  if (!dom.canvasPanel || !dom.nodeLayer || !dom.linkLayer) return;
  const shouldRender = options.force
    || state.canvasRenderedVersion !== state.canvasRenderVersion
    || (!dom.nodeLayer.childElementCount && !dom.frameLayer?.childElementCount);
  renderTransform();
  if (shouldRender) {
    const canvasRenderContext = options.renderContext || getCanvasRenderContext();
    renderNodes(canvasRenderContext);
    renderLinks(canvasRenderContext);
    markCanvasSurfaceRendered();
  }
  renderMinimap();
}

function invalidateCanvasSurface() {
  state.canvasRenderVersion += 1;
}

function markCanvasSurfaceRendered() {
  state.canvasRenderedVersion = state.canvasRenderVersion;
}

function markCanvasSurfaceRenderedIfActive() {
  if (isCanvasFileActive()) markCanvasSurfaceRendered();
}

function invalidateDocumentSurfaces(fileId = null) {
  state.documentRenderVersion += 1;
  if (fileId && state.documentRenderedVersions) {
    state.documentRenderedVersions[fileId] = 0;
  }
}

function renderPlaybookSurfaces(options = {}) {
  hideNodeContextMenu();
  renderShellState();
  if (state.activeFileId === "variables") {
    renderVariablesPage(options);
    markDocumentSurfaceRendered("variables");
  } else {
    renderWorkspaceFile();
  }
  renderProjectPanel();
  renderStoryPanel();
  updateStatus();
}

// Spell check is off by default so writers don't get red underlines on names, Ink/
// Yarn syntax, or variable keys. Setting `spellcheck` on the app-shell cascades to
// every descendant field that doesn't override it. The plugin exposes a toggle.
function isSpellCheckEnabled() {
  const host = window.NarrativeCanvasHost;
  if (host?.getSpellCheck) return Boolean(host.getSpellCheck());
  try {
    return getWebProjectStorage()?.getItem("narrative-canvas-spellcheck-v1") === "1";
  } catch (_error) {
    return false;
  }
}

function applySpellCheckSetting() {
  const shell = dom.root?.classList?.contains("app-shell") ? dom.root : dom.root?.querySelector?.(".app-shell");
  shell?.setAttribute("spellcheck", isSpellCheckEnabled() ? "true" : "false");
}

function isAiNarrativeKnowledgeEnabled() {
  const host = window.NarrativeCanvasHost;
  if (host?.getAiNarrativeKnowledge) return Boolean(host.getAiNarrativeKnowledge());
  try {
    return getWebProjectStorage()?.getItem("narrative-canvas-ai-knowledge-v1") === "1";
  } catch (_error) {
    return false;
  }
}

function renderShellState() {
  dom.root?.setAttribute("data-theme", state.theme);
  dom.root?.setAttribute("lang", state.language === "zh" ? "zh-CN" : "en");
  applySpellCheckSetting();
  dom.themeHost?.setAttribute("data-theme", state.theme);
  dom.themeHost?.setAttribute("lang", state.language === "zh" ? "zh-CN" : "en");
  localizeStaticShell();
  renderFloatingWindowPinStates();
  renderImmersiveFullscreenState();
  renderSidebarState();
  if (dom.themeToggle) {
    const isDark = state.theme === "dark";
    dom.themeToggle.textContent = isDark ? t("Dark") : t("Light");
    dom.themeToggle.setAttribute("aria-pressed", String(isDark));
    dom.themeToggle.title = isDark ? t("Switch to light theme") : t("Switch to dark theme");
  }
  if (dom.languageToggle) {
    const nextLanguageLabel = state.language === "zh" ? t("Switch to English") : t("Switch to Chinese");
    dom.languageToggle.dataset.activeLang = state.language;
    dom.languageToggle.title = nextLanguageLabel;
    dom.languageToggle.setAttribute("aria-label", nextLanguageLabel);
  }
  if (dom.exportImageScale) {
    dom.exportImageScale.value = getExportImageScalePreset().value;
  }
  if (dom.snapGridButton) {
    dom.snapGridButton.classList.toggle("active", state.snapToGrid);
    dom.snapGridButton.setAttribute("aria-pressed", String(state.snapToGrid));
  }
  if (dom.vaultProjectTitle) {
    dom.vaultProjectTitle.textContent = state.project.title || t("Untitled Story");
  }
  renderProjectFileStatus();
  dom.root?.setAttribute("data-active-file", state.activeFileId || "adventure");
  syncWorkspaceSearchControls();

  dom.scope.querySelectorAll(".nc-file-item[data-file-id]").forEach((button) => {
    const isActive = button.dataset.fileId === state.activeFileId;
    button.classList.toggle("active", isActive);
    button.setAttribute("aria-pressed", String(isActive));
    const label = button.querySelector(".nc-file-item-label");
    if (label) label.textContent = getFileViewLabel(button.dataset.fileId);
  });

  if (dom.activeFileTab) {
  dom.activeFileTab.textContent = getFileViewLabel(state.activeFileId);
  }

  dom.workspaceToolbar.hidden = state.activeFileId !== "adventure";
  dom.fileScopedActions = [...dom.scope.querySelectorAll("[data-files]")];

  dom.fileScopedActions.forEach((button) => {
    const files = String(button.dataset.files || "").split(/\s+/);
    button.hidden = !files.includes(state.activeFileId);
  });
  dom.webOnlyActions.forEach((element) => {
    element.hidden = Boolean(window.NarrativeCanvasHost);
  });
  renderFrameCanvasScopeState();
  renderHistoryButtons();
}

function localizeText(selector, key, root = dom.scope) {
  const element = root?.querySelector?.(selector);
  if (element) element.textContent = t(key);
}

function localizeAllText(selector, key, root = dom.scope) {
  root?.querySelectorAll?.(selector).forEach((element) => {
    element.textContent = t(key);
  });
}

function localizeAttr(selector, attr, key, root = dom.scope) {
  const element = root?.querySelector?.(selector);
  if (element) element.setAttribute(attr, t(key));
}

function localizeLabelText(selector, key, root = dom.scope) {
  const element = root?.querySelector?.(selector);
  if (!element) return;
  const textNodeType = window.Node?.TEXT_NODE || 3;
  const textNode = [...element.childNodes].find((node) => node.nodeType === textNodeType && node.nodeValue.trim());
  if (textNode) {
    textNode.nodeValue = `${t(key)} `;
  } else {
    element.prepend(document.createTextNode(`${t(key)} `));
  }
}

function localizeSelectOptions(selector, labels, root = dom.scope) {
  const select = root?.querySelector?.(selector);
  if (!select) return;
  [...select.options].forEach((option) => {
    option.textContent = t(labels[option.value] || option.textContent);
  });
}

