function renderPlaybookHelpDialog() {
  const dialog = dom.scope?.querySelector("#playbookHelpDialog");
  if (!dialog) return;
  const pages = getPlaybookHelpPages();
  const maxPage = Math.max(0, pages.length - 1);
  state.playbookHelpPage = Math.min(Math.max(Number(state.playbookHelpPage) || 0, 0), maxPage);
  const page = pages[state.playbookHelpPage] || pages[0];
  const body = dialog.querySelector("[data-playbook-help-body]");
  dialog.querySelector(".pane-kicker").textContent = t("Playbook");
  dialog.querySelector("h2").textContent = t(page.title);
  if (body) {
    body.innerHTML = `
      <article class="playbook-help-page">
        ${page.lead ? `<p class="playbook-help-lead">${escapeHtml(t(page.lead))}</p>` : ""}
        ${page.sections.map(renderPlaybookHelpSection).join("")}
        ${page.code ? `<pre class="playbook-example"><code>${escapeHtml(page.code)}</code></pre>` : ""}
      </article>
    `;
  }
  const current = state.playbookHelpPage + 1;
  const total = pages.length;
  const pageLabel = dialog.querySelector("[data-playbook-help-page-label]");
  if (pageLabel) pageLabel.textContent = t("Page {current} of {total}", { current, total });
  const prevButton = dialog.querySelector("[data-action='playbook-help-prev']");
  const nextButton = dialog.querySelector("[data-action='playbook-help-next']");
  if (prevButton) {
    prevButton.textContent = t("Previous tip");
    prevButton.disabled = state.playbookHelpPage <= 0;
  }
  if (nextButton) {
    nextButton.textContent = t("Next tip");
    nextButton.disabled = state.playbookHelpPage >= maxPage;
  }
  const closeButton = dialog.querySelector("[value='confirm']");
  if (closeButton) closeButton.textContent = t("Close");
  const dots = dialog.querySelector("[data-playbook-help-dots]");
  if (dots) {
    dots.innerHTML = pages.map((item, index) => `
      <button type="button" class="playbook-help-dot${index === state.playbookHelpPage ? " active" : ""}" data-action="playbook-help-page" data-playbook-help-page="${index}" aria-label="${escapeAttr(t("Page {current} of {total}", { current: index + 1, total }))}" aria-current="${index === state.playbookHelpPage ? "page" : "false"}"></button>
    `).join("");
  }
}

function renderPlaybookHelpSection(section) {
  return `
    <section class="playbook-help-section">
      <h3>${escapeHtml(t(section.heading))}</h3>
      <ul>
        ${(section.items || []).map((item) => `<li>${escapeHtml(t(item))}</li>`).join("")}
      </ul>
    </section>
  `;
}

function localizePlayRuleDialog() {
  const dialog = dom.playRuleDialog;
  if (!dialog) return;
  dialog.setAttribute("aria-label", t("Add preview rule"));
  dialog.querySelector(".pane-kicker").textContent = t("Playbook");
  dialog.querySelector("h2").textContent = t("Add preview rule");
  const labels = {
    startNode: ["Start Node", "Choose the exact node title where Play preview starts. This does not change canvas links or layout."],
    endCondition: ["End Condition", "End Play preview when this condition becomes true. Route checks such as route == ending work well here."],
    visitTracking: ["Visit Tracking", "Record visited nodes while Debug Mode is enabled. The list is discarded when Play preview closes."],
    debugMode: ["Debug Mode", "Show state values and condition results in Play preview, so it is easier to see why a choice appears or disappears."]
  };
  dialog.querySelectorAll("[data-playbook-rule-kind]").forEach((button) => {
    const [title, body] = labels[button.dataset.playbookRuleKind] || [];
    if (!title) return;
    button.querySelector("strong").textContent = t(title);
    button.querySelector("span").textContent = t(body);
  });
  const allSet = dialog.querySelector("[data-playbook-rule-allset]");
  if (allSet) allSet.textContent = t("All preview rules already enabled.");
  const cancel = dialog.querySelector(".confirm-cancel");
  if (cancel) cancel.textContent = t("Cancel");
}

function syncWorkspaceSearchControls() {
  const activeFile = state.activeFileId || "adventure";
  if (dom.queryInput && dom.queryInput.value !== state.search) dom.queryInput.value = state.search;
  if (dom.characterSearchInput && dom.characterSearchInput.value !== state.characterSearch) {
    dom.characterSearchInput.value = state.characterSearch || "";
  }
  if (dom.eventSearchInput && dom.eventSearchInput.value !== state.eventSearch) {
    dom.eventSearchInput.value = state.eventSearch || "";
  }
  if (dom.playbookSearchInput && dom.playbookSearchInput.value !== state.playbookSearch) {
    dom.playbookSearchInput.value = state.playbookSearch || "";
  }

  if (dom.documentSearchInput && dom.documentSearchInput.value !== state.documentSearch) {
    dom.documentSearchInput.value = state.documentSearch || "";
  }

  const hasSearch = activeFile === "adventure" || activeFile === "characters" || activeFile === "events" || activeFile === "variables" || activeFile === "document";
  if (dom.workspaceSearchControls) dom.workspaceSearchControls.hidden = !hasSearch;
  dom.scope.querySelectorAll("[data-search-scope]").forEach((element) => {
    element.hidden = element.dataset.searchScope !== activeFile;
  });
  refreshWorkspaceSearchCount();
}

function renderProjectFileStatus() {
  if (!dom.projectFileName || !dom.projectFilePath || !dom.projectDirtyIndicator) return;
  const path = getCurrentProjectFilePath();
  const host = window.NarrativeCanvasHost;
  const isVaultProject = Boolean(host?.loadProject || host?.saveProject || host?.ensureProjectFile);
  state.projectFilePath = path;

  if (path) {
    dom.projectFileName.textContent = getProjectFileBasename(path);
    dom.projectFilePath.textContent = path;
  } else if (isVaultProject) {
    dom.projectFileName.textContent = t("No .ncanvas selected");
    dom.projectFilePath.textContent = t("Save or create a project file in the vault.");
  } else {
    dom.projectFileName.textContent = t("Browser storage");
    dom.projectFilePath.textContent = t("Saved in this browser");
  }

  const saveState = getProjectSaveState();
  const saveLabel = getProjectSaveLabel(saveState);
  dom.projectDirtyIndicator.hidden = false;
  dom.projectDirtyIndicator.dataset.saveState = saveState;
  dom.projectDirtyIndicator.setAttribute("aria-label", saveLabel);
  const label = dom.projectDirtyIndicator.querySelector("[data-save-label]");
  if (label) label.textContent = saveLabel;
  else dom.projectDirtyIndicator.textContent = saveLabel;
}

function getProjectSaveState() {
  if (state.isSaving) return "saving";
  if (state.saveError) return "error";
  return state.hasUnsavedChanges ? "unsaved" : "saved";
}

function getProjectSaveLabel(saveState) {
  if (saveState === "saving") return t("Saving");
  if (saveState === "unsaved") return t("Unsaved");
  if (saveState === "error") return t("Save failed");
  return t("Saved");
}

function getCurrentProjectFilePath() {
  const host = window.NarrativeCanvasHost;
  try {
    const path = host?.getProjectFile?.() || host?.projectFile || "";
    return typeof path === "string" ? path : state.projectFilePath || "";
  } catch (error) {
    console.error(error);
    return state.projectFilePath || "";
  }
}

function getProjectFileBasename(path) {
  const parts = String(path || "").split(/[\\/]/).filter(Boolean);
  return parts[parts.length - 1] || "Project file";
}

function setProjectDirty(value) {
  const nextValue = Boolean(value);
  if (nextValue) {
    invalidateCanvasSurface();
    invalidateDocumentSurfaces();
    state.dirtyVersion += 1;
    state.hasUnsavedChanges = true;
    state.saveError = false;
    renderProjectFileStatus();
    scheduleAutoSave();
    scheduleOpenPreviewRefresh();
    return;
  }

  if (state.hasUnsavedChanges === nextValue && !state.saveError) {
    renderProjectFileStatus();
    return;
  }
  clearAutoSaveTimer();
  state.hasUnsavedChanges = nextValue;
  state.saveError = false;
  renderProjectFileStatus();
}

function markProjectStructureChanged(options = {}) {
  state.structureVersion += 1;
  invalidateCanvasSurface();
  invalidateDocumentSurfaces();
  invalidateCharacterRenderContext();
  if (!state.derived) return;
  state.derived.flowOrder = null;
  state.derived.displayId = null;
  state.derived.frameChildFlowOrder = null;
  state.derived.frameDescendantNodes = null;
  state.derived.nodeSearchText = null;
  state.derived.eventSearchText = null;
  state.derived.characterMentionContext = null;
  state.derived.choiceFollowupLabels = null;
  if (options.nodeTypes) {
    state.derived.nodeTypeMap = null;
    state.derived.projectNodeTypes = null;
  }
}

function configureAutoSave() {
  if (state.hasUnsavedChanges) scheduleAutoSave();
  else clearAutoSaveTimer();
  renderProjectFileStatus();
}

function scheduleAutoSave() {
  clearAutoSaveTimer();
  if (!initialized || !state.hasUnsavedChanges || state.isSaving || state.externalProjectChangePending) return;
  const interval = getAutoSaveIntervalMs();
  if (!interval) return;
  state.autoSaveTimer = window.setTimeout(() => {
    state.autoSaveTimer = null;
    if (!state.hasUnsavedChanges || state.isSaving) return;
    void saveCurrentState({ silent: true, reason: "auto" });
  }, interval);
}

function clearAutoSaveTimer() {
  if (!state.autoSaveTimer) return;
  window.clearTimeout(state.autoSaveTimer);
  state.autoSaveTimer = null;
}

function clearStatusTimer(resetOverride = true) {
  if (state.statusTimer) {
    window.clearTimeout(state.statusTimer);
    state.statusTimer = null;
  }
  if (resetOverride) state.statusOverride = false;
}

function clearStoryPanelRenderTimer() {
  if (!state.storyPanelRenderTimer) return;
  window.clearTimeout(state.storyPanelRenderTimer);
  state.storyPanelRenderTimer = null;
}

function getAutoSaveIntervalMs() {
  const host = window.NarrativeCanvasHost;
  try {
    const value = typeof host?.getAutoSaveIntervalMs === "function"
      ? host.getAutoSaveIntervalMs()
      : host?.autoSaveIntervalMs;
    const normalized = normalizeAutoSaveIntervalMs(value);
    if (normalized) return normalized;
  } catch (error) {
    console.error(error);
  }
  return FALLBACK_AUTO_SAVE_INTERVAL_MS;
}

function normalizeAutoSaveIntervalMs(value) {
  const numeric = Number(value);
  if (!Number.isFinite(numeric) || numeric <= 0) return 0;
  return Math.round(clamp(numeric, MIN_AUTO_SAVE_INTERVAL_MS, MAX_AUTO_SAVE_INTERVAL_MS));
}

function renderWorkspaceFile() {
  const activeFile = state.activeFileId || "adventure";
  setWorkspacePanelActive(dom.canvasPanel, activeFile === "adventure");
  setWorkspacePanelActive(dom.charactersPanel, activeFile === "characters");
  setWorkspacePanelActive(dom.variablesPanel, activeFile === "variables");
  setWorkspacePanelActive(dom.eventsPanel, activeFile === "events");
  setWorkspacePanelActive(dom.documentPanel, activeFile === "document");

  if (activeFile === "adventure") renderCanvasSurface();
  if (activeFile === "characters") renderDocumentSurface("characters");
  if (activeFile === "variables") renderDocumentSurface("variables");
  if (activeFile === "events") renderDocumentSurface("events");
  if (activeFile === "document") renderDocumentSurface("document");
}

function setWorkspacePanelActive(panel, active) {
  if (!panel) return;
  panel.classList.toggle("active", active);
  panel.setAttribute("aria-hidden", String(!active));
}

function renderDocumentSurface(fileId, options = {}) {
  if (!fileViews[fileId]) return;
  const renderedVersion = state.documentRenderedVersions?.[fileId] || 0;
  const panel = getDocumentPanel(fileId);
  const shouldRender = options.force
    || options.focusJsonToken
    || renderedVersion !== state.documentRenderVersion
    || !panel?.childElementCount;
  if (!shouldRender) return;
  if (fileId === "characters") renderCharactersPage();
  if (fileId === "variables") renderVariablesPage(options);
  if (fileId === "events") renderEventsSheetPage();
  if (fileId === "document") renderProjectDocumentPage();
  markDocumentSurfaceRendered(fileId);
}

function markDocumentSurfaceRendered(fileId) {
  if (!state.documentRenderedVersions || typeof state.documentRenderedVersions !== "object") {
    state.documentRenderedVersions = {};
  }
  state.documentRenderedVersions[fileId] = state.documentRenderVersion;
}

function getDocumentPanel(fileId) {
  if (fileId === "characters") return dom.charactersPanel;
  if (fileId === "variables") return dom.variablesPanel;
  if (fileId === "events") return dom.eventsPanel;
  if (fileId === "document") return dom.documentPanel;
  return null;
}

function getProjectDocumentFormatDetails(value = state.documentFormat) {
  const format = normalizeDocumentFormat(value);
  return {
    plain: { filename: "Document.md", label: "Plain text", exportLabel: "Export MD" },
    ink: { filename: "Document.ink", label: "Ink", exportLabel: "Export Ink" },
    yarn: { filename: "Document.yarn", label: "Yarn", exportLabel: "Export Yarn" },
    twee: { filename: "Document.twee", label: "Twee", exportLabel: "Export Twee" }
  }[format];
}

function renderDocumentChromeChevron() {
  return `<svg class="document-chrome-chevron" viewBox="0 0 24 24" aria-hidden="true" focusable="false"><path d="M5 15.5 12 8.5l7 7"></path></svg>`;
}

function renderProjectDocumentPage() {
  if (!dom.documentPanel) return;
  const format = normalizeDocumentFormat(state.documentFormat);
  const formatDetails = getProjectDocumentFormatDetails(format);
  const chromeCollapsed = Boolean(state.documentChromeCollapsed);
  const chromeToggleLabel = t(chromeCollapsed ? "Expand document header" : "Collapse document header");
  if (state.documentDraftFormat !== format || state.documentApplyStatus === "synced") {
    state.documentDraft = buildProjectDocumentSource(format);
    state.documentDraftFormat = format;
  }
  const formatButtons = [
    ["plain", "Plain text"],
    ["ink", "Ink"],
    ["yarn", "Yarn"],
    ["twee", "Twee"]
  ].map(([value, label]) => `
    <button class="document-format-button${format === value ? " active" : ""}" data-action="set-document-format" data-document-format="${value}" type="button" aria-pressed="${format === value}">${t(label)}</button>
  `).join("");
  const editorHint = t("Edit narrative content here. Recognized nodes, choices, conditions, effects, routes, and variables sync to the project; canvas layout and unsupported metadata stay unchanged.");
  dom.documentPanel.innerHTML = `
    <div class="document-source-shell" data-document-toc="${state.documentTocOpen ? "open" : "closed"}" data-document-chrome="${chromeCollapsed ? "collapsed" : "expanded"}">
      <div class="document-source-chrome">
        <header class="document-header document-project-header">
          <div>
            <span class="pane-kicker">${escapeHtml(t("Document"))}</span>
            <h2>${escapeHtml(formatDetails.filename)}</h2>
            <div class="document-meta">${escapeHtml(`${t("{nodes} nodes, {links} links", { nodes: state.project.nodes.length, links: state.project.links.length })} · ${t(formatDetails.label)}`)}</div>
          </div>
          <div class="document-actions">
            <button class="small-button" type="button" data-action="export-current-document">${escapeHtml(t(formatDetails.exportLabel))}</button>
          </div>
        </header>
        <div class="document-editor-toolbar">
          <div class="document-editor-identity">
            <span class="document-editor-filename" title="${escapeAttr(editorHint)}">${escapeHtml(formatDetails.filename)}</span>
            <div class="document-format-switch" role="group" aria-label="${escapeAttr(t("Document format"))}">${formatButtons}</div>
          </div>
          <div class="document-editor-status">
            <span class="document-sync-status" data-document-sync-status data-status="${escapeAttr(state.documentApplyStatus)}">${escapeHtml(getDocumentSyncStatusLabel())}</span>
            <button class="icon-button document-chrome-toggle" type="button" data-action="toggle-document-chrome" aria-expanded="${!chromeCollapsed}" aria-label="${escapeAttr(chromeToggleLabel)}" title="${escapeAttr(chromeToggleLabel)}">${renderDocumentChromeChevron()}</button>
          </div>
        </div>
      </div>
      <div class="document-editor-main">
        <div class="document-editor-surface">
          <div class="document-editor-gutter" data-document-gutter aria-hidden="true"></div>
          <div class="document-editor-input">
            <div class="document-editor-highlight" data-document-highlight aria-hidden="true"></div>
            <div class="document-editor-search-layer" data-document-search-layer aria-hidden="true"></div>
            <textarea class="document-source-editor" data-document-source="project" spellcheck="false" wrap="off" aria-label="${escapeAttr(t("Project document source"))}" title="${escapeAttr(editorHint)}">${escapeHtml(state.documentDraft)}</textarea>
          </div>
        </div>
        <aside class="document-toc-panel" data-document-toc-panel aria-label="${escapeAttr(t("Document outline"))}"></aside>
      </div>
    </div>
  `;
  bindDocumentEditor();
}

function bindDocumentEditor() {
  const editor = dom.documentPanel?.querySelector("[data-document-source]");
  if (!editor) return;
  renderDocumentHighlight(editor);
  syncDocumentEditorGutter(editor);
  updateDocumentSearchMatches();
  renderDocumentSearchLayer(editor);
  renderDocumentToc();
  updateDocumentTocButton();
  editor.addEventListener("scroll", () => {
    syncDocumentEditorGutter(editor);
    syncDocumentOverlayScroll(editor);
  }, { passive: true });
}

function syncDocumentEditorGutter(editor) {
  if (!editor) return;
  const gutter = editor.closest(".document-editor-surface")?.querySelector("[data-document-gutter]");
  if (!gutter) return;
  const lineCount = Math.max(1, editor.value.split("\n").length);
  if (Number(gutter.dataset.lineCount) !== lineCount) {
    // Plain text on a white-space:pre gutter — one text node instead of thousands of elements.
    const numbers = new Array(lineCount);
    for (let line = 1; line <= lineCount; line += 1) numbers[line - 1] = line;
    gutter.textContent = numbers.join("\n");
    gutter.dataset.lineCount = String(lineCount);
  }
  gutter.scrollTop = editor.scrollTop;
}

function syncDocumentOverlayScroll(editor) {
  const input = editor?.closest(".document-editor-input");
  if (!input) return;
  const transform = `translate(${-editor.scrollLeft}px, ${-editor.scrollTop}px)`;
  const highlight = input.querySelector("[data-document-highlight]");
  const searchLayer = input.querySelector("[data-document-search-layer]");
  if (highlight) highlight.style.transform = transform;
  if (searchLayer) searchLayer.style.transform = transform;
}

// Colorize the draft in a layer behind the transparent textarea (VSCode-style highlighting).
function renderDocumentHighlight(editor) {
  const highlight = editor?.closest(".document-editor-input")?.querySelector("[data-document-highlight]");
  if (!highlight) return;
  highlight.innerHTML = highlightDocumentSource(editor.value, normalizeDocumentFormat(state.documentFormat));
  syncDocumentOverlayScroll(editor);
}

function scheduleDocumentHighlight(editor) {
  if (state.documentHighlightFrame) return;
  state.documentHighlightFrame = window.requestAnimationFrame(() => {
    state.documentHighlightFrame = null;
    renderDocumentHighlight(editor);
    // Refresh the outline in the same frame so an open TOC tracks edits without
    // re-parsing the whole document on every keystroke.
    if (state.documentTocOpen) renderDocumentToc();
  });
}

const DOCUMENT_TOKEN_CACHE = {};

function getDocumentTokenEntry(format) {
  if (DOCUMENT_TOKEN_CACHE[format]) return DOCUMENT_TOKEN_CACHE[format];
  const defs = buildDocumentTokenDefs(format);
  const combined = new RegExp(defs.map((def) => `(${def.src})`).join("|"), "g");
  const entry = { defs, combined };
  DOCUMENT_TOKEN_CACHE[format] = entry;
  return entry;
}

function buildDocumentTokenDefs(format) {
  if (format === "ink") {
    return [
      { src: "^\\s*=+[^\\n]*", cls: "tok-key" },
      { src: "^\\s*[*+]\\s", cls: "tok-choice" },
      { src: "^\\s*(?:VAR|CONST|LIST|INCLUDE|EXTERNAL)\\b", cls: "tok-keyword" },
      { src: "^\\s*~[^\\n]*", cls: "tok-op" },
      { src: "//[^\\n]*", cls: "tok-comment" },
      { src: "->\\s*[\\w.]+", cls: "tok-op" },
      { src: "\\{[^}]*\\}", cls: "tok-var" }
    ];
  }
  if (format === "yarn") {
    return [
      { src: "^(?:---|===)\\s*$", cls: "tok-op" },
      { src: "^[A-Za-z_][\\w ]*:\\s", cls: "tok-key" },
      { src: "^\\s*->\\s", cls: "tok-choice" },
      { src: "//[^\\n]*", cls: "tok-comment" },
      { src: "<<[^>]*>>", cls: "tok-op" },
      { src: "\\{[^}]*\\}", cls: "tok-var" }
    ];
  }
  if (format === "twee") {
    return [
      { src: "^::\\s+[^\\n]*", cls: "tok-key" },
      { src: "<<[^>]*>>", cls: "tok-op" },
      { src: "<!--[^\\n]*?-->", cls: "tok-comment" },
      { src: "/\\*[^\\n]*?\\*/", cls: "tok-comment" },
      { src: "\\$[A-Za-z_]\\w*", cls: "tok-var" },
      { src: "\\[[^\\]]*\\]", cls: "tok-choice" }
    ];
  }
  return [
    { src: "^#{1,6}\\s[^\\n]*", cls: "tok-heading" },
    { src: "^\\s*>[^\\n]*", cls: "tok-quote" },
    { src: "^\\s*[-*]\\s", cls: "tok-list" },
    { src: "<!--[^\\n]*?-->", cls: "tok-comment" },
    { src: "`[^`]*`", cls: "tok-code" },
    { src: "\\*\\*[^*]+\\*\\*", cls: "tok-strong" },
    { src: "\\{[^}]+\\}", cls: "tok-var" }
  ];
}

function highlightDocumentSource(text, format) {
  const entry = getDocumentTokenEntry(format);
  return text.split("\n").map((line) => tokenizeDocumentLine(line, entry)).join("\n");
}

function tokenizeDocumentLine(line, entry) {
  if (!line) return "";
  const { combined, defs } = entry;
  combined.lastIndex = 0;
  let out = "";
  let last = 0;
  let match;
  while ((match = combined.exec(line))) {
    if (match.index > last) out += escapeHtml(line.slice(last, match.index));
    let groupIndex = 1;
    while (groupIndex <= defs.length && match[groupIndex] === undefined) groupIndex += 1;
    const cls = defs[groupIndex - 1]?.cls || "";
    out += `<span class="${cls}">${escapeHtml(match[0])}</span>`;
    last = match.index + match[0].length;
    if (match[0].length === 0) combined.lastIndex += 1;
  }
  if (last < line.length) out += escapeHtml(line.slice(last));
  return out;
}

// --- Document search (same find behavior as the other workspace tabs) ---

function getDocumentSearchMatchOffsets() {
  return (state.documentSearchMatches || []).map((range) => range.start);
}

function updateDocumentSearchMatches() {
  const query = (state.documentSearch || "").trim().toLowerCase();
  const matches = [];
  if (query) {
    const text = (state.documentDraft || "").toLowerCase();
    let from = 0;
    while (from <= text.length - query.length) {
      const idx = text.indexOf(query, from);
      if (idx < 0) break;
      matches.push({ start: idx, end: idx + query.length });
      from = idx + Math.max(1, query.length);
    }
  }
  state.documentSearchMatches = matches;
  if (state.documentSearchIndex >= matches.length) state.documentSearchIndex = matches.length ? matches.length - 1 : -1;
}

function renderDocumentSearchLayer(editor) {
  const layer = editor?.closest(".document-editor-input")?.querySelector("[data-document-search-layer]");
  if (!layer) return;
  const matches = state.documentSearchMatches || [];
  if (!matches.length) {
    layer.innerHTML = "";
    return;
  }
  const text = editor.value;
  let html = "";
  let last = 0;
  matches.forEach((range, index) => {
    if (range.start > last) html += escapeHtml(text.slice(last, range.start));
    const cls = index === state.documentSearchIndex ? "doc-search-hit current" : "doc-search-hit";
    html += `<span class="${cls}">${escapeHtml(text.slice(range.start, range.end))}</span>`;
    last = range.end;
  });
  if (last < text.length) html += escapeHtml(text.slice(last));
  layer.innerHTML = html;
  syncDocumentOverlayScroll(editor);
}

function focusDocumentSearchMatch(offset) {
  const editor = dom.documentPanel?.querySelector("[data-document-source]");
  if (!editor) return;
  renderDocumentSearchLayer(editor);
  const lineHeight = getDocumentEditorLineHeight(editor);
  const lineIndex = editor.value.slice(0, offset).split("\n").length - 1;
  const target = Math.max(0, lineIndex * lineHeight - editor.clientHeight / 2);
  editor.scrollTop = target;
  syncDocumentEditorGutter(editor);
  syncDocumentOverlayScroll(editor);
}

function getDocumentEditorLineHeight(editor) {
  const parsed = parseFloat(getComputedStyle(editor).lineHeight);
  if (Number.isFinite(parsed) && parsed > 0) return parsed;
  const fontSize = parseFloat(getComputedStyle(editor).fontSize) || 13;
  return fontSize * 1.6;
}

// --- Document outline (table of contents) ---

function buildDocumentOutline() {
  const format = normalizeDocumentFormat(state.documentFormat);
  const lines = (state.documentDraft || "").split("\n");
  const items = [];
  lines.forEach((line, index) => {
    if (format === "ink") {
      let match = /^\s*==+\s*(?:function\s+)?([^=]+?)\s*=*\s*$/.exec(line);
      if (match) { items.push({ line: index, level: 1, text: match[1].trim() }); return; }
      match = /^\s*=\s*([\w ]+?)\s*$/.exec(line);
      if (match) items.push({ line: index, level: 2, text: match[1].trim() });
      return;
    }
    if (format === "yarn") {
      const match = /^title:\s*(.*)$/.exec(line);
      if (match) items.push({ line: index, level: 1, text: match[1].trim() });
      return;
    }
    if (format === "twee") {
      const match = /^::\s+(.+?)(?:\s+\[[^\]]*\])?\s*$/.exec(line);
      if (match) items.push({ line: index, level: 1, text: match[1].trim() });
      return;
    }
    const match = /^(#{1,6})\s+(.*)$/.exec(line);
    if (match) items.push({ line: index, level: match[1].length, text: match[2].trim() });
  });
  return items;
}

function renderDocumentToc() {
  const panel = dom.documentPanel?.querySelector("[data-document-toc-panel]");
  if (!panel) return;
  const items = buildDocumentOutline();
  if (!items.length) {
    panel.innerHTML = `
      <div class="document-toc-title">${escapeHtml(t("Outline"))}</div>
      <div class="document-toc-empty">${escapeHtml(t("No headings yet."))}</div>
    `;
    return;
  }
  panel.innerHTML = `
    <div class="document-toc-title">${escapeHtml(t("Outline"))}</div>
    <ul class="document-toc-list">
      ${items.map((item) => `
        <li>
          <button type="button" class="document-toc-item" data-action="jump-document-toc" data-toc-line="${item.line}" data-toc-level="${item.level}">
            ${escapeHtml(item.text || t("(untitled)"))}
          </button>
        </li>
      `).join("")}
    </ul>
  `;
}

function toggleDocumentToc() {
  if (state.activeFileId !== "document") return;
  state.documentTocOpen = !state.documentTocOpen;
  const shell = dom.documentPanel?.querySelector(".document-source-shell");
  if (shell) shell.dataset.documentToc = state.documentTocOpen ? "open" : "closed";
  renderDocumentToc();
  updateDocumentTocButton();
  const editor = dom.documentPanel?.querySelector("[data-document-source]");
  if (editor) window.requestAnimationFrame(() => {
    syncDocumentEditorGutter(editor);
    syncDocumentOverlayScroll(editor);
  });
}

function toggleDocumentChrome() {
  if (state.activeFileId !== "document") return;
  state.documentChromeCollapsed = !state.documentChromeCollapsed;
  const shell = dom.documentPanel?.querySelector(".document-source-shell");
  const button = shell?.querySelector("[data-action='toggle-document-chrome']");
  const expanded = !state.documentChromeCollapsed;
  const label = t(expanded ? "Collapse document header" : "Expand document header");
  if (shell) shell.dataset.documentChrome = expanded ? "expanded" : "collapsed";
  if (button) {
    button.setAttribute("aria-expanded", String(expanded));
    button.setAttribute("aria-label", label);
    button.setAttribute("title", label);
  }
  const editor = dom.documentPanel?.querySelector("[data-document-source]");
  if (editor) window.requestAnimationFrame(() => {
    syncDocumentEditorGutter(editor);
    syncDocumentOverlayScroll(editor);
    editor.focus({ preventScroll: true });
  });
}

function updateDocumentTocButton() {
  const button = dom.scope?.querySelector(".workspace-toc-button");
  if (!button) return;
  button.setAttribute("aria-pressed", String(Boolean(state.documentTocOpen)));
}

function jumpToDocumentOutline(lineIndex) {
  const editor = dom.documentPanel?.querySelector("[data-document-source]");
  if (!editor || !Number.isFinite(lineIndex)) return;
  const lineHeight = getDocumentEditorLineHeight(editor);
  editor.scrollTop = Math.max(0, lineIndex * lineHeight - lineHeight);
  const offset = getDocumentLineStartOffset(editor.value, lineIndex);
  try {
    editor.focus({ preventScroll: true });
    editor.setSelectionRange(offset, offset);
  } catch (_error) {
    // no-op for embedded WebViews without selection support
  }
  syncDocumentEditorGutter(editor);
  syncDocumentOverlayScroll(editor);
}

function getDocumentLineStartOffset(text, lineIndex) {
  let offset = 0;
  const lines = text.split("\n");
  for (let index = 0; index < lineIndex && index < lines.length; index += 1) {
    offset += lines[index].length + 1;
  }
  return offset;
}

function scrollActiveWorkspaceTop() {
  const panels = {
    characters: dom.charactersPanel,
    events: dom.eventsPanel,
    variables: dom.variablesPanel,
    document: dom.documentPanel
  };
  const panel = panels[state.activeFileId];
  if (!panel) return;
  try {
    panel.scrollTo({ top: 0, behavior: "auto" });
  } catch (_error) {
    // Fallback for embedded WebViews with partial Element.scrollTo support.
  }
  panel.scrollTop = 0;
  const editor = panel.querySelector?.("[data-document-source]");
  if (editor) {
    editor.scrollTop = 0;
    syncDocumentEditorGutter(editor);
    syncDocumentOverlayScroll(editor);
  }
}

function handleDocumentSourceKeyDown(event) {
  const target = event.target;
  if (!target?.hasAttribute?.("data-document-source")) return false;
  if (event.key !== "Tab" || event.altKey || event.ctrlKey || event.metaKey) return false;
  event.preventDefault();
  const indent = "  ";
  const value = target.value;
  const start = target.selectionStart;
  const end = target.selectionEnd;
  if (start === end && !event.shiftKey) {
    target.value = value.slice(0, start) + indent + value.slice(end);
    target.selectionStart = target.selectionEnd = start + indent.length;
  } else {
    const lineStart = value.lastIndexOf("\n", start - 1) + 1;
    const selection = value.slice(lineStart, end);
    if (event.shiftKey) {
      const outdented = selection.replace(/^( {1,2}|\t)/gm, "");
      target.value = value.slice(0, lineStart) + outdented + value.slice(end);
      const firstLineTrim = selection.length - selection.replace(/^( {1,2}|\t)/, "").length;
      target.selectionStart = Math.max(lineStart, start - firstLineTrim);
      target.selectionEnd = end - (selection.length - outdented.length);
    } else {
      const indented = selection.replace(/^/gm, indent);
      target.value = value.slice(0, lineStart) + indented + value.slice(end);
      target.selectionStart = start + indent.length;
      target.selectionEnd = end + (indented.length - selection.length);
    }
  }
  state.documentDraft = target.value;
  state.documentDraftFormat = state.documentFormat;
  state.documentApplyStatus = "pending";
  state.documentLastError = "";
  updateDocumentSyncStatus();
  syncDocumentEditorGutter(target);
  scheduleDocumentHighlight(target);
  updateDocumentSearchMatches();
  renderDocumentSearchLayer(target);
  scheduleDocumentSourceApply();
  return true;
}

function normalizeDocumentFormat(value) {
  return ["plain", "ink", "yarn", "twee"].includes(value) ? value : "plain";
}

function buildProjectDocumentSource(format = state.documentFormat) {
  const document = buildRuntimeExportDocument();
  if (format === "ink") return buildInkScript(document, { documentSource: true });
  if (format === "yarn") return buildYarnScript(document, { documentSource: true });
  if (format === "twee") return buildProjectDocumentTweeSource(document);
  return buildStoryMarkdown(document, { documentSource: true });
}

function buildProjectDocumentTweeSource(document) {
  return buildTweeScript(document, { documentSource: true });
}

function setDocumentFormat(value) {
  const nextFormat = normalizeDocumentFormat(value);
  if (nextFormat === state.documentFormat) return;
  if (!flushDocumentSourceApply()) return;
  state.documentFormat = nextFormat;
  state.documentDraft = "";
  state.documentDraftFormat = "";
  state.documentApplyStatus = "synced";
  state.documentLastError = "";
  renderDocumentSurface("document", { force: true });
}

function scheduleDocumentSourceApply() {
  clearDocumentApplyTimer();
  state.documentApplyTimer = window.setTimeout(() => {
    state.documentApplyTimer = null;
    applyDocumentSourceDraft();
  }, 320);
}

function clearDocumentApplyTimer() {
  if (!state.documentApplyTimer) return;
  window.clearTimeout(state.documentApplyTimer);
  state.documentApplyTimer = null;
}

function flushDocumentSourceApply() {
  clearDocumentApplyTimer();
  if (state.documentApplyStatus !== "pending") return state.documentApplyStatus !== "error";
  return applyDocumentSourceDraft();
}

function applyDocumentSourceDraft() {
  try {
    const baseline = parseProjectDocumentSource(buildProjectDocumentSource(state.documentFormat), state.documentFormat);
    const parsed = parseProjectDocumentSource(state.documentDraft, state.documentFormat);
    validateDocumentSourceStructure(parsed, baseline);
    const result = mergeProjectDocumentSource(parsed, baseline);
    state.documentApplyStatus = "synced";
    state.documentLastError = "";
    setProjectDirty(true);
    if (result.structureChanged) markProjectStructureChanged({ nodeTypes: true });
    invalidateCharacterRenderContext();
    renderProjectPanel();
    renderStoryPanel();
    // A `# Heading` edit updates state.project.title; refresh the shell so the top-left
    // project name and the project-file/filename display track it. renderShellState only
    // touches chrome (not the Document editor), so the caret and scroll are preserved.
    renderShellState();
    updateDocumentSyncStatus();
    setStatus("Document changes synced to project.");
    return true;
  } catch (error) {
    state.documentApplyStatus = "error";
    state.documentLastError = error instanceof Error ? error.message : String(error);
    updateDocumentSyncStatus();
    setStatus(`Document source error: ${state.documentLastError}`);
    return false;
  }
}

function validateDocumentSourceStructure(parsed, baseline) {
  const parsedNodes = parsed.nodes || [];
  const baselineNodes = baseline.nodes || [];
  if (parsedNodes.length !== baselineNodes.length) throw new Error(t("Document node structure is incomplete. Add or delete nodes on the canvas."));
  const parsedIds = parsedNodes.map((node) => node.id).filter(Boolean);
  if (parsedIds.length !== parsedNodes.length || new Set(parsedIds).size !== parsedIds.length) {
    throw new Error(t("Document node IDs are missing or duplicated."));
  }
  const parsedById = new Map(parsedNodes.map((node) => [node.id, node]));
  baselineNodes.forEach((baselineNode) => {
    const node = parsedById.get(baselineNode.id);
    if (!node) throw new Error(t("Document node structure is incomplete. Add or delete nodes on the canvas."));
    if (!node.hasBodyMarkers) throw new Error(t("Document body markers are incomplete."));
    if ((node.choices || []).length !== (baselineNode.choices || []).length) {
      throw new Error(t("Add or delete choices in the node inspector; Document edits existing choices."));
    }
    const routes = node.next?.length ? node.next : node.branches || [];
    const baselineRoutes = baselineNode.next?.length ? baselineNode.next : baselineNode.branches || [];
    if (routes.length !== baselineRoutes.length) {
      throw new Error(t("Add or delete routes on the canvas; Document edits existing routes."));
    }
  });
}

function getDocumentSyncStatusLabel() {
  if (state.documentApplyStatus === "pending") return t("Syncing");
  if (state.documentApplyStatus === "error") return t("Source error");
  return t("Synced");
}

function updateDocumentSyncStatus() {
  const status = dom.documentPanel?.querySelector("[data-document-sync-status]");
  if (!status) return;
  status.dataset.status = state.documentApplyStatus;
  status.textContent = getDocumentSyncStatusLabel();
  status.title = state.documentLastError || "";
}

function getDocumentRenderLimit(fileId) {
  if (!state.documentRenderLimits || typeof state.documentRenderLimits !== "object") {
    state.documentRenderLimits = {};
  }
  const current = Number(state.documentRenderLimits[fileId]);
  if (Number.isFinite(current) && current > 0) return current;
  state.documentRenderLimits[fileId] = DOCUMENT_RENDER_INITIAL_LIMIT;
  return DOCUMENT_RENDER_INITIAL_LIMIT;
}

function resetDocumentRenderLimit(fileId) {
  if (!state.documentRenderLimits || typeof state.documentRenderLimits !== "object") {
    state.documentRenderLimits = {};
  }
  state.documentRenderLimits[fileId] = DOCUMENT_RENDER_INITIAL_LIMIT;
}

function showMoreDocument(fileId) {
  if (!fileViews[fileId]) return;
  const current = getDocumentRenderLimit(fileId);
  state.documentRenderLimits[fileId] = current + DOCUMENT_RENDER_INCREMENT;
  renderDocumentSurface(fileId, { force: true });
  setStatus(`Showing more ${fileViews[fileId]}.`);
}

function renderDocumentLimitNotice(fileId, shown, total) {
  if (shown >= total) return "";
  const remaining = total - shown;
  return `
    <div class="document-limit-notice" data-document-limit-notice>
      <span>${t("{shown} of {total} shown.", { shown, total })} ${t("{count} more not rendered yet.", { count: remaining })}</span>
      <button class="small-button" type="button" data-action="show-more-document" data-document-id="${escapeAttr(fileId)}">
        ${t("Show {count} more", { count: Math.min(DOCUMENT_RENDER_INCREMENT, remaining) })}
      </button>
    </div>
  `;
}

function renderCharactersPage() {
  const model = buildCharacterDocumentModel(getCharacterRenderContext());
  const selectedEntry = state.codexSelectedEntryId
    ? model.characters.find((entry) => entry.id === state.codexSelectedEntryId)
    : null;
  if (state.codexSelectedEntryId && !selectedEntry) state.codexSelectedEntryId = "";
  if (selectedEntry) {
    renderCodexEntryDetail(selectedEntry, model.context);
    return;
  }
  const limit = getDocumentRenderLimit("characters");
  const shownCount = Math.min(model.visible.length, limit);
  const masonryColumns = getCharacterMasonryColumnCount();
  dom.charactersPanel.innerHTML = `
    <div class="document-shell codex-overview-shell">
      <header class="document-header">
        <div>
          <span class="pane-kicker">Library</span>
          <h2>${t("Narrative Library")}</h2>
          <div class="document-meta" data-character-search-meta>${escapeHtml(formatCharacterMeta(model))}</div>
        </div>
        <div class="document-actions">
          <button class="small-button" data-action="add-codex-entry">${t("Add entry")}</button>
          <button class="small-button" data-action="export-characters-md">${t("Export MD")}</button>
          <button class="small-button" data-action="export-characters-json">${t("Export JSON")}</button>
        </div>
      </header>
      <nav class="codex-category-tabs" data-codex-category-tabs aria-label="${escapeAttr(t("Category"))}">
        ${renderCodexCategoryTabs(model)}
      </nav>
      <div class="codex-tag-filters" data-codex-tag-filters>${renderCodexTagFilters(model).trim()}</div>
      <div class="codex-template-editor" data-codex-template-editor>${renderCodexTemplateEditorContent(model).trim()}</div>
      <div class="document-filter-bar" data-character-filter-bar>${renderCharacterFilterBar(model).trim()}</div>
      ${renderHiddenCharacterRestoreBar(model)}
      <div class="character-grid" data-masonry-columns="${masonryColumns}" style="--codex-masonry-columns:${masonryColumns}">
        ${renderCharacterCardsMarkup(model, limit)}
      </div>
      ${renderDocumentLimitNotice("characters", shownCount, model.visible.length)}
    </div>
  `;
  scheduleCharacterMasonryLayout();
  runAfterRender(hydrateCodexCanvasEmbeds);
}

function renderCodexEntryDetail(character, context = getCharacterRenderContext()) {
  runAfterRender(hydrateCodexCanvasEmbeds);
  const groups = context?.backlinkIndex?.get(character.id) || getCharacterBacklinkGroups(character);
  const backlinkCount = groups.reduce((total, group) => total + group.items.length, 0);
  dom.charactersPanel.innerHTML = `
    <div class="document-shell codex-detail-shell">
      <header class="document-header codex-detail-header">
        <div>
          <button class="codex-detail-back" type="button" data-action="close-codex-entry-detail">
            <span aria-hidden="true">←</span><span>${t("Back to all entries")}</span>
          </button>
          <span class="pane-kicker">${escapeHtml(t(character.kind))}</span>
          <h2>${escapeHtml(character.name || t("Unnamed Character"))}</h2>
        </div>
      </header>
      <div class="codex-detail-editor codex-detail-columns">
        <aside class="codex-detail-references" aria-label="${escapeAttr(t("Referenced nodes"))}">
          <h3 class="codex-detail-references-title">${t("Referenced nodes")} <small>${backlinkCount}</small></h3>
          ${renderCharacterBacklinkSections(groups, character.id)}
        </aside>
        <div class="codex-detail-main">
          ${renderCharacterCard(character, context, { includeBacklinks: false })}
        </div>
      </div>
    </div>
  `;
}

function buildCharacterDocumentModel(context = getCharacterRenderContext()) {
  const characters = context.characters;
  const hidden = characters.filter((character) => character.hidden);
  const visibleCharacters = characters.filter((character) => !character.hidden);
  const focusedCharacter = getActiveCharacterFocus();
  const queryRaw = state.characterSearch || "";
  const query = queryRaw.trim().toLowerCase();
  const kindFilter = normalizeCodexKindFilter(state.codexKindFilter);
  const tagFilter = normalizeOptionalString(state.codexTagFilter).trim();
  const categoryEntries = kindFilter === CODEX_ALL_FILTER
    ? visibleCharacters
    : visibleCharacters.filter((entry) => entry.kind === kindFilter);
  const tagCounts = collectCodexTagCounts(categoryEntries);
  const taggedEntries = tagFilter
    ? categoryEntries.filter((entry) => parseCodexTags(entry.tags).some((tag) => tag.toLowerCase() === tagFilter.toLowerCase()))
    : categoryEntries;
  const visible = query
    ? taggedEntries.filter((character) => characterMatchesSearch(character, query, context))
    : taggedEntries;
  const kindCounts = Object.fromEntries(getCodexKindsList().map((kind) => [kind, visibleCharacters.filter((entry) => entry.kind === kind).length]));
  return {
    context,
    characters,
    hidden,
    visibleCharacters,
    visible,
    focusedCharacter,
    query,
    queryRaw,
    kindFilter,
    tagFilter,
    tagCounts,
    kindCounts,
    hasFilters: Boolean(query || tagFilter || kindFilter !== CODEX_ALL_FILTER),
    linkCount: context.linkCount,
    totalCount: characters.length,
    hiddenCount: hidden.length,
    visibleCount: visible.length
  };
}

function formatCharacterMeta(model) {
  const focusText = model.focusedCharacter ? t(", focusing {name}", { name: model.focusedCharacter.name }) : "";
  const hiddenText = model.hiddenCount ? `, ${t("{count} hidden", { count: model.hiddenCount })}` : "";
  if (model.hasFilters) return `${t("{visible} of {total} library entries shown", { visible: model.visibleCount, total: model.totalCount })}${hiddenText}${focusText}`;
  return `${t("{entries} library entries, {links} node links", { entries: model.totalCount, links: model.linkCount })}${hiddenText}${focusText}`;
}

function renderCodexCategoryTabs(model) {
  const entries = [
    { value: CODEX_ALL_FILTER, label: t("All entries"), count: model.visibleCharacters.length },
    ...getCodexKindsList().map((kind) => ({ value: kind, label: t(kind), count: model.kindCounts[kind] || 0 }))
  ];
  const customKinds = new Set(normalizeCustomCodexKinds(state.project.customCodexKinds).map((kind) => kind.toLowerCase()));
  return `${entries.map((entry) => {
    const isCustom = customKinds.has(String(entry.value).toLowerCase());
    // Custom categories always show the × control; it's disabled (with a reason)
    // while entries still use the category, so the affordance stays discoverable.
    const removeTitle = entry.count === 0
      ? t("Remove category")
      : t("Move or remove its entries first.");
    return `
    <span class="codex-category-tab-wrap">
      <button class="codex-category-tab${model.kindFilter === entry.value ? " active" : ""}" type="button" data-action="set-codex-kind-filter" data-codex-kind="${escapeAttr(entry.value)}" aria-pressed="${model.kindFilter === entry.value ? "true" : "false"}">
        <span>${escapeHtml(entry.label)}</span><small>${entry.count}</small>
      </button>
      ${isCustom ? `<button class="codex-category-remove" type="button" data-action="remove-codex-kind" data-codex-kind="${escapeAttr(entry.value)}" title="${escapeAttr(removeTitle)}" aria-label="${escapeAttr(removeTitle)}"${entry.count === 0 ? "" : " aria-disabled=\"true\""}>×</button>` : ""}
    </span>`;
  }).join("")}
    <button class="codex-category-tab codex-category-add" type="button" data-action="add-codex-kind" title="${escapeAttr(t("Add category"))}" aria-label="${escapeAttr(t("Add category"))}">+</button>`;
}

function renderCodexTagFilters(model) {
  const entries = [...model.tagCounts.entries()];
  if (!entries.length) return "";
  return `
    <span class="codex-filter-label">${t("Tags")}</span>
    <button class="codex-tag-filter${model.tagFilter ? "" : " active"}" type="button" data-action="clear-codex-tag-filter" aria-pressed="${model.tagFilter ? "false" : "true"}">${t("All")}</button>
    ${entries.map(([tag, count]) => `
      <button class="codex-tag-filter${model.tagFilter.toLowerCase() === tag.toLowerCase() ? " active" : ""}" type="button" data-action="set-codex-tag-filter" data-codex-tag="${escapeAttr(tag)}" aria-pressed="${model.tagFilter.toLowerCase() === tag.toLowerCase() ? "true" : "false"}">
        <span>${escapeHtml(tag)}</span><small>${count}</small>
      </button>
    `).join("")}
  `;
}

function renderCodexTemplateEditorContent(model) {
  // Templates are per category; the editor only appears on a specific category tab.
  if (model.kindFilter === CODEX_ALL_FILTER) return "";
  const template = getCodexFieldTemplate(model.kindFilter);
  return `
    <span class="codex-filter-label">${t("Category fields")}</span>
    ${template.map((key) => `
      <button class="codex-template-chip" type="button" data-action="remove-codex-template-field" data-codex-template-key="${escapeAttr(key)}" aria-label="${escapeAttr(t("Remove template field: {key}", { key }))}" title="${escapeAttr(t("Remove from template. Entry values are kept."))}">
        <span>${escapeHtml(key)}</span><span class="codex-tag-remove" aria-hidden="true">×</span>
      </button>
    `).join("")}
    <input class="codex-template-input" data-codex-template-input placeholder="${escapeAttr(t("New field name"))}" spellcheck="false" autocomplete="off" aria-label="${escapeAttr(t("New field name"))}">
    <button class="small-button" type="button" data-action="add-codex-template-field">${t("Add")}</button>
  `;
}

function renderCharacterFilterBar(model) {
  const chips = [];
  if (model.query) {
    chips.push(`
      <button type="button" class="filter-chip filter-chip-button" data-action="clear-character-search" aria-label="${escapeAttr(t("Clear character search"))}">
        <span>${t("Search")}: ${escapeHtml(model.queryRaw.trim())}</span>
        <span class="filter-chip-clear">${t("Clear")}</span>
      </button>
    `);
  }
  if (model.tagFilter) {
    chips.push(`
      <button type="button" class="filter-chip filter-chip-button" data-action="clear-codex-tag-filter" aria-label="${escapeAttr(t("Library tag filter cleared."))}">
        <span>${t("Tags")}: ${escapeHtml(model.tagFilter)}</span>
        <span class="filter-chip-clear">${t("Clear")}</span>
      </button>
    `);
  }
  if (model.focusedCharacter) {
    chips.push(`
      <button type="button" class="filter-chip filter-chip-button" data-action="clear-character-focus" aria-label="${escapeAttr(t("Clear character focus"))}">
        <span>${t("Focus")}: ${escapeHtml(model.focusedCharacter.name)}</span>
        <span class="filter-chip-clear">${t("Clear")}</span>
      </button>
    `);
  }
  return chips.join("");
}

function renderHiddenCharacterRestoreBar(model) {
  if (!model.hidden?.length) return "";
  return `
    <div class="document-restore-bar character-restore-bar" data-character-restore-bar>
      <span>${t("Hidden entries")}:</span>
      ${model.hidden.map((character) => `
        <button type="button" class="filter-chip" data-action="show-character" data-character-id="${escapeAttr(character.id)}" title="${escapeAttr(t("Show entry"))}">
          ${escapeHtml(character.name || t("Unnamed Character"))}
        </button>
      `).join("")}
      <button type="button" class="small-button" data-action="show-all-characters">${t("Show all entries")}</button>
    </div>
  `;
}

function renderCharacterCardsMarkup(model, limit = getDocumentRenderLimit("characters")) {
  if (!model.characters.length) return `<div class="nc-empty-state">${t("No library entries yet.")}</div>`;
  const visible = model.visible.slice(0, Math.max(0, limit));
  if (!model.visibleCharacters.length && model.hiddenCount) return `<div class="nc-empty-state">${t("All entries are hidden.")}</div>`;
  if (!visible.length) return `<div class="nc-empty-state">${t("No library entries match the current filters.")}</div>`;
  return renderCharacterMasonryColumns(visible, model.context);
}

function getCharacterRenderContext() {
  if (state.characterRenderContext) return state.characterRenderContext;
  return buildCharacterRenderContext();
}

function buildCharacterRenderContext() {
  const characters = getCharacters();
  const backlinkIndex = buildCharacterBacklinkIndex(characters);
  const searchIndex = new Map(characters.map((character) => [character.id, buildCharacterSearchText(character)]));
  const linkCount = [...backlinkIndex.values()]
    .reduce((total, groups) => total + groups.reduce((groupTotal, group) => groupTotal + group.items.length, 0), 0);
  const context = { characters, backlinkIndex, searchIndex, linkCount };
  state.characterRenderContext = context;
  return context;
}

function invalidateCharacterRenderContext() {
  state.characterRenderContext = null;
  state.characterIndex = null;
  if (state.derived) state.derived.characterMentionContext = null;
}

function renderCharacterMasonryColumns(characters, context) {
  const columnCount = getCharacterMasonryColumnCount();
  const columns = Array.from({ length: columnCount }, () => ({ score: 0, cards: [] }));
  characters.forEach((character) => {
    const target = columns.reduce((best, column) => (column.score < best.score ? column : best), columns[0]);
    target.cards.push(renderCodexOverviewCard(character, context));
    target.score += estimateCharacterCardWeight(character, context);
  });
  return columns
    .map((column) => `<div class="character-column">${column.cards.join("")}</div>`)
    .join("");
}

function renderCodexOverviewCard(character, context = getCharacterRenderContext()) {
  const groups = context?.backlinkIndex?.get(character.id) || getCharacterBacklinkGroups(character);
  const backlinkCount = groups.reduce((total, group) => total + group.items.length, 0);
  const tags = parseCodexTags(character.tags).slice(0, 3);
  const extraTags = Math.max(0, parseCodexTags(character.tags).length - tags.length);
  const host = window.NarrativeCanvasHost;
  const imageReference = normalizeNodeVaultFileReference(character.imageFile);
  const imageUrl = imageReference && host?.getVaultResourceUrl ? host.getVaultResourceUrl(imageReference) : "";
  const summary = normalizeOptionalString(character.role || character.voice || character.notes).trim();
  const kindLabel = t(character.kind);
  const isFocused = state.characterFocusId === character.id;
  return `
    <button class="codex-overview-card${isFocused ? " focused" : ""}" type="button" data-action="open-codex-entry-detail" data-character-id="${escapeAttr(character.id)}" data-character-card-id="${escapeAttr(character.id)}" data-codex-kind="${escapeAttr(character.kind)}" aria-label="${escapeAttr(t("Open entry: {name}", { name: character.name || t("Unnamed Character") }))}">
      <span class="codex-overview-image${imageUrl ? " has-image" : ""}">
        ${renderCodexOverviewCover(character, imageUrl, kindLabel, host)}
        <span class="codex-overview-kind">${escapeHtml(kindLabel)}</span>
        ${isFocused ? `<span class="codex-overview-focus-badge">${escapeHtml(t("Focus"))}</span>` : ""}
      </span>
      <span class="codex-overview-body">
        <strong class="codex-overview-name">${escapeHtml(character.name || t("Unnamed Character"))}</strong>
        ${summary ? `<span class="codex-overview-summary">${escapeHtml(summary)}</span>` : ""}
        ${tags.length ? `<span class="codex-overview-tags">${tags.map((tag) => `<span>${escapeHtml(tag)}</span>`).join("")}${extraTags ? `<small>+${extraTags}</small>` : ""}</span>` : ""}
        <span class="codex-overview-meta">${escapeHtml(t("{count} linked nodes", { count: backlinkCount }))}</span>
      </span>
    </button>
  `;
}

function getCharacterMasonryColumnCount() {
  const shell = dom.charactersPanel?.querySelector(".document-shell");
  const measuredWidths = [
    shell?.clientWidth || 0,
    shell?.getBoundingClientRect?.().width || 0,
    dom.charactersPanel?.clientWidth || 0,
    dom.charactersPanel?.getBoundingClientRect?.().width || 0
  ].filter((width) => Number.isFinite(width) && width > 0);
  const shellWidth = measuredWidths.length ? Math.max(...measuredWidths) : Math.max(window.innerWidth || 0, 320);
  return clamp(Math.floor((shellWidth + 16) / 260), 1, 6);
}

function applyCharacterMasonryLayout() {
  if (state.activeFileId !== "characters") return;
  const grid = dom.charactersPanel?.querySelector(".character-grid");
  if (!grid) return;
  const model = buildCharacterDocumentModel();
  const columnCount = getCharacterMasonryColumnCount();
  if (grid.dataset.masonryColumns === String(columnCount)) return;
  grid.dataset.masonryColumns = String(columnCount);
  grid.style.setProperty("--codex-masonry-columns", String(columnCount));
  grid.innerHTML = renderCharacterCardsMarkup(model, getDocumentRenderLimit("characters"));
}

function scheduleCharacterMasonryLayout() {
  // Measure twice: once right away, and once after the sidebar collapse/expand
  // transition has finished animating the panel width.
  window.setTimeout(applyCharacterMasonryLayout, 60);
  window.setTimeout(applyCharacterMasonryLayout, 340);
}

function estimateCharacterCardWeight(character) {
  // Overview cards share a fixed-ratio cover, so heights only differ by the
  // summary and tag lines. Uniform weights keep the masonry columns even.
  const summary = normalizeOptionalString(character.role || character.voice || character.notes).trim();
  return 240 + (summary ? 22 : 0) + (parseCodexTags(character.tags).length ? 26 : 0);
}

function buildCharacterSearchText(character) {
  const extraFieldText = normalizeCodexExtraFields(character.extraFields)
    .map((field) => `${field.key} ${formatCodexExtraFieldValue(field.value, field.type)}`);
  return [character.name, character.kind, character.role, character.voice, character.tags, character.notes, ...extraFieldText, ...normalizeCodexVaultFiles(character.vaultFiles)]
    .filter(Boolean)
    .map(String)
    .join("\n")
    .toLowerCase();
}

function parseCodexTags(value) {
  const seen = new Set();
  return String(value || "")
    .split(/[,，\n]/)
    .map((tag) => tag.trim())
    .filter((tag) => {
      const key = tag.toLowerCase();
      if (!tag || seen.has(key)) return false;
      seen.add(key);
      return true;
    });
}

function handleCodexTagInput(input) {
  const value = String(input?.value || "");
  const parts = value.split(/[,，\n]/);
  if (parts.length < 2) {
    updateCodexTagSuggestions(input);
    return false;
  }
  const trailingSeparator = /[,，\n]$/.test(value);
  const draft = trailingSeparator ? "" : parts.pop() || "";
  addCodexTags(input.dataset.characterId, parts, draft);
  return true;
}

function handleCodexTagKeyDown(event) {
  const input = event.target;
  if (!input?.hasAttribute?.("data-character-tag-input")) return false;
  if (event.isComposing || event.keyCode === 229) return false;
  const suggestionButtons = getVisibleCodexTagSuggestionButtons(input);
  if ((event.key === "ArrowDown" || event.key === "ArrowUp") && suggestionButtons.length) {
    const picked = moveActiveSuggestion(suggestionButtons, event.key === "ArrowDown" ? 1 : -1);
    if (picked?.id) input.setAttribute("aria-activedescendant", picked.id);
    event.preventDefault();
    return true;
  }
  if (event.key === "Enter" || event.key === "," || event.key === "，") {
    event.preventDefault();
    const activeSuggestion = suggestionButtons.find((button) => button.classList.contains("active"));
    if (event.key === "Enter" && activeSuggestion) {
      selectCodexTagSuggestion(activeSuggestion);
    } else if (input.value.trim()) {
      addCodexTags(input.dataset.characterId, [input.value], "");
    }
    return true;
  }
  if (event.key === "Backspace" && !input.value) {
    const tags = parseCodexTags(getCharacterById(input.dataset.characterId)?.tags);
    if (tags.length) {
      event.preventDefault();
      removeCodexTagAt(input.dataset.characterId, tags.length - 1, "", true);
    }
    return true;
  }
  if (event.key === "Escape") {
    hideCodexTagSuggestions(input);
    event.preventDefault();
    return true;
  }
  return false;
}

function updateCodexTagSuggestions(input) {
  const editor = input?.closest?.("[data-character-tag-editor]");
  const panel = editor?.querySelector?.("[data-codex-tag-suggestions]");
  if (!editor || !panel) return;
  const character = getCharacterById(input.dataset.characterId);
  const currentTags = new Set(parseCodexTags(character?.tags).map((tag) => tag.toLowerCase()));
  const query = String(input.value || "").trim().toLowerCase();
  const suggestions = [...collectCodexTagCounts(getCharacters()).entries()]
    .filter(([tag]) => !currentTags.has(tag.toLowerCase()) && (!query || tag.toLowerCase().includes(query)))
    .sort((a, b) => {
      const aPrefix = query && a[0].toLowerCase().startsWith(query) ? 0 : 1;
      const bPrefix = query && b[0].toLowerCase().startsWith(query) ? 0 : 1;
      return aPrefix - bPrefix || b[1] - a[1] || a[0].localeCompare(b[0]);
    })
    .slice(0, 8);
  if (!suggestions.length) {
    hideCodexTagSuggestions(input);
    return;
  }
  panel.innerHTML = suggestions.map(([tag, count], index) => `
    <button class="codex-tag-suggestion${index === 0 ? " active" : ""}" id="codex-tag-suggestion-${escapeAttr(character.id)}-${index}" type="button" role="option" data-action="select-codex-tag-suggestion" data-character-id="${escapeAttr(character.id)}" data-codex-tag-value="${escapeAttr(tag)}" aria-selected="${index === 0 ? "true" : "false"}">
      <span>${escapeHtml(tag)}</span><small>${count}</small>
    </button>
  `).join("");
  panel.hidden = false;
  input.setAttribute("aria-expanded", "true");
  input.setAttribute("aria-activedescendant", `codex-tag-suggestion-${character.id}-0`);
}

function hideCodexTagSuggestions(input) {
  const panel = input?.closest?.("[data-character-tag-editor]")?.querySelector?.("[data-codex-tag-suggestions]");
  if (panel) {
    panel.hidden = true;
    panel.innerHTML = "";
  }
  input?.setAttribute?.("aria-expanded", "false");
  input?.removeAttribute?.("aria-activedescendant");
}

function getVisibleCodexTagSuggestionButtons(input) {
  const panel = input?.closest?.("[data-character-tag-editor]")?.querySelector?.("[data-codex-tag-suggestions]");
  return panel && !panel.hidden ? [...panel.querySelectorAll("[data-codex-tag-value]")] : [];
}

function selectCodexTagSuggestion(target) {
  if (!target?.dataset?.codexTagValue) return false;
  return addCodexTags(target.dataset.characterId, [target.dataset.codexTagValue], "");
}

function addCodexTags(characterId, values, focusDraft = "") {
  const character = getCharacterById(characterId);
  if (!character) return false;
  const existing = parseCodexTags(character.tags);
  const seen = new Set(existing.map((tag) => tag.toLowerCase()));
  const additions = parseCodexTags((Array.isArray(values) ? values : [values]).join(","));
  const next = [...existing];
  additions.forEach((tag) => {
    const key = tag.toLowerCase();
    if (seen.has(key)) return;
    seen.add(key);
    next.push(tag);
  });
  if (next.length === existing.length) {
    if (focusDraft !== null) focusCodexTagInput(characterId, focusDraft);
    return false;
  }
  const historyBefore = getHistorySnapshot();
  writeCodexTags(character, next, {
    focusDraft,
    historyBefore,
    status: "Tag added."
  });
  return true;
}

function removeCodexTag(target) {
  const editor = target?.closest?.("[data-character-tag-editor]");
  const draft = editor?.querySelector("[data-character-tag-input]")?.value || "";
  removeCodexTagAt(target?.dataset?.characterId, Number(target?.dataset?.codexTagIndex), draft, false);
}

function removeCodexTagAt(characterId, index, focusDraft = "", recordHistory = true) {
  const character = getCharacterById(characterId);
  const tags = parseCodexTags(character?.tags);
  if (!character || !Number.isInteger(index) || index < 0 || index >= tags.length) return false;
  const historyBefore = recordHistory ? getHistorySnapshot() : null;
  tags.splice(index, 1);
  writeCodexTags(character, tags, {
    focusDraft,
    historyBefore,
    status: "Tag removed."
  });
  return true;
}

function writeCodexTags(character, tags, options = {}) {
  character.tags = parseCodexTags(tags.join(",")).join(", ");
  invalidateCharacterRenderContext();
  setProjectDirty(true);
  renderCharacterListSurfaces();
  if (options.historyBefore) commitHistoryFromSnapshot(options.historyBefore);
  if (options.status) setStatus(options.status);
  if (options.focusDraft !== null && options.focusDraft !== undefined) {
    focusCodexTagInput(character.id, options.focusDraft);
  }
}

function focusCodexTagInput(characterId, draft = "") {
  // Timer instead of requestAnimationFrame: rAF can be starved under headless/virtual-time
  // test runs and throttled iframes, dropping the preserved tag draft.
  window.setTimeout(() => {
    const input = dom.charactersPanel?.querySelector(`[data-character-tag-input][data-character-id="${CSS.escape(characterId)}"]`);
    if (!input) return;
    input.value = draft;
    input.focus?.({ preventScroll: true });
    input.setSelectionRange?.(input.value.length, input.value.length);
    updateCodexTagSuggestions(input);
  }, 0);
}

function collectCodexTagCounts(entries) {
  const counts = new Map();
  (entries || []).forEach((entry) => {
    parseCodexTags(entry.tags).forEach((tag) => {
      const existing = [...counts.keys()].find((key) => key.toLowerCase() === tag.toLowerCase());
      const key = existing || tag;
      counts.set(key, (counts.get(key) || 0) + 1);
    });
  });
  return new Map([...counts.entries()].sort((a, b) => a[0].localeCompare(b[0])));
}

function characterMatchesSearch(character, query, context = state.characterRenderContext) {
  if (!query) return true;
  const haystack = context?.searchIndex?.get(character.id) || buildCharacterSearchText(character);
  return haystack.includes(query);
}

function renderCharacterGridForSearch() {
  if (state.codexSelectedEntryId) {
    renderCharactersPage();
    return;
  }
  const grid = dom.charactersPanel?.querySelector(".character-grid");
  const meta = dom.charactersPanel?.querySelector("[data-character-search-meta]");
  const filterBar = dom.charactersPanel?.querySelector("[data-character-filter-bar]");
  const categoryTabs = dom.charactersPanel?.querySelector("[data-codex-category-tabs]");
  const tagFilters = dom.charactersPanel?.querySelector("[data-codex-tag-filters]");
  if (!grid) return;
  const model = buildCharacterDocumentModel();
  const limit = getDocumentRenderLimit("characters");
  const shownCount = Math.min(model.visible.length, limit);
  if (meta) meta.textContent = formatCharacterMeta(model);
  if (filterBar) filterBar.innerHTML = renderCharacterFilterBar(model).trim();
  if (categoryTabs) categoryTabs.innerHTML = renderCodexCategoryTabs(model);
  if (tagFilters) tagFilters.innerHTML = renderCodexTagFilters(model).trim();
  const templateEditor = dom.charactersPanel?.querySelector("[data-codex-template-editor]");
  if (templateEditor) templateEditor.innerHTML = renderCodexTemplateEditorContent(model).trim();
  const restoreBar = dom.charactersPanel?.querySelector("[data-character-restore-bar]");
  if (restoreBar) restoreBar.outerHTML = renderHiddenCharacterRestoreBar(model);
  else if (filterBar) filterBar.insertAdjacentHTML("afterend", renderHiddenCharacterRestoreBar(model));
  grid.innerHTML = renderCharacterCardsMarkup(model, limit);
  const masonryColumns = getCharacterMasonryColumnCount();
  grid.dataset.masonryColumns = String(masonryColumns);
  grid.style.setProperty("--codex-masonry-columns", String(masonryColumns));
  runAfterRender(hydrateCodexCanvasEmbeds);
  const shell = dom.charactersPanel?.querySelector(".document-shell");
  shell?.querySelector("[data-document-limit-notice]")?.remove();
  shell?.insertAdjacentHTML("beforeend", renderDocumentLimitNotice("characters", shownCount, model.visible.length));
}

// Overview cover precedence: entry icon → board snapshot → preview-image board
// snapshot (all images in their layout, scaled) → category placeholder.
function renderCodexOverviewCover(character, imageUrl, kindLabel, host) {
  if (character.icon && host?.getVaultResourceUrl) {
    return `<img src="${escapeAttr(host.getVaultResourceUrl(character.icon))}" alt="" loading="lazy">`;
  }
  const canvasPath = normalizeNodeVaultFileReference(character.canvasFile);
  if (canvasPath && host?.readVaultFile) {
    return `<span class="codex-overview-canvas" data-codex-canvas-embed data-canvas-cover="true" data-canvas-path="${escapeAttr(canvasPath)}" aria-hidden="true"></span>`;
  }
  const images = host?.getVaultResourceUrl ? getCharacterImages(character) : [];
  if (images.length) {
    return `<span class="codex-overview-board" aria-hidden="true">${images.map((image) => `
      <img src="${escapeAttr(host.getVaultResourceUrl(image.path))}" style="left:${image.x}%;top:${image.y}%;width:${image.w}%" alt="" loading="lazy" draggable="false">
    `).join("")}</span>`;
  }
  if (imageUrl) {
    return `<img src="${escapeAttr(imageUrl)}" alt="" loading="lazy">`;
  }
  return `<span class="codex-overview-placeholder" aria-hidden="true">${escapeHtml(kindLabel.slice(0, 1))}</span>`;
}

function renderCharacterCard(character, context = getCharacterRenderContext(), options = {}) {
  const isFocused = state.characterFocusId === character.id;
  const includeBacklinks = options.includeBacklinks !== false;
  const groups = includeBacklinks
    ? (context?.backlinkIndex?.get(character.id) || getCharacterBacklinkGroups(character))
    : [];
  const kindLabels = getCodexKindFieldLabels(character.kind);
  return `
    <article class="character-card ${isFocused ? "focused" : ""}" data-character-card-id="${escapeAttr(character.id)}" data-codex-kind="${escapeAttr(character.kind)}">
      <div class="character-card-header">
        ${window.NarrativeCanvasHost?.getVaultResourceUrl && character.icon
          ? `<img class="codex-icon-avatar" src="${escapeAttr(window.NarrativeCanvasHost.getVaultResourceUrl(character.icon))}" alt="" loading="lazy">`
          : ""}
        <label class="field">
          <span>${t("Name")}</span>
          <input data-character-id="${escapeAttr(character.id)}" data-character-field="name" value="${escapeAttr(character.name)}">
        </label>
        <div class="character-card-actions">
          <button class="small-button" data-action="${isFocused ? "clear-character-focus" : "focus-character"}" data-character-id="${escapeAttr(character.id)}">${isFocused ? t("Clear") : t("Focus")}</button>
          <button class="small-button" data-action="hide-character" data-character-id="${escapeAttr(character.id)}">${t("Hide")}</button>
          <button class="small-button danger-button" title="${escapeAttr(t("Delete entry"))}" data-action="delete-character" data-character-id="${escapeAttr(character.id)}">${t("Delete")}</button>
        </div>
      </div>
      ${window.NarrativeCanvasHost?.searchVaultFiles ? `
        <div class="field codex-icon-field">
          <span>${t("Icon")}</span>
          <div class="codex-icon-row">
            <div class="codex-vault-file-input-wrap codex-icon-input-wrap">
              <input data-character-icon-input data-character-id="${escapeAttr(character.id)}" value="${escapeAttr(character.icon || "")}" placeholder="${escapeAttr(t("Search icon image"))}" spellcheck="false" autocomplete="off" role="combobox" aria-label="${escapeAttr(t("Search icon image"))}" aria-autocomplete="list" aria-expanded="false">
              <div class="vault-file-suggestions" data-vault-file-suggestions hidden role="listbox" aria-label="${escapeAttr(t("Vault file suggestions"))}"></div>
            </div>
            ${character.icon ? `<button class="icon-button danger-button vault-row-icon-button" type="button" data-action="clear-codex-icon" data-character-id="${escapeAttr(character.id)}" title="${escapeAttr(t("Remove icon"))}" aria-label="${escapeAttr(t("Remove icon"))}">×</button>` : ""}
          </div>
        </div>
      ` : ""}
      ${renderCodexPluginFileFields(character)}
      <div class="field-row">
        <label class="field">
          <span>${t("Category")}</span>
          <select data-character-id="${escapeAttr(character.id)}" data-character-field="kind">
            ${renderCodexKindOptions(character.kind)}
          </select>
        </label>
        <label class="field">
          <span>${escapeHtml(kindLabels.primary)}</span>
          <input data-character-id="${escapeAttr(character.id)}" data-character-field="role" value="${escapeAttr(character.role || "")}">
        </label>
        <label class="field">
          <span>${escapeHtml(kindLabels.secondary)}</span>
          <input data-character-id="${escapeAttr(character.id)}" data-character-field="voice" value="${escapeAttr(character.voice || "")}">
        </label>
      </div>
      <div class="field codex-tags-field">
        <span>${t("Tags")}</span>
        ${renderCodexTagEditor(character)}
      </div>
      <label class="field">
        <span>${t("Notes")}</span>
        <textarea data-character-id="${escapeAttr(character.id)}" data-character-field="notes">${escapeHtml(character.notes || "")}</textarea>
      </label>
      ${renderCodexExtraFieldsEditor(character)}
      ${includeBacklinks ? renderCharacterBacklinkSections(groups, character.id) : ""}
    </article>
  `;
}

function renderCodexExtraFieldsEditor(character) {
  const fields = normalizeCodexExtraFields(character.extraFields);
  return `
    <section class="codex-extra-fields" data-character-extra-fields data-character-id="${escapeAttr(character.id)}">
      <div class="codex-extra-fields-header">
        <span>${t("Custom fields")}</span>
        <button class="small-button" type="button" data-action="add-codex-extra-field" data-character-id="${escapeAttr(character.id)}">+ ${t("Add field")}</button>
      </div>
      ${fields.length ? fields.map((field, index) => `
        <div class="codex-extra-field-row">
          <input data-character-id="${escapeAttr(character.id)}" data-character-extra-index="${index}" data-character-extra-part="key" value="${escapeAttr(field.key)}" placeholder="${escapeAttr(t("Field name"))}" spellcheck="false">
          <select data-character-id="${escapeAttr(character.id)}" data-character-extra-index="${index}" data-character-extra-part="type" aria-label="${escapeAttr(t("Field type"))}">
            ${[
              ["string", "Text"],
              ["number", "Number"],
              ["boolean", "Boolean"],
              ["array", "List"],
              ["object", "Object"],
              ["null", "Empty"]
            ].map(([value, label]) => `<option value="${value}" ${field.type === value ? "selected" : ""}>${escapeHtml(t(label))}</option>`).join("")}
          </select>
          <input data-character-id="${escapeAttr(character.id)}" data-character-extra-index="${index}" data-character-extra-part="value" value="${escapeAttr(formatCodexExtraFieldValue(field.value, field.type))}" placeholder="${escapeAttr(t("Field value"))}" ${field.type === "null" ? "disabled" : ""}>
          <button class="icon-button danger-button" type="button" data-action="remove-codex-extra-field" data-character-id="${escapeAttr(character.id)}" data-character-extra-index="${index}" title="${escapeAttr(t("Remove field"))}" aria-label="${escapeAttr(t("Remove field"))}">×</button>
        </div>
      `).join("") : `<div class="codex-extra-fields-empty">${t("No custom fields yet. Fields sync to the entry's markdown frontmatter.")}</div>`}
    </section>
  `;
}

function renderCodexTagEditor(character) {
  const tags = parseCodexTags(character.tags);
  return `
    <div class="codex-tag-editor" data-character-tag-editor data-character-id="${escapeAttr(character.id)}">
      ${tags.map((tag, index) => `
        <button class="codex-tag-chip" type="button" data-action="remove-codex-tag" data-character-id="${escapeAttr(character.id)}" data-codex-tag-index="${index}" aria-label="${escapeAttr(t("Remove tag: {tag}", { tag }))}">
          <span>${escapeHtml(tag)}</span><span class="codex-tag-remove" aria-hidden="true">×</span>
        </button>
      `).join("")}
      <input class="codex-tag-input" data-character-tag-input data-character-id="${escapeAttr(character.id)}" value="" placeholder="${escapeAttr(t("Add tag..."))}" aria-label="${escapeAttr(t("Add tag"))}" aria-autocomplete="list" aria-expanded="false" aria-controls="codex-tag-suggestions-${escapeAttr(character.id)}" autocomplete="off" spellcheck="false">
      <div class="codex-tag-suggestions" id="codex-tag-suggestions-${escapeAttr(character.id)}" data-codex-tag-suggestions role="listbox" aria-label="${escapeAttr(t("Tag suggestions"))}" hidden></div>
    </div>
  `;
}

function renderVisionBoard(kind, id, images, options = {}) {
  const host = window.NarrativeCanvasHost;
  if (!host?.getVaultResourceUrl || !images.length) return "";
  const focused = Boolean(options.focused);
  return `
    <div${focused ? " id=\"visionBoardCanvas\"" : ""} class="vision-board-canvas${focused ? " is-focused" : " is-embedded"}" data-vision-board-kind="${escapeAttr(kind)}" data-vision-board-id="${escapeAttr(id)}">
      ${images.map((image, index) => {
        const imageUrl = host.getVaultResourceUrl(image.path);
        return `
          <article class="vision-board-tile" data-vision-board-tile data-vision-board-index="${index}" style="--vision-x:${image.x};--vision-y:${image.y};--vision-w:${image.w}" title="${escapeAttr(image.path)}">
            ${imageUrl ? `<img src="${escapeAttr(imageUrl)}" alt="" draggable="false" loading="lazy">` : `<span class="vision-board-missing">${escapeHtml(image.path.split("/").pop() || image.path)}</span>`}
            <div class="vision-board-tile-actions">
              <button type="button" data-action="open-codex-reference" data-vault-file-reference="${escapeAttr(image.path)}" title="${escapeAttr(t("Open file"))}" aria-label="${escapeAttr(t("Open file"))}">↗</button>
              ${kind === "character" ? `<button type="button" data-action="remove-codex-image" data-character-id="${escapeAttr(id)}" data-codex-image-index="${index}" title="${escapeAttr(t("Remove image"))}" aria-label="${escapeAttr(t("Remove image"))}">×</button>` : ""}
            </div>
            ${focused ? `<span class="vision-board-tile-resize" data-vision-board-resize title="${escapeAttr(t("Resize image"))}" aria-hidden="true"></span>` : ""}
          </article>
        `;
      }).join("")}
    </div>
  `;
}

function renderCodexPluginFileFields(character) {
  const host = window.NarrativeCanvasHost;
  if (!host?.loadCodexEntries || !host?.searchVaultFiles) return "";
  const images = getCharacterImages(character);
  const pickerOpen = state.codexImagePickerCharacterId === character.id;
  const canvasPath = normalizeNodeVaultFileReference(character.canvasFile);
  // An entry with a native canvas board delegates images and linked files to it:
  // the board is embedded read-only here and edited in Obsidian's canvas view.
  if (host.readVaultFile && canvasPath) {
    return `
      <section class="codex-plugin-files">
        ${character.codexFile ? `
          <div class="codex-managed-file-row">
            <span><strong>${t("Library file")}</strong><small>${escapeHtml(character.codexFile)}</small></span>
            <button class="small-button" type="button" data-action="open-codex-reference" data-vault-file-reference="${escapeAttr(character.codexFile)}">${t("Open file")}</button>
          </div>
        ` : ""}
        <div class="codex-canvas-section">
          <div class="codex-vault-files-header">
            <span>${t("Board")}</span>
            <div>
              <button class="small-button" type="button" data-action="open-codex-reference" data-vault-file-reference="${escapeAttr(canvasPath)}">${t("Open board")}</button>
              <button class="small-button" type="button" data-action="detach-codex-canvas" data-character-id="${escapeAttr(character.id)}" title="${escapeAttr(t("Board detached. The canvas file is kept in the vault."))}">${t("Detach board")}</button>
            </div>
          </div>
          <div class="codex-canvas-embed" data-codex-canvas-embed data-canvas-path="${escapeAttr(canvasPath)}" data-action="open-codex-reference" data-vault-file-reference="${escapeAttr(canvasPath)}" role="button" tabindex="0" title="${escapeAttr(t("Open board"))}" aria-label="${escapeAttr(t("Open board"))}">${escapeHtml(t("Loading board..."))}</div>
        </div>
      </section>
    `;
  }
  return `
    <section class="codex-plugin-files">
      ${character.codexFile ? `
        <div class="codex-managed-file-row">
          <span><strong>${t("Library file")}</strong><small>${escapeHtml(character.codexFile)}</small></span>
          <button class="small-button" type="button" data-action="open-codex-reference" data-vault-file-reference="${escapeAttr(character.codexFile)}">${t("Open file")}</button>
        </div>
      ` : ""}
      ${host.createCodexCanvas ? `
        <div class="codex-canvas-create-row">
          <span>${escapeHtml(t("Create a native canvas board for this entry. Its images and linked files move onto the board."))}</span>
          <button class="small-button" type="button" data-action="create-codex-canvas" data-character-id="${escapeAttr(character.id)}">${t("Create board")}</button>
        </div>
      ` : ""}
      ${renderCodexVaultFileLinks(character)}
      <div class="codex-image-editor${images.length ? " has-image" : ""}${pickerOpen ? " picker-open" : ""}" data-codex-image-drop data-character-id="${escapeAttr(character.id)}">
        <div class="vision-board-toolbar">
          ${images.length ? `<strong>${t("Preview images")} <small>${images.length}</small></strong>` : `<span></span>`}
          <div>
            <button class="small-button" type="button" data-action="choose-codex-image-file" data-character-id="${escapeAttr(character.id)}">+ ${t("Add images")}</button>
            ${images.length ? `<button class="small-button" type="button" data-action="open-vision-board" data-vision-board-kind="character" data-vision-board-id="${escapeAttr(character.id)}">${t("Focus")}</button>` : ""}
          </div>
        </div>
        <input data-codex-local-image-input data-character-id="${escapeAttr(character.id)}" type="file" accept="image/*" multiple hidden>
        ${renderVisionBoard("character", character.id, images)}
        ${pickerOpen ? `
          <div class="codex-image-picker" data-codex-image-picker>
            <div class="codex-image-picker-head">
              <input data-character-id="${escapeAttr(character.id)}" data-character-image-picker-input="true" value="" placeholder="${escapeAttr(t("Search images in vault"))}" spellcheck="false" autocomplete="off" role="combobox" aria-label="${escapeAttr(t("Search images in vault"))}" aria-autocomplete="list" aria-expanded="false">
              <button class="small-button" type="button" data-action="import-local-codex-images" data-character-id="${escapeAttr(character.id)}">${t("Add local images")}</button>
              <button class="icon-button" type="button" data-action="close-codex-image-picker" data-character-id="${escapeAttr(character.id)}" title="${escapeAttr(t("Close image picker"))}" aria-label="${escapeAttr(t("Close image picker"))}">×</button>
            </div>
            <div class="vault-file-suggestions codex-image-suggestions" data-vault-file-suggestions role="listbox" aria-label="${escapeAttr(t("Search images in vault"))}" hidden></div>
          </div>
        ` : ""}
      </div>
    </section>
  `;
}

// Library entries can link vault files like nodes do: each row opens or removes its
// file, and the search input at the bottom links a new one. Paths sync to the entry's
// frontmatter `files` array.
function renderCodexVaultFileLinks(character) {
  const host = window.NarrativeCanvasHost;
  if (!host?.searchVaultFiles) return "";
  const files = normalizeCodexVaultFiles(character.vaultFiles);
  return `
    <div class="codex-vault-files">
      <div class="codex-vault-files-header"><span>${t("Vault file")}</span>${files.length ? `<small>${files.length}</small>` : ""}</div>
      ${files.map((path, index) => {
        const parts = path.split("/");
        const name = parts.pop() || path;
        const folder = parts.join("/");
        return `
          <div class="codex-vault-file-row" data-codex-vault-row-index="${index}">
            <button class="cast-drag-handle vault-drag-handle" type="button" data-codex-vault-drag="${index}" data-character-id="${escapeAttr(character.id)}" title="${escapeAttr(t("Drag to reorder linked file"))}" aria-label="${escapeAttr(t("Drag to reorder linked file"))}">::</button>
            <button class="node-vault-open" type="button" data-action="open-codex-reference" data-vault-file-reference="${escapeAttr(path)}" title="${escapeAttr(t("Open vault file"))}">
              <span class="node-vault-open-icon" aria-hidden="true">↗</span>
              <span class="node-vault-open-text"><strong>${escapeHtml(name)}</strong>${folder ? `<small>${escapeHtml(folder)}</small>` : ""}</span>
            </button>
            <button class="icon-button danger-button" type="button" data-action="remove-codex-vault-file" data-character-id="${escapeAttr(character.id)}" data-codex-vault-file-index="${index}" title="${escapeAttr(t("Remove vault file"))}" aria-label="${escapeAttr(t("Remove vault file"))}">×</button>
          </div>
        `;
      }).join("")}
      <div class="codex-vault-file-input-wrap">
        <input data-character-vault-file-input data-character-id="${escapeAttr(character.id)}" value="" placeholder="${escapeAttr(t("Search or choose a vault file"))}" spellcheck="false" autocomplete="off" role="combobox" aria-label="${escapeAttr(t("Add vault file"))}" aria-autocomplete="list" aria-expanded="false">
        <div class="vault-file-suggestions" data-vault-file-suggestions hidden role="listbox" aria-label="${escapeAttr(t("Vault file suggestions"))}"></div>
      </div>
    </div>
  `;
}

function detachCodexCanvas(characterId) {
  const character = getCharacterById(characterId);
  if (!character?.canvasFile) return;
  character.canvasFile = "";
  invalidateCharacterRenderContext();
  setProjectDirty(true);
  renderWorkspaceFile();
  setStatus(t("Board detached. The canvas file is kept in the vault."));
}

// Re-renders board previews when their .canvas file changes on disk (called by the
// plugin's vault watcher).
function refreshCodexCanvasPreviews(pathValue) {
  const path = normalizeNodeVaultFileReference(pathValue);
  dom.charactersPanel?.querySelectorAll?.("[data-codex-canvas-embed]").forEach((element) => {
    if (path && normalizeNodeVaultFileReference(element.dataset.canvasPath) !== path) return;
    void renderCodexCanvasPreview(element);
  });
}

function setCodexIcon(characterId, path) {
  const character = getCharacterById(characterId);
  if (!character) return;
  character.icon = normalizeNodeVaultFileReference(path);
  invalidateCharacterRenderContext();
  setProjectDirty(true);
  renderCharacterAwareSurfaces();
  setStatus(character.icon ? t("Icon updated.") : t("Icon removed."));
}

async function createCodexCanvasForCharacter(characterId) {
  const host = window.NarrativeCanvasHost;
  const character = getCharacterById(characterId);
  if (!character || !host?.createCodexCanvas) return;
  try {
    const path = await host.createCodexCanvas({
      id: character.id,
      name: character.name,
      images: getCharacterImages(character),
      files: normalizeCodexVaultFiles(character.vaultFiles).map((entry) => entry.path ?? entry),
      codexFile: character.codexFile
    });
    if (!path) return;
    character.canvasFile = normalizeNodeVaultFileReference(path);
    invalidateCharacterRenderContext();
    setProjectDirty(true);
    renderWorkspaceFile();
    setStatus(t("Board created."));
  } catch (error) {
    console.error(error);
    setStatus(t("Could not create the board."));
  }
}

// The board preview parses the .canvas JSON directly and draws a scaled, read-only
// snapshot: image cards show the image, note cards show a text excerpt, groups show
// dashed frames, edges are drawn as lines. (Obsidian's own embed component does not
// render inside the plugin's shell.)
const CANVAS_PREVIEW_COLOR_PRESETS = {
  1: "#fb464c", 2: "#e9973f", 3: "#e0de71", 4: "#44cf6e", 5: "#53dfdd", 6: "#a882ff"
};

function hydrateCodexCanvasEmbeds() {
  const host = window.NarrativeCanvasHost;
  if (!host?.readVaultFile) return;
  dom.charactersPanel?.querySelectorAll?.("[data-codex-canvas-embed]").forEach((element) => {
    if (element.dataset.canvasEmbedHydrated) return;
    element.dataset.canvasEmbedHydrated = "true";
    void renderCodexCanvasPreview(element, host);
  });
}

async function renderCodexCanvasPreview(element, host = window.NarrativeCanvasHost) {
  try {
    const raw = await host.readVaultFile(element.dataset.canvasPath);
    const text = typeof raw === "string" ? raw : String(raw?.text || "");
    const data = JSON.parse(text || "{}");
    if (!element.isConnected) return;
    renderCanvasPreviewInto(element, data, host);
  } catch (error) {
    console.error(error);
    element.textContent = t("Could not load the board.");
  }
}

function renderCanvasPreviewInto(element, data, host) {
  const nodes = (Array.isArray(data?.nodes) ? data.nodes : []).filter((node) => Number.isFinite(Number(node?.x)));
  const edges = Array.isArray(data?.edges) ? data.edges : [];
  if (!nodes.length) {
    element.textContent = t("The board is empty.");
    return;
  }
  const pad = 40;
  const minX = Math.min(...nodes.map((node) => Number(node.x))) - pad;
  const minY = Math.min(...nodes.map((node) => Number(node.y))) - pad;
  const maxX = Math.max(...nodes.map((node) => Number(node.x) + (Number(node.width) || 0))) + pad;
  const maxY = Math.max(...nodes.map((node) => Number(node.y) + (Number(node.height) || 0))) + pad;
  const boundsWidth = Math.max(1, maxX - minX);
  const boundsHeight = Math.max(1, maxY - minY);
  const containerWidth = element.clientWidth || 640;
  // Cover mode (overview card): fit the whole board into the fixed cover box.
  const heightLimit = element.dataset.canvasCover === "true" ? (element.clientHeight || 150) : 520;
  const scale = Math.min(1, containerWidth / boundsWidth, heightLimit / boundsHeight);
  const nodeById = new Map(nodes.map((node) => [node.id, node]));
  const edgePoint = (node, side) => {
    const x = Number(node.x) - minX;
    const y = Number(node.y) - minY;
    const w = Number(node.width) || 0;
    const h = Number(node.height) || 0;
    if (side === "left") return [x, y + h / 2];
    if (side === "right") return [x + w, y + h / 2];
    if (side === "top") return [x + w / 2, y];
    return [x + w / 2, y + h];
  };
  const colorOf = (value) => {
    const raw = String(value || "").trim();
    if (!raw) return "";
    return CANVAS_PREVIEW_COLOR_PRESETS[raw] || (raw.startsWith("#") ? raw : "");
  };
  // Groups render behind cards, in area order so nested groups stay visible.
  const ordered = [...nodes].sort((a, b) => (a.type === "group" ? -1 : 0) - (b.type === "group" ? -1 : 0));
  const cards = ordered.map((node) => {
    const x = Number(node.x) - minX;
    const y = Number(node.y) - minY;
    const w = Number(node.width) || 0;
    const h = Number(node.height) || 0;
    const color = colorOf(node.color);
    const style = `left:${x}px;top:${y}px;width:${w}px;height:${h}px;${color ? `--canvas-card-color:${escapeAttr(color)};` : ""}`;
    if (node.type === "group") {
      return `<div class="canvas-preview-group" style="${style}">${node.label ? `<span>${escapeHtml(String(node.label))}</span>` : ""}</div>`;
    }
    if (node.type === "text") {
      return `<div class="canvas-preview-card is-text" style="${style}"><div class="canvas-preview-card-body">${escapeHtml(String(node.text || "")).slice(0, 1200)}</div></div>`;
    }
    if (node.type === "file") {
      const path = String(node.file || "");
      const name = path.split("/").pop() || path;
      if (CODEX_IMAGE_FILE_PATTERN.test(path) && host?.getVaultResourceUrl) {
        return `<div class="canvas-preview-card is-image" style="${style}"><img src="${escapeAttr(host.getVaultResourceUrl(path))}" alt="" loading="lazy" draggable="false"></div>`;
      }
      return `<div class="canvas-preview-card is-file" style="${style}" data-canvas-preview-file="${escapeAttr(path)}"><div class="canvas-preview-card-title">${escapeHtml(name)}</div><div class="canvas-preview-card-body" data-canvas-preview-file-body>${escapeHtml(t("Loading linked file..."))}</div></div>`;
    }
    return `<div class="canvas-preview-card is-file" style="${style}"><div class="canvas-preview-card-title">${escapeHtml(String(node.url || node.type || ""))}</div></div>`;
  }).join("");
  const lines = edges.map((edge) => {
    const from = nodeById.get(edge.fromNode);
    const to = nodeById.get(edge.toNode);
    if (!from || !to) return "";
    const [x1, y1] = edgePoint(from, String(edge.fromSide || "bottom"));
    const [x2, y2] = edgePoint(to, String(edge.toSide || "top"));
    return `<line x1="${x1}" y1="${y1}" x2="${x2}" y2="${y2}"></line>`;
  }).join("");
  const offsetX = element.dataset.canvasCover === "true"
    ? Math.max(0, Math.round((containerWidth - boundsWidth * scale) / 2))
    : 0;
  element.replaceChildren();
  element.insertAdjacentHTML("beforeend", `
    <div class="canvas-preview-viewport" style="height:${Math.round(boundsHeight * scale)}px">
      <div class="canvas-preview-inner" style="left:${offsetX}px;width:${boundsWidth}px;height:${boundsHeight}px;transform:scale(${scale})">
        <svg class="canvas-preview-edges" width="${boundsWidth}" height="${boundsHeight}" aria-hidden="true">${lines}</svg>
        ${cards}
      </div>
    </div>
  `);
  hydrateCanvasPreviewFileCards(element, host);
}

function hydrateCanvasPreviewFileCards(element, host) {
  if (!host?.readVaultFile) return;
  element.querySelectorAll("[data-canvas-preview-file]").forEach((card) => {
    const path = card.dataset.canvasPreviewFile;
    const body = card.querySelector("[data-canvas-preview-file-body]");
    if (!path || !body) return;
    Promise.resolve(host.readVaultFile(path)).then((raw) => {
      if (!body.isConnected) return;
      const text = (typeof raw === "string" ? raw : String(raw?.text || ""))
        .replace(/^---\n[\s\S]*?\n---\n?/, "")
        .trim();
      body.textContent = text ? text.slice(0, 600) : t("Linked file is empty.");
    }).catch(() => {
      if (body.isConnected) body.textContent = t("Could not preview the linked vault file.");
    });
  });
}

function addCodexVaultFile(characterId, path) {
  const character = getCharacterById(characterId);
  const normalized = normalizeNodeVaultFileReference(path);
  if (!character || !normalized) return;
  const files = normalizeCodexVaultFiles(character.vaultFiles);
  if (files.includes(normalized)) {
    hideVaultFileSuggestions();
    setStatus("File already linked.");
    return;
  }
  files.push(normalized);
  character.vaultFiles = files;
  invalidateCharacterRenderContext();
  setProjectDirty(true);
  hideVaultFileSuggestions();
  renderWorkspaceFile();
  setStatus(t("Vault file linked."));
}

function removeCodexVaultFile(characterId, index) {
  const character = getCharacterById(characterId);
  if (!character) return;
  const files = normalizeCodexVaultFiles(character.vaultFiles);
  if (!Number.isInteger(index) || index < 0 || index >= files.length) return;
  files.splice(index, 1);
  character.vaultFiles = files;
  invalidateCharacterRenderContext();
  setProjectDirty(true);
  renderWorkspaceFile();
  setStatus(t("Vault file removed."));
}

function renderCodexKindOptions(selected) {
  const value = normalizeCodexKind(selected);
  return getCodexKindsList()
    .map((kind) => `<option value="${escapeAttr(kind)}" ${kind === value ? "selected" : ""}>${escapeHtml(t(kind))}</option>`)
    .join("");
}

function getCodexKindFieldLabels(kind) {
  if (kind === "Character") return { primary: t("Role"), secondary: t("Voice") };
  if (kind === "Location") return { primary: t("Type"), secondary: t("Atmosphere") };
  if (kind === "Item") return { primary: t("Type"), secondary: t("Owner") };
  if (kind === "Lore") return { primary: t("Type"), secondary: t("Reference source") };
  // Custom categories get generic, purpose-neutral labels instead of inheriting
  // the Character defaults; add per-field templates for anything more specific.
  return { primary: t("Type"), secondary: t("Summary") };
}

function renderCharacterBacklinkSections(groups, characterId) {
  const nonEmptyGroups = groups.filter((group) => group.items.length);
  if (!nonEmptyGroups.length) return `<div class="linked-node empty">${t("No linked scenes yet")}</div>`;
  return `
    <div class="character-backlink-section">
      ${nonEmptyGroups.map((group) => renderCharacterBacklinkGroup(group, characterId)).join("")}
    </div>
  `;
}

function renderCharacterBacklinkGroup(group, characterId) {
  const expanded = isCharacterBacklinkGroupExpanded(characterId, group.id);
  const label = t(group.label);
  return `
    <section class="character-backlink-group nc-collapsible${expanded ? " expanded" : ""}">
      <header class="character-backlink-header nc-collapsible-header">
        <button class="nc-section-toggle character-backlink-toggle" type="button" data-action="toggle-character-backlink-group" data-character-id="${escapeAttr(characterId)}" data-character-backlink-group="${escapeAttr(group.id)}" aria-expanded="${expanded ? "true" : "false"}" aria-label="${escapeAttr(`${label} (${group.items.length})`)}">
          <span class="nc-section-caret" aria-hidden="true">${expanded ? "▾" : "▸"}</span>
          <span class="nc-section-title">${escapeHtml(label)}</span>
        </button>
        <span class="nc-section-count">${group.items.length}</span>
      </header>
      ${expanded ? `
        <div class="linked-node-list">
          ${renderCharacterBacklinkGroupItems(group)}
        </div>
      ` : ""}
    </section>
  `;
}

function getCharacterBacklinkGroupKey(characterId, groupId) {
  return JSON.stringify([String(characterId || ""), String(groupId || "")]);
}

function isCharacterBacklinkGroupExpanded(characterId, groupId) {
  // Groups are expanded by default; the set remembers the ones the user collapsed.
  const keys = state.characterBacklinkGroupCollapsedKeys;
  return !(keys instanceof Set && keys.has(getCharacterBacklinkGroupKey(characterId, groupId)));
}

function renderCharacterBacklinkGroupItems(group) {
  // The relation group header is the fold level; an expanded group always shows
  // every node without a second "show more" truncation.
  return group.items.map((item) => renderCharacterBacklinkItem(item)).join("");
}

function renderCharacterBacklinkItem(item) {
  const node = item.node;
  return `
    <button class="linked-node character-backlink" data-action="focus-character-node" data-node-id="${escapeAttr(node.id)}">
      <span class="character-backlink-main">
        <strong>${escapeHtml(node.title || getNodeTypeLabel(node.type))}</strong>
        <small>${escapeHtml(getNodeTypeLabel(node.type))} ${escapeHtml(node.id || getNodeDisplayId(node))}</small>
      </span>
    </button>
  `;
}

function renderVariablesPage(options = {}) {
  if (options.focusJsonToken) state.playbookJsonOpen = true;
  const variables = normalizeVariablesObject(state.project.variables);
  state.project.variables = variables;
  const entries = Object.entries(variables);
  const actions = getPlaybookActions();
  const ruleCards = getPlaybookRuleCards();
  const actionCount = actions.length;
  const ruleCount = ruleCards.length;
  const enabledRuleCount = ruleCards.filter((card) => card.enabled).length;
  const limit = getDocumentRenderLimit("variables");
  const variableFilters = getVariableDefinitionFilterOptions(entries);
  const validFilters = new Set(variableFilters.map((filter) => filter.value));
  if (state.playbookCategoryFilter && !validFilters.has(state.playbookCategoryFilter)) state.playbookCategoryFilter = null;
  const activeVariableFilter = state.playbookCategoryFilter;
  const filteredEntries = activeVariableFilter ? entries.filter((entry) => getVariableDefinitionFilterKey(entry[1]) === activeVariableFilter) : entries;
  const filteredActions = actions;
  const scriptNodes = getScriptBuilderNodes();
  const gateRows = getPlaybookGateRows();
  const stateReport = buildStateReport();
  const validationRows = stateReport.rows;
  const visibleEntries = filteredEntries.slice(0, limit);
  const visibleScriptNodes = scriptNodes.slice(0, limit);
  const visibleGateRows = gateRows.slice(0, limit);
  const visibleActions = filteredActions.slice(0, limit);
  const visibleRuleCards = ruleCards.slice(0, limit);
  const visibleValidationRows = validationRows.slice(0, limit);
  const shownCount = Math.max(visibleEntries.length, visibleScriptNodes.length, visibleGateRows.length, visibleActions.length, visibleRuleCards.length, visibleValidationRows.length);
  const totalCount = Math.max(filteredEntries.length, scriptNodes.length, gateRows.length, filteredActions.length, ruleCount, validationRows.length);
  const playbookJson = buildVariablesJson();
  const activeTab = getValidPlaybookTab(state.playbookTab);
  dom.variablesPanel.innerHTML = `
    <div class="document-shell ${state.playbookJsonOpen ? "playbook-json-open" : ""}">
      <header class="document-header">
        <div>
          <span class="pane-kicker">Playbook</span>
          <h2>${PLAYBOOK_FILE_NAME}</h2>
          <div class="document-meta">${t("{variables} variable definitions, {actions} variable actions, {rules} Play rules, {scriptRows} node logic rows", { variables: entries.length, actions: actionCount, rules: enabledRuleCount, scriptRows: scriptNodes.length })}</div>
        </div>
        <div class="document-actions">
          <button class="help-button" type="button" data-action="show-playbook-help" aria-label="${escapeAttr(t("What can Playbook.json do?"))}">?</button>
          <button class="small-button" type="button" data-action="toggle-playbook-json">${state.playbookJsonOpen ? t("Hide JSON") : t("Advanced JSON")}</button>
          <button class="small-button" type="button" data-action="export-variables-json">${t("Export JSON")}</button>
        </div>
      </header>
      ${renderPlaybookValueDatalists()}
      ${renderPlaybookTabs(activeTab)}
      ${activeTab === "script" ? renderScriptBuilderSection(scriptNodes, visibleScriptNodes) : ""}
      ${activeTab === "actions" ? renderPlaybookActionsSection(actions, visibleActions) : ""}
      ${activeTab === "gates" ? renderPlaybookGatesSection(gateRows, visibleGateRows) : ""}
      ${activeTab === "variables" ? `
        <section class="playbook-section">
        <header class="playbook-section-header">
          <div>
            <h3>${t("Variable Definitions")}</h3>
          </div>
          <div class="playbook-section-header-actions">
            <span>${filteredEntries.length}</span>
            <button class="small-button" type="button" data-action="add-variable">${t("Add variable")}</button>
          </div>
        </header>
        ${renderPlaybookCategoryStrip(entries, { filters: variableFilters, total: entries.length })}
        <div class="variable-table">
          <div class="variable-row variable-heading">
            <span>${t("Key")}</span>
            <span>${t("Type")}</span>
            <span>${t("Value")}</span>
            <span>JSON</span>
            <span></span>
          </div>
          ${renderVariableRows(visibleEntries, activeVariableFilter ? "No variables match this variable type." : "No variables yet.")}
        </div>
      </section>` : ""}
      ${activeTab === "rules" ? `
        <section class="playbook-section">
        <header class="playbook-section-header">
          <div>
            <h3>${t("Play rules")}</h3>
          </div>
          <div class="playbook-section-header-actions">
            <span>${enabledRuleCount}/${ruleCount}</span>
            <button class="small-button" type="button" data-action="add-play-rule">${t("Add preview rule")}</button>
          </div>
        </header>
        <div class="playbook-rule-grid">
          ${visibleRuleCards.length ? visibleRuleCards.map(renderPlaybookRuleCard).join("") : `<div class="nc-empty-state">${t("No play rules yet.")}</div>`}
        </div>
      </section>` : ""}
      ${activeTab === "validation" ? renderPlaybookValidationReport(stateReport, visibleValidationRows) : ""}
      ${renderDocumentLimitNotice("variables", shownCount, totalCount)}
      ${state.playbookJsonOpen ? `
        <label class="field json-field">
          <span>${t("Advanced JSON")}</span>
          <div class="playbook-json-frame">
            <textarea data-project-field="variables" data-playbook-json-version="${state.dirtyVersion}" rows="${getPlaybookJsonRows(playbookJson)}" spellcheck="false">${escapeHtml(playbookJson)}</textarea>
            <div class="playbook-json-highlight" data-playbook-json-highlight hidden></div>
          </div>
        </label>
      ` : ""}
    </div>
  `;
  runAfterRender(() => {
    const textarea = resizePlaybookJsonTextarea();
    restorePlaybookJsonSearchHighlight();
    if (options.focusJsonToken) focusPlaybookJsonToken(options.focusJsonToken, textarea);
    focusPendingPlaybookTarget();
  });
}

function renderPlaybookValueDatalists() {
  const stateKeys = getPlaybookStateKeySuggestions();
  const targets = getPlaybookTargetEntries();
  const values = ["True", "False", "0", "1", "{title}", "{body}", "{value}", "{protagonist}", "{route}"];
  return `
    <datalist id="playbookStateKeyOptions">
      ${stateKeys.map((value) => `<option value="${escapeAttr(value)}"></option>`).join("")}
    </datalist>
    <datalist id="playbookTargetOptions">
      ${targets.map((entry) => `<option value="${escapeAttr(entry.value)}" label="${escapeAttr([entry.label, entry.hint].filter(Boolean).join(" "))}"></option>`).join("")}
    </datalist>
    <datalist id="playbookValueOptions">
      ${values.map((value) => `<option value="${escapeAttr(value)}"></option>`).join("")}
    </datalist>
  `;
}

function renderScriptBuilderSection(scriptNodes, visibleScriptNodes) {
  return `
    <section class="playbook-section playbook-builder-section">
      <header class="playbook-section-header">
        <div>
          <h3>${t("Script Builder")}</h3>
          <p>${t("Batch-edit node requirements, node effects, and routing. For ordinary per-node logic, use this instead of Variable Actions.")}</p>
        </div>
        <span>${scriptNodes.length}</span>
      </header>
      <div class="script-node-table">
        <div class="script-node-row script-node-heading">
          <span>${t("Node")}</span>
          <span>${t("Node requirements")}</span>
          <span>${t("Node effects")}</span>
          <span>${t("Routing")}</span>
          <span>${t("Go to title")}</span>
          <span>JSON</span>
        </div>
        ${visibleScriptNodes.map(renderScriptNodeRow).join("") || `<div class="nc-empty-state">${t("No editable node logic yet.")}</div>`}
      </div>
    </section>
  `;
}

function renderPlaybookTabs(activeTab) {
  const tabs = [
    { id: "variables", label: "Variable Definitions" },
    { id: "actions", label: "Variable Actions" },
    { id: "script", label: "Script Builder" },
    { id: "gates", label: "Choice Conditions" },
    { id: "rules", label: "Play Rules" },
    { id: "validation", label: "Validation" }
  ];
  return `
    <div class="playbook-tabs" role="tablist" aria-label="${escapeAttr(t("Playbook sections"))}">
      ${tabs.map((tab) => `
        <button type="button" class="playbook-tab${activeTab === tab.id ? " active" : ""}" data-action="select-playbook-tab" data-playbook-tab="${escapeAttr(tab.id)}" aria-selected="${activeTab === tab.id}">
          ${escapeHtml(t(tab.label))}
        </button>
      `).join("")}
    </div>
  `;
}

function getPlaybookGateRows() {
  const rows = [];
  getScriptBuilderNodes().forEach((node) => {
    getGateChoiceOptions(node).forEach((option) => {
      rows.push({
        id: `choice:${node.id}:${option.id}`,
        kind: "choiceRequirement",
        typeLabel: "Choice requirement",
        targetLabel: `${node.title || getNodeDisplayId(node)} -> ${option.label}`,
        condition: option.requires || "",
        conditionMode: option.requiresMode || "all",
        effects: normalizeNodeEffects(option.effects),
        nodeId: node.id,
        choiceOptionId: option.id,
        legacyActionId: ""
      });
    });
  });
  getPlaybookActions()
    .filter((action) => action.trigger === "gate" && action.op === "if")
    .forEach((action) => {
      rows.push({
        id: `legacy:${action.id}`,
        kind: "legacy",
        typeLabel: "Legacy action",
        targetLabel: action.target || t("Any node"),
        condition: formatLegacyGateCondition(action),
        nodeId: "",
        legacyActionId: action.id
      });
    });
  return rows;
}

function getGateChoiceOptions(node) {
  if (Array.isArray(node?.choiceOptions) && node.choiceOptions.length) return normalizeChoiceOptions(node);
  return parseChoiceLines(node?.choices).map((label, index) => ({
    id: `index:${index}`,
    label,
    requires: "",
    requiresMode: "all",
    effects: []
  }));
}

function renderPlaybookGatesSection(gates, visibleGates) {
  return `
    <section class="playbook-section playbook-gates-section">
      <header class="playbook-section-header">
        <div>
          <h3>${t("Choice Conditions")}</h3>
          <p>${t("Choice Conditions batch-edit choice requirements. Legacy condition rows are shown here for compatibility.")}</p>
        </div>
        <span>${gates.length}</span>
      </header>
      <div class="playbook-gate-table">
        <div class="playbook-gate-row playbook-gate-heading">
          <span>${t("Option")}</span>
          <span>${t("Choice condition")}</span>
          <span>${t("On choose effects")}</span>
          <span>JSON</span>
        </div>
        ${visibleGates.length ? visibleGates.map(renderPlaybookGateRow).join("") : `<div class="nc-empty-state">${t("No choice conditions yet.")}</div>`}
      </div>
    </section>
  `;
}

function renderPlaybookGateRow(row) {
  return `
    <div class="playbook-gate-row" data-gate-id="${escapeAttr(row.id)}" data-gate-kind="${escapeAttr(row.kind)}">
      <button class="linked-node script-node-link" type="button" ${row.nodeId ? `data-action="focus-canvas-node" data-node-id="${escapeAttr(row.nodeId)}"` : "disabled"}>
        <strong>${escapeHtml(row.targetLabel)}</strong>
        ${row.choiceOptionId ? `<small>${escapeHtml(row.choiceOptionId)}</small>` : ""}
      </button>
      ${renderPlaybookGateConditionCell(row)}
      ${renderPlaybookGateEffectsCell(row)}
      ${renderPlaybookJsonButton(getPlaybookJsonPairToken("rowId", row.id))}
    </div>
  `;
}

function renderPlaybookGateConditionCell(row) {
  return `
    <div class="playbook-gate-condition">
      ${renderPlaybookConditionCodeCell({
        value: row.condition,
        attributes: row.kind === "legacy" ? "" : `data-gate-id="${escapeAttr(row.id)}" data-gate-field="condition"`,
        readonly: row.kind === "legacy"
      })}
    </div>
  `;
}

function renderPlaybookGateEffectsCell(row) {
  if (row.kind === "legacy") {
    return `
      <div class="playbook-gate-effects">
        ${renderPlaybookEffectsCodeCell({
          value: "",
          defaultTrigger: "onChoose",
          readonly: true
        })}
        <small>${escapeHtml(t("Legacy gates"))}</small>
      </div>
    `;
  }
  if (row.kind !== "choiceRequirement") {
    return `<div class="playbook-gate-effects">${renderPlaybookEffectsCodeCell({ value: "", defaultTrigger: "onChoose", readonly: true })}</div>`;
  }
  const effects = normalizeNodeEffects(row.effects);
  const effectsText = formatStateEffectsText(effects, { defaultTrigger: "onChoose" });
  return `
    <div class="playbook-gate-effects">
      ${renderPlaybookEffectsCodeCell({
        value: effectsText,
        defaultTrigger: "onChoose",
        attributes: `data-gate-id="${escapeAttr(row.id)}" data-gate-field="effects"`
      })}
    </div>
  `;
}

function getConditionEvaluationStatus(source, variables = state.project.variables) {
  const text = String(source || "").trim();
  if (!text) return { status: "always" };
  const normalizedVariables = normalizeVariablesObject(variables);
  const result = collectExpressionKeys(text, normalizedVariables);
  if (result.invalid) return { status: "invalid" };
  const unknown = result.keys.filter((key) => !resolveRuntimeStatePath(key, normalizedVariables).found);
  if (unknown.length) return { status: "unknown", key: unknown[0] };
  const parsed = parseJsConditionExpression(text);
  if (parsed.invalid) return { status: "invalid" };
  return { status: coerceBoolean(evaluateJsConditionAst(parsed.ast, normalizedVariables)) ? "pass" : "fail" };
}

function formatConditionEvaluationStatusLabel(status) {
  if (!status || status.status === "always") return t("Always available");
  if (status.status === "pass") return t("Demo run can meet this condition");
  if (status.status === "fail") return t("Requires demo run progress");
  if (status.status === "invalid") return t("Invalid expression");
  if (status.status === "unknown") return t("Unknown variable: {key}", { key: status.key });
  return "";
}

function normalizePlaybookEditorStatus(status) {
  if (!status || typeof status !== "object") return { status: "invalid", message: t("Invalid expression") };
  return {
    status: String(normalizeOptionalString(status.status)).trim().toLowerCase() || "invalid",
    message: normalizeOptionalString(status.message),
    key: normalizeOptionalString(status.key),
    count: Number.isFinite(Number(status.count)) ? Number(status.count) : 0,
    line: Number.isFinite(Number(status.line)) ? Number(status.line) : 0
  };
}

function getPlaybookCodeStatusClass(status) {
  const normalized = normalizePlaybookEditorStatus(status);
  return normalized.status === "ok" ? "pass" : normalized.status;
}

function formatPlaybookEditorStatusLabel(status) {
  const normalized = normalizePlaybookEditorStatus(status);
  if (normalized.message) return normalized.message;
  if (["always", "pass", "fail", "invalid", "unknown"].includes(normalized.status)) {
    return formatConditionEvaluationStatusLabel(normalized);
  }
  if (normalized.status === "ok") {
    return normalized.count === 1 ? t("Effect lines OK") : t("{count} effect lines OK", { count: normalized.count });
  }
  if (normalized.status === "empty") return t("No effects.");
  return "";
}

function getPlaybookEffectsTextStatus(value, options = {}) {
  return parsePlaybookEffectsText(value, options).status;
}

function parsePlaybookEffectsText(value, options = {}) {
  const defaultTrigger = normalizePlaybookActionTrigger(options.defaultTrigger || "onVisit");
  const forceTrigger = options.forceTrigger ? normalizePlaybookActionTrigger(options.forceTrigger) : "";
  const effects = [];
  const lines = String(value || "").split(/\r?\n/);
  for (let index = 0; index < lines.length; index += 1) {
    const rawLine = lines[index];
    const line = rawLine.trim();
    if (!line) continue;
    const parsed = parsePlaybookEffectLine(line, { defaultTrigger, forceTrigger });
    if (parsed.status.status !== "ok") {
      return {
        effects: [],
        status: {
          ...parsed.status,
          line: index + 1,
          message: t("Effect line {line}: {message}", { line: index + 1, message: parsed.status.message })
        }
      };
    }
    effects.push(parsed.effect);
  }
  return {
    effects,
    status: effects.length
      ? { status: "ok", count: effects.length }
      : { status: "none", message: t("No effects.") }
  };
}

function parsePlaybookEffectLine(line, { defaultTrigger = "onVisit", forceTrigger = "" } = {}) {
  const triggerMatch = line.match(/^\[(onVisit|onChoose|manual)\]\s*(.+)$/i);
  const trigger = forceTrigger || (triggerMatch ? normalizePlaybookActionTrigger(triggerMatch[1]) : normalizePlaybookActionTrigger(defaultTrigger));
  const body = triggerMatch ? triggerMatch[2].trim() : line;
  const conditional = parseConditionalEffectBody(body, trigger);
  if (conditional) {
    const conditionStatus = getConditionEvaluationStatus(conditional.condition, state.project.variables);
    if (conditionStatus.status === "invalid") {
      return { effect: null, status: { status: "invalid", message: conditionStatus.message || t("Invalid condition syntax") } };
    }
    for (const branch of [conditional.thenEffect, conditional.elseEffect]) {
      const validation = validateParsedStateEffect(branch);
      if (validation) return { effect: null, status: validation };
    }
    return { effect: conditional, status: { status: "ok" } };
  }
  const effect = parseStateEffectBody(body, trigger);
  if (!effect) {
    return { effect: null, status: { status: "invalid", message: t("Invalid effect syntax") } };
  }
  const validation = validateParsedStateEffect(effect);
  if (validation) return { effect: null, status: validation };
  return {
    effect: normalizeStateEffectForVariableSchema(effect, { coerceValue: false }),
    status: { status: "ok" }
  };
}

function validateParsedStateEffect(effect) {
  const key = normalizeOptionalString(effect?.key).trim();
  if (!key) return { status: "invalid", message: t("Effect key is required.") };
  const info = getVariableInfoForStateEffect(effect);
  if (!info.hasVariable) {
    return { status: "unknown", key, message: t("Unknown variable: {key}", { key }) };
  }
  const allowed = getAllowedPlaybookActionOperationsForVariableInfo(info);
  if (!allowed.some((option) => option.value === effect.op)) {
    return { status: "invalid", message: t("Operation not available for this variable type.") };
  }
  return null;
}

function parseStateEffectBody(body, trigger = "onVisit") {
  const match = normalizeOptionalString(body).trim().match(/^(set|add|subtract|append|remove|toggle|invert|clear)\s+([^\s=]+)(?:\s*=\s*(.*)|\s+(.+))?$/i);
  if (!match) return null;
  const value = normalizeOptionalString(match[3] ?? match[4] ?? "").trim();
  return {
    trigger: normalizePlaybookActionTrigger(trigger),
    op: normalizePlaybookEffectTextOperation(match[1]),
    key: normalizeOptionalString(match[2]).trim(),
    value,
    valueMode: getStateEffectValueMode(value)
  };
}

function parseConditionalEffectBody(body, trigger = "onVisit") {
  const match = normalizeOptionalString(body).trim().match(/^if\s+(.+?)\s+then\s+(.+?)\s+else\s+(.+)$/i);
  if (!match) return null;
  const thenEffect = parseStateEffectBody(match[2], trigger);
  const elseEffect = parseStateEffectBody(match[3], trigger);
  if (!thenEffect || !elseEffect) return null;
  return {
    trigger: normalizePlaybookActionTrigger(trigger),
    op: "ifElse",
    condition: match[1].trim(),
    thenEffect,
    elseEffect
  };
}

function getStateEffectValueMode(value) {
  const key = normalizeExpressionVariableTerm(value);
  if (!key) return "literal";
  return resolveRuntimeStatePath(key, state.project.variables).found ? "variable" : "literal";
}

function normalizePlaybookEffectTextOperation(value) {
  const op = normalizeOptionalString(value).trim().toLowerCase();
  if (op === "invert") return "toggle";
  return normalizePlaybookActionOperation(op);
}

function formatLegacyGateCondition(action) {
  const key = getPlaybookActionStateKey(action);
  const value = normalizeOptionalString(action?.value).trim();
  return `${key} ${value}`.trim();
}

function renderPlaybookActionsSection(actions, visibleActions) {
  return `
    <section class="playbook-section playbook-actions-section">
      <header class="playbook-section-header">
        <div>
          <h3>${t("Playbook variable actions")}</h3>
          <p>${t("Variable Actions write defined Variables outside node rows. Node-specific changes belong in Script Builder or the node inspector.")}</p>
        </div>
        <div class="playbook-section-header-actions">
          <span>${visibleActions.length}</span>
          <button class="small-button" type="button" data-action="show-playbook-action-draft">${t("Add variable action")}</button>
        </div>
      </header>
      <div class="playbook-action-table">
        <div class="playbook-action-row playbook-action-heading">
          <span>${t("Trigger")}</span>
          <span>${t("Target")}</span>
          <span>${t("Key")}</span>
          <span>${t("Operation")}</span>
          <span>${t("Value")}</span>
          <span>JSON</span>
          <span></span>
        </div>
        ${renderPlaybookActionDraftRow()}
        ${visibleActions.length ? visibleActions.map(renderPlaybookActionRow).join("") : (state.playbookActionDraftOpen ? "" : `<div class="nc-empty-state">${t("No variable actions yet.")}</div>`)}
      </div>
    </section>
  `;
}

function renderPlaybookValidationReport(report, visibleRows, activeFilter = "") {
  const rows = Array.isArray(visibleRows) ? visibleRows : [];
  return `
    <section class="playbook-section state-report-section">
      <header class="playbook-section-header">
        <div>
          <h3>${t("State validation")}</h3>
          <p>${t("Scan conditions, effects, templates, and export risks before playtesting or exporting.")}</p>
        </div>
        <span>${t("{count} state issues", { count: report.issueCount })}</span>
      </header>
      <div class="state-report-summary">
        ${renderStateReportSummaryMetric({
          primary: t("{count} state keys", { count: report.rows.length }),
          secondary: report.issueCount ? t("{count} state issues", { count: report.issueCount }) : t("No state issues found.")
        })}
        ${renderStateReportSummaryMetric({
          primary: t("{count} reads", { count: report.readCount }),
          secondary: t("{count} writes", { count: report.writeCount })
        })}
        ${renderStateReportSummaryMetric({
          primary: t("{count} templates", { count: report.interpolationCount }),
          secondary: t("Validation")
        })}
      </div>
      ${renderStateReportInvalidExpressions(report.invalidExpressions)}
      ${renderStateReportExportBlocks(report.exportBlocks)}
      <div class="state-report-table">
        ${rows.length ? rows.map(renderStateReportRow).join("") : `<div class="nc-empty-state">${t("No state references yet.")}</div>`}
      </div>
    </section>
  `;
}

function renderStateReportSummaryMetric({ primary, secondary }) {
  return `
    <div class="state-report-summary-metric">
      <strong>${escapeHtml(primary)}</strong>
      <span>${escapeHtml(secondary)}</span>
    </div>
  `;
}

function renderStateReportInvalidExpressions(refs) {
  if (!Array.isArray(refs) || !refs.length) return "";
  return `
    <div class="state-report-invalid">
      <strong>${escapeHtml(t("Invalid expression"))}</strong>
      <div class="state-report-ref-list">
        ${refs.slice(0, 8).map(renderStateReportReference).join("")}
        ${refs.length > 8 ? `<span class="state-report-more">${escapeHtml(t("More: {count}", { count: refs.length - 8 }))}</span>` : ""}
      </div>
    </div>
  `;
}

function renderStateReportExportBlocks(blocks) {
  if (!Array.isArray(blocks) || !blocks.length) return "";
  const visible = blocks.slice(0, 12);
  return `
    <div class="state-report-export-blocks">
      <strong>${escapeHtml(t("Export risk"))}</strong>
      <div class="state-report-export-list">
        ${visible.map((block) => `
          <article class="state-report-export-item">
            <code>${escapeHtml(block.code)}</code>
            <span>${escapeHtml(formatExportWarningMessage(block))}</span>
            ${renderStateReportReference(block)}
          </article>
        `).join("")}
        ${blocks.length > visible.length ? `<span class="state-report-more">${escapeHtml(t("More: {count}", { count: blocks.length - visible.length }))}</span>` : ""}
      </div>
    </div>
  `;
}

function renderStateReportRow(row) {
  return `
    <article class="state-report-card" data-state-key="${escapeAttr(row.key)}" data-state-status="${escapeAttr(row.primaryStatus)}">
      <header class="state-report-card-head">
        <div class="state-report-key">
          <code>${escapeHtml(row.key)}</code>
          <small>${escapeHtml(row.typeLabel)}</small>
        </div>
        <div class="state-report-status-list">
          ${row.statuses.map((status, index) => renderStateReportStatusBadge(row, status, index)).join("")}
          ${renderPlaybookJsonButton(getPlaybookJsonPairToken("rowId", `state:${row.key}`))}
        </div>
      </header>
      <div class="state-report-card-grid">
        ${renderStateReportValueBlock(t("Initial"), row.hasInitial ? `<code>${escapeHtml(formatStateReportValue(row.initialValue))}</code>` : `<span>${escapeHtml(t("No initial value"))}</span>`)}
        ${renderStateReportReferenceBlock(t("Read by"), row.reads)}
        ${renderStateReportReferenceBlock(t("Written by"), row.writes)}
        ${renderStateReportReferenceBlock(t("Interpolated by"), row.interpolations)}
      </div>
    </article>
  `;
}

function renderStateReportStatusBadge(row, status, index = 0) {
  const label = t(STATE_REPORT_STATUS_LABELS[status] || status);
  const base = `state-report-status state-report-status-${escapeAttr(status)}`;
  if (status === "ok") {
    return `<span class="${base}">${escapeHtml(label)}</span>`;
  }
  const tooltipId = `state-status-${slugPlaybookCategory(row?.key || "state")}-${slugPlaybookCategory(status)}-${index}`;
  const title = formatStateReportStatusTitle(row, status);
  return `
    <span class="state-report-status-wrap">
      <span class="${base}" tabindex="0" aria-describedby="${escapeAttr(tooltipId)}" title="${escapeAttr(title)}">${escapeHtml(label)}</span>
      <span class="state-report-status-tooltip state-report-status-tooltip-${escapeAttr(status)}" id="${escapeAttr(tooltipId)}" role="tooltip">
        ${status === "export-blocked" ? renderStateReportExportRiskTooltip(row) : renderStateReportStatusTooltip(row, status)}
      </span>
    </span>
  `;
}

function renderStateReportStatusTooltip(row, status) {
  const detail = getStateReportStatusDetail(row, status);
  return `
    <strong>${escapeHtml(detail.title)}</strong>
    <span class="state-report-risk-summary">${escapeHtml(detail.body)}</span>
    <span class="state-report-risk-detail">
      <em>${escapeHtml(detail.hint)}</em>
    </span>
  `;
}

function formatStateReportStatusTitle(row, status) {
  if (status === "export-blocked") return formatStateReportExportRiskTitle(row);
  const detail = getStateReportStatusDetail(row, status);
  return [detail.title, detail.body, detail.hint].join("\n");
}

function getStateReportStatusDetail(row, status) {
  switch (status) {
    case "unknown-key":
      return {
        title: t("Unknown key details"),
        body: t("This key is used by a condition or template, but it has no initial value and no known write in the current project."),
        hint: t("Fix hint: add this key to Variables, correct the spelling, or add an effect that writes it before it is read.")
      };
    case "read-only":
      return {
        title: t("Read-only details"),
        body: t("This key is read by a condition, template, or export, but the project does not initialize it."),
        hint: t("Fix hint: add an initial value in Variables, or document that the target runtime will provide it.")
      };
    case "written-only":
      return {
        title: t("Written-only details"),
        body: t("This key is written by effects or actions, but nothing in the current project reads it."),
        hint: t("Fix hint: keep it only if the target runtime reads it; otherwise remove it or correct the key name.")
      };
    case "object-unreadable":
      return {
        title: t("Object value details"),
        body: t("This key contains an object or complex value. Runtime JSON can keep it, but conditions, templates, Yarn, and Ink usually need simpler state."),
        hint: t("Fix hint: split the object into flat keys, or use supported list checks such as array_key.includes(value) for arrays.")
      };
    case "template-mismatch":
      return {
        title: t("Template mismatch details"),
        body: t("A text template references this key, but it does not match a node field or variable. The placeholder may remain unresolved."),
        hint: t("Fix hint: add the variable, rename the placeholder, or use an existing node field name.")
      };
    case "invalid-expression":
      return {
        title: t("Expression error details"),
        body: t("A condition related to this key cannot be parsed. The route or option check may not behave as intended."),
        hint: t("Fix hint: use JavaScript comparisons, && / ||, parentheses, array_key.includes(value), or a bare boolean key.")
      };
    default:
      return {
        title: t("Status details"),
        body: t(STATE_REPORT_STATUS_LABELS[status] || status),
        hint: t("Review the export report before handing files to an engine.")
      };
  }
}

function renderStateReportExportRiskTooltip(row) {
  const blocks = Array.isArray(row?.exportBlocks) ? row.exportBlocks : [];
  const visible = blocks.slice(0, 4);
  const items = visible.length
    ? visible.map((block) => `
      <span class="state-report-risk-detail">
        <span>${escapeHtml(formatExportWarningMessage(block))}</span>
        ${block.label ? `<small>${escapeHtml(block.label)}</small>` : ""}
        <em>${escapeHtml(getStateReportExportRiskFixHint(block))}</em>
      </span>
    `).join("")
    : `<span class="state-report-risk-detail"><span>${escapeHtml(t("No detailed export warning was attached to this key. Review the export report before handing files to an engine."))}</span></span>`;
  const more = blocks.length > visible.length
    ? `<span class="state-report-risk-more">${escapeHtml(t("More: {count}", { count: blocks.length - visible.length }))}</span>`
    : "";
  return `
    <strong>${escapeHtml(t("Export risk details"))}</strong>
    <span class="state-report-risk-summary">${escapeHtml(t("Runtime JSON keeps the richest data. Yarn, Ink, and Twee may rename this state, comment it out, or need custom runtime handling."))}</span>
    ${items}
    ${more}
  `;
}

function formatStateReportExportRiskTitle(row) {
  const blocks = Array.isArray(row?.exportBlocks) ? row.exportBlocks : [];
  const lines = [
    t("Export risk details"),
    t("Runtime JSON keeps the richest data. Yarn, Ink, and Twee may rename this state, comment it out, or need custom runtime handling.")
  ];
  if (!blocks.length) {
    lines.push(t("No detailed export warning was attached to this key. Review the export report before handing files to an engine."));
    return lines.join("\n");
  }
  blocks.slice(0, 4).forEach((block) => {
    lines.push(formatExportWarningMessage(block));
    lines.push(getStateReportExportRiskFixHint(block));
  });
  if (blocks.length > 4) lines.push(t("More: {count}", { count: blocks.length - 4 }));
  return lines.join("\n");
}

function getStateReportExportRiskFixHint(block) {
  const code = String(block?.code || "");
  if (code === "effect-op-runtime-only") return t("Fix hint: use set/add/subtract/toggle for text exports, or handle this operation in your runtime.");
  if (code === "custom-node-type-runtime-only") return t("Fix hint: use Runtime JSON with a custom loader, or change this node to a default node type before text export.");
  if (code === "complex-variable") return t("Fix hint: flatten this value into simple variables if Yarn or Ink needs to read it.");
  if (code === "state-key-name-sanitized" || code === "state-path-flattened") return t("Fix hint: use the exported name in the target format, or rename the state key with underscores before exporting.");
  if (code === "implicit-variable") return t("Fix hint: add this key to Variables with a starting value.");
  if (code === "playbook-action-runtime-only" || code === "playbook-actions-runtime-only") return t("Fix hint: move this into node or choice effects for text export, or implement the action in your runtime.");
  if (code === "expression-not-translated") return t("Fix hint: check this expression in the target engine, or rewrite it as a simpler supported comparison.");
  if (code === "variable-name-sanitized" || code === "variable-name-collision" || code === "node-name-sanitized" || code === "node-name-collision") return t("Fix hint: use the exported name in the target format.");
  return t("Review the export report before handing files to an engine.");
}

function renderStateReportValueBlock(label, body) {
  return `
    <section class="state-report-card-block state-report-initial">
      <h4>${escapeHtml(label)}</h4>
      <div>${body}</div>
    </section>
  `;
}

function renderStateReportReferenceBlock(label, refs) {
  return `
    <section class="state-report-card-block">
      <h4>${escapeHtml(label)}</h4>
      ${renderStateReportReferenceList(refs)}
    </section>
  `;
}

function renderStateReportReferenceList(refs) {
  const visible = (Array.isArray(refs) ? refs : []).slice(0, 3);
  const remaining = Math.max((refs?.length || 0) - visible.length, 0);
  if (!visible.length) return `<div class="state-report-ref-list"><span class="state-report-empty">${escapeHtml(t("No references"))}</span></div>`;
  return `
    <div class="state-report-ref-list">
      ${visible.map(renderStateReportReference).join("")}
      ${remaining ? `<span class="state-report-more">${escapeHtml(t("More: {count}", { count: remaining }))}</span>` : ""}
    </div>
  `;
}

function renderStateReportReference(ref) {
  const label = ref?.label || "Reference";
  const labelAttr = escapeAttr(label);
  const labelText = escapeHtml(label);
  if (ref?.nodeId) {
    return `
      <button class="state-report-ref" type="button" data-action="focus-canvas-node" data-node-id="${escapeAttr(ref.nodeId)}" title="${labelAttr}">
        ${labelText}
      </button>
    `;
  }
  if (ref?.jsonToken) {
    return `
      <button class="state-report-ref" type="button" data-action="focus-playbook-json" data-playbook-token="${escapeAttr(JSON.stringify(ref.jsonToken))}" title="${labelAttr}">
        ${labelText}
      </button>
    `;
  }
  return `<span class="state-report-ref state-report-ref-static" title="${labelAttr}">${labelText}</span>`;
}

function formatStateReportValue(value) {
  const text = formatVariableValue(value);
  return text.length > 64 ? `${text.slice(0, 61)}...` : text;
}

function buildStateReport() {
  const variables = normalizeVariablesObject(state.project.variables);
  const rowsByKey = new Map();
  const invalidExpressions = [];
  const exportBlocks = [];
  const exportBlockIds = new Set();
  const ensureRow = (key) => {
    const normalizedKey = normalizeStateReportKey(key);
    if (!normalizedKey) return null;
    if (!rowsByKey.has(normalizedKey)) {
      rowsByKey.set(normalizedKey, {
        key: normalizedKey,
        hasInitial: Object.prototype.hasOwnProperty.call(variables, normalizedKey),
        initialValue: variables[normalizedKey],
        typeLabel: Object.prototype.hasOwnProperty.call(variables, normalizedKey) ? variableType(variables[normalizedKey]) : "implicit",
        reads: [],
        writes: [],
        interpolations: [],
        statusSet: new Set(),
        refIds: new Set()
      });
    }
    return rowsByKey.get(normalizedKey);
  };
  const addRef = (key, bucket, ref) => {
    const row = ensureRow(key);
    if (!row) return null;
    const normalized = normalizeStateReportRef(ref);
    const id = `${bucket}:${row.key}:${normalized.label}:${normalized.nodeId || ""}:${normalized.jsonToken || ""}`;
    if (!row.refIds.has(id)) {
      row.refIds.add(id);
      row[bucket].push(normalized);
    }
    return row;
  };
  const addRead = (key, ref) => addRef(key, "reads", ref);
  const addWrite = (key, ref) => addRef(key, "writes", ref);
  const addInterpolation = (key, ref) => addRef(key, "interpolations", ref);
  const addStatus = (key, status) => {
    const row = ensureRow(key);
    if (row) row.statusSet.add(status);
  };
  const addExportBlock = (block) => {
    const normalized = normalizeStateReportExportBlock(block);
    if (!normalized.code || !normalized.message) return;
    const id = [normalized.code, normalized.message, normalized.key, normalized.nodeId, normalized.jsonToken].join("|");
    if (exportBlockIds.has(id)) return;
    exportBlockIds.add(id);
    exportBlocks.push(normalized);
    if (normalized.key) addStatus(normalized.key, "export-blocked");
  };
  const addInvalidExpression = (source, ref) => {
    invalidExpressions.push(normalizeStateReportRef({
      ...ref,
      label: `${ref?.label || "Expression"}: ${String(source || "").trim()}`
    }));
  };
  const scanExpression = (source, node, ref) => {
    const raw = normalizeOptionalString(source).trim();
    if (!raw) return;
    scanTemplateReferences(raw, node, { ...ref, label: `${ref?.label || "Expression"} template` }, addInterpolation, addStatus);
    const expression = normalizeExpressionForStateReport(raw, node, variables);
    const result = collectExpressionKeys(expression, variables);
    if (result.invalid) {
      addInvalidExpression(raw, ref);
      return;
    }
    const membershipKeys = new Set(result.membershipKeys || []);
    result.keys.forEach((key) => {
      const row = addRead(key, ref);
      const resolved = resolveRuntimeStatePath(key, variables);
      if (row && resolved.found && isComplexRuntimeValue(resolved.value) && !membershipKeys.has(key)) row.statusSet.add("object-unreadable");
    });
  };
  const scanEffectValue = (effect, node, ref) => {
    if (!effect || effect.op === "clear") return;
    scanTemplateReferences(effect.value, node, { ...ref, label: `${ref?.label || "Effect"} value` }, addInterpolation, addStatus);
    if (effect.valueMode === "variable") addRead(normalizeExpressionVariableTerm(effect.value), { ...ref, label: `${ref?.label || "Effect"} value` });
  };
  const scanStateEffect = (effect, node, ref) => {
    if (!effect) return;
    if (effect.op === "ifElse") {
      scanExpression(effect.condition, node, { ...ref, label: `${ref?.label || "Effect"} condition` });
      scanStateEffect(effect.thenEffect, node, { ...ref, label: `${ref?.label || "Effect"} then` });
      scanStateEffect(effect.elseEffect, node, { ...ref, label: `${ref?.label || "Effect"} else` });
      return;
    }
    const key = normalizeStateReportKey(effect.key);
    if (key) {
      addWrite(key, ref);
      if (["add", "subtract", "remove", "toggle"].includes(effect.op)) addRead(key, ref);
      if (isRuntimeOnlyEffectOperation(effect.op)) {
        addExportBlock({
          code: "effect-op-runtime-only",
          key,
          nodeId: ref?.nodeId || "",
          label: ref?.label || key,
          message: `Effect "${effect.op}" on "${key}" is kept in runtime JSON but commented in Yarn, Ink, and Twee.`
        });
      }
    }
    scanEffectValue(effect, node, ref);
  };

  Object.keys(variables).forEach(ensureRow);

  getRuntimeExportableNodes().forEach((node) => {
    const nodeLabel = getStateReportNodeLabel(node);
    const script = getNodeRuntimeScript(node);
    if (isCustomRuntimeNodeType(node.type) && !hasExplicitRuntimeScript(script)) {
      addExportBlock({
        code: "custom-node-type-runtime-only",
        nodeId: node.id,
        label: `${nodeLabel} custom type`,
        message: `Custom node type "${getNodeTypeLabel(node.type)}" exports as rendered text and custom fields; target formats may need a custom loader.`
      });
    }
    const logic = normalizeNodeStateLogic(node.stateLogic);
    scanExpression(logic.requirements, node, { label: `${nodeLabel} requirement`, nodeId: node.id });
    const gateAction = getPlaybookGateAction(node);
    if (gateAction) {
      addRead(getPlaybookActionStateKey(gateAction), { label: `${nodeLabel} gate`, nodeId: node.id, jsonToken: gateAction.id });
      scanTemplateReferences(gateAction.value, node, { label: `${nodeLabel} gate value`, nodeId: node.id, jsonToken: gateAction.id }, addInterpolation, addStatus);
    }
    logic.effects.forEach((effect, index) => scanStateEffect(effect, node, { label: `${nodeLabel} effect ${index + 1}`, nodeId: node.id }));

    scanTemplateReferences(script.title || node.title, node, { label: `${nodeLabel} title`, nodeId: node.id }, addInterpolation, addStatus);
    scanTemplateReferences(script.body || displayBody(node), node, { label: `${nodeLabel} body`, nodeId: node.id }, addInterpolation, addStatus);
    if (isDialogNode(node) && Array.isArray(node.turns)) {
      node.turns.forEach((turn, index) => {
        scanTemplateReferences(turn.speaker, node, { label: `${nodeLabel} speaker ${index + 1}`, nodeId: node.id }, addInterpolation, addStatus);
        scanTemplateReferences(turn.line, node, { label: `${nodeLabel} line ${index + 1}`, nodeId: node.id }, addInterpolation, addStatus);
      });
    }
    getNodeCustomFieldEntries(node).forEach((field) => {
      scanTemplateReferences(field.value, node, { label: `${nodeLabel} ${field.label}`, nodeId: node.id }, addInterpolation, addStatus);
    });
    (Array.isArray(node.choiceOptions) ? node.choiceOptions : []).forEach((option, optionIndex) => {
      const optionLabel = option.label || `Choice ${optionIndex + 1}`;
      scanTemplateReferences(option.label, node, { label: `${nodeLabel} choice "${optionLabel}"`, nodeId: node.id }, addInterpolation, addStatus);
      scanExpression(option.requires, node, { label: `${nodeLabel} choice "${optionLabel}"`, nodeId: node.id });
      (Array.isArray(option.effects) ? option.effects : []).forEach((effect, effectIndex) => {
        scanStateEffect(effect, node, { label: `${nodeLabel} choice effect ${effectIndex + 1}`, nodeId: node.id });
      });
    });
  });

  (Array.isArray(state.project.links) ? state.project.links : []).forEach((link) => {
    const fromNode = getNode(link.from);
    const label = fromNode ? `${getStateReportNodeLabel(fromNode)} link` : `Link ${link.id || ""}`.trim();
    scanExpression(link.requirements || link.requires, fromNode, { label, nodeId: fromNode?.id || "" });
  });

  const rules = getRunnerRules();
  if (rules.endCondition?.enabled) {
    scanExpression(rules.endCondition.value, null, { label: "End Condition", jsonToken: "endCondition" });
  }
  getPlaybookActions().forEach((action) => {
    const key = getPlaybookActionStateKey(action);
    const ref = { label: `Script action ${action.id || ""}`.trim(), jsonToken: action.id };
    if (isPlaybookActionRuntimeOnlyForPortableExport(action)) {
      addExportBlock({
        code: "playbook-action-runtime-only",
        key,
        label: ref.label,
        jsonToken: action.id,
        message: `Playbook action "${action.id || action.op}" (${action.trigger}/${action.op}) is kept in runtime JSON but not emitted to Yarn, Ink, or Twee.`
      });
    }
    if (action.trigger === "gate" || action.op === "if") {
      addRead(key, ref);
      scanTemplateReferences(action.value, null, { ...ref, label: `${ref.label} value` }, addInterpolation, addStatus);
    } else if (["set", "add", "subtract", "append", "remove", "toggle", "clear"].includes(action.op)) {
      addWrite(key, ref);
      if (["add", "subtract", "remove", "toggle"].includes(action.op)) addRead(key, ref);
      scanTemplateReferences(action.value, null, { ...ref, label: `${ref.label} value` }, addInterpolation, addStatus);
    } else if (key) {
      addStatus(key, "export-blocked");
    }
    if (key && key.includes(".")) addStatus(key, "export-blocked");
  });

  rowsByKey.forEach((row) => {
    const resolvedInitial = resolveRuntimeStatePath(row.key, variables);
    row.hasInitial = resolvedInitial.found;
    row.initialValue = resolvedInitial.value;
    row.typeLabel = row.hasInitial ? variableType(row.initialValue) : "implicit";
    if (row.hasInitial && isComplexRuntimeValue(row.initialValue)) {
      if (Array.isArray(row.initialValue)) {
        if (row.interpolations.length) row.statusSet.add("object-unreadable");
      } else {
        addExportBlock({
          code: "complex-variable",
          key: row.key,
          label: row.key,
          message: `Variable "${row.key}" is an object; runtime JSON keeps it, Twee initializes it, and Yarn/Ink comment it out.`
        });
        if (row.reads.length || row.interpolations.length) row.statusSet.add("object-unreadable");
      }
    }
    if (row.key.includes(".")) {
      addExportBlock({
        code: "state-key-name-sanitized",
        key: row.key,
        label: row.key,
        message: `State key "${row.key}" exports with "." converted to "_" in portable text formats.`
      });
    }
    if (!row.hasInitial && row.reads.length && !row.writes.length) row.statusSet.add("read-only");
    if (!row.hasInitial && (row.reads.length || row.interpolations.length) && !row.writes.length) row.statusSet.add("unknown-key");
    if (row.writes.length && !row.reads.length && !row.interpolations.length) row.statusSet.add("written-only");
    if (!row.statusSet.size) row.statusSet.add("ok");
  });

  const filteredExportBlocks = exportBlocks.filter((block) => !isTransientVisitStateKey(block.key));
  const exportBlocksByKey = new Map();
  filteredExportBlocks.forEach((block) => {
    if (!block.key) return;
    const blocks = exportBlocksByKey.get(block.key) || [];
    blocks.push(block);
    exportBlocksByKey.set(block.key, blocks);
  });

  const rows = [...rowsByKey.values()]
    .filter((row) => !shouldOmitTransientVisitStateRow(row))
    .map((row) => ({
      ...row,
      statuses: sortStateReportStatuses([...row.statusSet]),
      primaryStatus: sortStateReportStatuses([...row.statusSet])[0] || "ok",
      exportBlocks: exportBlocksByKey.get(row.key) || []
    }))
    .sort(compareStateReportRows);
  const issueCount = rows.reduce((sum, row) => sum + row.statuses.filter((status) => status !== "ok").length, 0) + invalidExpressions.length;
  return {
    rows,
    invalidExpressions,
    exportBlocks: filteredExportBlocks,
    issueCount,
    readCount: rows.reduce((sum, row) => sum + row.reads.length, 0),
    writeCount: rows.reduce((sum, row) => sum + row.writes.length, 0),
    interpolationCount: rows.reduce((sum, row) => sum + row.interpolations.length, 0)
  };
}

function normalizeStateReportKey(key) {
  return normalizeOptionalString(key).trim();
}

function isTransientVisitStateKey(key) {
  return /^visited\.[a-z0-9_]+$/i.test(normalizeStateReportKey(key));
}

function shouldOmitTransientVisitStateRow(row) {
  return isTransientVisitStateKey(row?.key)
    && !row.hasInitial
    && !row.writes.length
    && !row.interpolations.length;
}

function normalizeStateReportRef(ref = {}) {
  return {
    label: normalizeOptionalString(ref.label).trim() || "Reference",
    nodeId: normalizeOptionalString(ref.nodeId).trim(),
    jsonToken: ref.jsonToken == null ? "" : String(ref.jsonToken)
  };
}

function normalizeStateReportExportBlock(block = {}) {
  const ref = normalizeStateReportRef(block);
  return {
    code: normalizeOptionalString(block.code).trim(),
    message: normalizeOptionalString(block.message).trim(),
    key: normalizeStateReportKey(block.key),
    label: ref.label,
    nodeId: ref.nodeId,
    jsonToken: ref.jsonToken
  };
}

function getStateReportNodeLabel(node) {
  if (!node) return "Node";
  return `${node.title || getNodeTypeLabel(node.type)} (${getNodeDisplayId(node)})`;
}

function isRuntimeOnlyEffectOperation(op) {
  return !["set", "add", "subtract", "toggle", "ifElse"].includes(op || "set");
}

function isPlaybookActionRuntimeOnlyForPortableExport(action) {
  if (!action || (!action.id && !action.trigger && !action.op)) return false;
  if (isPortableChoiceGateAction(action) && findPlaybookChoiceActionMatches(action).length) return false;
  return true;
}

function isPortableChoiceGateAction(action) {
  return action?.trigger === "gate" && (action.op === "lockChoice" || action.op === "unlockChoice");
}

function findPlaybookChoiceActionMatches(action) {
  if (!isPortableChoiceGateAction(action)) return [];
  return getRuntimeExportableNodes().flatMap((node) => {
    if (!matchesPlaybookActionTarget(action, node)) return [];
    const options = Array.isArray(node.choiceOptions) ? node.choiceOptions : [];
    return options
      .filter((option) => playbookChoiceActionMatchesOption(action, option, option.label))
      .map((option) => ({ node, option }));
  });
}

function isCustomRuntimeNodeType(type) {
  const value = normalizeOptionalString(type).trim();
  if (!value) return false;
  return !Object.prototype.hasOwnProperty.call(nodeTypes, value) || Boolean(getNodeMeta(value).custom);
}

function hasExplicitRuntimeScript(script) {
  if (!script || typeof script !== "object" || Array.isArray(script)) return false;
  return Object.values(script).some((value) => {
    if (Array.isArray(value)) return value.length > 0;
    if (value && typeof value === "object") return Object.keys(value).length > 0;
    return normalizeOptionalString(value).trim() !== "";
  });
}

function scanTemplateReferences(source, node, ref, addInterpolation, addStatus, depth = 0) {
  if (depth > 4) return;
  collectTemplateReferences(source).forEach((entry) => {
    const resolved = resolveRuntimeTemplateReference(node, entry.key, normalizeVariablesObject(state.project.variables));
    if (resolved.kind === "variable") {
      addInterpolation(resolved.key, { ...ref, label: `${ref?.label || "Template"} {${entry.key}}` });
      if (isComplexRuntimeValue(resolved.value)) addStatus(resolved.key, "object-unreadable");
      return;
    }
    if (resolved.kind === "nodeField") {
      scanTemplateReferences(resolved.value, node, ref, addInterpolation, addStatus, depth + 1);
      return;
    }
    const key = normalizeStateReportKey(entry.key.startsWith("variables.") ? entry.key.slice("variables.".length) : entry.key);
    if (key) {
      addInterpolation(key, { ...ref, label: `${ref?.label || "Template"} {${entry.key}}` });
      addStatus(key, "template-mismatch");
    }
  });
}

function collectTemplateReferences(source) {
  const refs = [];
  String(source || "").replace(/\{([a-zA-Z_][\w.-]*)\}/g, (match, key) => {
    refs.push({ key });
    return match;
  });
  return refs;
}

function resolveRuntimeTemplateReference(node, key, variables) {
  const raw = normalizeOptionalString(key).trim();
  if (!raw) return { kind: "missing", key: "" };
  if (raw.startsWith("variables.")) {
    const variableKey = raw.slice("variables.".length);
    const resolved = resolveRuntimeStatePath(variableKey, variables);
    return resolved.found
      ? { kind: "variable", key: variableKey, value: resolved.value }
      : { kind: "missing", key: variableKey };
  }
  const nodeValue = getNodeFieldValue(node, raw);
  if (nodeValue !== "") return { kind: "nodeField", key: raw, value: nodeValue };
  const resolved = resolveRuntimeStatePath(raw, variables);
  if (resolved.found) return { kind: "variable", key: raw, value: resolved.value };
  return { kind: "missing", key: raw };
}

function normalizeExpressionForStateReport(source, node, variables) {
  return String(source || "").replace(/\{([a-zA-Z_][\w.-]*)\}/g, (match, key) => {
    const resolved = resolveRuntimeTemplateReference(node, key, variables);
    if (resolved.kind === "variable") return resolved.key;
    if (resolved.kind === "nodeField") return resolved.value;
    return key.startsWith("variables.") ? key.slice("variables.".length) : key;
  });
}

function sortStateReportStatuses(statuses) {
  const order = ["invalid-expression", "template-mismatch", "unknown-key", "object-unreadable", "export-blocked", "read-only", "written-only", "ok"];
  return statuses.sort((a, b) => order.indexOf(a) - order.indexOf(b));
}

function compareStateReportRows(a, b) {
  const issueA = a.statuses.some((status) => status !== "ok") ? 0 : 1;
  const issueB = b.statuses.some((status) => status !== "ok") ? 0 : 1;
  if (issueA !== issueB) return issueA - issueB;
  return a.key.localeCompare(b.key);
}

function getVariableDefinitionFilterOptions(entries) {
  const counts = createVariableTypeFilterCounts();
  entries.forEach((entry) => {
    const filterKey = getVariableDefinitionFilterKey(entry[1]);
    counts.set(filterKey, (counts.get(filterKey) || 0) + 1);
  });
  return formatVariableTypeFilterOptions(counts);
}

function getVariableDefinitionFilterKey(value) {
  return getActionVariableType(value);
}

function createVariableTypeFilterCounts() {
  return new Map([
    ["string", 0],
    ["number", 0],
    ["boolean", 0],
    ["array", 0],
    ["object", 0],
    ["legacy", 0]
  ]);
}

function formatVariableTypeFilterOptions(counts) {
  return [
    { value: "string", label: "String", count: counts.get("string") || 0 },
    { value: "number", label: "Number", count: counts.get("number") || 0 },
    { value: "boolean", label: "Boolean", count: counts.get("boolean") || 0 },
    { value: "array", label: "Array", count: counts.get("array") || 0 },
    { value: "object", label: "Object", count: counts.get("object") || 0 },
    { value: "legacy", label: "Legacy / missing", count: counts.get("legacy") || 0 }
  ];
}

function renderPlaybookCategoryStrip(items, options = {}) {
  const activeFilter = state.playbookCategoryFilter;
  const filters = options.filters || [];
  const total = Number.isFinite(options.total) ? options.total : items.length;
  return `
    <div class="playbook-category-strip" role="group" aria-label="${escapeAttr(t("Variable type"))}">
      <button type="button" class="playbook-category-chip${!activeFilter ? " is-active" : ""}" data-action="filter-playbook-category" data-playbook-category="" aria-pressed="${!activeFilter}">
        <span>${t("All")}</span>
        <strong>${total}</strong>
      </button>
      ${filters.map((filter) => `
        <button type="button" class="playbook-category-chip${activeFilter === filter.value ? " is-active" : ""}" data-action="filter-playbook-category" data-playbook-category="${escapeAttr(filter.value)}" aria-pressed="${activeFilter === filter.value}">
          <span>${escapeHtml(t(filter.label))}</span>
          <strong>${filter.count}</strong>
        </button>
      `).join("")}
    </div>
  `;
}

function getPlaybookActionVariableInfo(action) {
  const stateKey = getPlaybookActionStateKey(action);
  const variables = normalizeVariablesObject(state.project.variables);
  const hasVariable = Boolean(stateKey) && Object.prototype.hasOwnProperty.call(variables, stateKey);
  const value = hasVariable ? variables[stateKey] : undefined;
  const type = hasVariable ? getActionVariableType(value) : "missing";
  return {
    stateKey,
    hasVariable,
    value,
    type,
    filterKey: hasVariable ? type : "legacy",
    typeLabel: getActionVariableTypeLabel(type)
  };
}

function getActionVariableType(value) {
  if (Array.isArray(value)) return "array";
  if (value && typeof value === "object") return "object";
  return variableType(value);
}

function getActionVariableTypeLabel(type) {
  const labels = {
    string: "String",
    number: "Number",
    boolean: "Boolean",
    array: "Array",
    object: "Object",
    missing: "Missing variable"
  };
  return labels[type] || "Missing variable";
}

function getAllowedPlaybookActionOperationsForVariableInfo(info) {
  if (!info?.hasVariable) return [];
  const valuesByType = {
    string: ["set"],
    number: ["set", "add", "subtract"],
    boolean: ["set", "toggle"],
    array: ["set", "append", "remove"],
    object: ["set"]
  };
  const values = valuesByType[info.type] || ["set"];
  return PLAYBOOK_ACTION_OPERATIONS.filter((option) => values.includes(option.value));
}

function getDefaultPlaybookActionValueForVariableInfo(info) {
  if (!info?.hasVariable) return "";
  if (info.type === "number") return "1";
  if (info.type === "boolean") return "true";
  if (info.type === "array") return "";
  if (info.type === "object") return "{}";
  return "";
}

function playbookActionUsesValue(op) {
  return !["toggle", "clear"].includes(op || "set");
}

function parsePlaybookActionJsonValue(value, fallback, validator) {
  try {
    const parsed = JSON.parse(value || JSON.stringify(fallback));
    return validator(parsed) ? parsed : fallback;
  } catch (error) {
    return fallback;
  }
}

function normalizePlaybookActionValueForVariableInfo(value, info, op) {
  if (!info?.hasVariable || !playbookActionUsesValue(op)) return "";
  const text = normalizeOptionalString(value);
  if (info.type === "number") {
    const parsed = Number(text);
    return Number.isFinite(parsed) ? String(parsed) : getDefaultPlaybookActionValueForVariableInfo(info);
  }
  if (info.type === "boolean") return coerceBoolean(text) ? "true" : "false";
  if (info.type === "array" && op === "set") {
    return JSON.stringify(parsePlaybookActionJsonValue(text, [], Array.isArray));
  }
  if (info.type === "object" && op === "set") {
    const parsed = parsePlaybookActionJsonValue(text, {}, (item) => item && typeof item === "object" && !Array.isArray(item));
    return JSON.stringify(parsed);
  }
  return text;
}

function renderPlaybookActionValueField({ attributes = "", value = "", variableInfo, op = "set", disabled = false } = {}) {
  const valueDisabled = disabled || !variableInfo?.hasVariable || !playbookActionUsesValue(op);
  const disabledAttr = valueDisabled ? "disabled" : "";
  const selectedValue = normalizePlaybookActionValueForVariableInfo(value, variableInfo, op);
  if (valueDisabled) {
    return `<input ${attributes} value="" placeholder="${escapeAttr(t("Value"))}" aria-label="${escapeAttr(t("Value"))}" disabled>`;
  }
  if (variableInfo.type === "boolean" && op === "set") {
    return `
      <select ${attributes} aria-label="${escapeAttr(t("Value"))}">
        <option value="true" ${selectedValue === "true" ? "selected" : ""}>true</option>
        <option value="false" ${selectedValue === "false" ? "selected" : ""}>false</option>
      </select>
    `;
  }
  if (variableInfo.type === "number") {
    return `<input ${attributes} type="number" step="any" inputmode="decimal" value="${escapeAttr(selectedValue)}" placeholder="${escapeAttr(t("Value"))}" spellcheck="false" ${disabledAttr}>`;
  }
  if (variableInfo.type === "array" && op === "set") {
    return `<input ${attributes} value="${escapeAttr(selectedValue || "[]")}" placeholder="[]" spellcheck="false" ${disabledAttr}>`;
  }
  if (variableInfo.type === "object" && op === "set") {
    return `<input ${attributes} value="${escapeAttr(selectedValue || "{}")}" placeholder="{}" spellcheck="false" ${disabledAttr}>`;
  }
  return `<input ${attributes} value="${escapeAttr(selectedValue)}" placeholder="${escapeAttr(t("Value"))}" spellcheck="false" ${disabledAttr}>`;
}

function getVariableInfoForStateEffect(effectOrKey) {
  const key = typeof effectOrKey === "string" ? effectOrKey : effectOrKey?.key;
  return getPlaybookActionVariableInfo({ category: "Variable", key: normalizeOptionalString(key).trim() });
}

function getEffectOperationOptions(key, selectedOp = "set") {
  const variableInfo = getVariableInfoForStateEffect(key);
  const allowedOperations = getAllowedPlaybookActionOperationsForVariableInfo(variableInfo);
  const requestedOp = normalizePlaybookActionOperation(selectedOp || "set");
  const op = allowedOperations.some((option) => option.value === requestedOp)
    ? requestedOp
    : (allowedOperations[0]?.value || "set");
  return { variableInfo, allowedOperations, op };
}

function renderEffectOperationOptions(key, selectedOp = "set") {
  const { allowedOperations, op } = getEffectOperationOptions(key, selectedOp);
  if (!allowedOperations.length) return `<option value="">${escapeHtml(t("Operation"))}</option>`;
  return renderPlaybookOptionList(allowedOperations, op);
}

function normalizeStateEffectForVariableSchema(effect, options = {}) {
  const action = {
    id: "effect",
    trigger: normalizePlaybookActionTrigger(effect?.trigger || "onVisit"),
    target: "",
    op: normalizePlaybookActionOperation(effect?.op || "set"),
    category: "Variable",
    key: normalizeOptionalString(effect?.key).trim(),
    value: normalizeOptionalString(effect?.value)
  };
  normalizePlaybookActionForVariableSchema(action, options);
  return {
    trigger: action.trigger,
    op: action.op,
    key: action.key,
    value: action.value
  };
}

function getPreferredVariableKeyForPlaybookAction(keys) {
  return keys[0];
}

function getScriptBuilderNodes() {
  return state.project.nodes
    .filter((node) => node && !isFrameNode(node))
    .sort(compareNodesByIdentity);
}

function renderScriptNodeRow(node) {
  const logic = normalizeNodeStateLogic(node.stateLogic);
  const routing = normalizeNodeRouting(node.routing);
  const targetStatus = routing.mode === "goTo" ? renderTargetResolutionStatus(routing.target) : "";
  const effectsText = formatNodeEffectsText(node);
  return `
    <div class="script-node-row" data-script-node-id="${escapeAttr(node.id)}">
      <button class="linked-node script-node-link" type="button" data-action="focus-canvas-node" data-node-id="${escapeAttr(node.id)}">
          <strong>${escapeHtml(node.title || node.id || getNodeDisplayId(node))}</strong>
          <small>${escapeHtml(getNodeTypeLabel(node.type))} ${escapeHtml(node.id || getNodeDisplayId(node))}</small>
      </button>
      ${renderPlaybookConditionCodeCell({
        value: logic.requirements,
        attributes: `data-script-node-id="${escapeAttr(node.id)}" data-script-node-field="requirements"`
      })}
      ${renderPlaybookEffectsCodeCell({
        value: effectsText,
        defaultTrigger: "onVisit",
        attributes: `data-script-node-id="${escapeAttr(node.id)}" data-script-node-field="effects"`
      })}
      <select data-script-node-id="${escapeAttr(node.id)}" data-script-node-field="routingMode">
        ${renderPlaybookOptionList(NODE_ROUTING_MODES, routing.mode)}
      </select>
      ${renderScriptNodeTargetSlot(node, routing, targetStatus)}
      ${renderPlaybookJsonButton(getPlaybookJsonPairToken("rowId", `node:${node.id}`))}
    </div>
  `;
}

function renderPlaybookConditionCodeCell({ value = "", attributes = "", readonly = false } = {}) {
  const status = getConditionEvaluationStatus(value, state.project.variables);
  return `
    <div class="playbook-code-cell playbook-condition-code-cell">
      <textarea class="playbook-code-editor playbook-condition-code-editor" ${attributes} ${readonly ? "readonly" : ""} spellcheck="false" placeholder="${escapeAttr(t("Condition expression"))}">${escapeHtml(value || "")}</textarea>
      ${renderPlaybookCodeStatus(status)}
    </div>
  `;
}

function renderPlaybookEffectsCodeCell({ value = "", attributes = "", defaultTrigger = "onVisit", readonly = false } = {}) {
  const status = getPlaybookEffectsTextStatus(value, { defaultTrigger });
  return `
    <div class="playbook-code-cell playbook-effects-code-cell">
      <textarea class="playbook-code-editor playbook-effects-code-editor" ${attributes} data-playbook-effects-default-trigger="${escapeAttr(defaultTrigger)}" ${readonly ? "readonly" : ""} spellcheck="false" placeholder="${escapeAttr(t("Effect lines"))}">${escapeHtml(value || "")}</textarea>
      ${renderPlaybookCodeStatus(status)}
    </div>
  `;
}

function renderPlaybookCodeStatus(status) {
  const normalized = normalizePlaybookEditorStatus(status);
  const label = formatPlaybookEditorStatusLabel(normalized);
  const statusClass = getPlaybookCodeStatusClass(normalized);
  return `<small class="play-rule-status play-rule-status-${escapeAttr(statusClass)}" data-playbook-code-status>${escapeHtml(label)}</small>`;
}

function getPlaybookCodeStatusForControl(target) {
  if (!target?.dataset) return null;
  if (target.dataset.scriptNodeField === "requirements" || target.dataset.gateField === "condition") {
    return getConditionEvaluationStatus(target.value, state.project.variables);
  }
  if (target.dataset.scriptNodeField === "effects" || target.dataset.gateField === "effects") {
    return getPlaybookEffectsTextStatus(target.value, {
      defaultTrigger: target.dataset.playbookEffectsDefaultTrigger || "onVisit"
    });
  }
  if (target.dataset.choiceOptionField === "requires") {
    return getConditionEvaluationStatus(target.value, state.project.variables);
  }
  if (target.dataset.choiceOptionField === "effects") {
    return getPlaybookEffectsTextStatus(target.value, {
      defaultTrigger: target.dataset.playbookEffectsDefaultTrigger || "onChoose"
    });
  }
  return null;
}

function updatePlaybookCodeStatusForControl(target) {
  const status = normalizePlaybookEditorStatus(getPlaybookCodeStatusForControl(target));
  const statusElement = target?.closest?.(".playbook-code-cell")?.querySelector?.("[data-playbook-code-status]");
  if (!statusElement) return;
  statusElement.textContent = formatPlaybookEditorStatusLabel(status);
  statusElement.className = `play-rule-status play-rule-status-${getPlaybookCodeStatusClass(status)}`;
}

function renderScriptNodeTargetSlot(node, routing, targetStatus) {
  if (routing.mode === "goTo") {
    return `
      <div class="script-node-target">
        <input data-script-node-id="${escapeAttr(node.id)}" data-script-node-field="routingTarget" list="playbookTargetOptions" value="${escapeAttr(routing.target)}" placeholder="${escapeAttr(t("Exact node title"))}" spellcheck="false">
        ${targetStatus}
      </div>
    `;
  }
  const hint = routing.mode === "end"
    ? t("Route ends at this node — no next step.")
    : t("Next step follows the outgoing link.");
  return `
    <div class="script-node-target script-node-target-hint">
      <p class="nc-routing-hint-body">${escapeHtml(hint)}</p>
    </div>
  `;
}

function renderPlaybookActionRow(action) {
  const targetStatus = renderTargetResolutionStatus(action.target);
  const variableInfo = getPlaybookActionVariableInfo(action);
  const operationAllowed = getAllowedPlaybookActionOperationsForVariableInfo(variableInfo).some((option) => option.value === action.op);
  const valueDisabled = !variableInfo.hasVariable || !operationAllowed || action.op === "toggle";
  return `
    <div class="playbook-action-row">
      ${renderPlaybookActionTriggerControl(action)}
      <div class="script-node-target">
        <input data-playbook-action-id="${escapeAttr(action.id)}" data-playbook-action-field="target" list="playbookTargetOptions" value="${escapeAttr(action.target)}" placeholder="${escapeAttr(t("Any node"))}" spellcheck="false">
        ${targetStatus}
      </div>
      <div class="playbook-state-key-cell">
        ${renderPlaybookActionVariableKeyControl(action, variableInfo)}
        <small class="playbook-state-key-preview">
          <span>${escapeHtml(t(variableInfo.hasVariable ? "Writes" : "Missing variable"))}</span>
          ${variableInfo.stateKey ? `<code>${escapeHtml(variableInfo.stateKey)}</code>` : ""}
        </small>
      </div>
      ${renderPlaybookActionOperationControl(action, variableInfo)}
      ${renderPlaybookActionValueControl(action, variableInfo, valueDisabled)}
      ${renderPlaybookJsonButton(getPlaybookJsonPairToken("id", action.id))}
      <div class="playbook-action-controls">
        <button class="icon-button danger-button playbook-action-delete" type="button" title="${escapeAttr(t("Delete action"))}" aria-label="${escapeAttr(t("Delete action"))}" data-action="delete-playbook-action" data-playbook-action-id="${escapeAttr(action.id)}">x</button>
      </div>
    </div>
  `;
}

function getPlaybookActionDraftModel(keys = Object.keys(normalizeVariablesObject(state.project.variables)).sort((a, b) => a.localeCompare(b))) {
  const source = state.playbookActionDraft && typeof state.playbookActionDraft === "object" && !Array.isArray(state.playbookActionDraft)
    ? state.playbookActionDraft
    : {};
  const key = source.key && keys.includes(source.key) ? source.key : getPreferredVariableKeyForPlaybookAction(keys);
  const variableInfo = getPlaybookActionVariableInfo({ category: "Variable", key });
  const allowedOperations = getAllowedPlaybookActionOperationsForVariableInfo(variableInfo);
  const requestedOp = normalizePlaybookActionOperation(source.op || "set");
  const op = allowedOperations.some((option) => option.value === requestedOp) ? requestedOp : (allowedOperations[0]?.value || "set");
  const value = Object.prototype.hasOwnProperty.call(source, "value")
    ? normalizeOptionalString(source.value)
    : getDefaultPlaybookActionValueForVariableInfo(variableInfo);
  return {
    trigger: normalizePlaybookActionTrigger(source.trigger || "manual"),
    target: normalizeOptionalString(source.target).trim(),
    key,
    op,
    value,
    variableInfo,
    allowedOperations
  };
}

function syncPlaybookActionDraftFromRow(row) {
  if (!row) return;
  const next = { ...(state.playbookActionDraft || {}) };
  ["trigger", "target", "key", "op", "value"].forEach((field) => {
    const control = row.querySelector(`[data-draft-field="${CSS.escape(field)}"]`);
    if (!control || control.disabled) return;
    next[field] = getPlaybookActionInputValue(control);
  });
  state.playbookActionDraft = next;
}

function normalizePlaybookActionDraft({ resetValue = false, coerceValue = true } = {}) {
  const draft = getPlaybookActionDraftModel();
  const action = {
    id: "draft",
    trigger: draft.trigger,
    target: draft.target,
    op: draft.op,
    category: "Variable",
    key: draft.key,
    value: resetValue ? getDefaultPlaybookActionValueForVariableInfo(draft.variableInfo) : draft.value
  };
  normalizePlaybookActionForVariableSchema(action, { coerceValue });
  state.playbookActionDraft = {
    trigger: action.trigger,
    target: action.target,
    key: action.key,
    op: action.op,
    value: action.value
  };
  return getPlaybookActionDraftModel();
}

function renderPlaybookActionDraftRow() {
  if (!state.playbookActionDraftOpen) return "";
  const variables = normalizeVariablesObject(state.project.variables);
  const keys = Object.keys(variables).sort((a, b) => a.localeCompare(b));
  if (!keys.length) {
    return `<div class="nc-empty-state">${t("Add a variable definition before adding a variable action.")}</div>`;
  }
  const draft = getPlaybookActionDraftModel(keys);
  return `
    <div class="playbook-action-row playbook-action-draft-row" data-draft-id="playbook-action">
      <select data-draft-field="trigger">
        ${renderPlaybookOptionList(PLAYBOOK_VARIABLE_ACTION_TRIGGERS, draft.trigger)}
      </select>
      <div class="script-node-target">
        ${renderTargetSelect({
          attributes: `data-draft-field="target"`,
          selected: draft.target,
          placeholder: "Any node"
        })}
      </div>
      <div class="playbook-state-key-cell">
        ${renderStateKeySelect({
          attributes: `data-draft-field="key"`,
          selected: draft.key,
          placeholder: "Variable"
        })}
      </div>
      <select data-draft-field="op" ${draft.allowedOperations.length ? "" : "disabled"}>
        ${renderPlaybookOptionList(draft.allowedOperations, draft.op)}
      </select>
      ${renderPlaybookActionValueField({
        attributes: `data-draft-field="value"`,
        value: draft.value,
        variableInfo: draft.variableInfo,
        op: draft.op,
        disabled: !draft.allowedOperations.length
      })}
      <span></span>
      <div class="playbook-action-controls">
        <button class="small-button" type="button" data-action="commit-playbook-action-draft">${t("Add")}</button>
      </div>
    </div>
  `;
}

function renderPlaybookActionValueControl(action, variableInfo, valueDisabled) {
  return renderPlaybookActionValueField({
    attributes: `data-playbook-action-id="${escapeAttr(action.id)}" data-playbook-action-field="value"`,
    value: action.value,
    variableInfo,
    op: action.op,
    disabled: valueDisabled
  });
}

function renderPlaybookActionVariableKeyControl(action, variableInfo) {
  const variables = normalizeVariablesObject(state.project.variables);
  const keys = Object.keys(variables).sort((a, b) => a.localeCompare(b));
  const selected = variableInfo.hasVariable ? variableInfo.stateKey : "";
  const missing = variableInfo.stateKey && !variableInfo.hasVariable ? variableInfo.stateKey : "";
  return `
    <select data-playbook-action-id="${escapeAttr(action.id)}" data-playbook-action-field="key" ${keys.length ? "" : "disabled"}>
      <option value="">${escapeHtml(t(keys.length ? "Variable" : "No variables yet."))}</option>
      ${missing ? `<option value="${escapeAttr(missing)}" selected>${escapeHtml(`${missing} (${t("Missing variable")})`)}</option>` : ""}
      ${keys.map((key) => {
        const typeLabel = getActionVariableTypeLabel(getActionVariableType(variables[key]));
        return `<option value="${escapeAttr(key)}" ${key === selected ? "selected" : ""}>${escapeHtml(`${key} (${t(typeLabel)})`)}</option>`;
      }).join("")}
    </select>
  `;
}

function renderStateKeySelect({ attributes = "", selected = "", placeholder = "State key" } = {}) {
  const variables = normalizeVariablesObject(state.project.variables);
  const keys = Object.keys(variables).sort((a, b) => a.localeCompare(b));
  const selectedValue = normalizeOptionalString(selected).trim();
  const hasSelected = selectedValue && keys.includes(selectedValue);
  const missing = selectedValue && !hasSelected ? selectedValue : "";
  return `
    <select ${attributes} ${keys.length || missing ? "" : "disabled"}>
      <option value="" ${selectedValue ? "" : "selected"}>${escapeHtml(t(keys.length || missing ? placeholder : "No variables yet."))}</option>
      ${missing ? `<option value="${escapeAttr(missing)}" selected>${escapeHtml(`${missing} (${t("Missing variable")})`)}</option>` : ""}
      ${keys.map((key) => {
        const typeLabel = getActionVariableTypeLabel(getActionVariableType(variables[key]));
        return `<option value="${escapeAttr(key)}" ${key === selectedValue ? "selected" : ""}>${escapeHtml(`${key} (${t(typeLabel)})`)}</option>`;
      }).join("")}
    </select>
  `;
}

function renderTargetSelect({ attributes = "", selected = "", placeholder = "Exact node title" } = {}) {
  const entries = getPlaybookTargetEntries();
  const selectedValue = normalizeOptionalString(selected).trim();
  const hasSelected = selectedValue && entries.some((entry) => entry.value === selectedValue);
  const missing = selectedValue && !hasSelected ? selectedValue : "";
  return `
    <select ${attributes} ${entries.length || missing ? "" : "disabled"}>
      <option value="" ${selectedValue ? "" : "selected"}>${escapeHtml(t(placeholder))}</option>
      ${missing ? `<option value="${escapeAttr(missing)}" selected>${escapeHtml(`${missing} (${t("No matching node, type, or ID.")})`)}</option>` : ""}
      ${entries.map((entry) => {
        const label = [entry.label, entry.hint].filter(Boolean).join(" ");
        return `<option value="${escapeAttr(entry.value)}" ${entry.value === selectedValue ? "selected" : ""}>${escapeHtml(label || entry.value)}</option>`;
      }).join("")}
    </select>
  `;
}

function renderPlaybookActionTriggerControl(action) {
  if (action.trigger === "gate") {
    return `
      <div class="playbook-action-fixed-op" title="${escapeAttr(t("This old gate trigger is handled in Choice Conditions."))}">
        <strong>${escapeHtml(t("Legacy gate trigger"))}</strong>
        <small>${escapeHtml(t("Choice Conditions"))}</small>
      </div>
    `;
  }
  if (action.trigger === "onChoose") {
    return `
      <div class="playbook-action-fixed-op" title="${escapeAttr(t("This old global on-choose trigger is still loaded for compatibility. New choice changes belong in each option's On choose effects."))}">
        <strong>${escapeHtml(t("Legacy global choose trigger"))}</strong>
        <small>${escapeHtml(t("Use Choice Effects"))}</small>
      </div>
    `;
  }
  return `
    <select data-playbook-action-id="${escapeAttr(action.id)}" data-playbook-action-field="trigger">
      ${renderPlaybookOptionList(PLAYBOOK_VARIABLE_ACTION_TRIGGERS, action.trigger)}
    </select>
  `;
}

function renderPlaybookActionOperationControl(action, variableInfo = getPlaybookActionVariableInfo(action)) {
  if (action.op === "if") {
    return `
      <div class="playbook-action-fixed-op" title="${escapeAttr(t("The old gate + if action is still loaded for compatibility. Edit node Requirements in Script Builder; edit choice Requirements in Choice Conditions or the Choice panel."))}">
        <strong>${escapeHtml(t("Legacy condition gate"))}</strong>
        <small>${escapeHtml(t("Conditions are not actions."))}</small>
      </div>
    `;
  }
  if (!PLAYBOOK_ACTION_OPERATIONS.some((option) => option.value === action.op)) {
    return `
      <div class="playbook-action-fixed-op" title="${escapeAttr(t("This old action is kept for compatibility. New actions should use state operations."))}">
        <strong>${escapeHtml(t("Legacy runtime-only action"))}</strong>
        <small>${escapeHtml(action.op || "")}</small>
      </div>
    `;
  }
  const allowedOperations = getAllowedPlaybookActionOperationsForVariableInfo(variableInfo);
  if (!allowedOperations.length) {
    return `
      <div class="playbook-action-fixed-op" title="${escapeAttr(t("Define this key in Variables before this action can run."))}">
        <strong>${escapeHtml(t("Missing variable"))}</strong>
        <small>${escapeHtml(t("Operation"))}</small>
      </div>
    `;
  }
  if (!allowedOperations.some((option) => option.value === action.op)) {
    return `
      <div class="playbook-action-fixed-op" title="${escapeAttr(t("Operation not available for this variable type."))}">
        <strong>${escapeHtml(t("Operation not available for this variable type."))}</strong>
        <small>${escapeHtml(action.op || "")}</small>
      </div>
    `;
  }
  return `
    <select data-playbook-action-id="${escapeAttr(action.id)}" data-playbook-action-field="op">
      ${renderPlaybookOptionList(allowedOperations, action.op)}
    </select>
  `;
}

function renderPlaybookOptionList(options, selectedValue) {
  return options.map((option) => `<option value="${escapeAttr(option.value)}" ${option.value === selectedValue ? "selected" : ""}>${escapeHtml(t(option.label))}</option>`).join("");
}

function renderPlaybookJsonButton(token) {
  if (!token) return `<span></span>`;
  return `<button class="small-button playbook-json-row-button" type="button" data-action="focus-playbook-json" data-playbook-token="${escapeAttr(token)}">${t("JSON")}</button>`;
}

function getPlaybookJsonPropertyToken(key) {
  return `${JSON.stringify(String(key || ""))}:`;
}

function getPlaybookJsonPairToken(key, value) {
  return `${JSON.stringify(String(key || ""))}: ${JSON.stringify(String(value || ""))}`;
}

function getPlaybookStateKeySuggestions() {
  const keys = new Set(Object.keys(normalizeVariablesObject(state.project.variables)));
  getCharacters().forEach((character) => {
    if (character.name) keys.add(character.name);
  });
  state.project.nodes.forEach((node) => {
    if (node.title) keys.add(node.title);
  });
  return [...keys].filter(Boolean).sort((a, b) => a.localeCompare(b));
}

// Richer datalist entries that disambiguate duplicate titles by appending the node id.
// Used by the renderer in Phase 4 to fix the "two scenes both called Hesitation" silent-fail mode.
function getPlaybookTargetEntries() {
  const out = [];
  const titleCounts = new Map();
  state.project.nodes.forEach((n) => {
    const t = String(n.title || "").trim();
    if (t) titleCounts.set(t, (titleCounts.get(t) || 0) + 1);
  });
  // node type entries
  getProjectNodeTypes().forEach((typeDef) => out.push({ value: typeDef.type, label: typeDef.type, hint: "(type)" }));
  // node title / id entries with disambiguation
  state.project.nodes.forEach((n) => {
    const title = String(n.title || "").trim();
    if (n.id) out.push({ value: n.id, label: n.id, hint: title ? `— "${title}"` : "" });
    if (title) {
      const ambig = (titleCounts.get(title) || 0) > 1;
      out.push({ value: title, label: title, hint: ambig ? `(${getNodeDisplayId(n)})` : "" });
    }
  });
  return out;
}

// Render a status line under target inputs showing what the typed value resolves to.
// Empty input → nothing; helps writers spot typos and intentional type/title broadcasts.
function renderTargetResolutionStatus(value, options = {}) {
  const trimmed = String(value || "").trim();
  if (!trimmed) return "";
  const resolved = resolveTarget(trimmed);
  if (resolved.kind === "none") {
    return `<small class="target-status target-status-error">${escapeHtml(t("No matching node, type, or ID."))}</small>`;
  }
  if (resolved.kind === "id") {
    const n = resolved.matches[0];
    return `<small class="target-status target-status-ok">${escapeHtml(t("Matches node:"))} ${escapeHtml(n.title || n.id)} (${escapeHtml(getNodeDisplayId(n))})</small>`;
  }
  if (resolved.kind === "title") {
    const count = resolved.matches.length;
    if (count === 1) return `<small class="target-status target-status-ok">${escapeHtml(t("Matches 1 node by title."))}</small>`;
    return `<small class="target-status target-status-warn">${escapeHtml(t("{count} nodes share this title — rule applies to all.", { count }))}</small>`;
  }
  if (resolved.kind === "type") {
    return `<small class="target-status target-status-info">${escapeHtml(t("Applies to all {count} nodes of type {type}.", { count: resolved.matches.length, type: trimmed }))}</small>`;
  }
  return "";
}

function renderPlaybookRuleCard(card) {
  const locked = Boolean(card.locked);
  const toggleDisabled = card.required || locked ? "disabled" : "";
  const toggleTitle = card.required ? t("System rule") : locked ? t("Enable Debug Mode before Visit Tracking.") : (card.enabled ? t("Enabled") : t("Disabled"));
  const help = card.help || t("This Play preview rule controls how the Play dialog behaves.");
  const helpOpen = state.playbookRuleHelpOpenIds.has(card.id);
  return `
    <article class="playbook-rule-card${card.enabled ? "" : " is-disabled"}" data-rule-enabled="${card.enabled}">
      <header>
        <div class="playbook-rule-heading">
          <span class="playbook-rule-kind">${escapeHtml(t(card.kind))}</span>
          <div class="playbook-rule-title-line">
            <h4>${escapeHtml(t(card.title))}</h4>
            <button class="help-button playbook-rule-help${helpOpen ? " active" : ""}" type="button" data-action="toggle-playbook-rule-help" data-playbook-rule-help="${escapeAttr(card.id)}" title="${escapeAttr(help)}" aria-label="${escapeAttr(t("What does this rule do?"))}" aria-expanded="${helpOpen}">?</button>
          </div>
        </div>
        <div class="playbook-rule-card-actions">
          <label class="playbook-rule-toggle${card.enabled ? " is-enabled" : ""}" title="${escapeAttr(toggleTitle)}" aria-label="${escapeAttr(toggleTitle)}">
            <input type="checkbox" data-runner-rule-enabled="${escapeAttr(card.id)}" aria-label="${escapeAttr(toggleTitle)}" ${card.enabled ? "checked" : ""} ${toggleDisabled}>
            <span class="playbook-rule-switch-track" aria-hidden="true">
              <span class="playbook-rule-switch-thumb"></span>
            </span>
          </label>
          ${renderPlaybookJsonButton(getPlaybookJsonPropertyToken(card.jsonToken))}
        </div>
      </header>
      ${helpOpen ? `<p class="playbook-rule-help-note">${escapeHtml(help)}</p>` : ""}
      ${card.body}
    </article>
  `;
}

function getPlaybookRuleCards() {
  const rules = getRunnerRules();
  return Object.entries(rules)
    .filter(([id]) => id !== "visitTracking")
    .map(([id, rule]) => renderRunnerRuleCardModel(id, rule, rules));
}

function isDebugModeRuleEnabled(rules = getRunnerRules()) {
  return Boolean(rules.debugMode?.enabled && rules.debugMode.value);
}

function renderRunnerRuleCardModel(id, rule, rules = getRunnerRules()) {
  const required = id === "startNode";
  const lockedByDebug = id === "visitTracking" && !isDebugModeRuleEnabled(rules);
  const enabled = lockedByDebug ? false : required || Boolean(rule.enabled);
  const disabledAttr = enabled ? "" : " disabled";
  const debugModeEnabled = isDebugModeRuleEnabled(rules);
  const visitRule = rules.visitTracking || getDefaultRunnerRules().visitTracking;
  const visitTrackingEnabled = Boolean(debugModeEnabled && visitRule.enabled && visitRule.value);
  const visitTrackingToggleTitle = debugModeEnabled
    ? (visitTrackingEnabled ? t("Enabled") : t("Disabled"))
    : t("Enable Debug Mode before Visit Tracking.");
  const bodyById = {
    startNode: `
      <label class="field">
        <span>${t("Exact node title")}</span>
        <input data-runner-rule-field="startNode" list="playbookTargetOptions" value="${escapeAttr(rule.value || "")}" placeholder="${escapeAttr(t("Exact node title"))}" spellcheck="false"${disabledAttr}>
      </label>
    `,
    endCondition: `
      <label class="field">
        <span>${t("End Condition")}</span>
        <textarea class="playbook-end-condition-editor" data-runner-rule-field="endCondition" rows="3" placeholder="${escapeAttr(t("Condition expression"))}" spellcheck="false"${disabledAttr}>${escapeHtml(rule.value || "")}</textarea>
        <small class="play-rule-status play-rule-status-${getEndConditionStatus(rule.value).status}" data-end-condition-status>${escapeHtml(formatEndConditionStatusLabel(getEndConditionStatus(rule.value)))}</small>
      </label>
    `,
    visitTracking: `
      <p class="playbook-rule-note">
        <span>${t(lockedByDebug ? "Enable Debug Mode before Visit Tracking." : "Record visited node titles")}</span>
      </p>
    `,
    debugMode: `
      <p class="playbook-rule-note">
        <span>${t("Show state and condition details in Play preview.")}</span>
      </p>
      <div class="playbook-rule-nested${visitTrackingEnabled ? "" : " is-disabled"}">
        <div class="playbook-rule-nested-copy">
          <strong>${escapeHtml(t("Visit Tracking"))}</strong>
          <span>${escapeHtml(t("Record visited nodes while Debug Mode is enabled. The list is discarded when Play preview closes."))}</span>
        </div>
        <div class="playbook-rule-nested-actions">
          <label class="playbook-rule-toggle${visitTrackingEnabled ? " is-enabled" : ""}" title="${escapeAttr(visitTrackingToggleTitle)}" aria-label="${escapeAttr(visitTrackingToggleTitle)}">
            <input type="checkbox" data-runner-rule-enabled="visitTracking" aria-label="${escapeAttr(visitTrackingToggleTitle)}" ${visitTrackingEnabled ? "checked" : ""} ${debugModeEnabled ? "" : "disabled"}>
            <span class="playbook-rule-switch-track" aria-hidden="true">
              <span class="playbook-rule-switch-thumb"></span>
            </span>
          </label>
          ${renderPlaybookJsonButton(getPlaybookJsonPropertyToken("visitTracking"))}
        </div>
      </div>
    `
  };
  const titles = {
    startNode: "Start Node",
    endCondition: "End Condition",
    visitTracking: "Visit Tracking",
    debugMode: "Debug Mode"
  };
  const helpById = {
    startNode: ["Choose the exact node title where Play preview starts. This does not change canvas links or layout."],
    endCondition: ["End Play preview when this condition becomes true. Route checks such as route == ending work well here."],
    visitTracking: ["Record visited nodes while Debug Mode is enabled. The list is discarded when Play preview closes."],
    debugMode: ["Show state values and condition results in Play preview, so it is easier to see why a choice appears or disappears."]
  };
  return {
    id,
    kind: "Play preview rule",
    title: titles[id] || id,
    jsonToken: id,
    required,
    locked: lockedByDebug,
    enabled,
    help: (helpById[id] || []).map((item) => t(item)).join(" "),
    body: bodyById[id] || `<p>${escapeHtml(String(rule.value ?? ""))}</p>`
  };
}

function getPlaybookJsonRows(value) {
  return Math.max(24, String(value || "").split(/\r?\n/).length + 2);
}

function resizePlaybookJsonTextarea(textarea = dom.variablesPanel?.querySelector("textarea[data-project-field='variables']")) {
  if (!textarea) return;
  textarea.style.height = "auto";
  textarea.style.height = `${Math.max(520, textarea.scrollHeight + 2)}px`;
  return textarea;
}

function focusPendingPlaybookTarget() {
  const target = state.playbookFocusTarget;
  if (!target || !dom.variablesPanel) return;
  state.playbookFocusTarget = null;
  let selector = "";
  if (target.kind === "variable") {
    selector = `[data-variable-key="${CSS.escape(target.id)}"][data-variable-field="${CSS.escape(target.field || "key")}"]`;
  } else if (target.kind === "action") {
    selector = `[data-playbook-action-id="${CSS.escape(target.id)}"][data-playbook-action-field="${CSS.escape(target.field || "target")}"]`;
  } else if (target.kind === "runnerRule") {
    selector = `[data-runner-rule-field="${CSS.escape(target.id)}"]`;
  }
  const element = selector ? dom.variablesPanel.querySelector(selector) : null;
  if (!element) return;
  element.scrollIntoView({ block: "center", inline: "nearest" });
  element.focus({ preventScroll: true });
  if (typeof element.select === "function") element.select();
}

function focusPlaybookJsonToken(token, textarea = dom.variablesPanel?.querySelector("textarea[data-project-field='variables']")) {
  if (!textarea || !token) return false;
  const value = textarea.value || "";
  const index = value.indexOf(token);
  if (index < 0) {
    textarea.scrollIntoView({ block: "center", behavior: "smooth" });
    return false;
  }
  const lineIndex = value.slice(0, index).split(/\r?\n/).length - 1;
  const lineStart = value.lastIndexOf("\n", index - 1) + 1;
  const nextLine = value.indexOf("\n", index);
  const lineEnd = nextLine < 0 ? value.length : nextLine;
  setTextareaSelection(textarea, lineStart, lineEnd);
  try {
    textarea.focus();
  } catch (error) {
    textarea.focus();
  }
  scrollPlaybookJsonLineIntoView(textarea, lineIndex);
  runAfterRender(() => {
    setTextareaSelection(textarea, lineStart, lineEnd);
    scrollPlaybookJsonLineIntoView(textarea, lineIndex);
  });
  return true;
}

function setTextareaSelection(textarea, start, end) {
  try {
    textarea.setSelectionRange(start, end);
  } catch (error) {
    // Some embedded environments delay textarea focus; the next frame retry handles it.
  }
}

function scrollPlaybookJsonLineIntoView(textarea, lineIndex) {
  const panel = getPlaybookJsonScrollContainer(textarea);
  if (!panel) {
    textarea.scrollIntoView({ block: "center", behavior: "smooth" });
    return;
  }
  const lineHeight = getTextareaLineHeight(textarea);
  textarea.scrollTop = Math.max(0, lineHeight * Math.max(0, lineIndex) - textarea.clientHeight * 0.35);
  const textareaRect = textarea.getBoundingClientRect();
  const lineTop = textareaRect.top + (lineHeight * Math.max(0, lineIndex)) - textarea.scrollTop;
  const lineBottom = lineTop + lineHeight;
  const isDocumentScroller = panel === document.scrollingElement || panel === document.documentElement || panel === document.body;
  const panelRect = isDocumentScroller
    ? { top: 0, bottom: window.innerHeight || document.documentElement.clientHeight, height: window.innerHeight || document.documentElement.clientHeight }
    : panel.getBoundingClientRect();
  const margin = Math.max(32, Math.min(120, panelRect.height * 0.28));
  let delta = 0;
  if (lineTop < panelRect.top + margin) delta = lineTop - (panelRect.top + margin);
  else if (lineBottom > panelRect.bottom - margin) delta = lineBottom - (panelRect.bottom - margin);
  if (!delta) return;
  const top = isDocumentScroller
    ? (window.scrollY || document.documentElement.scrollTop || document.body.scrollTop || 0) + delta
    : panel.scrollTop + delta;
  try {
    if (isDocumentScroller) window.scrollTo({ top: Math.max(0, top), behavior: "smooth" });
    else panel.scrollTo({ top: Math.max(0, top), behavior: "smooth" });
  } catch (error) {
    if (isDocumentScroller) window.scrollTo(0, Math.max(0, top));
    else panel.scrollTop = Math.max(0, top);
  }
}

function getTextareaLineHeight(textarea) {
  const styles = window.getComputedStyle ? window.getComputedStyle(textarea) : null;
  const parsedLineHeight = Number.parseFloat(styles?.lineHeight || "");
  const fontSize = Number.parseFloat(styles?.fontSize || "");
  return Number.isFinite(parsedLineHeight)
    ? parsedLineHeight
    : Math.max(18, (Number.isFinite(fontSize) ? fontSize * 1.35 : 18));
}

function getPlaybookJsonScrollContainer(textarea) {
  let element = textarea?.parentElement;
  while (element && element !== document.body) {
    const styles = window.getComputedStyle ? window.getComputedStyle(element) : null;
    const overflowY = styles?.overflowY || styles?.overflow || "";
    if (/(auto|scroll)/.test(overflowY) && element.scrollHeight > element.clientHeight) return element;
    element = element.parentElement;
  }
  return dom.variablesPanel || document.scrollingElement || document.documentElement;
}

function renderEventsSheetPage() {
  const model = buildEventSheetDocumentModel();
  const limit = getDocumentRenderLimit("events");
  const limited = limitEventSheetGroups(model.groups, limit);
  dom.eventsPanel.innerHTML = `
    <div class="document-shell event-sheet-shell">
      <header class="document-header">
        <div>
          <span class="pane-kicker">CSV</span>
          <h2>Events Sheet.csv</h2>
          <div class="document-meta" data-event-search-meta>${escapeHtml(formatEventSheetMeta(model))}</div>
        </div>
        <div class="document-actions">
          <button class="small-button" type="button" data-action="add-node" data-type="Event">${t("Add frame")}</button>
          <button class="small-button" type="button" data-action="reset-event-row-order" title="${escapeAttr(t("Clear manual drag order and re-sort rows by the canvas flow"))}">${t("Re-sort by graph")}</button>
          <button class="small-button" type="button" data-action="export-event-sheet">${t("Export CSV")}</button>
          <button class="small-button" type="button" data-action="export-event-sheet-json">${t("Export JSON")}</button>
        </div>
      </header>
      <div class="document-filter-bar" data-event-filter-bar>
        ${renderEventFilterBar(model)}
      </div>
      <div class="event-sheet-groups">
        ${renderEventSheetGroupsMarkup(model, limited.groups)}
      </div>
      ${renderDocumentLimitNotice("events", limited.shownRows, model.visibleRows)}
    </div>
  `;
}

function renderEventSheetGroupsForSearch() {
  const groupContainer = dom.eventsPanel?.querySelector(".event-sheet-groups");
  const meta = dom.eventsPanel?.querySelector("[data-event-search-meta]");
  const filterBar = dom.eventsPanel?.querySelector("[data-event-filter-bar]");
  if (!groupContainer) {
    renderEventsSheetPage();
    return;
  }
  const model = buildEventSheetDocumentModel();
  const limit = getDocumentRenderLimit("events");
  const limited = limitEventSheetGroups(model.groups, limit);
  if (meta) meta.textContent = formatEventSheetMeta(model);
  if (filterBar) filterBar.innerHTML = renderEventFilterBar(model);
  groupContainer.innerHTML = renderEventSheetGroupsMarkup(model, limited.groups);
  const shell = dom.eventsPanel?.querySelector(".event-sheet-shell");
  shell?.querySelector("[data-document-limit-notice]")?.remove();
  shell?.insertAdjacentHTML("beforeend", renderDocumentLimitNotice("events", limited.shownRows, model.visibleRows));
}

function buildEventSheetDocumentModel() {
  const allGroups = getEventRowGroups();
  const groups = getFilteredEventRowGroups(allGroups);
  const totalRows = allGroups.reduce((total, group) => total + group.rows.length, 0);
  const visibleRows = groups.reduce((total, group) => total + group.rows.length, 0);
  const queryRaw = state.eventSearch || "";
  const query = queryRaw.trim();
  return { allGroups, groups, totalRows, visibleRows, query, queryRaw };
}

function limitEventSheetGroups(groups, limit = getDocumentRenderLimit("events")) {
  let remaining = Math.max(0, limit);
  let shownRows = 0;
  const limitedGroups = [];
  groups.forEach((group) => {
    if (remaining <= 0) return;
    const rows = group.rows.slice(0, remaining);
    if (!rows.length) return;
    shownRows += rows.length;
    remaining -= rows.length;
    limitedGroups.push({ ...group, rows, totalRows: group.rows.length });
  });
  return { groups: limitedGroups, shownRows };
}

function renderEventSheetGroupsMarkup(model, groups = model.groups) {
  if (groups.length) return groups.map(renderEventSheetGroup).join("");
  if (model.allGroups.length) return `<div class="nc-empty-state">${t("No matching frames.")}</div>`;
  return `<div class="nc-empty-state">${t("No visible frame nodes yet.")}</div>`;
}

function formatEventSheetMeta(model) {
  if (!model.query) return t("{count} event rows from canvas nodes", { count: model.totalRows });
  return t("{visible} of {total} event rows match {query}", { visible: model.visibleRows, total: model.totalRows, query: `"${model.query}"` });
}

function renderEventFilterBar(model) {
  const hiddenTypes = getHiddenEventFrameTypes();
  const chips = [];
  if (model.query) {
    chips.push(`
      <span class="filter-chip">
        ${t("Search")}: ${escapeHtml(model.query)}
        <button type="button" data-action="clear-event-search" aria-label="${escapeAttr(t("Clear event search"))}">${t("Clear")}</button>
      </span>
    `);
  }
  if (hiddenTypes.length) {
    chips.push(`
      <span class="filter-chip">
        ${t("Hidden frame types")}:
        ${hiddenTypes.map((typeDef) => `
          <button type="button" data-action="show-event-frame-type" data-event-frame-type="${escapeAttr(typeDef.type)}" title="${escapeAttr(t("Show this frame type in Events Sheet"))}">
            ${escapeHtml(typeDef.label || typeDef.type)}
          </button>
        `).join("")}
      </span>
    `);
  }
  return chips.join("");
}

function clearEventSearch() {
  state.eventSearch = "";
  if (dom.eventSearchInput) dom.eventSearchInput.value = "";
  renderEventSheetGroupsForSearch();
  setStatus("Event search cleared.");
}

function hideEventFrameType(type) {
  const key = normalizeOptionalString(type).trim();
  if (!key) return;
  const typeDef = getProjectNodeTypes().find((item) => item.type === key);
  if (!typeDef || !isFrameKind(typeDef.kind)) {
    setStatus("Frame type not found.");
    return;
  }
  typeDef.eventSheetHidden = true;
  markProjectStructureChanged({ nodeTypes: true });
  if (state.activeFileId === "events") renderEventsSheetPage();
  else renderAll();
  setStatus(`${typeDef.label || key} hidden from Events Sheet.`);
}

function showEventFrameType(type) {
  const key = normalizeOptionalString(type).trim();
  if (!key) return;
  const typeDef = getProjectNodeTypes().find((item) => item.type === key);
  if (!typeDef || !isFrameKind(typeDef.kind)) {
    setStatus("Frame type not found.");
    return;
  }
  typeDef.eventSheetHidden = false;
  markProjectStructureChanged({ nodeTypes: true });
  if (state.activeFileId === "events") renderEventsSheetPage();
  else renderAll();
  setStatus(`${typeDef.label || key} shown in Events Sheet.`);
}

function getHiddenEventFrameTypes() {
  const rowTypes = new Set(state.project.nodes.filter((node) => isFrameNode(node)).map((node) => node.type));
  return getProjectNodeTypes()
    .filter((typeDef) => rowTypes.has(typeDef.type) && isFrameKind(typeDef.kind) && typeDef.eventSheetHidden)
    .sort((a, b) => (a.label || a.type).localeCompare(b.label || b.type));
}

function captureEventSheetScrollState() {
  const entries = [];
  dom.eventsPanel?.querySelectorAll(".event-sheet-group[data-event-group-type]").forEach((group) => {
    const scroll = group.querySelector(".event-sheet-scroll");
    if (!scroll) return;
    entries.push({
      type: group.dataset.eventGroupType || "",
      left: scroll.scrollLeft,
      top: scroll.scrollTop
    });
  });
  return entries;
}

function restoreEventSheetScrollState(entries) {
  if (!Array.isArray(entries) || !entries.length) return;
  const restore = () => {
    entries.forEach((entry) => {
      const group = dom.eventsPanel?.querySelector(`.event-sheet-group[data-event-group-type="${CSS.escape(entry.type)}"]`);
      const scroll = group?.querySelector(".event-sheet-scroll");
      if (!scroll) return;
      scroll.scrollLeft = Math.min(entry.left, Math.max(0, scroll.scrollWidth - scroll.clientWidth));
      scroll.scrollTop = Math.min(entry.top, Math.max(0, scroll.scrollHeight - scroll.clientHeight));
    });
  };
  restore();
  requestAnimationFrame(restore);
}

function renderEventSheetGroup(group) {
  const columns = getEventSheetColumns(group.type);
  const hiddenColumns = getHiddenEventSheetColumnDefs(group.type);
  return `
    <section class="event-sheet-group" data-event-group-type="${escapeAttr(group.type)}">
      <header class="event-sheet-group-header">
        <h3>${escapeHtml(group.label)}</h3>
        <div class="event-sheet-group-actions">
          <span>${group.totalRows && group.totalRows !== group.rows.length ? t("{visible} of {total} rows", { visible: group.rows.length, total: group.totalRows }) : t("{count} rows", { count: group.rows.length })}</span>
          <button class="small-button" type="button" data-action="hide-event-frame-type" data-event-frame-type="${escapeAttr(group.type)}" title="${escapeAttr(t("Hide this frame type from Events Sheet"))}">${t("Hide frame type")}</button>
        </div>
      </header>
      <div class="event-sheet-scroll">
        <table class="event-sheet-table">
          <colgroup>
            <col class="event-row-handle-col">
            <col class="event-node-col">
            ${columns.map((column) => `<col style="width:${column.width}">`).join("")}
            <col class="event-hidden-col">
          </colgroup>
          <thead>
            <tr>
              <th aria-hidden="true"></th>
              <th class="event-node-heading">${t("Node")}</th>
              ${columns.map((column) => renderEventColumnHeader(column, group.type)).join("")}
              <th>${t("Hidden")}</th>
            </tr>
          </thead>
          <tbody data-event-group-type="${escapeAttr(group.type)}">
            ${group.rows.map((node) => renderEventSheetRow(node, columns, hiddenColumns)).join("")}
          </tbody>
        </table>
      </div>
    </section>
  `;
}

function renderEventColumnHeader(column, eventType = null) {
  const columnName = column.custom ? `${column.label} field` : `${column.label} column`;
  return `
    <th style="${eventColumnWidthStyle(column.width)}" data-event-column-key="${escapeAttr(column.key)}">
      <div class="event-column-header">
        <span class="event-column-name">${escapeHtml(column.label)}</span>
        <span class="event-column-actions" aria-label="${escapeAttr(column.label)} column actions">
          <button class="event-column-button" type="button" aria-label="${escapeAttr(`${t("Rename")} ${columnName}`)}" data-action="rename-event-column" data-event-column-key="${escapeAttr(column.key)}" data-event-type="${escapeAttr(eventType || "")}">${t("Rename")}</button>
          <button class="event-column-button" type="button" aria-label="${escapeAttr(`${t("Hide")} ${columnName}`)}" data-action="hide-event-column" data-event-column-key="${escapeAttr(column.key)}">${t("Hide")}</button>
          <button class="event-column-button danger" type="button" aria-label="${escapeAttr(`${t("Delete")} ${columnName}`)}" data-action="delete-event-column" data-event-column-key="${escapeAttr(column.key)}">${t("Delete")}</button>
        </span>
      </div>
      <span class="event-column-resize-handle" data-event-column-resize="${escapeAttr(column.key)}" role="separator" aria-label="${escapeAttr(`${t("Resize")} ${columnName}`)}" title="${escapeAttr(t("Drag to resize"))}"></span>
    </th>
  `;
}

function renderEventSheetRow(node, columns, hiddenColumns = []) {
  return `
    <tr data-event-row-id="${escapeAttr(node.id)}">
      <td class="event-row-handle-cell">
        <span class="event-row-drag-handle" data-event-row-drag="${escapeAttr(node.id)}" title="${escapeAttr(t("Drag to reorder"))}" aria-label="${escapeAttr(t("Drag to reorder"))}">::</span>
      </td>
      <th data-action="focus-story-node" data-node-id="${escapeAttr(node.id)}">
        <div class="event-node-link">
          <span>${escapeHtml(node.title || getNodeDisplayId(node))}</span>
          <small>${escapeHtml(getNodeTypeLabel(node.type))} ${escapeHtml(getNodeDisplayId(node))}</small>
        </div>
      </th>
      ${columns.map((column) => renderEventCell(node, column)).join("")}
      <td class="event-hidden-cell">${renderHiddenEventColumnRestoreControls(hiddenColumns)}</td>
    </tr>
  `;
}

function renderHiddenEventColumnRestoreControls(hiddenColumns) {
  if (!hiddenColumns.length) return `<span class="event-hidden-empty">${t("No hidden columns")}</span>`;
  return `
    <div class="event-hidden-controls">
      ${hiddenColumns.map((column) => `
        <button class="event-hidden-restore-button" type="button" data-action="show-event-column" data-event-column-key="${escapeAttr(column.key)}">
          ${escapeHtml(column.label)}
        </button>
      `).join("")}
    </div>
  `;
}

function renderEventCell(node, column) {
  const value = getNodeEventValue(node, column.key);
  if (column.readonly) {
    return `<td style="${eventColumnWidthStyle(column.width)}">${renderEventElementsCell(node)}</td>`;
  }
  const control = isMultilineEventField(column.key)
    ? `<textarea data-event-node-id="${escapeAttr(node.id)}" data-event-field="${column.key}">${escapeHtml(value)}</textarea>`
    : `<input data-event-node-id="${escapeAttr(node.id)}" data-event-field="${column.key}" value="${escapeAttr(value)}">`;
  return `<td style="${eventColumnWidthStyle(column.width)}">${control}</td>`;
}

function eventColumnWidthStyle(width) {
  const normalized = normalizeEventColumnWidth(width);
  return `width:${normalized}; min-width:${normalized};`;
}

function isMultilineEventField(key) {
  return key === "eventDescription" || key === "choices" || key === "characterEncountered";
}

function renderEventElementsCell(node) {
  const elements = getEventContainedNodes(node).map(formatEventElement);
  if (!elements.length) return `<div class="event-elements-cell empty">No contained nodes</div>`;
  if (elements.length <= 3) {
    return `<div class="event-elements-cell">${escapeHtml(elements.join("\n"))}</div>`;
  }
  const preview = elements.slice(0, 3).join("\n");
  return `
    <details class="event-elements-cell event-elements-collapsible">
      <summary>${escapeHtml(elements.length)} elements - show all</summary>
      <div class="event-elements-preview">${escapeHtml(preview)}</div>
      <div class="event-elements-full">${escapeHtml(elements.join("\n"))}</div>
    </details>
  `;
}

function getEventSheetColumns(eventType = null) {
  if (eventType) return getEventSheetColumnsForType(eventType);
  const hidden = getHiddenEventSheetColumns();
  const columns = getProjectEventSheetColumns().filter((column) => !hidden.has(column.key));
  const seen = new Set(columns.map((column) => column.key));
  getProjectNodeTypes()
    .filter(isEventSheetTypeDef)
    .flatMap((typeDef) => typeDef.fields || [])
    .forEach((field) => {
      if (!field?.key || seen.has(field.key)) return;
      if (hidden.has(field.key)) return;
      seen.add(field.key);
      columns.push({
        key: field.key,
        label: field.label || field.key,
        width: "180px",
        custom: true
      });
    });
  return columns;
}

// Columns for one frame type: the canonical built-in columns this type still keeps
// (per-type deletions removed), followed by the type's own custom fields. The same
// list drives the node inspector and that type's Events Sheet group, so the property
// count stays in sync between the two surfaces.
function getEventSheetColumnsForType(eventType) {
  const hidden = getHiddenEventSheetColumns();
  const typeDef = getProjectNodeTypes().find((item) => item.type === eventType);
  const eventColumnLabels = normalizeEventColumnLabels(typeDef?.eventColumnLabels);
  const removed = new Set(getTypeRemovedColumns(typeDef));
  const projectColumns = new Map(getProjectEventSheetColumns().map((column) => [column.key, column]));
  const columns = [];
  const seen = new Set();
  CORE_EVENT_COLUMN_KEYS.forEach((key) => {
    if (removed.has(key) || hidden.has(key)) return;
    const base = projectColumns.get(key) || eventSheetColumns.find((column) => column.key === key);
    if (!base) return;
    seen.add(key);
    columns.push(normalizeEventSheetColumn({
      ...base,
      label: eventColumnLabels[key] || base.label,
      custom: false
    }));
  });
  (typeDef?.fields || []).forEach((field) => {
    if (!field?.key || seen.has(field.key) || removed.has(field.key) || hidden.has(field.key)) return;
    seen.add(field.key);
    const stored = projectColumns.get(field.key);
    columns.push({
      key: field.key,
      label: field.label || stored?.label || field.key,
      width: normalizeEventColumnWidth(stored?.width || "180px"),
      custom: true
    });
  });
  return columns;
}

function getTypeRemovedColumns(typeDef) {
  return Array.isArray(typeDef?.removedColumns) ? typeDef.removedColumns : [];
}

function getHiddenEventSheetColumns() {
  const eventSheet = getProjectEventSheet();
  return new Set(eventSheet.hiddenColumns);
}

function getHiddenEventSheetColumnDefs(eventType = null) {
  const hidden = getHiddenEventSheetColumns();
  const typeDef = eventType ? getProjectNodeTypes().find((item) => item.type === eventType) : null;
  const eventColumnLabels = normalizeEventColumnLabels(typeDef?.eventColumnLabels);
  const defs = new Map();
  eventSheetColumns.forEach((column) => defs.set(column.key, column));
  getProjectEventSheetColumns().forEach((column) => defs.set(column.key, column));
  getProjectNodeTypes()
    .filter(isEventSheetTypeDef)
    .filter((typeDef) => !eventType || typeDef.type === eventType)
    .flatMap((typeDef) => typeDef.fields || [])
    .forEach((field) => {
      if (!field?.key) return;
      defs.set(field.key, {
        key: field.key,
        label: field.label || field.key,
        width: "180px",
        custom: true
      });
    });
  return [...hidden]
    .map((key) => defs.get(key) || { key, label: key, width: "180px", custom: true })
    .map((column) => {
      if (!column || !eventType) return column;
      const labelOverride = eventColumnLabels[column.key];
      if (!labelOverride) return column;
      return { ...column, label: labelOverride };
    })
    .filter((column) => column.key !== EVENT_ELEMENTS_COLUMN_KEY);
}

function getProjectEventSheet() {
  state.project.eventSheet = normalizeEventSheetConfig(state.project.eventSheet, state.project.eventSheetHiddenColumns);
  delete state.project.eventSheetHiddenColumns;
  return state.project.eventSheet;
}

function getProjectEventSheetColumns() {
  return getProjectEventSheet().columns;
}

function normalizeEventSheetConfig(value, legacyHiddenColumns = []) {
  const source = value && typeof value === "object" && !Array.isArray(value) ? value : {};
  return {
    columns: normalizeEventSheetColumns(source.columns),
    hiddenColumns: normalizeEventSheetHiddenColumns(source.hiddenColumns, legacyHiddenColumns)
  };
}

function normalizeEventSheetColumns(columns) {
  const sourceColumns = Array.isArray(columns) && !isLegacyDefaultEventSheetColumns(columns) ? columns : eventSheetColumns;
  const seen = new Set();
  return sourceColumns
    .map(normalizeEventSheetColumn)
    .filter((column) => {
      if (!column || column.key === EVENT_ELEMENTS_COLUMN_KEY || seen.has(column.key)) return false;
      seen.add(column.key);
      return true;
    });
}

function isLegacyDefaultEventSheetColumns(columns) {
  if (!Array.isArray(columns) || columns.length !== legacyEventSheetColumns.length) return false;
  return legacyEventSheetColumns.every((legacyColumn, index) => {
    const column = columns[index];
    return column?.key === legacyColumn.key
      && (!column.label || column.label === legacyColumn.label);
  });
}

function normalizeEventSheetColumn(column) {
  const rawKey = typeof column === "string" ? column : column?.key;
  const defaultColumn = eventSheetColumns.find((item) => item.key === rawKey);
  const key = String(rawKey || defaultColumn?.key || "").trim();
  if (!key) return null;
  const sourceWidth = typeof column === "object" ? column?.width : "";
  const width = key === "characterEncountered" && sourceWidth === "220px"
    ? defaultColumn?.width
    : sourceWidth || defaultColumn?.width;
  const sourceLabel = String((typeof column === "object" && column?.label) || defaultColumn?.label || key).trim() || key;
  const label = key === "characterEncountered" && ["Characters", "Character Encountered"].includes(sourceLabel)
    ? defaultColumn?.label || sourceLabel
    : sourceLabel;
  return {
    key,
    label,
    width: normalizeEventColumnWidth(width),
    readonly: Boolean((typeof column === "object" && column?.readonly) || defaultColumn?.readonly),
    custom: defaultColumn ? Boolean(typeof column === "object" && column?.custom) : true
  };
}

function normalizeEventColumnWidth(value) {
  const width = String(value || "180px").trim();
  if (!width) return "180px";
  if (typeof CSS !== "undefined" && typeof CSS.supports === "function" && CSS.supports("width", width)) return width;
  return /^(?:\d+(?:\.\d+)?(?:px|rem|em|%|vw|vh)|auto)$/.test(width) ? width : "180px";
}

function normalizeEventSheetHiddenColumns(hiddenColumns, legacyHiddenColumns) {
  const values = Array.isArray(hiddenColumns) ? hiddenColumns : legacyHiddenColumns;
  return Array.isArray(values) ? [...new Set(values.map(String).filter((key) => key && key !== EVENT_ELEMENTS_COLUMN_KEY))] : [];
}

function renameEventColumn(key, eventType = null) {
  const column = getEventColumnByKey(key, eventType);
  if (!column) return;
  showGenericTextInput({
    kicker: "Events Sheet",
    title: t("Rename {label}", { label: column.label }),
    label: "Column name",
    value: column.label,
    maxLength: 60,
    confirmLabel: "Rename",
    recordHistory: true,
    onConfirm: (nextLabel) => applyEventColumnRename(key, nextLabel, eventType)
  });
}

function applyEventColumnRename(key, nextLabel, eventType = null) {
  const column = getEventColumnByKey(key, eventType);
  if (!column) return false;
  const label = String(nextLabel).trim().slice(0, 60);
  if (!label) {
    setStatus("Column name is required.");
    return false;
  }

  const result = setEventColumnLabel(key, label, column, eventType);
  markProjectStructureChanged({ nodeTypes: Boolean(result?.nodeTypes) });
  renderEventSheetSchemaSurfaces();
  setStatus(`${column.label} renamed to ${label}.`);
  return true;
}

function setEventColumnLabel(key, label, column = getEventColumnByKey(key), eventType = null) {
  const eventSheetKey = String(key || "").trim();
  if (!eventSheetKey) return { nodeTypes: false };
  const eventSheet = getProjectEventSheet();
  const typeDef = eventType ? getProjectNodeTypes().find((item) => item.type === eventType && isEventSheetTypeDef(item)) : null;
  if (column?.custom && typeDef) {
    let updated = false;
    (typeDef.fields || [])
      .filter((field) => field.key === eventSheetKey)
      .forEach((field) => {
        field.label = label;
        updated = true;
      });
    return { nodeTypes: updated };
  }
  if (!column?.custom && typeDef) {
    const labels = normalizeEventColumnLabels(typeDef.eventColumnLabels);
    const base = eventSheet.columns.find((item) => item.key === eventSheetKey)
      || eventSheetColumns.find((item) => item.key === eventSheetKey);
    if (!base || base.label !== label) labels[eventSheetKey] = label;
    else delete labels[eventSheetKey];
    typeDef.eventColumnLabels = labels;
    return { nodeTypes: true };
  }

  let schemaColumn = eventSheet.columns.find((item) => item.key === eventSheetKey);
  if (!schemaColumn && !column?.custom) {
    const defaultColumn = eventSheetColumns.find((item) => item.key === eventSheetKey);
    if (defaultColumn) {
      schemaColumn = normalizeEventSheetColumn(defaultColumn);
      eventSheet.columns.push(schemaColumn);
    }
  }
  if (schemaColumn) schemaColumn.label = label;

  if (column?.custom) {
    getProjectNodeTypes()
      .filter(isEventSheetTypeDef)
      .forEach((typeDef) => {
        (typeDef.fields || [])
          .filter((field) => field.key === eventSheetKey)
          .forEach((field) => {
            field.label = label;
          });
      });
  }
  return { nodeTypes: Boolean(column?.custom) };
}

function normalizeEventColumnLabels(value) {
  if (!value || typeof value !== "object" || Array.isArray(value)) return {};
  const labels = {};
  Object.entries(value).forEach(([rawKey, rawLabel]) => {
    const key = String(rawKey || "").trim();
    const label = String(rawLabel || "").trim().slice(0, 60);
    if (!key || !label) return;
    labels[key] = label;
  });
  return labels;
}

function hideEventColumn(key) {
  const column = getEventColumnByKey(key);
  if (!column) return;
  const eventSheet = getProjectEventSheet();
  const targetKey = String(key);
  const hiddenColumns = eventSheet.hiddenColumns.includes(targetKey)
    ? eventSheet.hiddenColumns
    : [...eventSheet.hiddenColumns, targetKey];
  state.project.eventSheet = { ...eventSheet, hiddenColumns };
  markProjectStructureChanged();
  renderEventSheetSchemaSurfaces();
  setStatus(`${column.label} column hidden. Data kept.`);
}

function showEventColumn(key) {
  const eventSheet = getProjectEventSheet();
  const column = getEventColumnByKey(key) || getHiddenEventSheetColumnDefs().find((item) => item.key === key);
  const targetKey = String(key);
  state.project.eventSheet = {
    ...eventSheet,
    hiddenColumns: eventSheet.hiddenColumns.filter((item) => String(item) !== targetKey)
  };
  markProjectStructureChanged();
  renderEventSheetSchemaSurfaces();
  setStatus(`${column?.label || key} column shown.`);
}

// Deleting a column only affects the one frame type it was deleted from. A custom
// column drops the type's field; a built-in column is recorded in that type's
// removedColumns. Stored values are cleared on that type's nodes only, so other
// frame types and their new default nodes keep the column.
function deleteEventColumn(key, eventType = null) {
  const typeDef = eventType ? getProjectNodeTypes().find((item) => item.type === eventType) : null;
  if (!typeDef) {
    deleteEventColumnGlobally(key);
    return;
  }
  const column = getEventColumnByKey(key, eventType);
  if (!column) return;

  if (column.custom) {
    typeDef.fields = (typeDef.fields || []).filter((field) => field.key !== key);
  } else {
    const removed = new Set(getTypeRemovedColumns(typeDef));
    removed.add(key);
    typeDef.removedColumns = [...removed];
  }

  state.project.nodes
    .filter((node) => node.type === eventType)
    .forEach((node) => deleteNodeFieldValue(node, key));

  markProjectStructureChanged({ nodeTypes: true });
  renderEventSheetSchemaSurfaces();
  setStatus(`${column.label} column deleted from ${typeDef.label || eventType}.`);
}

function deleteEventColumnGlobally(key) {
  const column = getEventColumnByKey(key);
  if (!column) return;
  const eventSheet = getProjectEventSheet();
  eventSheet.columns = eventSheet.columns.filter((item) => item.key !== key);
  eventSheet.hiddenColumns = eventSheet.hiddenColumns.filter((item) => item !== key);
  if (column.custom) {
    getProjectNodeTypes()
      .filter(isEventSheetTypeDef)
      .forEach((typeDef) => {
        typeDef.fields = (typeDef.fields || []).filter((field) => field.key !== key);
      });
  }
  state.project.nodes
    .filter((node) => isEventSheetNode(node))
    .forEach((node) => deleteNodeFieldValue(node, key));
  markProjectStructureChanged({ nodeTypes: Boolean(column.custom) });
  renderEventSheetSchemaSurfaces();
  setStatus(`${column.label} column deleted.`);
}

function renderEventSheetSchemaSurfaces() {
  if (state.activeFileId === "events") {
    renderEventsSheetPage();
    markDocumentSurfaceRendered("events");
  }
  renderInspector();
  updateStatus();
  renderHistoryButtons();
}

function showGenericConfirm(options) {
  if (!dom.genericConfirmDialog?.showModal) {
    setStatus("Confirmation dialog is unavailable.");
    return false;
  }
  state.genericConfirmAction = {
    onConfirm: typeof options.onConfirm === "function" ? options.onConfirm : null,
    onSecondary: typeof options.onSecondary === "function" ? options.onSecondary : null,
    recordHistory: Boolean(options.recordHistory)
  };
  dom.genericConfirmKicker.textContent = t(options.kicker || "Confirm");
  dom.genericConfirmTitle.textContent = t(options.title || "Confirm action?");
  dom.genericConfirmBody.textContent = t(options.message || "");
  dom.genericConfirmButton.textContent = t(options.confirmLabel || "Confirm");
  dom.genericConfirmButton.classList.toggle("danger-button", options.danger !== false);
  dom.genericConfirmButton.classList.toggle("primary", options.danger === false);
  if (dom.genericConfirmSecondaryButton) {
    const hasSecondary = typeof options.onSecondary === "function";
    dom.genericConfirmSecondaryButton.hidden = !hasSecondary;
    dom.genericConfirmSecondaryButton.textContent = t(options.secondaryLabel || "Keep");
  }
  dom.genericConfirmDialog.returnValue = "";
  dom.genericConfirmDialog.showModal();
  return true;
}

function handleGenericConfirmClose() {
  resolveGenericConfirm(dom.genericConfirmDialog.returnValue);
}

function closeGenericConfirmDialog(returnValue) {
  dom.genericConfirmDialog.returnValue = returnValue;
  resolveGenericConfirm(returnValue);
  if (dom.genericConfirmDialog.open) dom.genericConfirmDialog.close(returnValue);
}

function resolveGenericConfirm(returnValue) {
  const pending = state.genericConfirmAction;
  state.genericConfirmAction = null;
  const callback = returnValue === "confirm"
    ? pending?.onConfirm
    : (returnValue === "secondary" ? pending?.onSecondary : null);
  if (!callback) return;
  const historyBefore = pending.recordHistory ? getHistorySnapshot() : null;
  try {
    const result = callback();
    if (result && typeof result.catch === "function") result.catch((error) => console.error(error));
  } catch (error) {
    console.error(error);
  }
  if (historyBefore) commitHistoryFromSnapshot(historyBefore);
}

function showGenericTextInput(options) {
  if (!dom.genericTextDialog?.showModal) {
    setStatus("Text input dialog is unavailable.");
    return false;
  }
  state.genericTextAction = {
    onConfirm: typeof options.onConfirm === "function" ? options.onConfirm : null,
    recordHistory: Boolean(options.recordHistory)
  };
  dom.genericTextKicker.textContent = t(options.kicker || "Edit");
  dom.genericTextTitle.textContent = t(options.title || "Edit value");
  dom.genericTextLabel.textContent = t(options.label || "Value");
  dom.genericTextInput.value = options.value || "";
  // Assigning "" coerces maxLength to 0 and blocks all typing; remove instead.
  if (options.maxLength) dom.genericTextInput.maxLength = String(options.maxLength);
  else dom.genericTextInput.removeAttribute("maxlength");
  dom.genericTextBody.textContent = t(options.message || "");
  dom.genericTextButton.textContent = t(options.confirmLabel || "Apply");
  dom.genericTextDialog.returnValue = "";
  dom.genericTextDialog.showModal();
  runAfterRender(() => {
    dom.genericTextInput.focus();
    dom.genericTextInput.select();
  });
  return true;
}

function handleGenericTextClose() {
  const pending = state.genericTextAction;
  state.genericTextAction = null;
  if (dom.genericTextDialog.returnValue !== "confirm" || !pending?.onConfirm) return;
  const historyBefore = pending.recordHistory ? getHistorySnapshot() : null;
  let changed = false;
  try {
    changed = pending.onConfirm(dom.genericTextInput.value) !== false;
  } catch (error) {
    console.error(error);
  }
  if (historyBefore && changed) commitHistoryFromSnapshot(historyBefore);
}

function showEventColumnDeleteConfirm(key, eventType = null) {
  const column = getEventColumnByKey(key, eventType);
  if (!column) return;
  state.eventColumnDeleteKey = key;
  state.eventColumnDeleteType = eventType;
  const typeLabel = eventType
    ? (getProjectNodeTypes().find((item) => item.type === eventType)?.label || eventType)
    : "";
  const scope = typeLabel
    ? t('the "{label}" frame type', { label: typeLabel })
    : t("the Events Sheet schema");
  const message = t('Hide only hides the column and keeps data. Delete removes "{label}" from {scope} and clears that value from its frame nodes. Other frame types keep the column.', {
    label: column.label,
    scope
  });
  const title = t("Delete {label} column?", { label: column.label });

  if (dom.eventColumnDeleteDialog?.showModal) {
    dom.eventColumnDeleteDialog.returnValue = "";
    dom.eventColumnDeleteTitle.textContent = title;
    dom.eventColumnDeleteBody.textContent = message;
    dom.eventColumnDeleteDialog.showModal();
    return;
  }

  showGenericConfirm({
    kicker: "Event Column",
    title,
    message,
    confirmLabel: "Delete",
    danger: true,
    recordHistory: true,
    onConfirm: () => deleteEventColumn(key, eventType)
  });
  state.eventColumnDeleteKey = null;
  state.eventColumnDeleteType = null;
}

function getEventColumnByKey(key, eventType = null) {
  const typed = eventType ? getEventSheetColumnsForType(eventType).find((item) => item.key === key) : null;
  return typed
    || getEventSheetColumns().find((item) => item.key === key)
    || eventSheetColumns.find((item) => item.key === key)
    || getAllCustomEventColumns().find((item) => item.key === key);
}

function getAllCustomEventColumns() {
  const columns = [];
  const seen = new Set([...eventSheetColumns.map((column) => column.key), EVENT_ELEMENTS_COLUMN_KEY]);
  getProjectNodeTypes()
    .filter(isEventSheetTypeDef)
    .flatMap((typeDef) => typeDef.fields || [])
    .forEach((field) => {
      if (!field?.key || seen.has(field.key)) return;
      seen.add(field.key);
      columns.push({
        key: field.key,
        label: field.label || field.key,
        width: "180px",
        custom: true
      });
    });
  return columns;
}

function deleteNodeFieldValue(node, key) {
  if (key === "choices") {
    delete node.choices;
  } else if (isDirectNodeField(key)) {
    delete node[key];
  }
  if (node.customFields && typeof node.customFields === "object" && !Array.isArray(node.customFields)) {
    delete node.customFields[key];
  }
}

function resetEventColumns() {
  state.project.eventSheet = normalizeEventSheetConfig(null);
  getProjectNodeTypes()
    .filter((typeDef) => isFrameKind(typeDef.kind))
    .forEach((typeDef) => {
      typeDef.removedColumns = [];
      typeDef.eventColumnLabels = {};
    });
  markProjectStructureChanged({ nodeTypes: true });
  renderAll();
  setStatus("Events Sheet columns restored.");
}

function showResetEventColumnsConfirm() {
  const message = "This restores the default Events Sheet columns. It removes column renames, hidden-column settings, column order changes, and custom sheet-only columns. Frame nodes are not deleted, and stored field values are not actively cleared; values from removed columns may stop showing until that field or column is added again.";
  if (dom.eventColumnsResetDialog?.showModal) {
    dom.eventColumnsResetDialog.returnValue = "";
    dom.eventColumnsResetDialog.showModal();
    return;
  }
  showGenericConfirm({
    kicker: "Events Sheet",
    title: "Reset sheet columns?",
    message,
    confirmLabel: "Reset columns",
    danger: true,
    recordHistory: true,
    onConfirm: resetEventColumns
  });
}

function renderVariableRows(entries, emptyLabel = "No variables yet.") {
  if (!entries.length) return `<div class="nc-empty-state">${t(emptyLabel)}</div>`;
  return getGroupedVariableEntries(entries)
    .map((group) => `
      <div class="variable-group-heading" data-variable-group="${escapeAttr(group.key)}">
        <span>${escapeHtml(group.label)}</span>
        <small>${t("{count} variables", { count: group.entries.length })}</small>
      </div>
      ${group.entries.map(([key, value]) => renderVariableRow(key, value)).join("")}
    `)
    .join("");
}

function getGroupedVariableEntries(entries) {
  const groups = new Map();
  entries.forEach(([key, value]) => {
    const groupKey = getVariableGroupKey(key);
    if (!groups.has(groupKey)) {
      groups.set(groupKey, {
        key: groupKey,
        label: formatVariableGroupLabel(groupKey),
        entries: []
      });
    }
    groups.get(groupKey).entries.push([key, value]);
  });
  return [...groups.values()];
}

function getVariableGroupKey(key) {
  const normalized = String(key || "").trim();
  if (!normalized) return "other";
  const splitIndexes = [normalized.indexOf("_"), normalized.indexOf(".")].filter((index) => index > 0);
  if (!splitIndexes.length) return "other";
  return normalized.slice(0, Math.min(...splitIndexes)).toLowerCase();
}

function formatVariableGroupLabel(groupKey) {
  if (groupKey === "other") return t("Other");
  return String(groupKey)
    .split(/[-\s]+/)
    .filter(Boolean)
    .map(titleCase)
    .join(" ");
}

function renderVariableRow(key, value) {
  const type = variableType(value);
  return `
    <div class="variable-row">
      <input data-variable-key="${escapeAttr(key)}" data-variable-field="key" value="${escapeAttr(key)}">
      <select data-variable-key="${escapeAttr(key)}" data-variable-field="type">
        ${["string", "number", "boolean", "json"].map((option) => `<option value="${option}" ${option === type ? "selected" : ""}>${option}</option>`).join("")}
      </select>
      <textarea class="variable-value-input" data-variable-key="${escapeAttr(key)}" data-variable-field="value" rows="1" spellcheck="false">${escapeHtml(formatVariableValue(value))}</textarea>
      ${renderPlaybookJsonButton(getPlaybookJsonPropertyToken(key))}
      <button class="icon-button danger-button" type="button" title="${escapeAttr(t("Delete variable"))}" aria-label="${escapeAttr(t("Delete variable"))}" data-action="delete-variable" data-variable-key="${escapeAttr(key)}">x</button>
    </div>
  `;
}

function renderPalette() {
  const entries = getNodeTypeEntries();
  const visibleRows = entries.length ? entries
    .map(([type, meta]) => {
      const deleteControl = meta.system
        ? `<button class="icon-button palette-delete-button system-lock-button" type="button" title="${escapeAttr(t("Delete node type"))}" aria-label="${escapeAttr(t("Delete node type"))}" data-action="delete-custom-node-type" data-custom-node-type="${escapeAttr(type)}">lock</button>`
        : `<button class="icon-button danger-button palette-delete-button" aria-label="${escapeAttr(t("Delete node type"))}" title="${escapeAttr(t("Delete node type"))}" data-action="delete-custom-node-type" data-custom-node-type="${escapeAttr(type)}">x</button>`;
      return `
        <div class="palette-row">
          <button class="palette-badge" type="button" data-action="edit-node-type-badge" data-node-type="${escapeAttr(type)}" data-icon-size="${getNodeIconSize(meta.badge)}" style="--node-color:${escapeAttr(meta.color)}" title="${escapeAttr(t("Edit node type"))}" aria-label="${escapeAttr(t("Edit node type"))}">${escapeHtml(meta.badge)}</button>
          <button class="palette-item" data-action="add-node" data-type="${escapeAttr(type)}">
            <span class="palette-label">${escapeHtml(getNodeTypeLabel(type))}</span>
          </button>
          <button class="icon-button palette-hide-button" aria-label="${escapeAttr(t("Hide node type"))}" title="${escapeAttr(t("Hide node type"))}" data-action="hide-node-type" data-node-type="${escapeAttr(type)}">-</button>
          ${deleteControl}
        </div>
      `;
    })
    .join("") : `<div class="custom-node-empty">${t("No visible node types.")}</div>`;
  dom.palette.innerHTML = `
    <div class="palette-tools">
      <button class="small-button" data-action="restore-default-node-types" type="button">${t("Restore default types")}</button>
    </div>
    ${renderHiddenNodeTypeSection()}
    ${visibleRows}
  `;
}

function renderHiddenNodeTypeSection() {
  const hiddenEntries = getHiddenNodeTypeEntries();
  return `
    <details class="hidden-node-types" ${hiddenEntries.length ? "open" : "data-empty=\"true\""}>
      <summary>
        <span>${t("Hidden")}</span>
        <span class="hidden-node-count">${hiddenEntries.length}</span>
      </summary>
      <div class="hidden-node-list">
        ${hiddenEntries.length ? hiddenEntries.map(([type, meta]) => `
          <div class="hidden-node-row">
            <button class="palette-badge hidden-node-badge" type="button" data-action="edit-node-type-badge" data-node-type="${escapeAttr(type)}" data-icon-size="${getNodeIconSize(meta.badge)}" style="--node-color:${escapeAttr(meta.color)}" title="${escapeAttr(t("Edit node type"))}" aria-label="${escapeAttr(t("Edit node type"))}">${escapeHtml(meta.badge)}</button>
            <span class="palette-label">${escapeHtml(getNodeTypeLabel(type))}</span>
            <button class="small-button restore-node-type-button" title="${escapeAttr(t("Restore node type"))}" data-action="restore-node-type" data-node-type="${escapeAttr(type)}">${t("Show")}</button>
          </div>
        `).join("") : `<div class="custom-node-empty">${t("No hidden node types.")}</div>`}
      </div>
    </details>
  `;
}

function renderTransform() {
  normalizeCanvasViewScroll();
  syncCanvasScrollBounds();
  const transform = `translate(${state.view.x}px, ${state.view.y}px) scale(${state.view.scale})`;
  dom.content.style.transform = "";
  if (dom.frameLayer) dom.frameLayer.style.transform = transform;
  dom.linkLayer.style.transform = transform;
  dom.nodeLayer.style.transform = transform;
  if (dom.marqueeLayer) dom.marqueeLayer.style.transform = transform;
  dom.zoomReadout.textContent = `${Math.round(state.view.scale * 100)}%`;
  updateGridPosition();
}

function normalizeCanvasViewScroll() {
  if (!dom.viewport) return;
  const scale = Math.max(CANVAS_MIN_ZOOM, state.view.scale || DEFAULT_CANVAS_ZOOM);
  const bounds = getCanvasScrollableBoardBounds();
  const minPixelX = state.view.x + bounds.left * scale;
  const minPixelY = state.view.y + bounds.top * scale;
  let shiftX = 0;
  let shiftY = 0;
  if (minPixelX < CANVAS_VIEW_PADDING) shiftX = CANVAS_VIEW_PADDING - minPixelX;
  if (minPixelY < CANVAS_VIEW_PADDING) shiftY = CANVAS_VIEW_PADDING - minPixelY;
  if (shiftX || shiftY) {
    state.view.x += shiftX;
    state.view.y += shiftY;
    dom.viewport.scrollLeft += shiftX;
    dom.viewport.scrollTop += shiftY;
  }
}

function syncCanvasScrollBounds() {
  if (!dom.content) return;
  const viewportWidth = dom.viewport?.clientWidth || 0;
  const viewportHeight = dom.viewport?.clientHeight || 0;
  const scale = Math.max(CANVAS_MIN_ZOOM, state.view.scale || DEFAULT_CANVAS_ZOOM);
  const bounds = getCanvasScrollableBoardBounds();
  const right = state.view.x + bounds.right * scale;
  const bottom = state.view.y + bounds.bottom * scale;
  const width = Math.ceil(Math.max(
    viewportWidth + CANVAS_VIEW_PADDING,
    right + CANVAS_FREE_EXPLORE_PADDING,
    (dom.viewport?.scrollLeft || 0) + viewportWidth + CANVAS_FREE_EXPLORE_PADDING
  ));
  const height = Math.ceil(Math.max(
    viewportHeight + CANVAS_VIEW_PADDING,
    bottom + CANVAS_FREE_EXPLORE_PADDING,
    (dom.viewport?.scrollTop || 0) + viewportHeight + CANVAS_FREE_EXPLORE_PADDING
  ));
  setCanvasScrollAreaSize(width, height);
}

function extendCanvasScrollBoundsForPan(left, top) {
  if (!dom.content || !dom.viewport) return;
  const viewportWidth = dom.viewport.clientWidth || 0;
  const viewportHeight = dom.viewport.clientHeight || 0;
  const currentWidth = dom.content.offsetWidth || 0;
  const currentHeight = dom.content.offsetHeight || 0;
  const width = Math.ceil(Math.max(currentWidth, left + viewportWidth + CANVAS_FREE_EXPLORE_PADDING));
  const height = Math.ceil(Math.max(currentHeight, top + viewportHeight + CANVAS_FREE_EXPLORE_PADDING));
  if (width !== currentWidth || height !== currentHeight) setCanvasScrollAreaSize(width, height);
}

function setCanvasScrollAreaSize(width, height) {
  dom.content.style.width = `${width}px`;
  dom.content.style.height = `${height}px`;
  [dom.frameLayer, dom.linkLayer, dom.nodeLayer, dom.marqueeLayer].forEach((layer) => {
    if (!layer) return;
    layer.style.width = `${width}px`;
    layer.style.height = `${height}px`;
  });
}

function getCanvasScrollableBoardBounds() {
  const projectBounds = getProjectBounds();
  const left = Math.min(0, projectBounds.x);
  const top = Math.min(0, projectBounds.y);
  const right = Math.max(BOARD_WIDTH, projectBounds.x + projectBounds.width);
  const bottom = Math.max(BOARD_HEIGHT, projectBounds.y + projectBounds.height);
  return { left, top, right, bottom, width: right - left, height: bottom - top };
}

function renderNodes(renderContext = getCanvasRenderContext()) {
  const query = renderContext.query;
  const focusedCharacterId = getActiveCharacterFocusId();
  const frameMarkup = [];
  const nodeMarkup = [];
  const visibleNodeIds = renderContext.visibleNodeIds;
  getCanvasLayerItems()
    .filter((item) => visibleNodeIds.has(item.node.id))
    .forEach(({ node, order }) => {
    const markup = renderCanvasNodeMarkup(node, query, focusedCharacterId, order);
    if (isFrameNode(node)) frameMarkup.push(markup);
    else nodeMarkup.push(markup);
  });
  if (dom.frameLayer) dom.frameLayer.innerHTML = frameMarkup.join("");
  dom.nodeLayer.innerHTML = nodeMarkup.join("");
  hydrateVaultFilePreviews();
  refreshGraphHoverClasses();
  refreshWorkspaceSearchCount();
}

function renderCanvasNodeMarkup(node, query, focusedCharacterId, layerOrder = getNodeLayerOrder(node, state.project.nodes.indexOf(node))) {
  const meta = getNodeMeta(node.type);
  const isSelected = node.id === state.selectedNodeId;
  const isMultiSelected = state.selectedNodeIds.includes(node.id);
  const isFrame = isFrameNode(node);
  const frameClass = isFrame ? (isEventSheetNode(node) ? "event-frame" : "visual-frame") : "";
  const match = query && nodeMatches(node, query);
  const characterFocusClass = focusedCharacterId
    ? (isNodeRelatedToCharacter(node, focusedCharacterId) ? "character-focus-match" : "character-focus-muted")
    : "";
  const size = nodeLayoutSize(node);
  const width = size.width;
  const height = size.height;
  const icon = getNodeIcon(node);
  const inlineEditField = node.id === state.inlineEditNodeId ? state.inlineEditField : "";
  const inputPoint = getInputPoint(node);
  const outputPoint = getOutputPoint(node);
  const inputPortStyle = `left:${inputPoint.x - node.x}px; top:${inputPoint.y - node.y}px; --node-color:${meta.color};`;
  const outputPortStyle = `left:${outputPoint.x - node.x}px; top:${outputPoint.y - node.y}px; --node-color:${meta.color};`;
  const frameBgOpacity = isFrame ? normalizeNodeTypeOpacity(meta.cardOpacity) : null;
  const nodeClasses = [
    "node",
    isFrame ? `frame ${frameClass}` : "",
    isChoiceNode(node) ? "choice-node" : "",
    isFrameCollapsed(node) ? "collapsed" : "",
    isSelected ? "selected" : "",
    isMultiSelected ? "multi-selected" : "",
    characterFocusClass
  ].filter(Boolean).join(" ");
  return `
    <div class="node-stack" data-node-stack-id="${escapeAttr(node.id)}" style="left:${node.x}px; top:${node.y}px; width:${width}px; height:${height}px; --node-layer-order:${Number(layerOrder) || 0};">
      <article class="${nodeClasses}" data-node-id="${escapeAttr(node.id)}" style="left:0; top:0; width:${width}px; height:${height}px; --node-color:${meta.color};${frameBgOpacity != null ? ` --node-bg-opacity:${frameBgOpacity}%;` : " "}${match ? " outline:1px solid var(--accent-orange);" : ""}">
        <div class="node-header" data-drag-handle="true" data-node-id="${escapeAttr(node.id)}">
          <button class="node-icon" type="button" data-action="edit-node-type-badge" data-node-type="${escapeAttr(node.type)}" data-node-id="${escapeAttr(node.id)}" data-no-drag="true" data-icon-size="${getNodeIconSize(icon)}" title="${escapeAttr(t("Edit node type"))}" aria-label="${escapeAttr(t("Edit node type"))}">${escapeHtml(icon)}</button>
          <span class="node-type">${escapeHtml(getNodeTypeLabel(node.type))}</span>
            <span class="node-id">${escapeHtml(node.id || getNodeDisplayId(node))}</span>
          ${isFrame ? `<button class="frame-canvas-button" type="button" data-action="open-frame-canvas" data-node-id="${escapeAttr(node.id)}" data-no-drag="true" title="${escapeAttr(t("Open frame canvas"))}" aria-label="${escapeAttr(t("Open frame canvas"))}">▣</button>` : ""}
          ${isFrame ? `<button class="frame-collapse-button" type="button" data-action="toggle-frame-collapse" data-node-id="${escapeAttr(node.id)}" data-no-drag="true" title="${escapeAttr(isFrameCollapsed(node) ? t("Expand frame") : t("Collapse frame"))}" aria-label="${escapeAttr(isFrameCollapsed(node) ? t("Expand frame") : t("Collapse frame"))}">${isFrameCollapsed(node) ? "+" : "-"}</button>` : ""}
        </div>
        <div class="node-body">
          ${renderChoiceFollowupLabels(node)}
          ${renderNodeTitle(node, inlineEditField)}
          ${renderNodeCastChips(node)}
          ${renderNodeCardContent(node, inlineEditField)}
          ${renderNodeVaultFileCard(node)}
        </div>
        <button class="node-resize-handle right" data-resize-handle="e" data-node-id="${escapeAttr(node.id)}" title="${escapeAttr(t("Resize width"))}" aria-label="${escapeAttr(t("Resize width"))}"></button>
        <button class="node-resize-handle bottom" data-resize-handle="s" data-node-id="${escapeAttr(node.id)}" title="${escapeAttr(t("Resize height"))}" aria-label="${escapeAttr(t("Resize height"))}"></button>
        <button class="node-resize-handle corner" data-resize-handle="se" data-node-id="${escapeAttr(node.id)}" title="${escapeAttr(t("Resize node"))}" aria-label="${escapeAttr(t("Resize node"))}"></button>
      </article>
      <button class="port input" style="${inputPortStyle}" data-port="input" data-node-id="${escapeAttr(node.id)}" title="${escapeAttr(t("Input"))}" aria-label="${escapeAttr(t("Input port"))}"></button>
      <button class="port output ${node.id === state.connectingFrom ? "active" : ""}" style="${outputPortStyle}" data-port="output" data-node-id="${escapeAttr(node.id)}" title="${escapeAttr(t("Output"))}" aria-label="${escapeAttr(t("Output port"))}"></button>
    </div>
  `;
}

function renderChoiceFollowupLabels(node) {
  const entries = getChoiceFollowupEntries(node);
  if (!entries.length) return "";
  const renderedEntries = entries.map((entry) => ({
    ...entry,
    text: t("Choice: {label}", { label: entry.label }),
    focusLabel: t("Focus source Choice node: {label}", { label: entry.label })
  }));
  return `<div class="node-choice-followup" aria-label="${escapeAttr(renderedEntries.map((entry) => entry.text).join(" / "))}">${renderedEntries.map((entry) => `<button class="node-choice-followup-button" type="button" data-action="focus-choice-source" data-choice-source-node-id="${escapeAttr(entry.sourceNodeId)}" data-no-drag="true" aria-label="${escapeAttr(entry.focusLabel)}">${escapeHtml(entry.text)}</button>`).join("")}</div>`;
}

function getChoiceFollowupLabels(node) {
  return getChoiceFollowupEntries(node).map((entry) => entry.label);
}

function getChoiceFollowupEntries(node) {
  if (!node?.id) return [];
  return getChoiceFollowupLabelMap().get(node.id) || [];
}

function getChoiceFollowupLabelMap() {
  const cached = state.derived.choiceFollowupLabels;
  if (cached?.dirtyVersion === state.dirtyVersion && cached?.structureVersion === state.structureVersion) return cached.map;
  const map = new Map();
  const nodeMap = new Map((state.project?.nodes || []).map((node) => [node.id, node]));
  (state.project?.links || []).forEach((link) => {
    const source = nodeMap.get(link.from);
    if (!source || !isChoiceNode(source) || !link.to) return;
    const options = Array.isArray(source.choiceOptions) ? source.choiceOptions : [];
    const choiceIndex = normalizeChoiceIndex(link.choiceIndex);
    const option = (link.choiceOptionId ? options.find((entry) => entry?.id === link.choiceOptionId) : null)
      || (choiceIndex != null ? options[choiceIndex] : null);
    const legacyChoice = choiceIndex != null && Array.isArray(source.choices) ? source.choices[choiceIndex] : "";
    const label = stripChoiceDisplayOrdinal(normalizeOptionalString(option?.label || link.label || legacyChoice).trim());
    if (!label) return;
    const entries = map.get(link.to) || [];
    if (!entries.some((entry) => entry.label === label && entry.sourceNodeId === source.id)) {
      entries.push({ label, sourceNodeId: source.id });
    }
    map.set(link.to, entries);
  });
  state.derived.choiceFollowupLabels = { dirtyVersion: state.dirtyVersion, structureVersion: state.structureVersion, map };
  return map;
}

function renderNodeTitle(node, inlineEditField) {
  if (inlineEditField === "title") {
    return `<input class="node-inline-editor node-inline-title" data-inline-node-field="title" data-node-id="${escapeAttr(node.id)}" data-no-drag="true" value="${escapeAttr(getInlineNodeFieldValue(node, "title"))}" aria-label="Edit node title">`;
  }
  return `<div class="node-title">${escapeHtml(getNodeDisplayTitle(node, "Untitled"))}</div>`;
}

function renderNodeText(node, inlineEditField) {
  if (inlineEditField && inlineEditField !== "title") {
    return `<textarea class="node-inline-editor node-inline-text" data-inline-node-field="${escapeAttr(inlineEditField)}" data-node-id="${escapeAttr(node.id)}" data-no-drag="true" aria-label="Edit node content">${escapeHtml(getInlineNodeFieldValue(node, inlineEditField))}</textarea>`;
  }
  const body = displayBody(node);
  // Non-edit cards render the Markdown so bold/italic/heading/quote/list show as
  // formatted text; the raw markers only appear once you click in to edit.
  return `<div class="node-text node-text-rendered play-body-text">${renderNarrativeRichText(body)}</div>`;
}

function renderNodeCardContent(node, inlineEditField) {
  if (inlineEditField) return renderNodeText(node, inlineEditField);
  if (isChoiceNode(node)) return renderChoiceNodeCardContent(node);
  if (isDialogNode(node) && Array.isArray(node.turns) && node.turns.length) return renderDialogNodeCardContent(node);
  return `${renderNodeText(node, inlineEditField)}${hasNodeChoices(node) ? `<div class="node-meta">${t("{count} choices", { count: node.choices.length })}</div>` : ""}`;
}

function renderNodeVaultFileCard(node) {
  // Frames organize the canvas; they do not carry vault file links.
  if (isFrameNode(node)) return "";
  const host = window.NarrativeCanvasHost;
  const references = getNodeVaultFiles(node);
  if (!host?.readVaultFile || !references.length) return "";
  return `<div class="node-vault-links" data-no-drag="true">${references.map((entry, index) => {
    const parts = entry.path.split("/");
    const name = parts.pop() || entry.path;
    const folder = parts.join("/");
    return `
      <section class="node-vault-link${entry.preview ? " is-previewing" : ""}" data-no-drag="true">
        <div class="node-vault-link-row">
          <button class="node-vault-open" type="button" data-action="open-node-vault-file" data-node-id="${escapeAttr(node.id)}" data-node-vault-file-index="${index}" data-no-drag="true" title="${escapeAttr(t("Open vault file"))}">
            <span class="node-vault-open-icon" aria-hidden="true">↗</span>
            <span class="node-vault-open-text"><strong>${escapeHtml(name)}</strong>${folder ? `<small>${escapeHtml(folder)}</small>` : ""}</span>
          </button>
          ${entry.preview && CODEX_IMAGE_FILE_PATTERN.test(entry.path) ? `
            <input type="range" class="node-vault-size-slider" data-node-vault-size-slider data-node-id="${escapeAttr(node.id)}" data-node-vault-file-index="${index}" min="48" max="320" step="4" value="${normalizeVaultPreviewSize(entry.previewSize)}" data-no-drag="true" title="${escapeAttr(t("Image preview size"))}" aria-label="${escapeAttr(t("Image preview size"))}">
          ` : ""}
          ${renderNodeVaultPreviewSwitch(node, index, true)}
        </div>
        ${entry.preview ? `<div class="node-vault-preview" style="--vault-preview-h:${normalizeVaultPreviewSize(entry.previewSize)}px" data-vault-file-preview data-node-vault-preview-index="${index}" data-vault-file-path="${escapeAttr(entry.path)}" aria-live="polite">${escapeHtml(t("Loading linked file..."))}</div>` : ""}
      </section>
    `;
  }).join("")}</div>`;
}

function renderNodeVaultPreviewSwitch(node, index = 0, compact = false) {
  const enabled = Boolean(getNodeVaultFiles(node)[index]?.preview);
  const label = t("Preview linked file on canvas");
  return `
    <button class="vault-preview-toggle${enabled ? " is-enabled" : ""}${compact ? " is-compact" : ""}" type="button" role="switch" aria-checked="${enabled ? "true" : "false"}" aria-label="${escapeAttr(label)}" title="${escapeAttr(label)}" data-action="toggle-node-vault-preview" data-node-id="${escapeAttr(node?.id || "")}" data-node-vault-file-index="${index}" data-no-drag="true">
      <span class="vault-preview-toggle-track" aria-hidden="true"><span class="vault-preview-toggle-thumb"></span></span>
    </button>
  `;
}

function hydrateVaultFilePreviews() {
  const host = window.NarrativeCanvasHost;
  if (!host?.readVaultFile || !dom.nodeLayer) return;
  const previews = Array.from(dom.nodeLayer.querySelectorAll("[data-vault-file-preview]"));
  const paths = [...new Set(previews.map((element) => normalizeNodeVaultFileReference(element.dataset.vaultFilePath)).filter(Boolean))];
  paths.forEach((path) => { void loadVaultFilePreview(path); });
}

async function loadVaultFilePreview(path) {
  const host = window.NarrativeCanvasHost;
  if (!host?.readVaultFile || !path) return;
  const now = Date.now();
  // Image files render as images, not as their source text.
  if (CODEX_IMAGE_FILE_PATTERN.test(path) && host.getVaultResourceUrl) {
    const image = { status: "loaded", loadedAt: now, text: "", sourcePath: path, isMarkdown: false, isImage: true, imageUrl: host.getVaultResourceUrl(path), error: "" };
    state.vaultFilePreviewCache.set(path, image);
    patchVaultFilePreview(path, image);
    return;
  }
  const cached = state.vaultFilePreviewCache.get(path);
  if (cached?.status === "loading") return;
  if (cached && now - cached.loadedAt < 1500) {
    patchVaultFilePreview(path, cached);
    return;
  }
  const loading = { status: "loading", loadedAt: now, text: "", error: "" };
  state.vaultFilePreviewCache.set(path, loading);
  patchVaultFilePreview(path, loading);
  try {
    const result = await host.readVaultFile(path);
    const text = typeof result === "string" ? result : String(result?.text || "");
    const sourcePath = typeof result === "string" ? path : normalizeNodeVaultFileReference(result?.path) || path;
    const isMarkdown = typeof result === "string"
      ? /\.(?:md|markdown)$/i.test(sourcePath)
      : Boolean(result?.isMarkdown ?? /\.(?:md|markdown)$/i.test(sourcePath));
    const loaded = { status: "loaded", loadedAt: Date.now(), text: formatVaultFilePreviewText(text), sourcePath, isMarkdown, error: "" };
    state.vaultFilePreviewCache.set(path, loaded);
    patchVaultFilePreview(path, loaded);
  } catch (error) {
    console.error(error);
    const failed = { status: "error", loadedAt: Date.now(), text: "", error: t("Could not preview the linked vault file.") };
    state.vaultFilePreviewCache.set(path, failed);
    patchVaultFilePreview(path, failed);
  }
}

function patchVaultFilePreview(path, entry) {
  const host = window.NarrativeCanvasHost;
  if (!dom.nodeLayer) return;
  dom.nodeLayer.querySelectorAll("[data-vault-file-preview]").forEach((element) => {
    if (normalizeNodeVaultFileReference(element.dataset.vaultFilePath) !== path) return;
    element.classList.toggle("is-loading", entry.status === "loading");
    element.classList.toggle("is-error", entry.status === "error");
    element.classList.toggle("is-markdown", entry.status === "loaded" && Boolean(entry.isMarkdown));
    element.classList.toggle("is-image", entry.status === "loaded" && Boolean(entry.isImage));
    if (entry.status === "loading") element.textContent = t("Loading linked file...");
    else if (entry.status === "error") element.textContent = entry.error || t("Could not preview the linked vault file.");
    else if (entry.isImage) {
      if (entry.imageUrl) {
        const img = document.createElement("img");
        img.src = entry.imageUrl;
        img.alt = "";
        img.draggable = false;
        img.loading = "lazy";
        element.replaceChildren(img);
      } else {
        element.textContent = t("Could not preview the linked vault file.");
      }
    }
    else if (!entry.text) element.textContent = t("Linked file is empty.");
    else if (entry.isMarkdown && host?.renderVaultMarkdown) {
      const renderToken = String(entry.loadedAt || Date.now());
      element.dataset.vaultMarkdownRender = renderToken;
      element.replaceChildren();
      void Promise.resolve(host.renderVaultMarkdown(entry.text, element, entry.sourcePath || path)).catch((error) => {
        console.error(error);
        if (element.dataset.vaultMarkdownRender === renderToken) {
          element.classList.remove("is-markdown");
          element.textContent = entry.text;
        }
      });
    } else {
      element.textContent = entry.text;
    }
  });
}

function formatVaultFilePreviewText(value) {
  const text = String(value || "").replace(/\r\n?/g, "\n").trim();
  if (text.length <= 6000) return text;
  return `${text.slice(0, 6000).trimEnd()}\n…`;
}

function renderChoiceNodeCardContent(node) {
  const options = Array.isArray(node.choiceOptions) && node.choiceOptions.length
    ? node.choiceOptions.map((option, index) => ({ id: normalizeOptionalString(option?.id), label: normalizeOptionalString(option?.label), index })).filter((option) => option.label)
    : (Array.isArray(node.choices) ? node.choices.map((label, index) => ({ id: "", label: normalizeOptionalString(label), index })).filter((option) => option.label) : []);
  return `
    ${node.body ? `<div class="node-text node-text-summary">${escapeHtml(displayBody(node))}</div>` : ""}
    <ol class="node-choice-preview" aria-label="${escapeAttr(t("Choices"))}" tabindex="0">
      ${options.map((option, index) => {
        const displayLabel = stripChoiceDisplayOrdinal(option.label);
        const successorLink = findChoiceOptionLink(option, option.index, getOutgoing(node.id));
        const successor = successorLink?.to ? getNode(successorLink.to) : null;
        const focusLabel = successor
          ? t("Focus next node: {title}", { title: successor.title || getNodeDisplayId(successor) })
          : t("No linked next node");
        const focusAttributes = successor
          ? `data-action="focus-canvas-node" data-node-id="${escapeAttr(successor.id)}"`
          : "disabled";
        const optionHoverAttributes = `data-canvas-choice-option="true" data-choice-node-id="${escapeAttr(node.id)}" data-choice-option-id="${escapeAttr(option.id)}" data-choice-option-index="${option.index}"`;
        return `<li><button class="node-choice-index" type="button" ${focusAttributes} ${optionHoverAttributes} data-no-drag="true" title="${escapeAttr(focusLabel)}" aria-label="${escapeAttr(focusLabel)}">${index + 1}</button><input class="node-choice-label-input" ${optionHoverAttributes} data-choice-option-field="label" data-choice-initial-value="${escapeAttr(option.label)}" data-no-drag="true" value="${escapeAttr(displayLabel)}" title="${escapeAttr(t("Edit choice option"))}" aria-label="${escapeAttr(t("Edit choice option"))}"></li>`;
      }).join("")}
    </ol>
  `;
}

function stripChoiceDisplayOrdinal(value) {
  const source = normalizeOptionalString(value).trim();
  const stripped = source.replace(/^(?:[①②③④⑤⑥⑦⑧⑨⑩⑪⑫⑬⑭⑮⑯⑰⑱⑲⑳]|\(\d+\)|\d+[.)、:：])\s*/, "").trim();
  return stripped || source;
}

function renderDialogNodeCardContent(node) {
  const speakerRatio = normalizeDialogSpeakerRatio(node.dialogSpeakerRatio);
  return `
    <div class="node-dialog-preview" data-dialog-node-id="${escapeAttr(node.id)}" role="region" aria-label="${escapeAttr(t("Dialog"))}" tabindex="0" style="--dialog-speaker-ratio:${speakerRatio}%">
      ${node.turns.map((turn, index) => {
        const speaker = normalizeOptionalString(turn?.speaker);
        const line = normalizeOptionalString(turn?.line);
        return `<div class="node-dialog-line"><input class="node-dialog-speaker-input" data-canvas-dialog-turn="true" data-dialog-node-id="${escapeAttr(node.id)}" data-dialog-turn-index="${index}" data-dialog-turn-field="speaker" data-dialog-initial-value="${escapeAttr(speaker)}" data-no-drag="true" value="${escapeAttr(speaker)}" placeholder="${escapeAttr(t("Speaker"))}" aria-label="${escapeAttr(t("Speaker"))}"><span class="node-dialog-separator" data-dialog-column-resize="true" data-dialog-node-id="${escapeAttr(node.id)}" data-no-drag="true" role="separator" aria-orientation="vertical" aria-label="${escapeAttr(t("Resize speaker column"))}" title="${escapeAttr(t("Resize speaker column"))}">:</span><textarea class="node-dialog-line-input" data-canvas-dialog-turn="true" data-dialog-node-id="${escapeAttr(node.id)}" data-dialog-turn-index="${index}" data-dialog-turn-field="line" data-dialog-initial-value="${escapeAttr(line)}" data-no-drag="true" rows="1" placeholder="${escapeAttr(t("Line"))}" aria-label="${escapeAttr(t("Line"))}">${escapeHtml(line)}</textarea></div>`;
      }).join("")}
    </div>
  `;
}

function getInlineEditableField(node) {
  return "body";
}

function getActiveInlineEditField(node) {
  return node?.id && node.id === state.inlineEditNodeId ? state.inlineEditField : "";
}

function getInlineNodeFieldValue(node, field) {
  if (!INLINE_NODE_FIELD_KEYS.has(field)) return "";
  const value = node?.[field];
  return value == null ? "" : String(value);
}

function minInlineNodeEditHeight(field) {
  return field === "title" ? 112 : 154;
}

function setInlineNodeField(nodeId, field, value) {
  if (!INLINE_NODE_FIELD_KEYS.has(field)) return;
  const node = getNode(nodeId);
  if (!node) return;
  invalidateCharacterRenderContext();
  node[field] = value;
  state.selectedNodeId = nodeId;
  state.selectedNodeIds = [];
  state.selectedLinkId = null;
  state.panel = "node";
  setProjectDirty(true);
  renderNodePanel(node);
  scheduleStoryPanelRender();
  updateStatus();
}

function finishInlineNodeEdit(nodeId = state.inlineEditNodeId) {
  if (!state.inlineEditNodeId && !state.inlineEditField) return;
  state.inlineEditNodeId = null;
  state.inlineEditField = null;
  state.inlineEditPointerNodeId = null;
  renderNodes();
  renderLinks();
  markCanvasSurfaceRenderedIfActive();
  const node = getNode(nodeId);
  if (node && state.panel === "node") renderNodePanel(node);
  scheduleStoryPanelRender();
  updateStatus();
}

function focusInlineNodeEditor(nodeId) {
  const editor = getNodeElementById(nodeId)?.querySelector("[data-inline-node-field]");
  if (!editor) return false;
  try {
    editor.focus({ preventScroll: true });
  } catch (error) {
    editor.focus();
  }
  if (typeof editor.setSelectionRange === "function") {
    const position = editor.value.length;
    editor.setSelectionRange(position, position);
  }
  return true;
}

function getCanvasNodeIdFromTarget(target) {
  return target?.closest?.(".node[data-node-id]")?.dataset?.nodeId || "";
}

function rememberInlineEditPointerTarget(target) {
  if (!state.inlineEditNodeId) {
    state.inlineEditPointerNodeId = null;
    return;
  }
  const nodeId = getCanvasNodeIdFromTarget(target);
  state.inlineEditPointerNodeId = nodeId;
  window.requestAnimationFrame(() => {
    if (state.inlineEditPointerNodeId === nodeId) state.inlineEditPointerNodeId = null;
  });
}

function isActiveInlineEditNodeTarget(target) {
  return Boolean(state.inlineEditNodeId && getCanvasNodeIdFromTarget(target) === state.inlineEditNodeId);
}

function shouldKeepInlineNodeEditForTarget(target) {
  return isActiveInlineEditNodeTarget(target) && !isCanvasNodeInlineEditBlockedTarget(target);
}

function shouldKeepInlineNodeEditOnFocusOut(nodeId, relatedTarget) {
  if (!nodeId || nodeId !== state.inlineEditNodeId) return false;
  if (relatedTarget && getCanvasNodeIdFromTarget(relatedTarget) === nodeId) return true;
  return state.inlineEditPointerNodeId === nodeId;
}

function getCanvasRenderContext(query = state.search.trim().toLowerCase()) {
  const matchNodeIds = query ? getCanvasSearchMatchIdSet(query) : null;
  const activeFrame = getActiveFrameCanvas();
  if (matchNodeIds && activeFrame) {
    matchNodeIds.forEach((id) => {
      const node = getNode(id);
      if (!isNodeWithinFrameCanvas(node, activeFrame.id)) matchNodeIds.delete(id);
    });
  }
  return {
    query,
    matchNodeIds,
    visibleNodeIds: getCanvasVisibleNodeIds(query, matchNodeIds),
    nodeMap: getNodeIndex(),
    matchCount: matchNodeIds ? matchNodeIds.size : 0
  };
}

function scheduleCanvasViewportRender() {
  if (!isCanvasFileActive() || state.canvasViewportRenderFrame) return;
  state.canvasViewportRenderFrame = window.requestAnimationFrame(() => {
    state.canvasViewportRenderFrame = null;
    renderCanvasViewportNow();
  });
}

function renderCanvasViewportNow() {
  if (!isCanvasFileActive()) return;
  if (state.canvasViewportRenderFrame) {
    window.cancelAnimationFrame(state.canvasViewportRenderFrame);
    state.canvasViewportRenderFrame = null;
  }
  const canvasRenderContext = getCanvasRenderContext();
  renderNodes(canvasRenderContext);
  renderLinks(canvasRenderContext);
  markCanvasSurfaceRendered();
}

function getCanvasViewportBounds(padding = CANVAS_RENDER_PADDING) {
  if (!dom.viewport) {
    return {
      left: -padding,
      top: -padding,
      right: BOARD_WIDTH + padding,
      bottom: BOARD_HEIGHT + padding
    };
  }
  const scale = Math.max(CANVAS_MIN_ZOOM, state.view.scale || DEFAULT_CANVAS_ZOOM);
  const left = (dom.viewport.scrollLeft - state.view.x) / scale - padding;
  const top = (dom.viewport.scrollTop - state.view.y) / scale - padding;
  const width = (dom.viewport.clientWidth || 0) / scale + padding * 2;
  const height = (dom.viewport.clientHeight || 0) / scale + padding * 2;
  return {
    left,
    top,
    right: left + width,
    bottom: top + height
  };
}

function shouldForceCanvasNodeRender(node, query, matchNodeIds = null) {
  if (!node) return false;
  if (node.id === state.selectedNodeId || state.selectedNodeIds.includes(node.id)) return true;
  if (node.id === state.connectingFrom || node.id === state.contextNodeId) return true;
  if (query && matchNodeIds?.has(node.id)) return true;
  return false;
}

function boundsIntersect(a, b) {
  return a.left <= b.right && a.right >= b.left && a.top <= b.bottom && a.bottom >= b.top;
}

function getCanvasVisibleNodeIds(query = state.search.trim().toLowerCase(), matchNodeIds = null) {
  const bounds = getCanvasViewportBounds();
  const ids = new Set();
  const activeFrame = getActiveFrameCanvas();
  const frameCanvasNodeIds = activeFrame ? getFrameCanvasNodeIdSet(activeFrame.id) : null;
  state.project.nodes.forEach((node) => {
    if (frameCanvasNodeIds && !frameCanvasNodeIds.has(node.id)) return;
    if (isNodeHiddenByCollapsedFrame(node, activeFrame?.id || "")) return;
    if (shouldForceCanvasNodeRender(node, query, matchNodeIds) || boundsIntersect(getNodeBounds(node), bounds)) {
      ids.add(node.id);
    }
  });
  return ids;
}

function isFrameCollapsed(node) {
  return Boolean(node && isFrameNode(node) && node.collapsed);
}

function isNodeHiddenByCollapsedFrame(node, ignoredFrameId = "") {
  return Boolean(getCollapsedFrameForNode(node, ignoredFrameId));
}

function getCollapsedFrameForNode(node, ignoredFrameId = "") {
  if (!node) return null;
  const nodeMap = getNodeIndex();
  let current = normalizeOptionalString(node.frameId).trim();
  const seen = new Set();
  while (current) {
    if (seen.has(current)) return null;
    seen.add(current);
    const frame = nodeMap.get(current);
    if (!frame || !isFrameNode(frame)) return null;
    if (!isCollapsedFrameIgnoredForCanvas(frame.id, ignoredFrameId) && isFrameCollapsed(frame)) return frame;
    current = normalizeOptionalString(frame.frameId).trim();
  }
  return null;
}

function isCollapsedFrameIgnoredForCanvas(frameId, activeFrameId) {
  if (!frameId || !activeFrameId) return false;
  if (frameId === activeFrameId) return true;
  const activeFrame = getNode(activeFrameId);
  return Boolean(activeFrame && isFrameDescendantOf(activeFrame, frameId));
}

function getRenderedLinkEndpoints(link, nodeMap = getNodeIndex(), options = {}) {
  const rawFrom = nodeMap.get(link.from);
  const rawTo = nodeMap.get(link.to);
  if (!rawFrom || !rawTo) return null;
  const ignoredFrameId = options.ignoredCollapsedFrameId || "";
  const fromFrame = getCollapsedFrameForNode(rawFrom, ignoredFrameId);
  const toFrame = getCollapsedFrameForNode(rawTo, ignoredFrameId);
  if (fromFrame && toFrame && fromFrame.id === toFrame.id) return null;
  const from = fromFrame || rawFrom;
  const to = toFrame || rawTo;
  if (!from || !to || from.id === to.id) return null;
  return { from, to };
}

function getNodeTypeLabel(type) {
  const meta = getNodeMeta(type);
  if (meta.label) return meta.label;
  return type === "Event" ? "Frame" : type;
}

function getNodeDisplayTitle(node, fallback = "Untitled") {
  const title = node?.title || fallback;
  if (!node || !isFrameNode(node)) return title;
  const prefix = getEventFrameTitlePrefix(node);
  return prefix ? `${prefix} ${title}` : title;
}

function getEventFrameTitlePrefix(node) {
  if (!isFrameNode(node)) return "";
  const typeDef = getProjectNodeTypes().find((item) => item.type === node.type);
  const removedColumns = new Set(getTypeRemovedColumns(typeDef));
  const act = removedColumns.has("act") ? "" : String(getNodeEventValue(node, "act") || "").trim();
  const chapter = removedColumns.has("chapter") ? "" : String(getNodeEventValue(node, "chapter") || "").trim();
  const parts = [];
  if (act) parts.push(`Act ${act}`);
  if (chapter) parts.push(`Ch. ${chapter}`);
  return parts.length ? `${parts.join(" - ")} - ` : "";
}

function getNodeMeta(type) {
  return getNodeTypeMap()[type] || getFallbackNodeMeta(type);
}

function getNodeTypeMap() {
  const types = getProjectNodeTypes();
  const cache = state.derived.nodeTypeMap;
  if (cache && cache.source === types) return cache.value;
  const map = {};
  types.forEach((typeDef) => {
    map[typeDef.type] = {
      badge: typeDef.badge,
      color: typeDef.color,
      width: typeDef.width,
      label: typeDef.label,
      custom: Boolean(typeDef.custom),
      kind: typeDef.kind,
      template: getNodeTypeTemplate(typeDef),
      fields: typeDef.fields || [],
      hidden: Boolean(typeDef.hidden),
      eventSheetHidden: Boolean(typeDef.eventSheetHidden),
      cardOpacity: normalizeNodeTypeOpacity(typeDef.cardOpacity),
      system: Boolean(typeDef.system),
    };
  });
  state.derived.nodeTypeMap = { source: types, value: map };
  return map;
}

function getFallbackNodeMeta(type) {
  const builtIn = nodeTypes[type];
  if (builtIn) {
    return {
      ...builtIn,
      label: getDefaultNodeTypeLabel(type),
      kind: type === "Event" ? "frame" : "node",
      template: getBuiltInNodeTypeTemplate(type, type === "Event" ? "frame" : "node"),
      fields: [],
      hidden: false,
      eventSheetHidden: false,
      cardOpacity: 20,
      system: Boolean(builtIn.system),
    };
  }
  return { ...FALLBACK_NODE_META, label: type || FALLBACK_NODE_META.label, kind: "node", fields: [], hidden: false, eventSheetHidden: false, cardOpacity: 100, system: false };
}

function defaultNodeTypeList() {
  const builtIns = Object.entries(nodeTypes).map(([type, meta]) => ({
    type,
    label: getDefaultNodeTypeLabel(type),
    badge: getDefaultNodeTypeBadge(getDefaultNodeTypeLabel(type)),
    color: meta.color,
    width: meta.width,
    custom: false,
    kind: type === "Event" ? "frame" : "node",
    template: getBuiltInNodeTypeTemplate(type, type === "Event" ? "frame" : "node"),
    fields: [],
    hidden: false,
    eventSheetHidden: false,
    cardOpacity: 20,
    system: Boolean(meta.system),
  }));
  const advanced = defaultAdvancedNodeTypes.map((typeDef) => ({
    type: typeDef.type,
    label: typeDef.label,
    badge: getNormalizedNodeTypeBadge(typeDef.badge),
    color: normalizeNodeTypeColor(typeDef.type, typeDef.kind, typeDef.color),
    width: clamp(Number(typeDef.width) || (isFrameKind(typeDef.kind) ? 540 : 240), 160, isFrameKind(typeDef.kind) ? 860 : 420),
    custom: false,
    badgeCustom: Boolean(typeDef.badgeCustom),
    kind: isFrameKind(typeDef.kind) ? "frame" : "node",
    template: isFrameKind(typeDef.kind) ? "frame" : "node",
    fields: normalizeNodeTypeFields(typeDef.fields),
    hidden: Boolean(typeDef.hidden),
    eventSheetHidden: isFrameKind(typeDef.kind) ? Boolean(typeDef.eventSheetHidden) : false,
    cardOpacity: 20,
    system: true,
  }));
  const builtInTypes = new Map([...builtIns, ...advanced].map((typeDef) => [typeDef.type, typeDef]));
  SPECIAL_EDITOR_NODE_TYPES.forEach((type) => {
    if (builtInTypes.has(type)) return;
    const meta = nodeTypes[type];
    if (!meta) return;
    builtInTypes.set(type, {
      type,
      label: getDefaultNodeTypeLabel(type),
      badge: getDefaultNodeTypeBadge(getDefaultNodeTypeLabel(type)),
      color: meta.color,
      width: meta.width,
      custom: false,
      kind: type === "Event" ? "frame" : "node",
      template: getBuiltInNodeTypeTemplate(type, type === "Event" ? "frame" : "node"),
      fields: [],
      hidden: false,
      eventSheetHidden: false,
      system: Boolean(meta.system),
    });
  });
  return [...builtInTypes.values()];
}

function visibleDefaultNodeTypeList() {
  return defaultNodeTypeList().map((typeDef) => ({ ...typeDef, hidden: false }));
}

function getDefaultNodeTypeLabel(type) {
  return type === "Event" ? "Frame" : type;
}

function getNodeTypeEntries(includeType = null) {
  const entries = getProjectNodeTypes()
    .filter((typeDef) => !typeDef.hidden || typeDef.type === includeType)
    .map((typeDef) => [typeDef.type, {
      badge: typeDef.badge,
      color: typeDef.color,
      width: typeDef.width,
      label: typeDef.label,
      custom: Boolean(typeDef.custom),
      kind: typeDef.kind,
      template: getNodeTypeTemplate(typeDef),
      fields: typeDef.fields || [],
      hidden: Boolean(typeDef.hidden)
    }]);
  if (includeType && !entries.some(([type]) => type === includeType)) {
    entries.push([includeType, { ...getNodeMeta(includeType), removed: true }]);
  }
  return entries;
}

function getHiddenNodeTypeEntries() {
  return getProjectNodeTypes()
    .filter((typeDef) => typeDef.hidden)
    .map((typeDef) => [typeDef.type, {
      badge: typeDef.badge,
      color: typeDef.color,
      width: typeDef.width,
      label: typeDef.label,
      custom: Boolean(typeDef.custom),
      kind: typeDef.kind,
      template: getNodeTypeTemplate(typeDef),
      fields: typeDef.fields || [],
      hidden: true
    }]);
}

function getNodeTypeDef(type) {
  if (!type) return null;
  return getProjectNodeTypes().find((typeDef) => typeDef.type === type) || null;
}

function getLinkLabelVisualMetrics(scaleValue = state.view.scale) {
  const scale = Math.max(CANVAS_MIN_ZOOM, Number(scaleValue) || DEFAULT_CANVAS_ZOOM);
  const screenFontSize = Math.min(16, Math.max(10, 12 * Math.sqrt(scale)));
  return {
    fontSize: screenFontSize / scale,
    offset: 8 / scale,
    strokeWidth: 4 / scale,
    screenFontSize
  };
}

function renderLinks(renderContext = getCanvasRenderContext()) {
  const visibleNodeIds = renderContext.visibleNodeIds;
  const nodeMap = renderContext.nodeMap;
  const activeFrame = getActiveFrameCanvas();
  const linkSvg = [
    `<defs>
      <marker id="arrow-head" viewBox="0 0 8 8" refX="7.5" refY="4" markerWidth="5" markerHeight="5" markerUnits="userSpaceOnUse" orient="auto-start-reverse">
        <path d="M 0 0 L 8 4 L 0 8 z" fill="context-stroke"></path>
      </marker>
    </defs>`
  ];

  state.project.links.forEach((link) => {
    const endpoints = getRenderedLinkEndpoints(link, nodeMap, { ignoredCollapsedFrameId: activeFrame?.id || "" });
    if (!endpoints) return;
    const { from, to } = endpoints;
    if (isFrameCanvasActive() && (!visibleNodeIds.has(from.id) || !visibleNodeIds.has(to.id))) return;
    if (link.id !== state.selectedLinkId && !visibleNodeIds.has(from.id) && !visibleNodeIds.has(to.id)) return;
    const fromPoint = getOutputPoint(from);
    const toPoint = getInputPoint(to);
    const path = linkPath(fromPoint, toPoint);
    linkSvg.push(`<path class="link-hitpath" d="${path}" data-link-id="${escapeAttr(link.id)}"></path>`);
    linkSvg.push(`<path class="link-path ${link.id === state.selectedLinkId ? "selected" : ""}" d="${path}" marker-end="url(#arrow-head)" data-link-id="${escapeAttr(link.id)}"></path>`);
    if (link.id === state.inlineEditLinkId) {
      const mid = midpoint(fromPoint, toPoint);
      const scale = Math.max(CANVAS_MIN_ZOOM, state.view.scale || DEFAULT_CANVAS_ZOOM);
      const editorWidth = 240 / scale;
      const editorHeight = 38 / scale;
      const editorStyle = [
        `font-size:${14 / scale}px`,
        `padding:0 ${10 / scale}px`,
        `border-width:${1 / scale}px`,
        `border-radius:${6 / scale}px`
      ].join(";");
      linkSvg.push(`
        <foreignObject class="link-label-editor-wrap" x="${mid.x - editorWidth / 2}" y="${mid.y - editorHeight / 2}" width="${editorWidth}" height="${editorHeight}" data-link-id="${escapeAttr(link.id)}">
          <input xmlns="http://www.w3.org/1999/xhtml" class="link-label-editor" type="text" data-inline-link-label="true" data-link-id="${escapeAttr(link.id)}" value="${escapeAttr(link.label || "")}" placeholder="${escapeAttr(t("Add label"))}" aria-label="${escapeAttr(t("Edit link label"))}" style="${escapeAttr(editorStyle)}">
        </foreignObject>
      `);
    } else if (link.label) {
      const mid = midpoint(fromPoint, toPoint);
      const labelMetrics = getLinkLabelVisualMetrics();
      linkSvg.push(`<text class="link-label" x="${mid.x}" y="${mid.y - labelMetrics.offset}" font-size="${labelMetrics.fontSize}" stroke-width="${labelMetrics.strokeWidth}" text-anchor="middle" data-link-id="${escapeAttr(link.id)}" data-screen-font-size="${labelMetrics.screenFontSize}">${escapeHtml(link.label)}</text>`);
    }
  });

  if (state.connectingFrom) {
    const from = getNode(state.connectingFrom);
    if (from) {
      const path = linkPath(getOutputPoint(from), state.connectingTo || getOutputPoint(from));
      linkSvg.push(`<path class="link-path pending" d="${path}"></path>`);
    }
  }

  dom.linkLayer.innerHTML = linkSvg.join("");
  refreshGraphHoverClasses();
}

function getGraphHoverDescriptor(target) {
  if (!target?.closest || !dom.viewport?.contains(target)) return null;
  const option = target.closest("[data-canvas-choice-option][data-choice-node-id]");
  if (option) {
    return {
      kind: "choice",
      nodeId: option.dataset.choiceNodeId || "",
      optionId: option.dataset.choiceOptionId || "",
      optionIndex: Number(option.dataset.choiceOptionIndex)
    };
  }
  const link = target.closest("[data-link-id]");
  if (link && dom.linkLayer?.contains(link)) return { kind: "link", linkId: link.dataset.linkId || "" };
  const node = target.closest(".node[data-node-id]");
  if (node) return { kind: "node", nodeId: node.dataset.nodeId || "" };
  return null;
}

function graphHoverKey(descriptor) {
  if (!descriptor) return "";
  if (descriptor.kind === "choice") return `choice:${descriptor.nodeId}:${descriptor.optionId}:${descriptor.optionIndex}`;
  if (descriptor.kind === "link") return `link:${descriptor.linkId}`;
  return `node:${descriptor.nodeId}`;
}

function handleGraphHoverPointerMove(event) {
  const descriptor = getGraphHoverDescriptor(event.target);
  if (graphHoverKey(descriptor) === graphHoverKey(state.graphHover)) return;
  state.graphHover = descriptor;
  refreshGraphHoverClasses();
}

function clearGraphHover() {
  if (!state.graphHover && !dom.root?.querySelector(".graph-hover-node, .graph-hover-origin, .graph-hover-link, .graph-hover-choice-option")) return;
  state.graphHover = null;
  clearGraphHoverClasses();
}

function clearGraphHoverClasses() {
  dom.nodeLayer?.querySelectorAll(".graph-hover-node, .graph-hover-origin").forEach((element) => element.classList.remove("graph-hover-node", "graph-hover-origin"));
  dom.nodeLayer?.querySelectorAll(".graph-hover-choice-option").forEach((element) => element.classList.remove("graph-hover-choice-option"));
  dom.frameLayer?.querySelectorAll(".graph-hover-node, .graph-hover-origin").forEach((element) => element.classList.remove("graph-hover-node", "graph-hover-origin"));
  dom.linkLayer?.querySelectorAll(".graph-hover-link").forEach((element) => element.classList.remove("graph-hover-link"));
}

function addGraphHoverNode(nodeId, origin = false) {
  const element = getNodeElementById(nodeId);
  if (!element) return;
  element.classList.add("graph-hover-node");
  if (origin) element.classList.add("graph-hover-origin");
}

function addGraphHoverLink(linkId) {
  if (!linkId || !dom.linkLayer) return;
  dom.linkLayer.querySelectorAll(`[data-link-id="${CSS.escape(linkId)}"]`).forEach((element) => element.classList.add("graph-hover-link"));
}

function addGraphHoverChoiceOption(descriptor) {
  dom.nodeLayer?.querySelectorAll("[data-canvas-choice-option][data-choice-node-id]").forEach((element) => {
    const sameNode = element.dataset.choiceNodeId === descriptor.nodeId;
    const sameOption = descriptor.optionId
      ? element.dataset.choiceOptionId === descriptor.optionId
      : Number(element.dataset.choiceOptionIndex) === descriptor.optionIndex;
    if (sameNode && sameOption) element.classList.add("graph-hover-choice-option");
  });
}

function getRenderedGraphLinkEntries() {
  const nodeMap = getNodeIndex();
  const activeFrame = getActiveFrameCanvas();
  return state.project.links.map((link) => ({
    link,
    endpoints: getRenderedLinkEndpoints(link, nodeMap, { ignoredCollapsedFrameId: activeFrame?.id || "" })
  })).filter((entry) => entry.endpoints);
}

function refreshGraphHoverClasses() {
  clearGraphHoverClasses();
  const descriptor = state.graphHover;
  if (!descriptor) return;
  const entries = getRenderedGraphLinkEntries();
  if (descriptor.kind === "link") {
    const entry = entries.find((item) => item.link.id === descriptor.linkId);
    if (!entry) return;
    addGraphHoverLink(entry.link.id);
    addGraphHoverNode(entry.endpoints.from.id);
    addGraphHoverNode(entry.endpoints.to.id);
    return;
  }
  if (descriptor.kind === "node") {
    addGraphHoverNode(descriptor.nodeId, true);
    entries.filter((entry) => entry.endpoints.from.id === descriptor.nodeId || entry.endpoints.to.id === descriptor.nodeId).forEach((entry) => {
      addGraphHoverLink(entry.link.id);
      addGraphHoverNode(entry.endpoints.from.id);
      addGraphHoverNode(entry.endpoints.to.id);
    });
    return;
  }
  if (descriptor.kind === "choice") {
    addGraphHoverChoiceOption(descriptor);
    entries.filter(({ link }) => link.from === descriptor.nodeId && (
      (descriptor.optionId && link.choiceOptionId === descriptor.optionId)
      || (!link.choiceOptionId && Number.isInteger(descriptor.optionIndex) && Number(link.choiceIndex) === descriptor.optionIndex)
    )).forEach((entry) => {
      addGraphHoverLink(entry.link.id);
      addGraphHoverNode(entry.endpoints.to.id);
    });
  }
}

function renderInspector() {
  const activeNode = getNode(state.selectedNodeId);
  dom.inspectorTitle.textContent = state.panel === "node" && activeNode ? activeNode.title : t(titleCase(state.panel));
  renderInspectorTabs();
  renderProjectPanel();
  renderNodePanel(activeNode);
  renderStoryPanel();
  renderAiPanel();
  renderFloatingInspectorState();
}

function renderInspectorTabs() {
  dom.scope.querySelectorAll(".inspector-tab").forEach((button) => {
    button.disabled = false;
    button.removeAttribute("aria-disabled");
    button.classList.toggle("active", button.dataset.panel === state.panel);
  });
  dom.scope.querySelectorAll(".inspector-panel").forEach((panel) => {
    const panelName = panel.id.replace(/Panel$/, "");
    const activeInSidebar = panelName === state.panel;
    const activeInFloatingWindow = panelName === state.floatingInspectorPanel;
    panel.classList.toggle("active", activeInSidebar || activeInFloatingWindow);
  });
}

// BEGIN WEB_RUNTIME:AI_CONFIG
function getWebAiConfig() {
  if (window.NarrativeCanvasHost) return { endpoint: "", apiKey: "", model: "" };
  try {
    const stored = JSON.parse(localStorage.getItem("narrative-canvas-ai-config") || "{}");
    return {
      endpoint: String(stored.endpoint || ""),
      apiKey: String(stored.apiKey || ""),
      model: String(stored.model || "")
    };
  }
  catch (_error) { return {}; }
}

function saveWebAiConfig() {
  if (window.NarrativeCanvasHost || !dom.aiPanel) return;
  const config = {
    endpoint: dom.aiPanel.querySelector("[data-ai-config='endpoint']")?.value?.trim() || "",
    apiKey: dom.aiPanel.querySelector("[data-ai-config='apiKey']")?.value?.trim() || "",
    model: dom.aiPanel.querySelector("[data-ai-config='model']")?.value?.trim() || ""
  };
  localStorage.setItem("narrative-canvas-ai-config", JSON.stringify(config));
  const knowledgeOn = Boolean(dom.aiPanel.querySelector("[data-ai-config='narrativeKnowledge']")?.checked);
  try { localStorage.setItem("narrative-canvas-ai-knowledge-v1", knowledgeOn ? "1" : "0"); } catch (_error) { /* storage unavailable */ }
}
// END WEB_RUNTIME:AI_CONFIG

function renderAiMarkdownInline(value) {
  const tokens = [];
  const hold = (html) => `\u0000${tokens.push(html) - 1}\u0000`;
  let source = String(value || "");
  source = source.replace(/`([^`\n]+)`/g, (_match, code) => hold(`<code>${escapeHtml(code)}</code>`));
  source = source.replace(/\[([^\]\n]+)\]\(([^\s)]+)(?:\s+["']([^"']*)["'])?\)/g, (_match, label, href, title) => {
    let url = "";
    try {
      const parsed = new URL(href, window.location?.href || "https://localhost/");
      if (["http:", "https:", "mailto:"].includes(parsed.protocol)) url = href;
    } catch (_error) { /* Render invalid links as plain text. */ }
    if (!url) return escapeHtml(label);
    const titleAttr = title ? ` title="${escapeAttr(title)}"` : "";
    return hold(`<a href="${escapeAttr(url)}" target="_blank" rel="noopener noreferrer"${titleAttr}>${escapeHtml(label)}</a>`);
  });
  source = escapeHtml(source)
    .replace(/\*\*([^*\n]+)\*\*/g, "<strong>$1</strong>")
    .replace(/__([^_\n]+)__/g, "<strong>$1</strong>")
    .replace(/~~([^~\n]+)~~/g, "<del>$1</del>")
    .replace(/(^|[^*])\*([^*\n]+)\*(?!\*)/g, "$1<em>$2</em>")
    .replace(/(^|[^_])_([^_\n]+)_(?!_)/g, "$1<em>$2</em>");
  return source.replace(/\u0000(\d+)\u0000/g, (_match, index) => tokens[Number(index)] || "");
}

function renderAiMarkdown(value) {
  const lines = String(value || "").replace(/\r\n?/g, "\n").split("\n");
  const html = [];
  let paragraph = [];
  let listType = "";
  let inFence = false;
  let fenceLanguage = "";
  let fenceLines = [];
  const flushParagraph = () => {
    if (!paragraph.length) return;
    html.push(`<p>${paragraph.map(renderAiMarkdownInline).join("<br>")}</p>`);
    paragraph = [];
  };
  const closeList = () => {
    if (!listType) return;
    html.push(`</${listType}>`);
    listType = "";
  };
  lines.forEach((line) => {
    const fence = line.match(/^\s*```\s*([^\s`]*)\s*$/);
    if (fence) {
      flushParagraph(); closeList();
      if (inFence) {
        const languageClass = fenceLanguage ? ` class="language-${escapeAttr(fenceLanguage)}"` : "";
        html.push(`<pre><code${languageClass}>${escapeHtml(fenceLines.join("\n"))}</code></pre>`);
        inFence = false; fenceLanguage = ""; fenceLines = [];
      } else {
        inFence = true; fenceLanguage = fence[1] || "";
      }
      return;
    }
    if (inFence) { fenceLines.push(line); return; }
    if (!line.trim()) { flushParagraph(); closeList(); return; }
    const heading = line.match(/^\s*(#{1,4})\s+(.+)$/);
    if (heading) { flushParagraph(); closeList(); const level = heading[1].length; html.push(`<h${level}>${renderAiMarkdownInline(heading[2])}</h${level}>`); return; }
    if (/^\s*(?:-{3,}|\*{3,}|_{3,})\s*$/.test(line)) { flushParagraph(); closeList(); html.push("<hr>"); return; }
    const quote = line.match(/^\s*>\s?(.*)$/);
    if (quote) { flushParagraph(); closeList(); html.push(`<blockquote>${renderAiMarkdownInline(quote[1])}</blockquote>`); return; }
    const list = line.match(/^\s*([-+*]|\d+[.)])\s+(.+)$/);
    if (list) {
      flushParagraph();
      const nextType = /^\d/.test(list[1]) ? "ol" : "ul";
      if (listType !== nextType) { closeList(); listType = nextType; html.push(`<${listType}>`); }
      html.push(`<li>${renderAiMarkdownInline(list[2])}</li>`);
      return;
    }
    closeList();
    paragraph.push(line);
  });
  if (inFence) html.push(`<pre><code${fenceLanguage ? ` class="language-${escapeAttr(fenceLanguage)}"` : ""}>${escapeHtml(fenceLines.join("\n"))}</code></pre>`);
  flushParagraph(); closeList();
  return html.join("");
}

function aiCopyIcon() {
  return `<svg viewBox="0 0 24 24" aria-hidden="true"><rect x="8" y="8" width="11" height="11" rx="2"/><path d="M16 8V6a2 2 0 0 0-2-2H6a2 2 0 0 0-2 2v8a2 2 0 0 0 2 2h2"/></svg>`;
}

async function writeTextToClipboard(value) {
  const text = String(value || "");
  if (!text) return false;
  try {
    if (navigator.clipboard?.writeText) {
      await navigator.clipboard.writeText(text);
      return true;
    }
  } catch (_error) { /* Use the selection fallback below. */ }
  const field = document.createElement("textarea");
  field.value = text;
  field.setAttribute("readonly", "");
  field.style.position = "fixed";
  field.style.opacity = "0";
  document.body.append(field);
  field.select();
  let copied = false;
  try { copied = Boolean(document.execCommand?.("copy")); } catch (_error) { copied = false; }
  field.remove();
  return copied;
}

async function copyAiMessage(index) {
  const message = state.aiMessages[Number(index)];
  const copied = await writeTextToClipboard(message?.content || "");
  setStatus(t(copied ? "Message copied." : "Could not copy the text."));
}

async function copyAiConversation() {
  const text = state.aiMessages.map((message) => `${message.role === "user" ? t("You") : "AI"}:\n${message.content || ""}`).join("\n\n");
  const copied = await writeTextToClipboard(text);
  setStatus(t(copied ? "Conversation copied." : "Could not copy the text."));
}

function renderAiPanel() {
  if (!dom.aiPanel) return;
  const config = getWebAiConfig();
  const selected = (state.selectedNodeIds?.length ? state.selectedNodeIds : [state.selectedNodeId]).filter(Boolean);
  const messages = state.aiMessages.map((message, index) => `<article class="ai-message ai-message-${escapeAttr(message.role)}${state.aiBusy && index === state.aiStreamIndex ? " streaming" : ""}" data-ai-message-index="${index}"><div class="ai-message-header"><strong>${message.role === "user" ? t("You") : "AI"}</strong><button class="ai-copy-button" data-action="ai-copy-message" data-ai-message-index="${index}" type="button" title="${escapeAttr(t("Copy message"))}" aria-label="${escapeAttr(t("Copy message"))}">${aiCopyIcon()}</button></div><div class="ai-markdown">${renderAiMarkdown(message.content)}</div></article>`).join("");
  const patch = state.aiPendingPatch;
  const operations = Array.isArray(patch?.operations) ? patch.operations : [];
  const proposal = patch ? `<section class="ai-proposal"><h3>${escapeHtml(patch.summary || t("Canvas change proposal"))}</h3><ol>${operations.map((op) => `<li><code>${escapeHtml(op.op || "")}</code> ${escapeHtml(op.node?.title || op.id || op.from || "")}</li>`).join("")}</ol><div class="ai-actions"><button data-action="ai-apply-patch" type="button">${t("Apply to canvas")}</button><button data-action="ai-reject-patch" type="button">${t("Reject")}</button></div></section>` : "";
    const webConfig = window.NarrativeCanvasHost ? "" : `<details class="ai-config"><summary>${t("Connection settings")}</summary><label>Endpoint<input data-ai-config="endpoint" value="${escapeAttr(config.endpoint || "")}" placeholder="https://api.example.com/v1/chat/completions"></label><label>API key<input data-ai-config="apiKey" type="password" value="${escapeAttr(config.apiKey || "")}"></label><label>Model<input data-ai-config="model" value="${escapeAttr(config.model || "")}" placeholder="model-name"></label><label class="ai-config-check"><input type="checkbox" data-ai-config="narrativeKnowledge"${isAiNarrativeKnowledgeEnabled() ? " checked" : ""}>${t("Narrative craft guidance")}</label><button data-action="ai-save-config" type="button">${t("Save settings")}</button></details>`;
  const composerLocked = state.aiBusy;
  dom.aiPanel.innerHTML = `<div class="ai-workbench">${webConfig}<div class="ai-context"><span>${t("Context")}: ${selected.length ? selected.map((id) => `#${escapeHtml(id)}`).join(", ") : t("Entire canvas")}</span>${state.aiMessages.length ? `<button class="ai-copy-button" data-action="ai-copy-conversation" type="button" title="${escapeAttr(t("Copy conversation"))}" aria-label="${escapeAttr(t("Copy conversation"))}">${aiCopyIcon()}<span>${escapeHtml(t("Copy conversation"))}</span></button>` : ""}</div><div class="ai-messages" aria-live="polite">${messages || `<p class="muted">${t("Discuss the story, then ask AI to propose canvas changes.")}</p>`}</div>${proposal}${state.aiError ? `<p class="ai-error">${escapeHtml(state.aiError)}</p>` : ""}<div class="ai-composer"><textarea data-ai-prompt rows="5" placeholder="${escapeAttr(t("Ask about the story or request a canvas change. Enter to send; Shift+Enter for a new line."))}" ${composerLocked ? "disabled" : ""}>${escapeHtml(state.aiPromptDraft)}</textarea><div class="ai-composer-toolbar"><div class="ai-actions"><button data-action="ai-send" type="button" ${state.aiBusy ? "disabled" : ""}>${state.aiBusy ? t("Responding...") : t("Send")}</button>${state.aiBusy ? `<button data-action="ai-stop" type="button">${t("Stop")}</button>` : ""}<button data-action="ai-clear" type="button">${t("Clear")}</button></div></div></div></div>`;
  dom.aiPanel.querySelector(".ai-messages")?.scrollTo?.({ top: 999999 });
  renderAiFloatingState();
}

function renderAiStreamFrame() {
  state.aiStreamFrame = 0;
  const index = state.aiStreamIndex;
  const message = state.aiMessages[index];
  const body = dom.aiPanel?.querySelector(`[data-ai-message-index="${index}"] > .ai-markdown`);
  if (!message || !body) return;
  body.innerHTML = renderAiMarkdown(message.content);
  const list = dom.aiPanel.querySelector(".ai-messages");
  if (list) list.scrollTop = list.scrollHeight;
}

function scheduleAiStreamFrame() {
  if (state.aiStreamFrame) return;
  state.aiStreamFrame = window.requestAnimationFrame(renderAiStreamFrame);
}

function stopAiMessage({ silent = false } = {}) {
  if (!state.aiBusy) return;
  const streamIndex = state.aiStreamIndex;
  state.aiAbortController?.abort?.();
  state.aiRequestId += 1;
  state.aiAbortController = null;
  state.aiBusy = false;
  if (!silent) state.aiError = t("AI response stopped.");
  if (streamIndex >= 0 && !state.aiMessages[streamIndex]?.content) state.aiMessages.splice(streamIndex, 1);
  state.aiStreamIndex = -1;
  if (state.aiStreamFrame) window.cancelAnimationFrame(state.aiStreamFrame);
  state.aiStreamFrame = 0;
  renderAiPanel();
}

// Large centered editor for a node text field (issue #10). The dialog's textarea
// carries the same data-node-field/data-node-id, so existing input handlers route
// edits straight to the node; closing re-renders the inspector to sync the field.
function openExpandEditor(nodeId, field, title) {
  const node = getNode(nodeId);
  if (!node || !dom.expandEditorDialog?.showModal) return;
  state.expandEditor = { nodeId, field };
  if (dom.expandEditorTitle) dom.expandEditorTitle.textContent = title || t("Edit text");
  if (dom.expandEditorLanguage) {
    const format = normalizeRichTextFormat(state.project.richTextFormat);
    dom.expandEditorLanguage.value = format;
    dom.expandEditorLanguage.title = t("Rich text language");
    dom.expandEditorLanguage.setAttribute("aria-label", t("Rich text language"));
    updateExpandEditorToolbarFormat(format);
  }
  if (dom.expandEditorInput) {
    dom.expandEditorInput.value = String(node[field] ?? "");
    dom.expandEditorInput.dataset.nodeField = field;
    dom.expandEditorInput.dataset.nodeId = nodeId;
  }
  // Open in rendered ("what you see") mode; a click switches to the source editor.
  const wrap = dom.expandEditorInput?.closest("[data-live-field]");
  if (wrap) renderLiveField(wrap);
  dom.expandEditorDialog.showModal();
}

function closeExpandEditor() {
  if (!dom.expandEditorDialog?.open) return;
  dom.expandEditorDialog.close();
  // Do not rely on the browser's close-event scheduling to refresh the inspector.
  // The close handler remains registered for Escape and other native dialog exits.
  handleExpandEditorClose();
}

// "Render by default, click to edit" fields. A `[data-live-field]` holds a rendered
// Markdown view (`[data-live-rendered]`) and a source textarea (`[data-live-source]`).
// The rendered view is shown until the user clicks in; while the source is focused
// the raw **/##/> markers are visible so they can be edited, and on blur (unless the
// field is `[data-live-persist]`, like the large modal) it renders again.
function renderLiveField(wrap) {
  const source = wrap?.querySelector("[data-live-source]");
  const rendered = wrap?.querySelector("[data-live-rendered]");
  if (!source || !rendered) return;
  const value = source.value || "";
  rendered.innerHTML = value.trim()
    ? renderNarrativeRichText(value)
    : `<span class="field-live-placeholder">${escapeHtml(t("Click to edit"))}</span>`;
  rendered.hidden = false;
  source.hidden = true;
  wrap.classList.remove("live-editing");
}

function enterLiveFieldEdit(wrap) {
  const source = wrap?.querySelector("[data-live-source]");
  const rendered = wrap?.querySelector("[data-live-rendered]");
  if (!source || !rendered || !source.hidden) return;
  rendered.hidden = true;
  source.hidden = false;
  wrap.classList.add("live-editing");
  source.focus({ preventScroll: true });
  const length = source.value.length;
  source.setSelectionRange?.(length, length);
}

function getCurrentRichTextFormat() {
  return normalizeRichTextFormat(state.project?.richTextFormat);
}

function updateExpandEditorToolbarFormat(value) {
  const format = normalizeRichTextFormat(value);
  const toolbar = dom.expandEditorToolbar;
  if (!toolbar) return;
  toolbar.dataset.richTextFormat = format;
  const labels = {
    bold: "Bold", italic: "Italic", strike: "Strikethrough", code: "Inline code",
    highlight: "Highlight", link: "Link", h1: "Heading 1", h2: "Heading 2", h3: "Heading 3",
    quote: "Quote", list: "Bullet list", ordered: "Numbered list", task: "Task list",
    codeblock: "Code block", divider: "Divider"
  };
  const hints = {
    markdown: {
      bold: "**text**", italic: "*text*", strike: "~~text~~", code: "`text`", highlight: "==text==",
      link: "[text](url)", h1: "# text", h2: "## text", h3: "### text", quote: "> text",
      list: "- text", ordered: "1. text", task: "- [ ] text", codeblock: "```", divider: "---"
    },
    html: {
      bold: "<strong>", italic: "<em>", strike: "<s>", code: "<code>", highlight: "<mark>",
      link: "<a href>", h1: "<h1>", h2: "<h2>", h3: "<h3>", quote: "<blockquote>",
      list: "<ul><li>", ordered: "<ol><li>", task: "<li data-nc-task>", codeblock: "<pre><code>", divider: "<hr>"
    },
    unity: {
      bold: "<b>", italic: "<i>", strike: "<s>", code: '<style="NCCode">', highlight: "<mark=#...>",
      link: '<link="url">', h1: "<size=160%>", h2: "<size=140%>", h3: "<size=120%>", quote: "<indent><i>",
      list: "<indent>•", ordered: "<indent>1.", task: "<indent>☐", codeblock: '<style="NCCode">', divider: "────────"
    },
    bbcode: {
      bold: "[b]", italic: "[i]", strike: "[s]", code: "[code]", highlight: "[bgcolor]",
      link: "[url]", h1: "[font_size=32]", h2: "[font_size=26]", h3: "[font_size=21]", quote: "[quote]",
      list: "[ul][li]", ordered: "[ol][li]", task: "[ul][li]☐", codeblock: "[code]", divider: "────────"
    },
    unreal: {
      bold: "<NCBold>", italic: "<NCItalic>", strike: "<NCStrike>", code: "<NCCode>", highlight: "<NCHighlight>",
      link: "<NCLink>", h1: "<NCH1>", h2: "<NCH2>", h3: "<NCH3>", quote: "<NCQuote>",
      list: "<NCList>", ordered: "<NCOrderedList>", task: "<NCTaskList>", codeblock: "<NCCodeBlock>", divider: "<NCDivider>"
    }
  };
  toolbar.querySelectorAll("[data-action='expand-editor-format']").forEach((button) => {
    const action = button.dataset.format;
    const label = t(labels[action] || action);
    const hint = hints[format]?.[action] || "";
    button.title = hint ? `${label} · ${hint}` : label;
    button.setAttribute("aria-label", label);
    button.dataset.richTextFormat = format;
  });
  const codeButton = toolbar.querySelector("[data-format='code'] code");
  if (codeButton) codeButton.textContent = ({ markdown: "`x`", html: "</>", unity: "TMP", bbcode: "[]", unreal: "UE" })[format];
  const textColor = toolbar.querySelector("[data-expand-color='text']")?.closest(".expand-color-control");
  const highlightColor = toolbar.querySelector("[data-expand-color='highlight']")?.closest(".expand-color-control");
  if (textColor) textColor.title = `${t("Text color")} · ${hints[format]?.bold?.startsWith("[") ? "[color]" : format === "unity" ? "<color>" : format === "unreal" ? "<NCColor>" : format === "html" ? "<span style=color>" : "{color:#...}"}`;
  if (highlightColor) highlightColor.title = `${t("Highlight color")} · ${format === "bbcode" ? "[bgcolor]" : format === "unity" ? "<mark=#...>" : format === "unreal" ? "<NCHighlight>" : format === "html" ? "<mark style=background-color>" : "{highlight:#...}"}`;
}

function getRichTextInlineSyntax(format, action, color = "") {
  const safeColor = normalizeRichTextColor(color, action === "highlight" ? "#ffd43b" : "#e6e6e6");
  const syntax = {
    markdown: {
      bold: ["**", "**"], italic: ["*", "*"], strike: ["~~", "~~"], code: ["`", "`"],
      highlight: ["==", "=="], textColor: [`{color:${safeColor}}`, "{/color}"],
      highlightColor: [`{highlight:${safeColor}}`, "{/highlight}"]
    },
    html: {
      bold: ["<strong>", "</strong>"], italic: ["<em>", "</em>"], strike: ["<s>", "</s>"], code: ["<code>", "</code>"],
      highlight: ["<mark>", "</mark>"], textColor: [`<span style="color:${safeColor}">`, "</span>"],
      highlightColor: [`<mark style="background-color:${safeColor}">`, "</mark>"]
    },
    unity: {
      bold: ["<b>", "</b>"], italic: ["<i>", "</i>"], strike: ["<s>", "</s>"], code: ['<style="NCCode">', "</style>"],
      highlight: ["<mark=#ffff0080>", "</mark>"], textColor: [`<color=${safeColor}>`, "</color>"],
      highlightColor: [`<mark=${safeColor}80>`, "</mark>"]
    },
    bbcode: {
      bold: ["[b]", "[/b]"], italic: ["[i]", "[/i]"], strike: ["[s]", "[/s]"], code: ["[code]", "[/code]"],
      highlight: ["[bgcolor=#ffd43b]", "[/bgcolor]"], textColor: [`[color=${safeColor}]`, "[/color]"],
      highlightColor: [`[bgcolor=${safeColor}]`, "[/bgcolor]"]
    },
    unreal: {
      bold: ["<NCBold>", "</>"], italic: ["<NCItalic>", "</>"], strike: ["<NCStrike>", "</>"], code: ["<NCCode>", "</>"],
      highlight: ["<NCHighlight>", "</>"], textColor: [`<NCColor value="${safeColor}">`, "</>"],
      highlightColor: [`<NCHighlight value="${safeColor}">`, "</>"]
    }
  };
  return syntax[format]?.[action] || null;
}

function getRichTextLinkSyntax(format, label) {
  const url = "https://";
  if (format === "html") return { text: `<a href="${url}">${label}</a>`, urlOffset: 9 };
  if (format === "unity") return { text: `<link="${url}">${label}</link>`, urlOffset: 7 };
  if (format === "bbcode") return { text: `[url=${url}]${label}[/url]`, urlOffset: 5 };
  if (format === "unreal") return { text: `<NCLink href="${url}">${label}</>`, urlOffset: 14 };
  return { text: `[${label}](${url})`, urlOffset: label.length + 3 };
}

function formatRichTextBlock(format, action, selected) {
  const lines = (selected || t(action === "codeblock" ? "code" : "text")).split("\n");
  if (format === "markdown") {
    if (action === "codeblock") return `\`\`\`\n${lines.join("\n")}\n\`\`\``;
    if (action === "divider") return "---";
    const prefix = { h1: "# ", h2: "## ", h3: "### ", quote: "> ", list: "- ", ordered: "1. ", task: "- [ ] " }[action];
    return prefix ? lines.map((line) => `${prefix}${line}`).join("\n") : null;
  }
  if (format === "html") {
    const tags = { h1: "h1", h2: "h2", h3: "h3", quote: "blockquote" };
    if (tags[action]) return `<${tags[action]}>${lines.join("<br>")}</${tags[action]}>`;
    if (action === "codeblock") return `<pre><code>${lines.join("\n")}</code></pre>`;
    if (action === "divider") return "<hr>";
    if (["list", "ordered", "task"].includes(action)) {
      const tag = action === "ordered" ? "ol" : "ul";
      const taskAttr = action === "task" ? ' data-nc-task-list="true"' : "";
      return `<${tag}${taskAttr}>\n${lines.map((line) => `<li${action === "task" ? ' data-nc-task="false"' : ""}>${line}</li>`).join("\n")}\n</${tag}>`;
    }
  }
  if (format === "unity") {
    const wrappers = {
      h1: ["<size=160%><b>", "</b></size>"],
      h2: ["<size=140%><b>", "</b></size>"],
      h3: ["<size=120%><b>", "</b></size>"],
      quote: ['<indent=5%><i>“', "”</i></indent>"],
      codeblock: ['<style="NCCode">', "</style>"]
    };
    if (wrappers[action]) return `${wrappers[action][0]}${lines.join("\n")}${wrappers[action][1]}`;
    if (action === "divider") return "────────────────";
    if (action === "list") return lines.map((line) => `<indent=5%>• ${line}</indent>`).join("\n");
    if (action === "ordered") return lines.map((line, index) => `<indent=5%>${index + 1}. ${line}</indent>`).join("\n");
    if (action === "task") return lines.map((line) => `<indent=5%>☐ ${line}</indent>`).join("\n");
  }
  if (format === "bbcode") {
    const wrappers = {
      h1: ["[font_size=32][b]", "[/b][/font_size]"],
      h2: ["[font_size=26][b]", "[/b][/font_size]"],
      h3: ["[font_size=21][b]", "[/b][/font_size]"],
      quote: ["[quote]", "[/quote]"],
      codeblock: ["[code]", "[/code]"]
    };
    if (wrappers[action]) return `${wrappers[action][0]}${lines.join("\n")}${wrappers[action][1]}`;
    if (action === "divider") return "────────────────";
    if (["list", "ordered"].includes(action)) {
      const tag = action === "ordered" ? "ol" : "ul";
      return `[${tag}]${lines.map((line) => `[li]${line}[/li]`).join("")}[/${tag}]`;
    }
    if (action === "task") return `[ul]${lines.map((line) => `[li]☐ ${line}[/li]`).join("")}[/ul]`;
  }
  if (format === "unreal") {
    const tags = { h1: "NCH1", h2: "NCH2", h3: "NCH3", quote: "NCQuote", codeblock: "NCCodeBlock", list: "NCList", ordered: "NCOrderedList", task: "NCTaskList" };
    if (tags[action]) {
      const body = ["list", "ordered", "task"].includes(action)
        ? lines.map((line) => `<NCItem>${line}</>`).join("")
        : lines.join("\n");
      return `<${tags[action]}>${body}</>`;
    }
    if (action === "divider") return "<NCDivider></>";
  }
  return null;
}

// Formatting follows the project's selected storage language. All formats share the
// same semantic renderer, so changing language never changes the visible result.
function applyExpandEditorFormat(action) {
  const input = dom.expandEditorInput;
  if (!input) return;
  // The toolbar only makes sense on the source; switch out of rendered mode first.
  const wrap = input.closest("[data-live-field]");
  if (wrap && input.hidden) enterLiveFieldEdit(wrap);
  const value = input.value;
  const start = input.selectionStart ?? value.length;
  const end = input.selectionEnd ?? start;
  const selected = value.slice(start, end);
  const format = getCurrentRichTextFormat();
  const inlineWrap = getRichTextInlineSyntax(format, action);

  let nextValue;
  let nextStart;
  let nextEnd;
  if (inlineWrap) {
    const inner = selected || t("text");
    nextValue = `${value.slice(0, start)}${inlineWrap[0]}${inner}${inlineWrap[1]}${value.slice(end)}`;
    nextStart = start + inlineWrap[0].length;
    nextEnd = nextStart + inner.length;
  } else if (action === "link") {
    const label = selected || t("text");
    const link = getRichTextLinkSyntax(format, label);
    nextValue = `${value.slice(0, start)}${link.text}${value.slice(end)}`;
    nextStart = start + link.urlOffset;
    nextEnd = nextStart + "https://".length;
  } else {
    const block = formatRichTextBlock(format, action, selected);
    if (block == null) return;
    const before = value.slice(0, start);
    const lead = before && !before.endsWith("\n") ? "\n" : "";
    const tail = value.slice(end) && !value.slice(end).startsWith("\n") ? "\n" : "";
    const insert = `${lead}${block}${tail}`;
    nextValue = `${before}${insert}${value.slice(end)}`;
    nextStart = start + lead.length;
    nextEnd = nextStart + block.length;
  }

  input.value = nextValue;
  input.setSelectionRange(nextStart, nextEnd);
  input.focus();
  // Route through the same input path as typing so the node field and history update.
  input.dispatchEvent(new Event("input", { bubbles: true }));
}

function normalizeRichTextColor(value, fallback = "#ffffff") {
  const color = normalizeOptionalString(value).trim();
  return /^#[0-9a-f]{6}$/i.test(color) ? color.toLowerCase() : fallback;
}

function applyExpandEditorColor(kind, value) {
  const input = dom.expandEditorInput;
  if (!input) return;
  const wrap = input.closest("[data-live-field]");
  if (wrap && input.hidden) enterLiveFieldEdit(wrap);
  const source = input.value;
  const start = input.selectionStart ?? source.length;
  const end = input.selectionEnd ?? start;
  const selected = source.slice(start, end) || t("text");
  const action = kind === "highlight" ? "highlightColor" : "textColor";
  const syntax = getRichTextInlineSyntax(getCurrentRichTextFormat(), action, value);
  if (!syntax) return;
  input.value = `${source.slice(0, start)}${syntax[0]}${selected}${syntax[1]}${source.slice(end)}`;
  input.setSelectionRange(start + syntax[0].length, start + syntax[0].length + selected.length);
  input.focus();
  input.dispatchEvent(new Event("input", { bubbles: true }));
}

function setExpandEditorRichTextFormat(value) {
  const nextFormat = normalizeRichTextFormat(value);
  const previousFormat = getCurrentRichTextFormat();
  if (nextFormat === previousFormat) return;
  const before = getHistorySnapshot();
  const input = dom.expandEditorInput;
  const wasEditing = Boolean(input && !input.hidden);
  convertProjectRichText(previousFormat, nextFormat);
  state.project.richTextFormat = nextFormat;
  void window.NarrativeCanvasHost?.setRichTextFormat?.(nextFormat);
  const active = state.expandEditor;
  const node = active ? getNode(active.nodeId) : null;
  if (input && node) {
    input.value = String(node[active.field] ?? "");
    if (wasEditing) {
      input.hidden = false;
      input.closest("[data-live-field]")?.classList.add("live-editing");
      const cursor = input.value.length;
      input.setSelectionRange(cursor, cursor);
      input.focus();
    } else {
      renderLiveField(input.closest("[data-live-field]"));
    }
  }
  if (dom.expandEditorLanguage) dom.expandEditorLanguage.value = nextFormat;
  updateExpandEditorToolbarFormat(nextFormat);
  setProjectDirty(true);
  commitHistoryFromSnapshot(before);
  renderNodes();
  renderStoryPanel();
  renderProjectPanel();
  renderWorkspaceFile();
  updateStatus();
  setStatus(t("Rich text converted to {format}.", {
    format: RICH_TEXT_FORMATS.find((option) => option.value === nextFormat)?.label || nextFormat
  }));
}

function handleExpandEditorClose() {
  if (!state.expandEditor && !dom.expandEditorInput?.dataset.nodeField) return;
  state.expandEditor = null;
  // Clear the routing attributes so the closed modal's textarea is not a stray
  // duplicate of the inspector field.
  if (dom.expandEditorInput) {
    delete dom.expandEditorInput.dataset.nodeField;
    delete dom.expandEditorInput.dataset.nodeId;
    dom.expandEditorInput.value = "";
  }
  if (isCanvasFileActive()) {
    renderNodes();
    renderLinks();
    markCanvasSurfaceRendered();
  }
  renderInspector();
}

// The in-canvas AI launcher is hidden inside Obsidian until endpoint, key, and model
// are configured (issue #9). In the standalone web app the config form lives behind
// the button, so it stays visible there.
function isAiLauncherVisible() {
  const host = window.NarrativeCanvasHost;
  if (host) return typeof host.hasAiConfig === "function" ? Boolean(host.hasAiConfig()) : true;
  return true;
}

function renderAiFloatingState() {
  const launcherVisible = isAiLauncherVisible();
  if (!launcherVisible && state.aiOpen) state.aiOpen = false;
  if (dom.aiFloatingWindow) dom.aiFloatingWindow.hidden = !state.aiOpen;
  if (dom.aiFloatingButton) {
    dom.aiFloatingButton.hidden = !launcherVisible;
    dom.aiFloatingButton.setAttribute("aria-expanded", state.aiOpen ? "true" : "false");
    dom.aiFloatingButton.classList.toggle("active", state.aiOpen);
  }
  renderFloatingWindowPinState("ai");
}

// Called by the plugin after AI settings change so the launcher appears or hides
// without reopening the view.
function refreshAiLauncher() {
  renderAiFloatingState();
}

function toggleAiWindow(force = null) {
  const nextOpen = typeof force === "boolean" ? force : !state.aiOpen;
  state.aiOpen = nextOpen;
  if (nextOpen) {
    state.floatingWindowGeometry.ai = null;
    clearFloatingWindowStyles("ai");
  }
  if (!state.aiOpen) {
    setFloatingWindowPinned("ai", false);
  }
  renderAiPanel();
  if (state.aiOpen) window.setTimeout(() => dom.aiPanel?.querySelector("[data-ai-prompt]")?.focus?.(), 0);
}

function buildAiContext() {
  const selected = new Set((state.selectedNodeIds?.length ? state.selectedNodeIds : [state.selectedNodeId]).filter(Boolean));
  const contextScope = selected.size ? "focused-neighborhood" : "entire-canvas";
  let nodes = state.project.nodes;
  if (selected.size) {
    const related = new Set(selected);
    state.project.links.forEach((link) => { if (selected.has(link.from) || selected.has(link.to)) { related.add(link.from); related.add(link.to); } });
    nodes = nodes.filter((node) => related.has(node.id));
  }
  return {
    contextScope,
    contextNotice: selected.size
      ? "This payload contains only the focused node neighborhood. Unlisted project nodes and links may still exist; do not report them as missing without requesting the entire canvas."
      : "This payload contains the entire canvas.",
    project: { title: state.project.title, notes: state.project.notes, nodeCount: state.project.nodes.length, linkCount: state.project.links.length },
    focusNodeIds: [...selected], variables: state.project.variables, characters: state.project.characters,
    nodes: nodes.map((node) => ({ id: node.id, type: node.type, title: node.title, body: node.body, frameId: node.frameId || "", turns: node.turns, choiceOptions: node.choiceOptions, stateLogic: node.stateLogic, routing: node.routing })),
    links: state.project.links.filter((link) => !selected.size || nodes.some((node) => node.id === link.from || node.id === link.to))
  };
}

// Optional, opt-in craft primer (Settings → AI → Narrative craft guidance). Kept
// compact so it costs a bounded number of tokens per request.
const AI_NARRATIVE_KNOWLEDGE_PROMPT = `Apply established narrative craft when advising or editing:
- Structure: give the story a clear shape (setup, escalating complications, climax, resolution). Every scene should turn on a change in value and advance goal, conflict, or stakes. Cut scenes that do not.
- Causality: connect events with "therefore/but", not "and then". Plant setups before payoffs; honor foreshadowing.
- Character: drive people by concrete wants (external goal) and needs (internal lack). Reveal character through choices under pressure. Give antagonists their own coherent logic. Track arcs of change.
- Conflict & stakes: keep dramatic tension via opposing forces and meaningful consequences; raise stakes as the story proceeds.
- Scene craft: enter late, leave early; ground exposition in action and subtext; let dialogue carry conflict and voice rather than plain information.
- Cinematic storytelling: express dramatic beats through staging, composition, point of view, shot scale, and motivated camera movement. Preserve screen direction and spatial continuity unless a deliberate break serves the scene.
- Editing & sound: cut on decisions, revelations, movement, or changes in power; vary shot duration with tension; use sound, silence, and off-screen space to carry story information that dialogue or imagery should not repeat.
- Branching: make choices reflect values and produce consequences that matter; avoid false choices; keep routes thematically coherent.
Use these as guidance, not rigid rules; respect the author's intent and existing material.`;

function aiSystemPrompt() {
  return `You are the Narrative Canvas copilot. Discuss narrative design in the user's language. Respect contextScope: focused-neighborhood is partial, so never claim that an unlisted node or link is missing; ask for Entire canvas context before making whole-project integrity claims. When canvas edits are requested, finish with exactly one JSON object inside a fenced json block: {"summary":"...","operations":[{"op":"addNode","tempId":"new_1","node":{"type":"Dialog","title":"...","body":"","frameId":"","turns":[{"speaker":"...","line":"..."}]},"placement":{"x":500,"y":300}}]}. Every operation MUST include op. Allowed operations: addNode {op,tempId,node,placement}, updateNode {op,id,changes}, addLink {op,from,to,label,choiceOptionId}, deleteLink {op,id}. Never delete nodes. Node types include Content, Dialog, Choice, Marker, Clue, StorySequence and other existing project types. Preserve existing text unless asked. For addNode, include type,title,body,frameId; Dialog turns use {speaker,line}; Choice must include matching choiceOptions and choices. Keep operations <= 12.`;
}

function extractAiPatch(content) {
  const fenced = String(content || "").match(/```(?:json)?\s*([\s\S]*?)```/i);
  const candidates = [];
  if (fenced?.[1]) candidates.push(fenced[1].trim());
  const raw = String(content || "").trim();
  if (raw.startsWith("{") && raw.endsWith("}")) candidates.push(raw);
  const firstBrace = raw.indexOf("{");
  const lastBrace = raw.lastIndexOf("}");
  if (firstBrace >= 0 && lastBrace > firstBrace) candidates.push(raw.slice(firstBrace, lastBrace + 1));
  for (const candidate of candidates) {
    try {
      const parsed = JSON.parse(candidate);
      if (parsed && Array.isArray(parsed.operations)) return { patch: validateAiPatch(parsed), source: candidate };
    } catch (_error) { /* try the next candidate */ }
  }
  return null;
}

// Web-only AI transport. Isolated so the Obsidian plugin build can strip fetch entirely;
// inside Obsidian the request always goes through NarrativeCanvasHost.aiChat instead.
function aiResponseContent(response) {
  return response?.choices?.[0]?.message?.content || response?.output_text || response?.content || "";
}

function aiStreamDelta(event) {
  return event?.choices?.[0]?.delta?.content || event?.delta?.text || (typeof event?.delta === "string" ? event.delta : "") || event?.output_text || "";
}

async function readAiEventStream(result, onDelta) {
  if (!result.body?.getReader || !String(result.headers?.get?.("content-type") || "").includes("text/event-stream")) {
    return aiResponseContent(await result.json());
  }
  const reader = result.body.getReader();
  const decoder = new TextDecoder();
  let buffer = "";
  let content = "";
  const consumeLine = (line) => {
    const trimmed = line.trim();
    if (!trimmed.startsWith("data:")) return;
    const data = trimmed.slice(5).trim();
    if (!data || data === "[DONE]") return;
    try {
      const delta = aiStreamDelta(JSON.parse(data));
      if (delta) { content += delta; onDelta(delta); }
    } catch (_error) { /* Ignore provider keep-alive or non-JSON event rows. */ }
  };
  while (true) {
    const { value, done } = await reader.read();
    buffer += decoder.decode(value || new Uint8Array(), { stream: !done });
    const lines = buffer.split(/\r?\n/);
    buffer = lines.pop() || "";
    lines.forEach(consumeLine);
    if (done) break;
  }
  if (buffer) consumeLine(buffer);
  return content;
}

// BEGIN WEB_RUNTIME:AI_REQUEST
async function requestWebAiCompletion(payload, options) {
  const { signal, onDelta } = options;
  const config = getWebAiConfig();
  if (!config.endpoint || !config.apiKey || !config.model) throw new Error("Configure endpoint, API key, and model first.");
  const result = await fetch(config.endpoint, { method: "POST", headers: { "Content-Type": "application/json", Authorization: `Bearer ${config.apiKey}` }, body: JSON.stringify({ ...payload, model: config.model, stream: true }), signal });
  if (!result.ok) throw new Error(`AI request failed (${result.status}).`);
  return readAiEventStream(result, onDelta);
}
// END WEB_RUNTIME:AI_REQUEST

async function revealBufferedAiText(content, onDelta, signal) {
  const characters = Array.from(String(content || ""));
  const perFrame = Math.max(1, Math.ceil(characters.length / 120));
  for (let index = 0; index < characters.length; index += perFrame) {
    if (signal?.aborted) throw new DOMException("Aborted", "AbortError");
    onDelta(characters.slice(index, index + perFrame).join(""));
    await new Promise((resolve) => window.requestAnimationFrame(resolve));
  }
}

async function sendAiMessage() {
  if (state.aiBusy) return;
  const prompt = dom.aiPanel?.querySelector("[data-ai-prompt]")?.value?.trim() || state.aiPromptDraft.trim();
  if (!prompt) return;
  saveWebAiConfig();
  state.aiMessages.push({ role: "user", content: prompt });
  state.aiPromptDraft = "";
  const payloadMessages = state.aiMessages.slice(-12).map((message) => ({ role: message.role, content: message.content }));
  state.aiMessages.push({ role: "assistant", content: "" });
  const streamIndex = state.aiMessages.length - 1;
  const requestId = state.aiRequestId + 1;
  const controller = new AbortController();
  state.aiRequestId = requestId;
  state.aiStreamIndex = streamIndex;
  state.aiAbortController = controller;
  state.aiBusy = true; state.aiError = ""; state.aiPendingPatch = null; renderAiPanel();
  const signal = controller.signal;
  let timedOut = false;
  const timeoutId = window.setTimeout(() => {
    timedOut = true;
    controller.abort();
  }, 120000);
  let streamedContent = "";
  const onDelta = (delta) => {
    if (signal.aborted || !delta) return;
    const firstDelta = !streamedContent;
    streamedContent += delta;
    const message = state.aiMessages[streamIndex];
    if (message) message.content = streamedContent;
    if (firstDelta) renderAiStreamFrame();
    else scheduleAiStreamFrame();
  };
  try {
    const systemMessages = [{ role: "system", content: aiSystemPrompt() }];
    if (isAiNarrativeKnowledgeEnabled()) systemMessages.push({ role: "system", content: AI_NARRATIVE_KNOWLEDGE_PROMPT });
    systemMessages.push({ role: "system", content: `Canvas context:\n${JSON.stringify(buildAiContext())}` });
    const payload = { messages: [...systemMessages, ...payloadMessages], temperature: 0.4 };
    let content = "";
    if (window.NarrativeCanvasHost?.aiChatStream) content = await window.NarrativeCanvasHost.aiChatStream(payload, onDelta, signal);
    else if (window.NarrativeCanvasHost?.aiChat) content = aiResponseContent(await window.NarrativeCanvasHost.aiChat(payload));
    else content = await requestWebAiCompletion(payload, { signal, onDelta });
    content = String(content || streamedContent);
    if (!content) throw new Error("AI returned an empty response.");
    if (!streamedContent) await revealBufferedAiText(content, onDelta, signal);
    const extracted = extractAiPatch(content);
    state.aiPendingPatch = extracted?.patch || null;
    const visibleContent = extracted ? content.replace(extracted.source, "").replace(/```(?:json)?\s*```/i, "").trim() : content.trim();
    if (state.aiRequestId === requestId && state.aiMessages[streamIndex]) state.aiMessages[streamIndex].content = visibleContent || (extracted ? t("Canvas change proposal ready.") : content);
  } catch (error) {
    if (state.aiRequestId === requestId) {
      if (timedOut) state.aiError = t("AI request timed out.");
      else if (error?.name !== "AbortError") state.aiError = error?.message || String(error);
    }
  }
  window.clearTimeout(timeoutId);
  if (state.aiRequestId !== requestId) return;
  if (!state.aiMessages[streamIndex]?.content) state.aiMessages.splice(streamIndex, 1);
  if (state.aiStreamFrame) window.cancelAnimationFrame(state.aiStreamFrame);
  state.aiStreamFrame = 0;
  state.aiAbortController = null;
  state.aiBusy = false;
  state.aiStreamIndex = -1;
  renderAiPanel();
}

function validateAiPatch(value) {
  if (!value || typeof value !== "object" || !Array.isArray(value.operations)) throw new Error("AI patch is invalid.");
  const allowed = new Set(["addNode", "updateNode", "addLink", "deleteLink"]);
  const operations = value.operations.map((source) => {
    if (!source || typeof source !== "object" || Array.isArray(source)) throw new Error("AI patch contains an invalid operation.");
    const operation = { ...source };
    if (!operation.op && operation.node) operation.op = "addNode";
    if (!operation.op && operation.changes && operation.id) operation.op = "updateNode";
    if (!allowed.has(operation.op)) throw new Error("AI patch contains unsupported operations.");
    if (operation.op === "addNode" && operation.node && typeof operation.node === "object") {
      const node = { ...operation.node };
      if (isDialogNode(node) && !Array.isArray(node.turns) && (node.speaker || node.line)) {
        node.turns = [{ speaker: String(node.speaker || ""), line: String(node.line || "") }];
        delete node.speaker;
        delete node.line;
      }
      operation.node = node;
    }
    return operation;
  });
  if (operations.length > 12) throw new Error("AI patch contains too many operations.");
  return { summary: String(value.summary || ""), operations };
}

function applyAiPatch() {
  const patch = state.aiPendingPatch;
  if (!patch) return;
  const before = getHistorySnapshot();
  const tempIds = new Map();
  for (const operation of patch.operations) {
    if (operation.op === "addNode") {
      const source = operation.node && typeof operation.node === "object" ? operation.node : {};
      const id = nextId("n", state.project.nodes); tempIds.set(operation.tempId || id, id);
      const focus = getNode(state.selectedNodeId); const offset = tempIds.size;
      const placement = operation.placement && typeof operation.placement === "object" ? operation.placement : {};
      const node = normalizeNode({ ...source, id, type: source.type || "Content", title: source.title || "AI node", body: source.body || "", x: Number(placement.x ?? source.x ?? ((focus?.x || 80) + 380 * offset)), y: Number(placement.y ?? source.y ?? (focus?.y || 80)), frameId: source.frameId ?? focus?.frameId ?? "" });
      applyNodeTypeDefaults(node); state.project.nodes.push(normalizeNode(node));
    } else if (operation.op === "updateNode") {
      const node = getNode(operation.id); if (!node || !operation.changes || typeof operation.changes !== "object") continue;
      const protectedKeys = new Set(["id", "x", "y", "frameId"]); Object.entries(operation.changes).forEach(([key, value]) => { if (!protectedKeys.has(key)) node[key] = value; });
      Object.assign(node, normalizeNode(node));
    } else if (operation.op === "addLink") {
      const from = tempIds.get(operation.from) || operation.from; const to = tempIds.get(operation.to) || operation.to;
      if (!getNode(from) || !getNode(to)) continue;
      state.project.links.push({ id: nextId("l", state.project.links), from, to, label: String(operation.label || ""), ...(operation.choiceOptionId ? { choiceOptionId: operation.choiceOptionId } : {}) });
    } else if (operation.op === "deleteLink") state.project.links = state.project.links.filter((link) => link.id !== operation.id);
  }
  state.project = normalizeProject(state.project); markProjectStructureChanged(); commitHistoryFromSnapshot(before); state.aiPendingPatch = null; renderAll(); setStatus("AI proposal applied.");
}

function getInspectorPanelElement(panel) {
  if (panel === "project") return dom.projectPanel;
  if (panel === "node") return dom.nodePanel;
  if (panel === "story") return dom.storyPanel;
  return null;
}

function restoreInspectorPanels() {
  if (!dom.inspectorPanels) return;
  [dom.projectPanel, dom.nodePanel, dom.storyPanel].filter(Boolean).forEach((panel) => dom.inspectorPanels.append(panel));
}

function renderFloatingInspectorState() {
  const panel = validPanels.has(state.floatingInspectorPanel) ? state.floatingInspectorPanel : "";
  if (!panel || !dom.inspectorFloatOverlay || !dom.inspectorFloatBody) return;
  const panelElement = getInspectorPanelElement(panel);
  if (!panelElement) return;
  if (panelElement.parentElement !== dom.inspectorFloatBody) dom.inspectorFloatBody.append(panelElement);
  dom.inspectorFloatOverlay.hidden = false;
  renderFloatingWindowPinState("inspector");
  applyFloatingWindowGeometry("inspector");
  if (dom.inspectorFloatTitle) {
    const node = panel === "node" ? getNode(state.selectedNodeId) : null;
    dom.inspectorFloatTitle.textContent = node ? node.title || t("Node") : t(titleCase(panel));
  }
}

function openFloatingInspector(panel) {
  if (!validPanels.has(panel)) return;
  if (state.floatingInspectorPanel && state.floatingInspectorPanel !== panel) restoreInspectorPanels();
  state.floatingInspectorPanel = panel;
  state.panel = panel;
  renderInspector();
  dom.inspectorFloatOverlay?.querySelector(".inspector-float-window")?.focus?.();
}

function closeFloatingInspector(options = {}) {
  const previousPanel = state.floatingInspectorPanel;
  state.floatingInspectorPanel = "";
  setFloatingWindowPinned("inspector", false);
  restoreInspectorPanels();
  if (dom.inspectorFloatOverlay) dom.inspectorFloatOverlay.hidden = true;
  clearFloatingWindowStyles("inspector");
  renderInspectorTabs();
  if (options.restoreFocus !== false && previousPanel) {
    dom.scope?.querySelector?.(`[data-panel="${CSS.escape(previousPanel)}"]`)?.focus?.();
  }
}

