function renderNodePanel(node) {
  hideVaultFileSuggestions();
  dom.nodePanel.classList.remove("is-empty");
  if (!node) {
    dom.nodePanel.replaceChildren();
    delete dom.nodePanel.dataset.renderedNodeId;
    return;
  }
  // Rebuilding the panel resets the inspector scroll position; keep it when
  // re-rendering the same node so long editors (dialog turns, choice options)
  // don't jump back to the top after every committed edit.
  const scroller = dom.nodePanel.closest(".inspector-panel");
  const keepScroll = dom.nodePanel.dataset.renderedNodeId === node.id;
  const scrollTop = keepScroll && scroller ? scroller.scrollTop : 0;
  dom.nodePanel.dataset.renderedNodeId = node.id;
  const meta = getNodeMeta(node.type);
  dom.nodePanel.innerHTML = `
    <div class="form-stack">
      <label class="field">
        <span>${t("Type")}</span>
        <select data-node-field="type">
          ${getNodeTypeEntries(node.type).map(([type, m]) => `<option value="${escapeAttr(type)}" ${node.type === type ? "selected" : ""}>${escapeHtml(getNodeTypeLabel(type))}${m.hidden ? " (hidden)" : ""}${m.removed ? " (removed)" : ""}</option>`).join("")}
        </select>
      </label>
      ${isEventSheetNode(node) ? renderEventFrameFields(node) : `
        <label class="field">
          <span>${escapeHtml(getNodeTitleLabel(node))}</span>
          <input data-node-field="title" value="${escapeAttr(node.title || "")}">
        </label>
        ${renderNodeBodyField(node)}
        ${renderNodeVaultFileField(node)}
        ${isDialogNode(node) ? renderNodeDialogTurnsField(node) : ""}
        ${renderNodeCastFields(node)}
        ${!isFrameNode(node) ? renderNodeStateLogicFields(node) : ""}
        ${renderTypeFields(node)}
        ${renderCustomFields(node)}
      `}
      <div class="button-row">
        ${isFrameNode(node) ? `<button class="small-button" data-action="open-frame-canvas" data-node-id="${escapeAttr(node.id)}">${t("Open frame canvas")}</button>` : ""}
        <button class="small-button" data-action="duplicate-node">${t("Duplicate")}</button>
        <button class="small-button" data-action="focus-node">${t("Canvas focus")}</button>
        ${!isFrameNode(node) ? `<button class="small-button" data-action="focus-node-document">${t("Document focus")}</button>` : ""}
        <button class="small-button danger-button" data-action="delete-node">${t("Delete node")}</button>
      </div>
    </div>
  `;
  if (keepScroll && scroller) scroller.scrollTop = scrollTop;
}

function renderNodeDialogTurnsField(node) {
  const turns = Array.isArray(node.turns) ? node.turns : [];
  const speakerRatio = normalizeDialogSpeakerRatio(node.dialogSpeakerRatio);
  const expanded = isNodeSectionExpanded("dialogTurns");
  const headerHint = turns.length
    ? t("{count} turns — Play steps through each line. Cast Speaker chips auto-fill from speakers below.", { count: turns.length })
    : t("Optional: split this Dialog into multiple turns so a single node carries a back-and-forth exchange.");
  return `
    <section class="dialog-turns-editor nc-collapsible${expanded ? " expanded" : ""}" style="--dialog-speaker-ratio:${speakerRatio}%">
      <header class="nc-collapsible-header">
        ${renderNodeSectionToggle("dialogTurns", t("Turns"), expanded)}
        <span class="nc-section-count">${escapeHtml(t("{count} turns", { count: turns.length }))}</span>
      </header>
      ${expanded ? `
      <div class="dialog-turns-hint">${escapeHtml(headerHint)}</div>
      <div class="dialog-turns-list">
        ${turns.length === 0 ? `<div class="nc-empty-state">${t("No turns yet.")}</div>` : turns.map((turn, index) => `
          <div class="dialog-turn-row" data-dialog-turn-index="${index}">
            <input data-dialog-turn-index="${index}" data-dialog-turn-field="speaker" list="dialogTurnSpeakerOptions" value="${escapeAttr(turn.speaker || "")}" placeholder="${escapeAttr(t("Speaker"))}" spellcheck="false" data-dialog-turn-focus-target="speaker">
            <span class="dialog-turn-column-separator" data-dialog-column-resize="true" data-dialog-node-id="${escapeAttr(node.id)}" role="separator" aria-orientation="vertical" aria-label="${escapeAttr(t("Resize speaker column"))}" title="${escapeAttr(t("Resize speaker column"))}"></span>
            <textarea data-dialog-turn-index="${index}" data-dialog-turn-field="line" placeholder="${escapeAttr(t("Line"))}" spellcheck="false">${escapeHtml(turn.line || "")}</textarea>
            <div class="dialog-turn-actions">
              <button class="icon-button" type="button" title="${escapeAttr(t("Move turn up"))}" data-action="move-dialog-turn-up" data-dialog-turn-index="${index}" ${index === 0 ? "disabled" : ""}>^</button>
              <button class="icon-button" type="button" title="${escapeAttr(t("Move turn down"))}" data-action="move-dialog-turn-down" data-dialog-turn-index="${index}" ${index === turns.length - 1 ? "disabled" : ""}>v</button>
              <button class="icon-button" type="button" title="${escapeAttr(t("Copy turn"))}" data-action="copy-dialog-turn" data-dialog-turn-index="${index}">C</button>
              <button class="icon-button danger-button" type="button" title="${escapeAttr(t("Delete turn"))}" data-action="delete-dialog-turn" data-dialog-turn-index="${index}">x</button>
            </div>
          </div>
          ${index < turns.length - 1 ? `
            <div class="dialog-turn-split-row">
              <span aria-hidden="true"></span>
              <button class="small-button dialog-turn-split-button" type="button" title="${escapeAttr(t("Split Dialog"))}" data-action="split-dialog-turns" data-dialog-turn-index="${index}">${t("Split after this turn")}</button>
              <span aria-hidden="true"></span>
            </div>
          ` : ""}
        `).join("")}
      </div>
      <div class="dialog-turns-footer">
        <button class="small-button" type="button" data-action="add-dialog-turn">${t("Add turn")}</button>
      </div>
      <datalist id="dialogTurnSpeakerOptions">
        ${getCastCharacters().map((char) => `<option value="${escapeAttr(char.name)}"></option>`).join("")}
      </datalist>
      ` : ""}
    </section>
  `;
}

