async function reloadProjectFileFromUi() {
  if (!confirmDiscardUnsavedProject("Reload the current project and discard unsaved changes?", () => void reloadProjectFileFromUiConfirmed())) return;
  await reloadProjectFileFromUiConfirmed();
}

async function reloadProjectFileFromUiConfirmed() {
  const host = window.NarrativeCanvasHost;
  if (host?.loadProject) {
    const loaded = await loadCurrentVaultProject();
    setStatus(loaded ? `Reloaded ${getHostProjectFileLabel()}.` : "No project file to reload.");
    return;
  }
  const hasWebState = Boolean(loadWebState());
  const restored = await loadSavedState(true);
  if (restored === false && !hasWebState) setStatus("No saved project to reload.");
}

async function handleExternalProjectChange(detail = {}) {
  if (!initialized || state.isSaving) return { reloaded: false, dirty: state.hasUnsavedChanges };
  const path = String(detail?.path || getCurrentProjectFilePath() || "");
  if (state.hasUnsavedChanges) {
    state.externalProjectChangePending = true;
    clearAutoSaveTimer();
    state.saveError = true;
    renderProjectFileStatus();
    const message = t("Project changed outside Narrative Canvas. Reload before continuing; saving now will preserve local work as a conflict copy.");
    setStatus(message);
    window.NarrativeCanvasHost?.showNotice?.(message);
    return { reloaded: false, dirty: true, path };
  }
  const loaded = await loadCurrentVaultProject();
  if (loaded) {
    const message = t("Project changed outside Narrative Canvas and was reloaded.");
    setStatus(message);
    window.NarrativeCanvasHost?.showNotice?.(message);
  }
  return { reloaded: Boolean(loaded), dirty: false, path };
}

// BEGIN WEB_RUNTIME:CLEAR_STORAGE
async function clearBrowserStorageFromUi() {
  if (window.NarrativeCanvasHost) return;
  showGenericConfirm({
    kicker: "Project File",
    title: "Clear browser storage?",
    message: "Clear browser storage and load a blank project? This deletes the project saved in this browser.",
    confirmLabel: "Clear storage",
    danger: true,
    onConfirm: () => clearBrowserStorageConfirmed()
  });
}

async function clearBrowserStorageConfirmed() {
  try {
    getWebProjectStorage()?.removeItem(WEB_STORAGE_KEY);
  } catch (error) {
    console.error(error);
    setStatus("Could not clear browser storage.");
    return;
  }

  state.project = createBlankProject("Untitled");
  markProjectStructureChanged({ nodeTypes: true });
  state.selectedNodeId = "n0";
  state.selectedLinkId = null;
  state.selectedNodeIds = [];
  state.panel = "project";
  state.activeFileId = "adventure";
  centerViewAtScale(DEFAULT_CANVAS_ZOOM, false);
  resetHistory();
  setProjectDirty(true);
  renderAll();
  const saved = await saveCurrentState({ silent: true });
  setStatus(saved ? "Browser storage cleared. Blank project saved." : "Browser storage cleared. Blank project loaded.");
}
// END WEB_RUNTIME:CLEAR_STORAGE

function confirmDiscardUnsavedProject(message, onConfirm) {
  if (!state.hasUnsavedChanges) return true;
  showGenericConfirm({
    kicker: "Unsaved changes",
    title: "Discard unsaved changes?",
    message,
    confirmLabel: "Discard",
    danger: true,
    onConfirm
  });
  return false;
}

function showPlaybookHelp() {
  renderPlaybookHelpDialog();
  if (dom.playbookHelpDialog?.showModal) {
    if (!dom.playbookHelpDialog.open) dom.playbookHelpDialog.showModal();
    return;
  }
  const message = t(`${PLAYBOOK_FILE_NAME} stores runtime variable definitions, node logic rows, Variable Actions, and Play preview rules. Variable Definitions define state. Script Builder edits node Requirements, Effects, and Routing. Variable Actions keep manual or imported state writes outside node rows. Preview rules only control the Play dialog: start node, end condition, debug details, and temporary visit tracking. Validation checks keys and export risks before you ship files.`);
  if (window.NarrativeCanvasHost?.showNotice) {
    window.NarrativeCanvasHost.showNotice(message);
  } else {
    window.alert?.(message);
  }
}

function setPlaybookHelpPage(page) {
  const pages = getPlaybookHelpPages();
  const maxPage = Math.max(0, pages.length - 1);
  state.playbookHelpPage = Math.min(Math.max(Number.isFinite(page) ? page : 0, 0), maxPage);
  renderPlaybookHelpDialog();
}

function showPlayRuleDialog() {
  const firstDisabled = getFirstDisabledPlayRuleKind();
  if (dom.playRuleDialog?.showModal) {
    refreshPlayRuleDialogAvailability();
    if (!dom.playRuleDialog.open) dom.playRuleDialog.showModal();
    return;
  }
  if (firstDisabled) addPlaybookRule(firstDisabled);
}

function getFirstDisabledPlayRuleKind() {
  const rules = getRunnerRules();
  return ["startNode", "endCondition", "debugMode"]
    .find((key) => !rules[key]?.enabled) || "";
}

function refreshPlayRuleDialogAvailability() {
  const dialog = dom.playRuleDialog;
  if (!dialog) return;
  const rules = getRunnerRules();
  let remaining = 0;
  dialog.querySelectorAll("[data-playbook-rule-kind]").forEach((button) => {
    const kind = button.dataset.playbookRuleKind;
    const enabled = Boolean(rules[kind]?.enabled);
    const locked = false;
    button.hidden = enabled;
    button.disabled = enabled || locked;
    if (locked) button.setAttribute("title", t("Enable Debug Mode before Visit Tracking."));
    else button.removeAttribute("title");
    if (!enabled) remaining += 1;
  });
  const allSetMessage = dialog.querySelector("[data-playbook-rule-allset]");
  if (allSetMessage) {
    allSetMessage.hidden = remaining > 0;
    allSetMessage.textContent = t("All preview rules already enabled.");
  }
}

function showNodeContextMenu(nodeId, clientX, clientY) {
  if (!dom.nodeContextMenu) return;
  const node = getNode(nodeId);
  const frameCanvasButton = node && isFrameNode(node)
    ? `<button data-action="open-frame-canvas" data-node-id="${escapeAttr(node.id)}">${t("Open frame canvas")}</button>`
    : "";
  const deleteLabel = node && isFrameNode(node) ? t("Delete frame") : t("Delete node");
  state.contextNodeId = nodeId;
  state.contextLinkId = null;
  state.contextGroup = false;
  dom.nodeContextMenu.setAttribute("aria-label", t("Node layer menu"));
  dom.nodeContextMenu.innerHTML = `
    ${frameCanvasButton}
    <div class="context-menu-label">${t("Node layer")}</div>
    <button data-layer-action="front">${t("Bring to front")}</button>
    <button data-layer-action="forward">${t("Bring forward")}</button>
    <button data-layer-action="backward">${t("Send backward")}</button>
    <button data-layer-action="back">${t("Send to back")}</button>
    <button class="context-menu-danger" data-action="delete-node">${deleteLabel}</button>
  `;
  positionContextMenu(clientX, clientY);
}

function showGroupContextMenu(clientX, clientY) {
  if (!dom.nodeContextMenu) return;
  const count = state.selectedNodeIds.length;
  if (!count) return;
  state.contextNodeId = null;
  state.contextLinkId = null;
  state.contextGroup = true;
  dom.nodeContextMenu.setAttribute("aria-label", t("Node layer menu"));
  dom.nodeContextMenu.innerHTML = `
    <div class="context-menu-label">${t("{count} selected", { count })}</div>
    <div class="context-menu-label">${t("Node layer")}</div>
    <button data-layer-action="front">${t("Bring to front")}</button>
    <button data-layer-action="forward">${t("Bring forward")}</button>
    <button data-layer-action="backward">${t("Send backward")}</button>
    <button data-layer-action="back">${t("Send to back")}</button>
    <button class="context-menu-danger" data-action="delete-selected-nodes">${t("Delete selected nodes", { count })}</button>
  `;
  positionContextMenu(clientX, clientY);
}

function showLinkContextMenu(linkId, clientX, clientY) {
  if (!dom.nodeContextMenu) return;
  const link = getLink(linkId);
  state.contextNodeId = null;
  state.contextLinkId = linkId;
  dom.nodeContextMenu.innerHTML = `
    ${renderChoiceLinkMenu(link)}
    <button data-action="reconnect-link-from">${t("Reconnect from output")}</button>
    <button data-action="reconnect-link-to">${t("Reconnect to input")}</button>
    <button class="context-menu-danger" data-action="delete-context-link">${t("Delete link")}</button>
  `;
  positionContextMenu(clientX, clientY);
}

function renderChoiceLinkMenu(link) {
  const source = link ? getNode(link.from) : null;
  const branchLabels = getBranchLabels(source);
  if (!link || !branchLabels.length) return "";
  const currentIndex = normalizeChoiceIndex(link.choiceIndex);
  return `
    <div class="context-menu-label">${t("Choice branch")}</div>
    ${branchLabels.map((choice, index) => `
      <button data-action="assign-choice-link" data-link-id="${escapeAttr(link.id)}" data-choice-index="${index}" aria-current="${currentIndex === index ? "true" : "false"}">
        <span class="context-menu-check">${currentIndex === index ? "*" : ""}</span>
        <span>${escapeHtml(choice)}</span>
      </button>
    `).join("")}
    <div class="context-menu-label">${t("Link")}</div>
  `;
}

function positionContextMenu(clientX, clientY) {
  if (!dom.nodeContextMenu) return;
  dom.nodeContextMenu.style.left = "0px";
  dom.nodeContextMenu.style.top = "0px";
  dom.nodeContextMenu.style.display = "grid";
  dom.nodeContextMenu.hidden = false;
  dom.nodeContextMenu.setAttribute("aria-hidden", "false");
  const menuRect = dom.nodeContextMenu.getBoundingClientRect();
  const containerRect = getContextMenuContainerRect();
  const pointerX = clientX - containerRect.left;
  const pointerY = clientY - containerRect.top;
  const maxLeft = Math.max(8, containerRect.width - menuRect.width - 8);
  const maxTop = Math.max(8, containerRect.height - menuRect.height - 8);
  dom.nodeContextMenu.style.left = `${clamp(pointerX + 4, 8, maxLeft)}px`;
  dom.nodeContextMenu.style.top = `${clamp(pointerY + 4, 8, maxTop)}px`;
}

function getContextMenuContainerRect(element = dom.nodeContextMenu) {
  const parent = element?.offsetParent;
  if (parent?.getBoundingClientRect) return parent.getBoundingClientRect();
  return { left: 0, top: 0, width: window.innerWidth, height: window.innerHeight };
}

function hideNodeContextMenu() {
  state.contextNodeId = null;
  state.contextLinkId = null;
  state.contextGroup = false;
  hideCanvasRadialMenu();
  if (!dom.nodeContextMenu) return;
  dom.nodeContextMenu.hidden = true;
  dom.nodeContextMenu.style.display = "none";
  dom.nodeContextMenu.setAttribute("aria-hidden", "true");
}

function isCanvasRadialMenuOpen() {
  return Boolean(dom.canvasRadialMenu && !dom.canvasRadialMenu.hidden);
}

function hideCanvasRadialMenu() {
  if (!dom.canvasRadialMenu) return;
  const addList = dom.canvasRadialMenu.querySelector(".radial-add-list");
  if (addList) addList.hidden = true;
  dom.canvasRadialMenu.querySelectorAll("[data-radial-toggle]").forEach((toggle) => {
    toggle.setAttribute("aria-expanded", "false");
  });
  const focused = getScopeActiveElement();
  if (focused && dom.canvasRadialMenu.contains(focused) && typeof focused.blur === "function") focused.blur();
  dom.canvasRadialMenu.hidden = true;
  dom.canvasRadialMenu.setAttribute("aria-hidden", "true");
}

function readNodeSpawnPoint(target) {
  const x = Number(target?.dataset?.spawnX);
  const y = Number(target?.dataset?.spawnY);
  return Number.isFinite(x) && Number.isFinite(y) ? { x, y } : null;
}

function getRadialFrameNodeType() {
  const entries = getNodeTypeEntries();
  const frameEntry = entries.find(([type]) => type === "Frame") || entries.find(([, meta]) => isFrameKind(meta.kind));
  return frameEntry ? frameEntry[0] : "";
}

function renderCanvasRadialAddList(spawn) {
  const entries = getNodeTypeEntries();
  if (!entries.length) return `<div class="radial-add-empty">${t("No visible node types.")}</div>`;
  return entries.map(([type, meta]) => `
    <button class="radial-add-item" type="button" role="menuitem" data-action="add-node" data-type="${escapeAttr(type)}" data-spawn-x="${escapeAttr(String(spawn.x))}" data-spawn-y="${escapeAttr(String(spawn.y))}">
      <span class="radial-add-badge" data-icon-size="${getNodeIconSize(meta.badge)}" style="--node-color:${escapeAttr(meta.color)}">${escapeHtml(meta.badge)}</span>
      <span class="radial-add-label">${escapeHtml(getNodeTypeLabel(type))}</span>
    </button>
  `).join("");
}

function showCanvasRadialMenu(clientX, clientY) {
  if (!dom.canvasRadialMenu) return;
  hideNodeContextMenu();
  const spawn = screenToBoard(clientX, clientY);
  const frameType = getRadialFrameNodeType();
  const spawnAttrs = `data-spawn-x="${escapeAttr(String(spawn.x))}" data-spawn-y="${escapeAttr(String(spawn.y))}"`;
  dom.canvasRadialMenu.setAttribute("aria-label", t("Canvas quick menu"));
  dom.canvasRadialMenu.innerHTML = `
    <svg class="radial-arc" viewBox="0 0 180 180" role="group" aria-label="${escapeAttr(t("Canvas quick menu"))}">
      <g class="radial-button radial-segment-1" data-radial-toggle="add" role="button" tabindex="0" aria-haspopup="menu" aria-expanded="false" aria-label="${escapeAttr(t("Add"))}">
        <title>${escapeHtml(t("Add"))}</title>
        <polygon class="radial-wedge" points="90,0 153.72,26.28 118.26,61.74 90,50.04"></polygon>
        <text class="radial-icon" x="115.2" y="27.6" text-anchor="middle" dominant-baseline="middle">＋</text>
        <text class="radial-label" x="115.2" y="39.6" text-anchor="middle" dominant-baseline="middle">${escapeHtml(t("Add"))}</text>
      </g>
      <g class="radial-button radial-segment-2${frameType ? "" : " is-disabled"}" ${frameType ? `data-action="add-node" data-type="${escapeAttr(frameType)}" ${spawnAttrs} role="button" tabindex="0"` : `aria-disabled="true"`} aria-label="${escapeAttr(t("Frame"))}">
        <title>${escapeHtml(t("Frame"))}</title>
        <polygon class="radial-wedge" points="153.72,26.28 180,90 129.96,90 118.26,61.74"></polygon>
        <text class="radial-icon" x="149.4" y="61.8" text-anchor="middle" dominant-baseline="middle">▣</text>
        <text class="radial-label" x="149.4" y="73.8" text-anchor="middle" dominant-baseline="middle">${escapeHtml(t("Frame"))}</text>
      </g>
      <g class="radial-button radial-segment-3" data-action="play" role="button" tabindex="0" aria-label="${escapeAttr(t("Play"))}">
        <title>${escapeHtml(t("Play"))}</title>
        <polygon class="radial-wedge" points="180,90 153.72,153.72 118.26,118.26 129.96,90"></polygon>
        <text class="radial-icon" x="149.4" y="112.2" text-anchor="middle" dominant-baseline="middle">▶</text>
        <text class="radial-label" x="149.4" y="124.2" text-anchor="middle" dominant-baseline="middle">${escapeHtml(t("Play"))}</text>
      </g>
      <g class="radial-button radial-segment-4" data-action="center-view" role="button" tabindex="0" aria-label="${escapeAttr(t("Center"))}">
        <title>${escapeHtml(t("Center"))}</title>
        <polygon class="radial-wedge" points="153.72,153.72 90,180 90,129.96 118.26,118.26"></polygon>
        <text class="radial-icon" x="115.2" y="146.4" text-anchor="middle" dominant-baseline="middle">⌖</text>
        <text class="radial-label" x="115.2" y="158.4" text-anchor="middle" dominant-baseline="middle">${escapeHtml(t("Center"))}</text>
      </g>
    </svg>
    <button class="radial-hub" type="button" data-radial-close="true" title="${escapeAttr(t("Close"))}" aria-label="${escapeAttr(t("Close"))}">×</button>
    <div class="radial-add-list" role="menu" aria-label="${escapeAttr(t("Node Library"))}" hidden>${renderCanvasRadialAddList(spawn)}</div>
  `;
  positionCanvasRadialMenu(clientX, clientY);
}

function positionCanvasRadialMenu(clientX, clientY) {
  if (!dom.canvasRadialMenu) return;
  dom.canvasRadialMenu.hidden = false;
  dom.canvasRadialMenu.setAttribute("aria-hidden", "false");
  const containerRect = getContextMenuContainerRect(dom.canvasRadialMenu);
  const margin = 104;
  const pointerX = clientX - containerRect.left;
  const pointerY = clientY - containerRect.top;
  const maxLeft = Math.max(margin, containerRect.width - margin);
  const maxTop = Math.max(margin, containerRect.height - margin);
  dom.canvasRadialMenu.style.left = `${clamp(pointerX, margin, maxLeft)}px`;
  dom.canvasRadialMenu.style.top = `${clamp(pointerY, margin, maxTop)}px`;
}

function handleCanvasRadialMenuKeydown(event) {
  if (event.key !== "Enter" && event.key !== " " && event.key !== "Spacebar") return;
  if (!event.target.closest?.("[data-action], [data-radial-toggle], [data-radial-close]")) return;
  // SVG <g role="button"> segments don't fire a native click on Enter/Space; route the key to the
  // same handler so the radial menu keeps full keyboard support after the clip-path→SVG rewrite.
  event.preventDefault();
  handleCanvasRadialMenuClick(event);
}

function handleCanvasRadialMenuClick(event) {
  if (event.target.closest("[data-radial-close]")) {
    event.stopPropagation();
    hideCanvasRadialMenu();
    return;
  }
  const toggleTarget = event.target.closest("[data-radial-toggle]");
  if (toggleTarget) {
    event.stopPropagation();
    const list = dom.canvasRadialMenu?.querySelector(".radial-add-list");
    if (!list) return;
    list.hidden = !list.hidden;
    toggleTarget.setAttribute("aria-expanded", String(!list.hidden));
    if (!list.hidden && event.type === "keydown") {
      list.querySelector("[role='menuitem']")?.focus();
    } else if (typeof toggleTarget.blur === "function") {
      toggleTarget.blur();
    }
    return;
  }
  const actionTarget = event.target.closest("[data-action]");
  if (!actionTarget) return;
  event.preventDefault();
  event.stopPropagation();
  if (typeof event.stopImmediatePropagation === "function") event.stopImmediatePropagation();
  try {
    handleAction(actionTarget);
  } finally {
    hideCanvasRadialMenu();
  }
}

function moveContextNode(action) {
  const nodeId = state.contextNodeId;
  if (!nodeId) return;
  const changed = moveNodeLayer(nodeId, action);
  hideNodeContextMenu();
  if (!changed) return;
  state.selectedNodeId = nodeId;
  renderNodes();
  renderLinks();
  renderMinimap();
  renderInspector();
  setStatus("Node layer updated.");
}

function moveNodeLayer(nodeId, action) {
  const node = getNode(nodeId);
  if (!node) return false;
  const layerItems = getLayerItemsForNodeScope(node);
  const layerIndex = layerItems.findIndex((item) => item.node.id === nodeId);
  if (layerIndex < 0) return false;
  let targetLayerIndex = layerIndex;

  if (action === "front") {
    targetLayerIndex = layerItems.length - 1;
  } else if (action === "back") {
    targetLayerIndex = 0;
  } else if (action === "forward") {
    targetLayerIndex = Math.min(layerIndex + 1, layerItems.length - 1);
  } else if (action === "backward") {
    targetLayerIndex = Math.max(layerIndex - 1, 0);
  } else {
    return false;
  }

  if (targetLayerIndex === layerIndex) return false;

  const [movedItem] = layerItems.splice(layerIndex, 1);
  layerItems.splice(targetLayerIndex, 0, movedItem);
  assignLayerOrdersForScope(layerItems, isFrameNode(node));
  state.project.nodes = getCanvasLayerItems().map((item) => item.node);
  return true;
}

function moveSelectedNodesLayer(action) {
  const ids = new Set(state.selectedNodeIds);
  if (!ids.size) return false;
  const scopes = [
    getCanvasLayerItems().filter((item) => isFrameNode(item.node)),
    getCanvasLayerItems().filter((item) => !isFrameNode(item.node))
  ].filter((items) => items.some((item) => ids.has(item.node.id)));
  if (!scopes.length) return false;
  let changed = false;
  scopes.forEach((items) => {
    changed = moveSelectedLayerItemsWithinScope(items, ids, action) || changed;
  });
  if (!changed) return false;
  state.project.nodes = getCanvasLayerItems().map((item) => item.node);
  return true;
}

function moveSelectedLayerItemsWithinScope(items, ids, action) {
  const total = items.length;
  const selectedIndexes = items.reduce((indexes, item, index) => {
    if (ids.has(item.node.id)) indexes.push(index);
    return indexes;
  }, []);
  if (!selectedIndexes.length) return false;

  let arranged;
  if (action === "front") {
    const selected = selectedIndexes.map((index) => items[index]);
    arranged = [...items.filter((item) => !ids.has(item.node.id)), ...selected];
  } else if (action === "back") {
    const selected = selectedIndexes.map((index) => items[index]);
    arranged = [...selected, ...items.filter((item) => !ids.has(item.node.id))];
  } else if (action === "forward" || action === "backward") {
    const direction = action === "forward" ? 1 : -1;
    arranged = items.slice();
    const sequence = direction === 1 ? selectedIndexes.slice().reverse() : selectedIndexes.slice();
    sequence.forEach((index) => {
      const swapIndex = index + direction;
      if (swapIndex < 0 || swapIndex >= total) return;
      if (ids.has(arranged[swapIndex].node.id)) return;
      const temp = arranged[index];
      arranged[index] = arranged[swapIndex];
      arranged[swapIndex] = temp;
    });
  } else {
    return false;
  }

  const unchanged = arranged.every((item, index) => item === items[index]);
  if (unchanged) return false;
  assignLayerOrdersForScope(arranged, isFrameNode(arranged[0]?.node));
  return true;
}

function getLayerItemsForNodeScope(node) {
  const frameScope = isFrameNode(node);
  return getCanvasLayerItems().filter((item) => isFrameNode(item.node) === frameScope);
}

function assignLayerOrdersForScope(items, frameScope) {
  const base = frameScope ? EVENT_LAYER_BASE : REGULAR_LAYER_BASE;
  items.forEach((item, index) => {
    item.node.layerOrder = base + index;
  });
}

function moveContextSelection(action) {
  const changed = moveSelectedNodesLayer(action);
  hideNodeContextMenu();
  if (!changed) return;
  renderNodes();
  renderLinks();
  renderMinimap();
  renderInspector();
  setStatus("Node layers updated.");
}

function deleteSelectedNodes() {
  const ids = state.selectedNodeIds.filter((id) => getNode(id));
  if (ids.length <= 1) {
    if (ids.length === 1) state.selectedNodeId = ids[0];
    deleteSelectedNode();
    return;
  }
  const targets = getDeletionReferenceTargets(ids);
  const refs = collectNodeTargetReferences(targets);
  if (refs.length) {
    showGenericConfirm({
      kicker: "References",
      title: t("Delete {count} nodes with references?", { count: ids.length }),
      message: t("{references} point to these nodes. Delete and clear those references, or keep the references as orphan warnings.", {
        references: formatReferenceSummary(refs)
      }),
      confirmLabel: "Delete and clear references",
      secondaryLabel: "Keep orphan references",
      danger: true,
      recordHistory: true,
      onConfirm: () => deleteSelectedNodesConfirmed(ids, { removeReferences: true }),
      onSecondary: () => deleteSelectedNodesConfirmed(ids, { removeReferences: false })
    });
    return;
  }
  deleteSelectedNodesConfirmed(ids, { removeReferences: false });
}

function deleteSelectedNodesConfirmed(ids, options = {}) {
  if (options.removeReferences) removeNodeTargetReferences(ids);
  ids.forEach((id) => archiveDeletedNode(id));
  const idSet = new Set(ids);
  reparentChildrenOfDeletedFrames(idSet);
  state.project.nodes = state.project.nodes.filter((node) => !idSet.has(node.id));
  state.project.links = state.project.links.filter((link) => !idSet.has(link.from) && !idSet.has(link.to));
  markProjectStructureChanged();
  invalidateCharacterRenderContext();
  clearStoryOrderOverrides();
  clearEventRowOrderOverrides();
  clearNodeSelection();
  hideNodeContextMenu();
  renderAll();
  refreshOpenPreviewEntrySelector();
  setStatus(`${ids.length} nodes deleted and archived outside runtime.`);
}

function reparentChildrenOfDeletedFrames(deletedIds) {
  const ids = deletedIds instanceof Set ? deletedIds : new Set(deletedIds || []);
  if (!ids.size) return;
  const nodeMap = new Map(state.project.nodes.map((node) => [node.id, node]));
  state.project.nodes.forEach((node) => {
    if (ids.has(node.id) || !ids.has(normalizeOptionalString(node.frameId).trim())) return;
    let parentId = normalizeOptionalString(node.frameId).trim();
    const seen = new Set();
    while (parentId && ids.has(parentId) && !seen.has(parentId)) {
      seen.add(parentId);
      parentId = normalizeOptionalString(nodeMap.get(parentId)?.frameId).trim();
    }
    node.frameId = parentId && !ids.has(parentId) && isFrameNode(nodeMap.get(parentId)) ? parentId : "";
  });
}

function selectFile(fileId) {
  if (!fileViews[fileId]) return;
  if (state.activeFileId === fileId) {
    if (fileId === "characters" && state.codexSelectedEntryId) closeCodexEntryDetail();
    return;
  }
  state.activeFileId = fileId;
  // Each page starts at its top; the back-to-top button resets with it.
  dom.root?.classList.remove("workspace-scrolled");

  if (fileId === "adventure") {
    state.panel = state.selectedNodeId ? "node" : "project";
    renderCanvasFileSwitch();
    setStatus(`${fileViews.adventure} opened.`);
    return;
  }

  if (fileId === "characters") {
    // Keep the last-opened entry detail when returning from another file;
    // re-clicking the Library tab while already there returns to the overview (see above).
    renderDocumentFileSwitch();
    setStatus("Library.md opened.");
    return;
  }

  if (fileId === "events") {
    renderDocumentFileSwitch();
    setStatus("Events Sheet.csv opened.");
    return;
  }

  if (fileId === "document") {
    renderDocumentFileSwitch();
    setStatus("Document.md opened.");
    return;
  }

  renderDocumentFileSwitch();
  setStatus(`${PLAYBOOK_FILE_NAME} opened.`);
}

function renderDocumentFileSwitch() {
  hideNodeContextMenu();
  renderShellState();
  renderWorkspaceFile();
  renderInspectorTabs();
  updateStatus();
  renderHistoryButtons();
}

function renderCanvasFileSwitch() {
  hideNodeContextMenu();
  renderShellState();
  renderWorkspaceFile();
  renderInspector();
  updateStatus();
  renderHistoryButtons();
}

function getEditableHistoryKey(target) {
  if (!target?.dataset) return "";
  if (target === dom.queryInput || target.hasAttribute?.("data-character-search") || target.hasAttribute?.("data-event-search")) return "";
  const parts = [];
  ["documentSource", "projectField", "nodeField", "nodeVaultFileIndex", "inlineNodeField", "inlineLinkLabel", "nodeCustomField", "characterField", "variableField", "eventField", "nodeCastField", "nodeConditionField", "nodeLogicField", "nodeEffectField", "nodeRoutingField", "choiceTimerField", "choiceConditionField", "choiceOptionField", "choiceOptionEffectField", "dialogTurnField", "playbookActionField", "scriptConditionField", "scriptNodeField", "gateConditionField", "gateEffectField", "gateField", "runnerRuleField", "runnerRuleEnabled"].forEach((name) => {
    if (target.dataset[name]) parts.push(`${name}:${target.dataset[name]}`);
  });
  ["nodeId", "linkId", "choiceNodeId", "dialogNodeId", "characterId", "variableKey", "eventNodeId", "nodeCastIndex", "conditionIndex", "nodeEffectIndex", "choiceOptionId", "choiceOptionIndex", "dialogTurnIndex", "choiceOptionEffectIndex", "playbookActionId", "scriptNodeId", "gateId", "gateEffectId", "gateEffectIndex"].forEach((name) => {
    if (target.dataset[name]) parts.push(`${name}:${target.dataset[name]}`);
  });
  return parts.join("|");
}

function handleEditFocusIn(event) {
  if (!isNarrativeCanvasTarget(event.target)) return;
  if (event.target?.hasAttribute?.("data-character-tag-input")) updateCodexTagSuggestions(event.target);
  if (event.target?.hasAttribute?.("data-cast-entry-input")) {
    event.target.select?.();
    openCastEntrySuggestions(event.target);
  }
  beginNodeTitleReferenceEdit(event.target);
  if (event.target?.dataset?.nodeVaultSizeSlider == null
    && (event.target?.dataset?.nodeVaultFileIndex != null || event.target?.dataset?.characterImageFile || event.target?.dataset?.characterImagePickerInput || event.target?.dataset?.characterVaultFileInput != null || event.target?.dataset?.characterIconInput != null)) {
    if (state.vaultFileSuggestionSuppressedTargets?.has(event.target)) {
      state.vaultFileSuggestionSuppressedTargets.delete(event.target);
    }
    // Force so an empty input lists every file on focus — the browse buttons are gone,
    // the search input is the single entry point.
    else void updateVaultFileSuggestions(event.target, { force: true });
  }
  const key = getEditableHistoryKey(event.target);
  if (!key) return;
  state.editHistoryTarget = {
    key,
    snapshot: getHistorySnapshot()
  };
}

function handleEditFocusOut(event) {
  const target = event.target;
  // "Render by default" fields drop back to the rendered view when the source
  // textarea loses focus — including clicking the modal chrome or the sidebar.
  // Clicking a formatting-toolbar button is exempt: it re-enters edit itself, so
  // rendering there would just flash the view.
  const liveWrap = target?.dataset?.liveSource !== undefined ? target.closest("[data-live-field]") : null;
  if (liveWrap
    && !liveWrap.contains(event.relatedTarget)
    && !event.relatedTarget?.closest?.(".expand-editor-toolbar")) {
    renderLiveField(liveWrap);
  }
  if (target?.hasAttribute?.("data-character-tag-input")) {
    const editor = target.closest("[data-character-tag-editor]");
    if (!editor?.contains(event.relatedTarget)) hideCodexTagSuggestions(target);
    return;
  }
  if (target?.hasAttribute?.("data-cast-entry-input")) {
    const picker = target.closest("[data-cast-entry-picker]");
    if (!picker?.contains(event.relatedTarget)) {
      hideCastEntrySuggestions();
      restoreCastEntryInputValue(target);
    }
    return;
  }
  if (target?.dataset?.projectField === "variables") {
    setProjectField("variables", target.value);
  }
  commitFocusedEdit(event.target);
  finishNodeTitleReferenceEdit(target);
  if ((target?.dataset?.nodeVaultFileIndex != null || target?.dataset?.characterImageFile || target?.dataset?.characterImagePickerInput || target?.dataset?.characterVaultFileInput != null || target?.dataset?.characterIconInput != null)
    && !event.relatedTarget?.closest?.("[data-vault-file-suggestions]")) {
    hideVaultFileSuggestions();
  }
  if (target?.dataset?.inlineNodeField) {
    if (event.relatedTarget && dom.mentionPopover?.contains(event.relatedTarget)) return;
    if (shouldKeepInlineNodeEditOnFocusOut(target.dataset.nodeId, event.relatedTarget)) {
      requestAnimationFrame(() => focusInlineNodeEditor(target.dataset.nodeId));
      return;
    }
    finishInlineNodeEdit(target.dataset.nodeId);
  }
  if (target?.dataset?.inlineLinkLabel != null) {
    finishInlineLinkLabelEdit(target.dataset.linkId);
  }
}

function commitFocusedEdit(target) {
  const key = getEditableHistoryKey(target);
  if (!key || !state.editHistoryTarget || state.editHistoryTarget.key !== key) return false;
  const changed = commitHistoryFromSnapshot(state.editHistoryTarget.snapshot);
  state.editHistoryTarget = null;
  return changed;
}

function handleInput(event) {
  const target = event.target;
  const isMentionTarget = isMentionField(target);
  if (isMentionTarget) {
    updateMentionFromTarget(target);
  }
  if (!isMentionTarget && !isNarrativeCanvasTarget(target)) return;

  if (target.dataset?.inlineLinkLabel != null) {
    setInlineLinkLabel(target.dataset.linkId, target.value);
    return;
  }

  if (target.hasAttribute?.("data-character-tag-input")) {
    handleCodexTagInput(target);
    return;
  }

  if (target.hasAttribute?.("data-cast-entry-input")) {
    openCastEntrySuggestions(target);
    return;
  }

  if (target.hasAttribute?.("data-ai-prompt")) {
    state.aiPromptDraft = target.value;
    return;
  }

  if (target.dataset?.nodeVaultSizeSlider != null) {
    setNodeVaultPreviewSize(target.dataset.nodeId, Number(target.dataset.nodeVaultFileIndex), target.value, false);
    return;
  }

  if (target.dataset?.nodeVaultFileIndex != null) {
    setNodeVaultFile(Number(target.dataset.nodeVaultFileIndex), target.value);
    void updateVaultFileSuggestions(target);
    return;
  }

  if (target.dataset?.characterImageFile) {
    setCharacterField(target.dataset.characterId, "imageFile", target.value, false);
    void updateVaultFileSuggestions(target);
    return;
  }

  if (target.dataset?.characterVaultFileInput != null || target.dataset?.characterIconInput != null) {
    void updateVaultFileSuggestions(target, { force: true });
    return;
  }

  if (target.dataset?.characterImagePickerInput) {
    void updateVaultFileSuggestions(target, { force: true });
    return;
  }

  if (target.hasAttribute?.("data-document-source")) {
    state.documentDraft = target.value;
    state.documentDraftFormat = state.documentFormat;
    state.documentApplyStatus = "pending";
    state.documentLastError = "";
    updateDocumentSyncStatus();
    syncDocumentEditorGutter(target);
    scheduleDocumentHighlight(target);
    if ((state.documentSearch || "").trim()) {
      updateDocumentSearchMatches();
      renderDocumentSearchLayer(target);
      refreshWorkspaceSearchCount();
    }
    scheduleDocumentSourceApply();
    return;
  }

  if (target === dom.queryInput) {
    state.search = target.value;
    state.searchIndex = -1;
    if (target.value.trim() && state.activeFileId !== "adventure") {
      state.activeFileId = "adventure";
      renderShellState();
      renderWorkspaceFile();
    }
    const canvasRenderContext = getCanvasRenderContext();
    renderTransform();
    renderNodes(canvasRenderContext);
    renderLinks(canvasRenderContext);
    updateStatus();
    refreshWorkspaceSearchCount();
    return;
  }

  if (target.hasAttribute && target.hasAttribute("data-character-search")) {
    state.characterSearch = target.value;
    state.characterSearchIndex = -1;
    resetDocumentRenderLimit("characters");
    renderCharacterGridForSearch();
    refreshWorkspaceSearchCount();
    return;
  }

  if (target.hasAttribute && target.hasAttribute("data-event-search")) {
    state.eventSearch = target.value;
    state.eventSearchIndex = -1;
    resetDocumentRenderLimit("events");
    renderEventSheetGroupsForSearch();
    refreshWorkspaceSearchCount();
    return;
  }

  if (target.hasAttribute && target.hasAttribute("data-playbook-search")) {
    state.playbookSearch = target.value;
    state.playbookSearchIndex = -1;
    hidePlaybookJsonSearchHighlight();
    refreshWorkspaceSearchCount();
    return;
  }

  if (target.hasAttribute && target.hasAttribute("data-document-search")) {
    state.documentSearch = target.value;
    state.documentSearchIndex = -1;
    updateDocumentSearchMatches();
    const editor = dom.documentPanel?.querySelector("[data-document-source]");
    if (editor) {
      if (state.documentSearchMatches.length) {
        state.documentSearchIndex = 0;
        renderDocumentSearchLayer(editor);
        focusDocumentSearchMatch(state.documentSearchMatches[0].start);
      } else {
        renderDocumentSearchLayer(editor);
      }
    }
    refreshWorkspaceSearchCount();
    return;
  }

  if (target.dataset.characterField) {
    setCharacterField(target.dataset.characterId, target.dataset.characterField, target.value, false);
    return;
  }

  if (target.dataset.characterExtraPart) {
    if (target.dataset.characterExtraPart === "value") {
      const character = getCharacters().find((item) => item.id === target.dataset.characterId);
      const field = normalizeCodexExtraFields(character?.extraFields)[Number(target.dataset.characterExtraIndex)];
      if (field && field.type !== "string") return;
    }
    setCharacterExtraField(target.dataset.characterId, Number(target.dataset.characterExtraIndex), target.dataset.characterExtraPart, target.value, false);
    return;
  }

  if (target.dataset.variableField === "value") {
    setVariableField(target.dataset.variableKey, "value", target.value, false);
    return;
  }

  if (target.dataset.playbookActionField) {
    setPlaybookActionField(target.dataset.playbookActionId, target.dataset.playbookActionField, getPlaybookActionInputValue(target), false);
    return;
  }

  if (target.dataset.draftField && target.closest(".playbook-action-draft-row")) {
    syncPlaybookActionDraftFromRow(target.closest(".playbook-action-draft-row"));
    return;
  }

  if (target.dataset.draftField && target.closest(".effect-draft-row")) {
    syncEffectDraftRow(target.closest(".effect-draft-row"), target.dataset.draftField);
    return;
  }

  if (target.dataset.draftField && target.closest(".condition-draft-row")) {
    syncConditionDraftRow(target.closest(".condition-draft-row"), target.dataset.draftField);
    return;
  }

  if (target.dataset.eventField) {
    setEventField(target.dataset.eventNodeId, target.dataset.eventField, target.value, false);
    return;
  }

  if (target.dataset.nodeCastField) {
    setNodeCastField(Number(target.dataset.nodeCastIndex), target.dataset.nodeCastField, target.value, false);
    return;
  }
  if (target.dataset.nodeConditionField) {
    setNodeConditionPart(target.dataset.nodeConditionField, target.value, Number(target.dataset.conditionIndex), false);
    return;
  }
  if (target.dataset.nodeLogicField) {
    setNodeLogicField(target.dataset.nodeLogicField, target.value, false);
    return;
  }
  if (target.dataset.nodeRoutingField) {
    setNodeRoutingField(target.dataset.nodeRoutingField, target.value, false);
    return;
  }
  if (target.dataset.nodeEffectField) {
    setNodeEffectField(Number(target.dataset.nodeEffectIndex), target.dataset.nodeEffectField, target.value, false);
    return;
  }
  if (target.dataset.choiceTimerField) {
    setChoiceTimerField(target.dataset.choiceTimerField, target.value, false);
    return;
  }
  if (target.dataset.choiceOptionField) {
    if (target.dataset.canvasChoiceOption) {
      setCanvasChoiceOptionLabel(target.dataset.choiceNodeId, target.dataset.choiceOptionId, Number(target.dataset.choiceOptionIndex), target.value, false);
      return;
    }
    setChoiceOptionField(target.dataset.choiceOptionId, target.dataset.choiceOptionField, target.value, false);
    updatePlaybookCodeStatusForControl(target);
    return;
  }
  if (target.dataset.choiceConditionField) {
    setChoiceOptionConditionPart(target.dataset.choiceOptionId, target.dataset.choiceConditionField, target.value, Number(target.dataset.conditionIndex), false);
    return;
  }
  if (target.dataset.choiceOptionEffectField) {
    setChoiceOptionEffectField(target.dataset.choiceOptionId, Number(target.dataset.choiceOptionEffectIndex), target.dataset.choiceOptionEffectField, target.value, false);
    return;
  }
  if (target.dataset.dialogTurnField) {
    if (target.dataset.canvasDialogTurn) {
      setCanvasDialogTurnField(target.dataset.dialogNodeId, Number(target.dataset.dialogTurnIndex), target.dataset.dialogTurnField, target.value, false);
      return;
    }
    setDialogTurnField(Number(target.dataset.dialogTurnIndex), target.dataset.dialogTurnField, target.value, false);
    return;
  }
  if (target.dataset.scriptConditionField) {
    setScriptNodeConditionPart(target.dataset.scriptNodeId, target.dataset.scriptConditionField, target.value, Number(target.dataset.conditionIndex), false);
    return;
  }
  if (target.dataset.scriptNodeField) {
    setScriptNodeField(target.dataset.scriptNodeId, target.dataset.scriptNodeField, target.value, false);
    updatePlaybookCodeStatusForControl(target);
    return;
  }
  if (target.dataset.gateField) {
    setGateField(target.dataset.gateId, target.dataset.gateField, target.value, false);
    updatePlaybookCodeStatusForControl(target);
    return;
  }
  if (target.dataset.gateConditionField) {
    setGateConditionPart(target.dataset.gateId, target.dataset.gateConditionField, target.value, Number(target.dataset.conditionIndex), false);
    return;
  }
  if (target.dataset.gateEffectField) {
    setChoiceOptionEffectByGateId(target.dataset.gateEffectId, Number(target.dataset.gateEffectIndex), target.dataset.gateEffectField, target.value, false);
    return;
  }
  if (target.dataset.runnerRuleField) {
    setRunnerRuleField(target.dataset.runnerRuleField, getRunnerRuleInputValue(target), false);
    if (target.dataset.runnerRuleField === "endCondition") updateEndConditionStatusHint(target);
    return;
  }

  if (target.dataset.nodeCustomField) {
    setNodeCustomField(target.dataset.nodeCustomField, target.value, false);
    return;
  }

  if (target.dataset.inlineNodeField) {
    if (target.dataset.inlineNodeField === "title") beginNodeTitleReferenceEdit(target);
    setInlineNodeField(target.dataset.nodeId, target.dataset.inlineNodeField, target.value);
    return;
  }

  if (target.dataset.projectField) {
    if (target.dataset.projectField === "variables") {
      resizePlaybookJsonTextarea(target);
      return;
    }
    setProjectField(target.dataset.projectField, target.value);
    return;
  }

  if (target.dataset.nodeField) {
    if (target.dataset.nodeField === "title") beginNodeTitleReferenceEdit(target);
    setNodeField(target.dataset.nodeField, target.value);
  }
}

function handleChange(event) {
  const target = event.target;
  if (!isNarrativeCanvasTarget(target)) return;

  if (target.dataset?.expandRichTextFormat !== undefined) {
    setExpandEditorRichTextFormat(target.value);
    return;
  }

  if (target.dataset?.expandColor) {
    target.closest(".expand-color-control")?.style.setProperty("--expand-selected-color", normalizeRichTextColor(target.value));
    applyExpandEditorColor(target.dataset.expandColor, target.value);
    return;
  }

  if (target.dataset?.nodeVaultSizeSlider != null) {
    setNodeVaultPreviewSize(target.dataset.nodeId, Number(target.dataset.nodeVaultFileIndex), target.value, true);
    commitFocusedEdit(target);
    return;
  }

  if (target.hasAttribute?.("data-codex-local-image-input")) {
    const files = [...(target.files || [])];
    target.value = "";
    void importLocalCodexImages(target.dataset.characterId, files);
    return;
  }

  if (target.hasAttribute?.("data-document-source")) {
    state.documentDraft = target.value;
    state.documentDraftFormat = state.documentFormat;
    flushDocumentSourceApply();
    commitFocusedEdit(target);
    return;
  }

  if (target === dom.exportImageScale) {
    setExportImageScale(target.value);
    return;
  }
  if (target === dom.nodeTypeKindInput) {
    syncNodeTypeEventSheetOption();
    const typeDef = getNodeTypeDef(state.typeDialogType);
    if (typeDef) {
      const template = normalizeNodeTypeTemplate(target.value, typeDef.type, typeDef.kind);
      renderNodeTypeFieldSections({ ...typeDef, template, kind: template === "frame" ? "frame" : "node" });
    }
    return;
  }

  if (target.dataset.characterField) {
    setCharacterField(target.dataset.characterId, target.dataset.characterField, target.value, true);
    commitFocusedEdit(target);
    finishNodeTitleReferenceEdit(target);
    return;
  }
  if (target.dataset.characterExtraPart) {
    setCharacterExtraField(target.dataset.characterId, Number(target.dataset.characterExtraIndex), target.dataset.characterExtraPart, target.value, true);
    commitFocusedEdit(target);
    return;
  }
  if (target.dataset.variableField) {
    setVariableField(target.dataset.variableKey, target.dataset.variableField, target.value, true);
    commitFocusedEdit(target);
    return;
  }
  if (target.dataset.playbookActionField) {
    setPlaybookActionField(target.dataset.playbookActionId, target.dataset.playbookActionField, getPlaybookActionInputValue(target), true);
    commitFocusedEdit(target);
    return;
  }
  if (target.dataset.draftField && target.closest(".playbook-action-draft-row")) {
    const row = target.closest(".playbook-action-draft-row");
    syncPlaybookActionDraftFromRow(row);
    if (target.dataset.draftField === "key" || target.dataset.draftField === "op") {
      normalizePlaybookActionDraft({ resetValue: target.dataset.draftField === "key", coerceValue: target.dataset.draftField === "op" });
      renderPlaybookSurfaces();
    }
    commitFocusedEdit(target);
    return;
  }
  if (target.dataset.draftField && target.closest(".effect-draft-row")) {
    syncEffectDraftRow(target.closest(".effect-draft-row"), target.dataset.draftField);
    commitFocusedEdit(target);
    return;
  }
  if (target.dataset.draftField && target.closest(".condition-draft-row")) {
    syncConditionDraftRow(target.closest(".condition-draft-row"), target.dataset.draftField);
    commitFocusedEdit(target);
    return;
  }
  if (target.dataset.eventField) {
    setEventField(target.dataset.eventNodeId, target.dataset.eventField, target.value, true);
    commitFocusedEdit(target);
    return;
  }
  if (target.dataset.nodeCastField) {
    setNodeCastField(Number(target.dataset.nodeCastIndex), target.dataset.nodeCastField, target.value, true);
    commitFocusedEdit(target);
    return;
  }
  if (target.dataset.nodeConditionField) {
    setNodeConditionPart(target.dataset.nodeConditionField, target.value, Number(target.dataset.conditionIndex), true);
    commitFocusedEdit(target);
    return;
  }
  if (target.dataset.nodeLogicField) {
    setNodeLogicField(target.dataset.nodeLogicField, target.value, true);
    commitFocusedEdit(target);
    return;
  }
  if (target.dataset.nodeRoutingField) {
    setNodeRoutingField(target.dataset.nodeRoutingField, target.value, true);
    commitFocusedEdit(target);
    return;
  }
  if (target.dataset.nodeEffectField) {
    setNodeEffectField(Number(target.dataset.nodeEffectIndex), target.dataset.nodeEffectField, target.value, true);
    commitFocusedEdit(target);
    return;
  }
  if (target.dataset.choiceTimerField) {
    setChoiceTimerField(target.dataset.choiceTimerField, target.value, true);
    commitFocusedEdit(target);
    return;
  }
  if (target.dataset.choiceOptionField) {
    if (target.dataset.canvasChoiceOption) {
      setCanvasChoiceOptionLabel(target.dataset.choiceNodeId, target.dataset.choiceOptionId, Number(target.dataset.choiceOptionIndex), target.value, true);
      commitFocusedEdit(target);
      return;
    }
    setChoiceOptionField(target.dataset.choiceOptionId, target.dataset.choiceOptionField, target.value, true);
    updatePlaybookCodeStatusForControl(target);
    commitFocusedEdit(target);
    return;
  }
  if (target.dataset.choiceConditionField) {
    setChoiceOptionConditionPart(target.dataset.choiceOptionId, target.dataset.choiceConditionField, target.value, Number(target.dataset.conditionIndex), true);
    commitFocusedEdit(target);
    return;
  }
  if (target.dataset.choiceOptionEffectField) {
    const rerender = target.dataset.choiceOptionEffectField !== "op";
    setChoiceOptionEffectField(target.dataset.choiceOptionId, Number(target.dataset.choiceOptionEffectIndex), target.dataset.choiceOptionEffectField, target.value, rerender);
    commitFocusedEdit(target);
    return;
  }
  if (target.dataset.dialogTurnField) {
    if (target.dataset.canvasDialogTurn) {
      setCanvasDialogTurnField(target.dataset.dialogNodeId, Number(target.dataset.dialogTurnIndex), target.dataset.dialogTurnField, target.value, true);
      commitFocusedEdit(target);
      return;
    }
    setDialogTurnField(Number(target.dataset.dialogTurnIndex), target.dataset.dialogTurnField, target.value, true);
    commitFocusedEdit(target);
    return;
  }
  if (target.dataset.scriptConditionField) {
    setScriptNodeConditionPart(target.dataset.scriptNodeId, target.dataset.scriptConditionField, target.value, Number(target.dataset.conditionIndex), true);
    commitFocusedEdit(target);
    return;
  }
  if (target.dataset.scriptNodeField) {
    setScriptNodeField(target.dataset.scriptNodeId, target.dataset.scriptNodeField, target.value, true);
    updatePlaybookCodeStatusForControl(target);
    commitFocusedEdit(target);
    return;
  }
  if (target.dataset.gateField) {
    setGateField(target.dataset.gateId, target.dataset.gateField, target.value, true);
    updatePlaybookCodeStatusForControl(target);
    commitFocusedEdit(target);
    return;
  }
  if (target.dataset.gateConditionField) {
    setGateConditionPart(target.dataset.gateId, target.dataset.gateConditionField, target.value, Number(target.dataset.conditionIndex), true);
    commitFocusedEdit(target);
    return;
  }
  if (target.dataset.gateEffectField) {
    const rerender = target.dataset.gateEffectField !== "value";
    setChoiceOptionEffectByGateId(target.dataset.gateEffectId, Number(target.dataset.gateEffectIndex), target.dataset.gateEffectField, target.value, rerender);
    commitFocusedEdit(target);
    return;
  }
  if (target.dataset.runnerRuleField) {
    setRunnerRuleField(target.dataset.runnerRuleField, getRunnerRuleInputValue(target), true);
    commitFocusedEdit(target);
    return;
  }
  if (target.dataset.runnerRuleEnabled) {
    setRunnerRuleEnabled(target.dataset.runnerRuleEnabled, Boolean(target.checked), true);
    commitFocusedEdit(target);
    return;
  }
  if (target.dataset.nodeCustomField) {
    setNodeCustomField(target.dataset.nodeCustomField, target.value, true);
    commitFocusedEdit(target);
    return;
  }
  if (target.dataset.inlineNodeField) {
    setInlineNodeField(target.dataset.nodeId, target.dataset.inlineNodeField, target.value);
    commitFocusedEdit(target);
    finishNodeTitleReferenceEdit(target);
    return;
  }
  if (target.dataset.projectField) {
    if (target.dataset.projectField === "variables" && target.dataset.playbookJsonVersion !== String(state.dirtyVersion)) return;
    setProjectField(target.dataset.projectField, target.value);
    commitFocusedEdit(target);
    return;
  }
  if (target.dataset.nodeField) {
    setNodeField(target.dataset.nodeField, target.value);
    commitFocusedEdit(target);
    finishNodeTitleReferenceEdit(target);
  }
}

function syncNodeTypeEventSheetOption() {
  const isFrame = normalizeNodeTypeTemplate(dom.nodeTypeKindInput?.value) === "frame";
  const eventHiddenLabel = dom.nodeTypeEventHiddenInput?.closest("label");
  if (eventHiddenLabel) eventHiddenLabel.hidden = !isFrame;
  if (dom.nodeTypeOpacityField) dom.nodeTypeOpacityField.hidden = !isFrame;
}

function handleWorkspaceSearchKeyDown(event) {
  if (event.defaultPrevented || event.key !== "Enter") return;
  const target = event.target;
  if (!target) return;
  let scope = null;
  if (target === dom.queryInput) scope = "adventure";
  else if (target === dom.characterSearchInput) scope = "characters";
  else if (target === dom.eventSearchInput) scope = "events";
  else if (target === dom.playbookSearchInput) scope = "variables";
  else if (target === dom.documentSearchInput) scope = "document";
  if (!scope) return;
  event.preventDefault();
  cycleSearchScope(scope);
  if (typeof target.focus === "function") {
    try {
      target.focus({ preventScroll: true });
    } catch (_error) {
      target.focus();
    }
  }
}

function handleKeyDown(event) {
  if (event.defaultPrevented) return;
  if (handleHistoryShortcutEvent(event)) return;
  if (!isNarrativeCanvasTarget(event.target)) return;
  if (event.target.hasAttribute?.("data-ai-prompt") && event.key === "Enter" && !event.shiftKey) {
    if (event.isComposing || event.keyCode === 229) return;
    event.preventDefault();
    if (!state.aiBusy) void sendAiMessage();
    return;
  }
  if (handleVaultFileSuggestionKeyDown(event)) return;
  if (handleMentionKeyDown(event)) return;
  if (handleDocumentSourceKeyDown(event)) return;
  if (handleCodexTagKeyDown(event)) return;
  if (handleCastEntryPickerKeyDown(event)) return;
  if (event.target?.hasAttribute?.("data-codex-template-input") && event.key === "Enter") {
    event.preventDefault();
    addCodexTemplateField();
    return;
  }
  if (event.target?.dataset?.nodeCastDrag && (event.key === "ArrowUp" || event.key === "ArrowDown")) {
    const fromIndex = Number(event.target.dataset.nodeCastDrag);
    const direction = event.key === "ArrowUp" ? -1 : 1;
    const cast = normalizeNodeCast(getNode(state.selectedNodeId)?.cast);
    const targetIndex = fromIndex + direction;
    if (Number.isInteger(fromIndex) && targetIndex >= 0 && targetIndex < cast.length) {
      const historyBefore = getHistorySnapshot();
      if (moveNodeCastReference(fromIndex, targetIndex, direction < 0 ? "before" : "after")) {
        commitHistoryFromSnapshot(historyBefore);
        runAfterRender(() => dom.nodePanel?.querySelector(`[data-node-cast-drag="${targetIndex}"]`)?.focus?.({ preventScroll: true }));
      }
    }
    event.preventDefault();
    return;
  }
  if (event.target?.dataset?.codexVaultDrag != null && (event.key === "ArrowUp" || event.key === "ArrowDown")) {
    const fromIndex = Number(event.target.dataset.codexVaultDrag);
    const characterId = event.target.dataset.characterId;
    const direction = event.key === "ArrowUp" ? -1 : 1;
    const targetIndex = fromIndex + direction;
    const historyBefore = getHistorySnapshot();
    if (moveCodexVaultFileReference(characterId, fromIndex, targetIndex, direction < 0 ? "before" : "after")) {
      commitHistoryFromSnapshot(historyBefore);
      runAfterRender(() => dom.charactersPanel?.querySelector(`[data-codex-vault-drag="${targetIndex}"]`)?.focus?.({ preventScroll: true }));
    }
    event.preventDefault();
    return;
  }
  if (event.target?.dataset?.nodeVaultDrag && (event.key === "ArrowUp" || event.key === "ArrowDown")) {
    const fromIndex = Number(event.target.dataset.nodeVaultDrag);
    const direction = event.key === "ArrowUp" ? -1 : 1;
    const references = getNodeVaultFiles(getNode(state.selectedNodeId));
    const targetIndex = fromIndex + direction;
    if (Number.isInteger(fromIndex) && targetIndex >= 0 && targetIndex < references.length) {
      const historyBefore = getHistorySnapshot();
      if (moveNodeVaultFileReference(fromIndex, targetIndex, direction < 0 ? "before" : "after")) {
        commitHistoryFromSnapshot(historyBefore);
        runAfterRender(() => dom.nodePanel?.querySelector(`[data-node-vault-drag="${targetIndex}"]`)?.focus?.({ preventScroll: true }));
      }
    }
    event.preventDefault();
    return;
  }
  if (event.target.dataset?.canvasChoiceOption) {
    if (event.key === "Enter") {
      event.preventDefault();
      event.target.blur();
      return;
    }
    if (event.key === "Escape") {
      event.preventDefault();
      const original = event.target.dataset.choiceInitialValue || "";
      state.editHistoryTarget = null;
      setCanvasChoiceOptionLabel(event.target.dataset.choiceNodeId, event.target.dataset.choiceOptionId, Number(event.target.dataset.choiceOptionIndex), original, true);
      return;
    }
  }
  if (event.target.dataset?.canvasDialogTurn) {
    if (event.key === "Escape") {
      event.preventDefault();
      state.editHistoryTarget = null;
      setCanvasDialogTurnField(event.target.dataset.dialogNodeId, Number(event.target.dataset.dialogTurnIndex), event.target.dataset.dialogTurnField, event.target.dataset.dialogInitialValue || "", true);
      return;
    }
    if (event.key === "Enter" && (event.target.tagName === "INPUT" || event.ctrlKey || event.metaKey)) {
      event.preventDefault();
      event.target.blur();
    }
    return;
  }
  if (event.target.dataset?.inlineLinkLabel != null) {
    if (event.key === "Escape") {
      event.preventDefault();
      state.editHistoryTarget = null;
      setInlineLinkLabel(event.target.dataset.linkId, state.inlineEditLinkInitialValue);
      finishInlineLinkLabelEdit(event.target.dataset.linkId, { canceled: true });
      return;
    }
    if (event.key === "Enter") {
      event.preventDefault();
      event.target.blur();
    }
    return;
  }
  const isField = isNativeEditingTarget(event.target);
  if (isField && handleDialogTurnKeyDown(event)) return;
  if (event.target.dataset?.inlineNodeField && event.key === "Escape") {
    event.preventDefault();
    finishInlineNodeEdit(event.target.dataset.nodeId);
    return;
  }
  if (isField) return;
  if (event.key === "Delete" || event.key === "Backspace") {
    const historyBefore = getHistorySnapshot();
    if (state.selectedNodeIds.length > 1) deleteSelectedNodes();
    else if (state.selectedNodeId) deleteSelectedNode();
    if (state.selectedLinkId) deleteSelectedLink();
    commitHistoryFromSnapshot(historyBefore);
  }
}

const MENTION_SELECTOR = [
  "textarea[data-node-field]",
  "input[data-node-field='title']",
  "textarea[data-inline-node-field]",
  "input[data-inline-node-field='title']",
  "textarea[data-event-field]",
  "textarea[data-character-field]",
  "input[data-character-field='name']",
  "input[data-character-field='role']",
  "input[data-character-field='voice']",
  "textarea[data-node-custom-field]"
].join(",");

function isMentionField(target) {
  return target && target.matches && target.matches(MENTION_SELECTOR);
}

function updateMentionFromTarget(target) {
  if (!dom.mentionPopover || !isMentionField(target)) return;
  const value = target.value || "";
  const caret = typeof target.selectionStart === "number" ? target.selectionStart : value.length;
  const before = value.slice(0, caret);
  const match = before.match(/(^|[\s(\[{>,;:!?])@([\p{L}\p{N}_\-' .]{0,40})$/u);
  if (!match) {
    hideMentionPopover();
    return;
  }
  const query = match[2] || "";
  const atOffset = caret - query.length - 1;
  const entries = getCharacters();
  const needle = query.toLowerCase();
  const filtered = (query
    ? entries.filter((entry) => (entry.name || "").toLowerCase().includes(needle))
    : entries)
    .slice()
    .sort((a, b) => {
      const aName = String(a.name || "").toLowerCase();
      const bName = String(b.name || "").toLowerCase();
      const aPrefix = needle && aName.startsWith(needle) ? 0 : 1;
      const bPrefix = needle && bName.startsWith(needle) ? 0 : 1;
      return aPrefix - bPrefix
        || CODEX_KINDS.indexOf(a.kind) - CODEX_KINDS.indexOf(b.kind)
        || aName.localeCompare(bName);
    })
    .slice(0, 60);
  if (!filtered.length) {
    hideMentionPopover();
    return;
  }
  state.mention = {
    target,
    atOffset,
    queryLength: query.length,
    entries: filtered,
    activeIndex: 0
  };
  renderMentionPopover();
  positionMentionPopover(target);
}

function renderMentionPopover() {
  if (!dom.mentionPopover || !state.mention) return;
  const { entries, activeIndex } = state.mention;
  dom.mentionPopover.innerHTML = entries.map((entry, index) => `
    <button type="button" class="mention-option ${index === activeIndex ? "active" : ""}" data-mention-index="${index}" role="option">
      <span class="mention-option-main"><strong>${escapeHtml(entry.name || "Unnamed")}</strong>${entry.role ? `<small>${escapeHtml(entry.role)}</small>` : ""}</span>
      <span class="mention-option-kind" data-codex-kind="${escapeAttr(entry.kind)}">${escapeHtml(t(entry.kind))}</span>
    </button>
  `).join("");
  dom.mentionPopover.hidden = false;
  dom.mentionPopover.style.display = "grid";
  dom.mentionPopover.setAttribute("aria-hidden", "false");
}

function handleMentionPopoverPointerDown(event) {
  event.preventDefault();
}

function positionMentionPopover(target) {
  if (!dom.mentionPopover) return;
  const rect = target.getBoundingClientRect();
  const margin = 8;
  const gap = 4;
  const maxWidth = Math.max(180, Math.min(320, window.innerWidth - margin * 2));
  const width = Math.min(Math.max(rect.width, 180), maxWidth);
  const spaceBelow = window.innerHeight - rect.bottom - margin;
  const spaceAbove = rect.top - margin;
  const openBelow = spaceBelow >= 120 || spaceBelow >= spaceAbove;
  const availableHeight = Math.max(96, (openBelow ? spaceBelow : spaceAbove) - gap);
  const maxHeight = Math.min(260, availableHeight);
  const left = clamp(rect.left, margin, Math.max(margin, window.innerWidth - width - margin));
  const top = openBelow
    ? Math.min(rect.bottom + gap, window.innerHeight - margin - maxHeight)
    : Math.max(margin, rect.top - gap - maxHeight);
  dom.mentionPopover.style.left = `${left}px`;
  dom.mentionPopover.style.top = `${top}px`;
  dom.mentionPopover.style.minWidth = `${width}px`;
  dom.mentionPopover.style.maxWidth = `${maxWidth}px`;
  dom.mentionPopover.style.maxHeight = `${maxHeight}px`;
}

function hideMentionPopover() {
  if (!dom.mentionPopover) return;
  state.mention = null;
  dom.mentionPopover.hidden = true;
  dom.mentionPopover.style.display = "none";
  dom.mentionPopover.setAttribute("aria-hidden", "true");
  dom.mentionPopover.innerHTML = "";
}

function handleMentionKeyDown(event) {
  if (!state.mention) return false;
  if (event.target !== state.mention.target) {
    hideMentionPopover();
    return false;
  }
  if (event.key === "Escape") {
    hideMentionPopover();
    event.preventDefault();
    return true;
  }
  if (event.key === "ArrowDown" || event.key === "ArrowUp") {
    const dir = event.key === "ArrowDown" ? 1 : -1;
    const length = state.mention.entries.length;
    state.mention.activeIndex = (state.mention.activeIndex + dir + length) % length;
    renderMentionPopover();
    event.preventDefault();
    return true;
  }
  if (event.key === "Enter" || event.key === "Tab") {
    const entry = state.mention.entries[state.mention.activeIndex];
    if (entry) {
      insertMention(entry);
      event.preventDefault();
      return true;
    }
  }
  return false;
}

function insertMention(entry) {
  if (!state.mention) return;
  const { target, atOffset, queryLength } = state.mention;
  const value = target.value || "";
  const before = value.slice(0, atOffset);
  const after = value.slice(atOffset + 1 + queryLength);
  const insertion = `@${entry.name || ""}`;
  target.value = `${before}${insertion} ${after}`;
  const caret = (before + insertion + " ").length;
  if (typeof target.setSelectionRange === "function") target.setSelectionRange(caret, caret);
  target.focus();
  hideMentionPopover();
  target.dispatchEvent(new Event("input", { bubbles: true }));
  target.dispatchEvent(new Event("change", { bubbles: true }));
  hideMentionPopover();

  if (target.dataset.nodeField || target.dataset.inlineNodeField || target.dataset.nodeCustomField || target.dataset.eventField) {
    const node = getNode(target.dataset.nodeId || state.selectedNodeId);
    if (node && !isEventSheetNode(node)) {
      const cast = normalizeNodeCast(node.cast);
      if (!cast.some((link) => link.characterId === entry.id && link.role === "Mentioned")) {
        cast.push({ characterId: entry.id, role: "Mentioned" });
        node.cast = cast;
        if (target.dataset.inlineNodeField) {
          invalidateCharacterRenderContext();
          setProjectDirty(true);
          renderNodePanel(node);
          renderProjectPanel();
          scheduleStoryPanelRender();
          updateStatus();
        } else {
          renderCharacterAwareSurfaces(node);
        }
      }
    }
  }
}

function handleStoryPointerDown(event) {
  const castDragHandle = event.target.closest && event.target.closest("[data-node-cast-drag]");
  if (castDragHandle && dom.nodePanel?.contains(castDragHandle)) {
    const index = Number(castDragHandle.dataset.nodeCastDrag);
    const node = getNode(state.selectedNodeId);
    if (!node || !Number.isInteger(index) || !normalizeNodeCast(node.cast)[index]) return;
    state.nodeCastDrag = {
      nodeId: node.id,
      fromIndex: index,
      startX: event.clientX,
      startY: event.clientY,
      active: false,
      historyBefore: getHistorySnapshot()
    };
    event.preventDefault();
    return;
  }
  const codexVaultHandle = event.target.closest && event.target.closest("[data-codex-vault-drag]");
  if (codexVaultHandle && dom.charactersPanel?.contains(codexVaultHandle)) {
    const index = Number(codexVaultHandle.dataset.codexVaultDrag);
    const characterId = codexVaultHandle.dataset.characterId;
    if (!getCharacterById(characterId) || !Number.isInteger(index)) return;
    state.codexVaultFileDrag = {
      characterId,
      fromIndex: index,
      startX: event.clientX,
      startY: event.clientY,
      active: false,
      historyBefore: getHistorySnapshot()
    };
    event.preventDefault();
    return;
  }
  const vaultDragHandle = event.target.closest && event.target.closest("[data-node-vault-drag]");
  if (vaultDragHandle && dom.nodePanel?.contains(vaultDragHandle)) {
    const index = Number(vaultDragHandle.dataset.nodeVaultDrag);
    const node = getNode(state.selectedNodeId);
    if (!node || !Number.isInteger(index) || !getNodeVaultFiles(node)[index]) return;
    state.nodeVaultFileDrag = {
      nodeId: node.id,
      fromIndex: index,
      startX: event.clientX,
      startY: event.clientY,
      active: false,
      historyBefore: getHistorySnapshot()
    };
    event.preventDefault();
    return;
  }
  const columnResizeHandle = event.target.closest && event.target.closest("[data-event-column-resize]");
  if (columnResizeHandle && dom.eventsPanel?.contains(columnResizeHandle)) {
    const key = columnResizeHandle.dataset.eventColumnResize;
    const column = getEventColumnByKey(key);
    if (!column) return;
    const th = columnResizeHandle.closest("th");
    const startWidth = th ? th.getBoundingClientRect().width : parseFloat(normalizeEventColumnWidth(column.width));
    state.eventColumnResize = {
      key,
      startX: event.clientX,
      startWidth: Math.max(60, startWidth),
      lastWidth: Math.max(60, startWidth),
      active: false
    };
    dom.root?.classList.add("event-column-resizing");
    event.preventDefault();
    return;
  }
  const eventRowHandle = event.target.closest && event.target.closest("[data-event-row-drag]");
  if (eventRowHandle && dom.eventsPanel?.contains(eventRowHandle)) {
    const nodeId = eventRowHandle.dataset.eventRowDrag;
    if (!getNode(nodeId)) return;
    state.eventRowDrag = {
      id: nodeId,
      startX: event.clientX,
      startY: event.clientY,
      active: false
    };
    event.preventDefault();
    return;
  }
  if (!dom.storyPanel?.contains(event.target)) return;
  if (event.button !== undefined && event.button !== 0) return;
  if (event.target.closest("button, a, input, select, textarea")) return;
  const item = event.target.closest("[data-story-node-id]");
  if (!item) return;
  const nodeId = item.dataset.storyNodeId;
  if (!getNode(nodeId)) return;
  state.draggingStoryNodeId = nodeId;
  state.storyPointerDrag = {
    id: nodeId,
    startX: event.clientX,
    startY: event.clientY,
    active: false
  };
  item.classList.add("dragging");
  event.preventDefault();
}

function handleEventColumnResizeMove(event) {
  if (!state.eventColumnResize) return;
  const drag = state.eventColumnResize;
  const delta = event.clientX - drag.startX;
  if (Math.abs(delta) < 3 && !drag.active) return;
  drag.active = true;
  const nextWidth = Math.max(60, Math.round(drag.startWidth + delta));
  drag.lastWidth = nextWidth;
  applyEventColumnWidthToDom(drag.key, nextWidth);
  event.preventDefault();
}

function handleEventColumnResizeUp(event) {
  if (!state.eventColumnResize) return;
  const drag = state.eventColumnResize;
  state.eventColumnResize = null;
  dom.root?.classList.remove("event-column-resizing");
  if (!drag.active) return;
  const historyBefore = getHistorySnapshot();
  setEventColumnWidth(drag.key, `${drag.lastWidth}px`);
  commitHistoryFromSnapshot(historyBefore);
}

function applyEventColumnWidthToDom(key, width) {
  const widthStr = `${width}px`;
  const cellStyle = `width:${widthStr}; min-width:${widthStr};`;
  const safeKey = CSS.escape(key);
  dom.eventsPanel?.querySelectorAll(`[data-event-column-key="${safeKey}"]`).forEach((th) => {
    th.style.cssText = cellStyle;
    const table = th.closest("table");
    const colIndex = th.cellIndex;
    const col = table?.querySelector("colgroup")?.children?.[colIndex];
    if (col) col.style.width = widthStr;
  });
  dom.eventsPanel?.querySelectorAll(`[data-event-field="${safeKey}"]`).forEach((control) => {
    const td = control.closest("td");
    if (td) td.style.cssText = cellStyle;
  });
}

function setEventColumnWidth(key, width) {
  const normalized = normalizeEventColumnWidth(width);
  const sheet = getProjectEventSheet();
  let schemaColumn = sheet.columns.find((item) => item.key === key);
  if (!schemaColumn) {
    const defaultColumn = eventSheetColumns.find((item) => item.key === key);
    if (defaultColumn) {
      schemaColumn = normalizeEventSheetColumn(defaultColumn);
      sheet.columns.push(schemaColumn);
    }
  }
  if (!schemaColumn || schemaColumn.width === normalized) return;
  const scrollState = captureEventSheetScrollState();
  schemaColumn.width = normalized;
  state.project.eventSheet = sheet;
  markProjectStructureChanged();
  setProjectDirty(true);
  renderEventsSheetPage();
  restoreEventSheetScrollState(scrollState);
}

function handleEventRowPointerMove(event) {
  if (!state.eventRowDrag) return;
  const drag = state.eventRowDrag;
  const distance = Math.hypot(event.clientX - drag.startX, event.clientY - drag.startY);
  if (distance < 6 && !drag.active) return;
  drag.active = true;
  const placement = getEventRowDropPlacementFromPoint(event.clientX, event.clientY, drag.id);
  clearEventRowDropMarkers();
  if (placement) markEventRowDropPlacement(placement);
  event.preventDefault();
}

function handleEventRowPointerUp(event) {
  if (!state.eventRowDrag) return;
  const drag = state.eventRowDrag;
  const placement = drag.active ? getEventRowDropPlacementFromPoint(event.clientX, event.clientY, drag.id) : null;
  clearEventRowDropMarkers();
  state.eventRowDrag = null;
  if (placement && placement.targetId !== drag.id) {
    moveEventRow(drag.id, placement.targetId, placement.placement);
  }
}

function getEventRowDropPlacementFromPoint(x, y, draggingId) {
  const root = typeof dom.scope?.elementFromPoint === "function" ? dom.scope : document;
  const el = root.elementFromPoint(x, y);
  if (!el) return null;
  const row = el.closest("[data-event-row-id]");
  if (!row || !dom.eventsPanel?.contains(row)) return null;
  const targetId = row.dataset.eventRowId;
  if (!targetId || targetId === draggingId) return null;
  const draggingNode = getNode(draggingId);
  const targetNode = getNode(targetId);
  if (!draggingNode || !targetNode || draggingNode.type !== targetNode.type) return null;
  const rect = row.getBoundingClientRect();
  const placement = (y - rect.top) > rect.height / 2 ? "after" : "before";
  return { targetId, placement };
}

function clearEventRowDropMarkers() {
  dom.eventsPanel?.querySelectorAll(".event-row-drop-before, .event-row-drop-after")
    .forEach((row) => row.classList.remove("event-row-drop-before", "event-row-drop-after"));
}

function markEventRowDropPlacement(placement) {
  const row = dom.eventsPanel?.querySelector(`[data-event-row-id="${placement.targetId}"]`);
  if (row) row.classList.add(placement.placement === "after" ? "event-row-drop-after" : "event-row-drop-before");
}

function handleStoryPointerMove(event) {
  if (state.nodeCastDrag) {
    handleNodeCastPointerMove(event);
    return;
  }
  if (state.nodeVaultFileDrag) {
    handleNodeVaultFilePointerMove(event);
    return;
  }
  if (state.codexVaultFileDrag) {
    handleCodexVaultFilePointerMove(event);
    return;
  }
  if (state.eventColumnResize) {
    handleEventColumnResizeMove(event);
    return;
  }
  if (state.eventRowDrag) {
    handleEventRowPointerMove(event);
    return;
  }
  if (!state.storyPointerDrag) return;
  const drag = state.storyPointerDrag;
  const distance = Math.hypot(event.clientX - drag.startX, event.clientY - drag.startY);
  if (distance < 6 && !drag.active) return;
  drag.active = true;
  const placement = getStoryDropPlacementFromPoint(event.clientX, event.clientY);
  clearStoryDropMarkers(false);
  if (placement && canMoveStoryNode(drag.id, placement)) markStoryDropPlacement(placement);
  event.preventDefault();
}

function handleStoryPointerUp(event) {
  if (state.nodeCastDrag) {
    handleNodeCastPointerUp(event);
    return;
  }
  if (state.nodeVaultFileDrag) {
    handleNodeVaultFilePointerUp(event);
    return;
  }
  if (state.codexVaultFileDrag) {
    handleCodexVaultFilePointerUp(event);
    return;
  }
  if (state.eventColumnResize) {
    handleEventColumnResizeUp(event);
    return;
  }
  if (state.eventRowDrag) {
    handleEventRowPointerUp(event);
    return;
  }
  if (!state.storyPointerDrag) return;
  const drag = state.storyPointerDrag;
  const placement = drag.active ? getStoryDropPlacementFromPoint(event.clientX, event.clientY) : null;
  state.draggingStoryNodeId = null;
  state.storyPointerDrag = null;
  clearStoryDropMarkers();
  if (placement && canMoveStoryNode(drag.id, placement)) {
    moveStoryNode(drag.id, placement);
  }
}

function handleNodeCastPointerMove(event) {
  const drag = state.nodeCastDrag;
  if (!drag) return;
  const distance = Math.hypot(event.clientX - drag.startX, event.clientY - drag.startY);
  if (distance < 5 && !drag.active) return;
  drag.active = true;
  const placement = getNodeCastDropPlacement(event.clientX, event.clientY, drag.fromIndex);
  clearNodeCastDropMarkers();
  if (placement) {
    const row = dom.nodePanel?.querySelector(`[data-node-cast-row-index="${placement.targetIndex}"]`);
    row?.classList.add(placement.placement === "after" ? "cast-row-drop-after" : "cast-row-drop-before");
  }
  event.preventDefault();
}

function handleNodeCastPointerUp(event) {
  const drag = state.nodeCastDrag;
  if (!drag) return;
  const placement = drag.active && event.type !== "pointercancel"
    ? getNodeCastDropPlacement(event.clientX, event.clientY, drag.fromIndex)
    : null;
  state.nodeCastDrag = null;
  clearNodeCastDropMarkers();
  if (!placement || drag.nodeId !== state.selectedNodeId) return;
  if (moveNodeCastReference(drag.fromIndex, placement.targetIndex, placement.placement)) {
    commitHistoryFromSnapshot(drag.historyBefore);
  }
}

function handleNodeVaultFilePointerMove(event) {
  const drag = state.nodeVaultFileDrag;
  if (!drag) return;
  const distance = Math.hypot(event.clientX - drag.startX, event.clientY - drag.startY);
  if (distance < 5 && !drag.active) return;
  drag.active = true;
  const placement = getNodeVaultFileDropPlacement(event.clientX, event.clientY, drag.fromIndex, event.target);
  clearNodeVaultFileDropMarkers();
  if (placement) {
    const row = dom.nodePanel?.querySelector(`[data-node-vault-row-index="${placement.targetIndex}"]`);
    row?.classList.add(placement.placement === "after" ? "cast-row-drop-after" : "cast-row-drop-before");
  }
  event.preventDefault();
}

function handleNodeVaultFilePointerUp(event) {
  const drag = state.nodeVaultFileDrag;
  if (!drag) return;
  const placement = drag.active && event.type !== "pointercancel"
    ? getNodeVaultFileDropPlacement(event.clientX, event.clientY, drag.fromIndex, event.target)
    : null;
  state.nodeVaultFileDrag = null;
  clearNodeVaultFileDropMarkers();
  if (!placement || drag.nodeId !== state.selectedNodeId) return;
  if (moveNodeVaultFileReference(drag.fromIndex, placement.targetIndex, placement.placement)) {
    commitHistoryFromSnapshot(drag.historyBefore);
  }
}

function handleCodexVaultFilePointerMove(event) {
  const drag = state.codexVaultFileDrag;
  if (!drag) return;
  const distance = Math.hypot(event.clientX - drag.startX, event.clientY - drag.startY);
  if (distance < 5 && !drag.active) return;
  drag.active = true;
  const placement = getCodexVaultFileDropPlacement(event.clientX, event.clientY, drag.fromIndex);
  clearCodexVaultFileDropMarkers();
  if (placement) {
    const row = dom.charactersPanel?.querySelector(`[data-codex-vault-row-index="${placement.targetIndex}"]`);
    row?.classList.add(placement.placement === "after" ? "cast-row-drop-after" : "cast-row-drop-before");
  }
  event.preventDefault();
}

function handleCodexVaultFilePointerUp(event) {
  const drag = state.codexVaultFileDrag;
  if (!drag) return;
  const placement = drag.active && event.type !== "pointercancel"
    ? getCodexVaultFileDropPlacement(event.clientX, event.clientY, drag.fromIndex)
    : null;
  state.codexVaultFileDrag = null;
  clearCodexVaultFileDropMarkers();
  if (!placement) return;
  if (moveCodexVaultFileReference(drag.characterId, drag.fromIndex, placement.targetIndex, placement.placement)) {
    commitHistoryFromSnapshot(drag.historyBefore);
  }
}

function getCodexVaultFileDropPlacement(x, y, fromIndex) {
  const root = typeof dom.scope?.elementFromPoint === "function" ? dom.scope : document;
  const target = root.elementFromPoint(x, y);
  const row = target?.closest?.("[data-codex-vault-row-index]");
  if (!row || !dom.charactersPanel?.contains(row)) return null;
  const targetIndex = Number(row.dataset.codexVaultRowIndex);
  if (!Number.isInteger(targetIndex) || targetIndex === fromIndex) return null;
  const rect = row.getBoundingClientRect();
  const placement = y - rect.top > rect.height / 2 ? "after" : "before";
  return { targetIndex, placement };
}

function clearCodexVaultFileDropMarkers() {
  dom.charactersPanel?.querySelectorAll("[data-codex-vault-row-index].cast-row-drop-before, [data-codex-vault-row-index].cast-row-drop-after")
    .forEach((row) => row.classList.remove("cast-row-drop-before", "cast-row-drop-after"));
}

function moveCodexVaultFileReference(characterId, fromIndex, targetIndex, placement = "before") {
  const character = getCharacterById(characterId);
  if (!character || !Number.isInteger(fromIndex) || !Number.isInteger(targetIndex)) return false;
  const files = normalizeCodexVaultFiles(character.vaultFiles);
  if (fromIndex < 0 || fromIndex >= files.length || targetIndex < 0 || targetIndex >= files.length || fromIndex === targetIndex) return false;
  const insertionBeforeRemoval = targetIndex + (placement === "after" ? 1 : 0);
  const [entry] = files.splice(fromIndex, 1);
  const insertionIndex = clamp(insertionBeforeRemoval - (fromIndex < insertionBeforeRemoval ? 1 : 0), 0, files.length);
  if (insertionIndex === fromIndex) {
    files.splice(fromIndex, 0, entry);
    return false;
  }
  files.splice(insertionIndex, 0, entry);
  character.vaultFiles = files;
  invalidateCharacterRenderContext();
  setProjectDirty(true);
  renderWorkspaceFile();
  setStatus(t("Linked files reordered."));
  return true;
}

function getNodeVaultFileDropPlacement(x, y, fromIndex, eventTarget = null) {
  let row = eventTarget?.closest?.("[data-node-vault-row-index]") || null;
  if (!row || !dom.nodePanel?.contains(row)) {
    const root = typeof dom.scope?.elementFromPoint === "function" ? dom.scope : document;
    const target = root.elementFromPoint(x, y);
    row = target?.closest?.("[data-node-vault-row-index]") || null;
  }
  if (!row || !dom.nodePanel?.contains(row)) return null;
  const targetIndex = Number(row.dataset.nodeVaultRowIndex);
  if (!Number.isInteger(targetIndex)) return null;
  if (targetIndex === fromIndex) return null;
  const rect = row.getBoundingClientRect();
  const placement = y - rect.top > rect.height / 2 ? "after" : "before";
  return { targetIndex, placement };
}

function clearNodeVaultFileDropMarkers() {
  dom.nodePanel?.querySelectorAll("[data-node-vault-row-index].cast-row-drop-before, [data-node-vault-row-index].cast-row-drop-after")
    .forEach((row) => row.classList.remove("cast-row-drop-before", "cast-row-drop-after"));
}

function getNodeCastDropPlacement(x, y, fromIndex) {
  const root = typeof dom.scope?.elementFromPoint === "function" ? dom.scope : document;
  const target = root.elementFromPoint(x, y);
  const row = target?.closest?.("[data-node-cast-row-index]");
  if (!row || !dom.nodePanel?.contains(row)) return null;
  const targetIndex = Number(row.dataset.nodeCastRowIndex);
  if (!Number.isInteger(targetIndex)) return null;
  if (targetIndex === fromIndex) return null;
  const rect = row.getBoundingClientRect();
  const placement = y - rect.top > rect.height / 2 ? "after" : "before";
  return { targetIndex, placement };
}

function clearNodeCastDropMarkers() {
  dom.nodePanel?.querySelectorAll(".cast-row-drop-before, .cast-row-drop-after")
    .forEach((row) => row.classList.remove("cast-row-drop-before", "cast-row-drop-after"));
}

function getStoryDropPlacementFromPoint(x, y) {
  const root = typeof dom.scope?.elementFromPoint === "function" ? dom.scope : document;
  const target = root.elementFromPoint(x, y);
  if (!target) return null;
  return getStoryDropPlacement({ target, clientY: y });
}

function getStoryDropPlacement(event) {
  const item = event.target.closest("[data-story-node-id]");
  if (item && dom.storyPanel?.contains(item)) {
    const targetId = item.dataset.storyNodeId;
    const targetNode = getNode(targetId);
    const rect = item.getBoundingClientRect();
    const relativeY = rect.height ? (event.clientY - rect.top) / rect.height : 0.5;
    if (targetNode && isFrameNode(targetNode) && relativeY > 0.25 && relativeY < 0.75) {
      return { mode: "inside", parentId: targetId, targetId };
    }
    return {
      mode: relativeY < 0.5 ? "before" : "after",
      parentId: item.dataset.storyParentId || "",
      targetId
    };
  }

  const list = event.target.closest("[data-story-parent-id]");
  if (list && dom.storyPanel?.contains(list)) {
    return { mode: "append", parentId: list.dataset.storyParentId || "", targetId: "" };
  }
  return null;
}

function canMoveStoryNode(nodeId, placement) {
  const node = getNode(nodeId);
  if (!node || !placement) return false;
  if (placement.targetId === nodeId || placement.parentId === nodeId) return false;
  const parent = placement.parentId ? getNode(placement.parentId) : null;
  if (placement.parentId && !isFrameNode(parent)) return false;
  if (isFrameNode(node) && placement.parentId && isStoryFrameDescendant(placement.parentId, nodeId)) return false;
  return true;
}

function isStoryFrameDescendant(frameId, ancestorId) {
  const parentMap = getStoryParentMap();
  let current = frameId;
  while (current) {
    if (current === ancestorId) return true;
    current = parentMap.get(current) || "";
  }
  return false;
}

function clearStoryDropMarkers(removeDragging = true) {
  dom.storyPanel?.querySelectorAll(".story-drop-before, .story-drop-after, .story-drop-inside")
    .forEach((item) => item.classList.remove("story-drop-before", "story-drop-after", "story-drop-inside"));
  if (removeDragging) {
    dom.storyPanel?.querySelectorAll(".dragging").forEach((item) => item.classList.remove("dragging"));
  }
}

function markStoryDropPlacement(placement) {
  if (placement.mode === "append" || placement.mode === "inside") {
    const target = placement.mode === "inside"
      ? dom.storyPanel?.querySelector(`[data-story-node-id="${placement.parentId}"]`)
      : dom.storyPanel?.querySelector(`[data-story-parent-id="${placement.parentId}"]`);
    target?.classList.add("story-drop-inside");
    return;
  }
  const target = dom.storyPanel?.querySelector(`[data-story-node-id="${placement.targetId}"]`);
  target?.classList.add(placement.mode === "before" ? "story-drop-before" : "story-drop-after");
}

function isNarrativeCanvasTarget(target) {
  return Boolean(
    dom.root?.contains(target)
    || dom.mentionPopover?.contains(target)
    || dom.nodeContextMenu?.contains(target)
    || dom.nodeTypeDialog?.contains(target)
    || dom.playDialog?.contains(target)
    || dom.exportReportDialog?.contains(target)
    || dom.confirmDialog?.contains(target)
    || dom.eventColumnDeleteDialog?.contains(target)
    || dom.eventColumnsResetDialog?.contains(target)
    || dom.genericConfirmDialog?.contains(target)
    || dom.genericTextDialog?.contains(target)
    || dom.expandEditorDialog?.contains(target)
    || dom.playbookHelpDialog?.contains(target)
    || dom.playRuleDialog?.contains(target)
    || dom.nodeRequiredDialog?.contains(target)
    || dom.visionBoardDialog?.contains(target)
    || dom.aiFloatingWindow?.contains(target)
  );
}

function isNarrativeCanvasClickDelegateTarget(target) {
  if (!target?.closest) return false;
  const actionable = target.closest("[data-mention-index], [data-layer-action], [data-sidebar-toggle], [data-action], [data-file-id], [data-panel], [data-port], [data-link-id], [data-node-id], .node[data-node-id], .node-stack[data-node-stack-id]");
  return Boolean(actionable && getNarrativeCanvasScopeForTarget(target));
}

function getCanvasClickEventTarget(event) {
  const directTarget = getComposedEventTarget(event) || event?.target;
  const directLink = directTarget?.closest?.("[data-link-id]");
  if (directLink && dom.linkLayer?.contains(directLink)) return directTarget;
  return getCanvasCoveredFrameTarget(event) || directTarget;
}

function getCanvasCoveredFrameTarget(event) {
  if (!event || !dom.linkLayer?.contains(event.target) || typeof document.elementsFromPoint !== "function") return null;
  const stack = document.elementsFromPoint(event.clientX, event.clientY);
  return stack.find((element) => {
    if (!dom.frameLayer?.contains(element)) return false;
    return Boolean(element.closest?.("[data-action], [data-drag-handle], [data-resize-handle], [data-port], .node[data-node-id], .node-stack[data-node-stack-id]"));
  }) || null;
}

function getCanvasCoveredHeaderTarget(event) {
  if (!event || !dom.linkLayer?.contains(event.target) || typeof document.elementsFromPoint !== "function") return null;
  const stack = document.elementsFromPoint(event.clientX, event.clientY);
  const stackedHeader = stack.find((element) => {
    if (!dom.frameLayer?.contains(element) && !dom.nodeLayer?.contains(element)) return false;
    return Boolean(element.closest?.(".node-header"));
  });
  if (stackedHeader) return stackedHeader;
  const headers = [
    ...(dom.nodeLayer?.querySelectorAll(".node-header") || []),
    ...(dom.frameLayer?.querySelectorAll(".node-header") || [])
  ];
  return headers.reverse().find((header) => {
    const rect = header.getBoundingClientRect();
    return event.clientX >= rect.left && event.clientX <= rect.right && event.clientY >= rect.top && event.clientY <= rect.bottom;
  }) || null;
}

function isPointerOverNodeHeaderRegion(node, clientX, clientY) {
  if (!node || typeof document.elementsFromPoint !== "function") return false;
  // The input port overlaps the header's top border, so the pointer target is the port, not the
  // header. Look through the whole stack at this point for the header that belongs to this node.
  return document.elementsFromPoint(clientX, clientY).some((element) => {
    const header = element.closest?.(".node-header[data-node-id]");
    return Boolean(header) && header.dataset.nodeId === node.id;
  });
}

function getCanvasNodeIdFromTargetForClick(target, event = null) {
  const directNodeId = target?.closest?.("[data-node-id]")?.dataset?.nodeId;
  if (directNodeId && getNode(directNodeId)) return directNodeId;

  const directStackId = target?.closest?.(".node-stack[data-node-stack-id]")?.dataset?.nodeStackId;
  if (directStackId && getNode(directStackId)) return directStackId;

  if (!event || typeof event.clientX !== "number" || typeof document.elementsFromPoint !== "function") return null;
  const stack = document.elementsFromPoint(event.clientX, event.clientY);
  const found = stack.find((element) => {
    const stackTarget = element?.closest?.(".node-stack[data-node-stack-id]");
    if (!stackTarget) return false;
    const candidateNodeId = stackTarget.dataset?.nodeStackId;
    return Boolean(candidateNodeId && getNode(candidateNodeId));
  });
  return found?.closest?.(".node-stack[data-node-stack-id]")?.dataset?.nodeStackId || null;
}

function getNarrativeCanvasScopeForTarget(target) {
  if (!target?.closest) return null;
  // Shadow mount: the app tree lives inside a shadow root on the plugin host element.
  const rootNode = target.getRootNode?.();
  if (typeof ShadowRoot === "function" && rootNode instanceof ShadowRoot
    && rootNode.host?.classList?.contains("narrative-canvas-plugin-host")
    && rootNode.querySelector?.(".app-shell")) {
    return rootNode;
  }
  const host = target.closest(".narrative-canvas-plugin-host");
  if (host?.querySelector?.(".app-shell")) return host;
  if (dom.root?.contains(target)) return dom.scope || document;
  const shell = target.closest(".app-shell");
  if (shell) return shell.closest(".narrative-canvas-plugin-host") || document;
  return null;
}

function syncDomScopeForEventTarget(target) {
  const nextScope = getNarrativeCanvasScopeForTarget(target);
  if (!nextScope || nextScope === dom.scope) return;
  eventController?.abort();
  const scopeHostElement = typeof ShadowRoot === "function" && nextScope instanceof ShadowRoot ? nextScope.host : nextScope;
  if (window.NarrativeCanvasHost && scopeHostElement?.classList?.contains("narrative-canvas-plugin-host")) {
    window.NarrativeCanvasHost.root = nextScope;
  }
  bindDom(nextScope);
  bindEvents();
}

function handleViewportPointerDown(event) {
  const target = getCanvasCoveredFrameTarget(event) || event.target;
  rememberInlineEditPointerTarget(target);
  if (shouldKeepInlineNodeEditForTarget(target)) {
    event.preventDefault();
    requestAnimationFrame(() => focusInlineNodeEditor(state.inlineEditNodeId));
    return;
  }
  if (state.inlineEditNodeId && !isActiveInlineEditNodeTarget(target)) {
    finishInlineNodeEdit(state.inlineEditNodeId);
  }

  const portHandle = target.closest("[data-port][data-node-id]");
  if (portHandle && event.button === 0) {
    const node = getNode(portHandle.dataset.nodeId);
    if (!node) return;
    // Always start each port interaction with a clean slate; a stale flag from a previous
    // jittered click would otherwise eat the click event that follows pointerup.
    state.suppressPortClick = false;
    state.draggingPort = {
      nodeId: node.id,
      kind: portHandle.dataset.port,
      startX: event.clientX,
      startY: event.clientY,
      active: false,
      pointerId: event.pointerId,
      historyBefore: getHistorySnapshot(),
      linkRefs: collectLinkElementRefs(getPortDragLinks(node))
    };
    // Do NOT capture the pointer yet — capturing on viewport redirects pointer events away
    // from the port button and can also blackhole the implicit click event. We only need
    // capture once an actual drag starts (see handleViewportPointerMove).
    return;
  }

  if (target.closest("[data-no-drag]")) return;

  const resizeHandle = target.closest("[data-resize-handle]");
  if (resizeHandle && event.button === 0) {
    const node = getNode(resizeHandle.dataset.nodeId);
    if (!node) return;
    const size = nodeSize(node);
    beginGeometryHistoryCapture(withFrameCanvasHistoryFrames([node]));
    if (!isFrameNode(node)) {
      selectNode(node.id, false);
    }
    // Cache the element + incident link elements AFTER selectNode re-rendered, so
    // the move handler can patch them in place without re-querying or re-rendering.
    state.resizingNode = {
      id: node.id,
      handle: resizeHandle.dataset.resizeHandle,
      startX: event.clientX,
      startY: event.clientY,
      didMove: false,
      width: size.width,
      height: size.height,
      element: getNodeElementById(node.id),
      ports: getNodePortElementsById(node.id),
      linkRefs: collectLinkElementRefs(getIncidentLinks(node.id)),
      frameContainmentBeforeFrameId: isFrameNode(node) ? node.id : null,
      frameContainmentBefore: isFrameNode(node) ? getFrameVisualContainedNodeIds(node) : null
    };
    safeSetPointerCapture(dom.viewport, event.pointerId);
    event.preventDefault();
    return;
  }

  const handle = target.closest("[data-drag-handle]");
  if (handle && event.button === 0) {
    const node = getNode(handle.dataset.nodeId);
    if (!node) return;
    const selected = collectSelectedIds();
    const baseNodeIds = selected.includes(node.id) && selected.length > 1 ? selected : [node.id];
    const dragNodeIds = getDragNodeIdsForDrag(node);
    const dragNodes = dragNodeIds.map(getNode).filter(Boolean);
    beginGeometryHistoryCapture(withFrameCanvasHistoryFrames(dragNodes));
    if (isFrameNode(node) || !selected.includes(node.id)) {
      selectNode(node.id, false);
      // selectNode(…, false) skips rendering so a drag-start doesn't pay for a full canvas render,
      // but a plain click must still focus the Node tab. A frame's body is click-through, so its
      // header (this drag handle) is the only way to pick it, and the later click gets swallowed by
      // ignoreNextCanvasClick — refresh just the inspector here so the Node tab activates on the
      // press, deterministically, regardless of whether this becomes a drag or a click.
      if (state.selectedNodeId === node.id && state.panel === "node") renderInspector();
    }
    state.draggingNode = {
      id: node.id,
      baseNodeIds,
      nodeIds: dragNodeIds,
      nodePositions: dragNodes.map((item) => ({ id: item.id, x: item.x, y: item.y })),
      startX: event.clientX,
      startY: event.clientY,
      didMove: false,
      nodeX: node.x,
      nodeY: node.y,
      element: dragNodeIds.length === 1 ? getNodeElementById(node.id) : null,
      ports: dragNodeIds.length === 1 ? getNodePortElementsById(node.id) : null,
      linkRefs: collectLinkElementRefs(getIncidentLinksForNodes(dragNodeIds)),
      frameContainmentBeforeFrameId: baseNodeIds.length === 1 && isFrameNode(node) ? node.id : null,
      frameContainmentBefore: baseNodeIds.length === 1 && isFrameNode(node) ? getFrameVisualContainedNodeIds(node) : null
    };
    safeSetPointerCapture(dom.viewport, event.pointerId);
    return;
  }

  if (target === dom.viewport || target === dom.content || target === dom.frameLayer || target === dom.nodeLayer || target === dom.linkLayer) {
    if (state.connectingFrom || state.reconnectingLinkId) {
      event.preventDefault();
      return;
    }
    hideNodeContextMenu();
    // Middle button pans; left button drags a selection marquee on empty canvas.
    if (event.button === 1) {
      startCanvasPan(event);
      return;
    }
    if (event.button === 0) {
      startMarquee(event);
    }
  }
}

function startCanvasPan(event) {
  state.panning = {
    startX: event.clientX,
    startY: event.clientY,
    scrollLeft: dom.viewport.scrollLeft,
    scrollTop: dom.viewport.scrollTop
  };
  safeSetPointerCapture(dom.viewport, event.pointerId);
  event.preventDefault();
}

function collectSelectedIds() {
  const set = new Set(state.selectedNodeIds);
  if (state.selectedNodeId) set.add(state.selectedNodeId);
  return [...set];
}

function getDragNodeIdsForDrag(node) {
  const selected = collectSelectedIds();
  const baseIds = selected.includes(node.id) && selected.length > 1 ? selected : [node.id];
  return expandFrameDragNodeIds(baseIds);
}

function expandFrameDragNodeIds(baseIds) {
  const selectedFrames = baseIds.map(getNode).filter((node) => node && isFrameNode(node));
  const ids = new Set(baseIds);
  selectedFrames.forEach((frame) => {
    getFrameContainedNodeIds(frame).forEach((id) => ids.add(id));
  });
  return [...ids].filter((id) => getNode(id));
}

function getFrameContainedNodeIds(frame) {
  if (!frame || !isFrameNode(frame)) return [];
  const ids = [];
  const walk = (parentId) => {
    state.project.nodes.forEach((node) => {
      if (node.id === frame.id || normalizeOptionalString(node.frameId).trim() !== parentId) return;
      ids.push(node.id);
      if (isFrameNode(node)) walk(node.id);
    });
  };
  walk(frame.id);
  return ids;
}

function syncFrameMembershipAfterCanvasDrag(drag) {
  const movedIds = new Set(drag?.nodeIds || []);
  if (!movedIds.size) return;
  const baseIds = new Set(drag?.baseNodeIds || drag?.nodeIds || []);
  const movedFrames = [...movedIds].map(getNode).filter((node) => node && isFrameNode(node));
  const activeFrame = getActiveFrameCanvas();
  let changed = false;
  const explicitChildrenMovedWithFrame = (node) => movedFrames.some((frame) => frame.id !== node.id && isFrameDescendantOf(node, frame.id));
  movedIds.forEach((id) => {
    const node = getNode(id);
    if (!node) return;
    if (!baseIds.has(node.id) && explicitChildrenMovedWithFrame(node)) return;
    const parent = activeFrame ? getFrameCanvasDropFrameForNode(node, activeFrame.id) : getCanvasDropFrameForNode(node);
    const nextFrameId = parent?.id || "";
    if (normalizeOptionalString(node.frameId).trim() !== nextFrameId) {
      node.frameId = nextFrameId;
      changed = true;
    }
  });
  sanitizeFrameMembership(state.project);
  if (changed) markProjectStructureChanged();
}

function getFrameNestingDepth(node) {
  let depth = 0;
  let current = normalizeOptionalString(node?.frameId).trim();
  const seen = new Set();
  while (current && !seen.has(current)) {
    seen.add(current);
    depth += 1;
    current = normalizeOptionalString(getNode(current)?.frameId).trim();
  }
  return depth;
}

function getFrameCanvasFrames(frameCanvasId = state.frameCanvasId) {
  const root = getNode(frameCanvasId);
  if (!root || !isFrameNode(root)) return [];
  return [root, ...getFrameDescendantNodes(root.id).filter((node) => isFrameNode(node))];
}

function withFrameCanvasHistoryFrames(nodes) {
  if (!isFrameCanvasActive()) return nodes;
  const merged = new Map(nodes.map((node) => [node.id, node]));
  getFrameCanvasFrames().forEach((frame) => {
    if (!merged.has(frame.id)) merged.set(frame.id, frame);
  });
  return [...merged.values()];
}

function expandFrameToFitMembers(frame) {
  if (!frame || !isFrameNode(frame)) return false;
  const members = state.project.nodes.filter((node) => (
    node && node.id !== frame.id && normalizeOptionalString(node.frameId).trim() === frame.id
  ));
  if (!members.length) return false;
  const bounds = getCombinedNodeBounds(members);
  const size = nodeLayoutSize(frame);
  if (![frame.x, frame.y, size.width, size.height, bounds.left, bounds.top, bounds.right, bounds.bottom].every(Number.isFinite)) return false;
  const left = Math.min(frame.x, Math.round(bounds.left - AUTO_LAYOUT_FRAME_PADDING));
  const top = Math.min(frame.y, Math.round(bounds.top - AUTO_LAYOUT_FRAME_PADDING - AUTO_LAYOUT_FRAME_HEADER));
  const right = Math.max(frame.x + size.width, Math.round(bounds.right + AUTO_LAYOUT_FRAME_PADDING));
  const bottom = Math.max(frame.y + size.height, Math.round(bounds.bottom + AUTO_LAYOUT_FRAME_PADDING));
  if (left === frame.x && top === frame.y && right === frame.x + size.width && bottom === frame.y + size.height) return false;
  frame.x = left;
  frame.y = top;
  frame.width = Math.max(minNodeWidth(frame), right - left);
  frame.height = Math.max(minNodeHeight(frame), bottom - top);
  return true;
}

function expandFrameCanvasFramesToFit(frameCanvasId = state.frameCanvasId) {
  const frames = getFrameCanvasFrames(frameCanvasId)
    .sort((a, b) => getFrameNestingDepth(b) - getFrameNestingDepth(a));
  let changed = false;
  frames.forEach((frame) => {
    changed = expandFrameToFitMembers(frame) || changed;
  });
  return changed;
}

function getFrameVisualContainedNodeIds(frame) {
  if (!frame || !isFrameNode(frame)) return [];
  return state.project.nodes
    .filter((node) => {
      if (!node || node.id === frame.id) return false;
      if (isFrameNode(node) && wouldCreateFrameCycle(node.id, frame.id)) return false;
      return frameContainsNodeCenter(frame, node);
    })
    .map((node) => node.id);
}

function getFrameContainmentChange(frame, beforeIds) {
  if (!Array.isArray(beforeIds)) return null;
  const beforeList = beforeIds.filter((id) => getNode(id));
  const afterList = getFrameVisualContainedNodeIds(frame);
  const before = new Set(beforeList);
  const after = new Set(afterList);
  return {
    beforeIds: beforeList,
    afterIds: afterList,
    addedIds: afterList.filter((id) => !before.has(id)),
    removedIds: beforeList.filter((id) => !after.has(id))
  };
}

function formatFrameContainmentSummary(change) {
  const parts = [];
  if (change.addedIds.length) parts.push(t("{count} entered", { count: change.addedIds.length }));
  if (change.removedIds.length) parts.push(t("{count} left", { count: change.removedIds.length }));
  return parts.join(", ");
}

function canCaptureNodeInFrame(frame, node) {
  if (!frame || !isFrameNode(frame)) return false;
  if (!node || node.id === frame.id) return false;
  if (normalizeOptionalString(node.frameId).trim() === frame.id) return false;
  if (isFrameDescendantOf(node, frame.id)) return false;
  if (isFrameNode(node) && wouldCreateFrameCycle(node.id, frame.id)) return false;
  return true;
}

function getFrameEnteredCaptureCandidates(frame, enteredIds) {
  return enteredIds
    .map(getNode)
    .filter((node) => canCaptureNodeInFrame(frame, node));
}

function maybePromptFrameCapture(frameId, beforeContainmentIds = null) {
  const frame = getNode(frameId);
  if (!frame || !isFrameNode(frame)) return;
  const change = getFrameContainmentChange(frame, beforeContainmentIds);
  if (!change || (!change.addedIds.length && !change.removedIds.length)) return;
  const candidates = getFrameEnteredCaptureCandidates(frame, change.addedIds);
  const removedMembers = change.removedIds
    .map(getNode)
    .filter((node) => normalizeOptionalString(node?.frameId).trim() === frame.id);
  const summary = formatFrameContainmentSummary(change);
  const frameName = frame.title || getNodeDisplayId(frame);
  const hasWritableChanges = Boolean(candidates.length || removedMembers.length);
  showGenericConfirm({
    kicker: "Frame membership",
    title: "Update frame membership?",
    message: t("\"{frame}\" changed canvas containment: {summary}. Apply the current containment as this frame's membership?", { frame: frameName, summary }),
    confirmLabel: "Update membership",
    danger: false,
    recordHistory: hasWritableChanges,
    onConfirm: () => {
      let changed = false;
      candidates.forEach((node) => {
        if (normalizeOptionalString(node.frameId).trim() !== frame.id) {
          node.frameId = frame.id;
          changed = true;
        }
      });
      removedMembers.forEach((node) => {
        const nextParent = getCanvasDropFrameForNode(node);
        const nextFrameId = nextParent && nextParent.id !== frame.id ? nextParent.id : "";
        if (normalizeOptionalString(node.frameId).trim() === frame.id && node.frameId !== nextFrameId) {
          node.frameId = nextFrameId;
          changed = true;
        }
      });
      if (changed) {
        sanitizeFrameMembership(state.project);
        markProjectStructureChanged();
        renderAll();
        setStatus(t("Frame membership updated."));
      } else {
        setStatus(t("Frame membership already matches current canvas."));
      }
    }
  });
}

function isFrameDescendantOf(node, frameId) {
  let current = normalizeOptionalString(node?.frameId).trim();
  const seen = new Set();
  while (current) {
    if (current === frameId) return true;
    if (seen.has(current)) return false;
    seen.add(current);
    current = normalizeOptionalString(getNode(current)?.frameId).trim();
  }
  return false;
}

function getCanvasDropFrameForNode(node) {
  if (!node) return null;
  const descendants = isFrameNode(node) ? new Set(getFrameContainedNodeIds(node)) : new Set();
  const frames = state.project.nodes.filter((frame) => (
    isFrameNode(frame)
    && frame.id !== node.id
    && !descendants.has(frame.id)
  ));
  return getSmallestContainingFrameForNode(node, frames);
}

function getFrameCanvasDropFrameForNode(node, frameCanvasId) {
  if (!node || !frameCanvasId) return getCanvasDropFrameForNode(node);
  const parent = getCanvasDropFrameForNode(node);
  if (parent && (parent.id === frameCanvasId || isFrameDescendantOf(parent, frameCanvasId))) return parent;
  const frame = getNode(frameCanvasId);
  return frame && isFrameNode(frame) && node.id !== frame.id ? frame : null;
}

function getIncidentLinksForNodes(nodeIds) {
  const ids = new Set(nodeIds);
  return state.project.links.filter((link) => ids.has(link.from) || ids.has(link.to));
}

function getPortDragLinks(node) {
  if (!node || !isFrameCollapsed(node)) return getIncidentLinks(node.id);
  const nodeMap = getNodeIndex();
  const activeFrame = getActiveFrameCanvas();
  return state.project.links.filter((link) => {
    const endpoints = getRenderedLinkEndpoints(link, nodeMap, { ignoredCollapsedFrameId: activeFrame?.id || "" });
    return endpoints && (endpoints.from.id === node.id || endpoints.to.id === node.id);
  });
}

function startMarquee(event) {
  const board = screenToBoard(event.clientX, event.clientY);
  const additive = event.shiftKey;
  const baseIds = additive ? collectSelectedIds() : [];
  if (!additive) {
    clearNodeSelection();
    state.selectedLinkId = null;
    state.characterFocusId = null;
  }
  state.marquee = {
    startClientX: event.clientX,
    startClientY: event.clientY,
    startX: board.x,
    startY: board.y,
    curX: board.x,
    curY: board.y,
    baseIds,
    moved: false
  };
  safeSetPointerCapture(dom.viewport, event.pointerId);
  renderNodes();
  renderInspector();
  renderMarquee();
}

function getMarqueeBoardRect() {
  const marquee = state.marquee;
  return {
    left: Math.min(marquee.startX, marquee.curX),
    top: Math.min(marquee.startY, marquee.curY),
    right: Math.max(marquee.startX, marquee.curX),
    bottom: Math.max(marquee.startY, marquee.curY)
  };
}

function nodeIntersectsRect(node, rect) {
  const size = nodeLayoutSize(node);
  return node.x < rect.right
    && node.x + size.width > rect.left
    && node.y < rect.bottom
    && node.y + size.height > rect.top;
}

function updateMarqueeSelection() {
  if (!state.marquee) return;
  const rect = getMarqueeBoardRect();
  const set = new Set(state.marquee.baseIds);
  const activeFrame = getActiveFrameCanvas();
  const frameCanvasNodeIds = activeFrame ? getFrameCanvasNodeIdSet(activeFrame.id) : null;
  state.project.nodes.forEach((node) => {
    if (frameCanvasNodeIds && !frameCanvasNodeIds.has(node.id)) return;
    if (isNodeHiddenByCollapsedFrame(node, activeFrame?.id || "")) return;
    if (nodeIntersectsRect(node, rect)) set.add(node.id);
  });
  state.selectedNodeIds = [...set];
  state.selectedNodeId = null;
}

function renderMarquee() {
  if (!dom.marqueeRect) return;
  if (!state.marquee) {
    dom.marqueeRect.hidden = true;
    return;
  }
  const rect = getMarqueeBoardRect();
  dom.marqueeRect.hidden = false;
  dom.marqueeRect.style.left = `${rect.left}px`;
  dom.marqueeRect.style.top = `${rect.top}px`;
  dom.marqueeRect.style.width = `${Math.max(0, rect.right - rect.left)}px`;
  dom.marqueeRect.style.height = `${Math.max(0, rect.bottom - rect.top)}px`;
}

function finishMarquee(event) {
  const marquee = state.marquee;
  state.marquee = null;
  safeReleasePointerCapture(dom.viewport, event.pointerId);
  if (dom.marqueeRect) dom.marqueeRect.hidden = true;
  state.selectedNodeIds = state.selectedNodeIds.filter((id) => getNode(id));
  if (marquee.moved) {
    // Releasing a drag-select over a node fires a trailing click on it, which
    // would collapse the marquee selection to that single node. Swallow it.
    state.ignoreNextCanvasClick = true;
    state.ignoreNextCanvasClickTargetId = null;
  }
  renderNodes();
  renderInspector();
  if (marquee.moved && state.selectedNodeIds.length) {
    const clientX = event.clientX;
    const clientY = event.clientY;
    // Defer so the trailing click (which would hide the menu) runs first.
    requestAnimationFrame(() => {
      if (state.selectedNodeIds.length) showGroupContextMenu(clientX, clientY);
    });
  }
}

function handleViewportDoubleClick(event) {
  const nodeElement = event.target.closest?.(".node[data-node-id]");
  if (nodeElement) {
    if (isCanvasNodeInlineEditBlockedTarget(event.target)) return;
    cancelPendingConnection();
    focusCanvasNodeForInlineEdit(nodeElement.dataset.nodeId);
    event.preventDefault();
    event.stopPropagation();
    return;
  }
  const linkElement = event.target.closest?.("[data-link-id]");
  if (linkElement && dom.linkLayer?.contains(linkElement)) {
    startInlineLinkLabelEdit(linkElement.dataset.linkId);
    event.preventDefault();
    event.stopPropagation();
    return;
  }
  if (event.target !== dom.viewport && event.target !== dom.content && event.target !== dom.frameLayer && event.target !== dom.nodeLayer && event.target !== dom.linkLayer) return;
  if (cancelPendingConnection()) {
    event.preventDefault();
  }
}

function startInlineLinkLabelEdit(linkId) {
  const link = getLink(linkId);
  if (!link) return;
  state.inlineEditLinkId = link.id;
  state.inlineEditLinkInitialValue = normalizeOptionalString(link.label);
  state.selectedLinkId = link.id;
  clearNodeSelection();
  renderLinks();
  runAfterRender(() => {
    const editor = dom.linkLayer?.querySelector?.(`[data-inline-link-label][data-link-id="${CSS.escape(link.id)}"]`);
    editor?.focus?.({ preventScroll: true });
    editor?.select?.();
  });
}

function setInlineLinkLabel(linkId, value) {
  const link = getLink(linkId);
  if (!link) return;
  const label = normalizeOptionalString(value);
  const source = getNode(link.from);
  if (source && isChoiceNode(source)) {
    const options = ensureChoiceOptionsArray(source);
    const choiceIndex = normalizeChoiceIndex(link.choiceIndex);
    const option = (link.choiceOptionId ? options.find((entry) => entry.id === link.choiceOptionId) : null)
      || (choiceIndex != null ? options[choiceIndex] : null);
    if (option) {
      option.label = label;
      syncChoicesFromOptions(source);
    }
  }
  link.label = label;
  setProjectDirty(true);
  updateStatus();
  scheduleStoryPanelRender();
}

function finishInlineLinkLabelEdit(linkId, options = {}) {
  const link = getLink(linkId);
  if (link && !options.canceled) {
    const normalized = normalizeOptionalString(link.label).trim();
    if (normalized !== link.label) setInlineLinkLabel(link.id, normalized);
  }
  state.inlineEditLinkId = null;
  state.inlineEditLinkInitialValue = "";
  renderNodes();
  renderLinks();
  renderInspector();
  if (!options.canceled) setStatus(link?.label ? t("Link label updated.") : t("Link label cleared."));
}

function cancelPendingConnection() {
  if (!state.connectingFrom && !state.reconnectingLinkId) return false;
  clearLinkReconnect();
  renderLinks();
  setStatus("Connection canceled.");
  return true;
}

function handleViewportScroll() {
  hideNodeContextMenu();
  updateGridPosition();
  scheduleCanvasViewportRender();
}

function handleViewportPointerMove(event) {
  if (state.draggingPort) {
    const drag = state.draggingPort;
    const distance = Math.hypot(event.clientX - drag.startX, event.clientY - drag.startY);
    // Need a clear drag intent before swallowing the follow-up click. Otherwise small mouse
    // jitter on a port click sets suppressPortClick=true and connections can't start.
    if (!drag.active && distance < 8) return;
    if (!drag.active) {
      // First crossing of the threshold — take the pointer capture now so the pointermoves
      // keep flowing to the viewport even if the cursor leaves the small port button.
      safeSetPointerCapture(dom.viewport, drag.pointerId ?? event.pointerId);
    }
    drag.active = true;
    const node = getNode(drag.nodeId);
    if (!node) return;
    setNodePortFromBoardPoint(node, drag.kind, screenToBoard(event.clientX, event.clientY));
    patchNodePortGeometry(node);
    patchLinkElementRefs(drag.linkRefs);
    event.preventDefault();
    return;
  }
  if (state.marquee) {
    const board = screenToBoard(event.clientX, event.clientY);
    state.marquee.curX = board.x;
    state.marquee.curY = board.y;
    if (!state.marquee.moved
      && (Math.abs(event.clientX - state.marquee.startClientX) > 3 || Math.abs(event.clientY - state.marquee.startClientY) > 3)) {
      state.marquee.moved = true;
    }
    updateMarqueeSelection();
    renderMarquee();
    renderNodes();
    event.preventDefault();
    return;
  }
  if (state.resizingNode) {
    const resizeMoveX = event.clientX - state.resizingNode.startX;
    const resizeMoveY = event.clientY - state.resizingNode.startY;
    if (!state.resizingNode.didMove && (Math.abs(resizeMoveX) > 3 || Math.abs(resizeMoveY) > 3)) {
      state.resizingNode.didMove = true;
      state.ignoreNextCanvasClick = true;
    }
    if (!state.resizingNode.didMove) return;
    const node = getNode(state.resizingNode.id);
    if (!node) return;
    const handle = state.resizingNode.handle;
    if (handle.includes("e")) {
      node.width = clamp(snapCanvasValue(clamp(
        state.resizingNode.width + (event.clientX - state.resizingNode.startX) / state.view.scale,
        minNodeWidth(node),
        maxNodeWidth(node)
      ), { enabled: state.snapToGrid }), minNodeWidth(node), maxNodeWidth(node));
    }
    if (handle.includes("s")) {
      node.height = clamp(snapCanvasValue(clamp(
        state.resizingNode.height + (event.clientY - state.resizingNode.startY) / state.view.scale,
        minNodeHeight(node),
        maxNodeHeight(node)
      ), { enabled: state.snapToGrid }), minNodeHeight(node), maxNodeHeight(node));
    }
    // Patch only this node + its links in place; full resync runs on pointer-up.
    if (patchNodeElementGeometry(node, state.resizingNode.element, state.resizingNode.ports)) {
      patchLinkElementRefs(state.resizingNode.linkRefs);
    } else {
      const context = getCanvasRenderContext();
      renderNodes(context);
      renderLinks(context);
    }
  } else if (state.draggingNode) {
    const moveX = event.clientX - state.draggingNode.startX;
    const moveY = event.clientY - state.draggingNode.startY;
    if (!state.draggingNode.didMove && (Math.abs(moveX) > 3 || Math.abs(moveY) > 3)) {
      state.draggingNode.didMove = true;
      state.ignoreNextCanvasClick = true;
    }
    if (!state.draggingNode.didMove) return;
    const deltaX = moveX / state.view.scale;
    const deltaY = moveY / state.view.scale;
    const positions = state.draggingNode.nodePositions || [];
    const anchorPosition = positions.find((position) => position.id === state.draggingNode.id) || positions[0];
    const snappedDeltaX = anchorPosition && state.snapToGrid
      ? snapCanvasValue(anchorPosition.x + deltaX) - anchorPosition.x
      : deltaX;
    const snappedDeltaY = anchorPosition && state.snapToGrid
      ? snapCanvasValue(anchorPosition.y + deltaY) - anchorPosition.y
      : deltaY;
    positions.forEach((position) => {
      const item = getNode(position.id);
      if (!item) return;
      item.x = Math.round(position.x + snappedDeltaX);
      item.y = Math.round(position.y + snappedDeltaY);
    });
    const node = getNode(state.draggingNode.id);
    if (!node) return;
    if (positions.length <= 1 && patchNodeElementGeometry(node, state.draggingNode.element, state.draggingNode.ports)) {
      patchLinkElementRefs(state.draggingNode.linkRefs);
    } else if (positions.length > 1 && patchNodeElementsGeometry(positions.map((position) => position.id))) {
      patchLinkElementRefs(state.draggingNode.linkRefs);
    } else {
      const context = getCanvasRenderContext();
      renderNodes(context);
      renderLinks(context);
    }
  } else if (state.panning) {
    let nextScrollLeft = state.panning.scrollLeft - (event.clientX - state.panning.startX);
    let nextScrollTop = state.panning.scrollTop - (event.clientY - state.panning.startY);
    let shiftedOrigin = false;
    if (nextScrollLeft < CANVAS_PAN_EDGE_PADDING) {
      const shift = CANVAS_PAN_EDGE_PADDING - nextScrollLeft;
      state.view.x += shift;
      state.panning.scrollLeft += shift;
      nextScrollLeft += shift;
      shiftedOrigin = true;
    }
    if (nextScrollTop < CANVAS_PAN_EDGE_PADDING) {
      const shift = CANVAS_PAN_EDGE_PADDING - nextScrollTop;
      state.view.y += shift;
      state.panning.scrollTop += shift;
      nextScrollTop += shift;
      shiftedOrigin = true;
    }
    if (shiftedOrigin) renderTransform();
    extendCanvasScrollBoundsForPan(nextScrollLeft, nextScrollTop);
    dom.viewport.scrollLeft = nextScrollLeft;
    dom.viewport.scrollTop = nextScrollTop;
    updateGridPosition();
    event.preventDefault();
  } else if (state.connectingFrom) {
    state.connectingTo = screenToBoard(event.clientX, event.clientY);
    renderLinks();
  }
}

function setNodePortFromBoardPoint(node, kind, point) {
  const size = nodeLayoutSize(node);
  const relX = clamp((point.x - node.x) / Math.max(1, size.width), 0, 1);
  const relY = clamp((point.y - node.y) / Math.max(1, size.height), 0, 1);
  const outsideDistances = [
    { side: "top", value: node.y - point.y, t: relX },
    { side: "right", value: point.x - (node.x + size.width), t: relY },
    { side: "bottom", value: point.y - (node.y + size.height), t: relX },
    { side: "left", value: node.x - point.x, t: relY }
  ].filter((item) => item.value > 0);
  const distances = outsideDistances.length ? outsideDistances : [
    { side: "top", value: Math.abs(point.y - node.y), t: relX },
    { side: "right", value: Math.abs(point.x - (node.x + size.width)), t: relY },
    { side: "bottom", value: Math.abs(point.y - (node.y + size.height)), t: relX },
    { side: "left", value: Math.abs(point.x - node.x), t: relY }
  ];
  const next = distances.sort((a, b) => outsideDistances.length ? b.value - a.value : a.value - b.value)[0];
  node.ports = normalizeNodePorts(node.ports, node);
  node.ports[kind] = { side: next.side, t: clamp(next.t, 0, 1) };
  setProjectDirty(true);
}

function endPointerActions(event) {
  if (state.draggingPort) {
    const drag = state.draggingPort;
    state.draggingPort = null;
    if (drag.active) {
      // Capture was only taken once the drag crossed the threshold; release it here so
      // future clicks land on the right elements again.
      safeReleasePointerCapture(dom.viewport, drag.pointerId ?? event.pointerId);
      state.suppressPortClick = true;
      commitHistoryFromSnapshot(drag.historyBefore);
      renderLinks();
      updateStatus();
    }
    return;
  }
  if (state.marquee) {
    finishMarquee(event);
    return;
  }
  const shouldCommitHistory = Boolean(state.draggingNode || state.resizingNode);
  const interactionNodeId = state.draggingNode?.nodeIds?.length > 1 ? null : (state.draggingNode?.id || state.resizingNode?.id || null);
  const suppressNodeClickAfterRelease = Boolean(state.draggingNode?.didMove || state.resizingNode?.didMove);
  const captureFrameId = (() => {
    const candidateId = state.draggingNode?.baseNodeIds?.length === 1
      ? state.draggingNode.baseNodeIds[0]
      : interactionNodeId;
    const candidate = getNode(candidateId);
    return candidate && isFrameNode(candidate) ? candidate.id : null;
  })();
  const captureFrameContainmentBefore = (() => {
    const interaction = state.draggingNode || state.resizingNode;
    return captureFrameId && interaction?.frameContainmentBeforeFrameId === captureFrameId
      ? interaction.frameContainmentBefore
      : null;
  })();
  if (state.draggingNode || state.resizingNode || state.panning) {
    safeReleasePointerCapture(dom.viewport, event.pointerId);
  }
  if (state.draggingNode) syncFrameMembershipAfterCanvasDrag(state.draggingNode);
  if (shouldCommitHistory && isFrameCanvasActive()) expandFrameCanvasFramesToFit();
  state.draggingNode = null;
  state.resizingNode = null;
  state.panning = null;
  state.ignoreNextCanvasClick = suppressNodeClickAfterRelease;
  state.ignoreNextCanvasClickTargetId = suppressNodeClickAfterRelease ? interactionNodeId : null;
  if (suppressNodeClickAfterRelease) {
    const ignoredTargetId = interactionNodeId;
    window.setTimeout(() => {
      if (!state.ignoreNextCanvasClick || state.ignoreNextCanvasClickTargetId !== ignoredTargetId) return;
      state.ignoreNextCanvasClick = false;
      state.ignoreNextCanvasClickTargetId = null;
    }, 0);
  }
  if (shouldCommitHistory) {
    commitGeometryHistoryCapture();
    // The interaction patched the canvas in place; refresh visible DOM once and
    // update only the affected minimap marker/geometry fields.
    resyncCanvasAfterInteraction(interactionNodeId);
    if (captureFrameId) {
      maybePromptFrameCapture(captureFrameId, captureFrameContainmentBefore);
    }
  }
}

function handleWheel(event) {
  if (isCanvasRadialMenuOpen() && !dom.canvasRadialMenu.contains(event.target)) hideCanvasRadialMenu();
  if (!event.ctrlKey && !event.metaKey) return;
  event.preventDefault();
  const before = screenToBoard(event.clientX, event.clientY);
  const delta = event.deltaY < 0 ? 0.08 : -0.08;
  const nextScale = clamp(state.view.scale + delta, CANVAS_MIN_ZOOM, CANVAS_MAX_ZOOM);
  const rect = dom.viewport.getBoundingClientRect();
  state.view.scale = nextScale;
  state.view.x = event.clientX - rect.left + dom.viewport.scrollLeft - before.x * nextScale;
  state.view.y = event.clientY - rect.top + dom.viewport.scrollTop - before.y * nextScale;
  renderTransform();
  updateGridPosition();
  scheduleCanvasViewportRender();
  renderProjectPanel();
}

function handlePortClick(port) {
  const nodeId = port.dataset.nodeId;
  const kind = port.dataset.port;

  if (state.reconnectingLinkId) {
    const link = getLink(state.reconnectingLinkId);
    if (!link) {
      clearLinkReconnect();
      renderLinks();
      return;
    }
    if (state.reconnectingEnd === "to") {
      if (kind !== "input") {
        setStatus("Choose an input port for the new link target.");
        return;
      }
      if (link.from === nodeId) {
        setStatus("A link cannot target its own source.");
        return;
      }
      const historyBefore = getHistorySnapshot();
      link.to = nodeId;
      syncChoiceBranchLinksForNode(link.from, { markDirty: false, preferredLinkId: link.id });
      invalidateLinkIndexes();
      markProjectStructureChanged();
      finishLinkReconnect(link);
      commitHistoryFromSnapshot(historyBefore);
      return;
    }
    if (state.reconnectingEnd === "from") {
      if (kind !== "output") {
        setStatus("Choose an output port for the new link source.");
        return;
      }
      if (link.to === nodeId) {
        setStatus("A link cannot start from its own target.");
        return;
      }
      const historyBefore = getHistorySnapshot();
      link.from = nodeId;
      syncChoiceBranchLinksForNode(link.from, { markDirty: false, preferredLinkId: link.id });
      invalidateLinkIndexes();
      markProjectStructureChanged();
      finishLinkReconnect(link);
      commitHistoryFromSnapshot(historyBefore);
      return;
    }
  }

  if (kind === "output") {
    state.connectingFrom = nodeId;
    state.connectingTo = getOutputPoint(getNode(nodeId));
    dom.hint.classList.add("show");
    renderLinks();
    return;
  }

  if (kind === "input" && state.connectingFrom && state.connectingFrom !== nodeId) {
    const historyBefore = getHistorySnapshot();
    const link = {
      id: nextId("l", state.project.links),
      from: state.connectingFrom,
      to: nodeId
    };
    state.project.links.push(link);
    syncChoiceBranchLinksForNode(link.from, { markDirty: false, preferredLinkId: link.id });
    markProjectStructureChanged();
    clearStoryOrderOverrides();
    clearEventRowOrderOverrides();
    state.connectingFrom = null;
    state.connectingTo = null;
    dom.hint.classList.remove("show");
    state.selectedLinkId = link.id;
    clearNodeSelection();
    renderAll();
    setStatus(link.label ? `Link created: ${link.label}.` : "Link created.");
    commitHistoryFromSnapshot(historyBefore);
    return;
  }

  state.connectingFrom = null;
  state.connectingTo = null;
  dom.hint.classList.remove("show");
  renderLinks();
}

function addNode(type, spawnPoint = null) {
  state.activeFileId = "adventure";
  renderShellState();
  renderWorkspaceFile();
  const rect = dom.viewport.getBoundingClientRect();
  const center = spawnPoint && Number.isFinite(spawnPoint.x) && Number.isFinite(spawnPoint.y)
    ? spawnPoint
    : screenToBoard(rect.left + rect.width / 2, rect.top + rect.height / 2);
  const node = {
    id: nextId("n", state.project.nodes),
    type,
    title: type === "Entry" ? "Start" : getNodeTypeLabel(type),
    body: defaultBody(type),
    x: 0,
    y: snapCanvasValue(center.y - 70, { enabled: state.snapToGrid })
  };
  if (getNodeTypeTemplate(type) === "choice") node.choices = ["Continue", "Turn back"];
  applyNodeTypeDefaults(node);
  node.x = snapCanvasValue(center.x - nodeLayoutSize(node).width / 2, { enabled: state.snapToGrid });
  const activeFrame = getActiveFrameCanvas();
  const dropFrame = getCanvasDropFrameForNode(node);
  node.frameId = activeFrame
    ? (dropFrame && isNodeWithinFrameCanvas(dropFrame, activeFrame.id) ? dropFrame.id : activeFrame.id)
    : (dropFrame?.id || "");
  assignDefaultLayerOrderForNewNode(node);
  state.project.nodes.push(normalizeNode(node));
  markProjectStructureChanged();
  selectNode(node.id);
  setStatus(`${getNodeTypeLabel(type)} added.`);
}

function assignDefaultLayerOrderForNewNode(node) {
  if (!isFrameNode(node)) return;
  const existingDefaultFrameOrders = state.project.nodes
    .map((existingNode, index) => ({ node: existingNode, order: getNodeLayerOrder(existingNode, index) }))
    .filter((item) => isFrameNode(item.node) && item.order < REGULAR_LAYER_BASE)
    .map((item) => item.order);
  const topDefaultFrameOrder = existingDefaultFrameOrders.length
    ? Math.max(...existingDefaultFrameOrders)
    : EVENT_LAYER_BASE - 1;
  node.layerOrder = Math.min(REGULAR_LAYER_BASE - 1, topDefaultFrameOrder + 1);
}

function addCustomNodeType() {
  const label = dom.customNodeName.value.trim();
  if (!label) {
    setStatus("Enter a custom node type name.");
    return;
  }
  const template = normalizeNodeTypeTemplate(dom.customNodeKind.value);
  const kind = template === "frame" ? "frame" : "node";
  const typeDef = normalizeCustomNodeType({
    type: uniqueCustomNodeTypeId(label),
    label,
    color: getCustomNodeFormColor(template),
    kind,
    template,
    fields: parseCustomNodeFields(dom.customNodeFields.value),
    cardOpacity: isFrameKind(kind) ? 20 : undefined
  });
  state.project.nodeTypes = [...getProjectNodeTypes(), typeDef];
  markProjectStructureChanged({ nodeTypes: true });
  dom.customNodeName.value = "";
  dom.customNodeKind.value = "node";
  dom.customNodeFields.value = "";
  dom.customNodeColor.value = DEFAULT_CUSTOM_NODE_COLOR;
  renderPalette();
  renderInspector();
  setStatus(`${typeDef.label} node type added.`);
}

function getCustomNodeFormColor(template) {
  const color = dom.customNodeColor.value || DEFAULT_CUSTOM_NODE_COLOR;
  if (color === DEFAULT_CUSTOM_NODE_COLOR && template === "frame") return getDefaultNodeTypeColor("frame");
  return color;
}

function deleteCustomNodeType(type) {
  if (!type) return;
  const typeDef = getProjectNodeTypes().find((item) => item.type === type);
  if (!typeDef) return;
  const label = typeDef.label || type;
  const nodesInUse = state.project.nodes.filter((node) => node.type === type).length;
  if (nodesInUse) {
    showNodeTypeInUseDialog(typeDef, nodesInUse);
    return;
  }
  if (typeDef.system) {
    showGenericConfirm({
      kicker: "Node Library",
      title: t("Cannot delete {label}", { label }),
      message: t("Default node type \"{label}\" cannot be deleted. Hide it from the Node Library if you do not need it right now.", { label }),
      confirmLabel: "Hide node type",
      danger: false,
      recordHistory: true,
      onConfirm: () => hideNodeType(type)
    });
    return;
  }
  const isDefault = Boolean(nodeTypes[type]);
  const message = t("Delete \"{label}\" from the Node Library schema? {recovery}", {
    label,
    recovery: t(isDefault ? "Restore default types can bring this template back." : "Custom deleted types can only come back by importing or recreating them.")
  });
  showGenericConfirm({
    kicker: "Node Library",
    title: t("Delete {label}?", { label }),
    message,
    confirmLabel: "Delete",
    danger: true,
    recordHistory: true,
    onConfirm: () => deleteCustomNodeTypeConfirmed(type)
  });
}

function showNodeTypeInUseDialog(typeDef, nodesInUse) {
  const type = typeDef.type;
  const label = typeDef.label || type;
  showGenericConfirm({
    kicker: "Node Library",
    title: t("Cannot delete {label}", { label }),
    message: t("\"{label}\" is still used by {count} canvas nodes, so it cannot be deleted. Hide it from the Node Library instead, or change those nodes to another type first.", { label, count: nodesInUse }),
    confirmLabel: "Hide node type",
    danger: false,
    recordHistory: true,
    onConfirm: () => hideNodeType(type)
  });
}

function deleteCustomNodeTypeConfirmed(type) {
  const typeDef = getProjectNodeTypes().find((item) => item.type === type);
  if (!typeDef) return;
  const label = typeDef.label || type;
  const nodesInUse = state.project.nodes.filter((node) => node.type === type).length;
  if (nodesInUse) {
    showNodeTypeInUseDialog(typeDef, nodesInUse);
    return;
  }
  if (typeDef.system) {
    setStatus(`${typeDef.label || type} is a system type and cannot be deleted.`);
    return;
  }
  state.project.nodeTypes = getProjectNodeTypes().filter((item) => item.type !== type);
  markProjectStructureChanged({ nodeTypes: true });
  renderPalette();
  renderInspector();
  setStatus(`${label} node type deleted.`);
}

function hideNodeType(type) {
  if (!type) return;
  const typeDef = getProjectNodeTypes().find((item) => item.type === type);
  if (!typeDef) return;
  typeDef.hidden = true;
  markProjectStructureChanged({ nodeTypes: true });
  renderPalette();
  renderInspector();
  setStatus(`${typeDef.label || type} hidden from Node Library. Data kept.`);
}

function restoreDefaultNodeTypes() {
  const current = getProjectNodeTypes();
  const byType = new Map(current.map((typeDef) => [typeDef.type, typeDef]));
  let restored = 0;

  defaultNodeTypeList().forEach((defaultType) => {
    const existing = byType.get(defaultType.type);
    if (existing) {
      if (existing.hidden) {
        existing.hidden = false;
        restored += 1;
      }
      return;
    }
    current.push(defaultType);
    restored += 1;
  });

  state.project.nodeTypes = normalizeNodeTypes(current);
  markProjectStructureChanged({ nodeTypes: true });
  renderAll();
  if (restored) {
    setStatus("Default node types restored.");
  } else {
    setStatus("Default node types are already available.");
  }
}

function restoreNodeType(type) {
  const typeDef = getNodeTypeDef(type);
  if (!typeDef) return;
  typeDef.hidden = false;
  markProjectStructureChanged({ nodeTypes: true });
  renderPalette();
  renderInspector();
  setStatus(`${typeDef.label || type} restored to Node Library.`);
}

function defaultBody(type) {
  const defaults = {
    Entry: "Start here.",
    Content: "Write narration here.",
    Dialog: "Character line.",
    Choice: "Offer player choices.",
    Marker: "Planning marker.",
    Event: "Group related beats into one frame row."
  };
  if (defaults[type]) return defaults[type];
  const template = getNodeTypeTemplate(type);
  if (template === "dialog") return "Character line.";
  if (template === "choice") return "Offer player choices.";
  const kind = getNodeMeta(type).kind;
  if (isFrameKind(kind)) return "Group related nodes into one frame row.";
  return isFrameKind(kind) ? "Group related nodes." : "Write custom node content here.";
}

function applyNodeTypeDefaults(node) {
  const meta = getNodeMeta(node.type);
  ensureCustomFieldDefaults(node);
  if (isEventSheetNode(node)) ensureEventDefaults(node, getEventSheetColumnsForType(node.type));
  if (isFrameNode(node)) {
    node.width = node.width || meta.width || 420;
    node.height = node.height || defaultNodeHeight(node, node.width);
  }
}

function addCharacter(kind = "Character", codexMode = false) {
  const characters = getCharacters();
  const wasEmpty = characters.length === 0;
  const normalizedKind = normalizeCodexKind(kind);
  const nextNumber = characters.filter((entry) => entry.kind === normalizedKind).length + 1;
  const character = {
    id: nextId("c", characters),
    name: uniqueCharacterName(`${normalizedKind} ${nextNumber}`),
    kind: normalizedKind,
    role: "",
    voice: "",
    tags: "",
    notes: "",
    extraFields: [],
    codexFile: "",
    images: [],
    imageFile: "",
    imagePreview: false
  };
  applyCodexTemplateToCharacter(character);
  characters.push(character);
  state.project.characters = characters;
  state.codexSelectedEntryId = character.id;
  invalidateCharacterRenderContext();
  if (wasEmpty) {
    state.characterSearch = "";
    resetDocumentRenderLimit("characters");
  }
  const shouldSwitchToCharacters = state.activeFileId !== "characters";
  state.activeFileId = "characters";
  setProjectDirty(true);
  if (shouldSwitchToCharacters) renderDocumentFileSwitch();
  else renderCharacterListSurfaces();
  revealCharacterCard(character.id);
  setStatus(codexMode ? t("Library entry added.") : t("Character added."));
}

function addCodexEntry() {
  const kind = normalizeCodexKindFilter(state.codexKindFilter) === CODEX_ALL_FILTER
    ? "Character"
    : normalizeCodexKind(state.codexKindFilter);
  state.characterSearch = "";
  state.codexTagFilter = "";
  state.codexKindFilter = kind;
  if (dom.characterSearchInput) dom.characterSearchInput.value = "";
  addCharacter(kind, true);
}

function revealCharacterCard(id) {
  runAfterRender(() => {
    const card = dom.charactersPanel?.querySelector(`[data-character-card-id="${CSS.escape(id)}"]`);
    if (!card) return;
    card.scrollIntoView?.({ behavior: "smooth", block: "center" });
    const nameInput = card.querySelector("[data-character-field='name']");
    nameInput?.focus?.({ preventScroll: true });
  });
}

function deleteCharacter(id) {
  const characters = getCharacters();
  const character = characters.find((item) => item.id === id);
  if (!character) return;
  showGenericConfirm({
    kicker: "Narrative Library",
    title: t('Delete "{name}"?', { name: character.name }),
    message: character.codexFile
      ? t("The library entry and its managed Markdown file will be moved to the vault trash. Linked images and referenced files are kept.")
      : t("The library entry will be removed from this project. Linked images and referenced files are kept."),
    confirmLabel: "Delete entry",
    danger: true,
    recordHistory: false,
    onConfirm: async () => {
      const historyBefore = getHistorySnapshot();
      const host = window.NarrativeCanvasHost;
      try {
        if (host?.deleteCodexEntryFile) await host.deleteCodexEntryFile(character);
      } catch (error) {
        console.error(error);
        setStatus(t("Could not move the library Markdown file to trash. The entry was kept."));
        return;
      }
      performDeleteCharacter(id);
      commitHistoryFromSnapshot(historyBefore);
    }
  });
}

function performDeleteCharacter(id) {
  const characters = getCharacters();
  const character = characters.find((item) => item.id === id);
  state.project.characters = characters.filter((item) => item.id !== id);
  if (state.codexSelectedEntryId === id) state.codexSelectedEntryId = "";
  invalidateCharacterRenderContext();
  state.project.nodes.forEach((node) => {
    node.cast = normalizeNodeCast(node.cast).filter((entry) => entry.characterId !== id);
    if (!node.cast.length) delete node.cast;
  });
  if (state.characterFocusId === id || !getCharacterById(state.characterFocusId)) state.characterFocusId = null;
  if (state.characterBacklinkGroupCollapsedKeys instanceof Set) {
    [...state.characterBacklinkGroupCollapsedKeys].forEach((key) => {
      try {
        if (JSON.parse(key)?.[0] === id) state.characterBacklinkGroupCollapsedKeys.delete(key);
      } catch (_error) {
        state.characterBacklinkGroupCollapsedKeys.delete(key);
      }
    });
  }
  if (!state.project.characters.length) {
    state.characterSearch = "";
    resetDocumentRenderLimit("characters");
  }
  state.activeFileId = "characters";
  setProjectDirty(true);
  renderCharacterListSurfaces();
  setStatus(character ? `${character.name} deleted.` : "Library entry deleted.");
}

function hideCharacter(id) {
  const character = getCharacters().find((item) => item.id === id);
  if (!character) return;
  character.hidden = true;
  if (state.codexSelectedEntryId === id) state.codexSelectedEntryId = "";
  if (state.characterFocusId === id) state.characterFocusId = null;
  invalidateCharacterRenderContext();
  state.activeFileId = "characters";
  setProjectDirty(true);
  renderCharacterListSurfaces();
  setStatus(t("{name} hidden.", { name: character.name }));
}

function showCharacter(id) {
  const character = getCharacters().find((item) => item.id === id);
  if (!character) return;
  character.hidden = false;
  invalidateCharacterRenderContext();
  state.activeFileId = "characters";
  setProjectDirty(true);
  renderCharacterListSurfaces();
  setStatus(t("{name} shown.", { name: character.name }));
}

function showAllCharacters() {
  const characters = getCharacters();
  let changed = false;
  characters.forEach((character) => {
    if (character.hidden) {
      character.hidden = false;
      changed = true;
    }
  });
  if (!changed) return;
  invalidateCharacterRenderContext();
  state.activeFileId = "characters";
  setProjectDirty(true);
  renderCharacterListSurfaces();
  setStatus("All entries visible.");
}

function setCharacterField(id, field, value, rerender) {
  const character = getCharacters().find((item) => item.id === id);
  if (!character) return;
  invalidateCharacterRenderContext();
  if (field === "name") {
    const previousName = character.name;
    const nextName = normalizeOptionalString(value).trim();
    if (!nextName) {
      setStatus("Entry name is required.");
      if (rerender) renderCharacterListSurfaces();
      return;
    }
    character.name = nextName;
    state.project.nodes.forEach((node) => {
      if (character.kind === "Character" && isDialogNode(node) && node.title === previousName) {
        node.title = nextName;
      }
    });
    if (rerender) {
      if (isCanvasFileActive()) {
        renderNodes();
        renderLinks();
        markCanvasSurfaceRendered();
      }
      renderStoryPanel();
    }
  } else {
    if (field === "kind") {
      const nextKind = normalizeCodexKind(value);
      character.kind = nextKind;
      applyCodexTemplateToCharacter(character);
      state.project.nodes.forEach((node) => {
        const cast = normalizeNodeCast(node.cast);
        let changed = false;
        cast.forEach((entry) => {
          if (entry.characterId !== character.id) return;
          if ((CODEX_RELATIONS_BY_KIND[nextKind] || []).includes(entry.role)) return;
          entry.role = getDefaultCodexRelation(nextKind);
          changed = true;
        });
        if (changed) node.cast = normalizeNodeCast(cast);
      });
    } else if (field === "imageFile") {
      syncCharacterImageAliases(character, normalizeVisionBoardImages([], value));
    } else if (field === "imagePreview") {
      character.imagePreview = Boolean(value);
    } else {
      character[field] = value;
    }
  }
  setProjectDirty(true);
  if (rerender) updateStatus();
  if (rerender) renderWorkspaceFile();
}

function setCharacterExtraField(id, index, part, value, rerender) {
  const character = getCharacters().find((item) => item.id === id);
  if (!character) return;
  const fields = normalizeCodexExtraFields(character.extraFields);
  if (!Number.isInteger(index) || index < 0 || index >= fields.length) return;
  if (part === "key") {
    const nextKey = String(value || "").trim();
    if (CODEX_RESERVED_FRONTMATTER_KEYS.has(nextKey.toLowerCase())) {
      setStatus(t("Field name {key} is reserved.", { key: nextKey }));
      if (rerender) renderWorkspaceFile();
      return;
    }
    if (nextKey && fields.some((field, fieldIndex) => fieldIndex !== index && field.key.toLowerCase() === nextKey.toLowerCase())) {
      setStatus(t("Field name {key} already exists.", { key: nextKey }));
      if (rerender) renderWorkspaceFile();
      return;
    }
    fields[index].key = nextKey;
  } else if (part === "type") {
    const type = CODEX_EXTRA_FIELD_TYPES.has(String(value || "").toLowerCase()) ? String(value).toLowerCase() : "string";
    const formatted = formatCodexExtraFieldValue(fields[index].value, fields[index].type);
    const parsed = parseCodexExtraFieldInput(formatted, type);
    fields[index].type = type;
    fields[index].value = parsed.valid ? parsed.value : normalizeCodexExtraFieldValue(undefined, type);
  } else {
    const parsed = parseCodexExtraFieldInput(value, fields[index].type);
    if (!parsed.valid) {
      setStatus(t("Field value is invalid for type {type}.", { type: t(fields[index].type) }));
      if (rerender) renderWorkspaceFile();
      return;
    }
    fields[index].value = parsed.value;
  }
  character.extraFields = fields;
  invalidateCharacterRenderContext();
  setProjectDirty(true);
  if (rerender) renderWorkspaceFile();
}

function addCodexExtraField(id) {
  const character = getCharacters().find((item) => item.id === id);
  if (!character) return;
  const fields = normalizeCodexExtraFields(character.extraFields);
  fields.push({ key: "", type: "string", value: "" });
  character.extraFields = fields;
  invalidateCharacterRenderContext();
  setProjectDirty(true);
  renderWorkspaceFile();
  runAfterRender(() => {
    const inputs = dom.charactersPanel?.querySelectorAll(`[data-character-id="${CSS.escape(id)}"][data-character-extra-part="key"]`);
    inputs?.[inputs.length - 1]?.focus?.();
  });
}

function addCodexKind() {
  showGenericTextInput({
    kicker: "Library",
    title: t("Add category"),
    label: t("Category name"),
    confirmLabel: t("Add"),
    onConfirm: (value) => {
      const name = String(value || "").trim();
      if (!name) return;
      const kinds = getCodexKindsList();
      if (name.toLowerCase() === "all" || kinds.some((kind) => kind.toLowerCase() === name.toLowerCase())) {
        setStatus(t("Category {name} already exists.", { name }));
        return;
      }
      state.project.customCodexKinds = normalizeCustomCodexKinds([...(state.project.customCodexKinds || []), name]);
      state.codexKindFilter = name;
      setProjectDirty(true);
      renderCharactersPage();
      setStatus(t("Category {name} added.", { name }));
    }
  });
}

function removeCodexKind(kindValue) {
  const name = String(kindValue || "").trim();
  if (!name) return;
  const count = getCharacters().filter((entry) => entry.kind.toLowerCase() === name.toLowerCase()).length;
  if (count) {
    setStatus(t("Category {name} still has {count} entries. Move or remove them first.", { name, count }));
    return;
  }
  state.project.customCodexKinds = normalizeCustomCodexKinds(
    (state.project.customCodexKinds || []).filter((kind) => String(kind).toLowerCase() !== name.toLowerCase())
  );
  if (String(state.codexKindFilter).toLowerCase() === name.toLowerCase()) state.codexKindFilter = CODEX_ALL_FILTER;
  setProjectDirty(true);
  renderCharactersPage();
  setStatus(t("Category {name} removed.", { name }));
}

function addCodexTemplateField() {
  const kind = normalizeCodexKindFilter(state.codexKindFilter);
  if (kind === CODEX_ALL_FILTER) return;
  const input = dom.charactersPanel?.querySelector("[data-codex-template-input]");
  const key = String(input?.value || "").trim();
  if (!key) {
    input?.focus?.({ preventScroll: true });
    return;
  }
  if (CODEX_RESERVED_FRONTMATTER_KEYS.has(key.toLowerCase())) {
    setStatus(t("Field name {key} is reserved.", { key }));
    return;
  }
  const templates = normalizeCodexFieldTemplates(state.project.codexFieldTemplates);
  if (templates[kind].some((existing) => existing.toLowerCase() === key.toLowerCase())) {
    setStatus(t("Field {key} already in the template.", { key }));
    return;
  }
  templates[kind] = [...templates[kind], key];
  state.project.codexFieldTemplates = templates;
  let updated = 0;
  getCharacters().forEach((character) => {
    if (character.kind !== kind) return;
    if (applyCodexTemplateToCharacter(character)) updated += 1;
  });
  invalidateCharacterRenderContext();
  setProjectDirty(true);
  renderCharactersPage();
  runAfterRender(() => dom.charactersPanel?.querySelector("[data-codex-template-input]")?.focus?.({ preventScroll: true }));
  setStatus(t("Field {key} added to {count} entries.", { key, count: updated }));
}

function removeCodexTemplateField(keyValue) {
  const kind = normalizeCodexKindFilter(state.codexKindFilter);
  if (kind === CODEX_ALL_FILTER) return;
  const key = String(keyValue || "").trim();
  const templates = normalizeCodexFieldTemplates(state.project.codexFieldTemplates);
  const next = templates[kind].filter((existing) => existing.toLowerCase() !== key.toLowerCase());
  if (next.length === templates[kind].length) return;
  templates[kind] = next;
  state.project.codexFieldTemplates = templates;
  setProjectDirty(true);
  renderCharactersPage();
  setStatus(t("Field {key} removed from the template. Entry values are kept.", { key }));
}

function removeCodexExtraField(id, index) {
  const character = getCharacters().find((item) => item.id === id);
  if (!character) return;
  const fields = normalizeCodexExtraFields(character.extraFields);
  if (!Number.isInteger(index) || index < 0 || index >= fields.length) return;
  fields.splice(index, 1);
  character.extraFields = fields;
  invalidateCharacterRenderContext();
  setProjectDirty(true);
  renderWorkspaceFile();
}

function focusCharacter(id) {
  const character = getCharacters().find((item) => item.id === id);
  if (!character) return;
  state.characterFocusId = id;
  invalidateDocumentSurfaces("characters");
  state.activeFileId = "adventure";
  state.panel = "story";
  renderAll();
  setStatus(`${character.name} focus enabled.`);
}

function openCharacterSearch(id) {
  const character = getCharacters().find((item) => item.id === id);
  if (!character) return;
  state.characterFocusId = null;
  state.codexSelectedEntryId = "";
  state.characterSearch = character.name;
  state.characterSearchIndex = -1;
  resetDocumentRenderLimit("characters");
  state.activeFileId = "characters";
  renderDocumentFileSwitch();
  runAfterRender(() => {
    dom.characterSearchInput?.focus?.({ preventScroll: true });
    dom.charactersPanel?.querySelector(`[data-character-card-id="${CSS.escape(character.id)}"]`)?.scrollIntoView?.({ behavior: "smooth", block: "center" });
  });
  setStatus(t("Search library: {name}", { name: character.name }));
}

function clearCharacterFocus() {
  state.characterFocusId = null;
  invalidateDocumentSurfaces("characters");
  renderAll();
  setStatus("Library focus cleared.");
}

function clearCharacterSearch() {
  state.characterSearch = "";
  resetDocumentRenderLimit("characters");
  if (dom.characterSearchInput) dom.characterSearchInput.value = "";
  renderCharacterGridForSearch();
  setStatus("Library search cleared.");
}

function setCodexKindFilter(value) {
  state.codexKindFilter = normalizeCodexKindFilter(value);
  state.codexTagFilter = "";
  resetDocumentRenderLimit("characters");
  renderCharactersPage();
  setStatus(state.codexKindFilter === CODEX_ALL_FILTER
    ? t("Library category filter cleared.")
    : `${t("Category")}: ${t(state.codexKindFilter)}`);
}

function setCodexTagFilter(value) {
  const tag = normalizeOptionalString(value).trim();
  if (!tag) return clearCodexTagFilter();
  state.codexTagFilter = tag;
  resetDocumentRenderLimit("characters");
  renderCharactersPage();
  setStatus(`${t("Tags")}: ${tag}`);
}

function clearCodexTagFilter() {
  if (!state.codexTagFilter) return;
  state.codexTagFilter = "";
  resetDocumentRenderLimit("characters");
  renderCharactersPage();
  setStatus(t("Library tag filter cleared."));
}

function openCodexEntryDetail(id) {
  const character = getCharacters().find((entry) => entry.id === id);
  if (!character) return;
  state.codexSelectedEntryId = id;
  state.codexImagePickerCharacterId = "";
  renderCharactersPage();
  runAfterRender(() => dom.charactersPanel?.scrollTo?.({ top: 0, behavior: "smooth" }));
  setStatus(t("Open entry: {name}", { name: character.name }));
}

function closeCodexEntryDetail() {
  state.codexSelectedEntryId = "";
  state.codexImagePickerCharacterId = "";
  renderCharactersPage();
  setStatus(t("All entries"));
}

function toggleCharacterBacklinkGroup(characterId, groupId) {
  if (!characterId || !groupId || !getCharacterById(characterId)) return;
  if (!(state.characterBacklinkGroupCollapsedKeys instanceof Set)) {
    state.characterBacklinkGroupCollapsedKeys = new Set();
  }
  const key = getCharacterBacklinkGroupKey(characterId, groupId);
  const expanded = state.characterBacklinkGroupCollapsedKeys.has(key);
  if (expanded) state.characterBacklinkGroupCollapsedKeys.delete(key);
  else state.characterBacklinkGroupCollapsedKeys.add(key);
  renderCharacterGridForSearch();
  runAfterRender(() => {
    const selector = `[data-character-id="${CSS.escape(characterId)}"][data-character-backlink-group="${CSS.escape(groupId)}"]`;
    dom.charactersPanel?.querySelector(selector)?.focus?.({ preventScroll: true });
  });
  setStatus(expanded ? "Library links expanded." : "Library links collapsed.");
}

function addNodeCast() {
  const node = getNode(state.selectedNodeId);
  if (!node) return;
  const characterId = dom.nodePanel?.querySelector("[data-cast-entry-context='new']")?.dataset?.castEntryId || "";
  if (!characterId) {
    setStatus("Select a library entry first.");
    return;
  }
  const codexEntry = getCharacterById(characterId);
  if (!codexEntry) return;
  const requestedRole = dom.nodePanel?.querySelector("[data-new-cast-role]")?.value;
  const allowedRoles = getCodexRelationsForEntry(characterId);
  const role = allowedRoles.includes(requestedRole) ? requestedRole : getDefaultCodexRelation(codexEntry);
  const cast = normalizeNodeCast(node.cast);
  if (!cast.some((entry) => entry.characterId === characterId && entry.role === role)) {
    cast.push({ characterId, role });
  }
  node.cast = cast;
  renderCharacterAwareSurfaces(node);
  setStatus("Library reference added.");
}

function deleteNodeCast(index) {
  const node = getNode(state.selectedNodeId);
  if (!node || !Number.isInteger(index)) return;
  const cast = normalizeNodeCast(node.cast);
  if (index < 0 || index >= cast.length) return;
  cast.splice(index, 1);
  if (cast.length) node.cast = cast;
  else delete node.cast;
  renderCharacterAwareSurfaces(node);
  setStatus("Library reference removed.");
}

function setNodeCastField(index, field, value, rerender) {
  const node = getNode(state.selectedNodeId);
  if (!node || !Number.isInteger(index)) return;
  const cast = normalizeNodeCast(node.cast);
  const entry = cast[index];
  if (!entry) return;
  if (field === "characterId") {
    const codexEntry = getCharacterById(value);
    if (!codexEntry) return;
    entry.characterId = value;
    if (!getCodexRelationsForEntry(value).includes(entry.role)) {
      entry.role = getDefaultCodexRelation(codexEntry);
    }
  }
  if (field === "role") {
    const normalizedRole = normalizeCastRole(value);
    if (!getCodexRelationsForEntry(entry.characterId, entry.role).includes(normalizedRole)) return;
    entry.role = normalizedRole;
  }
  node.cast = normalizeNodeCast(cast);
  setProjectDirty(true);
  renderCharacterAwareSurfaces(rerender ? node : null);
}

function moveNodeCastReference(fromIndex, targetIndex, placement = "before") {
  const node = getNode(state.selectedNodeId);
  if (!node || !Number.isInteger(fromIndex) || !Number.isInteger(targetIndex)) return false;
  const cast = normalizeNodeCast(node.cast);
  if (fromIndex < 0 || fromIndex >= cast.length || targetIndex < 0 || targetIndex >= cast.length || fromIndex === targetIndex) return false;
  const insertionBeforeRemoval = targetIndex + (placement === "after" ? 1 : 0);
  const [entry] = cast.splice(fromIndex, 1);
  const insertionIndex = clamp(insertionBeforeRemoval - (fromIndex < insertionBeforeRemoval ? 1 : 0), 0, cast.length);
  if (insertionIndex === fromIndex) return false;
  cast.splice(insertionIndex, 0, entry);
  node.cast = cast;
  setProjectDirty(true);
  renderCharacterAwareSurfaces(node);
  setStatus("Library references reordered.");
  return true;
}

function renderCharacterAwareSurfaces(nodeForPanel = null) {
  invalidateCharacterRenderContext();
  if (isCanvasFileActive()) {
    renderNodes();
    renderLinks();
    markCanvasSurfaceRendered();
  }
  renderStoryPanel();
  renderProjectPanel();
  renderWorkspaceFile();
  updateStatus();
  if (nodeForPanel) renderNodePanel(nodeForPanel);
}

function beginNodeTitleReferenceEdit(target) {
  const dataset = target?.dataset || {};
  const isNodeTitle = dataset.nodeField === "title";
  const isInlineTitle = dataset.inlineNodeField === "title";
  if (!isNodeTitle && !isInlineTitle) return;
  const nodeId = isInlineTitle ? dataset.nodeId : state.selectedNodeId;
  const node = getNode(nodeId);
  if (!node) return;
  if (state.pendingNodeTitleEdit?.nodeId === node.id) return;
  state.pendingNodeTitleEdit = {
    nodeId: node.id,
    previousTitle: normalizeOptionalString(node.title).trim()
  };
}

function finishNodeTitleReferenceEdit(target) {
  const pending = state.pendingNodeTitleEdit;
  if (!pending) return;
  const dataset = target?.dataset || {};
  const isNodeTitle = dataset.nodeField === "title" && state.selectedNodeId === pending.nodeId;
  const isInlineTitle = dataset.inlineNodeField === "title" && dataset.nodeId === pending.nodeId;
  if (!isNodeTitle && !isInlineTitle) return;
  state.pendingNodeTitleEdit = null;
  const node = getNode(pending.nodeId);
  if (!node) return;
  const previousTitle = normalizeOptionalString(pending.previousTitle).trim();
  const nextTitle = normalizeOptionalString(node.title).trim();
  if (!previousTitle || !nextTitle || previousTitle === nextTitle) return;
  const refs = collectNodeTargetReferences({ titles: [previousTitle], includeIds: false });
  if (!refs.length) return;
  showGenericConfirm({
    kicker: "References",
    title: t('Update references to "{title}"?', { title: nextTitle }),
    message: t('{references} currently target "{previousTitle}". Update them to "{nextTitle}"? Cancel keeps the old target text.', {
      references: formatReferenceSummary(refs),
      previousTitle,
      nextTitle
    }),
    confirmLabel: "Update references",
    danger: false,
    recordHistory: true,
    onConfirm: () => {
      updateNodeTargetReferences({ titles: [previousTitle], replacement: nextTitle });
      renderAll();
      setStatus(t("Updated {count} references.", { count: refs.length }));
    }
  });
}

function collectNodeTargetReferences({ ids = [], titles = [], includeIds = true } = {}) {
  const targets = new Set([
    ...(includeIds ? ids : []),
    ...titles
  ].map((value) => normalizeOptionalString(value).trim()).filter(Boolean));
  if (!targets.size) return [];
  const refs = [];
  getPlaybookActions().forEach((action) => {
    const value = normalizeOptionalString(action.target).trim();
    if (targets.has(value)) refs.push({ kind: "playbookAction", actionId: action.id, label: `Script action ${action.id || ""}`.trim(), value });
  });
  state.project.nodes.forEach((node) => {
    const routing = normalizeNodeRouting(node.routing);
    const value = normalizeOptionalString(routing.target).trim();
    if (routing.mode === "goTo" && targets.has(value)) {
      refs.push({ kind: "nodeRouting", nodeId: node.id, label: `${node.title || getNodeDisplayId(node)} routing`, value });
    }
  });
  const rules = getRunnerRules();
  const startValue = normalizeOptionalString(rules.startNode?.value).trim();
  if (targets.has(startValue)) refs.push({ kind: "runnerStart", label: "Play Rule start node", value: startValue });
  return refs;
}

function updateNodeTargetReferences({ ids = [], titles = [], replacement = "" } = {}) {
  const targets = new Set([...ids, ...titles].map((value) => normalizeOptionalString(value).trim()).filter(Boolean));
  if (!targets.size) return 0;
  const nextValue = normalizeOptionalString(replacement).trim();
  let changed = 0;
  const actions = getPlaybookActions();
  actions.forEach((action) => {
    if (targets.has(normalizeOptionalString(action.target).trim())) {
      action.target = nextValue;
      changed += 1;
    }
  });
  state.project.nodes.forEach((node) => {
    const routing = normalizeNodeRouting(node.routing);
    if (routing.mode === "goTo" && targets.has(normalizeOptionalString(routing.target).trim())) {
      if (nextValue) node.routing = { ...routing, target: nextValue };
      else delete node.routing;
      changed += 1;
    }
  });
  const rules = getRunnerRules();
  if (rules.startNode && targets.has(normalizeOptionalString(rules.startNode.value).trim())) {
    rules.startNode = { ...rules.startNode, value: nextValue || getDefaultStartNodeTarget() };
    changed += 1;
  }
  state.project.script = normalizeScriptConfig({ ...state.project.script, actions, playRules: rules });
  if (changed) setProjectDirty(true);
  return changed;
}

function removeNodeTargetReferences(nodeIds) {
  return updateNodeTargetReferences({ ...getDeletionReferenceTargets(nodeIds), replacement: "" });
}

function getDefaultStartNodeTarget() {
  const entry = state.project.nodes.find((node) => node.type === "Entry") || state.project.nodes[0];
  return entry?.title || entry?.id || "";
}

function getDeletionReferenceTargets(nodeIds) {
  const idSet = new Set((nodeIds || []).map((id) => normalizeOptionalString(id).trim()).filter(Boolean));
  const nodes = [...idSet].map(getNode).filter(Boolean);
  const remainingTitles = new Set(state.project.nodes
    .filter((node) => !idSet.has(node.id))
    .map((node) => normalizeOptionalString(node.title).trim())
    .filter(Boolean));
  const titles = nodes
    .map((node) => normalizeOptionalString(node.title).trim())
    .filter((title) => title && !remainingTitles.has(title));
  return {
    ids: nodes.map((node) => node.id),
    titles
  };
}

function formatReferenceSummary(refs) {
  const total = refs.length;
  const byKind = refs.reduce((map, ref) => {
    map[ref.kind] = (map[ref.kind] || 0) + 1;
    return map;
  }, {});
  const parts = [
    byKind.playbookAction ? t("{count} Script Builder actions", { count: byKind.playbookAction }) : "",
    byKind.nodeRouting ? t("{count} node routing targets", { count: byKind.nodeRouting }) : "",
    byKind.runnerStart ? t("1 Play Rule start node") : ""
  ].filter(Boolean);
  if (!parts.length) return t("{count} references", { count: total });
  return t("{count} references ({parts})", {
    count: total,
    parts: parts.join(state.language === "zh" ? "，" : ", ")
  });
}

function getEditableNodeStateLogic(node = getNode(state.selectedNodeId)) {
  if (!node) return null;
  node.stateLogic = normalizeNodeStateLogic(node.stateLogic);
  return node.stateLogic;
}

function setNodeLogicField(field, value, rerender) {
  const node = getNode(state.selectedNodeId);
  const logic = getEditableNodeStateLogic(node);
  if (!node || !logic || isFrameNode(node)) return;
  if (field === "requirements") {
    logic.requirements = normalizeOptionalString(value).trim();
    logic.requirementsMode = getStoredConditionModeForExpression(logic.requirements, logic.requirementsMode);
  }
  if (field === "effects") logic.effects = parseNodeEffectsText(value);
  cleanupNodeStateLogic(node);
  setProjectDirty(true);
  updateStatus();
  if (rerender) renderNodePanel(node);
}

function setNodeConditionPart(field, value, conditionIndex, rerender) {
  const node = getNode(state.selectedNodeId);
  const logic = getEditableNodeStateLogic(node);
  if (!node || !logic || isFrameNode(node)) return;
  if (field === "mode") {
    const mode = normalizeStoredConditionGroupMode(value);
    logic.requirementsMode = mode;
    logic.requirements = setConditionExpressionGroupMode(logic.requirements, mode);
  } else {
    logic.requirements = updateConditionExpressionPart(logic.requirements, field, value, conditionIndex);
    logic.requirementsMode = getStoredConditionModeForExpression(logic.requirements, logic.requirementsMode);
  }
  cleanupNodeStateLogic(node);
  setProjectDirty(true);
  updateStatus();
  renderPlaybookSurfaces();
  if (rerender) renderNodePanel(node);
}

function addNodeConditionClause() {
  const node = getNode(state.selectedNodeId);
  const logic = getEditableNodeStateLogic(node);
  if (!node || !logic || isFrameNode(node)) return;
  if (!getDefaultConditionKey()) {
    setStatus(t("State key is required."));
    return;
  }
  logic.requirements = addConditionExpressionClause(logic.requirements, logic.requirementsMode);
  cleanupNodeStateLogic(node);
  setProjectDirty(true);
  renderNodePanel(node);
  renderPlaybookSurfaces();
  updateStatus();
  setStatus(t("Condition added."));
}

function deleteNodeConditionClause(conditionIndex) {
  const node = getNode(state.selectedNodeId);
  const logic = getEditableNodeStateLogic(node);
  if (!node || !logic || isFrameNode(node)) return;
  logic.requirements = deleteConditionExpressionClause(logic.requirements, conditionIndex);
  logic.requirementsMode = getStoredConditionModeForExpression(logic.requirements, logic.requirementsMode);
  cleanupNodeStateLogic(node);
  setProjectDirty(true);
  renderNodePanel(node);
  renderPlaybookSurfaces();
  updateStatus();
  setStatus(t("Condition deleted."));
}

function showNodeConditionDraft() {
  const node = getNode(state.selectedNodeId);
  if (!node || isFrameNode(node)) return;
  state.nodeConditionDraftNodeId = node.id;
  renderNodePanel(node);
  focusInspectorTarget(`.condition-draft-row[data-draft-id="node"] [data-draft-field="key"]`);
}

function commitNodeConditionDraft(target) {
  const node = getNode(state.selectedNodeId);
  const logic = getEditableNodeStateLogic(node);
  if (!node || !logic || isFrameNode(node)) return;
  const key = getDraftFieldValue(target, "key").trim();
  const op = getDraftFieldValue(target, "op").trim();
  const value = getDraftFieldValue(target, "value").trim();
  if (!key) {
    setStatus(t("State key is required."));
    return;
  }
  if (conditionOperatorNeedsValue(op) && !value) {
    setStatus(t("Condition value is required."));
    return;
  }
  const condition = buildConditionExpressionFromParts({ key, op, value });
  if (!condition) {
    setStatus(t("Condition expression is empty."));
    return;
  }
  logic.requirements = appendConditionExpression(logic.requirements, condition, logic.requirementsMode);
  node.stateLogic = logic;
  state.nodeConditionDraftNodeId = "";
  cleanupNodeStateLogic(node);
  setProjectDirty(true);
  renderNodePanel(node);
  renderPlaybookSurfaces();
  updateStatus();
  setStatus(t("Condition added."));
}

function showNodeEffectDraft() {
  const node = getNode(state.selectedNodeId);
  if (!node || isFrameNode(node)) return;
  state.nodeEffectDraftNodeId = node.id;
  renderNodePanel(node);
  focusInspectorTarget(`.effect-draft-row[data-draft-id="node"] [data-draft-field="key"]`);
}

function commitNodeEffectDraft(target) {
  const node = getNode(state.selectedNodeId);
  const logic = getEditableNodeStateLogic(node);
  if (!node || !logic || isFrameNode(node)) return;
  const effect = normalizeStateEffectForVariableSchema(getDraftEffectValue(target, "onVisit"));
  if (!effect.key && effect.op !== "clear") {
    setStatus(t("State key is required."));
    return;
  }
  if (!getVariableInfoForStateEffect(effect).hasVariable) {
    setStatus(t("Define this key in Variables before this action can run."));
    return;
  }
  logic.effects.push(effect);
  node.stateLogic = logic;
  state.nodeEffectDraftNodeId = "";
  cleanupNodeStateLogic(node);
  setProjectDirty(true);
  renderNodePanel(node);
  renderPlaybookSurfaces();
  updateStatus();
  setStatus(t("Effect added."));
}

function appendConditionExpression(current, addition, mode = "all") {
  const base = normalizeOptionalString(current).trim();
  const next = normalizeOptionalString(addition).trim();
  if (!base) return next;
  if (!next) return base;
  return `${base} ${getConditionConnectorForMode(mode)} ${next}`;
}

function getDraftFieldValue(target, field) {
  const row = target?.closest?.(".logic-draft-row, .playbook-action-draft-row");
  return normalizeOptionalString(row?.querySelector?.(`[data-draft-field="${CSS.escape(field)}"]`)?.value);
}

function syncConditionDraftRow(row, changedField = "") {
  if (!row) return;
  const keyControl = row.querySelector(`[data-draft-field="key"]`);
  const opControl = row.querySelector(`[data-draft-field="op"]`);
  const valueControl = row.querySelector(`[data-draft-field="value"]`);
  const commitButton = row.querySelector(`[data-action^="commit-"]`);
  const key = normalizeOptionalString(keyControl?.value).trim();
  const op = normalizeConditionOperatorForKey(key, opControl?.value);
  if (opControl) {
    opControl.disabled = !key;
    if (key && changedField === "key") {
      opControl.innerHTML = renderPlaybookOptionList(getAllowedConditionOperatorsForKey(key), op);
    }
    opControl.value = op;
  }
  const needsValue = Boolean(key && conditionOperatorNeedsValue(op));
  row.classList.toggle("no-condition-value", !needsValue);
  if (commitButton) commitButton.disabled = !key;
  if (!valueControl) return;
  valueControl.hidden = !needsValue;
  valueControl.disabled = !needsValue;
  if (!needsValue) {
    valueControl.value = "";
    return;
  }
  if (changedField === "key" || (changedField === "op" && !valueControl.value.trim())) {
    valueControl.value = getDefaultConditionValue(key, op);
  }
}

function syncEffectDraftRow(row, changedField = "") {
  if (!row) return;
  const keyControl = row.querySelector(`[data-draft-field="key"]`);
  const opControl = row.querySelector(`[data-draft-field="op"]`);
  const valueControl = row.querySelector(`[data-draft-field="value"]`);
  const commitButton = row.querySelector(`[data-action^="commit-"]`);
  const key = normalizeOptionalString(keyControl?.value).trim();
  const requestedOp = normalizePlaybookActionOperation(opControl?.value || "set");
  const { variableInfo, allowedOperations, op } = getEffectOperationOptions(key, requestedOp);
  if (opControl) {
    opControl.disabled = !allowedOperations.length;
    opControl.innerHTML = renderEffectOperationOptions(key, op);
    opControl.value = allowedOperations.length ? op : "";
  }
  if (valueControl && changedField !== "value") {
    const currentValue = changedField === "key"
      ? getDefaultPlaybookActionValueForVariableInfo(variableInfo)
      : getPlaybookActionInputValue(valueControl);
    valueControl.outerHTML = renderPlaybookActionValueField({
      attributes: `data-draft-field="value"`,
      value: currentValue,
      variableInfo,
      op,
      disabled: !allowedOperations.length
    });
  }
  if (commitButton) commitButton.disabled = !key || !allowedOperations.length;
}

function getDraftEffectValue(target, fallbackTrigger = "onVisit") {
  const trigger = getDraftFieldValue(target, "trigger") || fallbackTrigger;
  const op = getDraftFieldValue(target, "op") || "set";
  return {
    trigger: normalizePlaybookActionTrigger(trigger),
    op: normalizePlaybookActionOperation(op),
    key: getDraftFieldValue(target, "key").trim(),
    value: getDraftFieldValue(target, "value")
  };
}

function setNodeRoutingField(field, value, rerender, nodeId = state.selectedNodeId) {
  const node = getNode(nodeId);
  if (!node || isFrameNode(node)) return;
  const routing = normalizeNodeRouting(node.routing);
  const previousMode = routing.mode;
  if (field === "mode") routing.mode = ["continue", "end", "goTo"].includes(value) ? value : "continue";
  if (field === "target") routing.target = normalizeOptionalString(value).trim();
  if (routing.mode !== "goTo") routing.target = "";
  const modeChanged = field === "mode" && previousMode !== routing.mode;
  if (routing.mode === "continue" && !routing.target) delete node.routing;
  else node.routing = routing;
  setProjectDirty(true);
  updateStatus();
  if (rerender || modeChanged) {
    if (state.selectedNodeId === node.id) renderNodePanel(node);
    renderPlaybookSurfaces();
  }
}

function setNodeEffectField(index, field, value, rerender) {
  const node = getNode(state.selectedNodeId);
  const logic = getEditableNodeStateLogic(node);
  if (!node || !logic || isFrameNode(node)) return;
  const effect = logic.effects[index];
  if (!effect) return;
  if (field === "trigger") effect.trigger = normalizePlaybookActionTrigger(value);
  if (field === "op") {
    const nextOp = normalizePlaybookActionOperation(value);
    const allowed = getAllowedPlaybookActionOperationsForVariableInfo(getVariableInfoForStateEffect(effect));
    if (!allowed.some((option) => option.value === nextOp)) {
      setStatus(t("Operation not available for this variable type."));
      if (rerender) renderNodePanel(node);
      return;
    }
    effect.op = nextOp;
  }
  if (field === "key") effect.key = normalizeOptionalString(value).trim();
  if (field === "value") effect.value = normalizeOptionalString(value);
  Object.assign(effect, normalizeStateEffectForVariableSchema(effect));
  cleanupNodeStateLogic(node);
  setProjectDirty(true);
  updateStatus();
  if (rerender) renderNodePanel(node);
}

function addNodeEffect() {
  const node = getNode(state.selectedNodeId);
  const logic = getEditableNodeStateLogic(node);
  if (!node || !logic || isFrameNode(node)) return;
  logic.effects.push({ trigger: "onVisit", op: "set", key: uniqueVariableKey("new_state"), value: "true" });
  node.stateLogic = logic;
  setProjectDirty(true);
  renderNodePanel(node);
  updateStatus();
  setStatus("Effect added.");
}

function deleteNodeEffect(index) {
  const node = getNode(state.selectedNodeId);
  const logic = getEditableNodeStateLogic(node);
  if (!node || !logic || !Number.isInteger(index)) return;
  logic.effects.splice(index, 1);
  cleanupNodeStateLogic(node);
  setProjectDirty(true);
  renderNodePanel(node);
  updateStatus();
  setStatus("Effect deleted.");
}

function cleanupNodeStateLogic(node) {
  const logic = normalizeNodeStateLogic(node.stateLogic);
  logic.effects = logic.effects.filter((effect) => effect.op === "ifElse" || effect.key || effect.op === "clear");
  if (logic.requirements || logic.effects.length) node.stateLogic = logic;
  else delete node.stateLogic;
}

// --- Choice options editor (Phase 3) -----------------------------------------------------------

function getSelectedChoiceNode() {
  const node = getNode(state.selectedNodeId);
  return node && isChoiceNode(node) ? node : null;
}

function toggleChoiceTimer() {
  const node = getSelectedChoiceNode();
  if (!node) return;
  const timer = normalizeChoiceTimer(node.choiceTimer);
  timer.enabled = !timer.enabled;
  if (timer.enabled && !timer.fallbackLinkId) {
    timer.fallbackLinkId = getChoiceOrderedLinks(getOutgoing(node.id))[0]?.id || "";
  }
  node.choiceTimer = timer;
  setProjectDirty(true);
  renderNodePanel(node);
  scheduleOpenPreviewRefresh();
}

function setChoiceTimerField(field, value, rerender = false) {
  const node = getSelectedChoiceNode();
  if (!node) return;
  const timer = normalizeChoiceTimer(node.choiceTimer);
  if (field === "seconds") timer.seconds = normalizeChoiceTimerSeconds(value);
  if (field === "fallbackLinkId") timer.fallbackLinkId = normalizeOptionalString(value).trim();
  node.choiceTimer = timer;
  setProjectDirty(true);
  if (rerender) renderNodePanel(node);
  scheduleOpenPreviewRefresh();
}

function ensureChoiceOptionsArray(node) {
  if (!Array.isArray(node.choiceOptions)) {
    node.choiceOptions = normalizeChoiceOptions(node);
  }
  return node.choiceOptions;
}

function syncChoicesFromOptions(node) {
  if (Array.isArray(node.choiceOptions)) {
    node.choices = node.choiceOptions.map((opt) => opt.label);
  }
  // Drop stale link.choiceOptionId bindings that no longer exist on this node.
  if (Array.isArray(state.project.links)) {
    const idSet = new Set((node.choiceOptions || []).map((opt) => opt.id));
    state.project.links.forEach((link) => {
      if (link.from === node.id && link.choiceOptionId && !idSet.has(link.choiceOptionId)) {
        delete link.choiceOptionId;
      }
    });
  }
}

function formatChoiceOptionEffectsText(option) {
  return normalizeNodeEffects(option?.effects)
    .map((effect) => {
      const key = effect.key || "";
      const value = effect.value ? ` = ${effect.value}` : "";
      return `${effect.op || "set"} ${key}${value}`.trim();
    })
    .join("\n");
}

function parseChoiceOptionEffectsText(value) {
  return parseNodeEffectsText(value).map((effect) => ({
    ...effect,
    trigger: "onChoose"
  }));
}

function setChoiceOptionField(optionId, field, value, rerender) {
  const node = getSelectedChoiceNode();
  if (!node || !optionId) return;
  const options = ensureChoiceOptionsArray(node);
  const option = options.find((opt) => opt.id === optionId);
  if (!option) return;
  if (field === "label") option.label = normalizeOptionalString(value);
  else if (field === "requires") {
    option.requires = normalizeOptionalString(value).trim();
    option.requiresMode = getStoredConditionModeForExpression(option.requires, option.requiresMode);
  }
  else if (field === "effects") option.effects = parseChoiceOptionEffectsText(value);
  else return;
  syncChoicesFromOptions(node);
  setProjectDirty(true);
  updateStatus();
  if (field === "label") renderNodes();
  if (rerender) renderNodePanel(node);
  if (state.activeFileId === "variables") renderPlaybookSurfaces();
}

function setCanvasChoiceOptionLabel(nodeId, optionId, optionIndex, value, rerender) {
  const node = getNode(nodeId);
  if (!node || !isChoiceNode(node)) return;
  const options = ensureChoiceOptionsArray(node);
  const option = (optionId ? options.find((entry) => entry.id === optionId) : null)
    || (Number.isInteger(optionIndex) ? options[optionIndex] : null);
  if (!option) return;
  option.label = normalizeOptionalString(value);
  syncChoicesFromOptions(node);
  syncChoiceBranchLinksForNode(node.id, { markDirty: false });
  setProjectDirty(true);
  updateStatus();
  if (!rerender) return;
  renderNodes();
  renderLinks();
  if (state.selectedNodeId === node.id && state.panel === "node") renderNodePanel(node);
  scheduleStoryPanelRender();
}

function setCanvasDialogTurnField(nodeId, index, field, value, rerender) {
  const node = getNode(nodeId);
  if (!node || !isDialogNode(node) || !Number.isInteger(index)) return;
  const turns = ensureDialogTurns(node);
  const turn = turns[index];
  if (!turn) return;
  if (field === "speaker") turn.speaker = normalizeOptionalString(value).trim();
  else if (field === "line") turn.line = normalizeOptionalString(value);
  else return;
  syncDialogBodyFromTurns(node);
  setProjectDirty(true);
  updateStatus();
  if (!rerender) return;
  renderNodes();
  if (state.selectedNodeId === node.id && state.panel === "node") renderNodePanel(node);
  scheduleStoryPanelRender();
}

function setChoiceOptionConditionPart(optionId, field, value, conditionIndex, rerender) {
  const node = getSelectedChoiceNode();
  if (!node || !optionId) return;
  const options = ensureChoiceOptionsArray(node);
  const option = options.find((opt) => opt.id === optionId);
  if (!option) return;
  if (field === "mode") {
    option.requiresMode = normalizeStoredConditionGroupMode(value);
    option.requires = setConditionExpressionGroupMode(option.requires || "", option.requiresMode);
  } else {
    option.requires = updateConditionExpressionPart(option.requires || "", field, value, conditionIndex);
    option.requiresMode = getStoredConditionModeForExpression(option.requires, option.requiresMode);
  }
  syncChoicesFromOptions(node);
  setProjectDirty(true);
  updateStatus();
  if (rerender) renderNodePanel(node);
  if (state.activeFileId === "variables") renderPlaybookSurfaces();
}

function addChoiceOptionCondition(optionId) {
  const node = getSelectedChoiceNode();
  if (!node || !optionId) return;
  const option = ensureChoiceOptionsArray(node).find((opt) => opt.id === optionId);
  if (!option) return;
  if (!getDefaultConditionKey()) {
    setStatus(t("State key is required."));
    return;
  }
  if (!(state.choiceConditionDraftIds instanceof Set)) state.choiceConditionDraftIds = new Set();
  state.choiceConditionDraftIds.add(optionId);
  setChoiceOptionConditionExpanded(optionId, true);
  renderNodePanel(node);
  focusInspectorTarget(`.condition-draft-row[data-draft-id="${CSS.escape(optionId)}"] [data-draft-field="key"]`);
}

function commitChoiceOptionConditionDraft(target) {
  const node = getSelectedChoiceNode();
  if (!node) return;
  const optionId = target?.closest?.("[data-draft-id]")?.dataset?.draftId || "";
  if (!optionId) return;
  const option = ensureChoiceOptionsArray(node).find((opt) => opt.id === optionId);
  if (!option) return;
  const key = getDraftFieldValue(target, "key").trim();
  const op = getDraftFieldValue(target, "op").trim();
  const value = getDraftFieldValue(target, "value").trim();
  if (!key) {
    setStatus(t("State key is required."));
    return;
  }
  if (conditionOperatorNeedsValue(op) && !value) {
    setStatus(t("Condition value is required."));
    return;
  }
  const condition = buildConditionExpressionFromParts({ key, op, value });
  if (!condition) {
    setStatus(t("Condition expression is empty."));
    return;
  }
  option.requiresMode = normalizeStoredConditionGroupMode(option.requiresMode);
  option.requires = appendConditionExpression(option.requires || "", condition, option.requiresMode);
  if (state.choiceConditionDraftIds instanceof Set) state.choiceConditionDraftIds.delete(optionId);
  syncChoicesFromOptions(node);
  setProjectDirty(true);
  renderNodePanel(node);
  if (state.activeFileId === "variables") renderPlaybookSurfaces();
  updateStatus();
  setStatus(t("Condition added."));
}

function deleteChoiceOptionCondition(optionId, conditionIndex) {
  const node = getSelectedChoiceNode();
  if (!node || !optionId) return;
  const option = ensureChoiceOptionsArray(node).find((opt) => opt.id === optionId);
  if (!option) return;
  option.requires = deleteConditionExpressionClause(option.requires || "", conditionIndex);
  option.requiresMode = getStoredConditionModeForExpression(option.requires, option.requiresMode);
  syncChoicesFromOptions(node);
  setProjectDirty(true);
  renderNodePanel(node);
  if (state.activeFileId === "variables") renderPlaybookSurfaces();
  updateStatus();
  setStatus(t("Condition deleted."));
}

function updateConditionExpressionPart(expression, field, value, conditionIndex = 0) {
  const model = parseConditionBuilderExpression(expression);
  const clauses = model.custom
    ? [{ key: "", op: "==", value: "true", connector: "&&" }]
    : model.clauses.map((clause) => ({ ...clause }));
  const index = Number.isInteger(conditionIndex) && conditionIndex >= 0 && conditionIndex < clauses.length ? conditionIndex : 0;
  const parts = clauses[index] || clauses[0];
  if (field === "key") {
    parts.key = normalizeOptionalString(value).trim();
    parts.op = normalizeConditionOperatorForKey(parts.key, parts.op);
    if (!parts.key || !conditionOperatorNeedsValue(parts.op)) {
      parts.value = "";
    } else if (!parts.value) {
      parts.value = getDefaultConditionValue(parts.key, parts.op);
    }
  } else if (field === "op") {
    parts.op = normalizeConditionOperatorForKey(parts.key, value);
    if (!conditionOperatorNeedsValue(parts.op)) {
      parts.value = "";
    } else if (!parts.value) {
      parts.value = getDefaultConditionValue(parts.key, parts.op);
    }
  } else if (field === "value") {
    parts.value = normalizeOptionalString(value);
  } else if (field === "connector") {
    parts.connector = normalizeConditionConnector(value);
  } else {
    return normalizeOptionalString(expression).trim();
  }
  clauses[index] = parts;
  return buildConditionExpressionFromClauses(clauses);
}

function addChoiceOption() {
  const node = getSelectedChoiceNode();
  if (!node) return;
  const options = ensureChoiceOptionsArray(node);
  const used = new Set(options.map((opt) => opt.id));
  const id = generateChoiceOptionId(used);
  const newOption = { id, label: t("New choice"), requires: "", requiresMode: "all", effects: [] };
  options.push(newOption);
  syncChoicesFromOptions(node);
  setProjectDirty(true);
  renderNodePanel(node);
  renderNodes();
  renderLinks();
  updateStatus();
  setStatus("Choice option added.");
  focusInspectorTarget(`[data-choice-option-id="${id}"][data-choice-option-focus-target="label"]`);
}

function deleteChoiceOption(optionId) {
  const node = getSelectedChoiceNode();
  if (!node || !optionId) return;
  const options = ensureChoiceOptionsArray(node);
  const index = options.findIndex((opt) => opt.id === optionId);
  if (index < 0) return;
  options.splice(index, 1);
  setChoiceOptionConditionExpanded(optionId, false);
  setChoiceOptionExpanded(optionId, false);
  syncChoicesFromOptions(node);
  setProjectDirty(true);
  renderNodePanel(node);
  renderNodes();
  renderLinks();
  updateStatus();
  setStatus("Choice option deleted.");
}

function moveChoiceOption(optionId, delta) {
  const node = getSelectedChoiceNode();
  if (!node || !optionId || !Number.isFinite(delta)) return;
  const options = ensureChoiceOptionsArray(node);
  const index = options.findIndex((opt) => opt.id === optionId);
  if (index < 0) return;
  const target = index + delta;
  if (target < 0 || target >= options.length) return;
  const [moved] = options.splice(index, 1);
  options.splice(target, 0, moved);
  syncChoicesFromOptions(node);
  setProjectDirty(true);
  renderNodePanel(node);
  renderNodes();
  renderLinks();
}

function addChoiceOptionEffect(optionId) {
  const node = getSelectedChoiceNode();
  if (!node || !optionId) return;
  const option = ensureChoiceOptionsArray(node).find((opt) => opt.id === optionId);
  if (!option) return;
  if (!(state.choiceEffectDraftIds instanceof Set)) state.choiceEffectDraftIds = new Set();
  state.choiceEffectDraftIds.add(optionId);
  setChoiceOptionExpanded(optionId, true);
  renderNodePanel(node);
  focusInspectorTarget(`.effect-draft-row[data-draft-id="${CSS.escape(optionId)}"] [data-draft-field="key"]`);
}

function commitChoiceOptionEffectDraft(target) {
  const node = getSelectedChoiceNode();
  if (!node) return;
  const optionId = target?.closest?.("[data-draft-id]")?.dataset?.draftId || "";
  if (!optionId) return;
  const option = ensureChoiceOptionsArray(node).find((opt) => opt.id === optionId);
  if (!option) return;
  const effect = normalizeStateEffectForVariableSchema(getDraftEffectValue(target, "onChoose"));
  effect.trigger = "onChoose";
  if (!effect.key && effect.op !== "clear") {
    setStatus(t("State key is required."));
    return;
  }
  if (!getVariableInfoForStateEffect(effect).hasVariable) {
    setStatus(t("Define this key in Variables before this action can run."));
    return;
  }
  if (!Array.isArray(option.effects)) option.effects = [];
  option.effects.push(effect);
  if (state.choiceEffectDraftIds instanceof Set) state.choiceEffectDraftIds.delete(optionId);
  setProjectDirty(true);
  renderNodePanel(node);
  if (state.activeFileId === "variables") renderPlaybookSurfaces();
  updateStatus();
  setStatus(t("Effect added."));
}

function deleteChoiceOptionEffect(optionId, effectIndex) {
  const node = getSelectedChoiceNode();
  if (!node || !optionId || !Number.isInteger(effectIndex)) return;
  const option = ensureChoiceOptionsArray(node).find((opt) => opt.id === optionId);
  if (!option || !Array.isArray(option.effects)) return;
  option.effects.splice(effectIndex, 1);
  setProjectDirty(true);
  renderNodePanel(node);
  if (state.activeFileId === "variables") renderPlaybookSurfaces();
  updateStatus();
  setStatus("Effect deleted.");
}

function setChoiceOptionEffectField(optionId, effectIndex, field, value, rerender) {
  const node = getSelectedChoiceNode();
  if (!node || !optionId || !Number.isInteger(effectIndex)) return;
  const option = ensureChoiceOptionsArray(node).find((opt) => opt.id === optionId);
  if (!option || !Array.isArray(option.effects)) return;
  const effect = option.effects[effectIndex];
  if (!effect) return;
  if (field === "op") {
    const nextOp = normalizePlaybookActionOperation(value);
    const allowed = getAllowedPlaybookActionOperationsForVariableInfo(getVariableInfoForStateEffect(effect));
    if (!allowed.some((item) => item.value === nextOp)) {
      setStatus(t("Operation not available for this variable type."));
      if (rerender) renderNodePanel(node);
      return;
    }
    effect.op = nextOp;
  }
  else if (field === "key") effect.key = normalizeOptionalString(value).trim();
  else if (field === "value") effect.value = normalizeOptionalString(value);
  else return;
  Object.assign(effect, normalizeStateEffectForVariableSchema({ ...effect, trigger: "onChoose" }));
  effect.trigger = "onChoose";
  setProjectDirty(true);
  updateStatus();
  if (rerender) renderNodePanel(node);
  if (state.activeFileId === "variables") renderPlaybookSurfaces();
}

// --- Dialog turns editor (Phase 3) -------------------------------------------------------------

function getSelectedDialogNode() {
  const node = getNode(state.selectedNodeId);
  return node && isDialogNode(node) ? node : null;
}

function ensureDialogTurns(node) {
  if (!Array.isArray(node.turns)) node.turns = [];
  return node.turns;
}

function syncDialogBodyFromTurns(node) {
  if (!Array.isArray(node.turns) || !node.turns.length) return;
  // Mirror turns into body so legacy renderers that only read `body` see something coherent.
  node.body = node.turns.map((turn) => {
    const speaker = String(turn.speaker || "").trim();
    const line = String(turn.line || "").trim();
    return speaker ? `${speaker}: ${line}` : line;
  }).join("\n");
  // Auto-fill cast Speaker chips from the unique speakers in turns.
  syncDialogCastFromTurns(node);
}

function makeUniqueNodeTitle(baseTitle, ignoredNodeId = "") {
  const base = normalizeOptionalString(baseTitle).trim() || t("Untitled");
  const used = new Set(state.project.nodes
    .filter((node) => node.id !== ignoredNodeId)
    .map((node) => normalizeOptionalString(node.title).trim().toLocaleLowerCase())
    .filter(Boolean));
  if (!used.has(base.toLocaleLowerCase())) return base;
  let suffix = 2;
  while (used.has(`${base} ${suffix}`.toLocaleLowerCase())) suffix += 1;
  return `${base} ${suffix}`;
}

function syncSplitDialogCast(node, sourceCast) {
  const nonSpeakerCast = (Array.isArray(sourceCast) ? sourceCast : [])
    .filter((entry) => entry?.role !== "Speaker")
    .map((entry) => cloneProject(entry));
  const characterByName = new Map(getCastCharacters().map((character) => [character.name, character]));
  const speakerIds = new Set();
  (node.turns || []).forEach((turn) => {
    const character = characterByName.get(normalizeOptionalString(turn.speaker).trim());
    if (character) speakerIds.add(character.id);
  });
  const cast = [
    ...nonSpeakerCast,
    ...[...speakerIds].map((characterId) => ({ characterId, role: "Speaker" }))
  ];
  if (cast.length) node.cast = cast;
  else delete node.cast;
}

function splitDialogTurns(index) {
  const node = getSelectedDialogNode();
  if (!node || !Number.isInteger(index)) return;
  const turns = ensureDialogTurns(node);
  if (turns.length < 2 || index < 0 || index >= turns.length - 1) return;

  const sourceId = node.id;
  const sourceCast = cloneProject(Array.isArray(node.cast) ? node.cast : []);
  const sourceLogic = normalizeNodeStateLogic(node.stateLogic);
  const sourceSize = nodeLayoutSize(node);
  const secondNode = cloneProject(node);
  secondNode.id = nextId("n", state.project.nodes);
  secondNode.title = makeUniqueNodeTitle(t("{title} (continued)", {
    title: normalizeOptionalString(node.title).trim() || getNodeTypeLabel(node.type)
  }));
  secondNode.x = Number(node.x || 0) + sourceSize.width + 80;
  secondNode.y = Number(node.y || 0);

  node.turns = cloneProject(turns.slice(0, index + 1));
  secondNode.turns = cloneProject(turns.slice(index + 1));
  syncDialogBodyFromTurns(node);
  syncDialogBodyFromTurns(secondNode);
  syncSplitDialogCast(node, sourceCast);
  syncSplitDialogCast(secondNode, sourceCast);

  node.stateLogic = {
    requirements: sourceLogic.requirements,
    requirementsMode: sourceLogic.requirementsMode,
    effects: sourceLogic.effects.filter((effect) => effect.trigger !== "onChoose")
  };
  secondNode.stateLogic = {
    requirements: "",
    requirementsMode: sourceLogic.requirementsMode,
    effects: sourceLogic.effects.filter((effect) => effect.trigger === "onChoose")
  };
  cleanupNodeStateLogic(node);
  cleanupNodeStateLogic(secondNode);
  delete node.routing;

  state.project.links.forEach((link) => {
    if (link.from === sourceId) link.from = secondNode.id;
  });
  state.project.links.push({
    id: nextId("l", state.project.links),
    from: sourceId,
    to: secondNode.id
  });
  state.project.nodes.push(secondNode);
  invalidateLinkIndexes();
  invalidateCharacterRenderContext();
  clearStoryOrderOverrides();
  clearEventRowOrderOverrides();
  if (secondNode.frameId) expandFrameToFitMembers(getNode(secondNode.frameId));
  markProjectStructureChanged();
  setProjectDirty(true);
  selectNode(secondNode.id);
  setStatus(t("Dialog split into two nodes."));
}

function addDialogTurn() {
  const node = getSelectedDialogNode();
  if (!node) return;
  const turns = ensureDialogTurns(node);
  turns.push({ speaker: "", line: "" });
  syncDialogBodyFromTurns(node);
  setProjectDirty(true);
  renderNodePanel(node);
  renderNodes();
  updateStatus();
  setStatus("Turn added.");
  focusInspectorTarget(`[data-dialog-turn-index="${turns.length - 1}"][data-dialog-turn-focus-target="speaker"]`);
}

function insertDialogTurnAfter(index) {
  const node = getSelectedDialogNode();
  if (!node || !Number.isInteger(index)) return;
  const turns = ensureDialogTurns(node);
  const nextIndex = clamp(index + 1, 0, turns.length);
  turns.splice(nextIndex, 0, { speaker: "", line: "" });
  syncDialogBodyFromTurns(node);
  setProjectDirty(true);
  renderNodePanel(node);
  renderNodes();
  updateStatus();
  setStatus("Turn added.");
  focusInspectorTarget(`[data-dialog-turn-index="${nextIndex}"][data-dialog-turn-focus-target="speaker"]`);
}

function copyDialogTurn(index) {
  const node = getSelectedDialogNode();
  if (!node || !Number.isInteger(index)) return;
  const turns = ensureDialogTurns(node);
  const source = turns[index];
  if (!source) return;
  turns.splice(index + 1, 0, {
    speaker: normalizeOptionalString(source.speaker),
    line: normalizeOptionalString(source.line)
  });
  syncDialogBodyFromTurns(node);
  setProjectDirty(true);
  renderNodePanel(node);
  renderNodes();
  updateStatus();
  setStatus("Turn copied.");
  focusInspectorTarget(`[data-dialog-turn-index="${index + 1}"][data-dialog-turn-field="line"]`);
}

function moveDialogTurn(index, delta) {
  const node = getSelectedDialogNode();
  if (!node || !Number.isInteger(index)) return;
  const turns = ensureDialogTurns(node);
  const nextIndex = index + delta;
  if (!turns[index] || nextIndex < 0 || nextIndex >= turns.length) return;
  const [turn] = turns.splice(index, 1);
  turns.splice(nextIndex, 0, turn);
  syncDialogBodyFromTurns(node);
  setProjectDirty(true);
  renderNodePanel(node);
  renderNodes();
  updateStatus();
  setStatus("Turn moved.");
  focusInspectorTarget(`[data-dialog-turn-index="${nextIndex}"][data-dialog-turn-field="line"]`);
}

function deleteDialogTurn(index) {
  const node = getSelectedDialogNode();
  if (!node || !Number.isInteger(index)) return;
  const turns = ensureDialogTurns(node);
  turns.splice(index, 1);
  if (!turns.length) {
    delete node.turns;
    node.body = "";
  }
  else syncDialogBodyFromTurns(node);
  setProjectDirty(true);
  renderNodePanel(node);
  renderNodes();
  updateStatus();
  setStatus("Turn deleted.");
}

function handleDialogTurnKeyDown(event) {
  const field = event.target?.dataset?.dialogTurnField;
  if (!field || event.key !== "Enter" || !event.shiftKey || event.ctrlKey || event.metaKey || event.altKey) return false;
  const index = Number(event.target.dataset.dialogTurnIndex);
  if (!Number.isInteger(index)) return false;
  event.preventDefault();
  insertDialogTurnAfter(index);
  return true;
}

function setDialogTurnField(index, field, value, rerender) {
  const node = getSelectedDialogNode();
  if (!node || !Number.isInteger(index)) return;
  const turns = ensureDialogTurns(node);
  const turn = turns[index];
  if (!turn) return;
  if (field === "speaker") turn.speaker = normalizeOptionalString(value).trim();
  else if (field === "line") turn.line = normalizeOptionalString(value);
  else return;
  syncDialogBodyFromTurns(node);
  setProjectDirty(true);
  updateStatus();
  renderNodes();
  if (rerender) {
    rerenderNodePanelAfterPointer(node);
  }
}

// Rebuild the node panel, but not while a pointer is pressed inside it: the
// commit-on-blur rerender would otherwise destroy the button under the cursor
// between mousedown and mouseup, swallowing the click (e.g. editing a turn and
// then pressing "Add turn" did nothing).
function rerenderNodePanelAfterPointer(node) {
  const doRender = () => {
    const current = getNode(node.id);
    if (current && state.selectedNodeId === current.id) renderNodePanel(current);
  };
  if (state.nodePanelPointerDown) {
    window.addEventListener("pointerup", () => window.requestAnimationFrame(doRender), { once: true });
    return;
  }
  doRender();
}

function focusInspectorTarget(selector) {
  if (typeof document === "undefined") return;
  runAfterRender(() => {
    const el = dom.nodePanel?.querySelector(selector);
    if (el && typeof el.focus === "function") {
      el.focus();
      if (typeof el.select === "function") el.select();
    }
  });
}

function setScriptNodeField(nodeId, field, value, rerender) {
  const node = getNode(nodeId);
  if (!node || isFrameNode(node)) return;
  if (field === "requirements") {
    node.stateLogic = normalizeNodeStateLogic(node.stateLogic);
    node.stateLogic.requirements = normalizeOptionalString(value).trim();
    node.stateLogic.requirementsMode = getStoredConditionModeForExpression(node.stateLogic.requirements, node.stateLogic.requirementsMode);
    cleanupNodeStateLogic(node);
  } else if (field === "effects") {
    const parsed = parsePlaybookEffectsText(value, { defaultTrigger: "onVisit" });
    const editorStatus = ["ok", "empty", "none"].includes(parsed.status.status)
      ? ""
      : formatPlaybookEditorStatusLabel(parsed.status);
    node.stateLogic = normalizeNodeStateLogic(node.stateLogic);
    node.stateLogic.effects = parseNodeEffectsText(value);
    cleanupNodeStateLogic(node);
    if (editorStatus) setStatus(editorStatus);
  } else if (field === "routingMode") {
    setNodeRoutingField("mode", value, false, nodeId);
  } else if (field === "routingTarget") {
    setNodeRoutingField("target", value, false, nodeId);
  }
  setProjectDirty(true);
  updateStatus();
  if (field === "effects") {
    const parsed = parsePlaybookEffectsText(value, { defaultTrigger: "onVisit" });
    if (!["ok", "empty", "none"].includes(parsed.status.status)) setStatus(formatPlaybookEditorStatusLabel(parsed.status));
  }
  if (state.selectedNodeId === node.id && state.panel === "node") renderNodePanel(node);
}

function setScriptNodeConditionPart(nodeId, field, value, conditionIndex, rerender) {
  const node = getNode(nodeId);
  if (!node || isFrameNode(node)) return;
  node.stateLogic = normalizeNodeStateLogic(node.stateLogic);
  if (field === "mode") {
    node.stateLogic.requirementsMode = normalizeStoredConditionGroupMode(value);
    node.stateLogic.requirements = setConditionExpressionGroupMode(node.stateLogic.requirements, node.stateLogic.requirementsMode);
  } else {
    node.stateLogic.requirements = updateConditionExpressionPart(node.stateLogic.requirements, field, value, conditionIndex);
    node.stateLogic.requirementsMode = getStoredConditionModeForExpression(node.stateLogic.requirements, node.stateLogic.requirementsMode);
  }
  cleanupNodeStateLogic(node);
  setProjectDirty(true);
  updateStatus();
  if (state.selectedNodeId === node.id && state.panel === "node") renderNodePanel(node);
  if (rerender) renderPlaybookSurfaces();
}

function addScriptNodeCondition(nodeId) {
  const node = getNode(nodeId);
  if (!node || isFrameNode(node)) return;
  if (!getDefaultConditionKey()) {
    setStatus(t("State key is required."));
    return;
  }
  node.stateLogic = normalizeNodeStateLogic(node.stateLogic);
  node.stateLogic.requirements = addConditionExpressionClause(node.stateLogic.requirements, node.stateLogic.requirementsMode);
  cleanupNodeStateLogic(node);
  setProjectDirty(true);
  renderPlaybookSurfaces();
  if (state.selectedNodeId === node.id && state.panel === "node") renderNodePanel(node);
  updateStatus();
  setStatus(t("Condition added."));
}

function deleteScriptNodeCondition(nodeId, conditionIndex) {
  const node = getNode(nodeId);
  if (!node || isFrameNode(node)) return;
  node.stateLogic = normalizeNodeStateLogic(node.stateLogic);
  node.stateLogic.requirements = deleteConditionExpressionClause(node.stateLogic.requirements, conditionIndex);
  node.stateLogic.requirementsMode = getStoredConditionModeForExpression(node.stateLogic.requirements, node.stateLogic.requirementsMode);
  cleanupNodeStateLogic(node);
  setProjectDirty(true);
  renderPlaybookSurfaces();
  if (state.selectedNodeId === node.id && state.panel === "node") renderNodePanel(node);
  updateStatus();
  setStatus(t("Condition deleted."));
}

function setGateField(id, field, value, rerender) {
  const parts = String(id || "").split(":");
  const kind = parts[0] || "";
  if (!["condition", "effects"].includes(field)) return;
  const condition = normalizeOptionalString(value).trim();
  if (kind === "node") {
    if (field !== "condition") return;
    const node = getNode(parts[1]);
    if (!node || isFrameNode(node)) return;
    node.stateLogic = normalizeNodeStateLogic(node.stateLogic);
    node.stateLogic.requirements = condition;
    node.stateLogic.requirementsMode = getStoredConditionModeForExpression(condition, node.stateLogic.requirementsMode);
    cleanupNodeStateLogic(node);
  } else if (kind === "choice") {
    const node = getNode(parts[1]);
    const optionId = parts.slice(2).join(":");
    if (!node || !optionId || isFrameNode(node)) return;
    const options = ensureChoiceOptionsArray(node);
    const option = optionId.startsWith("index:")
      ? options[Number(optionId.slice("index:".length))]
      : options.find((item) => item.id === optionId);
    if (!option) return;
    if (field === "condition") {
      option.requires = condition;
      option.requiresMode = getStoredConditionModeForExpression(condition, option.requiresMode);
    } else {
      const parsed = parsePlaybookEffectsText(value, { defaultTrigger: "onChoose", forceTrigger: "onChoose" });
      option.effects = parseChoiceOptionEffectsText(value);
      if (!["ok", "empty", "none"].includes(parsed.status.status)) setStatus(formatPlaybookEditorStatusLabel(parsed.status));
    }
    syncChoicesFromOptions(node);
  } else {
    return;
  }
  setProjectDirty(true);
  updateStatus();
  if (kind === "choice" && field === "effects") {
    const parsed = parsePlaybookEffectsText(value, { defaultTrigger: "onChoose", forceTrigger: "onChoose" });
    if (!["ok", "empty", "none"].includes(parsed.status.status)) setStatus(formatPlaybookEditorStatusLabel(parsed.status));
  }
  if (state.selectedNodeId && state.panel === "node") renderNodePanel(getNode(state.selectedNodeId));
  if (rerender) renderPlaybookSurfaces();
}

function getGateConditionExpression(id) {
  const parts = String(id || "").split(":");
  const kind = parts[0] || "";
  if (kind === "node") {
    const node = getNode(parts[1]);
    return normalizeNodeStateLogic(node?.stateLogic).requirements || "";
  }
  if (kind === "choice") {
    return getChoiceOptionTargetFromGateId(id)?.option?.requires || "";
  }
  return "";
}

function getGateConditionMode(id) {
  const parts = String(id || "").split(":");
  const kind = parts[0] || "";
  if (kind === "node") {
    const node = getNode(parts[1]);
    const logic = normalizeNodeStateLogic(node?.stateLogic);
    return getConditionGroupModeForExpression(logic.requirements, logic.requirementsMode);
  }
  if (kind === "choice") {
    const option = getChoiceOptionTargetFromGateId(id)?.option;
    return getConditionGroupModeForExpression(option?.requires || "", option?.requiresMode);
  }
  return "all";
}

function setGateConditionPart(id, field, value, conditionIndex, rerender) {
  const current = getGateConditionExpression(id);
  if (field === "mode") {
    setGateConditionMode(id, value, rerender);
    return;
  }
  const next = updateConditionExpressionPart(current, field, value, conditionIndex);
  setGateField(id, "condition", next, rerender);
}

function setGateConditionMode(id, value, rerender) {
  const mode = normalizeStoredConditionGroupMode(value);
  const parts = String(id || "").split(":");
  const kind = parts[0] || "";
  const current = getGateConditionExpression(id);
  const next = setConditionExpressionGroupMode(current, mode);
  if (kind === "node") {
    const node = getNode(parts[1]);
    if (!node || isFrameNode(node)) return;
    node.stateLogic = normalizeNodeStateLogic(node.stateLogic);
    node.stateLogic.requirementsMode = mode;
    node.stateLogic.requirements = next;
    cleanupNodeStateLogic(node);
  } else if (kind === "choice") {
    const resolved = getChoiceOptionTargetFromGateId(id);
    if (!resolved) return;
    resolved.option.requiresMode = mode;
    resolved.option.requires = next;
    syncChoicesFromOptions(resolved.node);
  } else {
    return;
  }
  setProjectDirty(true);
  updateStatus();
  if (state.selectedNodeId && state.panel === "node") renderNodePanel(getNode(state.selectedNodeId));
  if (rerender) renderPlaybookSurfaces();
}

function addGateCondition(id) {
  if (!getDefaultConditionKey()) {
    setStatus(t("State key is required."));
    return;
  }
  const mode = getGateConditionMode(id);
  const next = addConditionExpressionClause(getGateConditionExpression(id), mode);
  setGateField(id, "condition", next, true);
  setStatus(t("Condition added."));
}

function deleteGateCondition(id, conditionIndex) {
  const next = deleteConditionExpressionClause(getGateConditionExpression(id), conditionIndex);
  setGateField(id, "condition", next, true);
  setStatus(t("Condition deleted."));
}

function getChoiceOptionTargetFromGateId(id) {
  const parts = String(id || "").split(":");
  if (parts[0] !== "choice") return null;
  const node = getNode(parts[1]);
  const optionId = parts.slice(2).join(":");
  if (!node || !optionId || isFrameNode(node)) return null;
  const options = ensureChoiceOptionsArray(node);
  const option = optionId.startsWith("index:")
    ? options[Number(optionId.slice("index:".length))]
    : options.find((item) => item.id === optionId);
  if (!option) return null;
  return { node, option, optionId };
}

function showPlaybookChoiceEffectDraft(gateId) {
  const target = getChoiceOptionTargetFromGateId(gateId);
  if (!target) return;
  if (!(state.playbookChoiceEffectDraftIds instanceof Set)) state.playbookChoiceEffectDraftIds = new Set();
  state.playbookChoiceEffectDraftIds.add(gateId);
  state.activeFileId = "variables";
  state.playbookTab = "gates";
  renderPlaybookSurfaces();
  runAfterRender(() => {
    const selector = `.effect-draft-row[data-draft-id="${CSS.escape(gateId)}"] [data-draft-field="key"]`;
    const element = dom.variablesPanel?.querySelector(selector);
    element?.focus?.({ preventScroll: true });
  });
}

function commitPlaybookChoiceEffectDraft(target) {
  const gateId = target?.closest?.("[data-draft-id]")?.dataset?.draftId || "";
  const resolved = getChoiceOptionTargetFromGateId(gateId);
  if (!resolved) return;
  const effect = normalizeStateEffectForVariableSchema(getDraftEffectValue(target, "onChoose"));
  effect.trigger = "onChoose";
  if (!effect.key && effect.op !== "clear") {
    setStatus(t("State key is required."));
    return;
  }
  if (!getVariableInfoForStateEffect(effect).hasVariable) {
    setStatus(t("Define this key in Variables before this action can run."));
    return;
  }
  if (!Array.isArray(resolved.option.effects)) resolved.option.effects = [];
  resolved.option.effects.push(effect);
  if (state.playbookChoiceEffectDraftIds instanceof Set) state.playbookChoiceEffectDraftIds.delete(gateId);
  syncChoicesFromOptions(resolved.node);
  setProjectDirty(true);
  renderPlaybookSurfaces();
  if (state.selectedNodeId === resolved.node.id && state.panel === "node") renderNodePanel(resolved.node);
  updateStatus();
  setStatus(t("Effect added."));
}

function setChoiceOptionEffectByGateId(gateId, effectIndex, field, value, rerender) {
  const resolved = getChoiceOptionTargetFromGateId(gateId);
  if (!resolved || !Number.isInteger(effectIndex)) return;
  if (!Array.isArray(resolved.option.effects)) return;
  const effect = resolved.option.effects[effectIndex];
  if (!effect) return;
  if (field === "op") {
    const nextOp = normalizePlaybookActionOperation(value);
    const allowed = getAllowedPlaybookActionOperationsForVariableInfo(getVariableInfoForStateEffect(effect));
    if (!allowed.some((item) => item.value === nextOp)) {
      setStatus(t("Operation not available for this variable type."));
      if (rerender) renderPlaybookSurfaces();
      return;
    }
    effect.op = nextOp;
  }
  else if (field === "key") effect.key = normalizeOptionalString(value).trim();
  else if (field === "value") effect.value = normalizeOptionalString(value);
  else return;
  Object.assign(effect, normalizeStateEffectForVariableSchema({ ...effect, trigger: "onChoose" }));
  effect.trigger = "onChoose";
  syncChoicesFromOptions(resolved.node);
  setProjectDirty(true);
  updateStatus();
  if (state.selectedNodeId === resolved.node.id && state.panel === "node") renderNodePanel(resolved.node);
  if (rerender) renderPlaybookSurfaces();
}

function deletePlaybookChoiceEffect(gateId, effectIndex) {
  const resolved = getChoiceOptionTargetFromGateId(gateId);
  if (!resolved || !Number.isInteger(effectIndex) || !Array.isArray(resolved.option.effects)) return;
  resolved.option.effects.splice(effectIndex, 1);
  syncChoicesFromOptions(resolved.node);
  setProjectDirty(true);
  renderPlaybookSurfaces();
  if (state.selectedNodeId === resolved.node.id && state.panel === "node") renderNodePanel(resolved.node);
  updateStatus();
  setStatus("Effect deleted.");
}

function migrateLegacyGateAction(id) {
  const action = getPlaybookActions().find((item) => item.id === id);
  if (!action || action.trigger !== "gate" || action.op !== "if") return;
  if (!normalizeOptionalString(action.target).trim()) {
    setStatus(t("This legacy gate has no target. Add a target before migrating."));
    return;
  }
  const condition = formatLegacyGateCondition(action);
  const targets = getScriptBuilderNodes().filter((node) => matchesPlaybookActionTarget(action, node));
  if (!targets.length) {
    setStatus(t("No matching node, type, or ID."));
    return;
  }
  targets.forEach((node) => {
    node.stateLogic = normalizeNodeStateLogic(node.stateLogic);
    node.stateLogic.requirements = condition;
    cleanupNodeStateLogic(node);
  });
  const nextActions = getPlaybookActions().filter((item) => item.id !== id);
  state.project.script = normalizeScriptConfig({ ...state.project.script, actions: nextActions });
  state.activeFileId = "variables";
  state.playbookTab = "gates";
  setProjectDirty(true);
  renderPlaybookSurfaces();
  renderNodes();
  renderInspector();
  updateStatus();
  setStatus(t("Legacy gate migrated."));
}

function parseNodeEffectsText(value) {
  return String(value || "")
    .split(/\r?\n/)
    .map((line) => line.trim())
    .filter(Boolean)
    .map((line) => {
      const triggerMatch = line.match(/^\[(onVisit|onChoose)\]\s*(.+)$/i);
      const trigger = triggerMatch ? normalizePlaybookActionTrigger(triggerMatch[1]) : "onVisit";
      const body = triggerMatch ? triggerMatch[2].trim() : line;
      return parseConditionalEffectBody(body, trigger)
        || parseStateEffectBody(body, trigger)
        || { trigger, op: "set", key: body, value: "true", valueMode: "literal" };
    })
    .filter((effect) => effect.op === "ifElse" || effect.key || effect.op === "clear");
}

function formatStateEffectsText(effects, { defaultTrigger = "onVisit" } = {}) {
  const fallbackTrigger = normalizePlaybookActionTrigger(defaultTrigger || "onVisit");
  return (Array.isArray(effects) ? effects : [])
    .map((effect) => {
      if (!effect || typeof effect !== "object" || Array.isArray(effect)) return "";
      const trigger = normalizePlaybookActionTrigger(effect.trigger || fallbackTrigger);
      const prefix = trigger && trigger !== fallbackTrigger ? `[${trigger}] ` : "";
      if (effect.op === "ifElse") {
        const thenText = formatStateEffectBody(effect.thenEffect);
        const elseText = formatStateEffectBody(effect.elseEffect);
        const condition = normalizeOptionalString(effect.condition).trim();
        return condition && thenText && elseText ? `${prefix}if ${condition} then ${thenText} else ${elseText}` : "";
      }
      const op = normalizePlaybookActionOperation(effect.op || "set");
      const key = normalizeOptionalString(effect.key || effect.variable || effect.name).trim();
      const value = normalizeOptionalString(effect.value);
      return key || op === "clear" ? `${prefix}${op} ${key}${value ? ` = ${value}` : ""}`.trim() : "";
    })
    .filter(Boolean)
    .join("\n");
}

function formatStateEffectBody(effect) {
  const op = normalizePlaybookActionOperation(effect?.op || "set");
  const key = normalizeOptionalString(effect?.key || effect?.variable || effect?.name).trim();
  const value = normalizeOptionalString(effect?.value);
  return key || op === "clear" ? `${op} ${key}${value ? ` = ${value}` : ""}`.trim() : "";
}

function formatNodeEffectsText(node) {
  return formatStateEffectsText(normalizeNodeStateLogic(node?.stateLogic).effects, { defaultTrigger: "onVisit" });
}

function renderCharacterListSurfaces() {
  hideNodeContextMenu();
  renderShellState();
  if (state.activeFileId === "characters") {
    renderCharactersPage();
  } else {
    renderWorkspaceFile();
  }
  renderProjectPanel();
  renderStoryPanel();
  updateStatus();
}

function addVariable() {
  const variables = normalizeVariablesObject(state.project.variables);
  const key = uniqueVariableKey("new_variable");
  variables[key] = "";
  state.project.variables = variables;
  state.activeFileId = "variables";
  state.playbookTab = "variables";
  state.playbookFocusTarget = { kind: "variable", id: key, field: "key" };
  setProjectDirty(true);
  renderPlaybookSurfaces();
  setStatus("Variable added.");
}

function showPlaybookActionDraft() {
  const variables = normalizeVariablesObject(state.project.variables);
  if (!Object.keys(variables).length) {
    state.activeFileId = "variables";
    state.playbookTab = "variables";
    renderPlaybookSurfaces();
    setStatus(t("Add a variable definition before adding a variable action."));
    return;
  }
  state.playbookActionDraftOpen = true;
  if (!state.playbookActionDraft) {
    const keys = Object.keys(variables).sort((a, b) => a.localeCompare(b));
    const key = getPreferredVariableKeyForPlaybookAction(keys);
    const variableInfo = getPlaybookActionVariableInfo({ category: "Variable", key });
    state.playbookActionDraft = {
      trigger: "manual",
      target: "",
      key,
      op: getAllowedPlaybookActionOperationsForVariableInfo(variableInfo)[0]?.value || "set",
      value: getDefaultPlaybookActionValueForVariableInfo(variableInfo)
    };
  }
  state.activeFileId = "variables";
  state.playbookTab = "actions";
  renderPlaybookSurfaces();
  runAfterRender(() => {
    const element = dom.variablesPanel?.querySelector(`.playbook-action-draft-row [data-draft-field="target"]`);
    element?.focus?.({ preventScroll: true });
  });
}

function commitPlaybookActionDraft(target) {
  const variables = normalizeVariablesObject(state.project.variables);
  const keys = Object.keys(variables).sort((a, b) => a.localeCompare(b));
  if (!keys.length) {
    setStatus(t("Add a variable definition before adding a variable action."));
    return;
  }
  syncPlaybookActionDraftFromRow(target?.closest?.(".playbook-action-draft-row"));
  const draft = normalizePlaybookActionDraft();
  const actions = getPlaybookActions();
  const key = draft.key || getPreferredVariableKeyForPlaybookAction(keys);
  const info = getPlaybookActionVariableInfo({ category: "Variable", key });
  if (!info.hasVariable) {
    setStatus(t("State key is required."));
    return;
  }
  const allowed = getAllowedPlaybookActionOperationsForVariableInfo(info);
  const requestedOp = normalizePlaybookActionOperation(draft.op || "set");
  const op = allowed.some((option) => option.value === requestedOp) ? requestedOp : (allowed[0]?.value || "set");
  const action = normalizePlaybookActionForVariableSchema({
    id: uniquePlaybookActionId(actions),
    trigger: normalizePlaybookActionTrigger(draft.trigger || "manual"),
    target: normalizeOptionalString(draft.target).trim(),
    op,
    category: "Variable",
    key,
    value: draft.value
  });
  actions.push(action);
  state.project.script = normalizeScriptConfig({ ...state.project.script, actions });
  state.playbookActionDraftOpen = false;
  state.playbookActionDraft = null;
  state.activeFileId = "variables";
  state.playbookTab = "actions";
  state.playbookFocusTarget = { kind: "action", id: action.id, field: "target" };
  setProjectDirty(true);
  renderPlaybookSurfaces();
  updateStatus();
  setStatus(t("Variable action added."));
}

function togglePlaybookJson() {
  state.playbookJsonOpen = !state.playbookJsonOpen;
  state.activeFileId = "variables";
  renderPlaybookSurfaces();
  setStatus(state.playbookJsonOpen ? "Advanced JSON shown." : "Advanced JSON hidden.");
}

function selectPlaybookTab(tab) {
  state.playbookTab = getValidPlaybookTab(tab);
  state.activeFileId = "variables";
  renderPlaybookSurfaces();
}

function togglePlaybookRuleHelp(ruleId) {
  if (!ruleId) return;
  if (state.playbookRuleHelpOpenIds.has(ruleId)) state.playbookRuleHelpOpenIds.delete(ruleId);
  else state.playbookRuleHelpOpenIds.add(ruleId);
  state.activeFileId = "variables";
  renderPlaybookSurfaces();
}

function filterPlaybookCategory(category) {
  const validFilters = new Set(formatVariableTypeFilterOptions(createVariableTypeFilterCounts()).map((filter) => filter.value));
  const next = category && validFilters.has(category) ? category : null;
  state.playbookCategoryFilter = next && state.playbookCategoryFilter === next ? null : next;
  state.activeFileId = "variables";
  state.playbookTab = getValidPlaybookTab(state.playbookTab);
  renderPlaybookSurfaces();
}

function showPlaybookJsonAtToken(token) {
  state.playbookJsonOpen = true;
  state.activeFileId = "variables";
  renderPlaybookSurfaces({ focusJsonToken: token });
}

function addPlaybookNodeRule() {
  addPlaybookRule("text");
}

function addPlaybookChoiceRule() {
  addPlaybookRule("choices");
}

function addPlaybookStateRules() {
  addPlaybookRule("state");
}

function addPlaybookRule(kind) {
  const ruleKind = normalizePlaybookRuleKind(kind);
  if (dom.playRuleDialog?.open) dom.playRuleDialog.close();
  const rules = getRunnerRules();
  if (ruleKind === "visitTracking" && !isDebugModeRuleEnabled(rules)) {
    state.activeFileId = "variables";
    state.playbookTab = "rules";
    renderPlaybookSurfaces();
    setStatus(t("Enable Debug Mode before Visit Tracking."));
    return;
  }
  rules[ruleKind] = {
    ...(rules[ruleKind] || getDefaultRunnerRules()[ruleKind]),
    enabled: true
  };
  state.project.script = normalizeScriptConfig({ ...state.project.script, playRules: rules });
  state.activeFileId = "variables";
  // Switch to Rules tab so the user sees what they just added. The Script Builder data is preserved —
  // earlier confusion came from the tab switch making writers think their rows had vanished. Keep the
  // switch but add a focus hint so the new rule visually stands out.
  state.playbookTab = "rules";
  state.playbookFocusTarget = { kind: "runnerRule", id: ruleKind, field: "value" };
  setProjectDirty(true);
  renderPlaybookSurfaces();
  updateStatus();
  setStatus(`${getRunnerRuleTitle(ruleKind)} enabled.`);
}

function normalizePlaybookRuleKind(kind) {
  return ["startNode", "endCondition", "visitTracking", "debugMode"].includes(kind) ? kind : "endCondition";
}

function getRunnerRuleTitle(kind) {
  const labels = {
    startNode: "Start Node",
    endCondition: "End Condition",
    visitTracking: "Visit Tracking",
    debugMode: "Debug Mode"
  };
  return labels[kind] || "Play rule";
}

function deleteVariable(key) {
  const variables = normalizeVariablesObject(state.project.variables);
  if (!key || !Object.prototype.hasOwnProperty.call(variables, key)) return;
  delete variables[key];
  state.project.variables = variables;
  if (!Object.keys(variables).length) {
    state.playbookCategoryFilter = null;
    resetDocumentRenderLimit("variables");
  }
  state.activeFileId = "variables";
  setProjectDirty(true);
  renderPlaybookSurfaces();
  setStatus(`${key} deleted.`);
}

function deletePlaybookAction(id) {
  const actions = getPlaybookActions();
  const nextActions = actions.filter((action) => action.id !== id);
  if (nextActions.length === actions.length) return;
  state.project.script = normalizeScriptConfig({ ...state.project.script, actions: nextActions });
  state.activeFileId = "variables";
  setProjectDirty(true);
  renderPlaybookSurfaces();
  updateStatus();
  setStatus("Variable action deleted.");
}

function deletePlaybookRule(target) {
  const key = String(target || "").trim();
  if (!key) return;
  const rules = getRunnerRules();
  if (!Object.prototype.hasOwnProperty.call(rules, key)) return;
  if (key === "startNode") {
    setStatus(`${getRunnerRuleTitle(key)} is a system rule.`);
    return;
  }
  rules[key] = { ...rules[key], enabled: false };
  state.project.script = normalizeScriptConfig({ ...state.project.script, playRules: rules });
  state.activeFileId = "variables";
  setProjectDirty(true);
  renderPlaybookSurfaces();
  updateStatus();
  setStatus(`${getRunnerRuleTitle(key)} disabled.`);
}

function toggleFrameCollapse(nodeId) {
  const node = getNode(nodeId);
  if (!node || !isFrameNode(node)) return;
  node.collapsed = !isFrameCollapsed(node);
  nodeLayoutSizeCache.delete(node);
  state.activeFileId = "adventure";
  setProjectDirty(true);
  renderNodes();
  renderLinks();
  renderStoryPanel();
  updateStatus();
  setStatus(node.collapsed ? "Frame collapsed." : "Frame expanded.");
}

function setPlaybookActionField(id, field, value, rerender) {
  const actions = getPlaybookActions();
  const action = actions.find((item) => item.id === id);
  if (!action) return;
  if (field === "append") return;
  if (field === "trigger") action.trigger = normalizePlaybookActionTrigger(value);
  else if (field === "op") {
    const nextOp = normalizePlaybookActionOperation(value);
    const info = getPlaybookActionVariableInfo(action);
    const allowed = getAllowedPlaybookActionOperationsForVariableInfo(info);
    if (!allowed.some((option) => option.value === nextOp)) {
      setStatus("Operation not available for this variable type.");
      if (rerender) renderPlaybookSurfaces();
      return;
    }
    action.op = nextOp;
  } else if (field === "category") {
    action.category = "Variable";
  } else if (field === "key") {
    action.category = "Variable";
    action.key = normalizeOptionalString(value).trim();
  } else if (["target", "value"].includes(field)) action[field] = normalizeOptionalString(value);
  normalizePlaybookActionForVariableSchema(action);
  state.project.script = normalizeScriptConfig({ ...state.project.script, actions });
  setProjectDirty(true);
  updateStatus();
  if (rerender) renderPlaybookSurfaces();
}

function normalizePlaybookActionForVariableSchema(action, options = {}) {
  const coerceValue = options.coerceValue !== false;
  const info = getPlaybookActionVariableInfo(action);
  if (!info.hasVariable) return action;
  const allowed = getAllowedPlaybookActionOperationsForVariableInfo(info);
  if (!allowed.some((option) => option.value === action.op)) {
    action.op = allowed[0]?.value || "set";
    action.value = getDefaultPlaybookActionValueForVariableInfo(info);
  }
  if (action.op === "toggle") action.value = "";
  else if (coerceValue) action.value = normalizePlaybookActionValueForVariableInfo(action.value, info, action.op);
  return action;
}

function setRunnerRuleField(field, value, rerender) {
  const rules = getRunnerRules();
  if (!rules[field]) return;
  rules[field] = {
    ...rules[field],
    enabled: true,
    value: normalizeRunnerRuleValue(field, value)
  };
  state.project.script = normalizeScriptConfig({ ...state.project.script, playRules: rules });
  setProjectDirty(true);
  updateStatus();
  if (rerender) renderPlaybookSurfaces();
}

function setRunnerRuleEnabled(field, enabled, rerender) {
  const rules = getRunnerRules();
  if (!rules[field]) return;
  if (field === "visitTracking" && enabled && !isDebugModeRuleEnabled(rules)) {
    setStatus(t("Enable Debug Mode before Visit Tracking."));
    if (rerender) renderPlaybookSurfaces();
    return;
  }
  const required = field === "startNode";
  const nextEnabled = required ? true : Boolean(enabled);
  const nextRule = {
    ...rules[field],
    enabled: nextEnabled
  };
  if (nextEnabled && (field === "visitTracking" || field === "debugMode")) nextRule.value = true;
  rules[field] = nextRule;
  if (field === "debugMode" && !nextEnabled && rules.visitTracking) {
    rules.visitTracking = { ...rules.visitTracking, enabled: false };
  }
  state.project.script = normalizeScriptConfig({ ...state.project.script, playRules: rules });
  state.activeFileId = "variables";
  setProjectDirty(true);
  updateStatus();
  if (rerender) renderPlaybookSurfaces();
  setStatus(`${getRunnerRuleTitle(field)} ${nextEnabled ? "enabled" : "disabled"}.`);
}

function getRunnerRuleInputValue(target) {
  if (target?.type === "checkbox") return Boolean(target.checked);
  return target?.value ?? "";
}

function getPlaybookActionInputValue(target) {
  if (target?.type === "checkbox") return Boolean(target.checked);
  return target?.value ?? "";
}

function uniquePlaybookActionId(actions) {
  const used = new Set(actions.map((action) => action.id));
  let index = actions.length;
  while (used.has(`a${index}`)) index += 1;
  return `a${index}`;
}

function setVariableField(key, field, value, rerender) {
  const variables = normalizeVariablesObject(state.project.variables);
  state.project.variables = variables;
  if (!Object.prototype.hasOwnProperty.call(variables, key)) return;

  if (field === "key") {
    const nextKey = value.trim();
    if (!nextKey || (nextKey !== key && Object.prototype.hasOwnProperty.call(variables, nextKey))) {
      setStatus("Variable key already exists.");
      if (rerender) renderWorkspaceFile();
      return;
    }
    if (nextKey !== key) {
      variables[nextKey] = variables[key];
      delete variables[key];
      renameVariableReferences(key, nextKey);
    }
  } else if (field === "type") {
    variables[key] = coerceVariableInput(formatVariableValue(variables[key]), value);
    normalizePlaybookActionsForVariableKey(key);
  } else if (field === "value") {
    variables[key] = coerceVariableInput(value, variableType(variables[key]));
    normalizePlaybookActionsForVariableKey(key);
  }

  state.project.variables = variables;
  setProjectDirty(true);
  renderNodes();
  renderStoryPanel();
  renderProjectPanel();
  updateStatus();
  if (rerender) renderWorkspaceFile();
}

function normalizePlaybookActionsForVariableKey(key) {
  const stateKey = normalizeOptionalString(key).trim();
  if (!stateKey) return;
  const actions = getPlaybookActions();
  let changed = false;
  actions.forEach((action) => {
    if (getPlaybookActionStateKey(action) !== stateKey) return;
    const before = JSON.stringify({ op: action.op, value: action.value });
    normalizePlaybookActionForVariableSchema(action);
    if (before !== JSON.stringify({ op: action.op, value: action.value })) changed = true;
  });
  if (changed) state.project.script = normalizeScriptConfig({ ...state.project.script, actions });
}

function selectNode(id, rerender = true) {
  const node = getNode(id);
  if (state.frameCanvasId && node && !isNodeWithinFrameCanvas(node)) exitFrameCanvas({ render: false });
  state.activeFileId = "adventure";
  state.selectedNodeId = id;
  state.selectedNodeIds = [];
  state.selectedLinkId = null;
  state.panel = "node";
  if (rerender) renderAll();
}

function focusStoryNode(id) {
  const node = getNode(id);
  if (!node) return;
  state.selectedNodeId = id;
  state.selectedLinkId = null;
  state.panel = "story";
  renderAll();
  runAfterRender(() => {
    const found = scrollStoryNodeIntoView(id);
    const label = node.title || getNodeDisplayId(node);
    setStatus(found
      ? `${label} shown in Story.`
      : `${label} is not in Story because it is not on the Entry path.`);
  });
}

function getCanvasSearchMatchIds(query = state.search.trim().toLowerCase()) {
  if (!query) return [];
  return [...getCanvasSearchMatchIdSet(query)];
}

function getCanvasSearchMatchIdSet(query = state.search.trim().toLowerCase()) {
  if (!query) return new Set();
  const matches = new Set();
  const includeCharacterTerms = queryCanMatchCharacterTerms(query);
  state.project.nodes.forEach((node) => {
    if (nodeMatches(node, query, { includeCharacterTerms })) matches.add(node.id);
  });
  return matches;
}

function getCharacterSearchMatchIds(query = (state.characterSearch || "").trim().toLowerCase()) {
  if (!query) return [];
  return getCharacters()
    .filter((character) => characterMatchesSearch(character, query))
    .map((character) => character.id);
}

function getEventSearchMatchIds(query = (state.eventSearch || "").trim().toLowerCase()) {
  if (!query) return [];
  return getEventSheetMatchRowIds(query);
}

function getEventSheetMatchRowIds(query) {
  const ids = [];
  state.project.nodes.forEach((node) => {
    if (!isEventSheetNode(node)) return;
    const haystack = buildEventNodeSearchText(node);
    if (haystack.includes(query)) ids.push(node.id);
  });
  return ids;
}

function buildEventNodeSearchText(node) {
  const cache = getEventSearchTextCache();
  if (cache.has(node.id)) return cache.get(node.id);
  const columns = getEventSheetColumns(node.type) || [];
  const parts = [node.title, getNodeDisplayId(node), getNodeTypeLabel(node.type)];
  columns.forEach((column) => parts.push(String(getNodeEventValue(node, column.key) || "")));
  const text = parts.filter(Boolean).join("\n").toLowerCase();
  cache.set(node.id, text);
  return text;
}

function getEventSearchTextCache() {
  const cached = state.derived.eventSearchText;
  if (cached?.dirtyVersion === state.dirtyVersion && cached?.structureVersion === state.structureVersion) return cached.map;
  const map = new Map();
  state.derived.eventSearchText = { dirtyVersion: state.dirtyVersion, structureVersion: state.structureVersion, map };
  return map;
}

function getPlaybookSearchMatchOffsets(query = (state.playbookSearch || "").trim().toLowerCase()) {
  if (!query) return [];
  const text = (buildVariablesJson() || "").toLowerCase();
  const offsets = [];
  let from = 0;
  while (from <= text.length - query.length) {
    const idx = text.indexOf(query, from);
    if (idx < 0) break;
    offsets.push(idx);
    from = idx + Math.max(1, query.length);
  }
  return offsets;
}

function getSearchScopeInfo(scope = state.activeFileId) {
  switch (scope) {
    case "adventure": {
      const matches = getCanvasSearchMatchIds();
      return { scope, matches, indexKey: "searchIndex" };
    }
    case "characters": {
      const matches = getCharacterSearchMatchIds();
      return { scope, matches, indexKey: "characterSearchIndex" };
    }
    case "events": {
      const matches = getEventSearchMatchIds();
      return { scope, matches, indexKey: "eventSearchIndex" };
    }
    case "variables": {
      const matches = getPlaybookSearchMatchOffsets();
      return { scope, matches, indexKey: "playbookSearchIndex" };
    }
    case "document": {
      const matches = getDocumentSearchMatchOffsets();
      return { scope, matches, indexKey: "documentSearchIndex" };
    }
    default:
      return { scope, matches: [], indexKey: null };
  }
}

function refreshWorkspaceSearchCount() {
  if (!dom.matchCount) return;
  const info = getSearchScopeInfo();
  const total = info.matches.length;
  const rawIndex = info.indexKey ? state[info.indexKey] : -1;
  const oneBased = rawIndex >= 0 && rawIndex < total ? rawIndex + 1 : 0;
  dom.matchCount.textContent = `${oneBased} / ${total}`;
}

function cycleSearchScope(scope) {
  const info = getSearchScopeInfo(scope);
  if (!info.matches.length || !info.indexKey) {
    refreshWorkspaceSearchCount();
    return;
  }
  const current = state[info.indexKey];
  const nextIndex = current >= 0 ? (current + 1) % info.matches.length : 0;
  state[info.indexKey] = nextIndex;
  focusSearchMatch(scope, info.matches[nextIndex]);
  refreshWorkspaceSearchCount();
}

function focusSearchMatch(scope, match) {
  if (scope === "adventure") {
    focusCanvasNode(match);
    return;
  }
  if (scope === "characters") {
    focusCharacter(match);
    runAfterRender(() => {
      const card = dom.charactersPanel?.querySelector(`[data-character-card-id="${CSS.escape(match)}"]`);
      if (card?.scrollIntoView) card.scrollIntoView({ behavior: "smooth", block: "center" });
    });
    return;
  }
  if (scope === "events") {
    runAfterRender(() => {
      const row = dom.eventsPanel?.querySelector(`[data-event-row-id="${CSS.escape(match)}"]`);
      if (row?.scrollIntoView) row.scrollIntoView({ behavior: "smooth", block: "center" });
    });
    return;
  }
  if (scope === "variables") {
    focusPlaybookJsonAtOffset(match);
    return;
  }
  if (scope === "document") {
    focusDocumentSearchMatch(match);
  }
}

function focusPlaybookJsonAtOffset(offset) {
  const wasOpen = state.playbookJsonOpen;
  state.playbookJsonOpen = true;
  if (!wasOpen) renderVariablesPage();
  const searchInput = dom.playbookSearchInput;
  const restoreSearchFocus = getScopeActiveElement() === searchInput;
  const searchCaretStart = restoreSearchFocus ? searchInput.selectionStart : null;
  const searchCaretEnd = restoreSearchFocus ? searchInput.selectionEnd : null;
  const searchDirection = restoreSearchFocus ? searchInput.selectionDirection : "none";
  const restoreFocus = () => {
    if (!restoreSearchFocus || !searchInput) return;
    try {
      searchInput.focus({ preventScroll: true });
    } catch (_error) {
      searchInput.focus();
    }
    if (searchCaretStart != null && searchCaretEnd != null && typeof searchInput.setSelectionRange === "function") {
      try { searchInput.setSelectionRange(searchCaretStart, searchCaretEnd, searchDirection || "none"); } catch (_error) { /* no-op */ }
    }
  };
  const apply = () => {
    const textarea = dom.variablesPanel?.querySelector('textarea[data-project-field="variables"]');
    if (!textarea) return;
    const length = (state.playbookSearch || "").length;
    const end = offset + Math.max(0, length);
    showPlaybookJsonSearchHighlight(textarea, offset, end);
    centerPlaybookJsonSearchMatch(textarea, offset, restoreFocus);
  };
  if (wasOpen) apply();
  else requestAnimationFrame(apply);
}

function restorePlaybookJsonSearchHighlight() {
  if (!state.playbookJsonOpen || state.playbookSearchIndex < 0 || !(state.playbookSearch || "").trim()) return;
  requestAnimationFrame(() => {
    if (!state.playbookJsonOpen || state.playbookSearchIndex < 0 || !(state.playbookSearch || "").trim()) return;
    const textarea = dom.variablesPanel?.querySelector('textarea[data-project-field="variables"]');
    if (!textarea) return;
    const matches = getPlaybookSearchMatchOffsets();
    const offset = matches[state.playbookSearchIndex];
    if (!Number.isFinite(offset)) {
      hidePlaybookJsonSearchHighlight();
      return;
    }
    const length = (state.playbookSearch || "").length;
    showPlaybookJsonSearchHighlight(textarea, offset, offset + Math.max(0, length));
    if (getScopeActiveElement() === dom.playbookSearchInput) {
      centerPlaybookJsonSearchMatch(textarea, offset);
    }
  });
}

function hidePlaybookJsonSearchHighlight() {
  const highlight = dom.variablesPanel?.querySelector("[data-playbook-json-highlight]");
  if (!highlight) return;
  highlight.hidden = true;
  highlight.removeAttribute("data-search-match-start");
  highlight.removeAttribute("data-search-match-end");
}

function showPlaybookJsonSearchHighlight(textarea, start, end) {
  const highlight = dom.variablesPanel?.querySelector("[data-playbook-json-highlight]");
  if (!highlight) return null;
  const metrics = getPlaybookJsonLineMetrics(textarea, start);
  highlight.style.top = `${metrics.top}px`;
  highlight.style.height = `${metrics.lineHeight}px`;
  highlight.hidden = false;
  highlight.dataset.searchMatchStart = String(start);
  highlight.dataset.searchMatchEnd = String(end);
  return highlight;
}

function centerPlaybookJsonSearchMatch(textarea, offset, restoreFocus = null) {
  const apply = () => {
    if (typeof restoreFocus === "function") restoreFocus();
    centerPlaybookJsonOffset(textarea, offset);
  };
  apply();
  requestAnimationFrame(() => {
    apply();
    requestAnimationFrame(apply);
  });
}

function centerPlaybookJsonOffset(textarea, offset) {
  const metrics = getPlaybookJsonLineMetrics(textarea, offset);
  const scrollable = findScrollableAncestor(textarea);
  if (!scrollable) return;
  const isDocumentScroller = scrollable === document.scrollingElement
    || scrollable === document.documentElement
    || scrollable === document.body;
  const lineCenterInViewport = getPlaybookJsonLineCenterInViewport(textarea, metrics);
  if (isDocumentScroller) {
    const viewportHeight = window.innerHeight || document.documentElement.clientHeight || scrollable.clientHeight;
    const currentScrollTop = window.scrollY || scrollable.scrollTop || 0;
    const maxScrollTop = Math.max(0, scrollable.scrollHeight - viewportHeight);
    const targetScrollTop = clamp(currentScrollTop + lineCenterInViewport - viewportHeight / 2, 0, maxScrollTop);
    if (typeof window.scrollTo === "function") {
      window.scrollTo({ left: window.scrollX || 0, top: targetScrollTop, behavior: "auto" });
    } else {
      scrollable.scrollTop = targetScrollTop;
    }
    return;
  }
  const scrollableRect = scrollable.getBoundingClientRect();
  const lineYInScrollable = (lineCenterInViewport - scrollableRect.top) + scrollable.scrollTop;
  const maxScrollTop = Math.max(0, scrollable.scrollHeight - scrollable.clientHeight);
  const targetScrollTop = clamp(lineYInScrollable - scrollable.clientHeight / 2, 0, maxScrollTop);
  scrollable.scrollTop = targetScrollTop;
}

function getPlaybookJsonLineCenterInViewport(textarea, metrics) {
  const textareaRect = textarea.getBoundingClientRect();
  return textareaRect.top
    + metrics.borderTop
    + metrics.paddingTop
    + metrics.lineIndex * metrics.lineHeight
    - (textarea.scrollTop || 0)
    + metrics.lineHeight / 2;
}

function getPlaybookJsonLineMetrics(textarea, offset) {
  const style = window.getComputedStyle ? window.getComputedStyle(textarea) : null;
  const parsedLineHeight = Number.parseFloat(style?.lineHeight || "");
  const fontSize = Number.parseFloat(style?.fontSize || "");
  const lineHeight = Number.isFinite(parsedLineHeight) ? parsedLineHeight : Math.max(18, (Number.isFinite(fontSize) ? fontSize * 1.35 : 18));
  const paddingTop = Number.parseFloat(style?.paddingTop || "") || 0;
  const borderTop = Number.parseFloat(style?.borderTopWidth || "") || 0;
  const before = textarea.value.slice(0, Math.max(0, offset));
  const lineIndex = (before.match(/\n/g) || []).length;
  return {
    lineIndex,
    lineHeight,
    borderTop,
    paddingTop,
    top: textarea.offsetTop + borderTop + paddingTop + lineIndex * lineHeight
  };
}

function findScrollableAncestor(element) {
  let node = element?.parentElement;
  while (node && node !== document.body) {
    const style = window.getComputedStyle(node);
    if (/(auto|scroll)/.test(style.overflowY) && node.scrollHeight > node.clientHeight) return node;
    node = node.parentElement;
  }
  return document.scrollingElement || document.documentElement;
}

function focusCanvasNode(id) {
  const node = getNode(id);
  if (!node) return;
  if (state.frameCanvasId && !isNodeWithinFrameCanvas(node)) exitFrameCanvas({ render: false });
  state.activeFileId = "adventure";
  state.selectedNodeId = id;
  state.selectedNodeIds = [];
  state.selectedLinkId = null;
  state.characterFocusId = null;
  state.panel = "node";
  renderAll();
  centerCanvasOnNode(node, NODE_FOCUS_ZOOM, { immediate: true });
  setStatus(`${node.title || getNodeDisplayId(node)} focused.`);
}

function focusCanvasNodeForInlineEdit(id) {
  const node = getNode(id);
  if (!node) return;
  if (state.frameCanvasId && !isNodeWithinFrameCanvas(node)) exitFrameCanvas({ render: false });
  state.activeFileId = "adventure";
  state.selectedNodeId = id;
  state.selectedNodeIds = [];
  state.selectedLinkId = null;
  state.panel = "node";
  state.inlineEditNodeId = id;
  state.inlineEditField = getInlineEditableField(node);
  renderAll();
  centerCanvasOnNode(node, NODE_FOCUS_ZOOM, { immediate: true });
  focusInlineNodeEditor(id);
  setStatus(`${node.title || getNodeDisplayId(node)} focused for editing.`);
  runAfterRender(() => {
    focusInlineNodeEditor(id);
  });
}

function focusCharacterNode(id) {
  const node = getNode(id);
  if (!node) return;
  if (state.frameCanvasId && !isNodeWithinFrameCanvas(node)) exitFrameCanvas({ render: false });
  state.activeFileId = "adventure";
  state.selectedNodeId = id;
  state.selectedLinkId = null;
  state.panel = "story";
  renderAll();
  centerCanvasOnNode(node, NODE_FOCUS_ZOOM, { immediate: true });
  runAfterRender(() => {
    scrollStoryNodeIntoView(id);
    setStatus(`${node.title || getNodeDisplayId(node)} focused.`);
  });
}

function scrollStoryNodeIntoView(id) {
  const target = dom.storyPanel?.querySelector(`[data-story-node-id="${id}"]`);
  if (!target) return false;
  target.scrollIntoView({ block: "center", behavior: "smooth" });
  return true;
}

function clearNodeSelection() {
  state.selectedNodeId = null;
  state.selectedNodeIds = [];
  if (state.panel === "node") state.panel = "project";
}

function editNodeType(type) {
  const typeDef = getNodeTypeDef(type);
  if (!typeDef) return;
  state.typeDialogType = typeDef.type;

  if (dom.nodeTypeDialog?.showModal) {
    dom.nodeTypeDialog.returnValue = "";
    dom.nodeTypeDialogTitle.textContent = t("Edit {label}", { label: typeDef.label });
    dom.nodeTypeNameInput.value = typeDef.label || typeDef.type;
    dom.nodeTypeKindInput.value = getNodeTypeTemplate(typeDef);
    dom.nodeTypeFieldsInput.value = formatNodeTypeFields(typeDef.fields);
    renderNodeTypeFieldSections(typeDef);
    if (dom.nodeTypeIconInput) {
      dom.nodeTypeIconInput.value = typeDef.badgeCustom ? (typeDef.badge || "") : "";
      dom.nodeTypeIconInput.placeholder = getDefaultNodeTypeBadge(typeDef.label);
    }
    dom.nodeTypeColorInput.value = normalizeCustomColor(typeDef.color);
    if (dom.nodeTypeOpacityInput) {
      dom.nodeTypeOpacityInput.value = String(normalizeNodeTypeOpacity(typeDef.cardOpacity) ?? 20);
      updateNodeTypeOpacityReadout();
    }
    if (dom.nodeTypeOpacityField) {
      dom.nodeTypeOpacityField.hidden = !isFrameKind(typeDef.kind);
    }
    dom.nodeTypeHiddenInput.checked = Boolean(typeDef.hidden);
    if (dom.nodeTypeEventHiddenInput) {
      dom.nodeTypeEventHiddenInput.checked = Boolean(typeDef.eventSheetHidden);
      dom.nodeTypeEventHiddenInput.closest("label").hidden = !isFrameKind(typeDef.kind);
    }
    dom.nodeTypeDialog.showModal();
    runAfterRender(() => {
      dom.nodeTypeNameInput.focus();
      dom.nodeTypeNameInput.select();
    });
    return;
  }

  showGenericTextInput({
    kicker: "Node Type",
    title: t("Rename {label}", { label: typeDef.label }),
    label: "Name",
    value: typeDef.label || typeDef.type,
    maxLength: 40,
    confirmLabel: "Apply",
    recordHistory: true,
    onConfirm: (nextName) => {
      applyNodeTypeValues(typeDef.type, {
        label: nextName,
        kind: typeDef.kind,
        template: getNodeTypeTemplate(typeDef),
        fields: typeDef.fields,
        color: typeDef.color,
        hidden: typeDef.hidden,
        eventSheetHidden: typeDef.eventSheetHidden
      });
      return true;
    }
  });
}

function applyNodeTypeDialog() {
  const typeDef = getNodeTypeDef(state.typeDialogType);
  const knownFields = [...(typeDef?.fields || []), ...getUndeclaredNodeTypeFields(typeDef)];
  applyNodeTypeValues(state.typeDialogType, {
    label: dom.nodeTypeNameInput.value,
    template: dom.nodeTypeKindInput.value,
    fields: parseCustomNodeFields(dom.nodeTypeFieldsInput.value, knownFields),
    badge: dom.nodeTypeIconInput ? dom.nodeTypeIconInput.value : undefined,
    color: dom.nodeTypeColorInput.value,
    cardOpacity: Number(dom.nodeTypeOpacityInput?.value ?? 100),
    hidden: dom.nodeTypeHiddenInput.checked,
    eventSheetHidden: Boolean(dom.nodeTypeEventHiddenInput?.checked)
  });
}

function updateNodeTypeOpacityReadout() {
  if (!dom.nodeTypeOpacityValue || !dom.nodeTypeOpacityInput) return;
  const value = Number(dom.nodeTypeOpacityInput.value) || 0;
  const min = Number(dom.nodeTypeOpacityInput.min) || 0;
  const max = Number(dom.nodeTypeOpacityInput.max) || 100;
  const ratio = max > min ? Math.min(1, Math.max(0, (value - min) / (max - min))) : 0;
  dom.nodeTypeOpacityValue.textContent = `${value}%`;
  dom.nodeTypeOpacityControl?.style.setProperty("--range-ratio", String(ratio));
}

function resetNodeTypeIconInput() {
  if (!dom.nodeTypeIconInput) return;
  dom.nodeTypeIconInput.value = "";
  dom.nodeTypeIconInput.focus();
}

function applyNodeTypeValues(type, values) {
  const typeDef = getNodeTypeDef(type);
  if (!typeDef) return;
  const label = String(values.label || "").trim().slice(0, 40);
  if (!label) {
    setStatus("Node type name is required.");
    return;
  }
  const previousFields = typeDef.fields || [];
  const nextFields = normalizeNodeTypeFields(values.fields);
  const nextFieldKeys = new Set(nextFields.map((field) => field.key));
  const removedFieldKeys = previousFields
    .map((field) => field.key)
    .filter((key) => key && !nextFieldKeys.has(key));

  typeDef.label = label;
  if (values.badge !== undefined) {
    const nextIcon = normalizeNodeTypeBadge(values.badge);
    typeDef.badge = nextIcon || getDefaultNodeTypeBadge(label);
    typeDef.badgeCustom = Boolean(nextIcon);
  }
  typeDef.template = normalizeNodeTypeTemplate(values.template, typeDef.type, values.kind);
  typeDef.kind = typeDef.template === "frame" ? "frame" : "node";
  typeDef.fields = nextFields;
  typeDef.color = normalizeNodeTypeColor(typeDef.type, typeDef.kind, values.color);
  typeDef.cardOpacity = isFrameKind(typeDef.kind) ? normalizeNodeTypeOpacity(values.cardOpacity ?? typeDef.cardOpacity ?? 20) : 100;
  typeDef.hidden = Boolean(values.hidden);
  typeDef.eventSheetHidden = isFrameKind(typeDef.kind) ? Boolean(values.eventSheetHidden) : false;
  typeDef.width = clamp(typeDef.width || (isFrameKind(typeDef.kind) ? 420 : 230), 160, isFrameKind(typeDef.kind) ? 860 : 420);

  state.project.nodes
    .filter((node) => node.type === typeDef.type)
    .forEach((node) => {
      removedFieldKeys.forEach((key) => deleteNodeFieldValue(node, key));
      applyNodeTypeDefaults(node);
    });

  if (removedFieldKeys.length && isEventSheetTypeDef(typeDef)) {
    const removed = new Set(removedFieldKeys);
    const eventSheet = getProjectEventSheet();
    eventSheet.columns = eventSheet.columns.filter((column) => !column.custom || !removed.has(column.key));
    eventSheet.hiddenColumns = eventSheet.hiddenColumns.filter((key) => !removed.has(key));
  }

  markProjectStructureChanged({ nodeTypes: true });
  renderAll();
  setStatus(`${typeDef.label} node type updated.`);
}

function formatNodeTypeFields(fields) {
  return (fields || []).map((field) => field.label || field.key || "").filter(Boolean).join("\n");
}

function renderNodeTypeFieldSections(typeDef) {
  if (!typeDef) return;
  const builtInFields = getNodeTypeBuiltInFields(typeDef);
  if (dom.nodeTypeBuiltinFields) {
    dom.nodeTypeBuiltinFields.innerHTML = builtInFields
      .map((field) => `<span class="node-type-field-chip" data-node-type-built-in-field="${escapeAttr(field.key)}">${escapeHtml(field.label)}</span>`)
      .join("");
  }
  const currentLabels = new Set(String(dom.nodeTypeFieldsInput?.value || "")
    .split(/\r?\n/)
    .map((label) => label.trim().toLowerCase())
    .filter(Boolean));
  const candidates = getUndeclaredNodeTypeFields(typeDef);
  if (dom.nodeTypeExistingFieldsSection) dom.nodeTypeExistingFieldsSection.hidden = !candidates.length;
  if (dom.nodeTypeExistingFields) {
    dom.nodeTypeExistingFields.innerHTML = candidates.map((field) => {
      const added = currentLabels.has(field.label.toLowerCase());
      const actionLabel = added ? t("Added") : t("Add {label} to type", { label: field.label });
      return `<button class="node-type-existing-field${added ? " added" : ""}" type="button" data-action="add-existing-node-type-field" data-node-type-field-key="${escapeAttr(field.key)}" ${added ? "disabled" : ""} aria-label="${escapeAttr(actionLabel)}"><span>${escapeHtml(field.label)}</span><small>${escapeHtml(field.key)}</small><strong>${added ? t("Added") : "+"}</strong></button>`;
    }).join("");
  }
}

function getNodeTypeBuiltInFields(typeDef) {
  const fields = [
    { key: "title", label: t("Title") },
    { key: "body", label: t("Body") }
  ];
  const template = getNodeTypeTemplate(typeDef);
  if (template === "frame") {
    const removed = new Set(getTypeRemovedColumns(typeDef));
    const projectColumns = new Map(getProjectEventSheetColumns().map((column) => [column.key, column]));
    CORE_EVENT_COLUMN_KEYS.forEach((key) => {
      if (removed.has(key)) return;
      const column = projectColumns.get(key) || eventSheetColumns.find((entry) => entry.key === key);
      if (column) fields.push({ key, label: column.label || key });
    });
  } else if (template === "choice") {
    fields.push({ key: "choices", label: t("Choices") });
  } else if (template === "dialog") {
    fields.push({ key: "turns", label: t("Dialog") });
  }
  return fields;
}

function getUndeclaredNodeTypeFields(typeDef) {
  if (!typeDef?.type) return [];
  const declared = new Set((typeDef.fields || []).map((field) => field.key));
  const builtIn = new Set(getNodeTypeBuiltInFields(typeDef).map((field) => field.key));
  const labels = new Map(getProjectEventSheetColumns().map((column) => [column.key, column.label || column.key]));
  const candidates = new Map();
  state.project.nodes
    .filter((node) => node.type === typeDef.type)
    .forEach((node) => {
      if (node.customFields && typeof node.customFields === "object" && !Array.isArray(node.customFields)) {
        Object.keys(node.customFields).forEach((key) => {
          if (!key || declared.has(key) || builtIn.has(key)) return;
          candidates.set(key, { key, label: labels.get(key) || formatNodeFieldKeyLabel(key) });
        });
      }
      DIRECT_NODE_FIELD_KEYS.forEach((key) => {
        const value = node[key];
        const hasValue = Array.isArray(value) ? value.length > 0 : value != null && value !== "";
        if (!hasValue || declared.has(key) || builtIn.has(key)) return;
        candidates.set(key, { key, label: labels.get(key) || formatNodeFieldKeyLabel(key) });
      });
    });
  return [...candidates.values()];
}

function formatNodeFieldKeyLabel(key) {
  const source = String(key || "").trim();
  const directLabels = {
    choices: t("Choices"),
    condition: t("Condition"),
    value: t("Value"),
    variable: t("Variable"),
    variables: t("Variables")
  };
  if (directLabels[source]) return directLabels[source];
  return source
    .replace(/([a-z0-9])([A-Z])/g, "$1 $2")
    .replace(/[_-]+/g, " ")
    .replace(/^\w/, (character) => character.toUpperCase());
}

function addExistingNodeTypeField(fieldKey) {
  const typeDef = getNodeTypeDef(state.typeDialogType);
  if (!typeDef) return;
  const field = getUndeclaredNodeTypeFields(typeDef).find((entry) => entry.key === fieldKey);
  if (!field) return;
  const labels = String(dom.nodeTypeFieldsInput.value || "").split(/\r?\n/).map((label) => label.trim()).filter(Boolean);
  if (!labels.some((label) => label.toLowerCase() === field.label.toLowerCase())) {
    labels.push(field.label);
    dom.nodeTypeFieldsInput.value = labels.join("\n");
  }
  renderNodeTypeFieldSections(typeDef);
}

function setProjectField(field, value, options = {}) {
  if (field === "variables") {
    if (value === buildVariablesJson()) return;
    try {
      applyScriptJson(value);
      setStatus("Playbook JSON updated.");
    } catch (error) {
      setStatus("Playbook JSON is invalid.");
      return;
    }
  } else if (field === "playHistoryLimit") {
    state.project.playHistoryLimit = normalizePlayHistoryLimit(value);
    trimPreviewHistory();
  } else if (field === "richTextFormat") {
    const nextFormat = normalizeRichTextFormat(value);
    const previousFormat = normalizeRichTextFormat(state.project.richTextFormat);
    if (nextFormat === previousFormat) return;
    convertProjectRichText(previousFormat, nextFormat);
    state.project.richTextFormat = nextFormat;
    if (!options.skipHostSync) void window.NarrativeCanvasHost?.setRichTextFormat?.(nextFormat);
    setStatus(t("Rich text converted to {format}.", {
      format: RICH_TEXT_FORMATS.find((option) => option.value === nextFormat)?.label || nextFormat
    }));
  } else {
    state.project[field] = value;
  }
  setProjectDirty(true);

  if (field === "title" || field === "notes" || field === "playHistoryLimit") {
    renderShellState();
    renderStoryPanel();
    renderWorkspaceFile();
    updateStatus();
    return;
  }

  if (field === "variables") {
    renderPlaybookSurfaces();
    return;
  }

  if (field === "richTextFormat") {
    renderAll();
    return;
  }

  renderNodes();
  renderStoryPanel();
  renderProjectPanel();
  renderWorkspaceFile();
  updateStatus();
}

function setProjectRichTextFormatFromHost(value) {
  const nextFormat = normalizeRichTextFormat(value);
  if (!state.project || nextFormat === getCurrentRichTextFormat()) return true;
  setProjectField("richTextFormat", nextFormat, { skipHostSync: true });
  return true;
}

function setNodeField(field, value) {
  const node = getNode(state.selectedNodeId);
  if (!node) return;
  invalidateCharacterRenderContext();
  if (field === "x" || field === "y") {
    node[field] = Number(value) || 0;
  } else if (field === "choices") {
    node.choices = value.split(/\r?\n/).map((item) => item.trim()).filter(Boolean);
  } else if (field === "type") {
    node[field] = value;
    applyNodeTypeDefaults(node);
  } else {
    node[field] = value;
  }
  if (field === "type") markProjectStructureChanged({ nodeTypes: true });
  const choiceLinksChanged = field === "choices" || field === "type"
    ? syncChoiceBranchLinksForNode(node.id, { markDirty: false })
    : false;
  setProjectDirty(true);
  // Incremental: rebuild only the visible nodes (cheap) and patch this node's
  // incident links in place. The minimap only changes when position changes, and
  // the (potentially large) story panel is refreshed on a short debounce instead
  // of on every keystroke.
  renderNodes();
  if (choiceLinksChanged) renderLinks();
  else patchLinkElementRefs(collectLinkElementRefs(getIncidentLinks(node.id)));
  markCanvasSurfaceRenderedIfActive();
  if (field === "x" || field === "y") renderMinimap();
  if (field === "type") {
    renderInspector();
  } else {
    scheduleStoryPanelRender();
  }
  updateStatus();
}

function setNodeVaultFile(index, value) {
  const node = getNode(state.selectedNodeId);
  if (!node || !Number.isInteger(index) || index < 0) return;
  const references = getNodeVaultFiles(node);
  const previousReference = references[index]?.path || "";
  const nextReference = normalizeNodeVaultFileReference(value);
  if (index < references.length) {
    if (nextReference) references[index] = { ...references[index], path: nextReference };
    else references.splice(index, 1);
  } else if (nextReference) {
    references.push({ path: nextReference, preview: false });
  }
  if (references.length) node.vaultFiles = references;
  else delete node.vaultFiles;
  delete node.vaultFile;
  delete node.vaultFilePreview;
  if (previousReference) state.vaultFilePreviewCache.delete(previousReference);
  if (nextReference) state.vaultFilePreviewCache.delete(nextReference);
  nodeLayoutSizeCache.delete(node);
  setProjectDirty(true);
  renderNodes();
  renderLinks();
  renderMinimap();
  scheduleStoryPanelRender();
  updateStatus();
}

function normalizeNodeVaultFileReference(value) {
  const source = String(value || "").trim();
  const wikiMatch = source.match(/^\[\[([^\]|#]+)(?:#[^\]|]*)?(?:\|[^\]]*)?\]\]$/);
  return (wikiMatch ? wikiMatch[1] : source).trim().replace(/^\/+/, "");
}

// Preview height in pixels for image previews on node cards. Accepts the legacy
// s/m/l names and clamps numbers into the slider range.
function normalizeVaultPreviewSize(value) {
  if (value === "s") return 64;
  if (value === "l") return 292;
  const number = Number(value);
  if (Number.isFinite(number) && number > 0) return Math.round(Math.min(320, Math.max(48, number)));
  return 132;
}

function normalizeNodeVaultFiles(value, legacyReference = "", legacyPreview = false) {
  const source = Array.isArray(value) ? value : [];
  const normalized = [];
  source.forEach((entry) => {
    const path = normalizeNodeVaultFileReference(typeof entry === "string" ? entry : entry?.path || entry?.reference || entry?.vaultFile);
    if (!path || normalized.some((item) => item.path === path)) return;
    const fallback = getDefaultVisionBoardPlacement(normalized.length);
    normalized.push({
      path,
      preview: Boolean(typeof entry === "object" && entry?.preview),
      previewSize: normalizeVaultPreviewSize(typeof entry === "object" ? entry?.previewSize : null),
      x: clampVisionBoardNumber(entry?.x, fallback.x, 0, 82),
      y: clampVisionBoardNumber(entry?.y, fallback.y, 0, 76),
      w: clampVisionBoardNumber(entry?.w, fallback.w, 14, 48)
    });
  });
  const legacyPath = normalizeNodeVaultFileReference(legacyReference);
  if (legacyPath && !normalized.some((entry) => entry.path === legacyPath)) {
    normalized.unshift({ path: legacyPath, preview: Boolean(legacyPreview), previewSize: 132, ...getDefaultVisionBoardPlacement(0) });
  }
  return normalized;
}

function getNodeVaultFiles(node) {
  return normalizeNodeVaultFiles(node?.vaultFiles, node?.vaultFile, node?.vaultFilePreview);
}

function normalizeVaultFileSuggestionQuery(value) {
  return String(value || "")
    .trim()
    .replace(/^\[\[/, "")
    .replace(/^\[/, "")
    .replace(/\]\]$/, "")
    .split(/[|#]/, 1)[0]
    .trim();
}

async function updateVaultFileSuggestions(target, options = {}) {
  const host = window.NarrativeCanvasHost;
  const source = String(target?.value || "").trim();
  if (!target?.isConnected || !host?.searchVaultFiles || (!source && !options.force)) {
    hideVaultFileSuggestions();
    return;
  }
  const requestId = ++state.vaultFileSuggestionRequestId;
  const query = normalizeVaultFileSuggestionQuery(source);
  const imageOnly = Boolean(target.dataset?.characterImageFile || target.dataset?.characterImagePickerInput || target.dataset?.characterIconInput != null);
  try {
    const result = await host.searchVaultFiles(query, imageOnly ? 80 : 40, { imageOnly });
    if (requestId !== state.vaultFileSuggestionRequestId || !target.isConnected) return;
    let paths = Array.isArray(result)
      ? result.map((path) => String(path || "").trim()).filter(Boolean)
      : [];
    if (imageOnly) {
      paths = paths.filter((path) => CODEX_IMAGE_FILE_PATTERN.test(path));
    }
    if (!paths.length) {
      hideVaultFileSuggestions();
      return;
    }
    state.vaultFileSuggestions = { target, paths, activeIndex: 0 };
    renderVaultFileSuggestions();
  } catch (error) {
    console.error(error);
    hideVaultFileSuggestions();
  }
}

function renderVaultFileSuggestions() {
  const current = state.vaultFileSuggestions;
  const target = current?.target;
  const container = getVaultFileSuggestionContainer(target);
  if (!current || !target?.isConnected || !container) {
    hideVaultFileSuggestions();
    return;
  }
  const imagePicker = Boolean(target.dataset?.characterImagePickerInput) || target.dataset?.characterIconInput != null;
  const host = window.NarrativeCanvasHost;
  container.innerHTML = current.paths.map((path, index) => {
    const parts = path.split("/");
    const name = parts.pop() || path;
    const folder = parts.join("/");
    const thumbnailUrl = imagePicker && host?.getVaultResourceUrl ? host.getVaultResourceUrl(path) : "";
    return `
      <button class="vault-file-suggestion${imagePicker ? " codex-image-suggestion" : ""}${index === current.activeIndex ? " active" : ""}" type="button" role="option" aria-selected="${index === current.activeIndex ? "true" : "false"}" data-action="select-vault-file-suggestion" data-vault-file-path="${escapeAttr(path)}">
        ${thumbnailUrl ? `<img src="${escapeAttr(thumbnailUrl)}" alt="" loading="lazy">` : ""}
        <span>
          <strong>${escapeHtml(name)}</strong>
          ${folder ? `<small>${escapeHtml(folder)}</small>` : ""}
        </span>
      </button>
    `;
  }).join("");
  container.hidden = false;
  target.setAttribute("aria-expanded", "true");
  container.querySelector(".vault-file-suggestion.active")?.scrollIntoView?.({ block: "nearest" });
}

function hideVaultFileSuggestions() {
  state.vaultFileSuggestionRequestId += 1;
  const target = state.vaultFileSuggestions?.target;
  const container = getVaultFileSuggestionContainer(target);
  if (container) {
    container.hidden = true;
    container.replaceChildren();
  }
  target?.setAttribute?.("aria-expanded", "false");
  state.vaultFileSuggestions = null;
}

function getVaultFileSuggestionContainer(target) {
  return target?.closest?.(".node-vault-file-input-wrap, .codex-image-picker, .codex-vault-file-input-wrap")
    ?.querySelector?.("[data-vault-file-suggestions]") || null;
}

function handleVaultFileSuggestionPointerDown(event) {
  if (!event.target.closest?.("[data-vault-file-path]")) return;
  event.preventDefault();
}

function handleVaultFileSuggestionKeyDown(event) {
  const current = state.vaultFileSuggestions;
  if (!current || event.target !== current.target) return false;
  if (event.key === "Escape") {
    if (current.target?.dataset?.characterImagePickerInput) {
      closeCodexImagePicker(current.target.dataset.characterId);
      event.preventDefault();
      return true;
    }
    hideVaultFileSuggestions();
    event.preventDefault();
    return true;
  }
  if (event.key === "ArrowDown" || event.key === "ArrowUp") {
    const direction = event.key === "ArrowDown" ? 1 : -1;
    current.activeIndex = (current.activeIndex + direction + current.paths.length) % current.paths.length;
    renderVaultFileSuggestions();
    event.preventDefault();
    return true;
  }
  if (event.key === "Enter" || event.key === "Tab") {
    const path = current.paths[current.activeIndex];
    if (path) {
      selectVaultFileSuggestion(path);
      event.preventDefault();
      return true;
    }
  }
  return false;
}

function selectVaultFileSuggestion(path) {
  const target = state.vaultFileSuggestions?.target
    || dom.nodePanel?.querySelector?.("[data-node-vault-file-index]");
  const reference = normalizeNodeVaultFileReference(path);
  if (!target || !reference) return;
  if (target.dataset?.characterImageFile || target.dataset?.characterImagePickerInput) {
    const characterId = target.dataset.characterId;
    hideVaultFileSuggestions();
    assignCodexImageFile(characterId, reference);
    return;
  }
  if (target.dataset?.characterVaultFileInput != null) {
    addCodexVaultFile(target.dataset.characterId, reference);
    return;
  }
  if (target.dataset?.characterIconInput != null) {
    hideVaultFileSuggestions();
    setCodexIcon(target.dataset.characterId, reference);
    return;
  }
  const index = Number(target.dataset.nodeVaultFileIndex);
  const node = getNode(state.selectedNodeId);
  const references = getNodeVaultFiles(node);
  if (references.some((entry, entryIndex) => entry.path === reference && entryIndex !== index)) {
    hideVaultFileSuggestions();
    setStatus("File already linked.");
    return;
  }
  target.value = reference;
  setNodeVaultFile(index, reference);
  commitFocusedEdit(target);
  hideVaultFileSuggestions();
  renderInspector();
  runAfterRender(() => {
    const input = dom.nodePanel?.querySelector?.(`[data-node-vault-file-index="${Math.min(index, getNodeVaultFiles(getNode(state.selectedNodeId)).length)}"]`);
    if (!input) return;
    state.vaultFileSuggestionSuppressedTargets?.add(input);
    input.focus({ preventScroll: true });
    input.setSelectionRange?.(input.value.length, input.value.length);
  });
}

async function chooseCodexImageFile(characterId) {
  const host = window.NarrativeCanvasHost;
  if (!getCharacterById(characterId) || !host?.searchVaultFiles) return;
  state.codexImagePickerCharacterId = characterId;
  renderCharacterGridForSearch();
  // Timer instead of requestAnimationFrame: rAF can be starved under headless/virtual-time
  // test runs and throttled iframes, leaving the picker without its suggestion list.
  window.setTimeout(() => {
    const input = dom.charactersPanel?.querySelector?.(`[data-character-card-id="${CSS.escape(characterId)}"] [data-character-image-picker-input]`);
    if (!input) return;
    input.focus({ preventScroll: true });
    void updateVaultFileSuggestions(input, { force: true });
  }, 0);
}

function closeCodexImagePicker(characterId = state.codexImagePickerCharacterId) {
  if (characterId && state.codexImagePickerCharacterId !== characterId) return;
  hideVaultFileSuggestions();
  state.codexImagePickerCharacterId = "";
  renderCharacterGridForSearch();
}

async function openCodexReference(reference) {
  const host = window.NarrativeCanvasHost;
  const normalized = normalizeNodeVaultFileReference(reference);
  if (!normalized || !host?.openVaultFile) return;
  try {
    await leaveImmersiveFullscreenForVaultNavigation();
    await host.openVaultFile(normalized);
  } catch (error) {
    console.error(error);
    setStatus(t("Could not open the linked vault file."));
  }
}

function clearCodexImageFile(characterId) {
  const character = getCharacterById(characterId);
  if (!getCharacterImages(character).length) return;
  const historyBefore = getHistorySnapshot();
  syncCharacterImageAliases(character, []);
  if (state.codexImagePickerCharacterId === characterId) state.codexImagePickerCharacterId = "";
  invalidateCharacterRenderContext();
  setProjectDirty(true);
  renderCharacterGridForSearch();
  commitHistoryFromSnapshot(historyBefore);
  setStatus("Library image removed.");
}

function assignCodexImageFile(characterId, reference) {
  return assignCodexImageFiles(characterId, [reference]);
}

function assignCodexImageFiles(characterId, references) {
  const character = getCharacterById(characterId);
  const normalized = (references || [])
    .map(normalizeNodeVaultFileReference)
    .filter((path) => CODEX_IMAGE_FILE_PATTERN.test(path));
  if (!character || !normalized.length) {
    setStatus("Drop an image file.");
    return false;
  }
  const images = getCharacterImages(character);
  const existing = new Set(images.map((image) => image.path));
  normalized.forEach((path) => {
    if (existing.has(path)) return;
    existing.add(path);
    images.push({ path, ...getDefaultVisionBoardPlacement(images.length) });
  });
  const historyBefore = getHistorySnapshot();
  syncCharacterImageAliases(character, images);
  state.codexImagePickerCharacterId = "";
  invalidateCharacterRenderContext();
  setProjectDirty(true);
  renderCharacterGridForSearch();
  commitHistoryFromSnapshot(historyBefore);
  setStatus("Library image assigned.");
  return true;
}

function removeCodexImage(characterId, index) {
  const character = getCharacterById(characterId);
  const images = getCharacterImages(character);
  if (!character || !images[index]) return;
  const historyBefore = getHistorySnapshot();
  images.splice(index, 1);
  syncCharacterImageAliases(character, images);
  invalidateCharacterRenderContext();
  setProjectDirty(true);
  renderCharacterGridForSearch();
  if (state.visionBoardContext?.kind === "character" && state.visionBoardContext.id === characterId) renderFocusedVisionBoard();
  commitHistoryFromSnapshot(historyBefore);
  setStatus("Library image removed.");
}

function openLocalCodexImageInput(characterId) {
  const input = dom.charactersPanel?.querySelector?.(`[data-codex-local-image-input][data-character-id="${CSS.escape(characterId || "")}"]`);
  input?.click?.();
}

async function importLocalCodexImages(characterId, files) {
  const host = window.NarrativeCanvasHost;
  const images = (files || []).filter(isCodexImageFile);
  if (!getCharacterById(characterId) || !images.length || !host?.importCodexImage) return;
  try {
    const references = [];
    for (const file of images) {
      references.push(await host.importCodexImage(file, getCharacterById(characterId)?.name || ""));
    }
    assignCodexImageFiles(characterId, references);
  } catch (error) {
    console.error(error);
    setStatus("Could not import image.");
  }
}

function getVisionBoardContextImages(context = state.visionBoardContext) {
  if (!context) return [];
  if (context.kind === "character") return getCharacterImages(getCharacterById(context.id));
  if (context.kind === "node") return getNodeVaultFiles(getNode(context.id)).filter((entry) => CODEX_IMAGE_FILE_PATTERN.test(entry.path));
  return [];
}

function openVisionBoard(kind, id) {
  const normalizedKind = kind === "node" ? "node" : "character";
  const context = { kind: normalizedKind, id: String(id || "") };
  if (!getVisionBoardContextImages(context).length || !dom.visionBoardDialog?.showModal) return;
  state.visionBoardContext = context;
  renderFocusedVisionBoard();
  if (!dom.visionBoardDialog.open) dom.visionBoardDialog.showModal();
}

function closeVisionBoard() {
  state.visionBoardDrag = null;
  state.visionBoardContext = null;
  if (dom.visionBoardDialog?.open) dom.visionBoardDialog.close();
}

function renderFocusedVisionBoard() {
  const context = state.visionBoardContext;
  if (!context || !dom.visionBoardCanvas) return;
  const images = getVisionBoardContextImages(context);
  if (!images.length) {
    closeVisionBoard();
    return;
  }
  const title = context.kind === "node"
    ? getNode(context.id)?.title || t("Linked images")
    : getCharacterById(context.id)?.name || t("Preview images");
  if (dom.visionBoardTitle) dom.visionBoardTitle.textContent = title;
  dom.visionBoardCanvas.outerHTML = renderVisionBoard(context.kind, context.id, images, { focused: true });
  dom.visionBoardCanvas = dom.visionBoardDialog.querySelector(".vision-board-canvas");
}

function handleVisionBoardPointerDown(event) {
  const tile = event.target?.closest?.("#visionBoardDialog [data-vision-board-tile]");
  if (!tile || event.target.closest?.("button") || event.button !== 0) return;
  const board = tile.closest(".vision-board-canvas");
  if (!board) return;
  const rect = board.getBoundingClientRect();
  state.visionBoardDrag = {
    pointerId: event.pointerId,
    // Dragging the corner grip resizes the tile; dragging anywhere else moves it.
    mode: event.target.closest?.("[data-vision-board-resize]") ? "resize" : "move",
    tile,
    board,
    kind: board.dataset.visionBoardKind,
    id: board.dataset.visionBoardId,
    index: Number(tile.dataset.visionBoardIndex),
    startClientX: event.clientX,
    startClientY: event.clientY,
    startX: Number(tile.style.getPropertyValue("--vision-x")) || 0,
    startY: Number(tile.style.getPropertyValue("--vision-y")) || 0,
    startW: Number(tile.style.getPropertyValue("--vision-w")) || 28,
    rect
  };
  tile.setPointerCapture?.(event.pointerId);
  tile.classList.add("is-moving");
  event.preventDefault();
}

function handleVisionBoardPointerMove(event) {
  const drag = state.visionBoardDrag;
  if (!drag || event.pointerId !== drag.pointerId) return;
  if (drag.mode === "resize") {
    const w = Math.max(10, Math.min(90, drag.startW + (event.clientX - drag.startClientX) / Math.max(1, drag.rect.width) * 100));
    drag.tile.style.setProperty("--vision-w", w.toFixed(2));
  } else {
    const x = Math.max(0, Math.min(90, drag.startX + (event.clientX - drag.startClientX) / Math.max(1, drag.rect.width) * 100));
    const y = Math.max(0, Math.min(88, drag.startY + (event.clientY - drag.startClientY) / Math.max(1, drag.rect.height) * 100));
    drag.tile.style.setProperty("--vision-x", x.toFixed(2));
    drag.tile.style.setProperty("--vision-y", y.toFixed(2));
  }
  event.preventDefault();
}

function handleVisionBoardPointerUp(event) {
  const drag = state.visionBoardDrag;
  if (!drag || event.pointerId !== drag.pointerId) return;
  drag.tile.releasePointerCapture?.(event.pointerId);
  drag.tile.classList.remove("is-moving");
  const x = Number(drag.tile.style.getPropertyValue("--vision-x"));
  const y = Number(drag.tile.style.getPropertyValue("--vision-y"));
  const w = Number(drag.tile.style.getPropertyValue("--vision-w"));
  persistVisionBoardPosition(drag.kind, drag.id, drag.index, x, y, Number.isFinite(w) ? w : undefined);
  state.visionBoardDrag = null;
  event.preventDefault();
}

// Right-click layer menu for focused vision-board tiles: stacking follows the image
// array order, so layer actions are array reorders.
function closeVisionBoardLayerMenu() {
  if (state.visionBoardLayerMenuDismiss) {
    document.removeEventListener("pointerdown", state.visionBoardLayerMenuDismiss, { capture: true });
    state.visionBoardLayerMenuDismiss = null;
  }
  state.visionBoardLayerMenu?.remove?.();
  state.visionBoardLayerMenu = null;
}

function showVisionBoardLayerMenu(event, tile) {
  closeVisionBoardLayerMenu();
  const board = tile.closest(".vision-board-canvas");
  if (!board || !dom.visionBoardDialog) return;
  const kind = board.dataset.visionBoardKind;
  const id = board.dataset.visionBoardId;
  const index = Number(tile.dataset.visionBoardIndex);
  const menu = document.createElement("div");
  menu.className = "vision-board-layer-menu";
  menu.innerHTML = [
    ["front", t("Bring to front")],
    ["forward", t("Bring forward")],
    ["backward", t("Send backward")],
    ["back", t("Send to back")]
  ].map(([action, label]) => `<button type="button" data-vision-layer-action="${action}">${escapeHtml(label)}</button>`).join("");
  const dialogRect = dom.visionBoardDialog.getBoundingClientRect();
  menu.style.left = `${Math.round(event.clientX - dialogRect.left)}px`;
  menu.style.top = `${Math.round(event.clientY - dialogRect.top)}px`;
  menu.addEventListener("click", (clickEvent) => {
    const button = clickEvent.target.closest("[data-vision-layer-action]");
    if (!button) return;
    clickEvent.preventDefault();
    clickEvent.stopPropagation();
    moveVisionBoardImageLayer(kind, id, index, button.dataset.visionLayerAction);
    closeVisionBoardLayerMenu();
  });
  dom.visionBoardDialog.append(menu);
  state.visionBoardLayerMenu = menu;
  // Owned by state so closeVisionBoardLayerMenu() always tears it down — including
  // when a menu item is chosen, not only when the pointer lands outside.
  const dismiss = (pointerEvent) => {
    if (menu.contains(getComposedEventTarget(pointerEvent))) return;
    closeVisionBoardLayerMenu();
  };
  state.visionBoardLayerMenuDismiss = dismiss;
  document.addEventListener("pointerdown", dismiss, { capture: true });
}

function moveVisionBoardImageLayer(kind, id, index, action) {
  if (kind !== "character") return;
  const character = getCharacterById(id);
  const images = getCharacterImages(character);
  if (!character || !images[index]) return;
  const historyBefore = getHistorySnapshot();
  const [entry] = images.splice(index, 1);
  const target = action === "front"
    ? images.length
    : action === "back"
      ? 0
      : action === "forward"
        ? Math.min(images.length, index + 1)
        : Math.max(0, index - 1);
  images.splice(target, 0, entry);
  syncCharacterImageAliases(character, images);
  invalidateCharacterRenderContext();
  setProjectDirty(true);
  renderFocusedVisionBoard();
  renderCharacterGridForSearch();
  commitHistoryFromSnapshot(historyBefore);
  setStatus(t("Image layer updated."));
}

function persistVisionBoardPosition(kind, id, index, x, y, w) {
  const historyBefore = getHistorySnapshot();
  const sizePatch = Number.isFinite(w) ? { w } : {};
  if (kind === "character") {
    const character = getCharacterById(id);
    const images = getCharacterImages(character);
    if (!character || !images[index]) return;
    images[index] = { ...images[index], x, y, ...sizePatch };
    syncCharacterImageAliases(character, images);
    invalidateCharacterRenderContext();
    renderCharacterGridForSearch();
  } else {
    const node = getNode(id);
    const references = getNodeVaultFiles(node);
    const image = references.filter((entry) => CODEX_IMAGE_FILE_PATTERN.test(entry.path))[index];
    const referenceIndex = references.findIndex((entry) => entry.path === image?.path);
    if (!node || referenceIndex < 0) return;
    references[referenceIndex] = { ...references[referenceIndex], x, y, ...sizePatch };
    node.vaultFiles = references;
    if (state.selectedNodeId === node.id) renderNodePanel(node);
  }
  setProjectDirty(true);
  renderFocusedVisionBoard();
  commitHistoryFromSnapshot(historyBefore);
}

function getCodexImageDropElement(event) {
  return event?.target?.closest?.("[data-codex-image-drop]") || null;
}

function handleCodexImageDragOver(event) {
  const dropElement = getCodexImageDropElement(event);
  if (!dropElement) return;
  event.preventDefault();
  event.stopPropagation();
  if (event.dataTransfer) event.dataTransfer.dropEffect = "copy";
  dropElement.classList.add("drag-over");
}

function handleCodexImageDragLeave(event) {
  const dropElement = getCodexImageDropElement(event);
  if (!dropElement || dropElement.contains(event.relatedTarget)) return;
  dropElement.classList.remove("drag-over");
}

async function handleCodexImageDrop(event) {
  const dropElement = getCodexImageDropElement(event);
  if (!dropElement) return;
  event.preventDefault();
  event.stopPropagation();
  dropElement.classList.remove("drag-over");
  const characterId = dropElement.dataset.characterId;
  const transfer = event.dataTransfer;
  const localImages = [...(transfer?.files || [])].filter((file) => isCodexImageFile(file));
  try {
    const references = [];
    if (localImages.length && window.NarrativeCanvasHost?.importCodexImage) {
      for (const file of localImages) {
        references.push(await window.NarrativeCanvasHost.importCodexImage(file, getCharacterById(characterId)?.name || ""));
      }
    }
    if (!references.length) references.push(getCodexImageReferenceFromDataTransfer(transfer));
    if (!assignCodexImageFiles(characterId, references)) setStatus("Drop an image file.");
  } catch (error) {
    console.error(error);
    setStatus("Could not import image.");
  }
}

function isCodexImageFile(file) {
  return Boolean(file && (String(file.type || "").toLowerCase().startsWith("image/") || CODEX_IMAGE_FILE_PATTERN.test(String(file.name || ""))));
}

function getCodexImageReferenceFromDataTransfer(transfer) {
  if (!transfer) return "";
  const preferredTypes = ["application/vnd.obsidian.file", "application/json", "text/plain", "text/uri-list"];
  for (const type of preferredTypes) {
    let value = "";
    try {
      value = transfer.getData(type);
    } catch (_error) {
      value = "";
    }
    const reference = findCodexImageReference(value);
    if (reference) return reference;
  }
  return "";
}

function findCodexImageReference(value, depth = 0) {
  if (depth > 4 || value == null) return "";
  if (Array.isArray(value)) {
    for (const item of value) {
      const reference = findCodexImageReference(item, depth + 1);
      if (reference) return reference;
    }
    return "";
  }
  if (typeof value === "object") {
    const preferredKeys = ["path", "filePath", "filepath", "source", "value"];
    for (const key of preferredKeys) {
      const reference = findCodexImageReference(value[key], depth + 1);
      if (reference) return reference;
    }
    for (const item of Object.values(value)) {
      const reference = findCodexImageReference(item, depth + 1);
      if (reference) return reference;
    }
    return "";
  }
  const source = String(value || "").trim();
  if (!source) return "";
  if ((source.startsWith("{") && source.endsWith("}")) || (source.startsWith("[") && source.endsWith("]"))) {
    try {
      const reference = findCodexImageReference(JSON.parse(source), depth + 1);
      if (reference) return reference;
    } catch (_error) {
      // Continue with plain-text parsing for non-JSON drag payloads.
    }
  }
  const wikiMatch = source.match(/\[\[([^\]|#]+\.(?:avif|bmp|gif|jpe?g|png|svg|webp))(?:#[^\]|]*)?(?:\|[^\]]*)?\]\]/i);
  if (wikiMatch) return normalizeNodeVaultFileReference(wikiMatch[1]);
  for (const line of source.split(/\r?\n/)) {
    const candidate = line.trim().replace(/^file:\/\//i, "").replace(/^['\"]|['\"]$/g, "");
    if (CODEX_IMAGE_FILE_PATTERN.test(candidate)) {
      try {
        return normalizeNodeVaultFileReference(decodeURIComponent(candidate));
      } catch (_error) {
        return normalizeNodeVaultFileReference(candidate);
      }
    }
  }
  return "";
}

async function openNodeVaultFile(nodeId = state.selectedNodeId, index = 0) {
  const node = getNode(nodeId || state.selectedNodeId);
  const host = window.NarrativeCanvasHost;
  const reference = getNodeVaultFiles(node)[Number.isInteger(index) && index >= 0 ? index : 0]?.path;
  if (!reference) {
    setStatus("No linked vault file.");
    return;
  }
  if (!host?.openVaultFile) {
    setStatus("Vault links open only in Obsidian.");
    return;
  }
  try {
    await leaveImmersiveFullscreenForVaultNavigation();
    await host.openVaultFile(reference);
  } catch (error) {
    console.error(error);
    setStatus("Could not open the linked vault file.");
  }
}

async function leaveImmersiveFullscreenForVaultNavigation() {
  const nativeFullscreen = Boolean(document.fullscreenElement || document.webkitFullscreenElement);
  if (!state.immersiveFullscreen && !nativeFullscreen) return;
  if (nativeFullscreen) {
    const exited = await exitNativeFullscreen();
    if (!exited && (document.fullscreenElement || document.webkitFullscreenElement)) {
      throw new Error("Could not exit fullscreen before opening the vault file.");
    }
  }
  if (state.immersiveFullscreen) {
    state.immersiveFullscreen = false;
    renderShellState();
    handleWindowResize();
  }
  await new Promise((resolve) => requestAnimationFrame(() => resolve()));
}

function clearNodeVaultFile(index = 0) {
  const node = getNode(state.selectedNodeId);
  const references = getNodeVaultFiles(node);
  if (!node || !references[index]) return;
  const historyBefore = getHistorySnapshot();
  const [removed] = references.splice(index, 1);
  if (references.length) node.vaultFiles = references;
  else delete node.vaultFiles;
  delete node.vaultFile;
  delete node.vaultFilePreview;
  if (removed?.path) state.vaultFilePreviewCache.delete(removed.path);
  nodeLayoutSizeCache.delete(node);
  setProjectDirty(true);
  renderInspector();
  renderNodes();
  renderLinks();
  renderMinimap();
  setStatus("Vault file link cleared.");
  commitHistoryFromSnapshot(historyBefore);
}

function moveNodeVaultFileReference(fromIndex, targetIndex, placement = "before") {
  const node = getNode(state.selectedNodeId);
  if (!node || !Number.isInteger(fromIndex) || !Number.isInteger(targetIndex)) return false;
  const references = getNodeVaultFiles(node);
  if (fromIndex < 0 || fromIndex >= references.length || targetIndex < 0 || targetIndex >= references.length || fromIndex === targetIndex) return false;
  const insertionBeforeRemoval = targetIndex + (placement === "after" ? 1 : 0);
  const [entry] = references.splice(fromIndex, 1);
  const insertionIndex = clamp(insertionBeforeRemoval - (fromIndex < insertionBeforeRemoval ? 1 : 0), 0, references.length);
  if (insertionIndex === fromIndex) {
    references.splice(fromIndex, 0, entry);
    return false;
  }
  references.splice(insertionIndex, 0, entry);
  node.vaultFiles = references;
  nodeLayoutSizeCache.delete(node);
  setProjectDirty(true);
  renderInspector();
  renderNodes();
  renderLinks();
  renderMinimap();
  setStatus(t("Linked files reordered."));
  return true;
}

// Slider on the node card: `input` events resize the preview live without a re-render
// (the slider must survive its own drag); the final `change` commits and reflows.
// --- Dropping a vault file from Obsidian's UI onto a node -----------------------
// Valid drop zones: a node card on the canvas, or the inspector's Vault file section.
function getVaultFileDropZone(target) {
  if (!target?.closest) return null;
  const nodeElement = target.closest(".node[data-node-id]");
  if (nodeElement && dom.nodeLayer?.contains(nodeElement)) {
    const node = getNode(nodeElement.dataset.nodeId);
    if (node && !isFrameNode(node)) return { nodeId: node.id, element: nodeElement };
  }
  const section = target.closest(".node-vault-file-field");
  if (section && dom.nodePanel?.contains(section)) {
    const node = getNode(state.selectedNodeId);
    if (node && !isFrameNode(node)) return { nodeId: node.id, element: section };
  }
  return null;
}

function parseVaultPathFromDataTransfer(dataTransfer) {
  const text = dataTransfer?.getData?.("text/plain") || "";
  const uri = text.match(/obsidian:\/\/open\?[^\s]*file=([^&\s]+)/);
  if (uri) {
    try { return decodeURIComponent(uri[1]); } catch (_error) { /* fall through */ }
  }
  const wiki = text.match(/^!?\[\[([^\]|#]+)/);
  if (wiki) return wiki[1].trim();
  return "";
}

function clearVaultDropHighlights() {
  dom.scope?.querySelectorAll?.(".vault-file-drop-ready")
    .forEach((element) => element.classList.remove("vault-file-drop-ready"));
}

function handleVaultFileDragOver(event) {
  const host = window.NarrativeCanvasHost;
  if (!host?.searchVaultFiles) return;
  const zone = getVaultFileDropZone(event.target);
  if (!zone) {
    clearVaultDropHighlights();
    return;
  }
  // During dragover the DataTransfer payload is unreadable; accept when Obsidian's
  // drag manager reports a file or when any payload types are present.
  if (!host.getDraggedVaultFile?.() && !(event.dataTransfer?.types || []).length) return;
  event.preventDefault();
  if (event.dataTransfer) event.dataTransfer.dropEffect = "link";
  if (!zone.element.classList.contains("vault-file-drop-ready")) {
    clearVaultDropHighlights();
    zone.element.classList.add("vault-file-drop-ready");
  }
}

function handleVaultFileDrop(event) {
  const host = window.NarrativeCanvasHost;
  if (!host?.searchVaultFiles) return;
  const zone = getVaultFileDropZone(event.target);
  clearVaultDropHighlights();
  if (!zone) return;
  const path = host.getDraggedVaultFile?.() || parseVaultPathFromDataTransfer(event.dataTransfer);
  if (!path) return;
  event.preventDefault();
  event.stopPropagation();
  linkVaultFileToNode(zone.nodeId, path);
}

function linkVaultFileToNode(nodeId, pathValue) {
  const node = getNode(nodeId);
  const path = normalizeNodeVaultFileReference(pathValue);
  if (!node || isFrameNode(node) || !path) return;
  const references = getNodeVaultFiles(node);
  if (references.some((entry) => entry.path === path)) {
    setStatus("File already linked.");
    return;
  }
  const historyBefore = getHistorySnapshot();
  references.push({ path, preview: false, previewSize: 132, ...getDefaultVisionBoardPlacement(references.length) });
  node.vaultFiles = references;
  nodeLayoutSizeCache.delete(node);
  selectNode(nodeId, false);
  setProjectDirty(true);
  renderInspector();
  renderNodes();
  renderLinks();
  renderMinimap();
  commitHistoryFromSnapshot(historyBefore);
  setStatus(t("Vault file linked."));
}

function setNodeVaultPreviewSize(nodeId, index, sizeValue, commit) {
  const node = getNode(nodeId);
  const references = getNodeVaultFiles(node);
  if (!node || !references[index]) return;
  const size = normalizeVaultPreviewSize(sizeValue);
  references[index].previewSize = size;
  node.vaultFiles = references;
  const preview = getNodeElementById(node.id)?.querySelector?.(`[data-node-vault-preview-index="${index}"]`);
  preview?.style?.setProperty("--vault-preview-h", `${size}px`);
  if (!commit) return;
  nodeLayoutSizeCache.delete(node);
  setProjectDirty(true);
  renderNodes();
  renderLinks();
  renderMinimap();
}

function toggleNodeVaultFilePreview(nodeId = state.selectedNodeId, index = 0) {
  const node = getNode(nodeId || state.selectedNodeId);
  const references = getNodeVaultFiles(node);
  if (!references[index] || !window.NarrativeCanvasHost?.readVaultFile) return;
  const historyBefore = getHistorySnapshot();
  references[index] = { ...references[index], preview: !references[index].preview };
  node.vaultFiles = references;
  delete node.vaultFile;
  delete node.vaultFilePreview;
  nodeLayoutSizeCache.delete(node);
  setProjectDirty(true);
  renderNodes();
  renderLinks();
  renderMinimap();
  if (state.selectedNodeId === node.id) renderNodePanel(node);
  setStatus(references[index].preview ? t("Linked file preview enabled.") : t("Linked file preview disabled."));
  commitHistoryFromSnapshot(historyBefore);
}

function setNodeCustomField(key, value, rerender) {
  const node = getNode(state.selectedNodeId);
  if (!node) return;
  const fields = getNodeMeta(node.type).fields || [];
  if (!fields.some((field) => field.key === key)) return;
  invalidateCharacterRenderContext();
  if (key === "choices") {
    node.choices = parseChoiceLines(value);
  } else if (isDirectNodeField(key)) {
    node[key] = value;
  } else {
    if (!node.customFields || typeof node.customFields !== "object" || Array.isArray(node.customFields)) node.customFields = {};
    node.customFields[key] = value;
  }
  const choiceLinksChanged = key === "choices" || key === "condition"
    ? syncChoiceBranchLinksForNode(node.id, { markDirty: false })
    : false;
  setProjectDirty(true);
  renderNodes();
  if (choiceLinksChanged) renderLinks();
  else patchLinkElementRefs(collectLinkElementRefs(getIncidentLinks(node.id)));
  markCanvasSurfaceRenderedIfActive();
  scheduleStoryPanelRender();
  renderProjectPanel();
  updateStatus();
  if (rerender) renderNodePanel(node);
}

function setEventField(nodeId, field, value, rerender) {
  const node = getNode(nodeId);
  const column = node
    ? (getEventSheetColumns(node.type).find((item) => item.key === field)
      || getEventSheetColumns().find((item) => item.key === field))
    : null;
  if (!node || !column || column.readonly) return;
  invalidateCharacterRenderContext();
  if (column.custom && !isDirectNodeField(field)) {
    if (!node.customFields || typeof node.customFields !== "object" || Array.isArray(node.customFields)) node.customFields = {};
    node.customFields[field] = value;
  } else if (field === "choices") {
    node.choices = parseChoiceLines(value);
  } else {
    node[field] = value;
  }
  if (field === "eventDescription" && !node.body) node.body = value;
  if (field === "choices" || field === "condition") syncChoiceBranchLinksForNode(node.id, { markDirty: false });
  setProjectDirty(true);
  renderNodes();
  if (isCanvasFileActive()) {
    renderLinks();
    markCanvasSurfaceRendered();
  }
  renderStoryPanel();
  renderProjectPanel();
  updateStatus();
  if (rerender && state.activeFileId === "events") renderEventsSheetPage();
  if (rerender && state.selectedNodeId === nodeId) renderNodePanel(node);
}

function duplicateSelectedNode() {
  const node = getNode(state.selectedNodeId);
  if (!node) return;
  const copy = { ...cloneProject(node), id: nextId("n", state.project.nodes), x: node.x + 42, y: node.y + 42 };
  state.project.nodes.push(copy);
  invalidateCharacterRenderContext();
  selectNode(copy.id);
  setStatus("Node duplicated.");
}

function deleteSelectedNode() {
  if (!state.selectedNodeId) return;
  const id = state.selectedNodeId;
  const node = getNode(id);
  if (!node) return;
  const targets = getDeletionReferenceTargets([id]);
  const refs = collectNodeTargetReferences(targets);
  if (refs.length) {
    showGenericConfirm({
      kicker: "References",
      title: t('Delete "{title}"?', { title: node.title || getNodeDisplayId(node) }),
      message: t("{references} point to this node. Delete and clear those references, or keep the references as orphan warnings.", {
        references: formatReferenceSummary(refs)
      }),
      confirmLabel: "Delete and clear references",
      secondaryLabel: "Keep orphan references",
      danger: true,
      recordHistory: true,
      onConfirm: () => deleteSelectedNodeConfirmed(id, { removeReferences: true }),
      onSecondary: () => deleteSelectedNodeConfirmed(id, { removeReferences: false })
    });
    return;
  }
  deleteSelectedNodeConfirmed(id, { removeReferences: false });
}

function deleteSelectedNodeConfirmed(id, options = {}) {
  if (options.removeReferences) removeNodeTargetReferences([id]);
  archiveDeletedNode(id);
  reparentChildrenOfDeletedFrames(new Set([id]));
  state.project.nodes = state.project.nodes.filter((node) => node.id !== id);
  state.project.links = state.project.links.filter((link) => link.from !== id && link.to !== id);
  markProjectStructureChanged();
  invalidateCharacterRenderContext();
  clearStoryOrderOverrides();
  clearEventRowOrderOverrides();
  clearNodeSelection();
  renderAll();
  refreshOpenPreviewEntrySelector();
  setStatus("Node deleted and archived outside runtime.");
}

function archiveDeletedNode(id) {
  const node = getNode(id);
  if (!node) return;
  const removedLinks = state.project.links.filter((link) => link.from === id || link.to === id);
  if (!Array.isArray(state.project.deletedNodes)) state.project.deletedNodes = [];
  state.project.deletedNodes.unshift({
    deletedAt: new Date().toISOString(),
    node: cloneProject(node),
    links: cloneProject(removedLinks)
  });
  state.project.deletedNodes = state.project.deletedNodes.slice(0, 50);
}

function deleteSelectedLink() {
  if (!state.selectedLinkId) return;
  state.project.links = state.project.links.filter((link) => link.id !== state.selectedLinkId);
  clearStoryOrderOverrides();
  clearEventRowOrderOverrides();
  state.selectedLinkId = null;
  renderAll();
  setStatus("Link deleted.");
}

function deleteContextLink() {
  const linkId = state.contextLinkId || state.selectedLinkId;
  if (!linkId) return;
  state.project.links = state.project.links.filter((link) => link.id !== linkId);
  clearStoryOrderOverrides();
  clearEventRowOrderOverrides();
  state.selectedLinkId = null;
  clearLinkReconnect();
  hideNodeContextMenu();
  renderAll();
  setStatus("Link deleted.");
}

function assignChoiceLink(linkId, choiceIndexValue) {
  const link = getLink(linkId || state.contextLinkId || state.selectedLinkId);
  const source = link ? getNode(link.from) : null;
  const choiceIndex = normalizeChoiceIndex(choiceIndexValue);
  const branchLabels = getBranchLabels(source);
  if (!link || choiceIndex == null || !branchLabels[choiceIndex]) {
    setStatus("Could not assign branch.");
    return;
  }
  link.choiceIndex = choiceIndex;
  link.label = branchLabels[choiceIndex];
  syncChoiceBranchLinksForNode(link.from, { markDirty: false, preferredLinkId: link.id });
  state.selectedLinkId = link.id;
  clearNodeSelection();
  clearStoryOrderOverrides();
  clearEventRowOrderOverrides();
  hideNodeContextMenu();
  renderAll();
  setProjectDirty(true);
  setStatus(`Branch set: ${branchLabels[choiceIndex]}.`);
}

function startLinkReconnect(end) {
  const link = getLink(state.contextLinkId || state.selectedLinkId);
  if (!link || !["from", "to"].includes(end)) return;
  state.reconnectingLinkId = link.id;
  state.reconnectingEnd = end;
  state.selectedLinkId = link.id;
  hideNodeContextMenu();

  if (end === "to") {
    state.connectingFrom = link.from;
    state.connectingTo = getOutputPoint(getNode(link.from));
    dom.hint.textContent = "Click a new input port to reconnect this link.";
  } else {
    state.connectingFrom = null;
    state.connectingTo = null;
    dom.hint.textContent = "Click a new output port to reconnect this link.";
  }

  dom.hint.classList.add("show");
  renderLinks();
  setStatus(end === "to" ? "Choose a new input port." : "Choose a new output port.");
}

function finishLinkReconnect(link) {
  clearStoryOrderOverrides();
  clearEventRowOrderOverrides();
  state.selectedLinkId = link.id;
  clearNodeSelection();
  clearLinkReconnect();
  renderAll();
  setStatus("Link reconnected.");
}

function clearLinkReconnect() {
  state.reconnectingLinkId = null;
  state.reconnectingEnd = null;
  state.connectingFrom = null;
  state.connectingTo = null;
  if (dom.hint) {
    dom.hint.textContent = "Click an output port, then an input port to connect nodes.";
    dom.hint.classList.remove("show");
  }
}

function focusSelectedNode() {
  const node = getNode(state.selectedNodeId);
  if (!node) return;
  state.activeFileId = "adventure";
  state.panel = "node";
  renderAll();
  centerCanvasOnNode(node, NODE_FOCUS_ZOOM, { immediate: true });
  setStatus(`${node.title || getNodeDisplayId(node)} focused.`);
}

function focusSelectedNodeInDocument() {
  const node = getNode(state.selectedNodeId);
  if (!node || isFrameNode(node)) return;
  selectFile("document");
  const editor = dom.documentPanel?.querySelector("[data-document-source]");
  const range = editor
    ? findDocumentNodeTitleRange(editor.value, state.documentFormat, node.id)
    : null;
  if (!editor || !range) {
    setStatus(t("Could not find this node in Document."));
    return;
  }
  focusDocumentSourceRange(editor, range);
  setStatus(t("Focused {title} in Document.", { title: node.title || getNodeDisplayId(node) }));
}

function findDocumentNodeTitleRange(source, format, nodeId) {
  const lines = getDocumentSourceLines(source);
  const id = String(nodeId || "").trim();
  if (!id) return null;
  const normalizedFormat = normalizeDocumentFormat(format);
  if (normalizedFormat === "plain") {
    const idIndex = lines.findIndex((line) => line.text.match(/^<!--\s*id:\s*(.*?)\s*-->$/)?.[1]?.trim() === id);
    if (idIndex < 1) return null;
    return getDocumentCapturedRange(lines[idIndex - 1], /^(##\s+)(.*?)(\s*)$/, 2);
  }
  if (normalizedFormat === "yarn") {
    const idIndex = lines.findIndex((line) => line.text.match(/^narrativeCanvasId:\s*(.*?)\s*$/)?.[1]?.trim() === id);
    if (idIndex < 0) return null;
    for (let index = idIndex + 1; index < lines.length && !/^---\s*$/.test(lines[index].text); index += 1) {
      const range = getDocumentCapturedRange(lines[index], /^(nodeTitle:\s*)(.*?)(\s*)$/, 2);
      if (range) return trimDocumentLiteralQuotes(source, range);
    }
    return null;
  }
  if (normalizedFormat === "ink") {
    const idIndex = lines.findIndex((line) => line.text.match(/^\/\/\s*narrativeCanvasId:\s*(.*?)\s*$/)?.[1]?.trim() === id);
    if (idIndex < 0) return null;
    for (let index = idIndex + 1; index < lines.length && !/^===\s+/.test(lines[index].text); index += 1) {
      const range = getDocumentCapturedRange(lines[index], /^(\/\/\s*nodeTitle:\s*)(.*?)(\s*)$/, 2);
      if (range) return trimDocumentLiteralQuotes(source, range);
    }
    return null;
  }
  const idIndex = lines.findIndex((line) => line.text.match(/^<!--\s*narrativeCanvasId:\s*(.*?)\s*-->$/)?.[1]?.trim() === id);
  if (idIndex < 0) return null;
  for (let index = idIndex + 1; index < lines.length && !/^::\s+/.test(lines[index].text); index += 1) {
    const range = getDocumentCapturedRange(lines[index], /^(<!--\s*narrativeCanvasTitle:\s*)(.*?)(\s*-->)$/, 2);
    if (range) return range;
  }
  return null;
}

function getDocumentSourceLines(source) {
  const text = String(source || "");
  const lines = [];
  let start = 0;
  text.split("\n").forEach((line) => {
    lines.push({ text: line, start, end: start + line.length });
    start += line.length + 1;
  });
  return lines;
}

function getDocumentCapturedRange(line, pattern, groupIndex) {
  const match = line?.text?.match(pattern);
  const value = match?.[groupIndex];
  if (value == null) return null;
  const relativeStart = match[0].indexOf(value, (match[1] || "").length);
  if (relativeStart < 0) return null;
  return {
    start: line.start + relativeStart,
    end: line.start + relativeStart + value.length
  };
}

function trimDocumentLiteralQuotes(source, range) {
  if (!range || range.end - range.start < 2) return range;
  const text = String(source || "");
  return text[range.start] === '"' && text[range.end - 1] === '"'
    ? { start: range.start + 1, end: range.end - 1 }
    : range;
}

function focusDocumentSourceRange(editor, range) {
  const start = Math.max(0, Math.min(editor.value.length, Number(range?.start) || 0));
  const end = Math.max(start, Math.min(editor.value.length, Number(range?.end) || start));
  const lineHeight = getDocumentEditorLineHeight(editor);
  const lineIndex = editor.value.slice(0, start).split("\n").length - 1;
  editor.scrollTop = Math.max(0, lineIndex * lineHeight - editor.clientHeight / 2);
  editor.scrollLeft = 0;
  try {
    editor.focus({ preventScroll: true });
    editor.setSelectionRange(start, end);
  } catch (_error) {
    // no-op for embedded WebViews without selection support
  }
  syncDocumentEditorGutter(editor);
  syncDocumentOverlayScroll(editor);
}

function centerCanvasOnNode(node, scale = state.view.scale, options = {}) {
  const size = nodeSize(node);
  centerCanvasOnBoardPoint(node.x + size.width / 2, node.y + size.height / 2, scale, options);
}

function centerCanvasOnBoardPoint(boardX, boardY, scale = state.view.scale, options = {}) {
  resetCanvasScroll();
  const rect = dom.viewport.getBoundingClientRect();
  state.view.scale = clamp(scale, CANVAS_MIN_ZOOM, CANVAS_MAX_ZOOM);
  state.view.x = rect.width / 2 - boardX * state.view.scale;
  state.view.y = rect.height / 2 - boardY * state.view.scale;
  renderTransform();
  updateGridPosition();
  if (options.immediate) renderCanvasViewportNow();
  else scheduleCanvasViewportRender();
}

function handleMinimapPointerDown(event) {
  event.preventDefault();
  event.stopPropagation();
  const point = minimapPointToBoard(event.clientX, event.clientY);
  centerCanvasOnBoardPoint(point.x, point.y);
  setStatus("Canvas moved from minimap.");
}

function minimapPointToBoard(clientX, clientY) {
  const rect = dom.minimap.getBoundingClientRect();
  const bounds = getCanvasScrollableBoardBounds();
  const x = bounds.left + clamp((clientX - rect.left) / Math.max(rect.width, 1), 0, 1) * bounds.width;
  const y = bounds.top + clamp((clientY - rect.top) / Math.max(rect.height, 1), 0, 1) * bounds.height;
  return { x, y };
}

function openNodeInspector() {
  const inspectNodeId = state.selectedNodeId || (state.selectedNodeIds.length === 1 ? state.selectedNodeIds[0] : null);
  if (!getNode(inspectNodeId)) {
    if (state.panel === "node") {
      state.panel = "project";
      renderInspector();
    }
    showNodeRequiredDialog();
    return;
  }
  state.selectedNodeId = inspectNodeId;
  state.selectedNodeIds = [];
  focusSelectedNode();
}

function centerView(announce = true) {
  const bounds = getProjectBounds();
  resetCanvasScroll();
  const rect = dom.viewport.getBoundingClientRect();
  const availableWidth = Math.max(rect.width - CANVAS_VIEW_PADDING * 2, 1);
  const availableHeight = Math.max(rect.height - CANVAS_VIEW_PADDING * 2, 1);
  const scaleX = availableWidth / Math.max(bounds.width, 1);
  const scaleY = availableHeight / Math.max(bounds.height, 1);
  state.view.scale = clamp(Math.min(scaleX, scaleY, CANVAS_MAX_AUTO_SCALE), CANVAS_MIN_AUTO_SCALE, CANVAS_MAX_AUTO_SCALE);
  state.view.x = getCanvasAxisOffset(bounds.x, bounds.width, state.view.scale, rect.width);
  state.view.y = getCanvasAxisOffset(bounds.y, bounds.height, state.view.scale, rect.height);
  renderTransform();
  updateGridPosition();
  scheduleCanvasViewportRender();
  renderProjectPanel();
  if (announce) setStatus("Canvas centered.");
}

function centerViewAtScale(scale = DEFAULT_CANVAS_ZOOM, announce = false) {
  const bounds = getProjectBounds();
  resetCanvasScroll();
  const rect = dom.viewport.getBoundingClientRect();
  state.view.scale = clamp(scale, CANVAS_MIN_ZOOM, CANVAS_MAX_ZOOM);
  state.view.x = getCanvasAxisOffset(bounds.x, bounds.width, state.view.scale, rect.width);
  state.view.y = getCanvasAxisOffset(bounds.y, bounds.height, state.view.scale, rect.height);
  renderTransform();
  updateGridPosition();
  scheduleCanvasViewportRender();
  renderProjectPanel();
  if (announce) setStatus("Canvas centered.");
}

function autoLayoutCanvas(orientation = "horizontal") {
  if (!state.project.nodes.length) {
    setStatus("No nodes to arrange.");
    return;
  }

  const direction = orientation === "vertical" ? "vertical" : "horizontal";
  const frameChildren = getAutoLayoutFrameChildren();
  const layoutItems = state.project.nodes.filter((node) => !isFrameNode(node) || !(frameChildren.get(node.id) || []).length);
  const depths = getAutoLayoutDepths(layoutItems);

  positionAutoLayoutItems(layoutItems, depths, direction);
  fitAutoLayoutFrames(frameChildren);

  state.activeFileId = "adventure";
  markProjectStructureChanged();
  renderAll();
  centerView(false);
  setStatus(direction === "horizontal" ? "Canvas arranged horizontally." : "Canvas arranged vertically.");
}

function getAutoLayoutFrameChildren() {
  const frames = state.project.nodes.filter((node) => isFrameNode(node));
  const frameChildren = new Map(frames.map((frame) => [frame.id, []]));
  state.project.nodes.forEach((node) => {
    const parentId = normalizeOptionalString(node.frameId).trim();
    if (parentId && frameChildren.has(parentId)) frameChildren.get(parentId)?.push(node.id);
  });
  return frameChildren;
}

function getAutoLayoutDepths(items) {
  const itemIds = new Set(items.map((node) => node.id));
  const depths = new Map();
  const roots = getAutoLayoutRoots(items, itemIds);
  const queue = [];

  roots.forEach((node) => {
    depths.set(node.id, 0);
    queue.push(node.id);
  });

  while (queue.length) {
    const id = queue.shift();
    const depth = depths.get(id) || 0;
    getOutgoing(id).forEach((link) => {
      if (!itemIds.has(link.to) || depths.has(link.to)) return;
      depths.set(link.to, depth + 1);
      queue.push(link.to);
    });
  }

  const maxDepth = depths.size ? Math.max(...depths.values()) : 0;
  getSortedAutoLayoutItems(items).forEach((node) => {
    if (!depths.has(node.id)) depths.set(node.id, maxDepth + 1);
  });
  return depths;
}

function getAutoLayoutRoots(items, itemIds) {
  const incoming = new Set(
    state.project.links
      .filter((link) => itemIds.has(link.from) && itemIds.has(link.to))
      .map((link) => link.to)
  );
  const roots = items.filter((node) => !incoming.has(node.id));
  const entry = items.find((node) => node.type === "Entry");
  if (!entry) return roots.length ? getSortedAutoLayoutItems(roots) : getSortedAutoLayoutItems(items).slice(0, 1);
  return [entry, ...getSortedAutoLayoutItems(roots.filter((node) => node.id !== entry.id))];
}

function positionAutoLayoutItems(items, depths, direction) {
  const ranks = [...new Set(depths.values())].sort((a, b) => a - b);
  const startX = getAutoLayoutStart(items, "x", 80);
  const startY = getAutoLayoutStart(items, "y", 120);

  if (direction === "vertical") {
    let y = startY;
    ranks.forEach((rank) => {
      const rankItems = getSortedAutoLayoutItems(items.filter((node) => depths.get(node.id) === rank));
      let x = startX;
      const rowHeight = Math.max(...rankItems.map((node) => nodeSize(node).height), 0);
      rankItems.forEach((node) => {
        node.x = Math.round(x);
        node.y = Math.round(y);
        x += nodeSize(node).width + AUTO_LAYOUT_NODE_GAP;
      });
      y += rowHeight + AUTO_LAYOUT_RANK_GAP;
    });
    return;
  }

  let x = startX;
  ranks.forEach((rank) => {
    const rankItems = getSortedAutoLayoutItems(items.filter((node) => depths.get(node.id) === rank));
    let y = startY;
    const columnWidth = Math.max(...rankItems.map((node) => nodeSize(node).width), 0);
    rankItems.forEach((node) => {
      node.x = Math.round(x);
      node.y = Math.round(y);
      y += nodeSize(node).height + AUTO_LAYOUT_NODE_GAP;
    });
    x += columnWidth + AUTO_LAYOUT_RANK_GAP;
  });
}

function getAutoLayoutStart(items, key, fallback) {
  const values = items.map((node) => Number(node[key])).filter(Number.isFinite);
  if (!values.length) return fallback;
  return Math.max(40, Math.min(...values));
}

function getSortedAutoLayoutItems(items) {
  const storyOrder = new Map(getReachableStory().map((node, index) => [node.id, index]));
  return [...items].sort((a, b) => {
    const storyA = storyOrder.get(a.id) ?? Number.POSITIVE_INFINITY;
    const storyB = storyOrder.get(b.id) ?? Number.POSITIVE_INFINITY;
    if (storyA !== storyB) return storyA - storyB;
    return a.y - b.y || a.x - b.x || a.id.localeCompare(b.id);
  });
}

function fitAutoLayoutFrames(frameChildren) {
  const frames = state.project.nodes
    .filter((node) => isFrameNode(node))
    .sort((a, b) => getAutoLayoutFrameDepth(b.id, frameChildren) - getAutoLayoutFrameDepth(a.id, frameChildren));

  frames.forEach((frame) => {
    const children = (frameChildren.get(frame.id) || [])
      .map(getNode)
      .filter((node) => node && node.id !== frame.id);
    if (!children.length) return;
    const bounds = getCombinedNodeBounds(children);
    frame.x = Math.max(40, Math.round(bounds.left - AUTO_LAYOUT_FRAME_PADDING));
    frame.y = Math.max(40, Math.round(bounds.top - AUTO_LAYOUT_FRAME_PADDING - AUTO_LAYOUT_FRAME_HEADER));
    frame.width = Math.max(minNodeWidth(frame), Math.round(bounds.right - frame.x + AUTO_LAYOUT_FRAME_PADDING));
    frame.height = Math.max(minNodeHeight(frame), Math.round(bounds.bottom - frame.y + AUTO_LAYOUT_FRAME_PADDING));
  });
}

function getAutoLayoutFrameDepth(frameId, frameChildren, seen = new Set()) {
  if (seen.has(frameId)) return 0;
  seen.add(frameId);
  for (const [parentId, childIds] of frameChildren.entries()) {
    if (childIds.includes(frameId)) return 1 + getAutoLayoutFrameDepth(parentId, frameChildren, seen);
  }
  return 0;
}

function getCombinedNodeBounds(nodes) {
  const bounds = nodes.map(getNodeBounds);
  return {
    left: Math.min(...bounds.map((item) => item.left)),
    top: Math.min(...bounds.map((item) => item.top)),
    right: Math.max(...bounds.map((item) => item.right)),
    bottom: Math.max(...bounds.map((item) => item.bottom))
  };
}

function settleInitialCanvasView() {
  centerViewAtScale(DEFAULT_CANVAS_ZOOM, false);
  const schedule = window.requestAnimationFrame?.bind(window) || ((callback) => setTimeout(callback, 0));
  schedule(() => {
    centerViewAtScale(DEFAULT_CANVAS_ZOOM, false);
    schedule(() => centerViewAtScale(DEFAULT_CANVAS_ZOOM, false));
  });
}

function getCanvasAxisOffset(origin, size, scale, viewportSize) {
  const scaledSize = size * scale;
  if (scaledSize + CANVAS_VIEW_PADDING * 2 > viewportSize) {
    return CANVAS_VIEW_PADDING - origin * scale;
  }
  return (viewportSize - scaledSize) / 2 - origin * scale;
}

function setZoom(value) {
  const rect = dom.viewport.getBoundingClientRect();
  const centerX = rect.left + rect.width / 2;
  const centerY = rect.top + rect.height / 2;
  const before = screenToBoard(centerX, centerY);
  state.view.scale = clamp(value, CANVAS_MIN_ZOOM, CANVAS_MAX_ZOOM);
  state.view.x = centerX - rect.left + dom.viewport.scrollLeft - before.x * state.view.scale;
  state.view.y = centerY - rect.top + dom.viewport.scrollTop - before.y * state.view.scale;
  renderTransform();
  updateGridPosition();
  scheduleCanvasViewportRender();
  renderProjectPanel();
}

function toggleTheme() {
  state.theme = state.theme === "light" ? "dark" : "light";
  renderShellState();
  renderTransform();
  updateGridPosition();
}

function snapCanvasValue(value, options = {}) {
  const enabled = options.enabled ?? state.snapToGrid;
  if (!enabled) return Math.round(value);
  return Math.round(Number(value || 0) / CANVAS_GRID_SIZE) * CANVAS_GRID_SIZE;
}

function toggleSnapToGrid() {
  state.snapToGrid = !state.snapToGrid;
  renderShellState();
  setProjectDirty(true);
  setStatus(t(state.snapToGrid ? "Grid snapping enabled." : "Grid snapping disabled."));
}

function toggleLanguage() {
  setLanguage(state.language === "zh" ? "en" : "zh");
}

function normalizeExportImageScale(value) {
  const numeric = Number(value);
  const preset = EXPORT_IMAGE_SCALES.find((item) => item.scale === numeric || item.value === String(value));
  return preset ? preset.scale : 1;
}

function getExportImageScalePreset(scale = state.exportImageScale) {
  return EXPORT_IMAGE_SCALES.find((item) => item.scale === normalizeExportImageScale(scale)) || EXPORT_IMAGE_SCALES[0];
}

function setExportImageScale(value) {
  const preset = getExportImageScalePreset(value);
  state.exportImageScale = preset.scale;
  renderShellState();
  setStatus(`Image export maximum set to ${preset.label}.`);
}

function updateGridPosition() {
  const scrollLeft = dom.viewport?.scrollLeft || 0;
  const scrollTop = dom.viewport?.scrollTop || 0;
  dom.viewport.style.backgroundPosition = `${state.view.x - scrollLeft}px ${state.view.y - scrollTop}px`;
}

function resetCanvasScroll() {
  if (!dom.viewport) return;
  try {
    dom.viewport.scrollTo(0, 0);
  } catch (error) {
    try {
      dom.viewport.scrollTo({ left: 0, top: 0, behavior: "auto" });
    } catch (innerError) {
      // Fall through to direct assignment.
    }
  }
  dom.viewport.scrollLeft = 0;
  dom.viewport.scrollTop = 0;
}

function createBlankProject(title = "Untitled") {
  const projectTitle = normalizeNewProjectTitle(title);
  return {
    title: projectTitle,
    richTextFormat: normalizeRichTextFormat(window.NarrativeCanvasHost?.getRichTextFormat?.()),
    notes: "",
    variables: defaultVariables(),
    nodeTypes: visibleDefaultNodeTypeList(),
    customNodeTypes: [],
    characters: [],
    nodes: [normalizeNode({ id: "n0", type: "Entry", title: "Start", body: "Adventure Begins", x: 120, y: 120 })],
    links: []
  };
}

function normalizeNewProjectTitle(value) {
  return String(value || "").trim() || "Untitled";
}

function getNewProjectTitleInput() {
  return normalizeNewProjectTitle(dom.newProjectNameInput?.value);
}

async function newProject(title = "Untitled") {
  const projectTitle = normalizeNewProjectTitle(title);
  state.project = createBlankProject(projectTitle);
  markProjectStructureChanged({ nodeTypes: true });
  state.selectedNodeId = "n0";
  state.selectedLinkId = null;
  state.panel = "project";
  state.activeFileId = "adventure";
  centerViewAtScale(DEFAULT_CANVAS_ZOOM, false);
  resetHistory();
  setProjectDirty(true);
  renderAll();
  setStatus("Creating new project file...");
  const target = await createVaultProjectForNewProject();
  renderProjectFileStatus();
  if (!target && window.NarrativeCanvasHost?.createProjectFile) {
    setStatus("New project created, but vault file creation failed.");
  } else if (!target) {
    setStatus("New project created.");
  }
}

function showNewProjectConfirm() {
  if (dom.newProjectNameInput) {
    dom.newProjectNameInput.value = "Untitled";
  }
  updateNewProjectPathPreview();
  if (dom.confirmDialog?.showModal) {
    dom.confirmDialog.returnValue = "";
    dom.confirmDialog.showModal();
    runAfterRender(() => {
      dom.newProjectNameInput?.focus();
      dom.newProjectNameInput?.select();
    });
    return;
  }
  showGenericConfirm({
    kicker: "New Canvas",
    title: "Create a blank project?",
    message: "Discard the current canvas and create a blank one?",
    confirmLabel: "Create",
    danger: true,
    onConfirm: () => newProject("Untitled")
  });
}

function confirmNewProject() {
  if (dom.confirmDialog?.open) {
    dom.confirmDialog.returnValue = "handled";
    dom.confirmDialog.close("handled");
  }
  void newProject(getNewProjectTitleInput());
}

function closeNewProjectConfirm() {
  if (dom.confirmDialog?.open) {
    dom.confirmDialog.returnValue = "cancel";
    dom.confirmDialog.close("cancel");
  }
}

async function updateNewProjectPathPreview() {
  if (!dom.newProjectPathPreview) return;
  const host = window.NarrativeCanvasHost;
  const projectTitle = getNewProjectTitleInput();
  const project = createBlankProject(projectTitle);
  if (!host?.previewNewProjectFile) {
    dom.newProjectPathPreview.textContent = host
      ? t("A new .ncanvas file will be created from the plugin save settings.")
      : t("The new project will use browser storage until you save or export it.");
    return;
  }
  try {
    const target = await host.previewNewProjectFile(JSON.stringify(buildSavedStateForProject(project), null, 2), {
      filenameProjectTitle: projectTitle
    });
    dom.newProjectPathPreview.textContent = target
      ? t("New file: {target}", { target })
      : t("A new .ncanvas file will be created from the plugin save settings.");
  } catch (error) {
    console.error(error);
    dom.newProjectPathPreview.textContent = t("Could not preview the new project file name.");
  }
}

function showNodeRequiredDialog() {
  if (dom.nodeRequiredDialog?.showModal) {
    if (!dom.nodeRequiredDialog.open) dom.nodeRequiredDialog.showModal();
    return;
  }
  setStatus("Select a node first to open the Node inspector.");
}

async function saveCurrentState(options = {}) {
  const silent = Boolean(options.silent);
  clearAutoSaveTimer();
  const dirtyVersionAtStart = state.dirtyVersion;
  state.isSaving = true;
  state.saveError = false;
  renderProjectFileStatus();

  const savedState = buildSavedState();
  const savedStateJson = JSON.stringify(savedState, null, 2);
  try {
    const host = window.NarrativeCanvasHost;
    if (host?.saveState || host?.saveProject) {
      const targets = [];
      if (host.saveProject) {
        const projectTarget = await host.saveProject(savedStateJson);
        if (projectTarget) targets.push(projectTarget);
        await reloadCodexFiles({ render: state.activeFileId === "characters", silent: true, markDirty: false });
      } else if (host.saveState) {
        const stateTarget = await host.saveState(savedState);
        if (stateTarget) targets.push(stateTarget);
      }
      finishSuccessfulSave(dirtyVersionAtStart);
      if (!silent) setStatus(targets.length ? `Project saved to ${targets.join(" and ")}.` : "Project saved.");
      return true;
    }
    saveWebState(savedState);
    finishSuccessfulSave(dirtyVersionAtStart);
    if (!silent) setStatus("Project saved.");
    return true;
  } catch (error) {
    console.error(error);
    state.isSaving = false;
    state.saveError = true;
    if (error?.code === "NARRATIVE_CANVAS_PROJECT_CONFLICT") state.externalProjectChangePending = true;
    renderProjectFileStatus();
    if (!state.externalProjectChangePending) scheduleAutoSave();
    if (!silent) setStatus(error?.code === "NARRATIVE_CANVAS_PROJECT_CONFLICT" ? error.message : "Project save failed.");
    return false;
  }
}

function finishSuccessfulSave(dirtyVersionAtStart) {
  state.isSaving = false;
  state.saveError = false;
  if (state.dirtyVersion === dirtyVersionAtStart) {
    setProjectDirty(false);
    return;
  }
  state.hasUnsavedChanges = true;
  renderProjectFileStatus();
  scheduleAutoSave();
}

async function createVaultProjectForNewProject() {
  const host = window.NarrativeCanvasHost;
  if (!host?.createProjectFile) return "";
  try {
    const projectTitle = state.project?.title || "Untitled";
    const target = await host.createProjectFile(JSON.stringify(buildSavedState(), null, 2), {
      filenameProjectTitle: projectTitle
    });
    if (target) {
      await reloadCodexFiles({ render: state.activeFileId === "characters", silent: true, markDirty: false });
      setProjectDirty(false);
      renderProjectFileStatus();
      setStatus(`New project created at ${target}.`);
    }
    return target || "";
  } catch (error) {
    console.error(error);
    setStatus("New project created, but vault JSON creation failed.");
    renderProjectFileStatus();
    return "";
  }
}

async function createSampleProjectFile() {
  const project = getSampleProject(state.language);
  state.project = cloneProject(project);
  markProjectStructureChanged({ nodeTypes: true });
  state.selectedNodeId = state.project.nodes[0]?.id || null;
  state.selectedLinkId = null;
  state.panel = "project";
  state.activeFileId = "adventure";
  centerViewAtScale(DEFAULT_CANVAS_ZOOM, false);
  resetHistory();
  setProjectDirty(true);
  renderAll();

  const host = window.NarrativeCanvasHost;
  if (!host?.createProjectFile) {
    saveWebState(buildSavedState());
    setProjectDirty(false);
    setStatus("Sample project loaded in browser storage.");
    return true;
  }

  try {
    setStatus("Creating sample project...");
    const target = await host.createProjectFile(JSON.stringify(buildSavedState(), null, 2), {
      filenameOverride: getSampleProjectFilename(state.language),
      filenameProjectTitle: project.title
    });
    setProjectDirty(false);
    renderProjectFileStatus();
    setStatus(target ? `Sample project created at ${target}.` : "Sample project opened.");
    return true;
  } catch (error) {
    console.error(error);
    setStatus("Sample project creation failed.");
    renderProjectFileStatus();
    return false;
  }
}

async function loadCurrentVaultProject() {
  const restoredView = await loadFromVault(true);
  if (restoredView === null) return false;
  if (!state.selectedNodeId) state.selectedNodeId = state.project.nodes[0]?.id || null;
  resetHistory();
  renderAll();
  if (!restoredView) settleInitialCanvasView();
  return true;
}

async function reloadCodexFiles(options = {}) {
  const host = window.NarrativeCanvasHost;
  if (!host?.loadCodexEntries) return false;
  try {
    const loaded = await host.loadCodexEntries();
    if (!Array.isArray(loaded) || !loaded.length) return false;
    const current = getCharacters();
    const currentById = new Map(current.map((entry) => [entry.id, entry]));
    let changed = false;
    loaded.forEach((source, index) => {
      const external = normalizeCharacter(source, index);
      if (!external) return;
      const existing = currentById.get(external.id);
      if (existing) {
        if (JSON.stringify(existing) !== JSON.stringify(external)) {
          Object.assign(existing, external);
          changed = true;
        }
        return;
      }
      current.push(external);
      currentById.set(external.id, external);
      changed = true;
    });
    if (!changed) return false;
    state.project.characters = normalizeCharacters(current);
    invalidateCharacterRenderContext();
    if (options.markDirty !== false) setProjectDirty(true);
    if (options.render !== false) renderCharacterAwareSurfaces();
    if (!options.silent) setStatus(t("Library files reloaded."));
    return true;
  } catch (error) {
    console.error(error);
    if (!options.silent) setStatus(t("Could not reload library files."));
    return false;
  }
}

async function loadSavedState(announce = true) {
  const host = window.NarrativeCanvasHost;
  if (host?.loadProject) {
    const restoredVaultView = await loadFromVault(announce);
    if (restoredVaultView !== null) return restoredVaultView;
    return false;
  }

  if (host?.loadState) {
    try {
      const saved = await host.loadState();
      if (saved) {
        const restoredView = applySavedState(saved);
        setProjectDirty(false);
        if (announce) setStatus(`Loaded ${host.stateFile || "saved state"}.`);
        return restoredView;
      }
    } catch (error) {
      console.error(error);
      if (announce) setStatus("Could not load saved state.");
    }
  }

  if (!host && shouldLoadWebState()) {
    const saved = loadWebState();
    if (saved) {
      const restoredView = applySavedState(saved);
      setProjectDirty(false);
      if (announce) setStatus("Loaded browser saved state.");
      return restoredView;
    }
  }

  return false;
}

function shouldLoadWebState() {
  try {
    return !new URLSearchParams(window.location.search).has("smoke");
  } catch (_error) {
    return true;
  }
}

function buildSavedState() {
  state.project = normalizeProject(state.project);
  return buildSavedStateForProject(state.project, {
    selectedNodeId: state.selectedNodeId,
    selectedLinkId: state.selectedLinkId,
    panel: state.panel,
    activeFileId: state.activeFileId,
    theme: state.theme,
    exportImageScale: state.exportImageScale,
    snapToGrid: state.snapToGrid,
    view: { ...state.view },
    sidebar: getSavedSidebarState(),
    aiButtonPos: state.aiButtonPos ? { ...state.aiButtonPos } : null,
    codexBacklinkCollapsed: state.characterBacklinkGroupCollapsedKeys instanceof Set ? [...state.characterBacklinkGroupCollapsedKeys] : [],
    search: state.search,
    characterSearch: state.characterSearch,
    codexKindFilter: state.codexKindFilter,
    codexTagFilter: state.codexTagFilter,
    eventSearch: state.eventSearch,
    playbookSearch: state.playbookSearch,
    playbookJsonOpen: state.playbookJsonOpen,
    playbookTab: state.playbookTab
  });
}

function buildSavedStateForProject(project, uiOverrides = {}) {
  return {
    version: SAVED_STATE_VERSION,
    savedAt: new Date().toISOString(),
    project: cloneProject(normalizeProject(project)),
    ui: {
      selectedNodeId: null,
      selectedLinkId: null,
      panel: "project",
      activeFileId: "adventure",
      theme: state.theme,
      exportImageScale: state.exportImageScale,
      snapToGrid: false,
      view: { x: 0, y: 0, scale: DEFAULT_CANVAS_ZOOM },
      sidebar: getSavedSidebarState(),
      aiButtonPos: null,
      codexBacklinkCollapsed: [],
      search: "",
      characterSearch: "",
      codexKindFilter: CODEX_ALL_FILTER,
      codexTagFilter: "",
      eventSearch: "",
      playbookSearch: "",
      playbookJsonOpen: false,
      ...uiOverrides
    }
  };
}

function applySavedState(saved) {
  const payload = parseSavedPayload(saved);
  if (!payload) return false;
  const projectSource = payload.project || payload;
  state.project = normalizeProject(projectSource);
  markProjectStructureChanged({ nodeTypes: true });
  invalidateCharacterRenderContext();

  const ui = payload.ui || {};
  state.selectedNodeId = getValidSavedNodeId(ui.selectedNodeId);
  state.selectedLinkId = getValidSavedLinkId(ui.selectedLinkId);
  state.panel = getValidSavedPanel(ui.panel, state.selectedNodeId);
  state.activeFileId = fileViews[ui.activeFileId] ? ui.activeFileId : "adventure";
  state.theme = ui.theme === "light" ? "light" : "dark";
  state.exportImageScale = normalizeExportImageScale(ui.exportImageScale);
  state.snapToGrid = Boolean(ui.snapToGrid);
  applySavedSidebarState(ui.sidebar);
  state.aiButtonPos = ui.aiButtonPos && Number.isFinite(ui.aiButtonPos.left) && Number.isFinite(ui.aiButtonPos.top)
    ? { left: ui.aiButtonPos.left, top: ui.aiButtonPos.top }
    : null;
  applyAiButtonPosition();
  state.characterBacklinkGroupCollapsedKeys = new Set(Array.isArray(ui.codexBacklinkCollapsed) ? ui.codexBacklinkCollapsed.filter((key) => typeof key === "string") : []);
  state.search = typeof ui.search === "string" ? ui.search : "";
  state.characterSearch = typeof ui.characterSearch === "string" ? ui.characterSearch : "";
  state.codexKindFilter = normalizeCodexKindFilter(ui.codexKindFilter);
  state.codexTagFilter = normalizeOptionalString(ui.codexTagFilter).trim();
  state.eventSearch = typeof ui.eventSearch === "string" ? ui.eventSearch : "";
  state.playbookSearch = typeof ui.playbookSearch === "string" ? ui.playbookSearch : "";
  state.searchIndex = -1;
  state.characterSearchIndex = -1;
  state.eventSearchIndex = -1;
  state.playbookSearchIndex = -1;
  state.playbookJsonOpen = Boolean(ui.playbookJsonOpen);
  state.playbookTab = getValidPlaybookTab(ui.playbookTab);
  return applySavedView(ui.view);
}

function getValidPlaybookTab(value) {
  return ["variables", "actions", "script", "gates", "rules", "validation"].includes(value) ? value : "variables";
}

function parseSavedPayload(saved) {
  if (!saved) return null;
  if (typeof saved !== "string") return saved;
  try {
    return JSON.parse(saved);
  } catch (error) {
    console.error(error);
    return null;
  }
}

function getValidSavedNodeId(nodeId) {
  return state.project.nodes.some((node) => node.id === nodeId) ? nodeId : null;
}

function getValidSavedLinkId(linkId) {
  return state.project.links.some((link) => link.id === linkId) ? linkId : null;
}

function getValidSavedPanel(panel, selectedNodeId) {
  if (!validPanels.has(panel)) return "project";
  if (panel === "node" && !selectedNodeId) return "project";
  return panel;
}

function normalizeView(view) {
  if (!view || typeof view !== "object") return { x: 0, y: 0, scale: DEFAULT_CANVAS_ZOOM };
  const x = Number(view.x);
  const y = Number(view.y);
  const scale = Number(view.scale);
  if (![x, y, scale].every(Number.isFinite)) return { x: 0, y: 0, scale: DEFAULT_CANVAS_ZOOM };
  return {
    x,
    y,
    scale: clamp(scale, CANVAS_MIN_ZOOM, CANVAS_MAX_ZOOM)
  };
}

function applySavedView(view) {
  if (!view || typeof view !== "object") return false;
  const normalized = normalizeView(view);
  state.view = normalized;
  return true;
}

// BEGIN WEB_RUNTIME:PROJECT_STORAGE
function loadWebState() {
  try {
    return getWebProjectStorage()?.getItem(WEB_STORAGE_KEY) || null;
  } catch (error) {
    console.error(error);
    return null;
  }
}

function saveWebState(savedState) {
  const storage = getWebProjectStorage();
  if (!storage) throw new Error("Browser project storage is unavailable.");
  storage.setItem(WEB_STORAGE_KEY, JSON.stringify(savedState));
}

function getWebProjectStorage() {
  // Inside Obsidian, persistence goes through NarrativeCanvasHost (data.json + vault files);
  // the bundle script replaces this whole function with a `return null` stub for the plugin.
  if (window.NarrativeCanvasHost) return null;
  try {
    return window["local" + "Storage"] || null;
  } catch (_error) {
    return null;
  }
}
// END WEB_RUNTIME:PROJECT_STORAGE

async function loadFromVault(announce = true) {
  if (!window.NarrativeCanvasHost?.loadProject) return null;
  try {
    const saved = await window.NarrativeCanvasHost.loadProject();
    if (!saved) return null;
    const payload = parseSavedPayload(saved);
    if (!payload) throw new Error("Vault project JSON could not be parsed.");
    const restoredView = applySavedState(payload);
    if (!state.selectedNodeId) state.selectedNodeId = state.project.nodes[0]?.id || null;
    state.externalProjectChangePending = false;
    setProjectDirty(false);
    await reloadCodexFiles({ render: false, silent: true });
    if (announce) setStatus(`Loaded ${getHostProjectFileLabel()}.`);
    return restoredView;
  } catch (error) {
    console.error(error);
    if (announce) setStatus("Could not load vault project.");
    return null;
  }
}

function getHostProjectFileLabel() {
  const host = window.NarrativeCanvasHost;
  return host?.getProjectFile?.() || host?.projectFile || "vault project";
}

async function ensureVaultProjectFile() {
  const host = window.NarrativeCanvasHost;
  if (!host?.ensureProjectFile) return false;
  try {
    const options = isSampleProjectForFilename() ? { filenameOverride: getSampleProjectFilenameForProject() } : undefined;
    const target = await host.ensureProjectFile(JSON.stringify(buildSavedState(), null, 2), options);
    if (target) setStatus(`Created ${target}.`);
    return Boolean(target);
  } catch (error) {
    console.error(error);
    setStatus("Could not create vault project file.");
    return false;
  }
}

function isSampleProjectForFilename() {
  return state.project?.variables?.sample_id === "narrative_canvas_feature_guide"
    && ["en", "zh"].includes(state.project?.variables?.sample_language)
    && state.project?.nodes?.some((node) => node.id === "e1" && node.type === "StorySequence");
}

function exportJson() {
  const blob = new Blob([buildProjectJson()], { type: "application/json" });
  downloadBlob(blob, `${slugify(state.project.title || "narrative-canvas")}.json`);
  setStatus("JSON exported.");
}

function exportPlaySession() {
  const session = state.playPath.length ? capturePlaySessionSnapshot() : state.lastPlaySession;
  if (!session?.steps?.length) {
    setStatus(t("No playthrough is available to export."));
    return;
  }
  const lines = [
    `# ${session.projectTitle || "Narrative Canvas"} — ${t("Playthrough")}`,
    "",
    `- ${t("Captured")}: ${session.capturedAt}`,
    `- ${t("Cards")}: ${session.steps.length}`,
    `- ${t("Earlier cards omitted")}: ${session.trimmedCount || 0}`,
    ""
  ];
  session.steps.forEach((step, index) => {
    lines.push(`## ${index + 1}. ${step.title || step.displayId || step.nodeId}`);
    lines.push("");
    lines.push(`- ${t("Type")}: ${step.type || ""}`);
    lines.push(`- ID: ${step.displayId || step.nodeId}`);
    if (step.body) lines.push("", step.body);
    if (step.operations?.length) {
      lines.push("", `### ${t("Operations")}`, "", ...step.operations.map((operation) => `- ${operation}`));
    }
    lines.push("");
  });
  const finalVariables = session.steps[session.steps.length - 1]?.variables;
  if (finalVariables) {
    lines.push(`## ${t("Final state")}`, "", "```json", JSON.stringify(finalVariables, null, 2), "```", "");
  }
  const slug = slugify(session.projectTitle || "narrative-canvas");
  downloadBlob(new Blob([lines.join("\n")], { type: "text/markdown;charset=utf-8" }), `${slug}-playthrough.md`);
  setStatus(t("Playthrough exported."));
}

function exportRuntimeJson() {
  const slug = slugify(state.project.title || "narrative-canvas");
  const document = buildRuntimeExportDocument();
  downloadJsonFile(document, `${slug}-runtime.json`);
  showExportReport(document, "Runtime JSON");
  setStatus("Runtime JSON exported.");
}

function exportStoryMarkdown() {
  const slug = slugify(state.project.title || "narrative-canvas");
  const document = buildRuntimeExportDocument();
  downloadBlob(new Blob([buildStoryMarkdown(document)], { type: "text/markdown;charset=utf-8" }), `${slug}-story.md`);
  showExportReport(document, "Story MD");
  setStatus("Story Markdown exported.");
}

function exportCurrentDocument() {
  if (!flushDocumentSourceApply()) {
    setStatus("Fix the Document source error before exporting.");
    return;
  }
  const exporters = {
    plain: exportStoryMarkdown,
    ink: exportInk,
    yarn: exportYarn,
    twee: exportTwee
  };
  exporters[normalizeDocumentFormat(state.documentFormat)]();
}

function exportStoryLayoutJson() {
  const slug = slugify(state.project.title || "narrative-canvas");
  downloadJsonFile(buildStoryLayoutDocument(), `${slug}-layout.json`);
  setStatus("Story layout JSON exported.");
}

function exportStateSchemaJson() {
  const slug = slugify(state.project.title || "narrative-canvas");
  downloadJsonFile(buildStateSchemaDocument(), `${slug}-state.schema.json`);
  setStatus("State schema JSON exported.");
}

function exportProfileJson() {
  const slug = slugify(state.project.title || "narrative-canvas");
  const runtimeDocument = buildRuntimeExportDocument();
  downloadJsonFile(buildExportProfileDocument(runtimeDocument), `${slug}-export.profile.json`);
  showExportReport(runtimeDocument, "Export Profile");
  setStatus("Export profile JSON exported.");
}

function exportYarn() {
  const slug = slugify(state.project.title || "narrative-canvas");
  const document = buildRuntimeExportDocument();
  downloadBlob(new Blob([buildYarnScript(document)], { type: "text/plain;charset=utf-8" }), `${slug}.yarn`);
  showExportReport(document, "Yarn");
  setStatus("Yarn exported.");
}

