async function exportImage() {
  const preset = getExportImageScalePreset();
  const slug = slugify(state.project.title || "narrative-canvas");
  try {
    const svg = buildExportSvg();
    const rasterPlan = getExportRasterPlan(svg, preset);
    const blob = await svgToPngBlob(svg, rasterPlan.scale);
    downloadBlob(blob, `${slug}${getExportImageSuffix(rasterPlan)}.png`);
    setStatus(rasterPlan.limited
      ? `Image exported at ${formatExportPixelSize(rasterPlan)} to fit browser PNG limits.`
      : `Image exported at ${formatExportPixelSize(rasterPlan)}.`);
  } catch (error) {
    console.error(error);
    downloadBlob(new Blob([buildExportSvg()], { type: "image/svg+xml" }), `${slug}.svg`);
    setStatus("PNG export failed; SVG exported.");
  }
}

async function exportAll() {
  try {
    const slug = slugify(state.project.title || "narrative-canvas");
    const runtimeDocument = buildRuntimeExportDocument();
    const files = [
      { name: `${slug}.json`, blob: new Blob([buildProjectJson()], { type: "application/json" }) },
      { name: `${slug}-story.md`, blob: new Blob([buildStoryMarkdown(runtimeDocument)], { type: "text/markdown;charset=utf-8" }) },
      { name: `${slug}-layout.json`, blob: new Blob([JSON.stringify(buildStoryLayoutDocument(), null, 2)], { type: "application/json;charset=utf-8" }) },
      { name: `${slug}-state.schema.json`, blob: new Blob([JSON.stringify(buildStateSchemaDocument(), null, 2)], { type: "application/json;charset=utf-8" }) },
      { name: `${slug}-export.profile.json`, blob: new Blob([JSON.stringify(buildExportProfileDocument(runtimeDocument), null, 2)], { type: "application/json;charset=utf-8" }) },
      { name: `${slug}-runtime.json`, blob: new Blob([JSON.stringify(runtimeDocument, null, 2)], { type: "application/json;charset=utf-8" }) },
      { name: `${slug}.yarn`, blob: new Blob([buildYarnScript(runtimeDocument)], { type: "text/plain;charset=utf-8" }) },
      { name: `${slug}.ink`, blob: new Blob([buildInkScript(runtimeDocument)], { type: "text/plain;charset=utf-8" }) },
      { name: `${slug}.twee`, blob: new Blob([buildTweeScript(runtimeDocument)], { type: "text/plain;charset=utf-8" }) },
      { name: `${slug}.dtl`, blob: new Blob([buildDialogicScript(runtimeDocument)], { type: "text/plain;charset=utf-8" }) },
      { name: `${slug}.conversation.json`, blob: new Blob([JSON.stringify(buildUnrealConversationDocument(runtimeDocument), null, 2)], { type: "application/json;charset=utf-8" }) },
      { name: "Events Sheet.csv", blob: new Blob([buildEventSheetCsv()], { type: "text/csv;charset=utf-8" }) },
      { name: `${slug}-events.json`, blob: new Blob([JSON.stringify(buildEventSheetJsonDocument(), null, 2)], { type: "application/json;charset=utf-8" }) },
      { name: "Node Fields.csv", blob: new Blob([buildNodeFieldsCsv()], { type: "text/csv;charset=utf-8" }) },
      { name: "Narrative-Library.md", blob: new Blob([buildCharactersMarkdown()], { type: "text/markdown;charset=utf-8" }) },
      { name: "Narrative-Library.json", blob: new Blob([JSON.stringify(buildCharactersJsonDocument(), null, 2)], { type: "application/json;charset=utf-8" }) },
      { name: PLAYBOOK_FILE_NAME, blob: new Blob([buildVariablesJson()], { type: "application/json" }) }
    ];
    const svg = buildExportSvg();
    const imagePreset = getExportImageScalePreset();
    try {
      const rasterPlan = getExportRasterPlan(svg, imagePreset);
      files.push({ name: `${slug}${getExportImageSuffix(rasterPlan)}.png`, blob: await svgToPngBlob(svg, rasterPlan.scale) });
    } catch (error) {
      console.error(error);
      files.push({ name: `${slug}.svg`, blob: new Blob([svg], { type: "image/svg+xml" }) });
    }
    const zipBlob = await createZipBlob(files);
    downloadBlob(zipBlob, `${slug}-export.zip`);
    showExportReport(runtimeDocument, "Export all");
    setStatus("Project export package created.");
  } catch (error) {
    console.error(error);
    setStatus("Project export package failed.");
  }
}

function showExportReport(document, formatName) {
  if (!dom.exportReportDialog?.showModal || !dom.exportReportBody || !dom.exportReportTitle) {
    setStatus("Export report is unavailable.");
    return false;
  }
  const warnings = getExportReportWarnings(document);
  const formatLabel = t(formatName || "Export");
  dom.exportReportKicker.textContent = t("Export report");
  dom.exportReportTitle.textContent = t("{format} export report", { format: formatLabel });
  dom.exportReportBody.innerHTML = buildExportReportHtml(document, warnings);
  dom.exportReportDialog.returnValue = "";
  if (!dom.exportReportDialog.open) dom.exportReportDialog.showModal();
  return true;
}

function getExportReportWarnings(document) {
  return Array.isArray(document?.report?.warnings) ? document.report.warnings : [];
}

function buildExportReportHtml(document, warnings) {
  const warningCount = warnings.length;
  const summaryTitle = warningCount
    ? t("{count} export warnings", { count: warningCount })
    : t("No export warnings");
  const warningSection = warningCount
    ? buildExportWarningListHtml(warnings)
    : "";
  return `
    <section class="export-report-summary" data-report-status="${warningCount ? "warning" : "ok"}">
      <strong>${escapeHtml(summaryTitle)}</strong>
      <span>${escapeHtml(t("Runtime JSON keeps the full report. Review any warning before wiring the export into a target engine."))}</span>
    </section>
    ${warningSection}
    ${buildExportVariableNameMapHtml(document)}
  `;
}

function buildExportWarningListHtml(warnings) {
  const visibleWarnings = warnings.slice(0, 30);
  const remainingCount = warnings.length - visibleWarnings.length;
  const remaining = remainingCount > 0
    ? `<p class="confirm-body">${escapeHtml(t("{count} more warnings are available in Runtime JSON.", { count: remainingCount }))}</p>`
    : "";
  return `
    <section class="export-report-section">
      <h3>${escapeHtml(t("Warnings"))}</h3>
      <div class="export-report-list">
        ${visibleWarnings.map((warning) => `
          <article class="export-report-warning">
            <code>${escapeHtml(warning.code || "warning")}</code>
            <span>${escapeHtml(formatExportWarningMessage(warning))}</span>
            ${formatExportWarningReference(warning)}
          </article>
        `).join("")}
      </div>
      ${remaining}
    </section>
  `;
}

function formatExportWarningMessage(warning) {
  const message = String(warning?.message || "");
  if (state.language !== "zh") return message;
  const quoted = [...message.matchAll(/"([^"]*)"/g)].map((match) => match[1]);
  const code = String(warning?.code || "");
  if (code === "complex-variable") {
    const key = quoted[0] || warning?.key || "";
    if (/\bis an array\b/.test(message)) {
      return t("Variable \"{key}\" is an array; runtime JSON and Twee keep it, Yarn exports it as a JSON string for membership predicates, and Ink exports a LIST when items are primitive.", { key });
    }
    return t("Variable \"{key}\" is an object; runtime JSON keeps it, Twee initializes it, and Yarn/Ink comment it out.", { key });
  }
  if (code === "effect-op-runtime-only") {
    return t("Effect \"{op}\" on \"{key}\" is kept in runtime JSON but commented in text exports.", {
      op: quoted[0] || "",
      key: quoted[1] || "(no key)"
    });
  }
  if (code === "custom-node-type-runtime-only") {
    return t("Custom node type \"{type}\" exports as rendered text and custom fields; target formats may need a custom loader.", { type: quoted[0] || "" });
  }
  if (code === "playbook-action-runtime-only") {
    const detail = message.match(/\(([^)]+)\)/)?.[1] || "";
    return t("Playbook action \"{id}\" ({detail}) is kept in runtime JSON but not emitted to text exports.", { id: quoted[0] || "", detail });
  }
  if (code === "playbook-actions-runtime-only") {
    const count = message.match(/^(\d+)/)?.[1] || "";
    return t("{count} Playbook action(s) are included in runtime JSON but not emitted to text exports.", { count });
  }
  if (code === "state-key-name-sanitized") {
    return t("State key \"{key}\" exports with \".\" converted to \"_\" in portable text formats.", { key: quoted[0] || "" });
  }
  if (code === "state-path-flattened") {
    return t("State path \"{key}\" exports as \"{exportKey}\" for portable text formats.", { key: quoted[0] || "", exportKey: quoted[1] || "" });
  }
  if (code === "implicit-variable") {
    return t("State key \"{key}\" is referenced or written but has no initial variable value.", { key: quoted[0] || "" });
  }
  if (code === "variable-name-sanitized" || code === "variable-name-collision" || code === "node-name-sanitized" || code === "node-name-collision") {
    const kind = code.startsWith("node-") ? t("Node") : t("Variable");
    return t("{kind} \"{source}\" exports as \"{target}\".", { kind, source: quoted[0] || "", target: quoted[1] || "" });
  }
  if (code === "expression-not-translated") {
    return t("Expression \"{expression}\" is kept in Runtime JSON; Yarn, Ink, and Twee use a false guard.", { expression: quoted[0] || "" });
  }
  return t(message);
}

function formatExportWarningReference(warning) {
  const parts = [];
  if (warning?.nodeId) {
    const node = getNode(warning.nodeId);
    parts.push(node ? `${getNodeDisplayTitle(node, node.type)} (${warning.nodeId})` : warning.nodeId);
  }
  if (warning?.linkId) parts.push(`link ${warning.linkId}`);
  if (warning?.choiceId) parts.push(`choice ${warning.choiceId}`);
  if (!parts.length) return "";
  return `<small>${escapeHtml(t("Reference: {value}", { value: parts.join(" / ") }))}</small>`;
}

function buildExportVariableNameMapHtml(document) {
  const entries = Object.entries(document?.report?.variableNameMap || {})
    .filter(([source, target]) => source !== target);
  if (!entries.length) {
    return `
      <section class="export-report-section">
        <h3>${escapeHtml(t("Variable name map"))}</h3>
        <p class="confirm-body">${escapeHtml(t("No variable names needed conversion."))}</p>
      </section>
    `;
  }
  return `
    <section class="export-report-section">
      <h3>${escapeHtml(t("Variable name map"))}</h3>
      <p class="confirm-body">${escapeHtml(t("Only changed names are shown."))}</p>
      <dl class="export-report-map">
        ${entries.map(([source, target]) => `
          <div>
            <dt><code>${escapeHtml(source)}</code></dt>
            <dd aria-hidden="true">→</dd>
            <dd><code>${escapeHtml(target)}</code></dd>
          </div>
        `).join("")}
      </dl>
    </section>
  `;
}

function buildProjectJson() {
  return JSON.stringify(state.project, null, 2);
}

function buildRuntimeExportDocument() {
  const warnings = [];
  const model = buildRuntimeExportNameModel(warnings);
  const nodes = getRuntimeExportNodeOrder(model)
    .map((node) => buildRuntimeExportNode(node, model, warnings));
  const links = buildRuntimeExportLinks(model, warnings);
  const playbookActions = getPlaybookActions();
  const runtimeOnlyPlaybookActions = playbookActions.filter(isPlaybookActionRuntimeOnlyForPortableExport);
  if (runtimeOnlyPlaybookActions.length) {
    pushExportWarning(warnings, "playbook-actions-runtime-only", `${runtimeOnlyPlaybookActions.length} Playbook action(s) are included in runtime JSON but not emitted to Yarn, Ink, or Twee.`);
  }
  appendStateReportExportWarnings(warnings, buildStateReport());
  const reportWarnings = dedupeExportWarnings(warnings);
  return {
    format: "narrative-canvas-runtime",
    version: 1,
    exportedAt: new Date().toISOString(),
    source: {
      title: state.project.title || "Untitled",
      notes: state.project.notes || "",
      richTextFormat: getCurrentRichTextFormat()
    },
    startNodeId: model.startNode?.id || "",
    startNode: model.startNode ? model.nodeNameMap[model.startNode.id] : "",
    variables: model.variables,
    variableNames: Object.values(model.variableNameMap),
    characters: getCastCharacters().map((character) => ({
      id: character.id,
      name: character.name,
      role: character.role,
      voice: character.voice,
      notes: character.notes
    })),
    codex: getCharacters().map((entry) => ({
      id: entry.id,
      name: entry.name,
      kind: entry.kind,
      role: entry.role,
      voice: entry.voice,
      tags: entry.tags,
      notes: entry.notes
    })),
    nodes,
    links,
    playbook: {
      rules: getRunnerRules(),
      actions: playbookActions.map((action) => ({
        id: action.id,
        trigger: action.trigger,
        op: action.op,
        target: action.target,
        category: action.category,
        key: action.key,
        stateKey: getPlaybookActionStateKey(action),
        value: action.value
      }))
    },
    report: {
      warnings: reportWarnings,
      variableNameMap: model.variableNameMap,
      nodeNameMap: model.nodeNameMap
    }
  };
}

function appendStateReportExportWarnings(warnings, report) {
  if (!Array.isArray(report?.exportBlocks)) return;
  report.exportBlocks
    .filter((block) => !["effect-op-runtime-only"].includes(block.code))
    .forEach((block) => {
      pushExportWarning(warnings, block.code, block.message, {
        nodeId: block.nodeId
      });
    });
}

function dedupeExportWarnings(warnings) {
  const seen = new Set();
  return (Array.isArray(warnings) ? warnings : []).filter((warning) => {
    const key = [
      warning?.code || "",
      warning?.message || "",
      warning?.nodeId || "",
      warning?.linkId || "",
      warning?.choiceId || ""
    ].join("|");
    if (seen.has(key)) return false;
    seen.add(key);
    return true;
  });
}

function buildRuntimeExportNameModel(warnings) {
  const sourceVariables = normalizeVariablesObject(state.project.variables);
  const variableNameMap = {};
  const variableUsed = new Set();
  const variables = {};
  Object.entries(sourceVariables).forEach(([key, value]) => {
    const safeKey = makeUniqueExportIdentifier(key, "variable", variableUsed, "variable", warnings);
    variableNameMap[key] = safeKey;
    variables[safeKey] = cloneRuntimeExportValue(value);
    if (isComplexRuntimeValue(value)) {
      const message = Array.isArray(value)
        ? `Variable "${key}" is an array; runtime JSON and Twee keep it, Yarn exports it as a JSON string for membership predicates, and Ink exports a LIST when items are primitive.`
        : `Variable "${key}" is an object; runtime JSON keeps it, Twee initializes it, and Yarn/Ink comment it out.`;
      pushExportWarning(warnings, "complex-variable", message);
    }
  });

  const exportNodes = getRuntimeExportableNodes();
  const startNode = getPreviewStartNode(getPreviewPath()) || exportNodes[0] || null;
  const nodeNameMap = {};
  const nodeUsed = new Set();
  if (startNode) {
    nodeNameMap[startNode.id] = makeUniqueExportIdentifier("Start", "Start", nodeUsed, "node", warnings, { original: startNode.title || startNode.id, suppressSanitizedWarning: true });
  }
  exportNodes.forEach((node, index) => {
    if (nodeNameMap[node.id]) return;
    nodeNameMap[node.id] = makeUniqueExportIdentifier(node.title || node.id, `Node_${index + 1}`, nodeUsed, "node", warnings);
  });

  return {
    sourceVariables,
    variables,
    variableNameMap,
    variableUsed,
    nodeNameMap,
    nodeUsed,
    startNode
  };
}

function getRuntimeExportableNodes() {
  return (Array.isArray(state.project.nodes) ? state.project.nodes : [])
    .filter((node) => node && !isFrameNode(node));
}

function getRuntimeExportNodeOrder(model) {
  const seen = new Set();
  const ordered = [];
  const add = (node) => {
    if (!node || seen.has(node.id) || isFrameNode(node)) return;
    seen.add(node.id);
    ordered.push(node);
  };
  add(model.startNode);
  getPreviewPath().forEach(add);
  getRuntimeExportableNodes().slice().sort(compareRawNodePosition).forEach(add);
  return ordered;
}

function buildRuntimeExportNode(node, model, warnings) {
  const script = getNodeRuntimeScript(node);
  const outgoing = getChoiceOrderedLinks(getOutgoing(node.id));
  const requirementsSource = getExportNodeRequirementsSource(node, script, model);
  const choices = getExportChoiceEntries(node, script, model, warnings, outgoing);
  const routing = normalizeNodeRouting(node.routing);
  return {
    id: node.id,
    slug: model.nodeNameMap[node.id],
    title: renderExportTemplate(script.title, node, getNodeDisplayTitle(node, node.type), model, "runtime"),
    type: node.type,
    typeLabel: getNodeTypeLabel(node.type),
    body: getExportNodeBody(node, script, model),
    requirements: transformExportExpression(requirementsSource, model, warnings, { nodeId: node.id }),
    effects: getRuntimeExportNodeEffects(node, model, warnings),
    choices,
    timer: buildRuntimeExportChoiceTimer(node, outgoing, model),
    next: choices.length ? [] : getExportNextTransitions(node, outgoing, routing, model, warnings),
    routing: {
      mode: routing.mode,
      target: routing.target,
      targetId: getRoutingNextNodeId(node)
    },
    cast: getRuntimeExportCast(node),
    customFields: getRuntimeExportCustomFields(node, model)
  };
}

function buildRuntimeExportChoiceTimer(node, outgoing, model) {
  const timer = normalizeChoiceTimer(node?.choiceTimer);
  if (!timer.enabled || !timer.fallbackLinkId) return null;
  const link = (outgoing || []).find((item) => item.id === timer.fallbackLinkId);
  if (!link) return null;
  return {
    seconds: timer.seconds,
    fallbackLinkId: link.id,
    fallbackChoiceOptionId: link.choiceOptionId || "",
    targetId: link.to || "",
    target: model.nodeNameMap[link.to] || ""
  };
}

function getRuntimeExportNodeEffects(node, model, warnings) {
  return normalizeNodeStateLogic(node.stateLogic).effects
    .map((effect) => buildRuntimeExportEffect(effect, model, warnings, { nodeId: node.id }));
}

function getExportNodeBody(node, script, model) {
  if (isDialogNode(node) && Array.isArray(node.turns) && node.turns.length) {
    return node.turns
      .map((turn) => {
        const speaker = renderExportTemplate(turn.speaker, node, turn.speaker, model, "runtime").trim();
        const line = renderExportTemplate(turn.line, node, turn.line, model, "runtime").trim();
        return speaker ? `${speaker}: ${line}` : line;
      })
      .filter(Boolean)
      .join("\n");
  }
  return renderExportTemplate(script.body, node, displayBody(node), model, "runtime");
}

function getRuntimeExportCast(node) {
  const entries = new Map(getCharacters().map((entry) => [entry.id, entry]));
  return normalizeNodeCast(node?.cast)
    .map((entry) => {
      const codexEntry = entries.get(entry.characterId);
      if (!codexEntry) return null;
      return {
        codexId: codexEntry.id,
        characterId: codexEntry.id,
        name: codexEntry.name,
        kind: codexEntry.kind,
        role: entry.role || "Present"
      };
    })
    .filter(Boolean);
}

function getRuntimeExportCustomFields(node, model) {
  const fields = {};
  getNodeCustomFieldEntries(node).forEach((field) => {
    fields[field.key] = renderExportTemplate(field.value, node, field.value, model, "runtime");
  });
  return fields;
}

function getExportNodeRequirementsSource(node, script, model) {
  const requirements = normalizeNodeStateLogic(node?.stateLogic).requirements;
  if (requirements) return renderExportTemplate(requirements, node, requirements, model, "runtime");
  const gateAction = getPlaybookGateAction(node);
  if (gateAction) {
    const value = renderExportTemplate(gateAction.value, node, gateAction.value, model, "runtime");
    return `${getPlaybookActionStateKey(gateAction)} ${value}`.trim();
  }
  return "";
}

function getExportChoiceEntries(node, script, model, warnings, outgoing) {
  const labels = getExportRuntimeChoices(node, script, model);
  const options = Array.isArray(node?.choiceOptions) ? node.choiceOptions : [];
  const links = getChoiceOrderedLinks(outgoing || []);
  return labels.map((label, index) => {
    const option = options[index];
    const link = findChoiceOptionLink(option, index, links);
    const requires = option?.requires ? renderExportTemplate(option.requires, node, option.requires, model, "runtime") : "";
    const linkCondition = link ? getExportLinkCondition(link, model, warnings, { nodeId: node.id, linkId: link.id }) : "";
    const targetRequirement = link ? getExportTargetRequirementCondition(link, model, warnings, { nodeId: node.id, linkId: link.id }) : "";
    const playbookChoiceCondition = getExportPlaybookChoiceCondition(node, option, label, model, warnings, { nodeId: node.id, choiceId: option?.id || "" });
    return {
      id: option?.id || "",
      label,
      condition: combineRuntimeConditions([transformExportExpression(requires, model, warnings, { nodeId: node.id }), linkCondition, targetRequirement, playbookChoiceCondition], "&&"),
      effects: (Array.isArray(option?.effects) ? option.effects : []).map((effect) => buildRuntimeExportEffect(effect, model, warnings, { nodeId: node.id, choiceId: option?.id || "" })),
      targetId: link?.to || "",
      target: link?.to ? model.nodeNameMap[link.to] || "" : "",
      linkId: link?.id || ""
    };
  });
}

function getExportPlaybookChoiceCondition(node, option, label, model, warnings, ref) {
  const conditions = getMatchingPlaybookChoiceGateActions(node, option, label)
    .map((action) => {
      const source = renderExportTemplate(action.value, node, action.value, model, "runtime").trim();
      const condition = getChoiceGateConditionExpression(action, source);
      return transformExportExpression(condition, model, warnings, { ...ref, choiceId: option?.id || ref?.choiceId || "" });
    })
    .filter(Boolean);
  return combineRuntimeConditions(conditions, "&&");
}

function getExportRuntimeChoices(node, script, model) {
  let choices = [];
  if (Array.isArray(script?.choices)) {
    choices = script.choices;
  } else if (script?.choices) {
    const fieldValue = getNodeFieldValue(node, script.choices);
    choices = parseChoiceLines(fieldValue !== "" ? fieldValue : script.choices);
  } else if (hasNodeChoices(node)) {
    choices = node.choices;
  }
  return choices.map((choice) => renderExportTemplate(choice, node, choice, model, "runtime")).filter(Boolean);
}

function getMatchingPlaybookChoiceGateActions(node, option, label) {
  return getPlaybookActions().filter((action) => {
    return isPortableChoiceGateAction(action)
      && matchesPlaybookActionTarget(action, node)
      && playbookChoiceActionMatchesOption(action, option, label);
  });
}

function playbookChoiceActionMatchesOption(action, option, label) {
  const selector = normalizeOptionalString(action?.key).trim();
  if (!selector || selector === "state_key") return false;
  const candidates = [
    option?.id,
    option?.label,
    label
  ].map((value) => normalizeOptionalString(value).trim()).filter(Boolean);
  if (candidates.some((candidate) => candidate === selector)) return true;
  const normalizedSelector = normalizeChoiceMatchText(selector);
  return Boolean(normalizedSelector) && candidates.some((candidate) => normalizeChoiceMatchText(candidate) === normalizedSelector);
}

function getChoiceGateConditionExpression(action, source) {
  const condition = normalizeOptionalString(source).trim();
  const truth = getStaticConditionTruth(condition);
  if (action?.op === "lockChoice") {
    if (truth === false) return "";
    if (truth === true || !condition) return "false";
    return `!(${condition})`;
  }
  if (action?.op === "unlockChoice") {
    if (truth === false) return "false";
    if (truth === true || !condition) return "";
    return condition;
  }
  return "";
}

function getStaticConditionTruth(source) {
  const text = normalizeOptionalString(source).trim();
  if (!text) return true;
  if (/^(true|1)$/i.test(text)) return true;
  if (/^(false|0|null)$/i.test(text)) return false;
  return null;
}

function findChoiceOptionLink(option, index, links) {
  if (option?.id) {
    const byId = links.find((link) => link.choiceOptionId === option.id);
    if (byId) return byId;
  }
  const byIndex = links.find((link) => normalizeChoiceIndex(link.choiceIndex) === index);
  return byIndex || links[index] || null;
}

function getExportNextTransitions(node, outgoing, routing, model, warnings) {
  if (routing.mode === "end") return [];
  const routingTargetId = getRoutingNextNodeId(node);
  if (routingTargetId) {
    return [{
      targetId: routingTargetId,
      target: model.nodeNameMap[routingTargetId] || "",
      condition: "",
      label: "Continue",
      source: "routing"
    }];
  }
  return getChoiceOrderedLinks(outgoing || []).map((link) => ({
    targetId: link.to,
    target: model.nodeNameMap[link.to] || "",
    linkId: link.id || "",
    label: link.label || "Continue",
    condition: combineRuntimeConditions([
      getExportLinkCondition(link, model, warnings, { nodeId: node.id, linkId: link.id }),
      getExportTargetRequirementCondition(link, model, warnings, { nodeId: node.id, linkId: link.id })
    ], "&&"),
    source: "link"
  }));
}

function getExportTargetRequirementCondition(link, model, warnings, ref) {
  const targetNode = getNode(link?.to);
  if (!targetNode) return "";
  const targetScript = getNodeRuntimeScript(targetNode);
  const requirements = getExportNodeRequirementsSource(targetNode, targetScript, model);
  return requirements ? transformExportExpression(requirements, model, warnings, { ...ref, nodeId: targetNode.id }) : "";
}

function buildRuntimeExportLinks(model, warnings) {
  return (Array.isArray(state.project.links) ? state.project.links : []).map((link) => ({
    id: link.id || "",
    fromId: link.from || "",
    from: model.nodeNameMap[link.from] || "",
    toId: link.to || "",
    to: model.nodeNameMap[link.to] || "",
    label: link.label || "",
    choiceIndex: normalizeChoiceIndex(link.choiceIndex),
    choiceOptionId: link.choiceOptionId || "",
    condition: getExportLinkCondition(link, model, warnings, { linkId: link.id || "" })
  }));
}

function getExportLinkCondition(link, model, warnings, ref) {
  const source = normalizeOptionalString(link?.requirements || link?.requires).trim();
  return source ? transformExportExpression(source, model, warnings, ref) : "";
}

function buildRuntimeExportEffect(effect, model, warnings, ref) {
  if (effect?.op === "ifElse") {
    return {
      trigger: effect.trigger || "onVisit",
      op: "ifElse",
      condition: transformExportExpression(effect.condition, model, warnings, ref),
      thenEffect: buildRuntimeExportEffect(effect.thenEffect, model, warnings, ref),
      elseEffect: buildRuntimeExportEffect(effect.elseEffect, model, warnings, ref)
    };
  }
  const sourceKey = normalizeOptionalString(effect?.key).trim();
  const key = sourceKey ? getOrCreateExportVariableName(sourceKey, model, warnings, ref) : "";
  const op = effect?.op || "set";
  const valueMode = effect?.valueMode === "variable" ? "variable" : "literal";
  const rawValueSource = normalizeOptionalString(effect?.value);
  const valueSource = valueMode === "variable"
    ? getOrCreateExportVariableName(normalizeExpressionVariableTerm(rawValueSource), model, warnings, ref)
    : rawValueSource;
  if (!["set", "add", "subtract", "toggle"].includes(op)) {
    pushExportWarning(warnings, "effect-op-runtime-only", `Effect "${op}" on "${sourceKey || "(no key)"}" is kept in runtime JSON but commented in Yarn and Ink.`, ref);
  }
  return {
    trigger: effect?.trigger || "onVisit",
    op,
    sourceKey,
    key,
    value: coerceValue(effect?.value ?? ""),
    valueSource,
    valueMode
  };
}

function cloneRuntimeExportValue(value) {
  if (value == null || typeof value !== "object") return value;
  return JSON.parse(JSON.stringify(value));
}

function isComplexRuntimeValue(value) {
  return Boolean(value && typeof value === "object");
}

function renderExportTemplate(template, node, fallback, model, format, depth = 0) {
  if (depth > 8) return String(template == null || template === "" ? fallback : template || "");
  const source = template == null || template === "" ? fallback : template;
  return String(source || "").replace(/\{([a-zA-Z_][\w.-]*)\}/g, (match, key) => {
    if (key.startsWith("variables.")) {
      const variableKey = key.slice("variables.".length);
      return formatExportVariableReference(getOrCreateExportVariableName(variableKey, model, [], {}), format);
    }
    const nodeValue = getNodeFieldValue(node, key);
    if (nodeValue !== "") return renderExportTemplate(nodeValue, node, nodeValue, model, format, depth + 1);
    if (Object.prototype.hasOwnProperty.call(model.sourceVariables, key)) {
      return formatExportVariableReference(getOrCreateExportVariableName(key, model, [], {}), format);
    }
    if (key.includes(".")) {
      return formatExportVariableReference(getOrCreateExportVariableName(key, model, [], {}), format);
    }
    return match;
  });
}

function formatExportVariableReference(key, format) {
  if (!key) return "";
  return format === "yarn" ? `{$${key}}` : `{${key}}`;
}

function parseJsConditionExpression(source) {
  const text = normalizeOptionalString(source).trim();
  if (!text) return { ast: null, invalid: false, error: "" };
  try {
    const tokens = tokenizeJsConditionExpression(text);
    const parser = createJsConditionParser(tokens);
    const ast = parser.parseExpression();
    parser.expect("eof");
    return { ast, invalid: false, error: "" };
  } catch (error) {
    return { ast: null, invalid: true, error: error?.message || "Invalid expression" };
  }
}

function tokenizeJsConditionExpression(source) {
  const tokens = [];
  const text = String(source || "");
  let index = 0;
  const push = (type, value, raw = value) => tokens.push({ type, value, raw });
  const previousAllowsSignedNumber = () => {
    const previous = tokens[tokens.length - 1];
    return !previous || previous.type === "operator" || previous.type === "(" || previous.type === ",";
  };
  while (index < text.length) {
    const char = text[index];
    if (/\s/.test(char)) {
      index += 1;
      continue;
    }
    if (char === "\"" || char === "'") {
      const quote = char;
      let raw = quote;
      let value = "";
      index += 1;
      let escaped = false;
      while (index < text.length) {
        const current = text[index];
        raw += current;
        index += 1;
        if (escaped) {
          value += current;
          escaped = false;
          continue;
        }
        if (current === "\\") {
          escaped = true;
          continue;
        }
        if (current === quote) break;
        value += current;
      }
      if (!raw.endsWith(quote)) throw new Error("Unclosed string");
      push("literal", value, raw);
      continue;
    }
    const numberMatch = text.slice(index).match(/^-?(?:\d+(?:\.\d*)?|\.\d+)/);
    if (numberMatch && (numberMatch[0][0] !== "-" || previousAllowsSignedNumber())) {
      push("literal", Number(numberMatch[0]), numberMatch[0]);
      index += numberMatch[0].length;
      continue;
    }
    const identifierMatch = text.slice(index).match(/^[A-Za-z_]\w*/);
    if (identifierMatch) {
      const value = identifierMatch[0];
      const lower = value.toLowerCase();
      if (lower === "true") push("literal", true, value);
      else if (lower === "false") push("literal", false, value);
      else if (lower === "null") push("literal", null, value);
      else if (lower === "undefined") push("literal", undefined, value);
      else if (lower === "not") push("operator", "!", value);
      else push("identifier", value, value);
      index += value.length;
      continue;
    }
    const operator = ["===", "!==", "&&", "||", "==", "!=", ">=", "<=", ">", "<", "!"].find((item) => text.startsWith(item, index));
    if (operator) {
      push("operator", operator, operator);
      index += operator.length;
      continue;
    }
    if ("().,".includes(char)) {
      push(char, char, char);
      index += 1;
      continue;
    }
    throw new Error(`Unexpected token ${char}`);
  }
  push("eof", "");
  return tokens;
}

function createJsConditionParser(tokens) {
  let index = 0;
  const current = () => tokens[index] || { type: "eof", value: "" };
  const consume = (type, value) => {
    const token = current();
    if (token.type !== type || (value != null && token.value !== value)) {
      throw new Error(`Expected ${value || type}`);
    }
    index += 1;
    return token;
  };
  const match = (type, value) => {
    const token = current();
    if (token.type !== type || (value != null && token.value !== value)) return null;
    index += 1;
    return token;
  };
  const parseExpression = () => parseLogicalOr();
  const parseLogicalOr = () => {
    let node = parseLogicalAnd();
    while (match("operator", "||")) node = { type: "logical", operator: "||", left: node, right: parseLogicalAnd() };
    return node;
  };
  const parseLogicalAnd = () => {
    let node = parseEquality();
    while (match("operator", "&&")) node = { type: "logical", operator: "&&", left: node, right: parseEquality() };
    return node;
  };
  const parseEquality = () => {
    let node = parseComparison();
    while (["===", "!==", "==", "!="].includes(current().value)) {
      const operator = consume("operator").value;
      node = { type: "binary", operator, left: node, right: parseComparison() };
    }
    return node;
  };
  const parseComparison = () => {
    let node = parseUnary();
    while ([">=", "<=", ">", "<"].includes(current().value)) {
      const operator = consume("operator").value;
      node = { type: "binary", operator, left: node, right: parseUnary() };
    }
    return node;
  };
  const parseUnary = () => {
    if (match("operator", "!")) return { type: "unary", operator: "!", argument: parseUnary() };
    return parsePostfix();
  };
  const parsePostfix = () => {
    let node = parsePrimary();
    while (match(".", ".")) {
      const property = consume("identifier").value;
      if (JS_CONDITION_METHODS.has(property) && match("(", "(")) {
        const args = parseArgumentsAfterOpenParen();
        node = { type: "call", name: property, object: node, args };
      } else if (node.type === "identifier") {
        node = { ...node, path: [...node.path, property] };
      } else {
        throw new Error("Unsupported property access");
      }
    }
    if (node.type === "identifier" && match("(", "(")) {
      const args = parseArgumentsAfterOpenParen();
      const name = node.path.join(".");
      if (!JS_CONDITION_LEGACY_FUNCTIONS.has(name)) throw new Error(`Unsupported function ${name}`);
      return { type: "call", name, object: null, args };
    }
    return node;
  };
  const parseArgumentsAfterOpenParen = () => {
    const args = [];
    if (match(")", ")")) return args;
    do {
      args.push(parseExpression());
    } while (match(",", ","));
    consume(")", ")");
    return args;
  };
  const parsePrimary = () => {
    if (current().type === "literal") {
      const token = consume("literal");
      return { type: "literal", value: token.value, raw: token.raw };
    }
    if (current().type === "identifier") {
      const token = consume("identifier");
      return { type: "identifier", path: [token.value] };
    }
    if (match("(", "(")) {
      const expression = parseExpression();
      consume(")", ")");
      return { type: "group", expression };
    }
    throw new Error("Expected expression");
  };
  return {
    parseExpression,
    expect: consume
  };
}

function formatJsConditionAst(ast, format, context = {}) {
  if (!ast) return "";
  if (ast.type === "literal") return formatConditionLiteral(ast.value);
  if (ast.type === "identifier") return formatConditionIdentifier(ast, format, context);
  if (ast.type === "group") {
    const expression = formatJsConditionAst(ast.expression, format, context);
    return expression ? `(${expression})` : "";
  }
  if (ast.type === "unary") {
    const argument = formatJsConditionAst(ast.argument, format, context);
    if (!argument) return "";
    if (format === "yarn" || format === "ink") return `not ${wrapConditionTerm(argument)}`;
    return `!${wrapConditionTerm(argument)}`;
  }
  if (ast.type === "logical") {
    const left = formatJsConditionAst(ast.left, format, context);
    const right = formatJsConditionAst(ast.right, format, context);
    const parts = [left, right].filter(Boolean);
    if (!parts.length) return "";
    if (parts.length === 1) return parts[0];
    const operator = format === "yarn" || format === "ink"
      ? (ast.operator === "&&" ? "and" : "or")
      : ast.operator;
    return parts.map((part) => wrapConditionTerm(part)).join(` ${operator} `);
  }
  if (ast.type === "binary") {
    const left = formatJsConditionAst(ast.left, format, context);
    const right = formatConditionComparisonOperand(ast.right, format, context);
    if (!left || !right) return "";
    return `${left} ${formatConditionOperator(ast.operator, format)} ${right}`;
  }
  if (ast.type === "call") return formatConditionCall(ast, format, context);
  return "";
}

function formatConditionLiteral(value) {
  if (typeof value === "number" && Number.isFinite(value)) return String(value);
  if (typeof value === "boolean") return value ? "true" : "false";
  if (value == null) return "null";
  if (typeof value === "undefined") return "undefined";
  return JSON.stringify(String(value));
}

function formatConditionIdentifier(ast, format, context = {}) {
  const key = normalizeConditionIdentifierPath(ast.path);
  if (!key) return "";
  if (isTransientVisitStateKey(key) && format === "runtime") return "";
  if (format === "runtime") {
    return getOrCreateExportVariableName(normalizeExportVariableSourceKey(key), context.model, context.warnings, context.ref);
  }
  if (format === "yarn") return `$${key}`;
  if (format === "twee") return `$${key}`;
  return key;
}

function formatConditionComparisonOperand(ast, format, context = {}) {
  if (format !== "runtime" || ast?.type !== "identifier") return formatJsConditionAst(ast, format, context);
  const key = normalizeConditionIdentifierPath(ast.path);
  if (!key || ast.path?.[0] === "variables" || isTransientVisitStateKey(key)) return formatJsConditionAst(ast, format, context);
  const resolved = resolveRuntimeStatePath(normalizeExportVariableSourceKey(key), context.model?.sourceVariables || {});
  if (!resolved.found) return formatConditionLiteral(key);
  return formatJsConditionAst(ast, format, context);
}

function normalizeConditionIdentifierPath(path) {
  const parts = (Array.isArray(path) ? path : []).map((part) => normalizeOptionalString(part).trim()).filter(Boolean);
  if (!parts.length) return "";
  if (parts[0] === "variables" && parts.length > 1) return parts.slice(1).join(".");
  return parts.join(".");
}

function formatConditionOperator(operator, format) {
  if (operator === "==" || operator === "===") return format === "runtime" ? "===" : "==";
  if (operator === "!=" || operator === "!==") return format === "runtime" ? "!==" : "!=";
  return operator;
}

function wrapConditionTerm(term) {
  const text = String(term || "").trim();
  if (!text) return "";
  if (/^(?:[$]?[A-Za-z_]\w*(?:\.[A-Za-z_]\w*)?|true|false|null|undefined|-?\d+(?:\.\d+)?)$/.test(text)) return text;
  if (text.startsWith("(") && text.endsWith(")")) return text;
  return `(${text})`;
}

function formatConditionCall(ast, format, context = {}) {
  if (ast.name === "includes") {
    const object = formatJsConditionAst(ast.object, format, context);
    const value = formatJsConditionAst(ast.args?.[0], format, context);
    if (!object || !value) return "";
    if (format === "yarn") return `contains(${object}, ${value})`;
    if (format === "ink") return formatInkIncludesExpression(ast, context);
    return `${object}.includes(${value})`;
  }
  if (JS_CONDITION_LEGACY_FUNCTIONS.has(ast.name)) {
    const key = formatJsConditionAst(ast.args?.[0], format, context);
    const value = formatJsConditionAst(ast.args?.[1], format, context);
    if (!key || !value) return "";
    if (format === "runtime" || format === "twee") return `${key}.includes(${value})`;
    if (format === "ink") return formatInkLegacyMembershipExpression(ast, context);
    return `contains(${key}, ${value})`;
  }
  return "";
}

function formatInkIncludesExpression(ast, context = {}) {
  const key = ast.object?.type === "identifier" ? normalizeConditionIdentifierPath(ast.object.path) : "";
  if (!key) {
    const object = formatJsConditionAst(ast.object, "ink", context);
    const value = formatJsConditionAst(ast.args?.[0], "ink", context);
    return object && value ? `(${object} ? ${value})` : "";
  }
  return formatInkMembershipByKey(key, ast.args?.[0], context);
}

function formatInkLegacyMembershipExpression(ast, context = {}) {
  const key = ast.args?.[0]?.type === "identifier" ? normalizeConditionIdentifierPath(ast.args[0].path) : "";
  if (!key) {
    const object = formatJsConditionAst(ast.args?.[0], "ink", context);
    const value = formatJsConditionAst(ast.args?.[1], "ink", context);
    return object && value ? `(${object} ? ${value})` : "";
  }
  return formatInkMembershipByKey(key, ast.args?.[1], context);
}

function formatInkMembershipByKey(key, valueAst, context = {}) {
  const list = context.inkListMap?.[key];
  const value = formatJsConditionAst(valueAst, "ink", context);
  if (!list) return value ? `(${key} ? ${value})` : "";
  const literal = valueAst?.type === "literal" ? valueAst.value : parseExpressionLiteral(value);
  const item = list.itemByValue.get(String(literal));
  return `(${key} ? ${item?.identifier || makeInkListIdentifier(`${key}_${literal || "item"}`, "item", new Set())})`;
}

function evaluateJsConditionAst(ast, variables) {
  if (!ast) return false;
  if (ast.type === "literal") return ast.value;
  if (ast.type === "identifier") return resolveJsConditionIdentifier(ast.path, variables);
  if (ast.type === "group") return evaluateJsConditionAst(ast.expression, variables);
  if (ast.type === "unary") return !coerceBoolean(evaluateJsConditionAst(ast.argument, variables));
  if (ast.type === "logical") {
    if (ast.operator === "&&") return coerceBoolean(evaluateJsConditionAst(ast.left, variables)) && coerceBoolean(evaluateJsConditionAst(ast.right, variables));
    return coerceBoolean(evaluateJsConditionAst(ast.left, variables)) || coerceBoolean(evaluateJsConditionAst(ast.right, variables));
  }
  if (ast.type === "binary") return evaluateJsConditionBinary(ast, variables);
  if (ast.type === "call") return evaluateJsConditionCall(ast, variables);
  return false;
}

function resolveJsConditionIdentifier(path, variables) {
  const key = normalizeConditionIdentifierPath(path);
  if (isTransientVisitStateKey(key)) return isPreviewVisitedStateKeyMet(key);
  return resolveRuntimeStatePath(key, variables).value;
}

function evaluateJsConditionBinary(ast, variables) {
  const left = evaluateJsConditionAst(ast.left, variables);
  const right = evaluateJsConditionComparisonOperand(ast.right, variables);
  if (ast.operator === "===") return expressionValuesStrictMatch(left, right);
  if (ast.operator === "!==") return !expressionValuesStrictMatch(left, right);
  if (ast.operator === "==") return expressionValuesMatch(left, right);
  if (ast.operator === "!=") return !expressionValuesMatch(left, right);
  if (ast.operator === ">=") return left >= right;
  if (ast.operator === "<=") return left <= right;
  if (ast.operator === ">") return left > right;
  if (ast.operator === "<") return left < right;
  return false;
}

function evaluateJsConditionComparisonOperand(ast, variables) {
  if (ast?.type !== "identifier") return evaluateJsConditionAst(ast, variables);
  const key = normalizeConditionIdentifierPath(ast.path);
  if (!key || ast.path?.[0] === "variables" || isTransientVisitStateKey(key)) return evaluateJsConditionAst(ast, variables);
  const resolved = resolveRuntimeStatePath(key, variables);
  return resolved.found ? resolved.value : key;
}

function evaluateJsConditionCall(ast, variables) {
  if (ast.name === "includes") {
    const container = evaluateJsConditionAst(ast.object, variables);
    const value = evaluateJsConditionAst(ast.args?.[0], variables);
    return jsConditionIncludes(container, value);
  }
  if (JS_CONDITION_LEGACY_FUNCTIONS.has(ast.name)) {
    const container = evaluateJsConditionAst(ast.args?.[0], variables);
    const value = evaluateJsConditionAst(ast.args?.[1], variables);
    return expressionContainerHasValue(container, value);
  }
  return false;
}

function jsConditionIncludes(container, value) {
  if (Array.isArray(container)) return container.some((item) => expressionValuesMatch(item, value));
  if (typeof container === "string") return String(value) !== "" && container.includes(String(value));
  return false;
}

function expressionValuesStrictMatch(left, right) {
  return left === right;
}

function collectJsConditionAstKeys(ast, variables = {}) {
  const keys = [];
  const membershipKeys = [];
  const scan = (node, options = {}) => {
    if (!node) return;
    if (node.type === "identifier") {
      const key = normalizeConditionIdentifierPath(node.path);
      if (key && !JS_CONDITION_LITERAL_WORDS.has(key)) {
        keys.push(key);
        if (options.membership) membershipKeys.push(key);
      }
      return;
    }
    if (node.type === "group") scan(node.expression, options);
    else if (node.type === "unary") scan(node.argument, options);
    else if (node.type === "logical") {
      scan(node.left, options);
      scan(node.right, options);
    } else if (node.type === "binary") {
      scan(node.left, options);
      if (shouldCollectComparisonRightKey(node.right, variables)) scan(node.right, options);
    } else if (node.type === "call") {
      if (node.name === "includes") {
        scan(node.object, { membership: true });
        (node.args || []).forEach((arg) => scan(arg));
      } else if (JS_CONDITION_LEGACY_FUNCTIONS.has(node.name)) {
        scan(node.args?.[0], { membership: true });
        scan(node.args?.[1]);
      } else {
        (node.args || []).forEach((arg) => scan(arg));
      }
    }
  };
  scan(ast);
  return {
    keys: uniqueExpressionKeys(keys),
    membershipKeys: uniqueExpressionKeys(membershipKeys),
    invalid: false
  };
}

function shouldCollectComparisonRightKey(node, variables) {
  if (node?.type !== "identifier") return true;
  const key = normalizeConditionIdentifierPath(node.path);
  if (!key) return false;
  if (node.path?.[0] === "variables") return true;
  return resolveRuntimeStatePath(key, variables).found;
}

function transformExportExpression(source, model, warnings, ref = {}) {
  const text = String(source || "").trim();
  if (!text) return "";
  const parsed = parseJsConditionExpression(text);
  if (parsed.invalid) {
    pushExportWarning(warnings, "expression-not-translated", `Expression "${text}" is kept in Runtime JSON; Yarn, Ink, and Twee use a false guard.`, ref);
    return text;
  }
  return formatJsConditionAst(parsed.ast, "runtime", { model, warnings, ref });
}

function normalizeExportVariableSourceKey(key) {
  const value = String(key || "").trim();
  return value.startsWith("variables.") ? value.slice("variables.".length) : value;
}

function getOrCreateExportVariableName(key, model, warnings, ref) {
  const sourceKey = String(key || "").trim();
  if (!sourceKey) return "";
  if (model.variableNameMap[sourceKey]) return model.variableNameMap[sourceKey];
  const resolvedPath = resolveRuntimeStatePath(sourceKey, model.sourceVariables);
  if (resolvedPath.found) {
    const safeKey = makeUniqueExportIdentifier(sourceKey, "variable", model.variableUsed, "variable", warnings, ref);
    model.variableNameMap[sourceKey] = safeKey;
    model.variables[safeKey] = cloneRuntimeExportValue(resolvedPath.value);
    if (resolvedPath.kind === "path") {
      pushExportWarning(warnings, "state-path-flattened", `State path "${sourceKey}" exports as "${safeKey}" for portable text formats.`, ref);
    }
    return safeKey;
  }
  const safeKey = makeUniqueExportIdentifier(sourceKey, "variable", model.variableUsed, "variable", warnings, ref);
  model.variableNameMap[sourceKey] = safeKey;
  pushExportWarning(warnings, "implicit-variable", `State key "${sourceKey}" is referenced or written but has no initial variable value.`, ref);
  return safeKey;
}

function makeUniqueExportIdentifier(value, fallback, used, kind, warnings, options = {}) {
  const original = String(options.original || value || "").trim();
  const raw = String(value || "").trim();
  let base = raw
    .replace(/\./g, "_")
    .replace(/[^a-zA-Z0-9_]+/g, "_")
    .replace(/^_+|_+$/g, "");
  if (!base) base = fallback;
  if (!/^[a-zA-Z_]/.test(base)) base = `${fallback}_${base}`;
  let candidate = base;
  let suffix = 2;
  while (used.has(candidate)) {
    candidate = `${base}_${suffix}`;
    suffix += 1;
  }
  used.add(candidate);
  if (!options.suppressSanitizedWarning && original && candidate !== original) {
    const code = candidate === base ? `${kind}-name-sanitized` : `${kind}-name-collision`;
    pushExportWarning(warnings, code, `${titleCase(kind)} "${original}" exports as "${candidate}".`);
  }
  return candidate;
}

function combineRuntimeConditions(conditions, operator) {
  const items = conditions.map((condition) => String(condition || "").trim()).filter(Boolean);
  if (!items.length) return "";
  if (items.length === 1) return items[0];
  return items.map((condition) => `(${condition})`).join(` ${operator} `);
}

function pushExportWarning(warnings, code, message, ref = {}) {
  if (!Array.isArray(warnings)) return;
  warnings.push({
    code,
    message,
    ...(ref.nodeId ? { nodeId: ref.nodeId } : {}),
    ...(ref.linkId ? { linkId: ref.linkId } : {}),
    ...(ref.choiceId ? { choiceId: ref.choiceId } : {})
  });
}

function buildYarnScript(document, options = {}) {
  const documentSource = Boolean(options.documentSource);
  const nodeMap = new Map(document.nodes.map((node) => [node.id, node]));
  const formatContext = {};
  const lines = buildExportHeaderLines(document, "Yarn Spinner");
  if (documentSource) lines.push(`// narrativeCanvasNotes: ${encodeURIComponent(document.source?.notes || "")}`, "");
  document.nodes.forEach((node) => {
    lines.push(`title: ${node.slug}`);
    lines.push(`narrativeCanvasId: ${node.id}`);
    lines.push(`nodeType: ${makePlainHeaderValue(node.typeLabel || node.type)}`);
    if (documentSource) lines.push(`nodeTitle: ${formatDocumentLiteral(getDocumentSourceNodeTitle(node))}`);
    lines.push("---");
    if (node.id === document.startNodeId) {
      appendYarnVariableDeclarations(lines, document, { documentSource });
    }
    appendYarnNodeEffects(lines, node.effects);
    if (documentSource) lines.push("// narrativeCanvasBody:start");
    appendTextLines(lines, convertRuntimeTextForFormat(
      convertNarrativeRichText(node.body, document.source?.richTextFormat, "unity"),
      document,
      "yarn"
    ));
    if (documentSource) lines.push("// narrativeCanvasBody:end");
    appendYarnRouting(lines, node, nodeMap, document, formatContext);
    lines.push("===", "");
  });
  return lines.join("\n").trimEnd() + "\n";
}

function buildInkScript(document, options = {}) {
  const documentSource = Boolean(options.documentSource);
  const nodeMap = new Map(document.nodes.map((node) => [node.id, node]));
  const formatContext = { inkListMap: buildInkListMap(document) };
  const lines = buildExportHeaderLines(document, "ink");
  if (documentSource) lines.push(`// narrativeCanvasNotes: ${encodeURIComponent(document.source?.notes || "")}`, "");
  appendInkVariableDeclarations(lines, document, formatContext, { documentSource });
  if (document.startNode) {
    lines.push(`-> ${document.startNode}`, "");
  }
  document.nodes.forEach((node) => {
    lines.push(`// narrativeCanvasId: ${node.id}`);
    lines.push(`// nodeType: ${makePlainHeaderValue(node.typeLabel || node.type)}`);
    if (documentSource) lines.push(`// nodeTitle: ${formatDocumentLiteral(getDocumentSourceNodeTitle(node))}`);
    lines.push(`=== ${node.slug} ===`);
    appendInkNodeEffects(lines, node.effects);
    if (documentSource) lines.push("// narrativeCanvasBody:start");
    appendTextLines(lines, convertRuntimeTextForFormat(
      convertNarrativeRichText(getInkNodeBody(node), document.source?.richTextFormat, "unity"),
      document,
      "ink"
    ));
    if (documentSource) lines.push("// narrativeCanvasBody:end");
    appendInkRouting(lines, node, nodeMap, document, formatContext);
    lines.push("");
  });
  return lines.join("\n").trimEnd() + "\n";
}

function buildTweeScript(document, options = {}) {
  const documentSource = Boolean(options.documentSource);
  const nodeMap = new Map(document.nodes.map((node) => [node.id, node]));
  const formatContext = {};
  const lines = buildTweeHeaderLines(document, options);
  document.nodes.forEach((node) => {
    lines.push(`:: ${formatTweePassageName(node.slug)} [${formatTweeTag(node.type || "node")}]`);
    if (documentSource) {
      lines.push(`<!-- narrativeCanvasId: ${String(node.id || "").replace(/--/g, "-")} -->`);
      lines.push(`<!-- narrativeCanvasTitle: ${encodeURIComponent(getDocumentSourceNodeTitle(node))} -->`);
    }
    appendTweeNodeEffects(lines, node.effects);
    if (documentSource) lines.push("<!-- narrativeCanvasBody:start -->");
    appendTextLines(lines, convertRuntimeTextForFormat(
      convertNarrativeRichText(node.body, document.source?.richTextFormat, "html"),
      document,
      "twee"
    ));
    if (documentSource) lines.push("<!-- narrativeCanvasBody:end -->");
    appendTweeRouting(lines, node, nodeMap, document, formatContext);
    lines.push("");
  });
  return lines.join("\n").trimEnd() + "\n";
}

function formatDialogicCondition(expression) {
  let source = normalizeOptionalString(expression).trim();
  if (!source) return "";
  source = source
    .replace(/===/g, "==")
    .replace(/!==/g, "!=")
    .replace(/&&/g, " and ")
    .replace(/\|\|/g, " or ");
  return source.replace(/\b([A-Za-z_][\w.]*)\b/g, (match, key, offset, whole) => {
    if (["true", "false", "null", "and", "or", "not"].includes(key.toLowerCase())) return match;
    const previous = whole.slice(0, offset);
    if ((previous.match(/"/g) || []).length % 2 || (previous.match(/'/g) || []).length % 2) return match;
    return `{${key}}`;
  });
}

function formatDialogicValue(value) {
  const source = normalizeOptionalString(value).trim();
  if (!source) return '""';
  if (/^(true|false|null|-?\d+(?:\.\d+)?)$/i.test(source)) return source;
  if (/^\{[^}]+\}$/.test(source)) return source;
  return `"${source.replaceAll("\\", "\\\\").replaceAll('"', '\\"')}"`;
}

function formatDialogicEffect(effect) {
  const key = normalizeOptionalString(effect?.key || effect?.stateKey).trim();
  if (!key) return `# Unsupported effect: ${normalizeOptionalString(effect?.op || "unknown")}`;
  const variable = `{${key}}`;
  const value = formatDialogicValue(effect?.value);
  const operation = {
    set: "=",
    add: "+=",
    subtract: "-=",
    append: "+="
  }[effect?.op];
  if (operation) return `set ${variable} ${operation} ${value}`;
  if (effect?.op === "toggle") return `set ${variable} = not ${variable}`;
  if (effect?.op === "clear") return `set ${variable} = null`;
  return `# Unsupported effect ${effect?.op || "unknown"} on ${key}`;
}

function appendDialogicNodeBody(lines, node, document, indent = "") {
  const format = normalizeRichTextFormat(document?.source?.richTextFormat);
  const body = convertNarrativeRichText(node.body || "", format, "bbcode");
  String(body).split(/\r?\n/).forEach((line) => {
    if (line.trim()) lines.push(`${indent}${line}`);
  });
}

function buildDialogicScript(document) {
  const lines = [
    `# Exported from Narrative Canvas: ${document.source?.title || "Untitled"}`,
    "# Target: Dialogic 2 timeline text (.dtl)",
    ""
  ];
  const nodes = Array.isArray(document.nodes) ? document.nodes : [];
  for (const node of nodes) {
    lines.push(`label ${node.slug} (${String(node.title || node.slug).replace(/[()\r\n]/g, " ")})`);
    const requirement = formatDialogicCondition(node.requirements);
    const bodyIndent = requirement ? "\t" : "";
    if (requirement) lines.push(`if ${requirement}:`);
    (node.effects || []).forEach((effect) => lines.push(`${bodyIndent}${formatDialogicEffect(effect)}`));
    appendDialogicNodeBody(lines, node, document, bodyIndent);
    if (node.choices?.length) {
      for (const choice of node.choices) {
        const condition = formatDialogicCondition(choice.condition);
        lines.push(`${bodyIndent}- ${choice.label || "Continue"}${condition ? ` | [if ${condition}]` : ""}`);
        const choiceIndent = `${bodyIndent}\t`;
        (choice.effects || []).forEach((effect) => lines.push(`${choiceIndent}${formatDialogicEffect(effect)}`));
        if (choice.target) lines.push(`${choiceIndent}jump ${choice.target}`);
      }
    } else if (node.next?.length) {
      for (const transition of node.next) {
        const condition = formatDialogicCondition(transition.condition);
        if (condition) {
          lines.push(`${bodyIndent}if ${condition}:`);
          if (transition.target) lines.push(`${bodyIndent}\tjump ${transition.target}`);
        } else if (transition.target) {
          lines.push(`${bodyIndent}jump ${transition.target}`);
        }
      }
    } else {
      lines.push(`${bodyIndent}[end_timeline]`);
    }
    lines.push("");
  }
  return lines.join("\n").trimEnd() + "\n";
}

function buildUnrealConversationDocument(document) {
  const sourceFormat = normalizeRichTextFormat(document?.source?.richTextFormat);
  return {
    format: "narrative-canvas-unreal-conversation",
    version: 1,
    target: {
      engine: "Unreal Engine",
      system: "CommonConversation",
      integration: "adapter-import",
      note: "CommonConversation assets are UPrimaryDataAsset graphs; import this JSON with a Narrative Canvas editor utility or custom importer."
    },
    source: {
      title: document?.source?.title || "Untitled",
      exportedAt: document?.exportedAt || new Date().toISOString(),
      richTextFormat: "unreal"
    },
    richTextStyles: {
      NCBold: "bold",
      NCItalic: "italic",
      NCStrike: "strikethrough",
      NCCode: "inline-code",
      NCCodeBlock: "code-block",
      NCHighlight: "highlight",
      NCColor: "text-color decorator; read the value metadata",
      NCLink: "hyperlink decorator; read the href metadata",
      NCH1: "heading-1",
      NCH2: "heading-2",
      NCH3: "heading-3",
      NCQuote: "quote"
    },
    entryPoints: (document?.nodes || [])
      .filter((node) => node.type === "Entry")
      .map((node) => ({ tag: node.slug, nodeId: node.id })),
    defaultEntry: document?.startNode || "",
    variables: cloneRuntimeExportValue(document?.variables || {}),
    participants: cloneRuntimeExportValue(document?.characters || []),
    nodes: (document?.nodes || []).map((node) => ({
      id: node.id,
      name: node.slug,
      title: node.title,
      type: node.type,
      text: convertNarrativeRichText(node.body || "", sourceFormat, "unreal"),
      requirements: node.requirements || "",
      effects: cloneRuntimeExportValue(node.effects || []),
      choices: (node.choices || []).map((choice) => ({
        id: choice.id || "",
        text: convertNarrativeRichText(choice.label || "", sourceFormat, "unreal"),
        target: choice.target || "",
        targetId: choice.targetId || "",
        condition: choice.condition || "",
        effects: cloneRuntimeExportValue(choice.effects || [])
      })),
      transitions: cloneRuntimeExportValue(node.next || []),
      cast: cloneRuntimeExportValue(node.cast || []),
      customFields: cloneRuntimeExportValue(node.customFields || {})
    }))
  };
}

function getDocumentSourceNodeTitle(runtimeNode) {
  const sourceNode = getNode(runtimeNode?.id);
  return sourceNode?.title || runtimeNode?.title || runtimeNode?.slug || runtimeNode?.id || "Untitled";
}

function buildTweeHeaderLines(document, options = {}) {
  const lines = [];
  lines.push(":: StoryData");
  lines.push(JSON.stringify({
    ifid: buildDeterministicIfid(document),
    format: "SugarCube",
    "format-version": TWEE_SUGARCUBE_FORMAT_VERSION,
    start: document.startNode || "Start"
  }, null, 2));
  lines.push("");
  lines.push(":: StoryTitle");
  lines.push(document.source?.title || "Untitled");
  lines.push("");
  if (options.documentSource) {
    lines.push(":: NarrativeCanvasProjectNotes [annotation]");
    lines.push(`<!-- narrativeCanvasNotes: ${encodeURIComponent(document.source?.notes || "")} -->`);
    lines.push("");
  }
  lines.push(":: StoryInit");
  appendTweeVariableDeclarations(lines, document);
  if (!Object.keys(document.variables || {}).length) lines.push("/* No initial variables. */");
  lines.push("");
  appendTweeExportReportPassage(lines, document);
  return lines;
}

function appendTweeExportReportPassage(lines, document) {
  const warnings = document.report?.warnings || [];
  lines.push(":: NarrativeCanvasExportReport [annotation]");
  lines.push(`Exported from Narrative Canvas as Twee 3 / SugarCube.`);
  lines.push(`Source: ${document.source?.title || "Untitled"}`);
  if (warnings.length) {
    lines.push("");
    lines.push("Export report warnings:");
    warnings.slice(0, 40).forEach((warning) => lines.push(`- [${warning.code}] ${warning.message}`));
    if (warnings.length > 40) lines.push(`- ${warnings.length - 40} more warning(s) are available in runtime JSON.`);
  }
  lines.push("");
}

function buildExportHeaderLines(document, formatName) {
  const lines = [
    `// Exported from Narrative Canvas as ${formatName}.`,
    `// Source: ${document.source?.title || "Untitled"}`
  ];
  const warnings = document.report?.warnings || [];
  if (warnings.length) {
    lines.push("// Export report warnings:");
    warnings.slice(0, 40).forEach((warning) => lines.push(`// - [${warning.code}] ${warning.message}`));
    if (warnings.length > 40) lines.push(`// - ${warnings.length - 40} more warning(s) are available in runtime JSON.`);
  }
  lines.push("");
  return lines;
}

function appendYarnVariableDeclarations(lines, document, options = {}) {
  Object.entries(document.variables || {}).forEach(([key, value]) => {
    if (Array.isArray(value)) {
      lines.push(`<<declare $${key} = ${formatYarnArrayLiteral(value)}>>`);
      return;
    }
    if (isComplexRuntimeValue(value)) {
      if (options.documentSource) lines.push(`// narrativeCanvasVariable: ${key} = ${formatDocumentLiteral(value)}`);
      lines.push(`// Skipped complex variable $${key}; see runtime JSON.`);
      return;
    }
    lines.push(`<<declare $${key} = ${formatExportLiteral(value)}>>`);
  });
  if (Object.keys(document.variables || {}).length) lines.push("");
}

function appendInkVariableDeclarations(lines, document, context = {}, options = {}) {
  const inkListMap = context.inkListMap || {};
  Object.entries(document.variables || {}).forEach(([key, value]) => {
    if (Array.isArray(value)) {
      const list = inkListMap[key];
      if (options.documentSource) {
        const valueMap = {};
        (list?.items || []).forEach((item) => {
          const original = value.find((entry) => String(entry) === item.value);
          valueMap[item.identifier] = original === undefined ? item.value : original;
        });
        lines.push(`// narrativeCanvasListValues: ${key} = ${formatDocumentLiteral(valueMap)}`);
      }
      if (!list || !list.items.length) {
        lines.push(`// Skipped empty list ${key}; see runtime JSON.`);
        return;
      }
      lines.push(`LIST ${list.listName} = ${list.items.map((item) => item.identifier).join(", ")}`);
      lines.push(`VAR ${key} = (${list.initialItems.map((item) => item.identifier).join(", ")})`);
      return;
    }
    if (isComplexRuntimeValue(value)) {
      if (options.documentSource) lines.push(`// narrativeCanvasVariable: ${key} = ${formatDocumentLiteral(value)}`);
      lines.push(`// Skipped complex variable ${key}; see runtime JSON.`);
      return;
    }
    lines.push(`VAR ${key} = ${formatExportLiteral(value)}`);
  });
  if (Object.keys(document.variables || {}).length) lines.push("");
}

function appendTweeVariableDeclarations(lines, document) {
  Object.entries(document.variables || {}).forEach(([key, value]) => {
    lines.push(`<<set $${key} = ${formatSugarCubeLiteral(value)}>>`);
  });
}

function appendYarnRouting(lines, node, nodeMap, document, context = {}) {
  if (node.choices.length) {
    node.choices.forEach((choice) => {
      const condition = formatRuntimeExpressionForFormat(choice.condition, "yarn", context);
      const suffix = condition ? ` <<if ${condition}>>` : "";
      lines.push(`-> ${formatYarnOptionLabel(convertRuntimeTextForFormat(choice.label, document, "yarn"))}${suffix}`);
      choice.effects.forEach((effect) => lines.push(indentEffectText(formatYarnEffect(effect), "    ")));
      appendYarnJump(lines, choice.targetId, nodeMap, "    ");
    });
    return;
  }
  appendYarnTransitions(lines, node.next, nodeMap, context);
}

function appendYarnTransitions(lines, transitions, nodeMap, context = {}) {
  (transitions || []).forEach((transition) => {
    if (transition.condition) {
      lines.push(`<<if ${formatRuntimeExpressionForFormat(transition.condition, "yarn", context)}>>`);
      appendYarnJump(lines, transition.targetId, nodeMap, "    ");
      lines.push("<<endif>>");
    } else {
      appendYarnJump(lines, transition.targetId, nodeMap, "");
    }
  });
}

function appendYarnJump(lines, targetId, nodeMap, indent) {
  const target = nodeMap.get(targetId);
  if (target) lines.push(`${indent}<<jump ${target.slug}>>`);
}

function appendInkRouting(lines, node, nodeMap, document, context = {}) {
  if (node.choices.length) {
    node.choices.forEach((choice) => {
      const condition = formatRuntimeExpressionForFormat(choice.condition, "ink", context);
      const conditionPrefix = condition ? `{${condition}} ` : "";
      lines.push(`+ ${conditionPrefix}[${formatInkOptionLabel(convertRuntimeTextForFormat(choice.label, document, "ink"))}]`);
      choice.effects.forEach((effect) => lines.push(indentEffectText(formatInkEffect(effect), "    ")));
      appendInkDivert(lines, choice.targetId, nodeMap, "    ");
    });
    return;
  }
  if (node.next.length) {
    node.next.forEach((transition) => {
      if (transition.condition) {
        lines.push(`{ ${formatRuntimeExpressionForFormat(transition.condition, "ink", context)}:`);
        appendInkDivert(lines, transition.targetId, nodeMap, "    ");
        lines.push("}");
      } else {
        appendInkDivert(lines, transition.targetId, nodeMap, "");
      }
    });
    return;
  }
  lines.push("-> END");
}

function appendInkDivert(lines, targetId, nodeMap, indent) {
  const target = nodeMap.get(targetId);
  lines.push(target ? `${indent}-> ${target.slug}` : `${indent}-> END`);
}

function getInkNodeBody(node) {
  return String(node?.body || "");
}

function getPortableNodeEffects(effects) {
  return (Array.isArray(effects) ? effects : [])
    .filter((effect) => !isRuntimeVisitTrackingEffect(effect))
    .filter((effect) => effect?.trigger === "onVisit" || !effect?.trigger);
}

function appendYarnNodeEffects(lines, effects) {
  const entries = getPortableNodeEffects(effects);
  entries.forEach((effect) => lines.push(formatYarnEffect(effect)));
  if (entries.length) lines.push("");
}

function appendInkNodeEffects(lines, effects) {
  const entries = getPortableNodeEffects(effects);
  entries.forEach((effect) => lines.push(formatInkEffect(effect)));
  if (entries.length) lines.push("");
}

function appendTweeNodeEffects(lines, effects) {
  const entries = getPortableNodeEffects(effects);
  entries.forEach((effect) => lines.push(formatTweeEffect(effect)));
  if (entries.length) lines.push("");
}

function appendTweeRouting(lines, node, nodeMap, document, context = {}) {
  if (node.choices.length) {
    node.choices.forEach((choice) => {
      const condition = formatRuntimeExpressionForFormat(choice.condition, "twee", context);
      if (condition) lines.push(`<<if ${condition}>>`);
      appendTweeLink(lines, choice.label, choice.targetId, nodeMap, choice.effects, condition ? "  " : "");
      if (condition) lines.push("<</if>>");
    });
    return;
  }
  appendTweeTransitions(lines, node.next, nodeMap, context);
}

function appendTweeTransitions(lines, transitions, nodeMap, context = {}) {
  (transitions || []).forEach((transition) => {
    const condition = formatRuntimeExpressionForFormat(transition.condition, "twee", context);
    if (condition) lines.push(`<<if ${condition}>>`);
    const target = nodeMap.get(transition.targetId);
    if (target) {
      const label = transition.source === "routing" ? "Continue" : (transition.label || "Continue");
      appendTweeLink(lines, label, transition.targetId, nodeMap, [], condition ? "  " : "");
    }
    if (condition) lines.push("<</if>>");
  });
}

function appendTweeLink(lines, label, targetId, nodeMap, effects, indent = "") {
  const target = nodeMap.get(targetId);
  const text = formatTweeLinkText(label || "Continue");
  if (!target) {
    lines.push(`${indent}${text}`);
    return;
  }
  const entries = Array.isArray(effects) ? effects : [];
  if (!entries.length) {
    lines.push(`${indent}[[${formatTweeWikiLinkText(text)}->${formatTweeWikiLinkText(target.slug)}]]`);
    return;
  }
  lines.push(`${indent}<<link ${formatSugarCubeString(text)} ${formatSugarCubeString(target.slug)}>>`);
  entries.forEach((effect) => lines.push(indentEffectText(formatTweeEffect(effect), `${indent}  `)));
  lines.push(`${indent}<</link>>`);
}

function formatYarnEffect(effect) {
  if (effect?.op === "ifElse") {
    const condition = formatRuntimeExpressionForFormat(effect.condition, "yarn");
    return [
      `<<if ${condition}>>`,
      indentEffectText(formatYarnEffect(effect.thenEffect), "    "),
      "<<else>>",
      indentEffectText(formatYarnEffect(effect.elseEffect), "    "),
      "<<endif>>"
    ].join("\n");
  }
  if (!effect?.key) return "// Skipped effect without a state key.";
  if (effect.op === "set") return `<<set $${effect.key} to ${formatExportEffectValue(effect, "yarn")}>>`;
  if (effect.op === "add") return `<<set $${effect.key} to $${effect.key} + ${formatExportEffectValue(effect, "yarn")}>>`;
  if (effect.op === "subtract") return `<<set $${effect.key} to $${effect.key} - ${formatExportEffectValue(effect, "yarn")}>>`;
  if (effect.op === "toggle") return `<<set $${effect.key} to not $${effect.key}>>`;
  return `// Runtime-only effect: ${effect.op} ${effect.sourceKey || effect.key}`;
}

function formatInkEffect(effect) {
  if (effect?.op === "ifElse") {
    const condition = formatRuntimeExpressionForFormat(effect.condition, "ink");
    return [
      `{ ${condition}:`,
      indentEffectText(formatInkEffect(effect.thenEffect), "    "),
      "- else:",
      indentEffectText(formatInkEffect(effect.elseEffect), "    "),
      "}"
    ].join("\n");
  }
  if (!effect?.key) return "// Skipped effect without a state key.";
  if (effect.op === "set") return `~ ${effect.key} = ${formatExportEffectValue(effect, "ink")}`;
  if (effect.op === "add") return `~ ${effect.key} = ${effect.key} + ${formatExportEffectValue(effect, "ink")}`;
  if (effect.op === "subtract") return `~ ${effect.key} = ${effect.key} - ${formatExportEffectValue(effect, "ink")}`;
  if (effect.op === "toggle") return `~ ${effect.key} = not ${effect.key}`;
  return `// Runtime-only effect: ${effect.op} ${effect.sourceKey || effect.key}`;
}

function formatTweeEffect(effect) {
  if (effect?.op === "ifElse") {
    const condition = formatRuntimeExpressionForFormat(effect.condition, "twee");
    return [
      `<<if ${condition}>>`,
      indentEffectText(formatTweeEffect(effect.thenEffect), "  "),
      "<<else>>",
      indentEffectText(formatTweeEffect(effect.elseEffect), "  "),
      "<</if>>"
    ].join("\n");
  }
  if (!effect?.key) return "/* Skipped effect without a state key. */";
  const value = formatExportEffectValue(effect, "twee");
  if (effect.op === "set") return `<<set $${effect.key} = ${value}>>`;
  if (effect.op === "add") return `<<set $${effect.key} += ${value}>>`;
  if (effect.op === "subtract") return `<<set $${effect.key} -= ${value}>>`;
  if (effect.op === "toggle") return `<<set $${effect.key} = !$${effect.key}>>`;
  return `/* Runtime-only effect: ${effect.op} ${effect.sourceKey || effect.key} */`;
}

function indentEffectText(text, indent) {
  return String(text || "").split("\n").map((line) => `${indent}${line}`).join("\n");
}

function formatExportEffectValue(effect, format = "plain") {
  const source = normalizeOptionalString(effect?.valueSource ?? effect?.value).trim();
  if (effect?.valueMode === "variable" && source) {
    if (format === "yarn") return `$${source}`;
    if (format === "twee") return `$${source}`;
    return source;
  }
  return format === "twee"
    ? formatSugarCubeLiteral(coerceValue(source))
    : formatExportLiteral(coerceValue(source));
}

function formatExportLiteral(value) {
  if (typeof value === "number" && Number.isFinite(value)) return String(value);
  if (typeof value === "boolean") return value ? "true" : "false";
  if (value == null) return "null";
  return JSON.stringify(String(value));
}

function formatYarnArrayLiteral(value) {
  return JSON.stringify(JSON.stringify((Array.isArray(value) ? value : []).map((item) => {
    if (item == null || typeof item === "string" || typeof item === "number" || typeof item === "boolean") return item;
    return String(item);
  })));
}

function formatSugarCubeLiteral(value) {
  if (typeof value === "number" && Number.isFinite(value)) return String(value);
  if (typeof value === "boolean") return value ? "true" : "false";
  if (value == null) return "null";
  if (typeof value === "object") return JSON.stringify(value);
  return JSON.stringify(String(value));
}

function formatSugarCubeString(value) {
  return JSON.stringify(String(value || ""));
}

function formatRuntimeExpressionForFormat(expression, format, context = {}) {
  const output = String(expression || "").trim();
  if (!output) return "";
  const parsed = parseJsConditionExpression(output);
  if (parsed.invalid) {
    // Runtime JSON and the export report keep the original expression; text formats stay parseable.
    return "false";
  }
  return formatJsConditionAst(parsed.ast, format, context);
}

function buildInkListMap(document) {
  const used = new Set();
  const maps = {};
  Object.entries(document?.variables || {}).forEach(([key, value]) => {
    if (!Array.isArray(value)) return;
    const listName = makeInkListIdentifier(`${key}_items`, "list_items", used);
    const itemByValue = new Map();
    const addItem = (rawValue) => {
      const normalizedValue = String(rawValue);
      if (itemByValue.has(normalizedValue)) return itemByValue.get(normalizedValue);
      const identifier = makeInkListIdentifier(`${key}_${normalizedValue}`, "item", used);
      const item = { value: normalizedValue, identifier };
      itemByValue.set(normalizedValue, item);
      return item;
    };
    const initialItems = value.map(addItem);
    maps[key] = {
      listName,
      itemByValue,
      get items() {
        return [...itemByValue.values()];
      },
      initialItems
    };
  });
  collectDocumentMembershipPredicates(document).forEach((predicate) => {
    const key = normalizeExpressionVariableTerm(predicate.key) || predicate.key;
    const list = maps[key];
    if (!list) return;
    const literal = parseExpressionLiteral(predicate.value);
    if (literal == null || typeof literal === "object") return;
    if (!list.itemByValue.has(String(literal))) {
      const identifier = makeInkListIdentifier(`${key}_${literal}`, "item", used);
      list.itemByValue.set(String(literal), { value: String(literal), identifier });
    }
  });
  return maps;
}

function collectDocumentMembershipPredicates(document) {
  const predicates = [];
  const scan = (source) => {
    collectExpressionPredicates(source).forEach((predicate) => predicates.push(predicate));
  };
  (document?.nodes || []).forEach((node) => {
    (node.choices || []).forEach((choice) => scan(choice.condition));
    (node.next || []).forEach((transition) => scan(transition.condition));
  });
  return predicates;
}

function makeInkListIdentifier(value, fallback, used) {
  let base = String(value || "")
    .replace(/[^a-zA-Z0-9_]+/g, "_")
    .replace(/^_+|_+$/g, "");
  if (!base) base = fallback;
  if (!/^[a-zA-Z_]/.test(base)) base = `${fallback}_${base}`;
  let candidate = base;
  let suffix = 2;
  while (used.has(candidate)) {
    candidate = `${base}_${suffix}`;
    suffix += 1;
  }
  used.add(candidate);
  return candidate;
}

function convertRuntimeTextForFormat(text, document, format) {
  const variables = new Set(document.variableNames || []);
  return String(text || "").replace(/\{([a-zA-Z_]\w*)\}/g, (match, key) => {
    if (!variables.has(key)) return match;
    if (format === "twee") return `<<print $${key}>>`;
    return format === "yarn" ? `{$${key}}` : `{${key}}`;
  });
}

function formatTweePassageName(value) {
  return String(value || "Untitled")
    .replace(/\\/g, "\\\\")
    .replace(/([\[\]{}])/g, "\\$1");
}

function formatTweeTag(value) {
  return String(value || "node").replace(/[^a-zA-Z0-9_-]+/g, "_") || "node";
}

function formatTweeLinkText(value) {
  return String(value || "Continue").replace(/\r?\n+/g, " ").replace(/\s+/g, " ").trim() || "Continue";
}

function formatTweeWikiLinkText(value) {
  return String(value || "").replace(/\]/g, "&#93;");
}

function buildDeterministicIfid(document) {
  const source = [
    document?.source?.title || "Untitled",
    document?.startNodeId || "",
    ...(Array.isArray(document?.nodes) ? document.nodes.map((node) => `${node.id}:${node.slug}`) : [])
  ].join("|");
  const hex = [
    hashString32(`${source}:0`),
    hashString32(`${source}:1`),
    hashString32(`${source}:2`),
    hashString32(`${source}:3`)
  ].map((value) => value.toString(16).padStart(8, "0")).join("").toUpperCase();
  return `${hex.slice(0, 8)}-${hex.slice(8, 12)}-4${hex.slice(13, 16)}-A${hex.slice(17, 20)}-${hex.slice(20, 32)}`;
}

function hashString32(value) {
  let hash = 2166136261;
  for (let index = 0; index < String(value).length; index += 1) {
    hash ^= String(value).charCodeAt(index);
    hash = Math.imul(hash, 16777619);
  }
  return hash >>> 0;
}

function appendTextLines(lines, text) {
  const value = String(text || "").trimEnd();
  if (!value) return;
  value.split(/\r?\n/).forEach((line) => lines.push(line));
}

function formatYarnOptionLabel(label) {
  return String(label || "Continue").replace(/\s+/g, " ").trim() || "Continue";
}

function formatInkOptionLabel(label) {
  return String(label || "Continue").replace(/[\[\]\r\n]+/g, " ").replace(/\s+/g, " ").trim() || "Continue";
}

function buildStoryMarkdown(document, options = {}) {
  const documentSource = Boolean(options.documentSource);
  const nodeMap = new Map((document.nodes || []).map((node) => [node.id, node]));
  const lines = [
    `# ${formatMarkdownHeading(document.source?.title || "Untitled Story")}`,
    "",
    "<!-- narrative-canvas-story-md: v1 -->",
    ""
  ];
  if (document.source?.notes) {
    lines.push("> Source notes");
    convertNarrativeRichText(document.source.notes, document.source?.richTextFormat, "markdown")
      .split(/\r?\n/)
      .forEach((line) => lines.push(`> ${line}`));
    lines.push("");
  }
  const variables = Object.entries(document.variables || {});
  if (variables.length) {
    lines.push("### Variables");
    variables.forEach(([key, value]) => lines.push(`- \`${key}\` = ${formatDocumentLiteral(value)}`));
    lines.push("");
  }
  (document.nodes || []).forEach((node) => {
    const sourceTitle = documentSource ? getDocumentSourceNodeTitle(node) : (node.title || node.slug || node.id);
    lines.push(`## ${formatMarkdownHeading(sourceTitle)}`);
    lines.push(`<!-- id: ${node.id} -->`);
    lines.push(`type: ${formatMarkdownInline(node.typeLabel || node.type || "Node")}`);
    lines.push(`slug: ${formatMarkdownInline(node.slug || node.id)}`);
    if (node.requirements) lines.push(`requires: ${node.requirements}`);
    if (node.cast?.length) lines.push(`cast: ${node.cast.map((entry) => entry.name).filter(Boolean).join(", ")}`);
    lines.push("");
    if (documentSource) lines.push("<!-- narrativeCanvasBody:start -->");
    appendStoryMarkdownBody(lines, convertNarrativeRichText(node.body, document.source?.richTextFormat, "markdown"));
    if (documentSource) lines.push("<!-- narrativeCanvasBody:end -->", "");
    appendStoryMarkdownEffects(lines, node.effects, "effects");
    appendStoryMarkdownChoices(lines, node, nodeMap);
    appendStoryMarkdownNext(lines, node, nodeMap);
    lines.push("");
  });
  return lines.join("\n").replace(/\n{4,}/g, "\n\n\n").trimEnd() + "\n";
}

function buildStoryLayoutDocument() {
  const nodes = Array.isArray(state.project.nodes) ? state.project.nodes : [];
  const links = Array.isArray(state.project.links) ? state.project.links : [];
  return {
    format: "narrative-canvas-story-layout",
    version: 1,
    exportedAt: new Date().toISOString(),
    source: {
      title: state.project.title || "Untitled",
      notes: state.project.notes || ""
    },
    nodes: nodes.map((node) => ({
      id: node.id,
      title: node.title || "",
      type: node.type || "Content",
      typeLabel: getNodeTypeLabel(node.type),
      frame: Boolean(isFrameNode(node)),
      x: Number(node.x) || 0,
      y: Number(node.y) || 0,
      ...(node.width != null ? { width: Number(node.width) || 0 } : {}),
      ...(node.height != null ? { height: Number(node.height) || 0 } : {}),
      ...(node.frameId ? { frameId: node.frameId } : {}),
      ...(node.ports ? { portPositions: cloneRuntimeExportValue(node.ports) } : {}),
      ...(node.collapsed != null ? { collapsed: Boolean(node.collapsed) } : {})
    })),
    links: links.map((link) => ({
      id: link.id || "",
      from: link.from || "",
      to: link.to || "",
      label: link.label || "",
      ...(link.choiceIndex != null ? { choiceIndex: link.choiceIndex } : {}),
      ...(link.choiceOptionId ? { choiceOptionId: link.choiceOptionId } : {}),
      ...(link.requirements || link.requires ? { requirements: link.requirements || link.requires } : {})
    })),
    view: normalizeView(state.view)
  };
}

function buildStateSchemaDocument() {
  const report = buildStateReport();
  const exportWarnings = [];
  const exportNameModel = buildRuntimeExportNameModel(exportWarnings);
  return {
    format: "narrative-canvas-state-schema",
    version: 1,
    exportedAt: new Date().toISOString(),
    source: {
      title: state.project.title || "Untitled",
      notes: state.project.notes || ""
    },
    summary: {
      variableCount: report.rows.length,
      issueCount: report.issueCount,
      readCount: report.readCount,
      writeCount: report.writeCount,
      interpolationCount: report.interpolationCount,
      exportBlockCount: report.exportBlocks.length,
      invalidExpressionCount: report.invalidExpressions.length
    },
    variables: report.rows.map((row) => ({
      key: row.key,
      exportKey: getOrCreateExportVariableName(row.key, exportNameModel, exportWarnings, {}),
      type: row.typeLabel,
      hasInitial: Boolean(row.hasInitial),
      ...(row.hasInitial ? { initialValue: cloneRuntimeExportValue(row.initialValue) } : {}),
      statuses: [...row.statuses],
      primaryStatus: row.primaryStatus,
      readBy: formatStateSchemaRefs(row.reads),
      writtenBy: formatStateSchemaRefs(row.writes),
      interpolatedBy: formatStateSchemaRefs(row.interpolations)
    })),
    invalidExpressions: formatStateSchemaRefs(report.invalidExpressions),
    exportBlocks: report.exportBlocks.map((block) => ({
      code: block.code,
      message: block.message,
      ...(block.key ? { key: block.key } : {}),
      label: block.label,
      ...(block.nodeId ? { nodeId: block.nodeId } : {}),
      ...(block.jsonToken ? { jsonToken: block.jsonToken } : {})
    }))
  };
}

function buildExportProfileDocument(runtimeDocument = buildRuntimeExportDocument()) {
  const slug = slugify(state.project.title || "narrative-canvas");
  const report = runtimeDocument?.report || {};
  return {
    format: "narrative-canvas-export-profile",
    version: 1,
    exportedAt: new Date().toISOString(),
    source: {
      title: runtimeDocument?.source?.title || state.project.title || "Untitled",
      notes: runtimeDocument?.source?.notes || state.project.notes || ""
    },
    baseSlug: slug,
    files: [
      { id: "project-json", name: `${slug}.json`, role: "source", format: "narrative-canvas-project" },
      { id: "story-md", name: `${slug}-story.md`, role: "text-source", format: "story-markdown", schema: "docs/story-markdown-format.md" },
      { id: "layout-json", name: `${slug}-layout.json`, role: "sidecar", format: "narrative-canvas-story-layout", schema: "docs/story-layout.schema.json" },
      { id: "state-schema", name: `${slug}-state.schema.json`, role: "sidecar", format: "narrative-canvas-state-schema", schema: "docs/state-schema.schema.json" },
      { id: "export-profile", name: `${slug}-export.profile.json`, role: "sidecar", format: "narrative-canvas-export-profile", schema: "docs/export-profile.schema.json" },
      { id: "runtime-json", name: `${slug}-runtime.json`, role: "runtime", format: "narrative-canvas-runtime", schema: "docs/runtime-json.schema.json" },
      { id: "yarn", name: `${slug}.yarn`, role: "engine-script", format: "yarn-spinner" },
      { id: "ink", name: `${slug}.ink`, role: "engine-script", format: "ink" },
      { id: "twee", name: `${slug}.twee`, role: "engine-script", format: "twee-3-sugarcube" },
      { id: "dialogic", name: `${slug}.dtl`, role: "engine-script", format: "dialogic-2-timeline" },
      { id: "unreal-conversation", name: `${slug}.conversation.json`, role: "engine-adapter", format: "narrative-canvas-unreal-conversation" }
    ],
    targets: [
      { id: "runtime-json", label: "Runtime JSON", fileId: "runtime-json", consumer: "custom-loader", schema: "docs/runtime-json.schema.json" },
      { id: "yarn", label: "Yarn Spinner", fileId: "yarn", consumer: "ysc" },
      { id: "ink", label: "Ink", fileId: "ink", consumer: "inklecate" },
      { id: "twee", label: "Twee / Twine", fileId: "twee", consumer: "Tweego / SugarCube" },
      { id: "dialogic", label: "Godot Dialogic 2", fileId: "dialogic", consumer: "Dialogic .dtl" },
      { id: "unreal-conversation", label: "Unreal CommonConversation", fileId: "unreal-conversation", consumer: "Narrative Canvas UE importer" }
    ],
    mappings: {
      variables: filterTransientVisitVariableMap(report.variableNameMap || {}),
      nodes: { ...(report.nodeNameMap || {}) }
    },
    warnings: buildExportProfileWarnings(report.warnings)
  };
}

function filterTransientVisitVariableMap(variableNameMap) {
  return Object.fromEntries(
    Object.entries(variableNameMap || {}).filter(([sourceKey]) => !isTransientVisitStateKey(sourceKey))
  );
}

function buildExportProfileWarnings(warnings) {
  return (Array.isArray(warnings) ? warnings : [])
    .filter((warning) => !isTransientVisitExportWarning(warning))
    .map((warning) => ({
      code: warning?.code || "warning",
      message: warning?.message || "",
      ...(warning?.nodeId ? { nodeId: warning.nodeId } : {}),
      ...(warning?.linkId ? { linkId: warning.linkId } : {}),
      ...(warning?.choiceId ? { choiceId: warning.choiceId } : {})
    }));
}

function isTransientVisitExportWarning(warning) {
  return /State key "visited\.[^"]+"/.test(normalizeOptionalString(warning?.message));
}

function formatStateSchemaRefs(refs) {
  return (Array.isArray(refs) ? refs : []).map((ref) => ({
    label: ref.label,
    ...(ref.nodeId ? { nodeId: ref.nodeId } : {}),
    ...(ref.jsonToken ? { jsonToken: ref.jsonToken } : {})
  }));
}

function appendStoryMarkdownBody(lines, body) {
  const text = String(body || "").trim();
  if (!text) return;
  text.split(/\r?\n/).forEach((line) => lines.push(line));
  lines.push("");
}

function appendStoryMarkdownEffects(lines, effects, title) {
  const entries = (Array.isArray(effects) ? effects : []).filter((effect) => !isRuntimeVisitTrackingEffect(effect));
  if (!entries.length) return;
  lines.push(`${title}:`);
  entries.forEach((effect) => lines.push(`- ${formatStoryMarkdownEffect(effect)}`));
  lines.push("");
}

function appendStoryMarkdownChoices(lines, node, nodeMap) {
  if (!node.choices?.length) return;
  lines.push("choices:");
  node.choices.forEach((choice) => {
    lines.push(`- ${formatMarkdownInline(choice.label || "Continue")}`);
    if (choice.id) lines.push(`  id: ${choice.id}`);
    if (choice.condition) lines.push(`  requires: ${choice.condition}`);
    if (choice.effects?.length) {
      choice.effects.forEach((effect) => lines.push(`  effect: ${formatStoryMarkdownEffect(effect)}`));
    }
    lines.push(`  goto: ${formatStoryMarkdownTarget(choice.targetId, nodeMap)}`);
  });
  lines.push("");
}

function appendStoryMarkdownNext(lines, node, nodeMap) {
  if (!node.next?.length) return;
  lines.push("next:");
  node.next.forEach((transition) => {
    const condition = transition.condition ? ` if ${transition.condition}` : "";
    lines.push(`- goto: ${formatStoryMarkdownTarget(transition.targetId, nodeMap)}${condition}`);
  });
  lines.push("");
}

function formatStoryMarkdownEffect(effect) {
  if (effect?.op === "ifElse") {
    return `if ${formatMarkdownInline(effect.condition)} then ${formatStateEffectBody(effect.thenEffect)} else ${formatStateEffectBody(effect.elseEffect)}`;
  }
  const parts = [
    effect?.trigger || "onVisit",
    effect?.op || "set",
    effect?.key || effect?.sourceKey || ""
  ].filter(Boolean);
  const value = effect?.valueSource ?? effect?.value;
  if (value !== "" && value != null) parts.push(formatMarkdownInline(String(value)));
  return parts.join(" ");
}

function formatStoryMarkdownTarget(targetId, nodeMap) {
  const target = nodeMap.get(targetId);
  return target ? (target.slug || target.title || target.id) : "END";
}

function formatMarkdownHeading(value) {
  return String(value || "Untitled").replace(/\r?\n+/g, " ").trim() || "Untitled";
}

function formatMarkdownInline(value) {
  return String(value || "").replace(/\r?\n+/g, " ").trim();
}

function makePlainHeaderValue(value) {
  return String(value || "").replace(/\r?\n/g, " ").trim();
}

function buildCharactersMarkdown() {
  const characters = getCharacters();
  const backlinkIndex = buildCharacterBacklinkIndex(characters);
  const lines = [`# Narrative Library`, ""];
  characters.forEach((character) => {
    lines.push(`## ${character.name || "Unnamed Character"}`);
    lines.push(`- Category: ${character.kind || "Character"}`);
    if (character.tags) lines.push(`- Tags: ${parseCodexTags(character.tags).join(", ")}`);
    if (character.role) lines.push(`- Role: ${character.role}`);
    if (character.voice) lines.push(`- Voice: ${character.voice}`);
    normalizeCodexExtraFields(character.extraFields)
      .filter((field) => field.key)
      .forEach((field) => lines.push(`- ${field.key}: ${formatCodexExtraFieldValue(field.value, field.type)}`));
    if (character.notes) lines.push("", character.notes);
    getCharacterBacklinkGroups(character, backlinkIndex)
      .filter((group) => group.items.length)
      .forEach((group) => {
        lines.push("", `### ${group.label}`);
        group.items.forEach((item) => {
          lines.push(`- ${item.node.title || getNodeTypeLabel(item.node.type)} (${getNodeDisplayId(item.node)}): ${formatNodeSnippet(item.node)}`);
        });
      });
    lines.push("");
  });
  return lines.join("\n");
}

function buildVariablesJson() {
  return JSON.stringify(buildScriptDocument(), null, 2);
}

function buildCharactersJsonDocument() {
  const characters = getCharacters();
  const backlinkIndex = buildCharacterBacklinkIndex(characters);
  return {
    characters: characters.map((character) => ({
      ...character,
      links: getCharacterBacklinkGroups(character, backlinkIndex)
        .filter((group) => group.items.length)
        .map((group) => ({
          label: group.label,
          nodes: group.items.map((item) => ({
            id: item.node.id,
            displayId: getNodeDisplayId(item.node),
            type: item.node.type,
            label: getNodeTypeLabel(item.node.type),
            title: item.node.title || ""
          }))
        }))
    }))
  };
}

function buildScriptDocument() {
  state.project.variables = normalizeVariablesObject(state.project.variables);
  return {
    variables: state.project.variables,
    nodeLogic: buildPlaybookNodeLogicRows(),
    choiceConditions: buildPlaybookChoiceConditionRows(),
    nodeTypes: getScriptNodeTypes(),
    actions: getPlaybookActions(),
    playRules: getRunnerRules(),
    validation: buildPlaybookValidationRows()
  };
}

function buildPlaybookNodeLogicRows() {
  return getScriptBuilderNodes().map((node) => {
    const logic = normalizeNodeStateLogic(node.stateLogic);
    return {
      rowId: `node:${node.id}`,
      nodeId: node.id,
      title: node.title || "",
      type: node.type,
      requirements: logic.requirements,
      requirementsMode: logic.requirementsMode,
      effects: logic.effects,
      routing: normalizeNodeRouting(node.routing)
    };
  });
}

function buildPlaybookChoiceConditionRows() {
  return getPlaybookGateRows().map((row) => ({
    rowId: row.id,
    kind: row.kind,
    typeLabel: row.typeLabel,
    target: row.targetLabel,
    nodeId: row.nodeId || "",
    optionId: row.choiceOptionId || "",
    legacyActionId: row.legacyActionId || "",
    condition: row.condition || "",
    conditionMode: row.conditionMode || "all",
    effects: normalizeNodeEffects(row.effects)
  }));
}

function buildPlaybookValidationRows() {
  const report = buildStateReport();
  return report.rows.map((row) => ({
    rowId: `state:${row.key}`,
    key: row.key,
    type: row.typeLabel,
    statuses: row.statuses,
    reads: row.reads.map((ref) => ref.label),
    writes: row.writes.map((ref) => ref.label),
    interpolations: row.interpolations.map((ref) => ref.label)
  }));
}

function applyScriptJson(value) {
  let parsed;
  try {
    parsed = JSON.parse(value || "{}");
  } catch (error) {
    const parseError = new Error("Playbook JSON is invalid.");
    parseError.cause = error;
    throw parseError;
  }
  if (isScriptDocument(parsed)) {
    state.project.variables = normalizeVariablesObject(parsed.variables);
    state.project.script = normalizeScriptConfig(parsed);
    applyPlaybookNodeLogicRows(parsed.nodeLogic);
    applyPlaybookChoiceConditionRows(parsed.choiceConditions);
    return;
  }
  state.project.variables = normalizeVariablesObject(parsed);
  state.project.script = normalizeScriptConfig(state.project.script);
}

function applyPlaybookNodeLogicRows(rows) {
  if (!Array.isArray(rows)) return;
  rows.forEach((row) => {
    if (!row || typeof row !== "object" || Array.isArray(row)) return;
    const node = getNode(row.nodeId || row.id);
    if (!node || isFrameNode(node)) return;
    const logic = normalizeNodeStateLogic(node.stateLogic);
    if (Object.prototype.hasOwnProperty.call(row, "requirements")) {
      logic.requirements = normalizeOptionalString(row.requirements).trim();
      logic.requirementsMode = getStoredConditionModeForExpression(logic.requirements, logic.requirementsMode);
    }
    if (Object.prototype.hasOwnProperty.call(row, "requirementsMode")) {
      logic.requirementsMode = normalizeStoredConditionGroupMode(row.requirementsMode);
      logic.requirements = setConditionExpressionGroupMode(logic.requirements, logic.requirementsMode);
    }
    if (Object.prototype.hasOwnProperty.call(row, "effects")) {
      logic.effects = normalizeNodeEffects(row.effects);
    }
    node.stateLogic = logic;
    cleanupNodeStateLogic(node);
    if (Object.prototype.hasOwnProperty.call(row, "routing")) {
      node.routing = normalizeNodeRouting(row.routing);
    }
  });
}

function applyPlaybookChoiceConditionRows(rows) {
  if (!Array.isArray(rows)) return;
  rows.forEach((row) => {
    if (!row || typeof row !== "object" || Array.isArray(row)) return;
    const condition = normalizeOptionalString(row.condition).trim();
    if (row.kind !== "choiceRequirement") return;
    const node = getNode(row.nodeId);
    if (!node || isFrameNode(node)) return;
    const optionId = normalizeOptionalString(row.optionId).trim();
    if (!optionId) return;
    const options = ensureChoiceOptionsArray(node);
    const option = optionId.startsWith("index:")
      ? options[Number(optionId.slice("index:".length))]
      : options.find((item) => item.id === optionId);
    if (!option) return;
    option.requires = condition;
    if (Object.prototype.hasOwnProperty.call(row, "conditionMode")) {
      option.requiresMode = normalizeStoredConditionGroupMode(row.conditionMode);
      option.requires = setConditionExpressionGroupMode(option.requires, option.requiresMode);
    } else {
      option.requiresMode = getStoredConditionModeForExpression(option.requires, option.requiresMode);
    }
    if (Object.prototype.hasOwnProperty.call(row, "effects")) option.effects = normalizeNodeEffects(row.effects);
    syncChoicesFromOptions(node);
  });
}

function isScriptDocument(value) {
  return value
    && typeof value === "object"
    && !Array.isArray(value)
    && (Object.prototype.hasOwnProperty.call(value, "variables")
      || Object.prototype.hasOwnProperty.call(value, "nodeLogic")
      || Object.prototype.hasOwnProperty.call(value, "choiceConditions")
      || Object.prototype.hasOwnProperty.call(value, "nodeTypes")
      || Object.prototype.hasOwnProperty.call(value, "actions")
      || Object.prototype.hasOwnProperty.call(value, "playRules"));
}

function normalizeVariablesObject(value) {
  return value && typeof value === "object" && !Array.isArray(value) ? value : {};
}

function normalizeScriptConfig(value) {
  const source = value && typeof value === "object" && !Array.isArray(value) ? value : {};
  return {
    nodeTypes: normalizeNodeTypeScripts(source.nodeTypes),
    actions: normalizePlaybookActions(source.actions),
    playRules: normalizeRunnerRules(source.playRules || source.rules)
  };
}

function normalizeRunnerRules(value) {
  const source = value && typeof value === "object" && !Array.isArray(value) ? value : {};
  const defaults = getDefaultRunnerRules();
  const normalized = {};
  Object.entries(defaults).forEach(([key, fallback]) => {
    const item = source[key];
    if (item && typeof item === "object" && !Array.isArray(item)) {
      normalized[key] = {
        enabled: item.enabled == null ? fallback.enabled : Boolean(item.enabled),
        value: normalizeRunnerRuleValue(key, item.value)
      };
    } else {
      normalized[key] = { ...fallback };
    }
  });
  if (!(normalized.debugMode?.enabled && normalized.debugMode.value) && normalized.visitTracking) {
    normalized.visitTracking.enabled = false;
  }
  return normalized;
}

function getDefaultRunnerRules() {
  return {
    startNode: { enabled: true, value: "Start" },
    endCondition: { enabled: false, value: "" },
    visitTracking: { enabled: false, value: true },
    debugMode: { enabled: false, value: false }
  };
}

function normalizeRunnerRuleValue(key, value) {
  if (key === "visitTracking" || key === "debugMode") return Boolean(value);
  return normalizeOptionalString(value).trim();
}

function normalizeNodeTypeScripts(value) {
  if (!value || typeof value !== "object" || Array.isArray(value)) return {};
  const normalized = {};
  Object.entries(value).forEach(([key, script]) => {
    if (!key || !script || typeof script !== "object" || Array.isArray(script)) return;
    normalized[String(key)] = {
      title: normalizeOptionalString(script.title),
      body: normalizeOptionalString(script.body),
      choices: normalizeScriptChoices(script.choices)
    };
  });
  return normalized;
}

function normalizeOptionalString(value) {
  return value == null ? "" : String(value);
}

function normalizeScriptChoices(value) {
  if (Array.isArray(value)) return value.map((item) => String(item)).filter(Boolean);
  return normalizeOptionalString(value);
}

function normalizePlaybookActions(value) {
  if (!Array.isArray(value)) return [];
  return value
    .map((action, index) => normalizePlaybookAction(action, index))
    .filter(Boolean);
}

function normalizePlaybookAction(action, index = 0) {
  if (!action || typeof action !== "object" || Array.isArray(action)) return null;
  const legacyAppend = Boolean(action.append);
  const normalized = {
    id: normalizePlaybookActionId(action.id, index),
    trigger: normalizePlaybookActionTrigger(action.trigger || action.when),
    target: normalizeOptionalString(action.target || action.nodeType || action.node || action.scope).trim(),
    op: normalizePlaybookActionOperation(action.op || action.action || action.type),
    category: normalizePlaybookActionCategory(action.category || action.scopeType),
    key: normalizeOptionalString(action.key || action.variable || action.name).trim(),
    value: normalizeOptionalString(action.value)
  };
  if (normalized.op === "set" && legacyAppend) normalized.op = "append";
  if (!normalized.key && normalized.op !== "clear") normalized.key = "state_key";
  return normalized;
}

function normalizePlaybookActionId(value, index = 0) {
  const id = normalizeOptionalString(value).trim();
  return id || `a${index}`;
}

function normalizePlaybookActionTrigger(value) {
  const trigger = normalizeOptionalString(value).trim();
  return PLAYBOOK_ACTION_TRIGGER_VALUES.has(trigger) ? trigger : "onVisit";
}

function normalizePlaybookActionOperation(value) {
  const operation = normalizeOptionalString(value).trim();
  return PLAYBOOK_ACTION_OPERATION_VALUES.has(operation) ? operation : "set";
}

function normalizePlaybookActionCategory(value) {
  const category = normalizeOptionalString(value).trim();
  return PLAYBOOK_STATE_CATEGORIES.includes(category) ? category : "Variable";
}

function getScriptNodeTypes() {
  if (!state.project.script) state.project.script = normalizeScriptConfig(null);
  state.project.script = normalizeScriptConfig(state.project.script);
  return state.project.script.nodeTypes;
}

function getPlaybookActions() {
  if (!state.project.script) state.project.script = normalizeScriptConfig(null);
  state.project.script = normalizeScriptConfig(state.project.script);
  return state.project.script.actions;
}

function getRunnerRules() {
  if (!state.project.script) state.project.script = normalizeScriptConfig(null);
  state.project.script = normalizeScriptConfig(state.project.script);
  return state.project.script.playRules;
}

function buildEventSheetCsv() {
  const rows = [];
  getEventRowGroups().forEach((group, groupIndex) => {
    const columns = getEventSheetColumns(group.type);
    if (groupIndex) rows.push([]);
    rows.push([group.label]);
    rows.push(["Node", ...columns.map((column) => column.label)]);
    group.rows.forEach((node) => {
      rows.push([
        `${node.title || node.id} (${getNodeDisplayId(node)})`,
        ...columns.map((column) => getNodeEventValue(node, column.key))
      ]);
    });
  });
  return rows.map((row) => row.map(formatCsvCell).join(",")).join("\n");
}

function buildEventSheetJsonDocument() {
  return {
    title: state.project.title || "",
    groups: getEventRowGroups().map((group) => {
      const columns = getEventSheetColumns(group.type);
      return {
        type: group.type,
        label: group.label,
        columns: columns.map((column) => ({
          key: column.key,
          label: column.label,
          custom: Boolean(column.custom),
          readonly: Boolean(column.readonly)
        })),
        rows: group.rows.map((node) => ({
          nodeId: node.id,
          displayId: getNodeDisplayId(node),
          type: node.type,
          title: node.title || "",
          values: Object.fromEntries(columns.map((column) => [column.key, getNodeEventValue(node, column.key)]))
        }))
      };
    })
  };
}

function buildNodeFieldsCsv() {
  const rows = [
    ["Node ID", "Type", "Title", "Field", "Value"],
    ...state.project.nodes.flatMap((node) => getNodeCustomFieldEntries(node)
      .filter((field) => field.value !== "")
      .map((field) => [getNodeDisplayId(node), getNodeTypeLabel(node.type), node.title || "", field.label, field.value]))
  ];
  return rows.map((row) => row.map(formatCsvCell).join(",")).join("\n");
}

function downloadBlob(blob, filename) {
  const url = URL.createObjectURL(blob);
  const anchor = document.createElement("a");
  anchor.href = url;
  anchor.download = filename;
  anchor.rel = "noopener";
  anchor.style.display = "none";
  (document.body || document.documentElement).appendChild(anchor);
  anchor.click();
  anchor.remove();
  // Defer revocation: revoking synchronously right after click() can cancel the download
  // before it starts in Chromium/Electron (Obsidian), producing an empty or missing file.
  window.setTimeout(() => URL.revokeObjectURL(url), 10000);
}

function downloadJsonFile(value, filename) {
  downloadBlob(new Blob([JSON.stringify(value, null, 2)], { type: "application/json;charset=utf-8" }), filename);
}

async function createZipBlob(files) {
  const entries = [];
  const localParts = [];
  const centralParts = [];
  let offset = 0;
  for (const file of files) {
    const nameBytes = encodeUtf8(file.name);
    const data = new Uint8Array(await file.blob.arrayBuffer());
    const crc = crc32(data);
    const { dosTime, dosDate } = zipDateTime(new Date());
    const localHeader = concatBytes(
      uint32(0x04034b50),
      uint16(20),
      uint16(0x0800),
      uint16(0),
      uint16(dosTime),
      uint16(dosDate),
      uint32(crc),
      uint32(data.length),
      uint32(data.length),
      uint16(nameBytes.length),
      uint16(0),
      nameBytes
    );
    localParts.push(localHeader, data);
    entries.push({ nameBytes, crc, size: data.length, dosTime, dosDate, offset });
    offset += localHeader.length + data.length;
  }
  const centralOffset = offset;
  for (const entry of entries) {
    const centralHeader = concatBytes(
      uint32(0x02014b50),
      uint16(20),
      uint16(20),
      uint16(0x0800),
      uint16(0),
      uint16(entry.dosTime),
      uint16(entry.dosDate),
      uint32(entry.crc),
      uint32(entry.size),
      uint32(entry.size),
      uint16(entry.nameBytes.length),
      uint16(0),
      uint16(0),
      uint16(0),
      uint16(0),
      uint32(0),
      uint32(entry.offset),
      entry.nameBytes
    );
    centralParts.push(centralHeader);
    offset += centralHeader.length;
  }
  const centralSize = offset - centralOffset;
  const endRecord = concatBytes(
    uint32(0x06054b50),
    uint16(0),
    uint16(0),
    uint16(entries.length),
    uint16(entries.length),
    uint32(centralSize),
    uint32(centralOffset),
    uint16(0)
  );
  return new Blob([...localParts, ...centralParts, endRecord], { type: "application/zip" });
}

function encodeUtf8(value) {
  return new TextEncoder().encode(value);
}

function uint16(value) {
  return new Uint8Array([value & 0xff, (value >>> 8) & 0xff]);
}

function uint32(value) {
  return new Uint8Array([value & 0xff, (value >>> 8) & 0xff, (value >>> 16) & 0xff, (value >>> 24) & 0xff]);
}

function concatBytes(...parts) {
  const length = parts.reduce((sum, part) => sum + part.length, 0);
  const bytes = new Uint8Array(length);
  let offset = 0;
  parts.forEach((part) => {
    bytes.set(part, offset);
    offset += part.length;
  });
  return bytes;
}

function zipDateTime(date) {
  const year = Math.max(1980, date.getFullYear());
  return {
    dosTime: (date.getHours() << 11) | (date.getMinutes() << 5) | Math.floor(date.getSeconds() / 2),
    dosDate: ((year - 1980) << 9) | ((date.getMonth() + 1) << 5) | date.getDate()
  };
}

function crc32(bytes) {
  let crc = 0xffffffff;
  for (let index = 0; index < bytes.length; index += 1) {
    crc = (crc >>> 8) ^ crc32Table()[(crc ^ bytes[index]) & 0xff];
  }
  return (crc ^ 0xffffffff) >>> 0;
}

function crc32Table() {
  if (crc32Table.cache) return crc32Table.cache;
  const table = new Uint32Array(256);
  for (let index = 0; index < 256; index += 1) {
    let value = index;
    for (let bit = 0; bit < 8; bit += 1) {
      value = value & 1 ? 0xedb88320 ^ (value >>> 1) : value >>> 1;
    }
    table[index] = value >>> 0;
  }
  crc32Table.cache = table;
  return table;
}

function importJsonFile() {
  const file = dom.fileInput.files?.[0];
  if (!file) return;
  const importKind = state.pendingImportKind || "json";
  const reader = new FileReader();
  reader.onload = () => {
    try {
      if (importKind === "story-md") {
        importStoryMarkdownText(String(reader.result || ""));
      } else if (importKind === "story-layout") {
        importStoryLayoutText(String(reader.result || ""));
      } else if (importKind === "state-schema") {
        importStateSchemaText(String(reader.result || ""));
      } else {
        const payload = JSON.parse(String(reader.result));
        const restoredView = applySavedState(payload);
        if (!state.selectedNodeId) state.selectedNodeId = state.project.nodes[0]?.id || null;
        if (!restoredView) centerViewAtScale(DEFAULT_CANVAS_ZOOM, false);
        resetHistory();
        setProjectDirty(true);
        renderAll();
        setStatus("JSON imported.");
      }
    } catch (error) {
      console.error(error);
      setStatus(getImportFailureStatus(importKind));
    } finally {
      dom.fileInput.value = "";
      dom.fileInput.accept = "application/json,.json,.ncanvas,.narrativecanvas";
      state.pendingImportKind = "";
    }
  };
  reader.readAsText(file);
}

function getImportFailureStatus(importKind) {
  if (importKind === "story-md") return "Import failed: invalid Story Markdown.";
  if (importKind === "story-layout") return "Import failed: invalid Story Layout.";
  if (importKind === "state-schema") return "Import failed: invalid State Schema.";
  return "Import failed: invalid JSON.";
}

function buildProjectFromStoryMarkdown(source) {
  const parsed = parseStoryMarkdownDocument(source);
  if (!parsed.nodes.length) throw new Error("Story Markdown has no nodes.");
  const usedIds = new Set();
  const nodes = parsed.nodes.map((node, index) => buildStoryMarkdownNode(node, index, usedIds));
  const nodeByRef = new Map();
  nodes.forEach((node, index) => {
    const sourceNode = parsed.nodes[index];
    [node.id, node.title, sourceNode.slug].filter(Boolean).forEach((ref) => nodeByRef.set(normalizeStoryMarkdownRef(ref), node.id));
  });
  const links = [];
  const ensureTarget = (ref) => {
    const key = normalizeStoryMarkdownRef(ref);
    if (!key || key === "end") return "";
    const existing = nodeByRef.get(key);
    if (existing) return existing;
    const id = makeUniqueStoryMarkdownId(ref || `n${nodes.length}`, usedIds);
    const title = normalizeOptionalString(ref).trim() || id;
    const node = normalizeNode({
      id,
      type: "Content",
      title,
      body: "",
      x: 80 + (nodes.length % 3) * 280,
      y: 80 + Math.floor(nodes.length / 3) * 220
    });
    nodes.push(node);
    [node.id, node.title].forEach((value) => nodeByRef.set(normalizeStoryMarkdownRef(value), node.id));
    return id;
  };
  parsed.nodes.forEach((sourceNode, index) => {
    const node = nodes[index];
    sourceNode.choices.forEach((choice, choiceIndex) => {
      const targetId = ensureTarget(choice.goto);
      if (!targetId) return;
      links.push({
        id: `l${links.length}`,
        from: node.id,
        to: targetId,
        label: choice.label,
        choiceIndex,
        choiceOptionId: node.choiceOptions?.[choiceIndex]?.id || ""
      });
    });
    sourceNode.next.forEach((next) => {
      const targetId = ensureTarget(next.goto);
      if (!targetId) return;
      links.push({
        id: `l${links.length}`,
        from: node.id,
        to: targetId,
        label: next.condition ? `if ${next.condition}` : "Continue",
        requirements: next.condition || ""
      });
    });
    sourceNode.branches.forEach((branch, branchIndex) => {
      const targetId = ensureTarget(branch.goto);
      if (!targetId) return;
      links.push({
        id: `l${links.length}`,
        from: node.id,
        to: targetId,
        label: branch.kind === "else" ? "false" : "true",
        choiceIndex: branch.kind === "else" ? 1 : branchIndex,
        requirements: branch.condition || ""
      });
    });
  });
  return {
    title: parsed.title || "Imported Story",
    workflowMode: WORKFLOW_MODE_TEXT_SOURCE,
    richTextFormat: "markdown",
    notes: "Imported from Story Markdown.",
    variables: {},
    script: {
      playRules: {
        startNode: { enabled: true, value: nodes[0]?.title || nodes[0]?.id || "" },
        endCondition: { enabled: false, value: "" },
        visitTracking: { enabled: false, value: true },
        debugMode: { enabled: false, value: false }
      }
    },
    nodeTypes: defaultNodeTypeList(),
    customNodeTypes: [],
    characters: [],
    nodes,
    links
  };
}

function parseStoryMarkdownDocument(source, options = {}) {
  const documentSource = Boolean(options.documentSource);
  const lines = String(source || "").replace(/\r\n/g, "\n").split("\n");
  const titleLine = lines.find((line) => /^#\s+/.test(line) && !/^##\s+/.test(line));
  const title = titleLine ? titleLine.replace(/^#\s+/, "").trim() : "Imported Story";
  const blocks = [];
  let current = null;
  lines.forEach((line, index) => {
    const heading = line.match(/^##\s+(.+)$/);
    const nextLineIsStableId = /^<!--\s*id:\s*[^>]+-->$/.test((lines[index + 1] || "").trim());
    if (heading && (!documentSource || nextLineIsStableId)) {
      current = { title: heading[1].trim(), lines: [] };
      blocks.push(current);
      return;
    }
    if (current) current.lines.push(line);
  });
  return {
    title,
    notes: parseStoryMarkdownNotes(lines),
    variables: parseStoryMarkdownVariables(lines),
    nodes: blocks.map(parseStoryMarkdownNodeBlock).filter((node) => node.title)
  };
}

function parseStoryMarkdownNotes(lines) {
  const notes = [];
  let inside = false;
  (Array.isArray(lines) ? lines : []).forEach((line) => {
    if (line.trim() === "> Source notes") {
      inside = true;
      return;
    }
    if (!inside) return;
    const quote = line.match(/^>\s?(.*)$/);
    if (!quote) {
      inside = false;
      return;
    }
    notes.push(quote[1]);
  });
  return notes.join("\n").trim();
}

function parseStoryMarkdownVariables(lines) {
  const variables = {};
  let inside = false;
  (Array.isArray(lines) ? lines : []).forEach((line) => {
    if (/^###\s+Variables\s*$/i.test(line.trim())) {
      inside = true;
      return;
    }
    if (inside && /^#{2,3}\s+/.test(line.trim())) {
      inside = false;
      return;
    }
    if (!inside) return;
    const match = line.match(/^\s*-\s+`?([^`=]+?)`?\s*=\s*(.+)\s*$/);
    if (match) variables[match[1].trim()] = parseDocumentLiteral(match[2]);
  });
  return variables;
}

function formatDocumentLiteral(value) {
  if (value === undefined) return "null";
  try {
    return JSON.stringify(value);
  } catch (error) {
    return JSON.stringify(String(value));
  }
}

function parseDocumentLiteral(value) {
  const source = String(value ?? "").trim();
  if (!source) return "";
  try {
    return JSON.parse(source);
  } catch (error) {
    if (source === "true") return true;
    if (source === "false") return false;
    if (source === "null") return null;
    if (/^-?\d+(?:\.\d+)?$/.test(source)) return Number(source);
    return source.replace(/^(?:"|')|(?:"|')$/g, "");
  }
}

function parseProjectDocumentSource(source, format) {
  const text = String(source || "").replace(/\r\n/g, "\n");
  if (!text.trim()) throw new Error(t("Document cannot be empty."));
  const normalizedFormat = normalizeDocumentFormat(format);
  const parsed = normalizedFormat === "yarn"
    ? parseYarnDocumentSource(text)
    : normalizedFormat === "ink"
      ? parseInkDocumentSource(text)
      : normalizedFormat === "twee"
        ? parseTweeDocumentSource(text)
        : parseStoryMarkdownDocument(text, { documentSource: true });
  if (!Array.isArray(parsed.nodes) || !parsed.nodes.length) {
    throw new Error(t("No editable nodes were found."));
  }
  return { ...parsed, format: normalizedFormat };
}

function parseTweeDocumentSource(source) {
  const passages = [];
  let current = null;
  const pushCurrent = () => {
    if (current) passages.push(current);
    current = null;
  };
  String(source || "").split("\n").forEach((line) => {
    const header = line.match(/^::\s+(.+?)(?:\s+\[([^\]]*)\])?\s*$/);
    if (header) {
      pushCurrent();
      current = {
        slug: unescapeTweePassageName(header[1].trim()),
        tags: (header[2] || "").split(/\s+/).filter(Boolean),
        lines: []
      };
      return;
    }
    if (current) current.lines.push(line);
  });
  pushCurrent();

  const bySlug = new Map(passages.map((passage) => [passage.slug, passage]));
  const title = (bySlug.get("StoryTitle")?.lines || []).join("\n").trim();
  const notesMarker = (bySlug.get("NarrativeCanvasProjectNotes")?.lines || []).join("\n").match(/<!--\s*narrativeCanvasNotes:\s*(.*?)\s*-->/);
  const notes = decodeDocumentMetadata(notesMarker?.[1] || "");
  const variables = {};
  (bySlug.get("StoryInit")?.lines || []).forEach((line) => {
    const match = line.trim().match(/^<<set\s+\$([A-Za-z_]\w*)\s*=\s*([\s\S]+?)>>$/);
    if (match) variables[match[1]] = parseDocumentLiteral(match[2]);
  });
  const reserved = new Set(["StoryData", "StoryTitle", "StoryInit", "NarrativeCanvasProjectNotes", "NarrativeCanvasExportReport"]);
  const nodes = passages
    .filter((passage) => !reserved.has(passage.slug) && !passage.tags.includes("annotation"))
    .map((passage) => parseTweeDocumentNode(passage));
  return { title, notes, variables, nodes };
}

function decodeDocumentMetadata(value) {
  try {
    return decodeURIComponent(String(value || ""));
  } catch (error) {
    return String(value || "");
  }
}

function parseTweeDocumentNode(passage) {
  const lines = passage.lines || [];
  const type = passage.tags[0] || "";
  const node = {
    id: "",
    type,
    slug: passage.slug,
    body: [],
    effects: [],
    choices: [],
    next: [],
    hasBodyMarkers: false,
    replaceEffects: true,
    replaceChoices: true
  };
  const hasBodyMarkers = lines.some((line) => line.trim() === "<!-- narrativeCanvasBody:start -->");
  node.hasBodyMarkers = hasBodyMarkers && lines.some((line) => line.trim() === "<!-- narrativeCanvasBody:end -->");
  let insideBody = false;
  const conditionStack = [];
  const currentCondition = () => conditionStack[conditionStack.length - 1] || "";
  for (let index = 0; index < lines.length; index += 1) {
    const line = lines[index];
    const trimmed = line.trim();
    const idMarker = trimmed.match(/^<!--\s*narrativeCanvasId:\s*(.+?)\s*-->$/);
    if (idMarker) {
      node.id = idMarker[1].trim();
      continue;
    }
    const titleMarker = trimmed.match(/^<!--\s*narrativeCanvasTitle:\s*(.*?)\s*-->$/);
    if (titleMarker) {
      try {
        node.title = decodeURIComponent(titleMarker[1]);
      } catch (error) {
        node.title = titleMarker[1];
      }
      continue;
    }
    if (trimmed === "<!-- narrativeCanvasBody:start -->") {
      insideBody = true;
      continue;
    }
    if (trimmed === "<!-- narrativeCanvasBody:end -->") {
      insideBody = false;
      continue;
    }
    if (hasBodyMarkers && insideBody) {
      node.body.push(line.replace(/\s+$/, ""));
      continue;
    }
    if (!trimmed && !node.body.length) continue;
    if (/^(?:<!--.*-->|\/\*.*\*\/)\s*$/.test(trimmed)) continue;
    const ifMatch = trimmed.match(/^<<if\s+([\s\S]+?)>>$/);
    if (ifMatch) {
      conditionStack.push(ifMatch[1].trim());
      continue;
    }
    if (trimmed === "<<else>>") {
      if (conditionStack.length) conditionStack[conditionStack.length - 1] = "";
      continue;
    }
    if (trimmed === "<</if>>") {
      conditionStack.pop();
      continue;
    }
    const link = parseTweeDocumentLink(trimmed);
    if (link) {
      const commands = [];
      if (link.macro) {
        for (index += 1; index < lines.length && lines[index].trim() !== "<</link>>"; index += 1) {
          commands.push(lines[index]);
        }
      }
      const effects = commands.map((command) => parseTweeDocumentEffect(command.trim())).filter(Boolean);
      if (type.toLowerCase() === "choice") {
        node.choices.push({ label: link.label, requires: currentCondition(), effects, goto: link.target });
      } else {
        node.next.push({ goto: link.target, condition: currentCondition(), label: link.label });
      }
      continue;
    }
    const goto = parseTweeDocumentGoto(trimmed);
    if (goto) {
      node.next.push({ goto: goto.target, condition: currentCondition() });
      continue;
    }
    const effect = parseTweeDocumentEffect(trimmed);
    if (effect) {
      node.effects.push(effect);
      continue;
    }
    if (/^<<[^>]+>>$/.test(trimmed) && !/^<<print\s+/.test(trimmed)) continue;
    node.body.push(line.replace(/\s+$/, ""));
  }
  node.body = node.body.join("\n").trim();
  return node;
}

function parseTweeDocumentLink(source) {
  const text = String(source || "").trim();
  const macro = text.match(/^<<link\s+((?:"(?:\\.|[^"])*")|(?:'(?:\\.|[^'])*'))\s+((?:"(?:\\.|[^"])*")|(?:'(?:\\.|[^'])*'))\s*>>$/);
  if (macro) return { label: parseTweeDocumentString(macro[1]), target: parseTweeDocumentString(macro[2]), macro: true };
  const wiki = text.match(/^\[\[([\s\S]*?)\]\]$/);
  if (!wiki) return null;
  const content = wiki[1];
  const forward = content.match(/^([\s\S]*?)(?:->|\|)([\s\S]+)$/);
  if (forward) return { label: parseTweeWikiLinkText(forward[1]), target: parseTweeWikiLinkText(forward[2]), macro: false };
  const backward = content.match(/^([\s\S]+)<-([\s\S]*?)$/);
  if (backward) return { label: parseTweeWikiLinkText(backward[2]), target: parseTweeWikiLinkText(backward[1]), macro: false };
  const target = parseTweeWikiLinkText(content);
  return { label: target, target, macro: false };
}

function parseTweeWikiLinkText(value) {
  return String(value || "").trim().replace(/&#93;/gi, "]");
}

function parseTweeDocumentGoto(source) {
  const match = String(source || "").match(/^<<goto\s+((?:"(?:\\.|[^"])*")|(?:'(?:\\.|[^'])*'))\s*>>$/);
  return match ? { target: parseTweeDocumentString(match[1]) } : null;
}

function parseTweeDocumentString(source) {
  const text = String(source || "").trim();
  if (text.startsWith('"')) {
    try {
      return JSON.parse(text);
    } catch (error) {
      return text.slice(1, -1);
    }
  }
  return text.slice(1, -1).replace(/\\(["'\\])/g, "$1");
}

function parseTweeDocumentEffect(source) {
  const match = String(source || "").match(/^<<set\s+\$([A-Za-z_]\w*)\s*(=|\+=|-=)\s*([\s\S]+?)>>$/);
  if (!match) return null;
  const [key, operator, value] = [match[1], match[2], match[3].trim()];
  if (operator === "=" && value === `!$${key}`) return { trigger: "onVisit", op: "toggle", key, value: "" };
  return {
    trigger: "onVisit",
    op: operator === "+=" ? "add" : operator === "-=" ? "subtract" : "set",
    key,
    value
  };
}

function unescapeTweePassageName(value) {
  return String(value || "").replace(/\\([\\[\]{}])/g, "$1");
}

function parseYarnDocumentSource(source) {
  const title = source.match(/^\/\/\s*Source:\s*(.+)$/m)?.[1]?.trim() || "";
  const notes = decodeDocumentMetadata(source.match(/^\/\/\s*narrativeCanvasNotes:\s*(.*)$/m)?.[1]?.trim() || "");
  const variables = {};
  for (const match of source.matchAll(/^\/\/\s*narrativeCanvasVariable:\s*([A-Za-z_]\w*)\s*=\s*(.+)$/gm)) {
    variables[match[1]] = parseDocumentLiteral(match[2]);
  }
  for (const match of source.matchAll(/<<declare\s+\$([A-Za-z_]\w*)\s*=\s*([\s\S]*?)>>/g)) {
    variables[match[1]] = parseDocumentLiteral(match[2]);
  }
  const nodes = [];
  const blockPattern = /^title:\s*(.+)\n([\s\S]*?)^===\s*$/gm;
  for (const match of source.matchAll(blockPattern)) {
    const headerAndBody = match[2];
    const separator = headerAndBody.indexOf("---\n");
    if (separator < 0) continue;
    const header = headerAndBody.slice(0, separator);
    const body = headerAndBody.slice(separator + 4);
    const id = header.match(/^narrativeCanvasId:\s*(.+)$/m)?.[1]?.trim() || "";
    const type = header.match(/^nodeType:\s*(.+)$/m)?.[1]?.trim() || "";
    const titleSource = header.match(/^nodeTitle:\s*(.+)$/m)?.[1]?.trim() || "";
    const title = titleSource ? String(parseDocumentLiteral(titleSource)) : "";
    nodes.push(parsePortableScriptNode(body, "yarn", { id, type, title, slug: match[1].trim() }));
  }
  return { title, notes, variables, nodes };
}

function parseInkDocumentSource(source) {
  const title = source.match(/^\/\/\s*Source:\s*(.+)$/m)?.[1]?.trim() || "";
  const notes = decodeDocumentMetadata(source.match(/^\/\/\s*narrativeCanvasNotes:\s*(.*)$/m)?.[1]?.trim() || "");
  const variables = {};
  const runtimeDocument = buildRuntimeExportDocument();
  const inkListMap = buildInkListMap(runtimeDocument);
  const listValues = new Map();
  for (const match of source.matchAll(/^\/\/\s*narrativeCanvasVariable:\s*([A-Za-z_]\w*)\s*=\s*(.+)$/gm)) {
    variables[match[1]] = parseDocumentLiteral(match[2]);
  }
  for (const match of source.matchAll(/^\/\/\s*narrativeCanvasListValues:\s*([A-Za-z_]\w*)\s*=\s*(.+)$/gm)) {
    const map = parseDocumentLiteral(match[2]);
    if (map && typeof map === "object" && !Array.isArray(map)) {
      listValues.set(match[1], map);
      variables[match[1]] = [];
    }
  }
  for (const match of source.matchAll(/^VAR\s+([A-Za-z_]\w*)\s*=\s*(.+)$/gm)) {
    const key = match[1];
    const expression = match[2].trim();
    const list = inkListMap[key];
    if (list && /^\([^)]*\)$/.test(expression)) {
      const identifiers = expression.slice(1, -1).split(",").map((item) => item.trim()).filter(Boolean);
      const metadataValues = listValues.get(key) || {};
      const originalValues = Array.isArray(runtimeDocument.variables?.[key]) ? runtimeDocument.variables[key] : [];
      const valueByIdentifier = new Map(list.items.map((item) => {
        const original = originalValues.find((value) => String(value) === item.value);
        return [item.identifier, original === undefined ? item.value : original];
      }));
      variables[key] = identifiers.map((identifier) => (
        Object.prototype.hasOwnProperty.call(metadataValues, identifier)
          ? metadataValues[identifier]
          : valueByIdentifier.has(identifier) ? valueByIdentifier.get(identifier) : identifier
      ));
    } else {
      variables[key] = parseDocumentLiteral(expression);
    }
  }
  const lines = source.split("\n");
  const nodes = [];
  let pendingId = "";
  let pendingType = "";
  let pendingTitle = "";
  let current = null;
  const pushCurrent = () => {
    if (!current) return;
    nodes.push(parsePortableScriptNode(current.lines.join("\n"), "ink", current));
    current = null;
  };
  lines.forEach((line) => {
    const idMatch = line.match(/^\/\/\s*narrativeCanvasId:\s*(.+)$/);
    if (idMatch) {
      pushCurrent();
      pendingId = idMatch[1].trim();
      return;
    }
    const typeMatch = line.match(/^\/\/\s*nodeType:\s*(.+)$/);
    if (typeMatch && !current) {
      pendingType = typeMatch[1].trim();
      return;
    }
    const titleMatch = line.match(/^\/\/\s*nodeTitle:\s*(.+)$/);
    if (titleMatch && !current) {
      pendingTitle = String(parseDocumentLiteral(titleMatch[1]));
      return;
    }
    const knot = line.match(/^===\s+(.+?)\s+===\s*$/);
    if (knot) {
      pushCurrent();
      current = { id: pendingId, type: pendingType, title: pendingTitle, slug: knot[1].trim(), lines: [] };
      pendingId = "";
      pendingType = "";
      pendingTitle = "";
      return;
    }
    if (current) current.lines.push(line);
  });
  pushCurrent();
  return { title, notes, variables, nodes };
}

function parsePortableScriptNode(source, format, meta) {
  const lines = String(source || "").split("\n");
  const body = [];
  const effects = [];
  const choices = [];
  const next = [];
  let currentChoice = null;
  const bodyStartMarker = format === "yarn" ? "// narrativeCanvasBody:start" : "// narrativeCanvasBody:start";
  const bodyEndMarker = format === "yarn" ? "// narrativeCanvasBody:end" : "// narrativeCanvasBody:end";
  const hasBodyMarkers = lines.some((line) => line.trim() === bodyStartMarker);
  let insideBody = false;
  lines.forEach((line) => {
    const trimmed = line.trim();
    if (trimmed === bodyStartMarker) {
      insideBody = true;
      return;
    }
    if (trimmed === bodyEndMarker) {
      insideBody = false;
      return;
    }
    if (hasBodyMarkers && insideBody) {
      body.push(line.replace(/\s+$/, ""));
      return;
    }
    if (format === "yarn") {
      const conditionalChoice = trimmed.match(/^->\s+(.+?)\s+<<if\s+(.+)>>$/);
      const choice = conditionalChoice || trimmed.match(/^->\s+(.+)$/);
      if (choice) {
        currentChoice = { label: choice[1].trim(), requires: (conditionalChoice?.[2] || "").trim(), effects: [], goto: "" };
        choices.push(currentChoice);
        return;
      }
      const jump = trimmed.match(/^<<jump\s+(.+)>>$/);
      if (jump) {
        if (currentChoice) currentChoice.goto = jump[1].trim();
        else next.push({ goto: jump[1].trim(), condition: "" });
        return;
      }
      const effect = parsePortableEffect(trimmed, "yarn");
      if (effect) {
        (currentChoice && /^\s{2,}/.test(line) ? currentChoice.effects : effects).push(effect);
        return;
      }
      if (/^<<.*>>$/.test(trimmed) || /^\/\//.test(trimmed)) return;
    } else {
      const choice = trimmed.match(/^\+\s+(?:\{(.+?)\}\s*)?\[(.*)\]\s*$/);
      if (choice) {
        currentChoice = { label: choice[2].trim(), requires: (choice[1] || "").trim(), effects: [], goto: "" };
        choices.push(currentChoice);
        return;
      }
      const divert = trimmed.match(/^->\s+(.+)$/);
      if (divert) {
        if (currentChoice) currentChoice.goto = divert[1].trim();
        else if (divert[1].trim() !== "END") next.push({ goto: divert[1].trim(), condition: "" });
        return;
      }
      const effect = parsePortableEffect(trimmed, "ink");
      if (effect) {
        (currentChoice && /^\s{2,}/.test(line) ? currentChoice.effects : effects).push(effect);
        return;
      }
      if (/^(?:\/\/|\{|\}|-\s*else:)/.test(trimmed)) return;
    }
    if (!trimmed && !body.length) return;
    body.push(line.replace(/\s+$/, ""));
  });
  return {
    id: meta.id || "",
    type: meta.type || "",
    title: meta.title || "",
    slug: meta.slug || "",
    body: body.join("\n").trim(),
    effects,
    choices,
    next,
    hasBodyMarkers: hasBodyMarkers && lines.some((line) => line.trim() === bodyEndMarker),
    replaceEffects: true,
    replaceChoices: true
  };
}

function parsePortableEffect(source, format) {
  if (format === "ink") {
    const match = source.match(/^~\s+([A-Za-z_]\w*)\s*=\s*(.+)$/);
    if (!match) return null;
    const [key, expression] = [match[1], match[2].trim()];
    if (expression === `not ${key}`) return { trigger: "onVisit", op: "toggle", key, value: "" };
    const delta = expression.match(new RegExp(`^${key.replace(/[.*+?^${}()|[\]\\]/g, "\\$&")}\\s*([+-])\\s*(.+)$`));
    if (delta) return { trigger: "onVisit", op: delta[1] === "+" ? "add" : "subtract", key, value: delta[2] };
    return { trigger: "onVisit", op: "set", key, value: expression };
  }
  const match = source.match(/^<<set\s+\$([A-Za-z_]\w*)\s+to\s+(.+)>>$/);
  if (!match) return null;
  const [key, expression] = [match[1], match[2].trim()];
  if (expression === `not $${key}`) return { trigger: "onVisit", op: "toggle", key, value: "" };
  const delta = expression.match(new RegExp(`^\\$${key.replace(/[.*+?^${}()|[\]\\]/g, "\\$&")}\\s*([+-])\\s*(.+)$`));
  if (delta) return { trigger: "onVisit", op: delta[1] === "+" ? "add" : "subtract", key, value: delta[2] };
  return { trigger: "onVisit", op: "set", key, value: expression };
}

function parseStoryMarkdownNodeBlock(block) {
  const node = {
    title: block.title,
    id: "",
    type: "",
    slug: "",
    requires: "",
    body: [],
    effects: [],
    choices: [],
    next: [],
    branches: []
  };
  let section = "body";
  let currentChoice = null;
  const hasBodyMarkers = block.lines.some((line) => line.trim() === "<!-- narrativeCanvasBody:start -->");
  let insideBody = false;
  block.lines.forEach((rawLine) => {
    const line = rawLine.replace(/\s+$/, "");
    const trimmed = line.trim();
    if (trimmed === "<!-- narrativeCanvasBody:start -->") {
      insideBody = true;
      section = "body";
      return;
    }
    if (trimmed === "<!-- narrativeCanvasBody:end -->") {
      insideBody = false;
      return;
    }
    if (hasBodyMarkers && insideBody) {
      node.body.push(line);
      return;
    }
    if (!trimmed) {
      if (section === "body" && node.body.length) node.body.push("");
      return;
    }
    const idComment = trimmed.match(/^<!--\s*id:\s*([^>]+?)\s*-->$/);
    if (idComment) {
      node.id = idComment[1].trim();
      return;
    }
    if (/^(choices|effects|branches|next):$/i.test(trimmed)) {
      section = trimmed.slice(0, -1).toLowerCase();
      currentChoice = null;
      return;
    }
    if (section === "choices") {
      const choiceStart = line.match(/^-\s+(.+)$/);
      if (choiceStart) {
        currentChoice = { label: choiceStart[1].trim(), id: "", requires: "", effects: [], goto: "" };
        node.choices.push(currentChoice);
        return;
      }
      if (currentChoice) {
        applyStoryMarkdownChoiceLine(currentChoice, trimmed);
        return;
      }
    }
    if (section === "effects") {
      const effect = trimmed.match(/^-\s+(.+)$/);
      if (effect) node.effects.push(parseStoryMarkdownEffect(effect[1], "onVisit"));
      return;
    }
    if (section === "next") {
      const next = parseStoryMarkdownNextLine(trimmed);
      if (next) node.next.push(next);
      return;
    }
    if (section === "branches") {
      const branch = parseStoryMarkdownBranchLine(trimmed);
      if (branch) node.branches.push(branch);
      return;
    }
    const meta = trimmed.match(/^(type|slug|requires):\s*(.*)$/i);
    if (meta) {
      const key = meta[1].toLowerCase();
      if (key === "type") node.type = meta[2].trim();
      if (key === "slug") node.slug = meta[2].trim();
      if (key === "requires") node.requires = meta[2].trim();
      return;
    }
    if (/^cast:\s*/i.test(trimmed)) return;
    const inlineChoice = trimmed.match(/^->\s*(.+)$/);
    if (inlineChoice) {
      currentChoice = { label: inlineChoice[1].trim(), id: "", requires: "", effects: [], goto: "" };
      node.choices.push(currentChoice);
      section = "choices";
      return;
    }
    const gotoLine = trimmed.match(/^goto:\s*(.+)$/i);
    if (gotoLine) {
      node.next.push({ goto: gotoLine[1].trim(), condition: "" });
      return;
    }
    node.body.push(line);
  });
  node.body = node.body.join("\n").trim();
  node.hasBodyMarkers = hasBodyMarkers && block.lines.some((line) => line.trim() === "<!-- narrativeCanvasBody:end -->");
  return node;
}

function applyStoryMarkdownChoiceLine(choice, line) {
  const match = line.match(/^(id|requires|goto|effect|set|add|subtract|toggle):\s*(.*)$/i);
  if (!match) return;
  const key = match[1].toLowerCase();
  const value = match[2].trim();
  if (key === "id") choice.id = value;
  if (key === "requires") choice.requires = value;
  if (key === "goto") choice.goto = value;
  if (key === "effect") choice.effects.push(parseStoryMarkdownEffect(value, "onChoose"));
  if (["set", "add", "subtract", "toggle"].includes(key)) choice.effects.push(parseStoryMarkdownEffect(`${key} ${value}`, "onChoose"));
}

function parseStoryMarkdownNextLine(line) {
  const match = line.match(/^-\s*goto:\s*(.+?)(?:\s+if\s+(.+))?$/i);
  return match ? { goto: match[1].trim(), condition: (match[2] || "").trim() } : null;
}

function parseStoryMarkdownBranchLine(line) {
  const match = line.match(/^-\s*(?:(if)\s+(.+?)|(else)):\s*(.+)$/i);
  if (!match) return null;
  return {
    kind: match[3] ? "else" : "if",
    condition: (match[2] || "").trim(),
    goto: (match[4] || "").trim()
  };
}

function parseStoryMarkdownEffect(source, fallbackTrigger) {
  const parts = String(source || "").trim().split(/\s+/).filter(Boolean);
  const triggerValues = new Set(["onVisit", "onChoose", "gate", "manual"]);
  let trigger = fallbackTrigger;
  if (triggerValues.has(parts[0])) trigger = parts.shift();
  const op = parts.shift() || "set";
  const key = parts.shift() || "";
  const value = parts.join(" ");
  return { trigger, op, key, value };
}

function mergeProjectDocumentSource(parsed, baseline = { title: "", variables: {}, nodes: [] }) {
  const runtimeDocument = buildRuntimeExportDocument();
  const nodeById = new Map(state.project.nodes.map((node) => [node.id, node]));
  const nodeByRef = new Map();
  state.project.nodes.forEach((node) => {
    [node.id, node.title].filter(Boolean).forEach((ref) => nodeByRef.set(normalizeStoryMarkdownRef(ref), node));
  });
  (runtimeDocument.nodes || []).forEach((runtimeNode) => {
    const node = nodeById.get(runtimeNode.id);
    if (node) [runtimeNode.id, runtimeNode.slug, runtimeNode.title].filter(Boolean).forEach((ref) => nodeByRef.set(normalizeStoryMarkdownRef(ref), node));
  });
  const variableNameMap = runtimeDocument.report?.variableNameMap || {};
  const sourceVariableByExportName = new Map(Object.entries(variableNameMap).map(([sourceKey, exportKey]) => [exportKey, sourceKey]));
  const baselineNodeById = new Map();
  const baselineNodeByRef = new Map();
  (baseline.nodes || []).forEach((node) => {
    if (node.id) baselineNodeById.set(node.id, node);
    [node.id, node.slug, node.title].filter(Boolean).forEach((ref) => baselineNodeByRef.set(normalizeStoryMarkdownRef(ref), node));
  });
  let structureChanged = false;

  if (parsed.title !== baseline.title) state.project.title = parsed.title;
  if ((parsed.notes || "") !== (baseline.notes || "")) state.project.notes = parsed.notes || "";
  const parsedVariables = parsed.variables || {};
  const baselineVariables = baseline.variables || {};
  new Set([...Object.keys(parsedVariables), ...Object.keys(baselineVariables)]).forEach((exportKey) => {
    if (documentValuesEqual(parsedVariables[exportKey], baselineVariables[exportKey])
      && Object.prototype.hasOwnProperty.call(parsedVariables, exportKey) === Object.prototype.hasOwnProperty.call(baselineVariables, exportKey)) return;
    const sourceKey = sourceVariableByExportName.get(exportKey) || exportKey;
    if (Object.prototype.hasOwnProperty.call(parsedVariables, exportKey)) {
      state.project.variables[sourceKey] = normalizeDocumentVariableValue(parsedVariables[exportKey]);
    } else {
      delete state.project.variables[sourceKey];
    }
  });

  parsed.nodes.forEach((sourceNode) => {
    const node = nodeById.get(sourceNode.id)
      || nodeByRef.get(normalizeStoryMarkdownRef(sourceNode.slug))
      || nodeByRef.get(normalizeStoryMarkdownRef(sourceNode.title));
    if (!node || isFrameNode(node)) return;
    const baselineNode = baselineNodeById.get(sourceNode.id)
      || baselineNodeByRef.get(normalizeStoryMarkdownRef(sourceNode.slug))
      || baselineNodeByRef.get(normalizeStoryMarkdownRef(sourceNode.title));
    if (!baselineNode) return;

    if (!documentValuesEqual(sourceNode.title, baselineNode.title)) node.title = normalizeOptionalString(sourceNode.title);
    if (!documentValuesEqual(sourceNode.type, baselineNode.type)) {
      const nextType = resolveDocumentNodeType(sourceNode.type);
      if (nextType && nextType !== node.type) {
        node.type = nextType;
        applyNodeTypeDefaults(node);
        structureChanged = true;
      }
    }

    if (!documentValuesEqual(sourceNode.body, baselineNode.body)) {
      node.body = restoreDocumentBodyVariables(sourceNode.body || "", parsed.format, sourceVariableByExportName);
      if (isDialogNode(node)) syncDialogTurnsFromDocumentBody(node);
    }

    const shouldReplaceEffects = !documentValuesEqual(sourceNode.effects || [], baselineNode.effects || []);
    const shouldReplaceRequirements = !documentValuesEqual(sourceNode.requires || "", baselineNode.requires || "");
    if (shouldReplaceEffects || shouldReplaceRequirements) {
      const logic = normalizeNodeStateLogic(node.stateLogic);
      if (shouldReplaceRequirements) {
        logic.requirements = restoreDocumentCondition(sourceNode.requires || "", parsed.format, sourceVariableByExportName);
        logic.requirementsMode = getStoredConditionModeForExpression(logic.requirements, "all");
      }
      if (shouldReplaceEffects) {
        logic.effects = mergeDocumentEffects(logic.effects, sourceNode.effects || [], parsed.format, sourceVariableByExportName, "onVisit");
      }
      if (logic.requirements || logic.effects.length) node.stateLogic = logic;
      else delete node.stateLogic;
    }

    const shouldReplaceChoices = isChoiceNode(node) && !documentValuesEqual(sourceNode.choices || [], baselineNode.choices || []);
    if (shouldReplaceChoices) {
      mergeDocumentChoices(node, sourceNode.choices || [], parsed.format, sourceVariableByExportName, nodeByRef);
      structureChanged = true;
    } else if (!documentValuesEqual(sourceNode.next || [], baselineNode.next || [])
      || !documentValuesEqual(sourceNode.branches || [], baselineNode.branches || [])) {
      structureChanged = mergeDocumentTransitions(node, sourceNode, baselineNode, nodeByRef, parsed.format, sourceVariableByExportName) || structureChanged;
    }
  });
  state.project.links = normalizeLinks(state.project.links);
  syncProjectChoiceOptionLinks(state.project);
  return { structureChanged };
}

function documentValuesEqual(left, right) {
  return JSON.stringify(left) === JSON.stringify(right);
}

function normalizeDocumentVariableValue(value) {
  if (typeof value !== "string") return value;
  const trimmed = value.trim();
  if (/^(?:\[|\{)/.test(trimmed)) {
    try {
      return JSON.parse(trimmed);
    } catch (error) {
      return value;
    }
  }
  return value;
}

function resolveDocumentNodeType(value) {
  const candidate = normalizeOptionalString(value).trim().toLowerCase();
  if (!candidate) return "";
  const type = getProjectNodeTypes().find((typeDef) => (
    typeDef.type.toLowerCase() === candidate || normalizeOptionalString(typeDef.label).trim().toLowerCase() === candidate
  ));
  return type && !isFrameKind(type.kind) ? type.type : "";
}

function restoreDocumentBodyVariables(value, format, sourceVariableByExportName) {
  let output = String(value || "");
  [...sourceVariableByExportName.entries()]
    .sort((a, b) => b[0].length - a[0].length)
    .forEach(([exportKey, sourceKey]) => {
      const escaped = exportKey.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
      if (format === "yarn") output = output.replace(new RegExp(`\\{\\$${escaped}\\}`, "g"), `{${sourceKey}}`);
      else if (format === "twee") output = output.replace(new RegExp(`<<print\\s+\\$${escaped}\\s*>>`, "g"), `{${sourceKey}}`);
      else output = output.replace(new RegExp(`\\{${escaped}\\}`, "g"), `{${sourceKey}}`);
    });
  return output;
}

function restoreDocumentCondition(value, format, sourceVariableByExportName) {
  let output = String(value || "");
  if (format === "yarn") {
    output = replaceOutsideDocumentStrings(output, (segment) => segment
      .replace(/\bcontains\(\s*\$?([A-Za-z_]\w*)\s*,\s*([^()]+?)\s*\)/g, "$1.includes($2)")
      .replace(/\band\b/g, "&&")
      .replace(/\bor\b/g, "||")
      .replace(/\bnot\s+/g, "!"));
  } else if (format === "ink") {
    const runtimeDocument = buildRuntimeExportDocument();
    const listMap = buildInkListMap(runtimeDocument);
    output = replaceOutsideDocumentStrings(output, (segment) => segment
      .replace(/\(\s*([A-Za-z_]\w*)\s*\?\s*([A-Za-z_]\w*)\s*\)/g, (match, key, identifier) => {
        const list = listMap[key];
        const item = list?.items?.find((entry) => entry.identifier === identifier);
        if (!item) return match;
        const originalValues = Array.isArray(runtimeDocument.variables?.[key]) ? runtimeDocument.variables[key] : [];
        const original = originalValues.find((entry) => String(entry) === item.value);
        return `${key}.includes(${formatDocumentLiteral(original === undefined ? item.value : original)})`;
      })
      .replace(/\band\b/g, "&&")
      .replace(/\bor\b/g, "||")
      .replace(/\bnot\s+/g, "!"));
  }
  return restoreDocumentExpressionVariables(output, format, sourceVariableByExportName);
}

function restoreDocumentExpressionVariables(value, format, sourceVariableByExportName) {
  return replaceOutsideDocumentStrings(String(value || ""), (segment) => {
    let output = segment;
    [...sourceVariableByExportName.entries()]
      .sort((a, b) => b[0].length - a[0].length)
      .forEach(([exportKey, sourceKey]) => {
        const escaped = exportKey.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
        output = output.replace(new RegExp(`\\$${escaped}\\b`, "g"), sourceKey);
        output = output.replace(new RegExp(`\\b${escaped}\\b`, "g"), sourceKey);
      });
    return output;
  });
}

function replaceOutsideDocumentStrings(value, replaceSegment) {
  const text = String(value || "");
  let output = "";
  let segment = "";
  let quote = "";
  let escaped = false;
  const flush = () => {
    if (!segment) return;
    output += quote ? segment : replaceSegment(segment);
    segment = "";
  };
  for (const char of text) {
    if (quote) {
      segment += char;
      if (escaped) escaped = false;
      else if (char === "\\") escaped = true;
      else if (char === quote) {
        flush();
        quote = "";
      }
      continue;
    }
    if (char === '"' || char === "'") {
      flush();
      quote = char;
      segment = char;
      continue;
    }
    segment += char;
  }
  flush();
  return output;
}

function restoreDocumentEffect(effect, format, sourceVariableByExportName) {
  const key = sourceVariableByExportName.get(effect?.key) || effect?.key || "";
  let value = restoreDocumentExpressionVariables(effect?.value || "", format, sourceVariableByExportName);
  if (/^"(?:\\.|[^"])*"$/.test(value)) {
    try {
      value = String(JSON.parse(value));
    } catch (error) {
      // Keep malformed target-format literals visible for correction.
    }
  }
  return {
    trigger: effect?.trigger || "onVisit",
    op: effect?.op || "set",
    key,
    value
  };
}

function mergeDocumentEffects(existingEffects, sourceEffects, format, sourceVariableByExportName, defaultTrigger) {
  const restored = (sourceEffects || []).map((effect) => restoreDocumentEffect({ ...effect, trigger: effect?.trigger || defaultTrigger }, format, sourceVariableByExportName));
  const preserved = (existingEffects || []).filter((effect) => !isDocumentEditableEffect(effect, format, defaultTrigger));
  return [...restored, ...preserved];
}

function isDocumentEditableEffect(effect, format, defaultTrigger) {
  if (isRuntimeVisitTrackingEffect(effect)) return false;
  if (format === "plain") return true;
  const trigger = normalizePlaybookActionTrigger(effect?.trigger || defaultTrigger);
  const op = normalizePlaybookActionOperation(effect?.op || "set");
  return trigger === defaultTrigger && ["set", "add", "subtract", "toggle"].includes(op);
}

function syncDialogTurnsFromDocumentBody(node) {
  const lines = String(node.body || "").split(/\r?\n/).filter((line) => line.trim());
  node.turns = lines.map((line) => {
    const match = line.match(/^([^:\n]{1,80}):\s*(.*)$/);
    return match ? { speaker: match[1].trim(), line: match[2] } : { speaker: "", line };
  });
  syncDialogCastFromTurns(node);
}

function mergeDocumentChoices(node, sourceChoices, format, sourceVariableByExportName, nodeByRef) {
  const existing = ensureChoiceOptionsArray(node);
  const assignedIds = new Set();
  const previousOptions = [];
  node.choiceOptions = sourceChoices.map((choice, index) => {
    const requestedId = normalizeOptionalString(choice.id).trim();
    const previous = existing.find((option) => requestedId && option.id === requestedId) || existing[index] || {};
    previousOptions.push(previous);
    let id = requestedId || previous.id;
    if (!id || assignedIds.has(id)) {
      const reserved = new Set([...existing.map((option) => option.id).filter(Boolean), ...assignedIds]);
      id = generateChoiceOptionId(reserved, index);
    }
    assignedIds.add(id);
    return {
      ...previous,
      id,
      label: restoreDocumentBodyVariables(normalizeOptionalString(choice.label).trim(), format, sourceVariableByExportName),
      requires: restoreDocumentCondition(choice.requires || "", format, sourceVariableByExportName),
      requiresMode: getStoredConditionModeForExpression(choice.requires || "", "all"),
      effects: mergeDocumentEffects(previous.effects || [], choice.effects || [], format, sourceVariableByExportName, "onChoose")
    };
  });
  syncChoicesFromOptions(node);
  const outgoing = state.project.links.filter((link) => link.from === node.id);
  const usedLinks = new Set();
  node.choiceOptions.forEach((option, index) => {
    const choice = sourceChoices[index] || {};
    const previous = previousOptions[index] || {};
    let link = outgoing.find((candidate) => !usedLinks.has(candidate) && candidate.choiceOptionId === previous.id)
      || outgoing.find((candidate) => !usedLinks.has(candidate) && Number(candidate.choiceIndex) === index)
      || outgoing.find((candidate) => !usedLinks.has(candidate));
    const target = resolveDocumentTarget(choice.goto, nodeByRef);
    if (!link && target) {
      link = { id: nextId("l", state.project.links), from: node.id, to: target.id };
      state.project.links.push(link);
    }
    if (!link) return;
    usedLinks.add(link);
    link.label = option.label;
    link.choiceIndex = index;
    link.choiceOptionId = option.id;
    if (target) link.to = target.id;
  });
  state.project.links = state.project.links.filter((link) => link.from !== node.id || usedLinks.has(link));
}

function mergeDocumentTransitions(node, sourceNode, baselineNode, nodeByRef, format, sourceVariableByExportName) {
  const routes = sourceNode.next?.length ? sourceNode.next : sourceNode.branches || [];
  const baselineRoutes = baselineNode.next?.length ? baselineNode.next : baselineNode.branches || [];
  const routing = normalizeNodeRouting(node.routing);
  if (routing.mode === "goTo") {
    const target = resolveDocumentTarget(routes[0]?.goto, nodeByRef);
    if (target) node.routing = { mode: "goTo", target: target.title || target.id };
    else if (!routes.length && baselineRoutes.length) node.routing = { mode: "end", target: "" };
    return true;
  }
  const outgoing = state.project.links.filter((link) => link.from === node.id);
  let changed = false;
  const usedLinks = new Set();
  routes.forEach((route, index) => {
    let link = outgoing[index];
    const target = resolveDocumentTarget(route.goto, nodeByRef);
    if (!link && target) {
      link = { id: nextId("l", state.project.links), from: node.id, to: target.id };
      state.project.links.push(link);
      changed = true;
    }
    if (!link) return;
    usedLinks.add(link);
    if (target && link.to !== target.id) {
      link.to = target.id;
      changed = true;
    }
    const baselineRoute = baselineRoutes[index] || {};
    if (!documentValuesEqual(route.condition || "", baselineRoute.condition || "")) {
      const condition = restoreDocumentCondition(route.condition || "", format, sourceVariableByExportName);
      if (condition) link.requirements = condition;
      else delete link.requirements;
      changed = true;
    }
    if (!documentValuesEqual(route.label || "", baselineRoute.label || "") && route.label) {
      link.label = route.label;
      changed = true;
    }
  });
  if (routes.length !== baselineRoutes.length) {
    state.project.links = state.project.links.filter((link) => link.from !== node.id || usedLinks.has(link));
    changed = true;
  }
  return changed;
}

function resolveDocumentTarget(value, nodeByRef) {
  const key = normalizeStoryMarkdownRef(value);
  if (!key || key === "end") return null;
  return nodeByRef.get(key) || null;
}

function buildStoryMarkdownNode(sourceNode, index, usedIds) {
  const type = sourceNode.type || (index === 0 ? "Entry" : sourceNode.choices.length ? "Choice" : "Content");
  const id = makeUniqueStoryMarkdownId(sourceNode.id || `n${index}`, usedIds);
  const node = {
    id,
    type,
    title: sourceNode.title || id,
    body: sourceNode.body || "",
    x: 80 + (index % 3) * 280,
    y: 80 + Math.floor(index / 3) * 220
  };
  if (sourceNode.requires || sourceNode.effects.length) {
    node.stateLogic = {
      requirements: sourceNode.requires,
      requirementsMode: getStoredConditionModeForExpression(sourceNode.requires, "all"),
      effects: sourceNode.effects
    };
  }
  if (sourceNode.choices.length) {
    node.choices = sourceNode.choices.map((choice) => choice.label);
    node.choiceOptions = sourceNode.choices.map((choice, choiceIndex) => ({
      id: choice.id || `${id}_choice_${choiceIndex + 1}`,
      label: choice.label,
      requires: choice.requires,
      requiresMode: getStoredConditionModeForExpression(choice.requires, "all"),
      effects: choice.effects
    }));
  }
  return normalizeNode(node);
}

function normalizeStoryMarkdownRef(value) {
  return String(value || "").trim().toLowerCase().replace(/\s+/g, "_");
}

function makeUniqueStoryMarkdownId(value, used) {
  const fallback = `n${used.size}`;
  let base = String(value || fallback)
    .replace(/[^a-zA-Z0-9_-]+/g, "_")
    .replace(/^_+|_+$/g, "");
  if (!base) base = fallback;
  if (!/^[a-zA-Z_]/.test(base)) base = `n_${base}`;
  let candidate = base;
  let suffix = 2;
  while (used.has(candidate)) {
    candidate = `${base}_${suffix}`;
    suffix += 1;
  }
  used.add(candidate);
  return candidate;
}

function importStoryMarkdownText(source) {
  const project = buildProjectFromStoryMarkdown(source);
  state.project = normalizeProject(project);
  markProjectStructureChanged({ nodeTypes: true });
  invalidateCharacterRenderContext();
  state.selectedNodeId = state.project.nodes[0]?.id || null;
  state.selectedNodeIds = [];
  state.selectedLinkId = null;
  state.panel = "project";
  state.activeFileId = "adventure";
  state.playbookTab = "variables";
  centerViewAtScale(DEFAULT_CANVAS_ZOOM, false);
  resetHistory();
  setProjectDirty(true);
  renderAll();
  setStatus("Story Markdown imported.");
  return true;
}

function importStoryLayoutText(source) {
  const document = typeof source === "string" ? JSON.parse(source) : source;
  applyStoryLayoutDocument(document);
  state.activeFileId = "adventure";
  markProjectStructureChanged({ nodeTypes: true });
  sanitizeFrameMembership(state.project);
  resetHistory();
  setProjectDirty(true);
  renderAll();
  setStatus("Story layout imported.");
  return true;
}

function applyStoryLayoutDocument(document) {
  if (!document || typeof document !== "object" || Array.isArray(document)) throw new Error("Invalid story layout.");
  if (document.format !== "narrative-canvas-story-layout" || document.version !== 1) throw new Error("Unsupported story layout.");
  if (!Array.isArray(document.nodes)) throw new Error("Story layout nodes are missing.");
  const nodeLayouts = new Map(document.nodes
    .filter((node) => node && typeof node === "object" && !Array.isArray(node) && node.id)
    .map((node) => [String(node.id), node]));
  const nodesById = new Map((state.project.nodes || []).map((node) => [node.id, node]));

  nodeLayouts.forEach((layout) => {
    if (!layout.frame || nodesById.has(String(layout.id))) return;
    const frameNode = normalizeNode({
      id: String(layout.id),
      type: "Event",
      title: normalizeOptionalString(layout.title).trim() || "Frame",
      body: "",
      x: Number(layout.x) || 0,
      y: Number(layout.y) || 0,
      width: Number(layout.width) || getNodeMeta("Event").width || 420,
      height: Number(layout.height) || 260,
      frameId: normalizeOptionalString(layout.frameId).trim(),
      collapsed: Boolean(layout.collapsed)
    });
    state.project.nodes.push(frameNode);
    nodesById.set(frameNode.id, frameNode);
  });

  state.project.nodes.forEach((node) => {
    const layout = nodeLayouts.get(node.id);
    if (!layout) return;
    applyStoryLayoutToNode(node, layout);
  });
  applyStoryLayoutToLinks(document.links);
  if (document.view) state.view = normalizeView(document.view);
}

function applyStoryLayoutToNode(node, layout) {
  const x = Number(layout.x);
  const y = Number(layout.y);
  if (Number.isFinite(x)) node.x = x;
  if (Number.isFinite(y)) node.y = y;
  if (layout.width != null) {
    const width = Number(layout.width);
    if (Number.isFinite(width) && width > 0) node.width = width;
  }
  if (layout.height != null) {
    const height = Number(layout.height);
    if (Number.isFinite(height) && height > 0) node.height = height;
  }
  if (Object.prototype.hasOwnProperty.call(layout, "frameId")) node.frameId = normalizeOptionalString(layout.frameId).trim();
  const portPositions = layout.portPositions || layout.ports;
  if (portPositions && typeof portPositions === "object" && !Array.isArray(portPositions)) {
    node.ports = normalizeNodePorts(portPositions, node);
    delete node.portPositions;
  }
  if (Object.prototype.hasOwnProperty.call(layout, "collapsed") && isFrameNode(node)) {
    node.collapsed = Boolean(layout.collapsed);
  }
}

function applyStoryLayoutToLinks(layoutLinks) {
  if (!Array.isArray(layoutLinks) || !Array.isArray(state.project.links)) return;
  const usedIds = new Set(state.project.links.map((link) => link.id).filter(Boolean));
  state.project.links.forEach((link) => {
    const layout = findStoryLayoutForLink(link, layoutLinks);
    if (!layout) return;
    const nextId = normalizeOptionalString(layout.id).trim();
    if (nextId && (nextId === link.id || !usedIds.has(nextId))) {
      usedIds.delete(link.id);
      link.id = nextId;
      usedIds.add(nextId);
    }
    if (Object.prototype.hasOwnProperty.call(layout, "label")) link.label = normalizeOptionalString(layout.label).trim();
    if (Object.prototype.hasOwnProperty.call(layout, "choiceIndex")) {
      const choiceIndex = normalizeChoiceIndex(layout.choiceIndex);
      if (choiceIndex == null) delete link.choiceIndex;
      else link.choiceIndex = choiceIndex;
    }
    if (Object.prototype.hasOwnProperty.call(layout, "choiceOptionId")) {
      const choiceOptionId = normalizeOptionalString(layout.choiceOptionId).trim();
      if (choiceOptionId) link.choiceOptionId = choiceOptionId;
      else delete link.choiceOptionId;
    }
    if (Object.prototype.hasOwnProperty.call(layout, "requirements")) {
      const requirements = normalizeOptionalString(layout.requirements).trim();
      if (requirements) link.requirements = requirements;
      else delete link.requirements;
    }
  });
  state.project.links = normalizeLinks(state.project.links);
}

function findStoryLayoutForLink(link, layoutLinks) {
  const byId = layoutLinks.find((item) => item?.id && item.id === link.id && item.from === link.from && item.to === link.to);
  if (byId) return byId;
  return layoutLinks.find((item) => {
    if (!item || item.from !== link.from || item.to !== link.to) return false;
    if (item.choiceOptionId && link.choiceOptionId) return item.choiceOptionId === link.choiceOptionId;
    if (item.choiceIndex != null && link.choiceIndex != null) return normalizeChoiceIndex(item.choiceIndex) === normalizeChoiceIndex(link.choiceIndex);
    return normalizeOptionalString(item.label).trim() === normalizeOptionalString(link.label).trim();
  }) || null;
}

function importStateSchemaText(source) {
  const document = typeof source === "string" ? JSON.parse(source) : source;
  const variables = buildVariablesFromStateSchemaDocument(document);
  state.project.variables = variables;
  state.activeFileId = "variables";
  state.playbookTab = "variables";
  state.panel = "project";
  resetHistory();
  setProjectDirty(true);
  renderAll();
  setStatus("State schema imported.");
  return true;
}

function buildVariablesFromStateSchemaDocument(document) {
  if (!document || typeof document !== "object" || Array.isArray(document)) throw new Error("Invalid state schema.");
  if (document.format !== "narrative-canvas-state-schema" || document.version !== 1) throw new Error("Unsupported state schema.");
  if (!Array.isArray(document.variables)) throw new Error("State schema variables are missing.");
  const variables = {};
  document.variables.forEach((entry) => {
    if (!entry || typeof entry !== "object" || Array.isArray(entry)) return;
    const key = normalizeStateReportKey(entry.exportKey || entry.key);
    if (!key || !entry.hasInitial || !Object.prototype.hasOwnProperty.call(entry, "initialValue")) return;
    variables[key] = cloneRuntimeExportValue(entry.initialValue);
  });
  return variables;
}

function normalizePlayHistoryLimit(value) {
  const number = Number(value);
  return PLAY_HISTORY_LIMIT_OPTIONS.includes(number) ? number : DEFAULT_PLAY_HISTORY_LIMIT;
}

function normalizeRichTextFormat(value) {
  const format = normalizeOptionalString(value).trim().toLowerCase();
  return RICH_TEXT_FORMAT_VALUES.has(format) ? format : DEFAULT_RICH_TEXT_FORMAT;
}

function normalizeProject(project) {
  const nodeTypesList = normalizeProjectNodeTypes(project.nodeTypes, project.customNodeTypes);
  const nodeTypeTemplates = new Map(nodeTypesList.map((typeDef) => [typeDef.type, getNodeTypeTemplate(typeDef)]));
  const eventFrameTypes = new Set(nodeTypesList.filter(isEventSheetTypeDef).map((typeDef) => typeDef.type));
  const eventSheet = normalizeEventSheetConfig(project.eventSheet, project.eventSheetHiddenColumns);
  const normalized = {
    title: project.title || "Sample",
    workflowMode: normalizeWorkflowMode(project.workflowMode || project.sourceMode || project.mode),
    notes: project.notes || "",
    playHistoryLimit: normalizePlayHistoryLimit(project.playHistoryLimit),
    richTextFormat: normalizeRichTextFormat(project.richTextFormat),
    variables: normalizeVariablesObject(project.variables),
    script: normalizeScriptConfig(project.script),
    eventSheet,
    eventRowOrder: normalizeEventRowOrder(project.eventRowOrder),
    nodeTypes: nodeTypesList,
    customNodeTypes: [],
    codexFieldTemplates: normalizeCodexFieldTemplates(project.codexFieldTemplates),
    customCodexKinds: normalizeCustomCodexKinds(project.customCodexKinds),
    characters: normalizeProjectCharacters(project),
    deletedNodes: Array.isArray(project.deletedNodes) ? project.deletedNodes : [],
    nodes: Array.isArray(project.nodes) ? project.nodes.map((node) => normalizeNode(node, eventFrameTypes, eventSheet.columns, nodeTypeTemplates)) : [],
    links: normalizeLinks(project.links)
  };
  migrateRetiredNodeFeatures(normalized, project.script?.nodeTypes);
  inferLegacyDialogTurns(normalized, nodeTypeTemplates);
  inferLegacyFrameMembership(normalized);
  syncProjectChoiceOptionLinks(normalized);
  syncProjectChoiceBranchLinks(normalized);
  return normalized;
}

function getRetiredScriptReference(node, reference) {
  const key = normalizeOptionalString(reference).trim();
  if (!key) return "";
  if (Object.prototype.hasOwnProperty.call(node, key)) return normalizeOptionalString(node[key]);
  if (node.customFields && Object.prototype.hasOwnProperty.call(node.customFields, key)) return normalizeOptionalString(node.customFields[key]);
  return key;
}

function addMigratedNodeEffect(node, key, value) {
  const normalizedKey = normalizeOptionalString(key).trim();
  if (!normalizedKey) return;
  const logic = normalizeNodeStateLogic(node.stateLogic);
  const duplicate = logic.effects.some((effect) => effect.trigger === "onVisit" && effect.op === "set" && effect.key === normalizedKey && normalizeOptionalString(effect.value) === normalizeOptionalString(value));
  if (!duplicate) logic.effects.push({ trigger: "onVisit", op: "set", key: normalizedKey, value: normalizeOptionalString(value) });
  node.stateLogic = logic;
}

function addMigratedLinkRequirement(link, expression) {
  const next = normalizeOptionalString(expression).trim();
  if (!next) return;
  link.requirements = link.requirements ? appendConditionExpression(link.requirements, next, "all") : next;
}

function migrateRetiredNodeFeatures(project, rawNodeTypeScripts) {
  if (!project || !Array.isArray(project.nodes) || !Array.isArray(project.links)) return;
  const scripts = rawNodeTypeScripts && typeof rawNodeTypeScripts === "object" && !Array.isArray(rawNodeTypeScripts) ? rawNodeTypeScripts : {};
  const outgoingByNode = new Map();
  project.links.forEach((link) => {
    if (!outgoingByNode.has(link.from)) outgoingByNode.set(link.from, []);
    outgoingByNode.get(link.from).push(link);
  });
  project.nodes.forEach((node) => {
    const retiredType = RETIRED_NODE_TYPES.has(node.type);
    const script = scripts[node.id] || scripts[node.type] || {};
    const directKey = normalizeOptionalString(node.variable || node.variables).trim();
    if (directKey && node.value != null) addMigratedNodeEffect(node, directKey, node.value);
    if (script?.set?.key) {
      addMigratedNodeEffect(node, getRetiredScriptReference(node, script.set.key), getRetiredScriptReference(node, script.set.value));
    }

    const directCondition = normalizeOptionalString(node.condition).trim();
    const scriptedCondition = script?.condition ? getRetiredScriptReference(node, script.condition).trim() : "";
    const condition = directCondition || scriptedCondition || (node.type === "Condition" ? normalizeOptionalString(node.body).trim() : "");
    if (condition) {
      const outgoing = outgoingByNode.get(node.id) || [];
      if (outgoing.length >= 2) {
        addMigratedLinkRequirement(outgoing[0], condition);
        addMigratedLinkRequirement(outgoing[1], `!(${condition})`);
      } else {
        const logic = normalizeNodeStateLogic(node.stateLogic);
        if (!logic.requirements) logic.requirements = condition;
        logic.requirementsMode = getStoredConditionModeForExpression(logic.requirements, logic.requirementsMode);
        node.stateLogic = logic;
      }
      if (node.type === "Condition" && normalizeOptionalString(node.body).trim() === condition) node.body = "";
    }

    if (retiredType) node.type = "Content";
    delete node.variable;
    delete node.variables;
    delete node.value;
    delete node.condition;
    delete node.conditionMode;
    if (node.stateLogic) cleanupNodeStateLogic(node);
  });
}

function inferLegacyDialogTurns(project, templateMap = null) {
  if (!project || !Array.isArray(project.nodes)) return;
  const characterNames = new Set((project.characters || []).map((character) => String(character.name || "").trim()).filter(Boolean));
  project.nodes.forEach((node) => {
    if (!isDialogNode(node, templateMap) || Array.isArray(node.turns)) return;
    const line = normalizeOptionalString(node.body).trim();
    if (!line) return;
    const title = normalizeOptionalString(node.title).trim();
    const speaker = characterNames.has(title) ? title : "";
    node.turns = [{ speaker, line }];
    if (speaker) node.title = `${speaker} scene`;
    syncDialogCastFromTurns(node, project.characters || []);
  });
}

function syncDialogCastFromTurns(node, characters = getCastCharacters()) {
  if (!node || !Array.isArray(node.turns) || !Array.isArray(characters) || !characters.length) return;
  characters = characters.filter((character) => normalizeCodexKind(character?.kind) === "Character");
  const cast = Array.isArray(node.cast) ? node.cast : [];
  const existingSpeakerCharIds = new Set(cast.filter((c) => c.role === "Speaker").map((c) => c.characterId));
  const speakerNames = new Set(node.turns.map((t) => String(t.speaker || "").trim()).filter(Boolean));
  speakerNames.forEach((name) => {
    const character = characters.find((c) => c.name === name);
    if (character && !existingSpeakerCharIds.has(character.id)) {
      cast.push({ characterId: character.id, role: "Speaker" });
      existingSpeakerCharIds.add(character.id);
    }
  });
  if (cast.length) node.cast = cast;
}

// One-time geometric -> explicit migration: only nodes that do not carry a
// frameId field are inferred from geometry. Nodes with frameId: "" intentionally
// live at the root and must not be recaptured on later loads.
function inferLegacyFrameMembership(project) {
  if (!project || !Array.isArray(project.nodes)) return;
  const frames = project.nodes.filter((node) => isFrameNode(node));
  const frameEntries = buildFrameContainmentEntries(frames);
  const frameIndex = buildFrameContainmentIndex(frameEntries);
  project.nodes.forEach((node) => {
    if (Object.prototype.hasOwnProperty.call(node, "frameId")) return;
    const winner = getSmallestContainingFrameForNode(node, frameIndex);
    node.frameId = winner ? winner.id : "";
  });
  sanitizeFrameMembership(project);
}

function sanitizeFrameMembership(project) {
  if (!project || !Array.isArray(project.nodes)) return;
  const nodeMap = new Map(project.nodes.map((node) => [node.id, node]));
  project.nodes.forEach((node) => {
    const parentId = normalizeOptionalString(node.frameId).trim();
    const parent = parentId ? nodeMap.get(parentId) : null;
    if (!parentId || !parent || !isFrameNode(parent) || parent.id === node.id || wouldCreateFrameCycle(node.id, parent.id, nodeMap)) {
      node.frameId = "";
    } else {
      node.frameId = parent.id;
    }
  });
}

function wouldCreateFrameCycle(nodeId, parentId, nodeMap = getNodeIndex()) {
  let current = parentId;
  const seen = new Set();
  while (current) {
    if (current === nodeId) return true;
    if (seen.has(current)) return true;
    seen.add(current);
    const parent = nodeMap.get(current);
    current = normalizeOptionalString(parent?.frameId).trim();
  }
  return false;
}

function buildFrameContainmentEntries(frames) {
  if (!Array.isArray(frames) || !frames.length) return [];
  return frames.map((frame) => {
    const fx = Number(frame?.x);
    const fy = Number(frame?.y);
    const size = nodeLayoutSize(frame);
    const width = Number(size.width);
    const height = Number(size.height);
    if (![fx, fy, width, height].every(Number.isFinite)) return null;
    const area = Math.max(0, width) * Math.max(0, height);
    return {
      frame,
      area,
      left: fx,
      top: fy,
      right: fx + width,
      bottom: fy + height
    };
  }).filter(Boolean);
}

function buildFrameContainmentIndex(frameEntries) {
  if (!Array.isArray(frameEntries) || !frameEntries.length) return [];
  const cells = new Map();
  frameEntries.forEach((entry) => {
    const minX = Math.floor(entry.left / FRAME_CONTAINMENT_INDEX_CELL_SIZE);
    const maxX = Math.floor(entry.right / FRAME_CONTAINMENT_INDEX_CELL_SIZE);
    const minY = Math.floor(entry.top / FRAME_CONTAINMENT_INDEX_CELL_SIZE);
    const maxY = Math.floor(entry.bottom / FRAME_CONTAINMENT_INDEX_CELL_SIZE);
    for (let cellX = minX; cellX <= maxX; cellX += 1) {
      for (let cellY = minY; cellY <= maxY; cellY += 1) {
        const key = `${cellX}:${cellY}`;
        if (!cells.has(key)) cells.set(key, []);
        cells.get(key).push(entry);
      }
    }
  });
  return { entries: frameEntries, cells };
}

function getSmallestContainingFrameForNode(node, frames = state.project.nodes.filter((item) => isFrameNode(item))) {
  if (!node) return null;
  const frameSource = normalizeFrameContainmentSource(frames);
  if (!frameSource.entries.length) return null;
  const nx = Number(node?.x);
  const ny = Number(node?.y);
  if (!Number.isFinite(nx) || !Number.isFinite(ny)) return null;
  const nodeSize = nodeLayoutSize(node);
  const nw = Number(nodeSize.width);
  const nh = Number(nodeSize.height);
  if (!Number.isFinite(nw) || !Number.isFinite(nh)) return null;
  const cx = nx + nw / 2;
  const cy = ny + nh / 2;
  const nodeArea = isFrameNode(node) ? Math.max(0, nw) * Math.max(0, nh) : 0;
  const frameEntries = getFrameContainmentCandidates(frameSource, cx, cy);
  let winner = null;
  let winnerArea = Infinity;
  frameEntries.forEach((entry) => {
    const frame = entry.frame;
    if (!frame || frame.id === node.id) return;
    if (isFrameNode(node) && entry.area <= nodeArea) return;
    if (cx < entry.left || cx > entry.right || cy < entry.top || cy > entry.bottom) return;
    if (entry.area < winnerArea) {
      winner = frame;
      winnerArea = entry.area;
    }
  });
  return winner;
}

function normalizeFrameContainmentSource(frames) {
  if (frames?.cells instanceof Map && Array.isArray(frames.entries)) return frames;
  const frameList = Array.isArray(frames) ? frames : [];
  const entries = frameList.length && frameList[0]?.frame ? frameList : buildFrameContainmentEntries(frameList);
  return { entries, cells: null };
}

function getFrameContainmentCandidates(source, cx, cy) {
  if (!source?.cells) return source?.entries || [];
  const cellX = Math.floor(cx / FRAME_CONTAINMENT_INDEX_CELL_SIZE);
  const cellY = Math.floor(cy / FRAME_CONTAINMENT_INDEX_CELL_SIZE);
  return source.cells.get(`${cellX}:${cellY}`) || [];
}

function frameContainsNodeCenter(frame, node) {
  const fx = Number(frame?.x);
  const fy = Number(frame?.y);
  const frameSize = nodeLayoutSize(frame);
  const fw = frameSize.width;
  const fh = frameSize.height;
  if (!Number.isFinite(fx) || !Number.isFinite(fy) || !Number.isFinite(fw) || !Number.isFinite(fh)) return false;
  const nx = Number(node?.x);
  const ny = Number(node?.y);
  if (!Number.isFinite(nx) || !Number.isFinite(ny)) return false;
  const nodeSize = nodeLayoutSize(node);
  const nw = nodeSize.width;
  const nh = nodeSize.height;
  const cx = nx + nw / 2;
  const cy = ny + nh / 2;
  return cx >= fx && cx <= fx + fw && cy >= fy && cy <= fy + fh;
}

// Map link.choiceIndex (legacy index-bound) → link.choiceOptionId (stable id-bound) for Choice sources.
// Index is preserved as a fallback so older runtimes still resolve; new code prefers choiceOptionId.
function syncProjectChoiceOptionLinks(project) {
  if (!project || !Array.isArray(project.nodes) || !Array.isArray(project.links)) return;
  const nodeMap = new Map(project.nodes.map((node) => [node.id, node]));
  project.links.forEach((link) => {
    const source = nodeMap.get(link.from);
    if (!source || !Array.isArray(source.choiceOptions) || !source.choiceOptions.length) return;
    if (link.choiceOptionId) {
      // Validate it still exists on the source; drop stale ids.
      const exists = source.choiceOptions.some((opt) => opt.id === link.choiceOptionId);
      if (!exists) delete link.choiceOptionId;
      else return;
    }
    const idx = normalizeChoiceIndex(link.choiceIndex);
    if (idx == null) return;
    const option = source.choiceOptions[idx];
    if (option) link.choiceOptionId = option.id;
  });
}

// Resolve a free-text target (node id, exact title, or node type) to matching nodes.
// Used by Playbook actions and rule inspectors to give writers real-time match feedback.
function resolveTarget(target, project = state.project) {
  const result = { input: String(target || "").trim(), kind: "none", matches: [] };
  if (!result.input || !project || !Array.isArray(project.nodes)) return result;
  const byId = project.nodes.find((node) => node.id === result.input);
  if (byId) {
    result.kind = "id";
    result.matches = [byId];
    return result;
  }
  const titleMatches = project.nodes.filter((node) => String(node.title || "").trim() === result.input);
  if (titleMatches.length) {
    result.kind = "title";
    result.matches = titleMatches;
    return result;
  }
  const typeMatches = project.nodes.filter((node) => node.type === result.input);
  if (typeMatches.length) {
    result.kind = "type";
    result.matches = typeMatches;
    return result;
  }
  return result;
}

function normalizeLinks(links) {
  if (!Array.isArray(links)) return [];
  return links.map((link, index) => normalizeLink(link, index)).filter(Boolean);
}

function normalizeLink(link, index) {
  if (!link || typeof link !== "object" || Array.isArray(link)) return null;
  const normalized = {
    ...link,
    id: String(link.id || `l${index + 1}`),
    from: String(link.from || ""),
    to: String(link.to || "")
  };
  const label = normalizeOptionalString(link.label).trim();
  if (label) normalized.label = label;
  else delete normalized.label;
  const choiceIndex = normalizeChoiceIndex(link.choiceIndex);
  if (choiceIndex == null) delete normalized.choiceIndex;
  else normalized.choiceIndex = choiceIndex;
  const choiceOptionId = normalizeOptionalString(link.choiceOptionId).trim();
  if (choiceOptionId) normalized.choiceOptionId = choiceOptionId;
  else delete normalized.choiceOptionId;
  const requirements = normalizeOptionalString(link.requirements || link.requires).trim();
  if (requirements) normalized.requirements = requirements;
  else delete normalized.requirements;
  return normalized;
}

function normalizeEventRowOrder(value) {
  if (!value || typeof value !== "object" || Array.isArray(value)) return {};
  return Object.fromEntries(Object.entries(value)
    .filter(([type, ids]) => type && Array.isArray(ids))
    .map(([type, ids]) => [String(type), ids.map((id) => String(id)).filter(Boolean)]));
}

function getProjectNodeTypes() {
  if (!Array.isArray(state.project.nodeTypes)) {
    state.project.nodeTypes = normalizeProjectNodeTypes(null, state.project.customNodeTypes);
    state.project.customNodeTypes = [];
    markProjectStructureChanged({ nodeTypes: true });
  }
  const cache = state.derived.projectNodeTypes;
  if (cache && cache.source === state.project.nodeTypes && cache.version === state.structureVersion) {
    return cache.value;
  }
  const normalized = normalizeNodeTypes(state.project.nodeTypes);
  state.project.nodeTypes = normalized;
  // After canonicalizing, source === value === the array ref, so subsequent calls
  // at the same structureVersion hit the cache without re-normalizing (which previously
  // allocated a fresh array on every call and defeated downstream ref-based caches).
  state.derived.projectNodeTypes = { source: normalized, version: state.structureVersion, value: normalized };
  return normalized;
}

function normalizeProjectNodeTypes(types, legacyCustomTypes) {
  const hasProjectTypes = Array.isArray(types);
  const normalized = normalizeNodeTypes(hasProjectTypes ? types : defaultNodeTypeList()).filter((typeDef) => !RETIRED_NODE_TYPES.has(typeDef.type));
  const legacyTypes = normalizeNodeTypes(legacyCustomTypes).filter((typeDef) => !RETIRED_NODE_TYPES.has(typeDef.type));
  if (!legacyTypes.length) return normalized;
  const seen = new Set(normalized.map((typeDef) => typeDef.type));
  return [
    ...normalized,
    ...legacyTypes.filter((typeDef) => {
      if (seen.has(typeDef.type)) return false;
      seen.add(typeDef.type);
      return true;
    })
  ];
}

function normalizeRemovedColumns(value) {
  if (!Array.isArray(value)) return [];
  const seen = new Set();
  return value
    .map((key) => String(key || "").trim())
    .filter((key) => key && !seen.has(key) && seen.add(key));
}

function normalizeNodeTypes(types) {
  if (!Array.isArray(types)) return [];
  const seen = new Set();
  return types
    .map(normalizeCustomNodeType)
    .filter((typeDef) => {
      if (!typeDef || seen.has(typeDef.type)) return false;
      seen.add(typeDef.type);
      return true;
    });
}

function normalizeCustomNodeType(typeDef) {
  const label = String(typeDef?.label || typeDef?.type || "").trim().slice(0, 40);
  if (!label) return null;
  const type = String(typeDef?.type || customNodeTypeId(label)).trim() || customNodeTypeId(label);
  const template = normalizeNodeTypeTemplate(typeDef?.template, type, typeDef?.kind);
  const kind = template === "frame" ? "frame" : "node";
  const builtIn = nodeTypes[type];
  return {
    type,
    label,
    badge: normalizeNodeTypeBadge(getNormalizedNodeTypeBadge(type, label, typeDef?.badge, typeDef?.badgeCustom)) || getDefaultNodeTypeBadge(label),
    color: normalizeNodeTypeColor(type, kind, typeDef?.color),
    width: clamp(Number(typeDef?.width) || (isFrameKind(kind) ? 420 : 200), 160, isFrameKind(kind) ? 860 : 420),
    custom: Boolean(typeDef?.custom),
    badgeCustom: Boolean(typeDef?.badgeCustom),
    kind,
    template,
    fields: normalizeNodeTypeFields(typeDef?.fields),
    removedColumns: isFrameKind(kind) ? normalizeRemovedColumns(typeDef?.removedColumns) : [],
    eventColumnLabels: isFrameKind(kind) ? normalizeEventColumnLabels(typeDef?.eventColumnLabels) : {},
    hidden: Boolean(typeDef?.hidden),
    eventSheetHidden: isFrameKind(kind) ? Boolean(typeDef?.eventSheetHidden) : false,
    cardOpacity: normalizeNodeTypeOpacity(typeDef?.cardOpacity),
    system: Boolean(typeDef?.system) || Boolean(builtIn?.system)
  };
}

function getNodeCustomFieldValue(node, key) {
  if (isDirectNodeField(key)) return node?.[key] == null ? "" : String(node[key]);
  if (!node?.customFields || typeof node.customFields !== "object") return "";
  return node.customFields[key] == null ? "" : String(node.customFields[key]);
}

function isDirectNodeField(key) {
  return DIRECT_NODE_FIELD_KEYS.has(String(key || "").trim());
}

function normalizeNodeTypeKind(value) {
  if (value === "eventFrame") return "frame";
  return value === "frame" ? "frame" : "node";
}

function getBuiltInNodeTypeTemplate(type, kind = "node") {
  if (type === "Dialog") return "dialog";
  if (type === "Choice") return "choice";
  return isFrameKind(kind) || type === "Event" ? "frame" : "node";
}

function normalizeNodeTypeTemplate(value, type = "", kind = "node") {
  const normalized = String(value || "").trim().toLowerCase();
  if (NODE_TYPE_TEMPLATES.has(normalized)) return normalized;
  return getBuiltInNodeTypeTemplate(type, normalizeNodeTypeKind(kind));
}

function getNodeTypeTemplate(typeOrDef, templateMap = null) {
  const requestedType = typeof typeOrDef === "string" ? typeOrDef : String(typeOrDef?.type || "");
  if (templateMap?.has(requestedType)) return templateMap.get(requestedType);
  const typeDef = typeof typeOrDef === "string"
    ? getNodeTypeDef(typeOrDef)
    : (typeOrDef?.type ? typeOrDef : getNodeTypeDef(typeOrDef?.type));
  return normalizeNodeTypeTemplate(typeDef?.template, typeDef?.type || requestedType, typeDef?.kind || "node");
}

function isChoiceNode(node, templateMap = null) {
  return Boolean(node?.type) && getNodeTypeTemplate(node.type, templateMap) === "choice";
}

function isDialogNode(node, templateMap = null) {
  return Boolean(node?.type) && getNodeTypeTemplate(node.type, templateMap) === "dialog";
}

function parseCustomNodeFields(value, previousFields = []) {
  const previousByLabel = new Map(
    previousFields
      .filter((field) => field?.label && field?.key)
      .map((field) => [String(field.label).trim().toLowerCase(), field.key])
  );
  return String(value || "")
    .split(/\r?\n/)
    .map((line) => line.trim())
    .map((label, index) => {
      if (!label) return null;
      const previousKey = previousByLabel.get(label.toLowerCase()) || previousFields[index]?.key;
      return { key: previousKey, label };
    })
    .filter(Boolean);
}

function normalizeNodeTypeFields(fields) {
  if (!Array.isArray(fields)) return [];
  const seen = new Set();
  return fields
    .map((field, index) => {
      const label = String(field?.label || field?.key || "").trim().slice(0, 40);
      if (!label) return null;
      let key = String(field?.key || fieldKeyFromLabel(label, index)).trim();
      key = key.replace(/[^\w-]/g, "_").replace(/^[-_]+|[-_]+$/g, "") || "field";
      if (/^\d/.test(key)) key = `field_${key}`;
      let uniqueKey = key;
      let duplicateIndex = 2;
      while (seen.has(uniqueKey)) {
        uniqueKey = `${key}_${duplicateIndex}`;
        duplicateIndex += 1;
      }
      seen.add(uniqueKey);
      return { key: uniqueKey, label };
    })
    .filter(Boolean)
    .slice(0, 12);
}

function fieldKeyFromLabel(label, index) {
  const ascii = String(label || "")
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, "_")
    .replace(/^_+|_+$/g, "");
  return ascii || `field_${index + 1}`;
}

function uniqueCustomNodeTypeId(label) {
  const base = customNodeTypeId(label);
  const existing = new Set(getProjectNodeTypes().map((typeDef) => typeDef.type));
  let type = base;
  let index = 2;
  while (existing.has(type)) {
    type = `${base}_${index}`;
    index += 1;
  }
  return type;
}

function customNodeTypeId(label) {
  return `Custom_${slugify(label).replace(/-/g, "_") || "node"}`;
}

function getNormalizedNodeTypeBadge(type, label, value, isCustomBadge = false) {
  const raw = String(value ?? "").trim();
  if (!raw || (!isCustomBadge && nodeTypes[type] && raw === LEGACY_DEFAULT_NODE_BADGES[type])) {
    return getDefaultNodeTypeBadge(label);
  }
  return raw;
}

function getDefaultNodeTypeBadge(label) {
  const first = firstGrapheme(label);
  return first ? uppercaseIconGrapheme(first) : "N";
}

function normalizeNodeTypeBadge(value) {
  return normalizeCustomIconText(value);
}

function normalizeCustomColor(value) {
  const color = String(value || "").trim();
  return /^#[0-9a-f]{6}$/i.test(color) ? color : DEFAULT_CUSTOM_NODE_COLOR;
}

function normalizeNodeTypeColor(type, kind, value) {
  const color = String(value || "").trim();
  if (type === "Event" && (!/^#[0-9a-f]{6}$/i.test(color) || LEGACY_EVENT_FRAME_COLORS.has(color.toLowerCase()))) {
    return DEFAULT_EVENT_FRAME_COLOR;
  }
  if (/^#[0-9a-f]{6}$/i.test(color)) return color;
  return getDefaultNodeTypeColor(kind);
}

function getDefaultNodeTypeColor(kind) {
  if (kind === "frame") return DEFAULT_VISUAL_FRAME_COLOR;
  return DEFAULT_CUSTOM_NODE_COLOR;
}

function normalizeNodeTypeOpacity(value) {
  if (value === undefined || value === null || value === "") return null;
  const number = Number(value);
  if (!Number.isFinite(number)) return null;
  return Math.max(0, Math.min(100, Math.round(number)));
}

function normalizeNode(node, eventFrameTypes = null, eventColumns = null, templateMap = null) {
  const normalized = { ...node };
  const hasExplicitFrameId = Object.prototype.hasOwnProperty.call(normalized, "frameId");
  delete normalized.icon;
  if (Number.isFinite(Number(normalized.storyOrder))) {
    normalized.storyOrder = Number(normalized.storyOrder);
  } else {
    delete normalized.storyOrder;
  }
  normalized.choices = parseChoiceLines(normalized.choices);
  normalized.vaultFiles = normalizeNodeVaultFiles(normalized.vaultFiles, normalized.vaultFile, normalized.vaultFilePreview);
  delete normalized.vaultFile;
  delete normalized.vaultFilePreview;
  if (!normalized.vaultFiles.length) delete normalized.vaultFiles;
  normalized.customFields = normalizeNodeCustomFields(normalized.customFields);
  normalized.cast = normalizeNodeCast(normalized.cast);
  if (!normalized.cast.length) delete normalized.cast;
  migrateDirectCustomFields(normalized);
  if (normalized.type === "Frame") {
    normalized.type = "Event";
    if (normalized.eventType === "Frame" || normalized.eventType === "Event") normalized.eventType = "";
  }
  // Jump legacy: collapse to Content; routing.goTo carries the destination so flow is preserved.
  if (normalized.type === "Jump") {
    if (!normalized.routing && normalized.body) {
      normalized.routing = { mode: "goTo", target: String(normalized.body).trim() };
    }
    normalized.type = "Content";
  }
  const isEventType = eventFrameTypes ? eventFrameTypes.has(normalized.type) : isEventSheetNode(normalized);
  if (isEventType) ensureEventDefaults(normalized, eventColumns);
  const rawPorts = normalized.ports || normalized.portPositions;
  normalized.ports = normalizeNodePorts(rawPorts, normalized);
  delete normalized.portPositions;
  normalized.stateLogic = normalizeNodeStateLogic(normalized.stateLogic);
  if (!normalized.stateLogic.requirements && !normalized.stateLogic.effects.length) delete normalized.stateLogic;
  if (normalized.condition || normalized.type === "Condition") normalized.conditionMode = normalizeStoredConditionGroupMode(normalized.conditionMode);
  else delete normalized.conditionMode;
  normalized.routing = normalizeNodeRouting(normalized.routing || normalized.route);
  if (normalized.routing.mode === "continue" && !normalized.routing.target) delete normalized.routing;
  // Explicit frame membership; "" means root level. Missing frameId means legacy
  // data and is inferred once in normalizeProject.
  if (hasExplicitFrameId) normalized.frameId = normalizeOptionalString(normalized.frameId).trim();
  else delete normalized.frameId;
  if (isFrameNode(normalized)) {
    normalized.collapsed = Boolean(normalized.collapsed);
    normalized.layout = normalizeFrameLayout(normalized.layout);
  } else {
    delete normalized.collapsed;
    delete normalized.layout;
  }
  if (isDialogNode(normalized, templateMap)) {
    normalized.turns = normalizeDialogTurns(normalized);
    if (!normalized.turns.length) delete normalized.turns;
    if (normalized.dialogSpeakerRatio != null) normalized.dialogSpeakerRatio = normalizeDialogSpeakerRatio(normalized.dialogSpeakerRatio);
  } else {
    delete normalized.turns;
    delete normalized.dialogSpeakerRatio;
  }
  if (isChoiceNode(normalized, templateMap)) {
    normalized.choiceRevealMode = normalizeChoiceRevealMode(normalized.choiceRevealMode || normalized.revealMode);
  } else {
    delete normalized.choiceRevealMode;
  }
  delete normalized.revealMode;
  normalized.choiceOptions = normalizeChoiceOptions(normalized);
  normalized.choiceTimer = normalizeChoiceTimer(normalized.choiceTimer);
  if (!normalized.choiceTimer.enabled && !normalized.choiceTimer.fallbackLinkId) delete normalized.choiceTimer;
  if (normalized.choiceOptions.length) {
    // Mirror option labels into the legacy choices[] field so existing runtime paths and
    // story/preview UI that read `node.choices` see the same list as `choiceOptions`.
    normalized.choices = normalized.choiceOptions.map((opt) => opt.label);
  } else {
    delete normalized.choiceOptions;
  }
  return normalized;
}

function normalizeChoiceRevealMode(value) {
  return value === "disabled" || value === "disableUnavailable" ? "disabled" : "hide";
}

function normalizeChoiceTimerSeconds(value) {
  const seconds = Number(value);
  return Number.isFinite(seconds) ? clamp(Math.round(seconds), 1, 3600) : 10;
}

function normalizeChoiceTimer(value) {
  const source = value && typeof value === "object" && !Array.isArray(value) ? value : {};
  return {
    enabled: Boolean(source.enabled),
    seconds: normalizeChoiceTimerSeconds(source.seconds),
    fallbackLinkId: normalizeOptionalString(source.fallbackLinkId || source.linkId).trim()
  };
}

function normalizeFrameLayout(value) {
  return value === "stack" ? "stack" : "free";
}

function normalizeDialogTurns(node) {
  const raw = Array.isArray(node?.turns) ? node.turns : null;
  if (raw) {
    // Keep empty turns: they are work-in-progress rows the writer just added.
    // Autosave normalizes the live project, so dropping them here silently
    // deleted turns while the user was still filling them in. Play already
    // filters empty turns at runtime (getRuntimeDialogTurns).
    return raw
      .map((turn) => {
        if (!turn || typeof turn !== "object" || Array.isArray(turn)) return null;
        const speaker = normalizeOptionalString(turn.speaker || turn.who || turn.name).trim();
        const line = normalizeOptionalString(turn.line || turn.body || turn.text).trim();
        return { speaker, line };
      })
      .filter(Boolean);
  }
  return [];
}

function normalizeChoiceOptions(node) {
  const raw = Array.isArray(node?.choiceOptions) ? node.choiceOptions : null;
  const labels = Array.isArray(node?.choices) ? node.choices : [];
  if (raw && raw.length) {
    const used = new Set();
    return raw
      .map((opt, index) => {
        if (!opt || typeof opt !== "object" || Array.isArray(opt)) return null;
        // Keep options with an empty label: autosave normalizes the live
        // project, and dropping them here deleted an option (plus its
        // requires/effects) while the user was mid-edit on the label.
        const label = normalizeOptionalString(opt.label || opt.text || labels[index]).trim();
        let id = normalizeOptionalString(opt.id).trim();
        if (!id || used.has(id)) id = generateChoiceOptionId(used, index);
        used.add(id);
        const requires = normalizeOptionalString(opt.requires || opt.requirement || opt.gate).trim();
        const requiresMode = normalizeStoredConditionGroupMode(opt.requiresMode || opt.requirementsMode || opt.conditionMode);
        const effects = normalizeNodeEffects(opt.effects || opt.effect);
        return { id, label, requires, requiresMode, effects };
      })
      .filter(Boolean);
  }
  // Derive from legacy choices[] so per-option requires/effects can attach later without breaking existing links.
  if (!labels.length) return [];
  const used = new Set();
  return labels.map((label, index) => {
    const id = generateChoiceOptionId(used, index);
    used.add(id);
    return { id, label: String(label).trim(), requires: "", requiresMode: "all", effects: [] };
  });
}

function generateChoiceOptionId(used, index = null) {
  if (Number.isInteger(index) && index >= 0) {
    return makeUniqueChoiceOptionId(`opt_${index + 1}`, used);
  }
  for (let i = 0; i < 999; i += 1) {
    const id = `opt_${Math.random().toString(36).slice(2, 8)}`;
    if (!used.has(id)) return id;
  }
  return `opt_${Date.now().toString(36)}`;
}

function makeUniqueChoiceOptionId(base, used) {
  let candidate = base;
  let suffix = 2;
  while (used.has(candidate)) {
    candidate = `${base}_${suffix}`;
    suffix += 1;
  }
  return candidate;
}

function normalizeNodeStateLogic(value) {
  const source = value && typeof value === "object" && !Array.isArray(value) ? value : {};
  return {
    requirements: normalizeOptionalString(source.requirements || source.requirement || source.gate).trim(),
    requirementsMode: normalizeStoredConditionGroupMode(source.requirementsMode || source.requirementMode || source.conditionMode),
    effects: normalizeNodeEffects(source.effects || source.effect)
  };
}

function normalizeNodeEffects(value) {
  if (!Array.isArray(value)) return [];
  return value
    .map((effect) => {
      if (!effect || typeof effect !== "object" || Array.isArray(effect)) return null;
      if (effect.op === "ifElse" || (effect.condition && effect.thenEffect && effect.elseEffect)) {
        const thenEffect = normalizeNodeEffectBranch(effect.thenEffect);
        const elseEffect = normalizeNodeEffectBranch(effect.elseEffect);
        const condition = normalizeOptionalString(effect.condition).trim();
        if (!condition || !thenEffect || !elseEffect) return null;
        return {
          trigger: normalizePlaybookActionTrigger(effect.trigger || "onVisit"),
          op: "ifElse",
          condition,
          thenEffect,
          elseEffect
        };
      }
      return {
        trigger: normalizePlaybookActionTrigger(effect.trigger || "onVisit"),
        op: normalizePlaybookActionOperation(effect.op || "set"),
        key: normalizeOptionalString(effect.key || effect.variable || effect.name).trim(),
        value: normalizeOptionalString(effect.value),
        valueMode: effect.valueMode === "variable" ? "variable" : "literal"
      };
    })
    .filter((effect) => effect && (effect.op === "ifElse" || effect.key || effect.op === "clear"));
}

function normalizeNodeEffectBranch(effect) {
  if (!effect || typeof effect !== "object" || Array.isArray(effect)) return null;
  const normalized = {
    op: normalizePlaybookActionOperation(effect.op || "set"),
    key: normalizeOptionalString(effect.key || effect.variable || effect.name).trim(),
    value: normalizeOptionalString(effect.value),
    valueMode: effect.valueMode === "variable" ? "variable" : "literal"
  };
  return normalized.key || normalized.op === "clear" ? normalized : null;
}

function normalizeNodeRouting(value) {
  const source = value && typeof value === "object" && !Array.isArray(value) ? value : {};
  const legacyTarget = typeof value === "string" ? value : "";
  const mode = ["continue", "end", "goTo"].includes(source.mode) ? source.mode : (source.target || legacyTarget ? "goTo" : "continue");
  return {
    mode,
    target: normalizeOptionalString(source.target || source.title || legacyTarget).trim()
  };
}

function normalizeNodePorts(value, node) {
  const frame = isFrameNode(node);
  return {
    input: normalizePort(value?.input, frame ? "left" : "top"),
    output: normalizePort(value?.output, frame ? "right" : "bottom")
  };
}

function normalizePort(value, defaultSide) {
  const side = ["top", "right", "bottom", "left"].includes(value?.side) ? value.side : defaultSide;
  const t = Number(value?.t);
  return { side, t: Number.isFinite(t) ? clamp(t, 0, 1) : 0.5 };
}

function normalizeNodeCustomFields(customFields) {
  if (!customFields || typeof customFields !== "object" || Array.isArray(customFields)) return {};
  const normalized = {};
  Object.entries(customFields).forEach(([key, value]) => {
    normalized[String(key)] = value == null ? "" : String(value);
  });
  return normalized;
}

function migrateDirectCustomFields(node) {
  if (!node.customFields || typeof node.customFields !== "object" || Array.isArray(node.customFields)) return;
  Object.keys(node.customFields).forEach((key) => {
    if (!isDirectNodeField(key)) return;
    if (key === "choices") {
      if (!node.choices?.length) node.choices = parseChoiceLines(node.customFields[key]);
    } else if (node[key] == null || node[key] === "") {
      node[key] = node.customFields[key];
    }
    delete node.customFields[key];
  });
}

function ensureCustomFieldDefaults(node) {
  const fields = getNodeMeta(node.type).fields || [];
  if (!fields.length) return;
  const hasCustomField = fields.some((field) => !isDirectNodeField(field.key));
  if (hasCustomField && (!node.customFields || typeof node.customFields !== "object" || Array.isArray(node.customFields))) node.customFields = {};
  fields.forEach((field) => {
    if (field.key === "choices") {
      node.choices = parseChoiceLines(node.choices);
    } else if (isDirectNodeField(field.key)) {
      if (node[field.key] == null) node[field.key] = "";
    } else if (node.customFields && node.customFields[field.key] == null) {
      node.customFields[field.key] = "";
    }
  });
}

function getNodeCustomFieldEntries(node) {
  return (getNodeMeta(node?.type).fields || []).map((field) => ({
    key: field.key,
    label: field.label,
    value: getNodeCustomFieldValue(node, field.key)
  }));
}

function ensureEventDefaults(node, eventColumns = null) {
  const columns = eventColumns || getProjectEventSheetColumns();
  columns.forEach((column) => {
    if (column.key === "characterEncountered") return;
    if (!column.readonly && node[column.key] == null) node[column.key] = getNodeEventValue(node, column.key);
  });
  getNodeCustomFieldEntries(node).forEach((field) => {
    if (isDirectNodeField(field.key)) return;
    if (!node.customFields || typeof node.customFields !== "object" || Array.isArray(node.customFields)) node.customFields = {};
    if (node.customFields[field.key] == null) node.customFields[field.key] = "";
  });
}

function setPreviewPanelOpen(open) {
  if (!dom.root) return;
  if (open) dom.root.setAttribute("data-play-panel", "open");
  else dom.root.removeAttribute("data-play-panel");
  if (!open) {
    state.playFloating = false;
    setFloatingWindowPinned("play", false);
  }
  applyPlayFloatState();
  requestAnimationFrame(() => {
    renderTransform();
    scheduleCanvasViewportRender();
  });
}

function applyPlayFloatState() {
  const floating = Boolean(state.playFloating) && Boolean(dom.root?.hasAttribute("data-play-panel"));
  if (dom.root) dom.root.setAttribute("data-play-floating", floating ? "true" : "false");
  if (dom.playDialog) dom.playDialog.classList.toggle("floating", floating);
  if (floating) applyFloatingWindowGeometry("play");
  else clearFloatingWindowStyles("play");
  const button = dom.playDialog?.querySelector("[data-action='toggle-play-float']");
  if (button) {
    button.setAttribute("aria-pressed", String(floating));
    const label = t(floating ? "Dock preview to the right" : "Float preview to center");
    button.title = label;
    button.setAttribute("aria-label", label);
  }
  const pinButton = dom.playDialog?.querySelector("[data-floating-window-pin='play']");
  if (pinButton) pinButton.hidden = !floating;
  renderFloatingWindowPinState("play");
}

function togglePlayFloat() {
  if (!dom.root?.hasAttribute("data-play-panel")) return;
  state.playFloating = !state.playFloating;
  if (!state.playFloating) setFloatingWindowPinned("play", false);
  applyPlayFloatState();
}

function openPreviewPanel() {
  if (!dom.playDialog) return;
  setPreviewPanelOpen(true);
  if (dom.playDialog.open) return;
  try {
    if (typeof dom.playDialog.show === "function") dom.playDialog.show();
    else dom.playDialog.setAttribute("open", "");
  } catch (error) {
    dom.playDialog.setAttribute("open", "");
  }
}

function handlePreviewPanelClose() {
  resetPreviewSessionState();
  setPreviewPanelOpen(false);
}

function focusCanvasOnPreviewNode(node) {
  if (!node || !dom.viewport) return;
  requestAnimationFrame(() => {
    const current = getNode(node.id);
    if (!current || state.playNodeId !== current.id) return;
    state.activeFileId = "adventure";
    state.selectedNodeId = current.id;
    state.selectedNodeIds = [];
    state.selectedLinkId = null;
    state.characterFocusId = null;
    state.panel = "node";
    // Focus the node in the inspector, but honor a right panel the reader deliberately collapsed
    // during playback instead of forcing it open again on every step.
    if (state.floatingInspectorPanel && !isFloatingWindowPinned("inspector")) closeFloatingInspector({ restoreFocus: false });
    renderShellState();
    renderWorkspaceFile();
    renderInspector();
    centerCanvasOnNode(current, state.view.scale || DEFAULT_CANVAS_ZOOM, { immediate: true });
  });
}

function openPreview() {
  const entries = getPreviewEntryNodes();
  if (entries.length > 1) {
    openPreviewEntrySelector(entries);
    return;
  }

  const previewPath = getPreviewPath();
  const entry = getPreviewStartNode(previewPath);
  if (!entry) {
    setStatus("No nodes to play.");
    return;
  }
  startPreviewSession(entry);
}

function getPreviewEntryNodes() {
  return state.project.nodes
    .filter((node) => node.type === "Entry" && !isFrameNode(node))
    .slice()
    .sort(compareRawNodePosition);
}

function openPreviewEntrySelector(entries = getPreviewEntryNodes()) {
  const liveEntries = [];
  const seen = new Set();
  (Array.isArray(entries) ? entries : []).forEach((entry) => {
    const current = getNode(entry?.id);
    if (!current || current.type !== "Entry" || isFrameNode(current) || seen.has(current.id)) return;
    seen.add(current.id);
    liveEntries.push(current);
  });
  resetPreviewSessionState();
  state.project.variables = normalizeVariablesObject(state.project.variables);
  openPreviewPanel();
  dom.playTitle.textContent = t("Choose a system to play");
  dom.playBody.innerHTML = `
    <section class="play-entry-selector" aria-label="${escapeAttr(t("System entries"))}">
      <span class="play-entry-selector-kicker">${escapeHtml(t("System entries"))}</span>
      <h3>${escapeHtml(t("Choose a system to play"))}</h3>
      <p>${escapeHtml(t("This canvas has {count} Entry nodes. Choose the system you want to play.", { count: liveEntries.length }))}</p>
    </section>
  `;
  dom.playActions.innerHTML = liveEntries.map((entry, index) => renderPreviewEntryOption(entry, index)).join("");
  const scroller = getPreviewScroller();
  if (scroller) scroller.scrollTop = 0;
}

function refreshOpenPreviewEntrySelector() {
  if (!dom.playDialog?.open || !dom.playBody?.querySelector(".play-entry-selector")) return;
  openPreviewEntrySelector(getPreviewEntryNodes());
}

function renderPreviewEntryOption(entry, index = 0) {
  const title = getNodeDisplayTitle(entry, t("Entry"));
  const snippet = formatNodeSnippet(entry);
  const detail = snippet === "No text"
    ? `${getNodeTypeLabel(entry.type)} ${getNodeDisplayId(entry)}`
    : `${getNodeTypeLabel(entry.type)} ${getNodeDisplayId(entry)} · ${snippet}`;
  return `
    <button class="play-action play-choice-action play-entry-option" type="button" data-action="play-select-entry" data-node-id="${escapeAttr(entry.id)}">
      <span class="play-entry-option-number" aria-hidden="true">${String(index + 1).padStart(2, "0")}</span>
      <span class="play-entry-option-copy">
        <strong>${escapeHtml(title)}</strong>
        <small>${escapeHtml(detail)}</small>
      </span>
      <span class="play-entry-option-arrow" aria-hidden="true">→</span>
    </button>
  `;
}

function startPreviewSession(entry) {
  if (!entry) {
    setStatus("No nodes to play.");
    return;
  }
  resetPreviewSessionState();
  state.project.variables = normalizeVariablesObject(state.project.variables);
  state.playVariables = clonePreviewVariables(state.project.variables);
  state.playPath = [entry.id];
  state.playStepIndex = 0;
  state.playSteps = [];
  state.playNodeId = entry.id;
  state.playTurnIndex = 0;
  state.playManualActionRunIds = new Set();
  state.playVisitedNodeIds = new Set();
  state.playVisitRecords = [];
  state.activeFileId = "adventure";
  state.selectedNodeId = entry.id;
  state.selectedNodeIds = [];
  state.selectedLinkId = null;
  state.panel = "node";
  state.sidebar.rightCollapsed = false;
  if (state.floatingInspectorPanel && !isFloatingWindowPinned("inspector")) closeFloatingInspector({ restoreFocus: false });
  openPreviewPanel();
  renderShellState();
  renderWorkspaceFile();
  renderInspector();
  renderPreviewNode(entry.id);
}

function resetPreviewSessionState() {
  capturePlaySessionSnapshot();
  if (state.playRefreshTimer) {
    window.clearTimeout(state.playRefreshTimer);
    state.playRefreshTimer = null;
  }
  clearPlayChoiceTimer();
  state.playNodeId = null;
  state.playPath = [];
  state.playStepIndex = 0;
  state.playSteps = [];
  state.playTrimmedCount = 0;
  state.playTurnIndex = 0;
  state.playVariables = null;
  state.playManualActionRunIds = new Set();
  state.playVisitedNodeIds = new Set();
  state.playVisitRecords = [];
}

function getPlayHistoryLimit() {
  return normalizePlayHistoryLimit(state.project?.playHistoryLimit);
}

function capturePlaySessionSnapshot() {
  if (!Array.isArray(state.playPath) || !state.playPath.length) return null;
  const steps = state.playPath.map((nodeId, index) => {
    const node = getNode(nodeId);
    const snapshot = Array.isArray(state.playSteps) ? state.playSteps[index] : null;
    return {
      nodeId,
      displayId: node ? getNodeDisplayId(node) : "",
      type: node?.type || "",
      title: node?.title || "",
      body: node ? displayBody(node) : "",
      variables: snapshot?.variables ? clonePreviewVariables(snapshot.variables) : null,
      operations: clonePreviewVisitRecords(snapshot?.visitRecords || [])
        .find((record) => record.nodeId === nodeId)?.operations || []
    };
  });
  state.lastPlaySession = {
    projectTitle: state.project?.title || "Narrative Canvas",
    capturedAt: new Date().toISOString(),
    trimmedCount: Number(state.playTrimmedCount || 0),
    steps
  };
  return state.lastPlaySession;
}

function trimPreviewHistory() {
  const limit = getPlayHistoryLimit();
  const maximum = limit;
  const excess = Math.max(0, state.playPath.length - maximum);
  if (!excess) return false;
  state.playPath = state.playPath.slice(excess);
  state.playSteps = Array.isArray(state.playSteps) ? state.playSteps.slice(excess) : [];
  state.playVisitRecords = Array.isArray(state.playVisitRecords) ? state.playVisitRecords.slice(excess) : [];
  state.playStepIndex = Math.max(0, state.playStepIndex - excess);
  state.playTrimmedCount = Number(state.playTrimmedCount || 0) + excess;
  return true;
}

function scheduleOpenPreviewRefresh() {
  if (!state.playNodeId || !dom.playDialog?.open || state.playRefreshTimer) return;
  // Debounce with a timer rather than requestAnimationFrame: rAF can be starved under
  // headless/virtual-time test runs, so the open play preview would intermittently fail to
  // refresh after a focused-node edit. A short timeout coalesces the same way and fires reliably.
  state.playRefreshTimer = window.setTimeout(() => {
    state.playRefreshTimer = null;
    if (!state.playNodeId || !dom.playDialog?.open) return;
    renderPreviewNode(state.playNodeId, { skipVisit: true, skipCanvasFocus: true });
  }, 33);
}

function clonePreviewVariables(variables) {
  return JSON.parse(JSON.stringify(normalizeVariablesObject(variables)));
}

function hasPreviewVariables() {
  return Boolean(state.playVariables && typeof state.playVariables === "object" && !Array.isArray(state.playVariables));
}

function getRuntimeVariableSource() {
  return hasPreviewVariables() ? state.playVariables : state.project.variables;
}

function getPlayRuntimeVariables() {
  if (!hasPreviewVariables()) state.playVariables = clonePreviewVariables(state.project.variables);
  return state.playVariables;
}

function getPreviewCurrentPathIndex() {
  const index = Number.isInteger(state.playStepIndex) ? state.playStepIndex : -1;
  if (index >= 0 && state.playPath[index] === state.playNodeId) return index;
  const fallback = state.playPath.lastIndexOf(state.playNodeId);
  state.playStepIndex = fallback >= 0 ? fallback : Math.max(state.playPath.length - 1, 0);
  return fallback;
}

function clonePreviewVisitRecords(records = []) {
  return (Array.isArray(records) ? records : []).map((record) => ({
    nodeId: record.nodeId || "",
    title: record.title || "",
    displayId: record.displayId || "",
    operations: Array.isArray(record.operations) ? [...record.operations] : []
  }));
}

function capturePreviewStep(nodeId = state.playNodeId) {
  if (!nodeId) return;
  let index = getPreviewCurrentPathIndex();
  if (index < 0) {
    state.playPath.push(nodeId);
    index = state.playPath.length - 1;
    state.playStepIndex = index;
  }
  if (!Array.isArray(state.playSteps)) state.playSteps = [];
  state.playSteps[index] = {
    nodeId,
    variables: clonePreviewVariables(getPlayRuntimeVariables()),
    manualActionRunIds: state.playManualActionRunIds instanceof Set ? [...state.playManualActionRunIds] : [],
    visitedNodeIds: state.playVisitedNodeIds instanceof Set ? [...state.playVisitedNodeIds] : [],
    visitRecords: clonePreviewVisitRecords(state.playVisitRecords)
  };
}

function restorePreviewStep(index) {
  if (!Array.isArray(state.playSteps) || index < 0 || index >= state.playSteps.length) return false;
  const step = state.playSteps[index];
  if (!step?.nodeId) return false;
  state.playSteps = state.playSteps.slice(0, index + 1);
  state.playPath = state.playPath.slice(0, index + 1);
  state.playStepIndex = index;
  state.playNodeId = step.nodeId;
  state.playTurnIndex = 0;
  state.playVariables = clonePreviewVariables(step.variables || {});
  state.playManualActionRunIds = new Set(step.manualActionRunIds || []);
  state.playVisitedNodeIds = new Set(step.visitedNodeIds || []);
  state.playVisitRecords = clonePreviewVisitRecords(step.visitRecords || []);
  return true;
}

function isPreviewVisitTrackingEnabled() {
  const rule = getRunnerRules().visitTracking;
  return Boolean(isDebugModeRuleEnabled() && rule?.enabled && rule.value);
}

function ensurePreviewVisitRecord(node) {
  if (!node || !isPreviewVisitTrackingEnabled()) return null;
  if (!Array.isArray(state.playVisitRecords)) state.playVisitRecords = [];
  let index = getPreviewCurrentPathIndex();
  if (index < 0) index = Math.max(state.playVisitRecords.length, 0);
  const existing = state.playVisitRecords[index];
  if (existing?.nodeId === node.id) return existing;
  state.playVisitRecords = state.playVisitRecords.slice(0, index);
  const record = {
    nodeId: node.id,
    title: node.title || getNodeTypeLabel(node.type),
    displayId: getNodeDisplayId(node),
    operations: []
  };
  state.playVisitRecords[index] = record;
  return record;
}

function getPreviewVisitRecordForNode(node) {
  if (!node || !isPreviewVisitTrackingEnabled()) return null;
  if (!Array.isArray(state.playVisitRecords)) state.playVisitRecords = [];
  const index = getPreviewCurrentPathIndex();
  const record = index >= 0 ? state.playVisitRecords[index] : null;
  if (record?.nodeId === node.id) return record;
  for (let i = state.playVisitRecords.length - 1; i >= 0; i -= 1) {
    if (state.playVisitRecords[i]?.nodeId === node.id) return state.playVisitRecords[i];
  }
  return ensurePreviewVisitRecord(node);
}

function recordPreviewOperation(node, text) {
  const label = normalizeOptionalString(text).trim();
  if (!label) return;
  const record = getPreviewVisitRecordForNode(node);
  if (!record) return;
  record.operations.push(label);
}

function advancePreview(nodeId, opts = {}) {
  clearPlayChoiceTimer();
  const currentIndex = getPreviewCurrentPathIndex();
  const currentNode = getNode(state.playNodeId);
  if (currentNode) {
    applyNodeEffectsForNode(currentNode, "onChoose", "Node choose");
    applyPlaybookActionsForNode(currentNode, "onChoose", "Node choose");
    // Per-option effects: when the user picked a specific choice option, run that option's effects
    // (these are independent from the node-level onChoose effects above).
    const optionId = opts && opts.optionId ? String(opts.optionId) : "";
    if (optionId && Array.isArray(currentNode.choiceOptions)) {
      const option = currentNode.choiceOptions.find((o) => o.id === optionId);
      const entry = getRuntimeChoiceEntries(currentNode, getNodeRuntimeScript(currentNode)).find((item) => item.optionId === optionId);
      const optionLabel = entry?.label || option?.label || optionId;
      recordPreviewOperation(currentNode, `${t("Selected choice")}: ${optionLabel}`);
      if (option && Array.isArray(option.effects)) {
        option.effects.forEach((effect) => applyNodeEffect(effect, currentNode, "Choice effect"));
      }
    }
  }
  const nextIndex = currentIndex >= 0 ? currentIndex + 1 : state.playPath.length;
  state.playPath = state.playPath.slice(0, nextIndex);
  state.playSteps = Array.isArray(state.playSteps) ? state.playSteps.slice(0, nextIndex) : [];
  state.playPath[nextIndex] = nodeId;
  state.playStepIndex = nextIndex;
  state.playNodeId = nodeId;
  state.playTurnIndex = 0;
  renderPreviewNode(nodeId);
}

function advanceDialogTurn(delta) {
  const node = getNode(state.playNodeId);
  const turns = getRuntimeDialogTurns(node);
  if (!turns.length) return;
  state.playTurnIndex = clamp((state.playTurnIndex || 0) + delta, 0, turns.length - 1);
  renderPreviewNode(node.id, { skipVisit: true });
}

function previousPreview() {
  const index = getPreviewCurrentPathIndex();
  if (index <= 0) return;
  if (!restorePreviewStep(index - 1)) return;
  renderPreviewNode(state.playNodeId, { skipVisit: true });
}

function jumpToPreviewStep(stepIndexValue) {
  const stepIndex = Number(stepIndexValue);
  const currentIndex = getPreviewCurrentPathIndex();
  if (!Number.isInteger(stepIndex) || stepIndex < 0 || stepIndex >= currentIndex) return;
  if (!restorePreviewStep(stepIndex)) return;
  renderPreviewNode(state.playNodeId, { skipVisit: true });
  scrollPreviewToCurrentCard();
  setStatus(t("Returned to card {number}.", { number: stepIndex + 1 }));
}

function executePreviewManualAction(nodeId, actionIdValue) {
  const node = getNode(nodeId);
  if (!node) return;
  const actionId = normalizeOptionalString(actionIdValue).trim();
  if (!actionId) return;
  const actions = getMatchingPlaybookActions(node, "manual").filter(isExecutablePlaybookAction);
  const action = actions.find((item) => item.id === actionId);
  if (!action) return;
  const applied = applyPlaybookActionWithPreviewLog(action, node, "Manual action");
  if (applied) {
    if (!(state.playManualActionRunIds instanceof Set)) state.playManualActionRunIds = new Set();
    state.playManualActionRunIds.add(action.id);
    capturePreviewStep(node.id);
  }
  renderPreviewNode(node.id, { skipVisit: true });
}

function renderPreviewHistoryCards() {
  const index = getPreviewCurrentPathIndex();
  if (index <= 0) return "";
  const historyLimit = getPlayHistoryLimit();
  const start = Math.max(0, index - Math.max(0, historyLimit - 1));
  const cards = [];
  for (let i = start; i < index; i += 1) {
    const node = getNode(state.playPath[i]);
    if (!node) continue;
    const step = Array.isArray(state.playSteps) ? state.playSteps[i] : null;
    cards.push(renderPreviewHistoryCard(node, step, i));
  }
  if (!cards.length) return "";
  const trimmedNotice = start > 0 || state.playTrimmedCount > 0
    ? `<div class="play-history-trimmed">${escapeHtml(t("Showing the last {count} cards.", { count: historyLimit }))}</div>`
    : "";
  return `<section class="play-history" aria-label="${escapeAttr(t("Recent cards"))}">${trimmedNotice}${cards.join("")}</section>`;
}

// Renders the limited Markdown the node editor's toolbar produces into safe HTML for
// the Play preview (the reader-facing view). HTML is escaped first, then a small,
// fixed set of block and inline markers is converted — no raw HTML passes through.
function renderNarrativeMarkdown(text) {
  const source = String(text ?? "");
  // Inline formatting runs on already-escaped text, so Markdown markers survive but
  // no raw HTML gets through. Links are limited to safe schemes.
  const inline = (line) => escapeHtml(line)
    .replace(/\[([^\]]+)\]\(([^)\s]+)\)/g, (match, label, url) =>
      `<a href="${/^(https?:|mailto:|#)/i.test(url) ? url : "#"}" target="_blank" rel="noopener noreferrer">${label}</a>`)
    .replace(/`([^`]+)`/g, "<code>$1</code>")
    .replace(/\*\*([^*]+)\*\*/g, "<strong>$1</strong>")
    .replace(/(^|[^*])\*([^*]+)\*/g, "$1<em>$2</em>")
    .replace(/~~([^~]+)~~/g, "<del>$1</del>")
    .replace(/==([^=]+)==/g, "<mark>$1</mark>")
    .replace(/\{color:(#[0-9a-f]{6})\}(.+?)\{\/color\}/gi, '<span style="color:$1">$2</span>')
    .replace(/\{highlight:(#[0-9a-f]{6})\}(.+?)\{\/highlight\}/gi, '<mark style="background-color:$1">$2</mark>');
  const lines = source.split("\n");
  const out = [];
  let listItems = null;
  let orderedItems = null;
  let codeLines = null;
  const flushList = () => { if (listItems) { out.push(`<ul>${listItems.join("")}</ul>`); listItems = null; } };
  const flushOrdered = () => { if (orderedItems) { out.push(`<ol>${orderedItems.join("")}</ol>`); orderedItems = null; } };
  const flushBlocks = () => { flushList(); flushOrdered(); };
  for (const rawLine of lines) {
    const line = rawLine.replace(/\r$/, "");
    const fence = /^\s*```/.test(line);
    if (codeLines) {
      if (fence) { out.push(`<pre><code>${codeLines.map((code) => escapeHtml(code)).join("\n")}</code></pre>`); codeLines = null; }
      else codeLines.push(line);
      continue;
    }
    if (fence) { flushBlocks(); codeLines = []; continue; }
    const taskMatch = line.match(/^\s*-\s+\[([ xX])\]\s+(.*)$/);
    if (taskMatch) {
      flushOrdered();
      const checked = taskMatch[1].toLowerCase() === "x";
      (listItems ||= []).push(`<li class="nc-md-task" data-nc-task="${checked ? "true" : "false"}"><input type="checkbox" disabled${checked ? " checked" : ""}>${inline(taskMatch[2])}</li>`);
      continue;
    }
    const listMatch = line.match(/^\s*-\s+(.*)$/);
    if (listMatch) { flushOrdered(); (listItems ||= []).push(`<li>${inline(listMatch[1])}</li>`); continue; }
    const orderedMatch = line.match(/^\s*\d+\.\s+(.*)$/);
    if (orderedMatch) { flushList(); (orderedItems ||= []).push(`<li>${inline(orderedMatch[1])}</li>`); continue; }
    flushBlocks();
    if (/^\s*(-{3,}|\*{3,}|_{3,})\s*$/.test(line)) { out.push("<hr>"); continue; }
    const h3 = line.match(/^###\s+(.*)$/);
    const h2 = line.match(/^##\s+(.*)$/);
    const h1 = line.match(/^#\s+(.*)$/);
    const quote = line.match(/^>\s+(.*)$/);
    if (h3) out.push(`<h3>${inline(h3[1])}</h3>`);
    else if (h2) out.push(`<h2>${inline(h2[1])}</h2>`);
    else if (h1) out.push(`<h1>${inline(h1[1])}</h1>`);
    else if (quote) out.push(`<blockquote>${inline(quote[1])}</blockquote>`);
    else if (line.trim() === "") out.push("<br>");
    else out.push(`<p>${inline(line)}</p>`);
  }
  if (codeLines) out.push(`<pre><code>${codeLines.map((code) => escapeHtml(code)).join("\n")}</code></pre>`);
  flushBlocks();
  return out.join("");
}

function normalizeNarrativeMarkupColor(value, fallback = "") {
  const match = normalizeOptionalString(value).trim().match(/^(#[0-9a-f]{6})(?:[0-9a-f]{2})?$/i);
  return match ? match[1].toLowerCase() : fallback;
}

function safeNarrativeHref(value) {
  const href = normalizeOptionalString(value).trim();
  return /^(https?:|mailto:|#)/i.test(href) ? href : "#";
}

function getNarrativeStyleColor(node, property) {
  const style = normalizeOptionalString(node?.getAttribute?.("style"));
  const pattern = property === "background-color"
    ? /(?:^|;)\s*background-color\s*:\s*(#[0-9a-f]{6})(?:\s*;|$)/i
    : /(?:^|;)\s*color\s*:\s*(#[0-9a-f]{6})(?:\s*;|$)/i;
  return style.match(pattern)?.[1] || "";
}

function sanitizeNarrativeHtml(source) {
  const template = document.createElement("template");
  template.innerHTML = String(source ?? "");
  const renderNode = (node, parentTag = "") => {
    if (node.nodeType === 3) return escapeHtml(node.nodeValue || "");
    if (node.nodeType !== 1) return "";
    const tag = node.tagName.toLowerCase();
    const children = [...node.childNodes].map((child) => renderNode(child, tag)).join("");
    if (tag === "script" || tag === "style" || tag === "iframe" || tag === "object") return "";
    if (tag === "br" || tag === "hr") return `<${tag}>`;
    if (tag === "input" && node.getAttribute("type") === "checkbox") {
      return `<input type="checkbox" disabled${node.hasAttribute("checked") ? " checked" : ""}>`;
    }
    if (tag === "b" || tag === "strong") return `<strong>${children}</strong>`;
    if (tag === "i" || tag === "em") return `<em>${children}</em>`;
    if (tag === "s" || tag === "strike" || tag === "del") return `<del>${children}</del>`;
    if (tag === "code") return `<code>${children}</code>`;
    if (tag === "pre") return `<pre>${children}</pre>`;
    if (tag === "a") {
      const href = safeNarrativeHref(node.getAttribute("href"));
      return `<a href="${escapeAttr(href)}" target="_blank" rel="noopener noreferrer">${children}</a>`;
    }
    if (tag === "span") {
      const color = normalizeNarrativeMarkupColor(
        node.dataset.ncColor || getNarrativeStyleColor(node, "color") || node.getAttribute("color")
      );
      return color ? `<span style="color:${color}">${children}</span>` : children;
    }
    if (tag === "mark") {
      const color = normalizeNarrativeMarkupColor(
        node.dataset.ncHighlight || getNarrativeStyleColor(node, "background-color") || node.getAttribute("color")
      );
      return `<mark${color ? ` style="background-color:${color}"` : ""}>${children}</mark>`;
    }
    if (["h1", "h2", "h3", "blockquote", "ul", "ol", "p"].includes(tag)) {
      return `<${tag}>${children}</${tag}>`;
    }
    if (tag === "li") {
      const taskValue = node.dataset.ncTask;
      const taskAttr = taskValue === "true" || taskValue === "false" ? ` data-nc-task="${taskValue}" class="nc-md-task"` : "";
      return `<li${taskAttr}>${children}</li>`;
    }
    if (tag === "div") return `<p>${children}</p>`;
    return children;
  };
  return [...template.content.childNodes].map((node) => renderNode(node)).join("");
}

function renderNarrativeHtml(text) {
  return sanitizeNarrativeHtml(text);
}

function renderNarrativeUnity(text) {
  let source = String(text ?? "");
  source = source
    .replace(/<size=160%>\s*<b>([\s\S]*?)<\/b>\s*<\/size>/gi, "<h1>$1</h1>")
    .replace(/<size=140%>\s*<b>([\s\S]*?)<\/b>\s*<\/size>/gi, "<h2>$1</h2>")
    .replace(/<size=120%>\s*<b>([\s\S]*?)<\/b>\s*<\/size>/gi, "<h3>$1</h3>")
    .replace(/<indent=5%>\s*<i>[“\"]?([\s\S]*?)[”\"]?<\/i>\s*<\/indent>/gi, "<blockquote>$1</blockquote>")
    .replace(/<indent=5%>\s*•\s*([\s\S]*?)<\/indent>/gi, "<ul><li>$1</li></ul>")
    .replace(/<indent=5%>\s*\d+\.\s*([\s\S]*?)<\/indent>/gi, "<ol><li>$1</li></ol>")
    .replace(/<indent=5%>\s*☐\s*([\s\S]*?)<\/indent>/gi, '<ul><li data-nc-task="false">$1</li></ul>')
    .replace(/<style=["']NCCode["']>([\s\S]*?)<\/style>/gi, (match, content) =>
      content.includes("\n") ? `<pre><code>${content}</code></pre>` : `<code>${content}</code>`)
    .replace(/<color=([^>]+)>/gi, '<span data-nc-color="$1">')
    .replace(/<\/color>/gi, "</span>")
    .replace(/<mark=([^>]+)>/gi, '<mark data-nc-highlight="$1">')
    .replace(/<link=["']([^"']+)["']>/gi, '<a href="$1">')
    .replace(/<\/link>/gi, "</a>")
    .replace(/^─{4,}$/gm, "<hr>");
  return sanitizeNarrativeHtml(source);
}

function renderNarrativeBbcode(text) {
  let source = escapeHtml(String(text ?? ""));
  const replacePaired = (pattern, replacement) => {
    for (let pass = 0; pass < 8 && pattern.test(source); pass += 1) {
      pattern.lastIndex = 0;
      source = source.replace(pattern, replacement);
    }
    pattern.lastIndex = 0;
  };
  replacePaired(/\[font_size=32\]\[b\]([\s\S]*?)\[\/b\]\[\/font_size\]/gi, "<h1>$1</h1>");
  replacePaired(/\[font_size=26\]\[b\]([\s\S]*?)\[\/b\]\[\/font_size\]/gi, "<h2>$1</h2>");
  replacePaired(/\[font_size=21\]\[b\]([\s\S]*?)\[\/b\]\[\/font_size\]/gi, "<h3>$1</h3>");
  replacePaired(/\[quote\]([\s\S]*?)\[\/quote\]/gi, "<blockquote>$1</blockquote>");
  replacePaired(/\[code\]([\s\S]*?)\[\/code\]/gi, (match, content) =>
    content.includes("\n") ? `<pre><code>${content}</code></pre>` : `<code>${content}</code>`);
  replacePaired(/\[url=([^\]]+)\]([\s\S]*?)\[\/url\]/gi, '<a href="$1">$2</a>');
  replacePaired(/\[color=(#[0-9a-f]{6})\]([\s\S]*?)\[\/color\]/gi, '<span data-nc-color="$1">$2</span>');
  replacePaired(/\[bgcolor=(#[0-9a-f]{6})\]([\s\S]*?)\[\/bgcolor\]/gi, '<mark data-nc-highlight="$1">$2</mark>');
  replacePaired(/\[b\]([\s\S]*?)\[\/b\]/gi, "<strong>$1</strong>");
  replacePaired(/\[i\]([\s\S]*?)\[\/i\]/gi, "<em>$1</em>");
  replacePaired(/\[s\]([\s\S]*?)\[\/s\]/gi, "<del>$1</del>");
  replacePaired(/\[li\]([\s\S]*?)\[\/li\]/gi, "<li>$1</li>");
  replacePaired(/\[ul\]([\s\S]*?)\[\/ul\]/gi, "<ul>$1</ul>");
  replacePaired(/\[ol\]([\s\S]*?)\[\/ol\]/gi, "<ol>$1</ol>");
  source = source.replace(/^─{4,}$/gm, "<hr>");
  return sanitizeNarrativeHtml(source);
}

function parseUnrealTag(token) {
  const match = token.match(/^<([A-Za-z][\w]*)([^>]*)>$/);
  if (!match) return null;
  const attrs = {};
  match[2].replace(/([\w-]+)=["']([^"']*)["']/g, (whole, key, value) => {
    attrs[key.toLowerCase()] = value;
    return whole;
  });
  return { tag: match[1], attrs, children: [] };
}

function renderNarrativeUnreal(text) {
  const root = { tag: "root", attrs: {}, children: [] };
  const stack = [root];
  const source = String(text ?? "");
  let cursor = 0;
  const tokens = source.matchAll(/<[^>]*>/g);
  for (const match of tokens) {
    if (match.index > cursor) stack.at(-1).children.push({ text: source.slice(cursor, match.index) });
    const token = match[0];
    if (token === "</>") {
      if (stack.length > 1) stack.pop();
    } else {
      const entry = parseUnrealTag(token);
      if (entry) {
        stack.at(-1).children.push(entry);
        stack.push(entry);
      } else {
        stack.at(-1).children.push({ text: token });
      }
    }
    cursor = match.index + token.length;
  }
  if (cursor < source.length) stack.at(-1).children.push({ text: source.slice(cursor) });
  const renderEntry = (entry) => {
    if (Object.prototype.hasOwnProperty.call(entry, "text")) return escapeHtml(entry.text);
    const children = entry.children.map(renderEntry).join("");
    const tag = entry.tag.toLowerCase();
    if (tag === "root") return children;
    if (tag === "ncbold") return `<strong>${children}</strong>`;
    if (tag === "ncitalic") return `<em>${children}</em>`;
    if (tag === "ncstrike") return `<del>${children}</del>`;
    if (tag === "nccode") return `<code>${children}</code>`;
    if (tag === "nccodeblock") return `<pre><code>${children}</code></pre>`;
    if (tag === "nchighlight") {
      const color = normalizeNarrativeMarkupColor(entry.attrs.value);
      return `<mark${color ? ` style="background-color:${color}"` : ""}>${children}</mark>`;
    }
    if (tag === "nccolor") {
      const color = normalizeNarrativeMarkupColor(entry.attrs.value);
      return color ? `<span style="color:${color}">${children}</span>` : children;
    }
    if (tag === "nclink") return `<a href="${escapeAttr(safeNarrativeHref(entry.attrs.href))}">${children}</a>`;
    if (tag === "nch1" || tag === "nch2" || tag === "nch3") return `<h${tag.at(-1)}>${children}</h${tag.at(-1)}>`;
    if (tag === "ncquote") return `<blockquote>${children}</blockquote>`;
    if (tag === "ncitem") return `<li>${children}</li>`;
    if (tag === "nclist" || tag === "nctasklist") return `<ul>${children}</ul>`;
    if (tag === "ncorderedlist") return `<ol>${children}</ol>`;
    if (tag === "ncdivider") return "<hr>";
    return children;
  };
  return sanitizeNarrativeHtml(renderEntry(root));
}

function renderNarrativeRichText(text, format = getCurrentRichTextFormat()) {
  const normalized = normalizeRichTextFormat(format);
  if (normalized === "html") return renderNarrativeHtml(text);
  if (normalized === "unity") return renderNarrativeUnity(text);
  if (normalized === "bbcode") return renderNarrativeBbcode(text);
  if (normalized === "unreal") return renderNarrativeUnreal(text);
  return renderNarrativeMarkdown(text);
}

function getCanonicalNodeColor(node, kind) {
  const value = kind === "highlight"
    ? node.dataset?.ncHighlight || getNarrativeStyleColor(node, "background-color")
    : node.dataset?.ncColor || getNarrativeStyleColor(node, "color");
  return normalizeNarrativeMarkupColor(value);
}

function serializeNarrativeHtml(html, format) {
  const target = normalizeRichTextFormat(format);
  if (target === "html") return sanitizeNarrativeHtml(html);
  const template = document.createElement("template");
  template.innerHTML = sanitizeNarrativeHtml(html);
  const textValue = (node) => node.textContent || "";
  const children = (node, context = {}) => [...node.childNodes].map((child) => serializeNode(child, context)).join("");
  const serializeList = (node, ordered, context) => {
    const items = [...node.children].filter((child) => child.tagName?.toLowerCase() === "li");
    if (target === "markdown") {
      return items.map((item, index) => {
        const task = item.dataset.ncTask;
        const prefix = task != null ? `- [${task === "true" ? "x" : " "}] ` : ordered ? `${index + 1}. ` : "- ";
        return `${prefix}${children(item, context).replace(/^<input[^>]*>/, "")}`;
      }).join("\n");
    }
    if (target === "unity") {
      return items.map((item, index) => {
        const task = item.dataset.ncTask;
        const prefix = task != null ? (task === "true" ? "☑ " : "☐ ") : ordered ? `${index + 1}. ` : "• ";
        return `<indent=5%>${prefix}${children(item, context).replace(/^<input[^>]*>/, "")}</indent>`;
      }).join("\n");
    }
    if (target === "bbcode") {
      const tag = ordered ? "ol" : "ul";
      return `[${tag}]${items.map((item) => {
        const task = item.dataset.ncTask;
        const prefix = task != null ? (task === "true" ? "☑ " : "☐ ") : "";
        return `[li]${prefix}${children(item, context).replace(/^<input[^>]*>/, "")}[/li]`;
      }).join("")}[/${tag}]`;
    }
    const tag = ordered ? "NCOrderedList" : items.some((item) => item.dataset.ncTask != null) ? "NCTaskList" : "NCList";
    return `<${tag}>${items.map((item) => {
      const task = item.dataset.ncTask;
      const prefix = task != null ? (task === "true" ? "☑ " : "☐ ") : "";
      return `<NCItem>${prefix}${children(item, context).replace(/^<input[^>]*>/, "")}</>`;
    }).join("")}</>`;
  };
  const serializeNode = (node, context = {}) => {
    if (node.nodeType === 3) return node.nodeValue || "";
    if (node.nodeType !== 1) return "";
    const tag = node.tagName.toLowerCase();
    const inner = children(node, context);
    if (tag === "input") return "";
    if (tag === "br") return "\n";
    if (tag === "hr") return target === "markdown" ? "---" : target === "unreal" ? "<NCDivider></>" : "────────────────";
    if (tag === "p") return inner;
    if (tag === "h1" || tag === "h2" || tag === "h3") {
      const level = Number(tag.at(-1));
      if (target === "markdown") return `${"#".repeat(level)} ${inner}`;
      if (target === "unity") return `<size=${[0, "160%", "140%", "120%"][level]}><b>${inner}</b></size>`;
      if (target === "bbcode") return `[font_size=${[0, 32, 26, 21][level]}][b]${inner}[/b][/font_size]`;
      return `<NCH${level}>${inner}</>`;
    }
    if (tag === "blockquote") {
      if (target === "markdown") return textValue(node).split("\n").map((line) => `> ${line}`).join("\n");
      if (target === "unity") return `<indent=5%><i>“${inner}”</i></indent>`;
      if (target === "bbcode") return `[quote]${inner}[/quote]`;
      return `<NCQuote>${inner}</>`;
    }
    if (tag === "ul" || tag === "ol") return serializeList(node, tag === "ol", context);
    if (tag === "li") return inner;
    if (tag === "pre") {
      const code = textValue(node);
      if (target === "markdown") return `\`\`\`\n${code}\n\`\`\``;
      if (target === "unity") return `<style="NCCode">${code}</style>`;
      if (target === "bbcode") return `[code]${code}[/code]`;
      return `<NCCodeBlock>${code}</>`;
    }
    if (tag === "strong") {
      if (target === "markdown") return `**${inner}**`;
      if (target === "unity") return `<b>${inner}</b>`;
      if (target === "bbcode") return `[b]${inner}[/b]`;
      return `<NCBold>${inner}</>`;
    }
    if (tag === "em") {
      if (target === "markdown") return `*${inner}*`;
      if (target === "unity") return `<i>${inner}</i>`;
      if (target === "bbcode") return `[i]${inner}[/i]`;
      return `<NCItalic>${inner}</>`;
    }
    if (tag === "del") {
      if (target === "markdown") return `~~${inner}~~`;
      if (target === "unity") return `<s>${inner}</s>`;
      if (target === "bbcode") return `[s]${inner}[/s]`;
      return `<NCStrike>${inner}</>`;
    }
    if (tag === "code") {
      if (node.parentElement?.tagName?.toLowerCase() === "pre") return inner;
      if (target === "markdown") return `\`${inner}\``;
      if (target === "unity") return `<style="NCCode">${inner}</style>`;
      if (target === "bbcode") return `[code]${inner}[/code]`;
      return `<NCCode>${inner}</>`;
    }
    if (tag === "a") {
      const href = safeNarrativeHref(node.getAttribute("href"));
      if (target === "markdown") return `[${inner}](${href})`;
      if (target === "unity") return `<link="${href}">${inner}</link>`;
      if (target === "bbcode") return `[url=${href}]${inner}[/url]`;
      return `<NCLink href="${href}">${inner}</>`;
    }
    if (tag === "span") {
      const color = getCanonicalNodeColor(node, "text");
      if (!color) return inner;
      if (target === "markdown") return `{color:${color}}${inner}{/color}`;
      if (target === "unity") return `<color=${color}>${inner}</color>`;
      if (target === "bbcode") return `[color=${color}]${inner}[/color]`;
      return `<NCColor value="${color}">${inner}</>`;
    }
    if (tag === "mark") {
      const color = getCanonicalNodeColor(node, "highlight");
      if (target === "markdown") return color ? `{highlight:${color}}${inner}{/highlight}` : `==${inner}==`;
      if (target === "unity") return `<mark=${color || "#ffff00"}80>${inner}</mark>`;
      if (target === "bbcode") return `[bgcolor=${color || "#ffd43b"}]${inner}[/bgcolor]`;
      return `<NCHighlight${color ? ` value="${color}"` : ""}>${inner}</>`;
    }
    return inner;
  };
  const blockTags = new Set(["p", "h1", "h2", "h3", "blockquote", "ul", "ol", "pre", "hr"]);
  let output = "";
  let previousWasBlock = false;
  for (const node of template.content.childNodes) {
    const part = serializeNode(node);
    if (!part) continue;
    const isBlock = node.nodeType === 1 && blockTags.has(node.tagName.toLowerCase());
    if (output && (isBlock || previousWasBlock) && !output.endsWith("\n")) output += "\n";
    output += part;
    previousWasBlock = isBlock;
  }
  return output.replace(/\n{3,}/g, "\n\n").trim();
}

function convertNarrativeRichText(text, fromFormat, toFormat) {
  const source = String(text ?? "");
  if (!source || normalizeRichTextFormat(fromFormat) === normalizeRichTextFormat(toFormat)) return source;
  return serializeNarrativeHtml(renderNarrativeRichText(source, fromFormat), toFormat);
}

function convertProjectRichText(fromFormat, toFormat) {
  state.project.notes = convertNarrativeRichText(state.project.notes, fromFormat, toFormat);
  for (const node of state.project.nodes || []) {
    node.body = convertNarrativeRichText(node.body, fromFormat, toFormat);
    if (Array.isArray(node.turns)) {
      for (const turn of node.turns) {
        turn.line = convertNarrativeRichText(turn.line, fromFormat, toFormat);
      }
    }
  }
}

// Linked image previews (the ones enabled on the node card) also show on play cards.
function renderPlayCardImages(node) {
  const host = window.NarrativeCanvasHost;
  if (!host?.getVaultResourceUrl) return "";
  const images = getNodeVaultFiles(node).filter((entry) => entry.preview && CODEX_IMAGE_FILE_PATTERN.test(entry.path));
  if (!images.length) return "";
  return `<div class="play-card-images">${images.map((entry) => `<img src="${escapeAttr(host.getVaultResourceUrl(entry.path))}" alt="" loading="lazy" draggable="false">`).join("")}</div>`;
}

// Runs `callback` with `state.playVariables` temporarily swapped to a snapshot, so
// templated text renders against the values of that moment.
function withPreviewVariables(variables, callback) {
  const activeVariables = state.playVariables;
  if (variables) state.playVariables = variables;
  try {
    return callback();
  } finally {
    state.playVariables = activeVariables;
  }
}

function renderPreviewHistoryCard(node, step, index) {
  // Render each past card against the variable snapshot captured at that step, so
  // templated text shows what the reader actually saw back then.
  return withPreviewVariables(step?.variables, () => {
    const runtimeScript = getNodeRuntimeScript(node);
    const title = renderRuntimeTemplate(runtimeScript.title, node, getNodeDisplayTitle(node, node.type));
    const turns = getRuntimeDialogTurns(node);
    const body = turns.length
      ? turns.map((turn) => formatRuntimeDialogTurn(turn)).join("\n")
      : renderRuntimeTemplate(runtimeScript.body, node, displayBody(node));
    // A step can only be restored when its snapshot exists; without one the jump
    // button is omitted rather than silently failing.
    const canRestore = Boolean(step?.nodeId);
    return `
      <article class="play-history-card">
        <div class="play-meta">
          <span>${escapeHtml(getNodeTypeLabel(node.type))} ${escapeHtml(getNodeDisplayId(node))}</span>
          <span>${index + 1}</span>
        </div>
        <h4>${escapeHtml(title)}</h4>
        <div class="play-body-text">${renderNarrativeRichText(body)}</div>
        ${renderPlayCardImages(node)}
        ${canRestore ? `
          <button class="play-history-jump" type="button" data-action="play-history-jump" data-play-step-index="${index}" title="${escapeAttr(t("Rewind the story to this card. Later steps are discarded."))}">
            ↩ ${escapeHtml(t("Return to this card"))}
          </button>
        ` : ""}
      </article>
    `;
  });
}

function getPreviewScroller() {
  return dom.playDialog?.querySelector?.(".play-scroll") || null;
}

function isPreviewScrollerNearBottom() {
  const scroller = getPreviewScroller();
  if (!scroller) return true;
  return scroller.scrollHeight - scroller.scrollTop - scroller.clientHeight < 48;
}

function scrollPreviewToCurrentCard() {
  // Scroll synchronously right after the DOM swap, then once more on a short timer to
  // absorb late layout shifts (images, debug details). Timer instead of rAF: rAF can be
  // starved under headless/virtual-time test runs.
  const scroller = getPreviewScroller();
  if (!scroller) return;
  scroller.scrollTop = scroller.scrollHeight;
  window.setTimeout(() => {
    const settled = getPreviewScroller();
    if (settled) settled.scrollTop = settled.scrollHeight;
  }, 50);
}

function renderPreviewNode(nodeId, options = {}) {
  const node = getNode(nodeId);
  if (!node) return;
  if (state.playChoiceTimer?.nodeId && state.playChoiceTimer.nodeId !== node.id) clearPlayChoiceTimer();
  const runtimeScript = getNodeRuntimeScript(node);
  if (!options.skipVisit) {
    ensurePreviewVisitRecord(node);
    applyNodeEffectsForNode(node, "onVisit", "Node visit");
    applyPlaybookActionsForNode(node, "onVisit", "Node visit");
    applyVisitTrackingRule(node);
    capturePreviewStep(node.id);
    trimPreviewHistory();
  }

  const outgoing = getOutgoing(node.id);
  let nextLinks = outgoing;
  const requirementsSource = getRuntimeNodeRequirementsSource(node, runtimeScript);
  nextLinks = filterRuntimeLinksByRequirements(nextLinks, node);

  if (!state.playPath.includes(node.id)) {
    state.playPath.push(node.id);
    state.playStepIndex = state.playPath.length - 1;
  }
  const runtimeChoices = getRuntimeChoices(node, runtimeScript);
  if (runtimeChoices.length && nextLinks.length) {
    nextLinks = getChoiceOrderedLinks(nextLinks);
  }
  const progress = getPreviewProgress(node, nextLinks, runtimeChoices);
  const { pageNumber, pageTotal, nextPathId } = progress;
  const previousButton = pageNumber > 1
    ? `<button class="play-action" type="button" data-action="play-prev">${escapeHtml(t("Previous"))}</button>`
    : "";
  const runtimeTitle = renderRuntimeTemplate(runtimeScript.title, node, getNodeDisplayTitle(node, node.type));
  const dialogTurns = getRuntimeDialogTurns(node);
  const manualActionButtons = renderPreviewManualActions(node);
  const dialogTurnIndex = dialogTurns.length ? clamp(state.playTurnIndex || 0, 0, dialogTurns.length - 1) : 0;
  state.playTurnIndex = dialogTurnIndex;
  const runtimeBody = dialogTurns.length
    ? formatRuntimeDialogTurn(dialogTurns[dialogTurnIndex])
    : renderRuntimeTemplate(runtimeScript.body, node, displayBody(node));
  dom.playTitle.textContent = runtimeTitle;
  const customFields = renderPreviewCustomFields(node);
  const debugDetails = renderPreviewDebugDetails(node, { requirementsSource, branchConditionSource: "" });
  // Measure before the DOM swap: a reader parked at the bottom follows the story;
  // one scrolled up into history keeps their place on passive refreshes.
  const followStory = !options.skipVisit || isPreviewScrollerNearBottom();
  dom.playBody.innerHTML = `
    ${renderPreviewHistoryCards()}
    <div class="play-current-card">
      <div class="play-meta">
        <span>${escapeHtml(getNodeTypeLabel(node.type))} ${escapeHtml(getNodeDisplayId(node))}</span>
        <span>${pageNumber} / ${pageTotal}</span>
      </div>
      <h3>${escapeHtml(runtimeTitle)}</h3>
      <div class="play-body-text">${renderNarrativeRichText(runtimeBody)}</div>
      ${renderPlayCardImages(node)}
      ${dialogTurns.length ? `<div class="play-meta"><span>${escapeHtml(t("Line"))} ${dialogTurnIndex + 1} / ${dialogTurns.length}</span></div>` : ""}
      ${customFields}
      ${debugDetails}
    </div>
  `;
  if (followStory) scrollPreviewToCurrentCard();
  if (!options.skipCanvasFocus) focusCanvasOnPreviewNode(node);

  if (dialogTurns.length && dialogTurnIndex < dialogTurns.length - 1) {
    clearPlayChoiceTimer();
    const linePrevButton = dialogTurnIndex > 0
      ? `<button class="play-action" type="button" data-action="play-dialog-prev">${escapeHtml(t("Previous line"))}</button>`
      : "";
    dom.playActions.innerHTML = previousButton + linePrevButton + manualActionButtons + `<button class="play-action primary" type="button" data-action="play-dialog-next">${escapeHtml(t("Continue"))}</button>`;
    return;
  }

  if (isPreviewEndConditionMet() || normalizeNodeRouting(node.routing).mode === "end") {
    clearPlayChoiceTimer();
    dom.playActions.innerHTML = previousButton + manualActionButtons + `<button class="play-action" type="button" data-action="restart-play">${escapeHtml(t("Restart"))}</button>`;
    return;
  }

  if (runtimeChoices.length && nextLinks.length) {
    const entries = getRuntimeChoiceEntries(node, runtimeScript);
    const revealMode = getChoiceRevealMode(node);
    const availability = new Map(entries.map((entry, index) => [entry.optionId || `index:${index}`, isChoiceOptionAvailable(entry, node)]));
    const visibleLinks = nextLinks.filter((link) => {
      if (revealMode !== "hide") return true;
      if (!link.choiceOptionId) return true;  // legacy links with no option id stay visible
      return availability.get(link.choiceOptionId) !== false;
    });
    const timer = normalizeChoiceTimer(node.choiceTimer);
    const fallbackLink = timer.enabled
      ? visibleLinks.find((link) => link.id === timer.fallbackLinkId
        && (!link.choiceOptionId || availability.get(link.choiceOptionId) !== false))
      : null;
    const timerStatus = fallbackLink
      ? `<div class="play-choice-countdown" data-play-choice-countdown aria-live="polite"></div>`
      : "";
    dom.playActions.innerHTML = previousButton + manualActionButtons + timerStatus + visibleLinks.map((link, index) => {
      const label = getChoiceBranchButtonLabel(link, runtimeChoices, index, entries);
      const optionAttr = link.choiceOptionId ? ` data-choice-option-id="${escapeAttr(link.choiceOptionId)}"` : "";
      const available = link.choiceOptionId ? availability.get(link.choiceOptionId) !== false : true;
      const disabledAttr = revealMode === "disabled" && !available ? ` disabled aria-disabled="true" title="${escapeAttr(t("Requirements not met"))}"` : "";
      return `<button class="play-action play-choice-action" type="button" data-action="play-next" data-node-id="${escapeAttr(link.to)}"${optionAttr}${disabledAttr}>${escapeHtml(label)}</button>`;
    }).join("");
    if (fallbackLink) ensurePlayChoiceTimer(node, timer, fallbackLink);
    else clearPlayChoiceTimer();
    return;
  }

  if (nextLinks.length > 1) {
    clearPlayChoiceTimer();
    dom.playActions.innerHTML = previousButton + manualActionButtons + nextLinks.map((link, index) => {
      const label = getPreviewBranchLabel(link, index);
      return `<button class="play-action play-choice-action" type="button" data-action="play-next" data-node-id="${escapeAttr(link.to)}">${escapeHtml(label)}</button>`;
    }).join("");
    return;
  }

  const routingNextId = getRoutingNextNodeId(node);
  clearPlayChoiceTimer();
  const nextId = routingNextId || nextLinks[0]?.to || nextPathId;
  dom.playActions.innerHTML = previousButton + manualActionButtons + (nextId
    ? `<button class="play-action primary" type="button" data-action="play-next" data-node-id="${escapeAttr(nextId)}">${escapeHtml(t("Next page"))}</button>`
    : `<button class="play-action" type="button" data-action="restart-play">${escapeHtml(t("Restart"))}</button>`);
}

function getPreviewBranchLabel(link, index = 0) {
  const rawLabel = normalizeOptionalString(link?.label).trim();
  const target = getNode(link?.to);
  const generic = !rawLabel || /^(?:continue|next|next page)$/i.test(rawLabel);
  return generic
    ? (target?.title || t("Branch {number}", { number: index + 1 }))
    : rawLabel;
}

function clearPlayChoiceTimer() {
  const timer = state.playChoiceTimer;
  if (timer?.timeoutId) window.clearTimeout(timer.timeoutId);
  if (timer?.intervalId) window.clearInterval(timer.intervalId);
  state.playChoiceTimer = null;
}

function ensurePlayChoiceTimer(node, timer, fallbackLink) {
  if (!node || !fallbackLink || !timer?.enabled) {
    clearPlayChoiceTimer();
    return;
  }
  const key = `${node.id}|${fallbackLink.id}|${timer.seconds}`;
  if (state.playChoiceTimer?.key === key) {
    updatePlayChoiceCountdown();
    return;
  }
  clearPlayChoiceTimer();
  const deadline = Date.now() + timer.seconds * 1000;
  const timeoutId = window.setTimeout(() => {
    const active = state.playChoiceTimer;
    if (!active || active.key !== key || state.playNodeId !== node.id) return;
    const currentLink = getLink(fallbackLink.id);
    clearPlayChoiceTimer();
    if (!currentLink || currentLink.from !== node.id || !isLinkRequirementMet(currentLink, node) || !isTargetNodeRequirementMet(currentLink)) return;
    const fallbackEntry = currentLink.choiceOptionId
      ? getRuntimeChoiceEntries(node, getNodeRuntimeScript(node)).find((entry) => entry.optionId === currentLink.choiceOptionId)
      : null;
    if (fallbackEntry && !isChoiceOptionAvailable(fallbackEntry, node)) return;
    advancePreview(currentLink.to, { optionId: currentLink.choiceOptionId || "", timed: true });
  }, timer.seconds * 1000);
  const intervalId = window.setInterval(updatePlayChoiceCountdown, 250);
  state.playChoiceTimer = { key, nodeId: node.id, deadline, timeoutId, intervalId };
  updatePlayChoiceCountdown();
}

function updatePlayChoiceCountdown() {
  const timer = state.playChoiceTimer;
  const target = dom.playActions?.querySelector?.("[data-play-choice-countdown]");
  if (!timer || !target) return;
  const seconds = Math.max(0, Math.ceil((timer.deadline - Date.now()) / 1000));
  target.textContent = t("Time remaining: {seconds}s", { seconds });
}

function renderPreviewManualActions(node) {
  const actions = getMatchingPlaybookActions(node, "manual").filter(isExecutablePlaybookAction);
  if (!actions.length) return "";
  return actions.map((action, index) => {
    const label = getPlaybookManualActionLabel(action);
    const applied = state.playManualActionRunIds instanceof Set && state.playManualActionRunIds.has(action.id);
    const appliedAttr = applied ? ` data-play-manual-applied="true"` : "";
    return `<button class="play-action" type="button" data-action="play-manual" data-node-id="${escapeAttr(node.id)}" data-playbook-action-id="${escapeAttr(action.id)}"${appliedAttr}>${escapeHtml(label)}</button>`;
  }).join("");
}

function isExecutablePlaybookAction(action) {
  const info = getPlaybookActionVariableInfo(action);
  return getAllowedPlaybookActionOperationsForVariableInfo(info).some((entry) => entry.value === action?.op);
}

function getPlaybookManualActionLabel(action) {
  const op = String(action?.op || "action").trim();
  const operation = PLAYBOOK_ACTION_OPERATIONS.find((entry) => entry.value === op);
  let opLabel = t(operation?.label || op);
  const key = getPlaybookActionStateKey(action);
  const value = String(action?.value || "").trim();
  if (!key) return opLabel;
  if (value === "" || ["clear", "toggle", "show", "hide", "lockChoice", "unlockChoice", "goTo"].includes(op)) {
    return `${opLabel} ${key}`;
  }
  return `${opLabel} ${key} = ${value}`;
}

function getPreviewProgress(node, nextLinks, runtimeChoices) {
  const pathIndex = state.playPath.indexOf(node.id);
  const pageNumber = pathIndex >= 0 ? pathIndex + 1 : Math.max(state.playPath.length, 1);
  const knownTotal = Math.max(state.playPath.length, pageNumber, 1);
  const canProjectFuture = !(runtimeChoices.length && nextLinks.length);
  const projectedTotal = canProjectFuture
    ? pageNumber + getPreviewFutureCount(node.id, nextLinks)
    : pageNumber;
  return {
    pageNumber,
    pageTotal: Math.max(knownTotal, projectedTotal),
    nextPathId: pathIndex >= 0 ? state.playPath[pathIndex + 1] : null
  };
}

function getPreviewFutureCount(startId, initialNextLinks) {
  let count = 0;
  let nextId = initialNextLinks[0]?.to || "";
  const seen = new Set([startId]);
  while (nextId && !seen.has(nextId)) {
    const node = getNode(nextId);
    if (!node) break;
    seen.add(nextId);
    count += 1;
    const runtimeScript = getNodeRuntimeScript(node);
    const outgoing = getOutgoing(node.id);
    if (getRuntimeChoices(node, runtimeScript).length && outgoing.length) break;
    let nextLinks = outgoing;
    nextLinks = filterRuntimeLinksByRequirements(nextLinks, node);
    nextId = nextLinks[0]?.to || "";
  }
  return count;
}

function getPreviewPath() {
  return getReachableStory().filter((node) => !isFrameNode(node));
}

function getPreviewStartNode(previewPath = getPreviewPath()) {
  const startTitle = getRunnerRuleValue("startNode");
  if (startTitle) {
    const found = findNodeByTitleOrId(startTitle, { includeFrames: false });
    if (found) return found;
  }
  return previewPath[0];
}

function getRoutingNextNodeId(node) {
  const routing = normalizeNodeRouting(node?.routing);
  if (routing.mode !== "goTo" || !routing.target) return "";
  return findNodeByTitleOrId(routing.target, { includeFrames: false })?.id || "";
}

function findNodeByTitleOrId(value, options = {}) {
  const target = normalizeOptionalString(value).trim();
  if (!target) return null;
  const includeFrames = Boolean(options.includeFrames);
  return state.project.nodes.find((node) => (includeFrames || !isFrameNode(node)) && node.id === target)
    || state.project.nodes.find((node) => (includeFrames || !isFrameNode(node)) && normalizeOptionalString(node.title).trim() === target)
    || null;
}

function applyVisitTrackingRule(node) {
  if (!isPreviewVisitTrackingEnabled() || !node) return;
  if (!(state.playVisitedNodeIds instanceof Set)) state.playVisitedNodeIds = new Set();
  state.playVisitedNodeIds.add(node.id);
  ensurePreviewVisitRecord(node);
}

function isRuntimeVisitTrackingEffect(effect) {
  return false;
}

function isPreviewEndConditionMet() {
  const rule = getRunnerRules().endCondition;
  return Boolean(rule?.enabled && rule.value && evaluateCondition(rule.value));
}

function getEndConditionStatus(source) {
  const text = String(source || "").trim();
  if (!text) return { status: "empty" };
  const variables = normalizeVariablesObject(state.project.variables);
  const result = collectExpressionKeys(text, variables);
  if (result.invalid) return { status: "invalid" };
  const unknown = result.keys.filter((key) => !resolveRuntimeStatePath(key, variables).found);
  if (unknown.length) return { status: "unknown", key: unknown[0] };
  return { status: "ok" };
}

function collectExpressionKeys(text, variables = {}) {
  const trimmed = String(text || "").trim();
  if (!trimmed) return { keys: [], membershipKeys: [], invalid: false };
  const parsed = parseJsConditionExpression(trimmed);
  if (parsed.invalid) return { keys: [], membershipKeys: [], invalid: true };
  return collectJsConditionAstKeys(parsed.ast, variables);
}

function uniqueExpressionKeys(keys) {
  return [...new Set((keys || []).map((key) => normalizeOptionalString(key).trim()).filter(Boolean))];
}

function formatEndConditionStatusLabel(status) {
  if (!status || status.status === "empty") return "";
  if (status.status === "ok") return t("Expression valid");
  if (status.status === "invalid") return t("Invalid expression");
  if (status.status === "unknown") return t("Unknown variable: {key}", { key: status.key });
  return "";
}

function updateEndConditionStatusHint(input) {
  if (!input) return;
  const hint = input.parentElement?.querySelector("[data-end-condition-status]");
  if (!hint) return;
  const status = getEndConditionStatus(input.value);
  hint.textContent = formatEndConditionStatusLabel(status);
  hint.classList.remove("play-rule-status-empty", "play-rule-status-ok", "play-rule-status-invalid", "play-rule-status-unknown");
  hint.classList.add(`play-rule-status-${status.status}`);
}

function getRunnerRuleValue(key) {
  const rule = getRunnerRules()[key];
  return rule?.enabled ? rule.value : "";
}

function formatPreviewTemplateValues(node) {
  const refs = collectPreviewTemplateValueRefs(node);
  if (!refs.length) return t("No template values.");
  return refs
    .map((ref) => `${ref.label && ref.label !== ref.key ? `${ref.label} (${ref.key})` : ref.key}: ${formatPreviewDebugValue(ref.value)}`)
    .join("\n");
}

function collectPreviewTemplateValueRefs(node) {
  const runtimeScript = getNodeRuntimeScript(node);
  const sources = [
    runtimeScript.title || getNodeDisplayTitle(node, node?.type || "Node"),
    runtimeScript.body || displayBody(node)
  ];
  if (node?.title) sources.push(node.title);
  if (node?.body) sources.push(node.body);
  getRuntimeDialogTurns(node).forEach((turn) => {
    sources.push(turn.speaker, turn.line);
  });
  getNodeCustomFieldEntries(node).forEach((field) => {
    if (field.value !== "") sources.push(field.value);
  });
  const refs = new Map();
  sources.forEach((source) => {
    collectPreviewTemplateValueRefsFromSource(source, node).forEach((ref) => {
      const existing = refs.get(ref.key);
      if (!existing || (existing.label === ref.key && ref.label !== ref.key)) refs.set(ref.key, ref);
    });
  });
  return [...refs.values()].sort((a, b) => a.key.localeCompare(b.key));
}

function collectPreviewTemplateValueRefsFromSource(source, node) {
  const text = String(source || "");
  const variables = normalizeVariablesObject(getPlayRuntimeVariables());
  const refs = [];
  text.replace(/\{([a-zA-Z_][\w.-]*)\}/g, (match, rawKey, offset) => {
    const key = rawKey.startsWith("variables.") ? rawKey.slice("variables.".length) : rawKey;
    if (!rawKey.startsWith("variables.") && getNodeFieldValue(node, rawKey) !== "") return match;
    const resolved = resolveRuntimeStatePath(key, variables);
    if (!resolved.found) return match;
    refs.push({
      key,
      label: inferTemplateValueLabel(text, offset, key),
      value: resolved.value
    });
    return match;
  });
  return refs;
}

function inferTemplateValueLabel(source, offset, key) {
  const prefix = String(source || "").slice(0, Math.max(0, offset));
  const cleaned = prefix.replace(/\{[^{}]*\}/g, " ");
  const parts = cleaned.split(/[\r\n;；。.!！?？,，:：()（）/|]/);
  let label = normalizeOptionalString(parts[parts.length - 1]).trim();
  label = label.replace(/["'“”‘’`[\]{}<>]+/g, "").replace(/\s+/g, " ").trim();
  if (label.length > 32) label = label.slice(Math.max(0, label.length - 32)).trim();
  return label || key;
}

function formatPreviewAffectedValues(node) {
  const rows = collectPreviewAffectedValueRows(node);
  return rows.length ? rows.join("\n") : t("No affected values.");
}

function collectPreviewAffectedValueRows(node) {
  const rows = [];
  const push = (label, action) => {
    const row = formatPreviewAffectedValueRow(label, action, node);
    if (row) rows.push(row);
  };
  normalizeNodeStateLogic(node?.stateLogic).effects.forEach((effect) => {
    const label = `${t("Node effect")} / ${t(effect.trigger === "onChoose" ? "On choose" : "On visit")}`;
    if (effect.op === "ifElse") {
      push(`${label} / if`, effect.thenEffect);
      push(`${label} / else`, effect.elseEffect);
    } else {
      push(label, effect);
    }
  });
  getMatchingPlaybookActions(node, "onVisit").forEach((action) => push(`${t("Variable action")} / ${t("On visit")}`, action));
  getMatchingPlaybookActions(node, "manual").forEach((action) => push(t("Manual action"), action));
  getMatchingPlaybookActions(node, "onChoose").forEach((action) => push(`${t("Variable action")} / ${t("On choose")}`, action));
  getRuntimeChoiceEntries(node, getNodeRuntimeScript(node)).forEach((entry) => {
    (entry.effects || []).forEach((effect) => {
      const label = `${t("Choice effect")} / ${entry.label || entry.optionId || t("Option")}`;
      if (effect.op === "ifElse") {
        push(`${label} / if`, effect.thenEffect);
        push(`${label} / else`, effect.elseEffect);
      } else {
        push(label, effect);
      }
    });
  });
  return [...new Set(rows)];
}

function formatPreviewAffectedValueRow(label, action, node) {
  const stateAction = { ...action, category: action?.category || "Variable" };
  const key = getPlaybookActionStateKey(stateAction);
  if (!key) return "";
  const op = String(stateAction?.op || "set").trim() || "set";
  const operation = PLAYBOOK_ACTION_OPERATIONS.find((entry) => entry.value === op);
  const opLabel = t(operation?.label || op);
  const rawValue = normalizeOptionalString(stateAction?.value).trim();
  const value = rawValue ? renderRuntimeTemplate(rawValue, node, rawValue) : "";
  const current = getPlayRuntimeStateValueLabel(key);
  const valueText = value === "" || ["clear", "toggle", "show", "hide", "lockChoice", "unlockChoice", "goTo"].includes(op)
    ? `${opLabel} ${key}`
    : `${opLabel} ${key} = ${value}`;
  return current === "" ? `${label}: ${valueText}` : `${label}: ${valueText} (${t("current")}: ${current})`;
}

function formatPreviewDebugValue(value) {
  return JSON.stringify(value);
}

function renderPreviewDebugDetails(node, details = {}) {
  const rule = getRunnerRules().debugMode;
  if (!rule?.enabled || !rule.value) return "";
  const branchConditionSource = typeof details === "string" ? details : details.branchConditionSource;
  const requirementsSource = typeof details === "string" ? "" : details.requirementsSource;
  const variables = Object.entries(normalizeVariablesObject(getPlayRuntimeVariables()))
    .sort(([a], [b]) => a.localeCompare(b))
    .map(([key, value]) => `${key}: ${JSON.stringify(value)}`)
    .join("\n") || t("No variables yet.");
  const visitTrackingEnabled = isPreviewVisitTrackingEnabled();
  const visitedTitles = visitTrackingEnabled ? getPreviewVisitedNodeTitles() : [];
  const visited = visitedTitles.length ? visitedTitles.join("\n") : t("No visits yet.");
  const gate = branchConditionSource ? `${branchConditionSource} => ${evaluateCondition(branchConditionSource)}` : "No gate";
  const requirements = requirementsSource ? `\n${t("Requirements")}: ${requirementsSource} => ${evaluateRequirementExpression(requirementsSource)}` : "";
  const routing = normalizeNodeRouting(node.routing);
  const routingText = routing.mode === "goTo" ? `Go to ${routing.target}` : routing.mode;
  const templateValues = formatPreviewTemplateValues(node);
  const affectedValues = formatPreviewAffectedValues(node);
  const visitedText = visitTrackingEnabled ? `\n${t("Visited")}:\n${visited}` : "";
  return `
    <details class="play-debug" ${state.playDebugOpen === false ? "" : "open"}>
      <summary>${escapeHtml(t("Debug"))}</summary>
      <pre>${escapeHtml(`${t("Gate")}: ${gate}${requirements}\n${t("Routing")}: ${routingText}\n${t("Template values")}:\n${templateValues}\n${t("Variables")}:\n${variables}\n${t("Affected values")}:\n${affectedValues}${visitedText}`)}</pre>
    </details>
  `;
}

function getPreviewVisitedNodeTitles() {
  const records = clonePreviewVisitRecords(state.playVisitRecords);
  if (records.length) {
    return records.map((record) => {
      const title = record.title || getNode(record.nodeId)?.title || getNodeTypeLabel(getNode(record.nodeId)?.type);
      const displayId = record.displayId || (getNode(record.nodeId) ? getNodeDisplayId(getNode(record.nodeId)) : record.nodeId);
      const operations = record.operations.length
        ? `\n${record.operations.map((operation) => `  - ${operation}`).join("\n")}`
        : "";
      return `${title} (${displayId})${operations}`;
    });
  }
  const ids = state.playVisitedNodeIds instanceof Set ? [...state.playVisitedNodeIds] : [];
  return ids
    .map((id) => {
      const node = getNode(id);
      return node ? `${node.title || getNodeTypeLabel(node.type)} (${getNodeDisplayId(node)})` : "";
    })
    .filter(Boolean);
}

function renderPreviewCustomFields(node) {
  const fields = getNodeCustomFieldEntries(node).filter((field) => field.value !== "");
  if (!fields.length) return "";
  return `
    <dl class="play-fields">
      ${fields.map((field) => `
        <div>
          <dt>${escapeHtml(field.label)}</dt>
          <dd>${escapeHtml(renderRuntimeTemplate(field.value, node, field.value))}</dd>
        </div>
      `).join("")}
    </dl>
  `;
}

function getNodeRuntimeScript(node) {
  const scripts = getScriptNodeTypes();
  return scripts[node?.id]
    || scripts[node?.type]
    || scripts[getNodeTypeLabel(node?.type)]
    || {};
}

function getRuntimeNodeRequirementsSource(node, script) {
  const requirements = normalizeNodeStateLogic(node?.stateLogic).requirements;
  if (requirements) return requirements;
  const gateAction = getPlaybookGateAction(node);
  if (gateAction) return `${getPlaybookActionStateKey(gateAction)} ${renderRuntimeTemplate(gateAction.value, node, gateAction.value)}`.trim();
  return "";
}

function applyNodeEffectsForNode(node, trigger, contextLabel = "") {
  normalizeNodeStateLogic(node?.stateLogic).effects
    .filter((effect) => effect.trigger === trigger)
    .forEach((effect) => applyNodeEffect(effect, node, contextLabel));
}

function applyNodeEffect(effect, node, contextLabel = "") {
  if (effect?.op === "ifElse") {
    const condition = renderRuntimeTemplate(effect.condition, node, effect.condition);
    const branch = evaluateRequirementExpression(condition) ? effect.thenEffect : effect.elseEffect;
    if (!branch) return false;
    return applyPlaybookActionWithPreviewLog({
      ...branch,
      id: "",
      trigger: effect.trigger || "onVisit",
      target: "",
      category: "Variable"
    }, node, contextLabel);
  }
  return applyPlaybookActionWithPreviewLog({
    id: "",
    trigger: effect.trigger || "onVisit",
    target: "",
    op: effect.op || "set",
    category: "Variable",
    key: effect.key || "",
    value: effect.value || "",
    valueMode: effect.valueMode === "variable" ? "variable" : "literal"
  }, node, contextLabel);
}

function getRuntimeChoices(node, script) {
  if (Array.isArray(script?.choices)) {
    return script.choices.map((choice) => renderRuntimeTemplate(choice, node, choice)).filter(Boolean);
  }
  if (script?.choices) {
    return parseChoiceLines(resolveScriptReference(node, script.choices));
  }
  return hasNodeChoices(node) ? node.choices : [];
}

function getRuntimeDialogTurns(node) {
  if (!node || !isDialogNode(node) || !Array.isArray(node.turns)) return [];
  return node.turns
    .map((turn) => ({
      speaker: renderRuntimeTemplate(turn.speaker, node, turn.speaker).trim(),
      line: renderRuntimeTemplate(turn.line, node, turn.line).trim()
    }))
    .filter((turn) => turn.speaker || turn.line);
}

function formatRuntimeDialogTurn(turn) {
  if (!turn) return "";
  return turn.speaker ? `${turn.speaker}: ${turn.line}` : turn.line;
}

// Full option records (label + optionId + requires + effects). Returns the same number of items as getRuntimeChoices.
// Used by Play to gate options on `requires` and apply per-option `effects` when selected.
function getRuntimeChoiceEntries(node, script) {
  const labels = getRuntimeChoices(node, script);
  const options = Array.isArray(node?.choiceOptions) ? node.choiceOptions : [];
  return labels.map((label, index) => {
    const option = options[index];
    const renderedLabel = renderRuntimeTemplate(label, node, label);
    if (!option) return { label: renderedLabel, optionId: "", requires: "", effects: [] };
    return {
      label: renderedLabel || option.label,
      optionId: option.id || "",
      requires: option.requires || "",
      effects: Array.isArray(option.effects) ? option.effects : []
    };
  });
}

// True iff the option's `requires` expression evaluates true. Empty `requires` means always available.
function isChoiceOptionAvailable(entry, node) {
  const conditions = [];
  if (entry?.requires) conditions.push(renderRuntimeTemplate(entry.requires, node, entry.requires));
  getMatchingPlaybookChoiceGateActions(node, { id: entry?.optionId || "", label: entry?.label || "" }, entry?.label || "")
    .forEach((action) => {
      const source = renderRuntimeTemplate(action.value, node, action.value);
      const condition = getChoiceGateConditionExpression(action, source);
      if (condition) conditions.push(condition);
    });
  return conditions.every((condition) => evaluateRequirementExpression(condition));
}

function getChoiceRevealMode(node) {
  if (node?.choiceRevealMode) return normalizeChoiceRevealMode(node.choiceRevealMode);
  return "hide";
}

function filterRuntimeLinksByRequirements(links, node) {
  return (links || []).filter((link) => isLinkRequirementMet(link, node) && isTargetNodeRequirementMet(link));
}

function isLinkRequirementMet(link, node) {
  const source = normalizeOptionalString(link?.requirements || link?.requires).trim();
  if (!source) return true;
  return evaluateRequirementExpression(renderRuntimeTemplate(source, node, source));
}

function isTargetNodeRequirementMet(link) {
  const targetNode = getNode(link?.to);
  if (!targetNode) return true;
  const targetScript = getNodeRuntimeScript(targetNode);
  const source = getRuntimeNodeRequirementsSource(targetNode, targetScript);
  if (!source) return true;
  return evaluateRequirementExpression(renderRuntimeTemplate(source, targetNode, source));
}

function evaluateRequirementExpression(source) {
  const text = String(source || "").trim();
  if (!text) return true;
  const notWrapped = text.match(/^!\((.*)\)$/);
  if (notWrapped) return !evaluateCondition(notWrapped[1]);
  const notPrefix = text.match(/^not\s+(.+)$/i);
  if (notPrefix) return !evaluateCondition(notPrefix[1]);
  return evaluateCondition(text);
}

function renderRuntimeTemplate(template, node, fallback) {
  const source = template == null || template === "" ? fallback : template;
  const variables = getRuntimeVariableSource();
  return String(source || "").replace(/\{([a-zA-Z_][\w.-]*)\}/g, (match, key) => {
    if (key.startsWith("variables.")) {
      const variableKey = key.slice("variables.".length);
      const resolved = resolveRuntimeStatePath(variableKey, variables);
      return resolved.found ? resolved.value : match;
    }
    const nodeValue = getNodeFieldValue(node, key);
    if (nodeValue !== "") return nodeValue;
    const resolved = resolveRuntimeStatePath(key, variables);
    return resolved.found ? resolved.value : match;
  });
}

function resolveRuntimeStatePath(key, variables = state.project.variables) {
  const sourceKey = String(key || "").trim();
  const source = normalizeVariablesObject(variables);
  if (!sourceKey) return { found: false, key: "", value: undefined, kind: "missing" };
  if (Object.prototype.hasOwnProperty.call(source, sourceKey)) {
    return { found: true, key: sourceKey, value: source[sourceKey], kind: "flat" };
  }
  if (!sourceKey.includes(".")) return { found: false, key: sourceKey, value: undefined, kind: "missing" };
  const parts = sourceKey.split(".").filter(Boolean);
  if (!parts.length || !Object.prototype.hasOwnProperty.call(source, parts[0])) {
    return { found: false, key: sourceKey, value: undefined, kind: "missing" };
  }
  let value = source[parts[0]];
  for (let index = 1; index < parts.length; index += 1) {
    const part = parts[index];
    if (value == null) return { found: false, key: sourceKey, value: undefined, kind: "missing" };
    if (Array.isArray(value) && /^\d+$/.test(part)) {
      const arrayIndex = Number(part);
      if (arrayIndex < 0 || arrayIndex >= value.length) return { found: false, key: sourceKey, value: undefined, kind: "missing" };
      value = value[arrayIndex];
      continue;
    }
    if (typeof value !== "object" || !Object.prototype.hasOwnProperty.call(value, part)) {
      return { found: false, key: sourceKey, value: undefined, kind: "missing" };
    }
    value = value[part];
  }
  return { found: true, key: sourceKey, value, kind: "path" };
}

function getPlaybookGateAction(node) {
  return getMatchingPlaybookActions(node, "gate").find((action) => action.op === "if" && action.key && action.value);
}

function applyPlaybookActionsForNode(node, trigger, contextLabel = "") {
  getMatchingPlaybookActions(node, trigger).forEach((action) => applyPlaybookActionWithPreviewLog(action, node, contextLabel));
}

function getMatchingPlaybookActions(node, trigger) {
  return getPlaybookActions().filter((action) => action.trigger === trigger && matchesPlaybookActionTarget(action, node));
}

function matchesPlaybookActionTarget(action, node) {
  const target = String(action?.target || "").trim();
  if (!target) return true;
  if (!node) return false;
  const candidates = new Set([
    node.id,
    node.type,
    getNodeTypeLabel(node.type),
    node.title
  ].map((value) => String(value || "").trim()).filter(Boolean));
  return candidates.has(target);
}

function applyPlaybookActionWithPreviewLog(action, node, contextLabel = "") {
  const applied = applyPlaybookAction(action, node);
  if (applied && contextLabel) {
    const operationText = formatPreviewStateOperation(contextLabel, action, node);
    if (operationText) recordPreviewOperation(node, operationText);
  }
  return applied;
}

function formatPreviewStateOperation(contextLabel, action, node) {
  const key = getPlaybookActionStateKey(action);
  if (!key) return "";
  const op = String(action?.op || "set").trim() || "set";
  const operation = PLAYBOOK_ACTION_OPERATIONS.find((entry) => entry.value === op);
  const opLabel = t(operation?.label || op);
  const rawValue = normalizeOptionalString(action?.value).trim();
  const value = rawValue ? renderRuntimeTemplate(rawValue, node, rawValue) : "";
  const prefix = t(contextLabel);
  // Toggle has no authored value, so show the resulting state value (true/false)
  // instead of just the operation name.
  if (op === "toggle") {
    const result = getPlayRuntimeStateValueLabel(key);
    return result === "" ? `${prefix}: ${opLabel} ${key}` : `${prefix}: ${opLabel} ${key} → ${result}`;
  }
  if (value === "" || ["clear", "show", "hide", "lockChoice", "unlockChoice", "goTo"].includes(op)) {
    return `${prefix}: ${opLabel} ${key}`;
  }
  return `${prefix}: ${opLabel} ${key} = ${value}`;
}

function getPlayRuntimeStateValueLabel(key) {
  const resolved = resolveRuntimeStatePath(key, normalizeVariablesObject(getPlayRuntimeVariables()));
  if (!resolved.found) return "";
  const value = resolved.value;
  if (typeof value === "boolean") return value ? "true" : "false";
  if (value == null) return "";
  if (typeof value === "object") return JSON.stringify(value);
  return String(value);
}

function applyPlaybookAction(action, node) {
  const info = getPlaybookActionVariableInfo(action);
  if (!info.hasVariable) return false;
  if (!getAllowedPlaybookActionOperationsForVariableInfo(info).some((option) => option.value === action.op)) return false;
  const key = getPlaybookActionStateKey(action);
  if (!key) return false;
  const variables = getPlayRuntimeVariables();
  const valueReference = action?.valueMode === "variable"
    ? resolveRuntimeStatePath(normalizeExpressionVariableTerm(action.value), variables)
    : null;
  const value = valueReference?.found
    ? cloneRuntimeExportValue(valueReference.value)
    : coercePlaybookActionValueForVariable(renderRuntimeTemplate(action.value, node, action.value), info, action);
  const existing = variables[key];
  if (action.op === "set") {
    variables[key] = value;
    return true;
  }
  if (action.op === "add" || action.op === "subtract") {
    const currentNumber = Number(existing ?? 0);
    const delta = Number(value || 0);
    variables[key] = (Number.isFinite(currentNumber) ? currentNumber : 0) + (action.op === "subtract" ? -delta : delta);
    return true;
  }
  if (action.op === "append") {
    appendPlaybookStateValue(variables, key, value);
    return true;
  }
  if (action.op === "remove") {
    removePlaybookStateValue(variables, key, value);
    return true;
  }
  if (action.op === "toggle") {
    variables[key] = !coerceBoolean(existing);
    return true;
  }
  if (action.op === "clear") {
    delete variables[key];
    return true;
  }
  return false;
}

function coercePlaybookActionValueForVariable(value, info, action = null) {
  if (info.type === "number") return Number(value) || 0;
  if (info.type === "boolean") return coerceBoolean(value);
  if ((info.type === "array" || info.type === "object") && action?.op === "set") {
    try {
      return JSON.parse(value || (info.type === "array" ? "[]" : "{}"));
    } catch (error) {
      return info.type === "array" ? [] : {};
    }
  }
  if (info.type === "array") return coerceValue(value);
  return String(value ?? "");
}

function appendPlaybookStateValue(variables, key, value) {
  const current = variables[key];
  if (Array.isArray(current)) {
    current.push(value);
    return;
  }
  if (current == null || current === "") {
    variables[key] = [value];
    return;
  }
  variables[key] = [current, value];
}

function removePlaybookStateValue(variables, key, value) {
  const current = variables[key];
  if (Array.isArray(current)) {
    variables[key] = current.filter((item) => String(item) !== String(value));
    return;
  }
  if (String(current) === String(value) || value === "") delete variables[key];
}

function getPlaybookActionStateKey(action) {
  const key = String(action?.key || "").trim();
  if (!key) return "";
  if (action.category === "Variable" || action.category === "Manual Enter") return key;
  return `${slugPlaybookCategory(action.category)}.${key}`;
}

function slugPlaybookCategory(value) {
  return String(value || "custom")
    .trim()
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, "_")
    .replace(/^_+|_+$/g, "") || "custom";
}

function resolveScriptReference(node, reference) {
  const value = getNodeFieldValue(node, reference);
  return value !== "" ? value : reference;
}

function getNodeFieldValue(node, key) {
  if (!node || !key) return "";
  if (key === "label") return getNodeTypeLabel(node.type);
  if (key === "choices") return parseChoiceLines(node.choices).join("\n");
  if (Object.prototype.hasOwnProperty.call(node, key)) {
    const value = node[key];
    return Array.isArray(value) ? value.join("\n") : String(value ?? "");
  }
  if (node.customFields && typeof node.customFields === "object" && !Array.isArray(node.customFields) && Object.prototype.hasOwnProperty.call(node.customFields, key)) {
    return String(node.customFields[key] ?? "");
  }
  const customField = getNodeCustomFieldEntries(node).find((field) => field.key === key || field.label === key);
  return customField?.value || "";
}

function hasNodeChoices(node) {
  return Array.isArray(node?.choices) && node.choices.length > 0;
}

function parseChoiceLines(value) {
  if (Array.isArray(value)) return value.map((item) => String(item).trim()).filter(Boolean);
  return String(value || "").split(/\r?\n/).map((item) => item.trim()).filter(Boolean);
}

function getChoiceBranchLabels(node) {
  return parseChoiceLines(node?.choices);
}

function getBranchLabels(node) {
  return getChoiceBranchLabels(node);
}

function normalizeChoiceIndex(value) {
  if (value == null || value === "") return null;
  const index = Number(value);
  return Number.isInteger(index) && index >= 0 ? index : null;
}

function syncProjectChoiceBranchLinks(project) {
  if (!project || !Array.isArray(project.nodes) || !Array.isArray(project.links)) return false;
  const nodeMap = new Map(project.nodes.map((node) => [node.id, node]));
  const outgoing = new Map();
  let changed = false;
  project.links.forEach((link) => {
    const source = nodeMap.get(link.from);
    if (!source || !getBranchLabels(source).length) {
      if (link.choiceIndex != null) {
        delete link.choiceIndex;
        changed = true;
      }
      return;
    }
    if (!outgoing.has(link.from)) outgoing.set(link.from, []);
    outgoing.get(link.from).push(link);
  });
  project.nodes.forEach((node) => {
    changed = syncChoiceOutgoingLinks(node, outgoing.get(node.id) || [], nodeMap) || changed;
  });
  return changed;
}

function syncChoiceBranchLinksForNode(nodeId, options = {}) {
  const node = getNode(nodeId);
  if (!node || !Array.isArray(state.project.links)) return false;
  const outgoing = state.project.links.filter((link) => link.from === nodeId);
  const changed = syncChoiceOutgoingLinks(node, outgoing, getNodeIndex(), options.preferredLinkId || "");
  if (!changed) return false;
  invalidateLinkIndexes();
  if (options.markDirty !== false) setProjectDirty(true);
  return true;
}

function syncChoiceOutgoingLinks(node, outgoing, nodeMap = null, preferredLinkId = "") {
  if (!Array.isArray(outgoing) || !outgoing.length) return false;
  const branchLabels = getBranchLabels(node);
  let changed = false;
  if (!branchLabels.length) {
    outgoing.forEach((link) => {
      if (link.choiceIndex != null) {
        delete link.choiceIndex;
        changed = true;
      }
    });
    return changed;
  }

  const ordered = getBranchSyncOrder(node, outgoing, preferredLinkId);
  const used = new Set();
  ordered.forEach((link) => {
    const index = normalizeChoiceIndex(link.choiceIndex);
    if (index != null && index < branchLabels.length && !used.has(index)) {
      if (link.choiceIndex !== index) {
        link.choiceIndex = index;
        changed = true;
      }
      used.add(index);
      return;
    }
    if (link.choiceIndex != null) {
      delete link.choiceIndex;
      changed = true;
    }
  });

  ordered.forEach((link) => {
    if (normalizeChoiceIndex(link.choiceIndex) != null) return;
    const index = findUnusedChoiceIndexForLink(link, branchLabels, used, nodeMap);
    if (index == null) return;
    link.choiceIndex = index;
    used.add(index);
    changed = true;
  });

  outgoing.forEach((link) => {
    const index = normalizeChoiceIndex(link.choiceIndex);
    const label = index == null ? "" : branchLabels[index];
    if (label && link.label !== label) {
      link.label = label;
      changed = true;
    }
  });
  return changed;
}

function getBranchSyncOrder(node, outgoing, preferredLinkId = "") {
  return preferredLinkId
    ? outgoing.slice().sort((a, b) => (a.id === preferredLinkId ? -1 : b.id === preferredLinkId ? 1 : 0))
    : outgoing;
}

function findUnusedChoiceIndexForLink(link, choices, used, nodeMap = null) {
  const candidates = [
    normalizeChoiceMatchText(link.label),
    normalizeChoiceMatchText(nodeMap?.get(link.to)?.title)
  ].filter(Boolean);
  for (const candidate of candidates) {
    const exact = choices.findIndex((choice, index) => !used.has(index) && normalizeChoiceMatchText(choice) === candidate);
    if (exact >= 0) return exact;
  }
  for (const candidate of candidates) {
    const partial = choices.findIndex((choice, index) => !used.has(index) && choiceCandidateMatches(candidate, choice));
    if (partial >= 0) return partial;
  }
  return findFirstUnusedChoiceIndex(choices, used);
}

function findFirstUnusedChoiceIndex(choices, used) {
  for (let index = 0; index < choices.length; index += 1) {
    if (!used.has(index)) return index;
  }
  return null;
}

function choiceCandidateMatches(candidate, choice) {
  const choiceText = normalizeChoiceMatchText(choice);
  if (!candidate || !choiceText) return false;
  if (choiceText.startsWith(candidate) || candidate.startsWith(choiceText)) return true;
  const tokens = candidate.split(/\s+/).filter(Boolean);
  return Boolean(tokens.length) && tokens.every((token) => choiceText.includes(token));
}

function normalizeChoiceMatchText(value) {
  return String(value || "")
    .toLowerCase()
    .replace(/[^a-z0-9\u4e00-\u9fff]+/g, " ")
    .trim();
}

function getChoiceOrderedLinks(links) {
  return links
    .map((link, order) => ({ link, order, choiceIndex: normalizeChoiceIndex(link.choiceIndex) }))
    .sort((a, b) => {
      const aIndexed = a.choiceIndex != null;
      const bIndexed = b.choiceIndex != null;
      if (aIndexed && bIndexed) return a.choiceIndex - b.choiceIndex || a.order - b.order;
      if (aIndexed !== bIndexed) return aIndexed ? -1 : 1;
      return a.order - b.order;
    })
    .map((entry) => entry.link);
}

function getChoiceBranchButtonLabel(link, runtimeChoices, fallbackIndex, entries) {
  // Prefer stable choiceOptionId binding (survives reordering); fall back to legacy choiceIndex.
  if (link.choiceOptionId && Array.isArray(entries)) {
    const entry = entries.find((e) => e.optionId === link.choiceOptionId);
    if (entry?.label) return entry.label;
  }
  const choiceIndex = normalizeChoiceIndex(link.choiceIndex);
  if (choiceIndex != null && runtimeChoices[choiceIndex]) return runtimeChoices[choiceIndex];
  return link.label || runtimeChoices[fallbackIndex] || getNode(link.to)?.title || "Continue";
}

function evaluateCondition(source) {
  const text = String(source || "").trim();
  const variables = getRuntimeVariableSource();
  if (!text) return false;
  const parsed = parseJsConditionExpression(text);
  if (parsed.invalid) return false;
  return coerceBoolean(evaluateJsConditionAst(parsed.ast, variables || {}));
}

function isPreviewVisitedStateKeyMet(key) {
  const visitSlug = normalizeStateReportKey(key).slice("visited.".length).toLowerCase();
  if (!visitSlug || !(state.playVisitedNodeIds instanceof Set)) return false;
  return [...state.playVisitedNodeIds].some((nodeId) => {
    const node = getNode(nodeId);
    if (!node) return false;
    const titleSlug = slugPlaybookCategory(node.title || node.id || "node").toLowerCase();
    const idSlug = slugPlaybookCategory(node.id || "node").toLowerCase();
    return titleSlug === visitSlug || idSlug === visitSlug;
  });
}

function collectExpressionPredicates(source) {
  const parsed = parseJsConditionExpression(source);
  if (parsed.invalid) return [];
  const predicates = [];
  const scan = (node) => {
    if (!node) return;
    if (node.type === "call" && node.name === "includes" && node.object?.type === "identifier") {
      predicates.push({
        name: "contains",
        key: normalizeConditionIdentifierPath(node.object.path),
        value: formatJsConditionAst(node.args?.[0], "runtime", { model: { variableNameMap: {}, sourceVariables: {}, variableUsed: new Set(), variables: {} }, warnings: [], ref: {} }),
        invalid: false
      });
      return;
    }
    if (node.type === "call" && JS_CONDITION_LEGACY_FUNCTIONS.has(node.name) && node.args?.[0]?.type === "identifier") {
      predicates.push({
        name: node.name,
        key: normalizeConditionIdentifierPath(node.args[0].path),
        value: formatJsConditionAst(node.args?.[1], "runtime", { model: { variableNameMap: {}, sourceVariables: {}, variableUsed: new Set(), variables: {} }, warnings: [], ref: {} }),
        invalid: false
      });
      return;
    }
    if (node.type === "group") scan(node.expression);
    else if (node.type === "unary") scan(node.argument);
    else if (node.type === "logical" || node.type === "binary") {
      scan(node.left);
      scan(node.right);
    } else if (node.type === "call") {
      scan(node.object);
      (node.args || []).forEach(scan);
    }
  };
  scan(parsed.ast);
  return predicates;
}

function normalizeExpressionVariableTerm(source) {
  const text = String(source || "").trim().replace(/^\$/, "");
  const variablePrefix = text.match(/^variables\.([a-zA-Z_][\w.-]*)$/);
  if (variablePrefix) return variablePrefix[1];
  const match = text.match(/^([a-zA-Z_][\w.-]*)$/);
  return match ? match[1] : "";
}

function parseExpressionLiteral(source) {
  const text = String(source || "").trim();
  if (isQuotedExpressionLiteral(text)) return text.slice(1, -1).replace(/\\(["'\\])/g, "$1");
  if (/^true$/i.test(text)) return true;
  if (/^false$/i.test(text)) return false;
  if (/^null$/i.test(text)) return null;
  if (text !== "" && !Number.isNaN(Number(text))) return Number(text);
  return text;
}

function isQuotedExpressionLiteral(source) {
  return /^"(?:\\.|[^"\\])*"$/.test(String(source || "").trim())
    || /^'(?:\\.|[^'\\])*'$/.test(String(source || "").trim());
}

function expressionContainerHasValue(container, value) {
  if (Array.isArray(container)) {
    return container.some((item) => expressionValuesMatch(item, value));
  }
  if (typeof container === "string") return String(value) !== "" && container.includes(String(value));
  if (container && typeof container === "object") {
    return Object.prototype.hasOwnProperty.call(container, String(value));
  }
  return expressionValuesMatch(container, value);
}

function expressionValuesMatch(left, right) {
  if (left === right) return true;
  const leftNumber = Number(left);
  const rightNumber = Number(right);
  if (Number.isFinite(leftNumber) && Number.isFinite(rightNumber)) return leftNumber === rightNumber;
  return String(left) === String(right);
}

function coerceValue(value) {
  if (String(value).toLowerCase() === "true") return true;
  if (String(value).toLowerCase() === "false") return false;
  if (value !== "" && !Number.isNaN(Number(value))) return Number(value);
  return value;
}

function coerceBoolean(value) {
  if (typeof value === "boolean") return value;
  if (String(value).toLowerCase() === "true") return true;
  if (String(value).toLowerCase() === "false") return false;
  return Boolean(value);
}

function getCharacters() {
  if (!Array.isArray(state.project.characters)) {
    state.project.characters = inferCharacters(state.project);
  }
  state.project.characters = normalizeCharacters(state.project.characters);
  return state.project.characters;
}

function getCastCharacters() {
  return getCharacters().filter((entry) => entry.kind === "Character");
}

function normalizeCharacters(characters) {
  if (!Array.isArray(characters)) return [];
  const seen = new Set();
  return characters
    .map((character, index) => normalizeCharacter(character, index))
    .filter((character) => {
      if (!character || seen.has(character.id)) return false;
      seen.add(character.id);
      return true;
    });
}

function normalizeCharacter(character, index) {
  if (!character || typeof character !== "object") return null;
  const name = String(character.name || `Character ${index + 1}`).trim() || `Character ${index + 1}`;
  const images = normalizeVisionBoardImages(character.images, character.imageFile || character.image || "");
  return {
    id: String(character.id || `c${index}`).trim() || `c${index}`,
    name,
    kind: normalizeCodexKind(character.kind || character.category || "Character"),
    role: String(character.role || ""),
    voice: String(character.voice || ""),
    tags: String(character.tags || ""),
    notes: String(character.notes || ""),
    extraFields: normalizeCodexExtraFields(character.extraFields),
    vaultFiles: normalizeCodexVaultFiles(character.vaultFiles ?? character.files),
    canvasFile: normalizeNodeVaultFileReference(character.canvasFile ?? character.canvas ?? ""),
    icon: normalizeNodeVaultFileReference(character.icon ?? ""),
    codexFile: normalizeNodeVaultFileReference(character.codexFile || ""),
    images,
    imageFile: images[0]?.path || "",
    imagePreview: images.length ? Boolean(character.imagePreview ?? true) : false,
    hidden: Boolean(character.hidden)
  };
}

// Frontmatter keys managed by the built-in fields; custom fields may not shadow them.
const CODEX_RESERVED_FRONTMATTER_KEYS = new Set([
  "narrative_canvas_codex", "id", "name", "category", "kind", "role", "voice",
  "tags", "notes", "images", "image", "image_preview", "hidden", "files", "canvas", "icon"
]);
const CODEX_EXTRA_FIELD_TYPES = new Set(["string", "number", "boolean", "array", "object", "null"]);

function inferCodexExtraFieldType(value) {
  if (value === null) return "null";
  if (Array.isArray(value)) return "array";
  if (typeof value === "number" && Number.isFinite(value)) return "number";
  if (typeof value === "boolean") return "boolean";
  if (value && typeof value === "object") return "object";
  return "string";
}

function normalizeCodexExtraFieldValue(value, type = inferCodexExtraFieldType(value)) {
  if (type === "null") return null;
  if (type === "number") {
    const number = Number(value);
    return Number.isFinite(number) ? number : 0;
  }
  if (type === "boolean") {
    if (typeof value === "string") return value.trim().toLowerCase() === "true";
    return Boolean(value);
  }
  if (type === "array") {
    if (Array.isArray(value)) return value;
    try {
      const parsed = JSON.parse(String(value || "[]"));
      return Array.isArray(parsed) ? parsed : [];
    } catch (_error) {
      return [];
    }
  }
  if (type === "object") {
    if (value && typeof value === "object" && !Array.isArray(value)) return value;
    try {
      const parsed = JSON.parse(String(value || "{}"));
      return parsed && typeof parsed === "object" && !Array.isArray(parsed) ? parsed : {};
    } catch (_error) {
      return {};
    }
  }
  return String(value ?? "");
}

function formatCodexExtraFieldValue(value, type = inferCodexExtraFieldType(value)) {
  if (type === "array" || type === "object") return JSON.stringify(value);
  if (type === "null") return "null";
  return String(value ?? "");
}

function parseCodexExtraFieldInput(value, type) {
  const source = String(value ?? "").trim();
  if (type === "string") return { valid: true, value: String(value ?? "") };
  if (type === "null") return { valid: true, value: null };
  if (type === "number") {
    const number = Number(source);
    return { valid: source !== "" && Number.isFinite(number), value: number };
  }
  if (type === "boolean") {
    if (!["true", "false"].includes(source.toLowerCase())) return { valid: false, value: false };
    return { valid: true, value: source.toLowerCase() === "true" };
  }
  try {
    const parsed = JSON.parse(source);
    if (type === "array") return { valid: Array.isArray(parsed), value: parsed };
    return { valid: Boolean(parsed) && typeof parsed === "object" && !Array.isArray(parsed), value: parsed };
  } catch (_error) {
    return { valid: false, value: type === "array" ? [] : {} };
  }
}

function normalizeCodexVaultFiles(value) {
  const source = Array.isArray(value) ? value : [];
  const seen = new Set();
  return source
    .map((entry) => normalizeNodeVaultFileReference(typeof entry === "string" ? entry : entry?.path || ""))
    .filter((path) => {
      if (!path || seen.has(path)) return false;
      seen.add(path);
      return true;
    });
}

function normalizeCodexExtraFields(value) {
  const source = Array.isArray(value)
    ? value
    : (value && typeof value === "object" ? Object.entries(value).map(([key, entry]) => ({ key, value: entry })) : []);
  const normalized = [];
  source.forEach((entry) => {
    const key = String(entry?.key ?? "").trim();
    if (CODEX_RESERVED_FRONTMATTER_KEYS.has(key.toLowerCase())) return;
    const raw = entry?.value;
    const requestedType = String(entry?.type || "").trim().toLowerCase();
    const type = CODEX_EXTRA_FIELD_TYPES.has(requestedType) ? requestedType : inferCodexExtraFieldType(raw);
    normalized.push({ key, type, value: normalizeCodexExtraFieldValue(raw, type) });
  });
  return normalized;
}

// Per-category custom-field templates: { Character: ["faction", ...], Location: [...], ... }.
// Template keys are prefilled on new entries of that category and merged into existing ones
// when a key is added; removing a template key never deletes entry values.
function normalizeCodexFieldTemplates(value) {
  const source = value && typeof value === "object" && !Array.isArray(value) ? value : {};
  const normalized = {};
  const kinds = [...new Set([...CODEX_KINDS, ...Object.keys(source).map((kind) => String(kind || "").trim()).filter(Boolean)])];
  kinds.forEach((kind) => {
    const seen = new Set();
    normalized[kind] = (Array.isArray(source[kind]) ? source[kind] : [])
      .map((key) => String(key || "").trim())
      .filter((key) => {
        const lower = key.toLowerCase();
        if (!key || CODEX_RESERVED_FRONTMATTER_KEYS.has(lower) || seen.has(lower)) return false;
        seen.add(lower);
        return true;
      });
  });
  return normalized;
}

function getCodexFieldTemplate(kind) {
  const templates = normalizeCodexFieldTemplates(state.project.codexFieldTemplates);
  state.project.codexFieldTemplates = templates;
  return templates[normalizeCodexKind(kind)] || [];
}

function applyCodexTemplateToCharacter(character) {
  const template = getCodexFieldTemplate(character.kind);
  if (!template.length) return false;
  const fields = normalizeCodexExtraFields(character.extraFields);
  const present = new Set(fields.map((field) => field.key.toLowerCase()).filter(Boolean));
  let changed = false;
  template.forEach((key) => {
    if (present.has(key.toLowerCase())) return;
    fields.push({ key, type: "string", value: "" });
    changed = true;
  });
  if (changed) character.extraFields = fields;
  return changed;
}

function normalizeVisionBoardImages(value, legacyReference = "") {
  const source = Array.isArray(value) ? value : [];
  const normalized = [];
  source.forEach((entry, index) => {
    const path = normalizeNodeVaultFileReference(typeof entry === "string" ? entry : entry?.path || entry?.image || entry?.reference);
    if (!path || !CODEX_IMAGE_FILE_PATTERN.test(path) || normalized.some((item) => item.path === path)) return;
    const fallback = getDefaultVisionBoardPlacement(index);
    normalized.push({
      path,
      x: clampVisionBoardNumber(entry?.x, fallback.x, 0, 90),
      y: clampVisionBoardNumber(entry?.y, fallback.y, 0, 88),
      w: clampVisionBoardNumber(entry?.w, fallback.w, 10, 90)
    });
  });
  const legacyPath = normalizeNodeVaultFileReference(legacyReference);
  if (legacyPath && CODEX_IMAGE_FILE_PATTERN.test(legacyPath) && !normalized.some((entry) => entry.path === legacyPath)) {
    const fallback = getDefaultVisionBoardPlacement(normalized.length);
    normalized.unshift({ path: legacyPath, ...fallback });
  }
  return normalized.map((entry, index) => ({ ...getDefaultVisionBoardPlacement(index), ...entry }));
}

function clampVisionBoardNumber(value, fallback, minimum, maximum) {
  const number = Number(value);
  return Number.isFinite(number) ? Math.max(minimum, Math.min(maximum, number)) : fallback;
}

function getDefaultVisionBoardPlacement(index) {
  const column = index % 3;
  const row = Math.floor(index / 3) % 3;
  return { x: 4 + column * 31, y: 5 + row * 30, w: 28 };
}

function getCharacterImages(character) {
  return normalizeVisionBoardImages(character?.images, character?.imageFile || character?.image || "");
}

function syncCharacterImageAliases(character, images = getCharacterImages(character)) {
  character.images = images;
  character.imageFile = images[0]?.path || "";
  character.imagePreview = images.length > 0;
}

function normalizeCodexKind(value) {
  const raw = String(value || "").trim();
  const normalized = raw.toLowerCase();
  if (normalized === "character") return "Character";
  if (normalized === "location") return "Location";
  if (normalized === "item") return "Item";
  if (normalized === "lore") return "Lore";
  // Custom categories keep their name; only an empty value falls back.
  return raw || "Character";
}

function normalizeCustomCodexKinds(value) {
  const seen = new Set(CODEX_KINDS.map((kind) => kind.toLowerCase()));
  return (Array.isArray(value) ? value : [])
    .map((kind) => String(kind || "").trim())
    .filter((kind) => {
      const lower = kind.toLowerCase();
      if (!kind || lower === "all" || seen.has(lower)) return false;
      seen.add(lower);
      return true;
    });
}

// Built-in categories plus user-defined ones plus any category already used by an
// entry (e.g. typed straight into a markdown frontmatter `category`).
function getCodexKindsList() {
  const kinds = [...CODEX_KINDS];
  const push = (kind) => {
    const name = String(kind || "").trim();
    if (name && !kinds.some((existing) => existing.toLowerCase() === name.toLowerCase())) kinds.push(name);
  };
  (Array.isArray(state.project?.customCodexKinds) ? state.project.customCodexKinds : []).forEach(push);
  getCharacters().forEach((entry) => push(entry.kind));
  return kinds;
}

function normalizeCodexKindFilter(value) {
  const normalized = String(value || "").trim();
  if (!normalized || normalized.toLowerCase() === CODEX_ALL_FILTER.toLowerCase()) return CODEX_ALL_FILTER;
  const kind = normalizeCodexKind(normalized);
  return getCodexKindsList().some((existing) => existing.toLowerCase() === kind.toLowerCase()) ? kind : CODEX_ALL_FILTER;
}

function inferCharacters(project) {
  const names = [...new Set((project.nodes || [])
    .filter((node) => isDialogNode(node) && node.title)
    .map((node) => node.title))];
  return names.map((name, index) => ({
    id: `c${index}`,
    name,
    role: "",
    voice: "",
    notes: ""
  }));
}

function normalizeNodeCast(cast) {
  if (!Array.isArray(cast)) return [];
  const seen = new Set();
  return cast
    .map((entry) => {
      const characterId = String(entry?.codexId || entry?.characterId || entry?.id || "").trim();
      if (!characterId) return null;
      const role = normalizeCastRole(entry?.role || entry?.relation);
      return { characterId, role };
    })
    .filter((entry) => {
      if (!entry) return false;
      const key = `${entry.characterId}:${entry.role}`;
      if (seen.has(key)) return false;
      seen.add(key);
      return true;
    })
    .slice(0, 64);
}

function normalizeCastRole(value) {
  const role = String(value || "").trim();
  return CAST_RELATIONS.includes(role) ? role : "Present";
}

function uniqueCharacterName(baseName) {
  const used = new Set(getCharacters().map((character) => character.name));
  if (!used.has(baseName)) return baseName;
  let index = 2;
  while (used.has(`${baseName} ${index}`)) index += 1;
  return `${baseName} ${index}`;
}

function getCharacterById(id) {
  return getCharacterIndex().get(id) || null;
}

function getCharacterName(id) {
  return getCharacterById(id)?.name || "";
}

function getCharacterIndex() {
  const characters = getCharacters();
  const current = state.characterIndex;
  if (current?.characters === characters && current.length === characters.length) return current.map;
  const map = new Map(characters.map((character) => [character.id, character]));
  state.characterIndex = { characters, length: characters.length, map };
  return map;
}

function getActiveCharacterFocusId() {
  if (!state.characterFocusId) return null;
  if (getCharacterById(state.characterFocusId)) return state.characterFocusId;
  state.characterFocusId = null;
  return null;
}

function getActiveCharacterFocus() {
  const id = getActiveCharacterFocusId();
  return id ? getCharacterById(id) : null;
}

function getNodeCharacterLinks(node, options = {}) {
  if (!node) return [];
  const includeCast = options.includeCast !== false;
  const includeEventAggregate = Boolean(options.includeEventAggregate);
  const characters = getCharacters();
  const characterIndex = getCharacterIndex();
  const links = [];

  if (includeCast) {
    normalizeNodeCast(node.cast).forEach((entry) => {
      const character = characterIndex.get(entry.characterId);
      if (character) links.push(createCharacterLink(character, entry.role, "cast"));
    });
  }

  const dialogSpeaker = isDialogNode(node) && node.title
    ? getUniqueCastCharacterByName(node.title)
    : null;
  if (dialogSpeaker) links.push(createCharacterLink(dialogSpeaker, "Speaker", "dialog"));

  const fieldText = getNodeCharacterFieldText(node);
  if (fieldText) {
    getCharactersMentionedInText(fieldText, dialogSpeaker?.id).forEach((entry) => {
      links.push(createCharacterLink(entry, getDefaultCodexRelation(entry), "field"));
    });
  }

  const body = displayBody(node);
  if (body) {
    getCharactersMentionedInText(body, "", { requireAtPrefix: true }).forEach((character) => {
      links.push(createCharacterLink(character, "Mentioned", "mention"));
    });
  }

  if (includeEventAggregate && isEventSheetNode(node)) {
    getEventContainedNodes(node).forEach((child) => {
      getNodeCharacterLinks(child, { includeEventAggregate: false }).forEach((link) => {
        links.push({ ...link, source: "event" });
      });
    });
  }

  return dedupeCharacterLinks(links);
}

function createCharacterLink(character, role, source) {
  return {
    characterId: character.id,
    character,
    role: normalizeCastRole(role),
    source
  };
}

function dedupeCharacterLinks(links) {
  const seen = new Set();
  return links.filter((link) => {
    if (!link?.characterId) return false;
    const key = `${link.characterId}:${normalizeCastRole(link.role)}`;
    if (seen.has(key)) return false;
    seen.add(key);
    return true;
  });
}

function getNodeCharacterFieldText(node) {
  return String(node?.characterEncountered || "");
}

function isMentionNameChar(character) {
  return /[a-z0-9_]/i.test(character || "");
}

function getCharactersMentionedInText(text, excludeCharacterId = "", options = {}) {
  const value = String(text || "");
  if (!value) return [];
  const context = getCharacterMentionContext();
  if (!context.pattern) return [];
  const requireAtPrefix = Boolean(options.requireAtPrefix);
  if (requireAtPrefix && !value.includes("@")) return [];
  const matches = [];
  const seen = new Set();
  context.pattern.lastIndex = 0;
  let match = context.pattern.exec(value);
  while (match) {
    const name = match[0];
    const prefixIndex = match.index - 1;
    const before = value[prefixIndex] || "";
    const beforePrefix = value[prefixIndex - 1] || "";
    const after = value[match.index + name.length] || "";
    const character = context.byName.get(name.toLowerCase());
    const prefixOk = requireAtPrefix
      ? before === "@" && !isMentionNameChar(beforePrefix)
      : !isMentionNameChar(before);
    if (character && character.id !== excludeCharacterId && !seen.has(character.id) && prefixOk && !isMentionNameChar(after)) {
      seen.add(character.id);
      matches.push(character);
    }
    match = context.pattern.exec(value);
  }
  return matches;
}

function getCharacterMentionContext() {
  const cached = state.derived.characterMentionContext;
  const characters = getCharacters();
  if (cached?.characters === characters && cached.length === characters.length) return cached;
  const candidatesByName = new Map();
  characters.forEach((character) => {
    const name = String(character.name || "").trim().toLowerCase();
    if (!name) return;
    if (!candidatesByName.has(name)) candidatesByName.set(name, []);
    candidatesByName.get(name).push(character);
  });
  const byName = new Map();
  candidatesByName.forEach((entries, name) => {
    if (entries.length === 1) byName.set(name, entries[0]);
  });
  const alternatives = [...byName.keys()]
    .sort((a, b) => b.length - a.length)
    .map(escapeRegExp);
  const pattern = alternatives.length ? new RegExp(alternatives.join("|"), "gi") : null;
  const context = { characters, length: characters.length, byName, candidatesByName, pattern };
  state.derived.characterMentionContext = context;
  return context;
}

function getUniqueCastCharacterByName(value) {
  const normalizedName = String(value || "").trim().toLowerCase();
  if (!normalizedName) return null;
  const matches = getCastCharacters().filter((entry) => String(entry.name || "").trim().toLowerCase() === normalizedName);
  return matches.length === 1 ? matches[0] : null;
}

function isNodeRelatedToCharacter(node, characterId) {
  return getNodeCharacterLinks(node, { includeEventAggregate: isEventSheetNode(node) })
    .some((link) => link.characterId === characterId);
}

function getNodeCharacterSummary(node, options = {}) {
  const names = [];
  const seen = new Set();
  getNodeCharacterLinks(node, options).forEach((link) => {
    const name = link.character?.name || getCharacterName(link.characterId);
    if (!name || seen.has(link.characterId)) return;
    seen.add(link.characterId);
    names.push(name);
  });
  return names.join(", ");
}

function getEventFrameCharacterSummary(node) {
  return getNodeCharacterSummary(node, { includeEventAggregate: true });
}

function createCharacterBacklinkGroups() {
  return CHARACTER_BACKLINK_GROUP_DEFS.map((group) => ({
    ...group,
    items: [],
    seen: new Set()
  }));
}

function getIndexedCharacterBacklinkGroups(index, characterId) {
  if (!index.has(characterId)) index.set(characterId, createCharacterBacklinkGroups());
  return index.get(characterId);
}

function addIndexedCharacterBacklink(index, characterId, groupId, node, relation, source) {
  const groups = getIndexedCharacterBacklinkGroups(index, characterId);
  const group = groups.find((item) => item.id === groupId);
  if (!group || !node) return;
  const key = `${node.id}:${relation || ""}`;
  if (group.seen.has(key)) return;
  group.seen.add(key);
  group.items.push({ node, relation, source });
}

function finalizeCharacterBacklinkGroups(groups, sequenceMap) {
  groups.forEach((group) => {
    group.items.sort((a, b) => compareCharacterBacklinkItems(a, b, sequenceMap));
    delete group.seen;
  });
  return groups;
}

function buildCharacterBacklinkIndex(characters = getCharacters()) {
  const sequenceMap = getNodeFlowOrderMap();
  const characterIds = new Set(characters.map((character) => character.id));
  const index = new Map(characters.map((character) => [character.id, createCharacterBacklinkGroups()]));
  const directCharacterIdsByNodeId = new Map();

  state.project.nodes.forEach((node) => {
    const directCharacterIds = new Set();
    const addDirectLink = (characterId, role, relation, source) => {
      if (!characterIds.has(characterId)) return;
      const normalizedRole = normalizeCastRole(role);
      addIndexedCharacterBacklink(index, characterId, normalizedRole, node, relation || getCastRelationLabel(normalizedRole), source);
      directCharacterIds.add(characterId);
    };

    normalizeNodeCast(node.cast).forEach((entry) => {
      addDirectLink(entry.characterId, entry.role, "", "cast");
    });

    if (isDialogNode(node) && node.title) {
      const speaker = getUniqueCastCharacterByName(node.title);
      if (speaker) addDirectLink(speaker.id, "Speaker", getCastRelationLabel("Speaker"), "dialog");
    }

    const fieldText = getNodeCharacterFieldText(node);
    if (fieldText) {
      getCharactersMentionedInText(fieldText).forEach((entry) => {
        const role = getDefaultCodexRelation(entry);
        addDirectLink(entry.id, role, getCastRelationLabel(role), "field");
      });
    }

    const body = displayBody(node);
    if (body) {
      getCharactersMentionedInText(body, "", { requireAtPrefix: true }).forEach((character) => {
        addDirectLink(character.id, "Mentioned", getCastRelationLabel("Mentioned"), "mention");
      });
    }

    directCharacterIdsByNodeId.set(node.id, directCharacterIds);
  });

  state.project.nodes.forEach((node) => {
    if (!isEventSheetNode(node)) return;
    const eventCharacterIds = new Set();
    getEventContainedNodes(node).forEach((child) => {
      directCharacterIdsByNodeId.get(child.id)?.forEach((characterId) => eventCharacterIds.add(characterId));
    });
    eventCharacterIds.forEach((characterId) => {
      if (characterIds.has(characterId)) addIndexedCharacterBacklink(index, characterId, "EventFrames", node, t("Library references"), "event");
    });
  });

  index.forEach((groups) => finalizeCharacterBacklinkGroups(groups, sequenceMap));
  return index;
}

function getCharacterBacklinkGroups(character, index = null) {
  if (index?.has(character.id)) return index.get(character.id);
  return buildCharacterBacklinkIndex([character]).get(character.id) || finalizeCharacterBacklinkGroups(createCharacterBacklinkGroups(), new Map());
}

function compareCharacterBacklinkItems(a, b, sequenceMap) {
  const sequenceA = sequenceMap.get(a.node.id) ?? Number.POSITIVE_INFINITY;
  const sequenceB = sequenceMap.get(b.node.id) ?? Number.POSITIVE_INFINITY;
  if (sequenceA !== sequenceB) return sequenceA - sequenceB;
  return a.node.y - b.node.y || a.node.x - b.node.x || a.node.id.localeCompare(b.node.id);
}

function getTotalCharacterLinkCount() {
  return getCharacterRenderContext().linkCount;
}

function formatNodeSnippet(node) {
  const text = String(displayBody(node) || node.eventDescription || "").replace(/\s+/g, " ").trim();
  if (!text) return "No text";
  return text.length > 96 ? `${text.slice(0, 93)}...` : text;
}

function uniqueVariableKey(baseKey) {
  const variables = normalizeVariablesObject(state.project.variables);
  if (!Object.prototype.hasOwnProperty.call(variables, baseKey)) return baseKey;
  let index = 2;
  while (Object.prototype.hasOwnProperty.call(variables, `${baseKey}_${index}`)) index += 1;
  return `${baseKey}_${index}`;
}

function variableType(value) {
  if (typeof value === "number") return "number";
  if (typeof value === "boolean") return "boolean";
  if (value && typeof value === "object") return "json";
  return "string";
}

function formatVariableValue(value) {
  if (value && typeof value === "object") return JSON.stringify(value);
  return String(value ?? "");
}

function coerceVariableInput(value, type) {
  if (type === "number") return Number(value) || 0;
  if (type === "boolean") return String(value).toLowerCase() === "true";
  if (type === "json") {
    try {
      return JSON.parse(value || "null");
    } catch (error) {
      setStatus("Variable JSON value is invalid.");
      return value;
    }
  }
  return value;
}

function renameVariableReferences(oldKey, newKey) {
  const tokenPattern = new RegExp(`\\{${escapeRegExp(oldKey)}\\}`, "g");
  state.project.nodes.forEach((node) => {
    if (typeof node.body === "string") node.body = node.body.replace(tokenPattern, `{${newKey}}`);
  });
}

function getReachableStory() {
  const entries = getPreviewEntryNodes();
  if (!entries.length) return [];
  const seen = new Set();
  const ordered = [];
  const walk = (node) => {
    if (!node || seen.has(node.id)) return;
    seen.add(node.id);
    ordered.push(node);
    getOutgoing(node.id).forEach((link) => walk(getNode(link.to)));
  };
  entries.forEach(walk);
  return ordered;
}

function getStoryStructure() {
  const entries = new Map(state.project.nodes.map((node) => [node.id, { node, children: [] }]));
  const frames = state.project.nodes.filter((node) => isFrameNode(node));
  const frameIds = new Set(frames.map((node) => node.id));
  const frameChildren = new Map([...frameIds].map((frameId) => [frameId, []]));
  const parentFrameByNodeId = new Map(state.project.nodes.map((node) => [node.id, getStoryParentFrameId(node, frameIds, frames)]));
  const reachable = new Set(getReachableStory().map((node) => node.id));
  const includeMemo = new Map();
  const roots = [];

  state.project.nodes.forEach((node) => {
    const parentId = parentFrameByNodeId.get(node.id);
    if (parentId && entries.has(parentId)) {
      frameChildren.get(parentId)?.push(node.id);
    }
  });

  const shouldInclude = (node) => {
    if (!node) return false;
    if (includeMemo.has(node.id)) return includeMemo.get(node.id);
    const included = isFrameNode(node)
      || reachable.has(node.id)
      || Boolean(parentFrameByNodeId.get(node.id));
    includeMemo.set(node.id, included);
    return included;
  };

  state.project.nodes.forEach((node) => {
    if (!shouldInclude(node)) return;
    const entry = entries.get(node.id);
    const parentId = parentFrameByNodeId.get(node.id);
    const parent = parentId ? getNode(parentId) : null;
    if (parent && entries.has(parent.id) && shouldInclude(parent)) {
      entries.get(parent.id).children.push(entry);
    } else {
      roots.push(entry);
    }
  });

  const sortContext = createStorySortContext();
  const sortEntries = (items) => {
    items.forEach((entry) => sortEntries(entry.children));
    items.sort((a, b) => compareStoryEntries(a, b, sortContext));
  };
  sortEntries(roots);
  return roots;
}

function getStoryParentFrameId(node, frameIds, frames) {
  if (node && Object.prototype.hasOwnProperty.call(node, "frameId")) {
    const explicitParentId = normalizeOptionalString(node.frameId).trim();
    return explicitParentId && frameIds.has(explicitParentId) && explicitParentId !== node.id ? explicitParentId : "";
  }
  const explicitParentId = normalizeOptionalString(node?.frameId).trim();
  if (explicitParentId && frameIds.has(explicitParentId) && explicitParentId !== node.id) return explicitParentId;

  const visualParent = getSmallestContainingFrameForNode(node, frames);
  if (!visualParent || visualParent.id === node?.id) return "";
  if (isFrameNode(node) && wouldCreateFrameCycle(node.id, visualParent.id)) return "";
  return visualParent.id;
}

function createStorySortContext() {
  return { flowOrder: getNodeFlowOrderMap(), computedOrder: new Map() };
}

function compareStoryEntries(a, b, context) {
  const storyOrderA = getNodeStoryOrder(a.node);
  const storyOrderB = getNodeStoryOrder(b.node);
  if (storyOrderA !== storyOrderB) return storyOrderA - storyOrderB;

  const orderA = getStoryEntryOrder(a, context);
  const orderB = getStoryEntryOrder(b, context);
  if (orderA !== orderB) return orderA - orderB;

  return a.node.y - b.node.y || a.node.x - b.node.x || a.node.id.localeCompare(b.node.id);
}

function getStoryEntryOrder(entry, context) {
  if (context.computedOrder.has(entry.node.id)) return context.computedOrder.get(entry.node.id);
  const ownOrder = getNodeIdentityOrder(entry.node, context.flowOrder);
  const childOrder = entry.children.reduce((best, child) => Math.min(best, getStoryEntryOrder(child, context)), Number.POSITIVE_INFINITY);
  const order = Math.min(ownOrder, childOrder);
  context.computedOrder.set(entry.node.id, order);
  return order;
}

function getNodeStoryOrder(node) {
  return Number.isFinite(node?.storyOrder) ? node.storyOrder : Number.POSITIVE_INFINITY;
}

function clearStoryOrderOverrides() {
  state.project.nodes.forEach((node) => delete node.storyOrder);
}

function clearEventRowOrderOverrides() {
  state.project.eventRowOrder = {};
}

function resetStoryOrderToGraph() {
  const hadOverrides = state.project.nodes.some((node) => Number.isFinite(node.storyOrder));
  clearStoryOrderOverrides();
  renderStoryPanel();
  setStatus(hadOverrides ? "Story re-sorted by flow id." : "Story already follows flow id.");
}

function resetEventRowOrderToGraph() {
  const hadOverrides = Object.keys(getEventRowOrderMap()).length > 0;
  clearEventRowOrderOverrides();
  renderEventsSheetPage();
  setStatus(hadOverrides ? "Event rows re-sorted by flow id." : "Event rows already follow flow id.");
}

function getStoryParentMap() {
  const parentMap = new Map();
  const walk = (entries, parentId) => {
    entries.forEach((entry) => {
      parentMap.set(entry.node.id, parentId);
      walk(entry.children, entry.node.id);
    });
  };
  walk(getStoryStructure(), "");
  return parentMap;
}

function getStoryEntriesForParent(parentId) {
  if (!parentId) return getStoryStructure();
  const stack = [...getStoryStructure()];
  while (stack.length) {
    const entry = stack.shift();
    if (entry.node.id === parentId) return entry.children;
    stack.push(...entry.children);
  }
  return [];
}

function getNodeBounds(node) {
  // Pure arithmetic size: never touch the DOM here. getNodeBounds is called for
  // every node on every viewport cull (and inside frame-containment scans), so
  // reading offsetWidth/offsetHeight here caused N forced reflows per render
  // (layout thrashing). The rendered size equals nodeLayoutSize() because
  // renderNodes writes that exact box into the element's inline style.
  const size = nodeLayoutSize(node);
  return {
    left: node.x,
    top: node.y,
    right: node.x + size.width,
    bottom: node.y + size.height
  };
}

function nodeLayoutSize(node) {
  if (!node || typeof node !== "object") {
    return { width: FALLBACK_NODE_META.width, height: minNodeHeight(null) };
  }
  const manualWidth = getManualNodeWidth(node);
  const manualHeight = getManualNodeHeight(node);
  const signature = getNodeLayoutSignature(node, manualWidth, manualHeight);
  const cached = nodeLayoutSizeCache.get(node);
  if (cached && cached.signature === signature) return cached.size;
  const width = manualWidth || defaultNodeWidth(node);
  if (isFrameCollapsed(node)) {
    const size = { width, height: 46 };
    nodeLayoutSizeCache.set(node, { signature, size });
    return size;
  }
  const baseHeight = manualHeight || defaultNodeHeight(node, width);
  const inlineEditField = getActiveInlineEditField(node);
  const height = inlineEditField ? Math.max(baseHeight, minInlineNodeEditHeight(inlineEditField)) : baseHeight;
  const size = { width, height };
  nodeLayoutSizeCache.set(node, { signature, size });
  return size;
}

function boundsContainBounds(container, child) {
  return child.left >= container.left
    && child.top >= container.top
    && child.right <= container.right
    && child.bottom <= container.bottom;
}

function boundsArea(bounds) {
  return Math.max(0, bounds.right - bounds.left) * Math.max(0, bounds.bottom - bounds.top);
}

function moveStoryNode(nodeId, placement) {
  const node = getNode(nodeId);
  if (!node) return;
  const historyBefore = getHistorySnapshot();
  const parent = placement.parentId ? getNode(placement.parentId) : null;
  const parentMap = getStoryParentMap();
  const previousParentId = parentMap.get(nodeId) || "";
  const nextParentId = placement.parentId || "";
  const siblings = getStoryEntriesForParent(placement.parentId)
    .map((entry) => entry.node)
    .filter((sibling) => sibling.id !== nodeId);
  let targetIndex = siblings.length;
  if (placement.targetId) {
    const targetSiblingIndex = siblings.findIndex((sibling) => sibling.id === placement.targetId);
    if (targetSiblingIndex >= 0) targetIndex = placement.mode === "after" ? targetSiblingIndex + 1 : targetSiblingIndex;
  }
  const ordered = [...siblings];
  ordered.splice(targetIndex, 0, node);

  if (previousParentId !== nextParentId) {
    getStoryEntriesForParent(previousParentId)
      .map((entry) => entry.node)
      .filter((sibling) => sibling.id !== nodeId)
      .forEach((sibling, index) => {
        sibling.storyOrder = index;
      });
    moveStoryNodeForParentChange(node, parent, ordered, placement);
  }

  ordered.forEach((sibling, index) => {
    sibling.storyOrder = index;
  });
  state.selectedNodeId = nodeId;
  state.selectedLinkId = null;
  state.panel = "story";
  markProjectStructureChanged();
  renderAll();
  runAfterRender(() => scrollStoryNodeIntoView(nodeId));
  setStatus(parent
    ? `${node.title || getNodeDisplayId(node)} moved inside ${parent.title || getNodeDisplayId(parent)}.`
    : `${node.title || getNodeDisplayId(node)} moved in Story.`);
  commitHistoryFromSnapshot(historyBefore);
}

function moveStoryNodeForParentChange(node, parent, ordered, placement) {
  node.frameId = parent?.id || "";
  const position = parent
    ? getStoryPositionInsideFrame(node, parent, ordered, placement)
    : getStoryPositionAtRoot(node, placement);
  moveNodeWithStoryChildren(node, position.x, position.y);
  if (parent) ensureFrameContainsNodes(parent, [node]);
  sanitizeFrameMembership(state.project);
}

function getStoryPositionInsideFrame(node, parent, ordered, placement) {
  const minX = parent.x + STORY_FRAME_PADDING;
  const minY = parent.y + STORY_FRAME_PADDING + 34;
  const target = placement.targetId && placement.targetId !== parent.id ? getNode(placement.targetId) : null;
  let position = { x: minX, y: minY };

  if (target && target.id !== node.id) {
    const targetBounds = getNodeBounds(target);
    position = {
      x: targetBounds.left,
      y: placement.mode === "before"
        ? targetBounds.top - nodeHeight(node) - 24
        : targetBounds.bottom + 24
    };
  } else {
    const childBounds = ordered
      .filter((candidate) => candidate.id !== node.id)
      .map(getNodeBounds);
    position.y = childBounds.length
      ? Math.max(...childBounds.map((bounds) => bounds.bottom)) + 24
      : minY;
  }

  position.x = Math.max(minX, position.x);
  position.y = Math.max(minY, position.y);
  return avoidNestedFramesInsideParent(node, parent, roundStoryPosition(position));
}

function getStoryPositionAtRoot(node, placement) {
  const target = placement.targetId ? getNode(placement.targetId) : null;
  let position = { x: getRootStoryX(), y: getRootStoryY() };

  if (target && target.id !== node.id) {
    const targetBounds = getNodeBounds(target);
    position = {
      x: targetBounds.left,
      y: placement.mode === "before"
        ? targetBounds.top - nodeHeight(node) - 32
        : targetBounds.bottom + 32
    };
  } else {
    const rootBounds = getStoryEntriesForParent("")
      .map((entry) => entry.node)
      .filter((candidate) => candidate.id !== node.id)
      .map(getNodeBounds);
    if (rootBounds.length) {
      position = {
        x: Math.min(...rootBounds.map((bounds) => bounds.left)),
        y: Math.max(...rootBounds.map((bounds) => bounds.bottom)) + 32
      };
    }
  }

  position.y = Math.max(40, position.y);
  return avoidAllFrames(node, roundStoryPosition(position));
}

function roundStoryPosition(position) {
  return {
    x: Math.round(position.x),
    y: Math.round(position.y)
  };
}

function avoidNestedFramesInsideParent(node, parent, position) {
  const parentBounds = getNodeBounds(parent);
  const nestedFrames = state.project.nodes
    .filter((frame) => frame.id !== node.id && frame.id !== parent.id && isFrameNode(frame))
    .filter((frame) => boundsContainBounds(parentBounds, getNodeBounds(frame)));
  return avoidFrames(node, position, nestedFrames);
}

function avoidAllFrames(node, position) {
  const frames = state.project.nodes.filter((frame) => frame.id !== node.id && isFrameNode(frame));
  return avoidFrames(node, position, frames);
}

function avoidFrames(node, position, frames) {
  let next = { ...position };
  for (let attempt = 0; attempt < 16; attempt += 1) {
    const testBounds = getNodeBounds({ ...node, x: next.x, y: next.y });
    const container = frames
      .filter((frame) => boundsContainBounds(getNodeBounds(frame), testBounds))
      .sort((a, b) => boundsArea(getNodeBounds(a)) - boundsArea(getNodeBounds(b)))
      [0];
    if (!container) return next;
    const containerBounds = getNodeBounds(container);
    next = {
      x: Math.round(containerBounds.right + STORY_FRAME_PADDING),
      y: Math.round(Math.max(containerBounds.top, next.y))
    };
  }
  return next;
}

function moveNodeWithStoryChildren(node, x, y) {
  const descendants = isFrameNode(node) ? getStoryDescendantNodes(node.id) : [];
  const deltaX = Math.round(x - node.x);
  const deltaY = Math.round(y - node.y);
  node.x = Math.round(x);
  node.y = Math.round(y);
  descendants.forEach((descendant) => {
    descendant.x = Math.round(descendant.x + deltaX);
    descendant.y = Math.round(descendant.y + deltaY);
  });
}

function getStoryDescendantNodes(parentId) {
  const parentMap = getStoryParentMap();
  return state.project.nodes.filter((node) => {
    let current = parentMap.get(node.id) || "";
    while (current) {
      if (current === parentId) return true;
      current = parentMap.get(current) || "";
    }
    return false;
  });
}

function ensureFrameContainsNodes(frame, nodes) {
  if (!nodes.length) return;
  const frameBounds = getNodeBounds(frame);
  const childBounds = nodes.map(getNodeBounds);
  const right = Math.max(...childBounds.map((bounds) => bounds.right)) + STORY_FRAME_PADDING;
  const bottom = Math.max(...childBounds.map((bounds) => bounds.bottom)) + STORY_FRAME_PADDING;
  frame.width = Math.max(frame.width || getNodeMeta(frame.type).width || 420, right - frameBounds.left);
  frame.height = Math.max(frame.height || nodeHeight(frame), bottom - frameBounds.top);
}

function getRootStoryX() {
  const rootEntries = getStoryEntriesForParent("");
  const rootX = rootEntries.map((entry) => entry.node.x).filter(Number.isFinite);
  return rootX.length ? Math.min(...rootX) : 80;
}

function getRootStoryY() {
  const rootEntries = getStoryEntriesForParent("");
  const rootY = rootEntries.map((entry) => entry.node.y).filter(Number.isFinite);
  return rootY.length ? Math.min(...rootY) : 120;
}

function getProjectBounds() {
  const activeFrame = getActiveFrameCanvas();
  const nodes = activeFrame ? getFrameDescendantNodes(activeFrame.id) : state.project.nodes;
  if (!nodes.length) {
    if (activeFrame) {
      const frameSize = nodeLayoutSize(activeFrame);
      return {
        x: Math.round(activeFrame.x + 48),
        y: Math.round(activeFrame.y + 58),
        width: Math.max(800, Math.round(frameSize.width - 96)),
        height: Math.max(500, Math.round(frameSize.height - 116))
      };
    }
    return { x: 0, y: 0, width: 800, height: 500 };
  }
  let minX = Number.POSITIVE_INFINITY;
  let minY = Number.POSITIVE_INFINITY;
  let maxRight = Number.NEGATIVE_INFINITY;
  let maxBottom = Number.NEGATIVE_INFINITY;
  nodes.forEach((node) => {
    const size = nodeLayoutSize(node);
    minX = Math.min(minX, node.x);
    minY = Math.min(minY, node.y);
    maxRight = Math.max(maxRight, node.x + size.width);
    maxBottom = Math.max(maxBottom, node.y + size.height);
  });
  return {
    x: minX,
    y: minY,
    width: maxRight - minX,
    height: maxBottom - minY
  };
}

function getExportBounds(nodes, links) {
  if (!nodes.length) return { x: 0, y: 0, width: 800, height: 500 };
  const nodeMap = new Map(nodes.map((node) => [node.id, node]));
  let minX = Number.POSITIVE_INFINITY;
  let minY = Number.POSITIVE_INFINITY;
  let maxRight = Number.NEGATIVE_INFINITY;
  let maxBottom = Number.NEGATIVE_INFINITY;
  nodes.forEach((node) => {
    const size = nodeLayoutSize(node);
    minX = Math.min(minX, node.x);
    minY = Math.min(minY, node.y);
    maxRight = Math.max(maxRight, node.x + size.width);
    maxBottom = Math.max(maxBottom, node.y + size.height);
  });
  links.forEach((link) => {
    const from = nodeMap.get(link.from);
    const to = nodeMap.get(link.to);
    if (!from || !to) return;
    const bounds = getLinkCurveBounds(getOutputPoint(from), getInputPoint(to));
    minX = Math.min(minX, bounds.left);
    minY = Math.min(minY, bounds.top);
    maxRight = Math.max(maxRight, bounds.right);
    maxBottom = Math.max(maxBottom, bounds.bottom);
  });
  return {
    x: minX,
    y: minY,
    width: maxRight - minX,
    height: maxBottom - minY
  };
}

function getEventRowGroups() {
  const typeOrder = new Map(getProjectNodeTypes().map((typeDef, index) => [typeDef.type, index]));
  const groups = new Map();
  getEventRows().forEach((node) => {
    const type = node.type || "Event";
    if (!groups.has(type)) {
      groups.set(type, {
        type,
        label: getNodeTypeLabel(type),
        rows: []
      });
    }
    groups.get(type).rows.push(node);
  });
  return [...groups.values()]
    .sort((a, b) => (typeOrder.get(a.type) ?? Number.POSITIVE_INFINITY) - (typeOrder.get(b.type) ?? Number.POSITIVE_INFINITY)
      || a.label.localeCompare(b.label));
}

function getFilteredEventRowGroups(groups) {
  const query = state.eventSearch.trim().toLowerCase();
  if (!query) return groups;
  return groups
    .map((group) => ({
      ...group,
      rows: group.rows.filter((node) => eventRowMatchesSearch(node, query))
    }))
    .filter((group) => group.rows.length);
}

function eventRowMatchesSearch(node, query) {
  const columns = getEventSheetColumns(node.type);
  const values = [
    node.id,
    getNodeDisplayId(node),
    node.title,
    node.type,
    getNodeTypeLabel(node.type),
    displayBody(node),
    getNodeCharacterSummary(node, { includeEventAggregate: false }),
    ...columns.map((column) => column.key === "characterEncountered"
      ? getNodeCharacterSummary(node, { includeEventAggregate: false })
      : getNodeEventValue(node, column.key))
  ];
  if (values.filter(Boolean).some((value) => String(value).toLowerCase().includes(query))) return true;
  return getEventContainedNodes(node).some((child) => [
      child.id,
      getNodeDisplayId(child),
      child.title,
      getNodeTypeLabel(child.type),
      displayBody(child),
      getNodeCharacterSummary(child, { includeEventAggregate: false })
    ]
    .filter(Boolean)
    .some((value) => String(value).toLowerCase().includes(query)));
}

function getEventRows(type = null) {
  const rows = state.project.nodes
    .filter((node) => isEventSheetNode(node))
    .filter((node) => !type || node.type === type)
    .sort(compareNodesByIdentity);
  return applyEventRowOrder(rows);
}

function getEventRowOrderMap() {
  const map = state.project.eventRowOrder;
  if (!map || typeof map !== "object" || Array.isArray(map)) return {};
  return map;
}

function applyEventRowOrder(rows) {
  const orderMap = getEventRowOrderMap();
  const groups = new Map();
  rows.forEach((node) => {
    const list = groups.get(node.type) || [];
    list.push(node);
    groups.set(node.type, list);
  });
  const ordered = [];
  groups.forEach((list, type) => {
    const order = Array.isArray(orderMap[type]) ? orderMap[type] : [];
    const known = new Set(list.map((node) => node.id));
    const sorted = order
      .filter((id) => known.has(id))
      .map((id) => list.find((node) => node.id === id))
      .filter(Boolean);
    const seenIds = new Set(sorted.map((node) => node.id));
    list.forEach((node) => {
      if (!seenIds.has(node.id)) sorted.push(node);
    });
    ordered.push(...sorted);
  });
  return ordered;
}

function setEventRowOrder(type, ids) {
  if (!type) return;
  if (!state.project.eventRowOrder || typeof state.project.eventRowOrder !== "object" || Array.isArray(state.project.eventRowOrder)) {
    state.project.eventRowOrder = {};
  }
  state.project.eventRowOrder[type] = ids.slice();
}

function moveEventRow(nodeId, targetId, placement) {
  const node = getNode(nodeId);
  const target = getNode(targetId);
  if (!node || !target || node.type !== target.type) return;
  const historyBefore = getHistorySnapshot();
  const rowsInType = getEventRows(node.type);
  const ids = rowsInType.map((row) => row.id).filter((id) => id !== nodeId);
  const targetIndex = ids.indexOf(targetId);
  if (targetIndex < 0) return;
  const insertIndex = placement === "after" ? targetIndex + 1 : targetIndex;
  ids.splice(insertIndex, 0, nodeId);
  setEventRowOrder(node.type, ids);
  renderEventsSheetPage();
  setStatus(`${node.title || getNodeDisplayId(node)} reordered.`);
  commitHistoryFromSnapshot(historyBefore);
}

function getNodeEventValue(node, key) {
  if (!node) return "";
  const customField = getNodeCustomFieldEntries(node).find((field) => field.key === key);
  if (customField) return customField.value;
  if (node.customFields && node.customFields[key] != null && node.customFields[key] !== "") return String(node.customFields[key]);
  if (Array.isArray(node[key])) return node[key].join("\n");
  if (node[key] != null && node[key] !== "") return String(node[key]);
  if (key === "eventDescription") return displayBody(node);
  if (key === "characterEncountered") {
    const summary = isEventSheetNode(node)
      ? getEventFrameCharacterSummary(node)
      : getNodeCharacterSummary(node, { includeEventAggregate: false });
    if (summary) return summary;
    if (isDialogNode(node)) return node.title || "";
  }
  if (key === "eventType") return "";
  if (key === "beatList") return node.title || "";
  return "";
}

function getEventContainedNodes(eventNode) {
  if (!isEventSheetNode(eventNode)) return [];
  return getFrameDescendantNodes(eventNode.id).filter((node) => !isFrameNode(node));
}

function getFrameDescendantNodes(frameId) {
  const sourceId = normalizeOptionalString(frameId).trim();
  if (!sourceId) return [];
  const store = getFrameDescendantNodeStore();
  if (store.cache.has(sourceId)) return store.cache.get(sourceId);
  const result = [];
  const stack = (store.direct.get(sourceId) || []).slice().reverse();
  const seen = new Set([sourceId]);
  while (stack.length) {
    const node = stack.pop();
    if (!node || seen.has(node.id)) continue;
    seen.add(node.id);
    result.push(node);
    const children = store.direct.get(node.id);
    if (children?.length) {
      for (let index = children.length - 1; index >= 0; index -= 1) stack.push(children[index]);
    }
  }
  result.sort((a, b) => a.y - b.y || a.x - b.x);
  store.cache.set(sourceId, result);
  return result;
}

function getFrameDescendantNodeStore() {
  const cached = state.derived.frameDescendantNodes;
  if (derivedStructureUnchanged(cached)) return cached;
  const frameIds = new Set(state.project.nodes.filter((node) => isFrameNode(node)).map((node) => node.id));
  const direct = new Map([...frameIds].map((frameId) => [frameId, []]));
  state.project.nodes.forEach((node) => {
    const parentId = normalizeOptionalString(node.frameId).trim();
    if (parentId && frameIds.has(parentId) && parentId !== node.id) {
      direct.get(parentId)?.push(node);
    }
  });
  const store = derivedStructureStamp(new Map());
  store.direct = direct;
  store.cache = new Map();
  state.derived.frameDescendantNodes = store;
  return store;
}

function formatEventElement(node) {
  const content = displayBody(node).trim();
  const label = `[${getNodeTypeLabel(node.type)} ${getNodeDisplayId(node)}] ${node.title || getNodeDisplayId(node)}`;
  return content ? `${label}\n${content}` : label;
}

function formatCsvCell(value) {
  const text = String(value ?? "");
  return /[",\n\r]/.test(text) ? `"${text.replaceAll('"', '""')}"` : text;
}

function buildExportSvg() {
  const margin = 90;
  const nodes = getExportRenderNodes();
  const nodeIds = new Set(nodes.map((node) => node.id));
  const renderLinks = state.project.links.filter((link) => nodeIds.has(link.from) && nodeIds.has(link.to));
  const bounds = getExportBounds(nodes, renderLinks);
  const width = Math.ceil(bounds.width + margin * 2);
  const height = Math.ceil(bounds.height + margin * 2);
  const offset = { x: margin - bounds.x, y: margin - bounds.y };

  const frameMarkup = nodes.filter(isFrameNode).map((node) => renderExportNode(node, offset)).join("");
  const links = renderLinks.map((link) => renderExportLink(link, offset)).join("");
  const nodeMarkup = nodes.filter((node) => !isFrameNode(node)).map((node) => renderExportNode(node, offset)).join("");

  return `<svg xmlns="http://www.w3.org/2000/svg" width="${width}" height="${height}" viewBox="0 0 ${width} ${height}">
  <defs>
    <pattern id="grid-small" width="16" height="16" patternUnits="userSpaceOnUse">
      <path d="M 16 0 L 0 0 0 16" fill="none" stroke="rgba(255,255,255,0.055)" stroke-width="1"/>
    </pattern>
    <pattern id="grid-large" width="80" height="80" patternUnits="userSpaceOnUse">
      <rect width="80" height="80" fill="url(#grid-small)"/>
      <path d="M 80 0 L 0 0 0 80" fill="none" stroke="rgba(255,255,255,0.09)" stroke-width="1"/>
    </pattern>
    <marker id="export-arrow" viewBox="0 0 8 8" refX="7.5" refY="4" markerWidth="5" markerHeight="5" markerUnits="userSpaceOnUse" orient="auto-start-reverse">
      <path d="M 0 0 L 8 4 L 0 8 z" fill="rgba(220,221,222,0.78)"/>
    </marker>
  </defs>
  <rect width="100%" height="100%" fill="#202020"/>
  <rect width="100%" height="100%" fill="url(#grid-large)"/>
  <text x="28" y="42" fill="#dcddde" font-family="system-ui, sans-serif" font-size="22" font-weight="700">${escapeSvg(state.project.title || "Narrative Canvas")}</text>
  ${frameMarkup}
  ${links}
  ${nodeMarkup}
</svg>`;
}

function getExportRenderNodes() {
  return getCanvasLayerItems().map((item) => item.node);
}

function renderExportNode(node, offset) {
  const meta = getNodeMeta(node.type);
  const size = nodeLayoutSize(node);
  const width = size.width;
  const height = size.height;
  const x = node.x + offset.x;
  const y = node.y + offset.y;
  const isFrame = isFrameNode(node);
  const frameStyle = getExportFrameStyle(node);
  const fill = isFrame ? frameStyle.fill : "rgba(43,43,43,0.96)";
  const stroke = isFrame ? frameStyle.stroke : "rgba(255,255,255,0.13)";
  const bodyLines = wrapSvgText(getNodeExportBody(node), Math.max(14, Math.floor((width - 28) / 7.2)), isFrame ? 8 : 5);
  const titleLines = wrapSvgText(node.title || "Untitled", Math.max(10, Math.floor((width - 76) / 8)), 2);
  const titleText = renderSvgLines(titleLines, x + 14, y + 58, 14, 13, "#dcddde", 700);
  const bodyText = renderSvgLines(bodyLines, x + 14, y + 88, 14, 12, "#dcddde", 400);
  const icon = getNodeIcon(node);

  return `<g>
    <rect x="${x}" y="${y}" width="${width}" height="${height}" rx="7" fill="${fill}" stroke="${stroke}"/>
    <rect x="${x}" y="${y}" width="${width}" height="36" rx="7" fill="rgba(255,255,255,0.06)"/>
    <rect x="${x + 10}" y="${y + 8}" width="22" height="22" rx="4" fill="${meta.color}"/>
    <text x="${x + 21}" y="${y + 24}" text-anchor="middle" fill="#101010" font-family="system-ui, sans-serif" font-size="${getNodeIconFontSize(icon)}" font-weight="800">${escapeSvg(icon)}</text>
    <text x="${x + 40}" y="${y + 23}" fill="#a8a8a8" font-family="system-ui, sans-serif" font-size="12">${escapeSvg(getNodeTypeLabel(node.type))}</text>
    <text x="${x + width - 12}" y="${y + 23}" text-anchor="end" fill="#7a7a7a" font-family="system-ui, sans-serif" font-size="12">${escapeSvg(getNodeDisplayId(node))}</text>
    ${titleText}
    ${bodyText}
    ${hasNodeChoices(node) ? `<text x="${x + 14}" y="${y + height - 16}" fill="#a8a8a8" font-family="system-ui, sans-serif" font-size="12">${node.choices.length} choices</text>` : ""}
  </g>`;
}

function getExportFrameStyle(node) {
  return isEventSheetNode(node)
    ? { fill: "rgba(96,65,150,0.52)", stroke: "rgba(180,140,255,0.62)" }
    : { fill: "rgba(118,124,134,0.2)", stroke: "rgba(188,194,204,0.42)" };
}

function renderExportLink(link, offset) {
  const from = getNode(link.from);
  const to = getNode(link.to);
  if (!from || !to) return "";
  const fromPoint = exportOutputPoint(from, offset);
  const toPoint = exportInputPoint(to, offset);
  const path = linkPath(fromPoint, toPoint);
  const label = link.label ? renderExportLinkLabel(link.label, midpoint(fromPoint, toPoint)) : "";
  return `<path d="${path}" fill="none" stroke="rgba(220,221,222,0.78)" stroke-width="2" stroke-linecap="round" marker-end="url(#export-arrow)"/>${label}`;
}

function renderExportLinkLabel(label, point) {
  return `<text x="${point.x}" y="${point.y - 8}" fill="#a8a8a8" font-family="system-ui, sans-serif" font-size="12" text-anchor="middle">${escapeSvg(label)}</text>`;
}

function exportInputPoint(node, offset) {
  const size = nodeLayoutSize(node);
  return { x: node.x + offset.x - LINK_PORT_ANCHOR_OFFSET, y: node.y + offset.y + size.height / 2 };
}

function exportOutputPoint(node, offset) {
  const size = nodeLayoutSize(node);
  return { x: node.x + offset.x + size.width + LINK_PORT_ANCHOR_OFFSET, y: node.y + offset.y + size.height / 2 };
}

function renderSvgLines(lines, x, y, lineHeight, fontSize, fill, weight) {
  return `<text x="${x}" y="${y}" fill="${fill}" font-family="system-ui, sans-serif" font-size="${fontSize}" font-weight="${weight}">${lines.map((line, index) => `<tspan x="${x}" dy="${index === 0 ? 0 : lineHeight}">${escapeSvg(line)}</tspan>`).join("")}</text>`;
}

function wrapSvgText(value, maxChars, maxLines) {
  const lines = [];
  String(value || "").split(/\r?\n/).forEach((paragraph) => {
    const words = paragraph.split(/\s+/).filter(Boolean);
    let line = "";
    words.forEach((word) => {
      const next = line ? `${line} ${word}` : word;
      if (next.length > maxChars && line) {
        lines.push(line);
        line = word;
      } else {
        line = next;
      }
    });
    if (line) lines.push(line);
    if (!words.length) lines.push("");
  });
  if (lines.length <= maxLines) return lines;
  return [...lines.slice(0, maxLines - 1), `${lines[maxLines - 1].slice(0, Math.max(0, maxChars - 1))}...`];
}

function getExportRasterPlan(svg, presetOrScale = 1) {
  const size = getSvgDimensions(svg);
  const preset = typeof presetOrScale === "object" ? presetOrScale : getExportImageScalePreset(presetOrScale);
  const requested = getExportTargetScale(size.width, size.height, preset);
  const scale = getSafeExportRasterScale(size.width, size.height, requested);
  return {
    ...size,
    requestedScale: requested,
    scale,
    outputWidth: Math.max(1, Math.ceil(size.width * scale)),
    outputHeight: Math.max(1, Math.ceil(size.height * scale)),
    limited: scale < requested - 0.001
  };
}

function getSvgDimensions(svg) {
  const width = Number((String(svg).match(/\swidth="([\d.]+)"/) || [])[1]);
  const height = Number((String(svg).match(/\sheight="([\d.]+)"/) || [])[1]);
  return {
    width: Number.isFinite(width) && width > 0 ? width : 800,
    height: Number.isFinite(height) && height > 0 ? height : 500
  };
}

function getExportTargetScale(width, height, preset) {
  const safeWidth = Math.max(1, Number(width) || 1);
  const safeHeight = Math.max(1, Number(height) || 1);
  const maxWidth = Math.max(1, Number(preset?.maxWidth) || 2048);
  const maxHeight = Math.max(1, Number(preset?.maxHeight) || maxWidth);
  return Math.max(EXPORT_IMAGE_MIN_SCALE, Math.min(maxWidth / safeWidth, maxHeight / safeHeight));
}

function getSafeExportRasterScale(width, height, requestedScale = 1) {
  const requested = Math.max(EXPORT_IMAGE_MIN_SCALE, Number(requestedScale) || 1);
  const safeWidth = Math.max(1, Number(width) || 1);
  const safeHeight = Math.max(1, Number(height) || 1);
  const dimensionLimit = Math.min(EXPORT_IMAGE_MAX_DIMENSION / safeWidth, EXPORT_IMAGE_MAX_DIMENSION / safeHeight);
  const areaLimit = Math.sqrt(EXPORT_IMAGE_MAX_PIXELS / Math.max(1, safeWidth * safeHeight));
  return Math.max(EXPORT_IMAGE_MIN_SCALE, Math.min(requested, dimensionLimit, areaLimit));
}

function getExportImageSuffix(rasterPlan) {
  return `-${rasterPlan.outputWidth}x${rasterPlan.outputHeight}`;
}

function formatExportPixelSize(rasterPlan) {
  return `${rasterPlan.outputWidth} x ${rasterPlan.outputHeight}`;
}

function svgToPngBlob(svg, scale = 1) {
  return new Promise((resolve, reject) => {
    const svgBlob = new Blob([svg], { type: "image/svg+xml" });
    const url = URL.createObjectURL(svgBlob);
    const image = new Image();
    image.onload = () => {
      const outputScale = getSafeExportRasterScale(image.naturalWidth, image.naturalHeight, scale);
      const canvas = document.createElement("canvas");
      canvas.width = Math.max(1, Math.ceil(image.naturalWidth * outputScale));
      canvas.height = Math.max(1, Math.ceil(image.naturalHeight * outputScale));
      const context = canvas.getContext("2d");
      context.fillStyle = "#202020";
      context.fillRect(0, 0, canvas.width, canvas.height);
      context.drawImage(image, 0, 0, canvas.width, canvas.height);
      URL.revokeObjectURL(url);
      canvas.toBlob((blob) => {
        if (blob) resolve(blob);
        else reject(new Error("Canvas export failed."));
      }, "image/png");
    };
    image.onerror = () => {
      URL.revokeObjectURL(url);
      reject(new Error("SVG image export failed."));
    };
    image.src = url;
  });
}

function getNode(id) {
  return getNodeIndex().get(id);
}

function getNodeIndex() {
  const nodes = Array.isArray(state.project.nodes) ? state.project.nodes : [];
  const current = state.nodeIndex;
  if (current?.nodes === nodes && current.length === nodes.length) return current.map;
  const map = new Map(nodes.map((node) => [node.id, node]));
  state.nodeIndex = { nodes, length: nodes.length, map };
  return map;
}

function getLink(id) {
  return getLinkIndex().get(id);
}

function getOutgoing(id) {
  return getOutgoingIndex().get(id) || [];
}

function getLinkIndex() {
  const links = Array.isArray(state.project.links) ? state.project.links : [];
  const current = state.linkIndex;
  if (current?.links === links && current.length === links.length) return current.map;
  const map = new Map(links.map((link) => [link.id, link]));
  state.linkIndex = { links, length: links.length, map };
  return map;
}

function getOutgoingIndex() {
  const links = Array.isArray(state.project.links) ? state.project.links : [];
  const current = state.outgoingIndex;
  if (current?.links === links && current.length === links.length) return current.map;
  const map = new Map();
  links.forEach((link) => {
    if (!map.has(link.from)) map.set(link.from, []);
    map.get(link.from).push(link);
  });
  map.forEach((items, sourceId) => {
    if (items.some((link) => normalizeChoiceIndex(link.choiceIndex) != null)) {
      map.set(sourceId, getChoiceOrderedLinks(items));
    }
  });
  state.outgoingIndex = { links, length: links.length, map };
  return map;
}

function invalidateLinkIndexes() {
  state.linkIndex = null;
  state.outgoingIndex = null;
}

// Derived maps (flow order, display IDs) depend on graph structure, geometry,
// and node-type definitions. They do not depend on ordinary text edits, so the
// cache is keyed by structureVersion rather than dirtyVersion.
function derivedStructureUnchanged(cache) {
  return Boolean(cache)
    && cache.nodes === state.project.nodes
    && cache.links === state.project.links
    && cache.nodesLen === (state.project.nodes ? state.project.nodes.length : 0)
    && cache.linksLen === (state.project.links ? state.project.links.length : 0)
    && cache.version === state.structureVersion;
}

function derivedStructureStamp(map) {
  return {
    nodes: state.project.nodes,
    links: state.project.links,
    nodesLen: state.project.nodes ? state.project.nodes.length : 0,
    linksLen: state.project.links ? state.project.links.length : 0,
    version: state.structureVersion,
    map
  };
}

function getNearestLinkAtClientPoint(clientX, clientY) {
  if (!dom.viewport) return null;
  const point = screenToBoard(clientX, clientY);
  const threshold = 18 / Math.max(0.01, state.view.scale);
  let best = null;
  const nodeMap = getNodeIndex();
  const activeFrame = getActiveFrameCanvas();
  const frameCanvasNodeIds = activeFrame ? getFrameCanvasNodeIdSet(activeFrame.id) : null;
  state.project.links.forEach((link) => {
    const endpoints = getRenderedLinkEndpoints(link, nodeMap, { ignoredCollapsedFrameId: activeFrame?.id || "" });
    if (!endpoints) return;
    const { from, to } = endpoints;
    if (frameCanvasNodeIds && (!frameCanvasNodeIds.has(from.id) || !frameCanvasNodeIds.has(to.id))) return;
    const distance = distancePointToLink(point, getOutputPoint(from), getInputPoint(to));
    if (!best || distance < best.distance) best = { link, distance };
  });
  return best && best.distance <= threshold ? best.link : null;
}

function distancePointToLink(point, from, to) {
  const { c1, c2 } = getLinkControlPoints(from, to);
  let previous = from;
  let minDistance = Number.POSITIVE_INFINITY;
  for (let index = 1; index <= 28; index += 1) {
    const t = index / 28;
    const current = cubicPoint(from, c1, c2, to, t);
    minDistance = Math.min(minDistance, distancePointToSegment(point, previous, current));
    previous = current;
  }
  return minDistance;
}

function getLinkCurveBounds(from, to) {
  const { c1, c2 } = getLinkControlPoints(from, to);
  let minX = Math.min(from.x, to.x);
  let minY = Math.min(from.y, to.y);
  let maxX = Math.max(from.x, to.x);
  let maxY = Math.max(from.y, to.y);
  for (let index = 1; index < 32; index += 1) {
    const point = cubicPoint(from, c1, c2, to, index / 32);
    minX = Math.min(minX, point.x);
    minY = Math.min(minY, point.y);
    maxX = Math.max(maxX, point.x);
    maxY = Math.max(maxY, point.y);
  }
  return { left: minX, top: minY, right: maxX, bottom: maxY };
}

function getLinkControlPoints(from, to) {
  const distance = Math.hypot(to.x - from.x, to.y - from.y);
  const tension = clamp(distance * 0.42, 64, 260);
  const fromVector = getPortSideVector(from.side) || inferLinkControlVector(from, to);
  const toVector = getPortSideVector(to.side) || inferLinkControlVector(to, from);
  return {
    c1: { x: from.x + fromVector.x * tension, y: from.y + fromVector.y * tension },
    c2: { x: to.x + toVector.x * tension, y: to.y + toVector.y * tension }
  };
}

function getPortSideVector(side) {
  if (side === "top") return { x: 0, y: -1 };
  if (side === "right") return { x: 1, y: 0 };
  if (side === "bottom") return { x: 0, y: 1 };
  if (side === "left") return { x: -1, y: 0 };
  return null;
}

function inferLinkControlVector(point, otherPoint) {
  const dx = point.x - otherPoint.x;
  const dy = point.y - otherPoint.y;
  if (Math.abs(dx) >= Math.abs(dy)) return { x: dx >= 0 ? 1 : -1, y: 0 };
  return { x: 0, y: dy >= 0 ? 1 : -1 };
}

function cubicPoint(p0, p1, p2, p3, t) {
  const u = 1 - t;
  const uu = u * u;
  const tt = t * t;
  return {
    x: uu * u * p0.x + 3 * uu * t * p1.x + 3 * u * tt * p2.x + tt * t * p3.x,
    y: uu * u * p0.y + 3 * uu * t * p1.y + 3 * u * tt * p2.y + tt * t * p3.y
  };
}

function distancePointToSegment(point, a, b) {
  const dx = b.x - a.x;
  const dy = b.y - a.y;
  if (dx === 0 && dy === 0) return Math.hypot(point.x - a.x, point.y - a.y);
  const t = Math.max(0, Math.min(1, ((point.x - a.x) * dx + (point.y - a.y) * dy) / (dx * dx + dy * dy)));
  return Math.hypot(point.x - (a.x + dx * t), point.y - (a.y + dy * t));
}

function getInputPoint(node) {
  return getNodePortPoint(node, "input");
}

function getOutputPoint(node) {
  return getNodePortPoint(node, "output");
}

function getNodePortPoint(node, kind) {
  const size = nodeLayoutSize(node);
  const frame = isFrameNode(node);
  const defaults = {
    input: frame ? "left" : "top",
    output: frame ? "right" : "bottom"
  };
  const port = normalizePort(node?.ports?.[kind], defaults[kind] || "top");
  const left = node.x;
  const top = node.y;
  const right = node.x + size.width;
  const bottom = node.y + size.height;
  if (port.side === "top") return { x: left + size.width * port.t, y: top - LINK_PORT_ANCHOR_OFFSET, side: port.side };
  if (port.side === "right") return { x: right + LINK_PORT_ANCHOR_OFFSET, y: top + size.height * port.t, side: port.side };
  if (port.side === "bottom") return { x: left + size.width * port.t, y: bottom + LINK_PORT_ANCHOR_OFFSET, side: port.side };
  return { x: left - LINK_PORT_ANCHOR_OFFSET, y: top + size.height * port.t, side: port.side };
}

function nodeHeight(node) {
  return nodeLayoutSize(node).height;
}

function defaultNodeWidth(node) {
  const meta = getNodeMeta(node?.type);
  const baseWidth = meta.width || (isFrameNode(node) ? nodeTypes.Event.width : FALLBACK_NODE_META.width);
  const maxWidth = isFrameNode(node) ? NODE_AUTO_FRAME_MAX_WIDTH : Math.min(maxNodeWidth(node), NODE_AUTO_MAX_WIDTH);
  const minWidth = isFrameNode(node) ? minNodeWidth(node) : Math.max(minNodeWidth(node), NODE_AUTO_MIN_WIDTH);
  const widestTextUnits = getNodeAutoSizeTextParts(node)
    .reduce((widest, part) => Math.max(widest, maxTextLineUnits(part)), 0);
  const contentWidth = Math.ceil(108 + widestTextUnits * 6.8);
  return Math.round(clamp(Math.max(baseWidth, contentWidth), minWidth, maxWidth));
}

function defaultNodeHeight(node, width = defaultNodeWidth(node)) {
  const titleLines = Math.min(2, Math.max(1, estimateWrappedLineCount(getNodeDisplayTitle(node, "Untitled"), width - 76, 8)));
  const body = displayBody(node);
  const maxBodyLines = isFrameNode(node) ? NODE_AUTO_FRAME_MAX_BODY_LINES : NODE_AUTO_MAX_BODY_LINES;
  const bodyLines = body
    ? Math.min(maxBodyLines, Math.max(NODE_AUTO_MIN_BODY_LINES, estimateWrappedLineCount(body, width - 28, 7.2)))
    : 0;
  const castLine = normalizeNodeCast(node?.cast).length ? 1 : 0;
  const choicesLine = hasNodeChoices(node) ? 1 : 0;
  const choiceFollowupLabels = getChoiceFollowupLabels(node);
  const choiceFollowupLines = choiceFollowupLabels.length
    ? Math.min(3, Math.max(1, estimateWrappedLineCount(choiceFollowupLabels.join(" · "), width - 28, 7)))
    : 0;
  const vaultFileHeight = window.NarrativeCanvasHost?.readVaultFile
    ? getNodeVaultFiles(node).reduce((height, entry) => {
      if (!entry.preview) return height + 42;
      if (CODEX_IMAGE_FILE_PATTERN.test(entry.path)) {
        return height + normalizeVaultPreviewSize(entry.previewSize) + 46;
      }
      return height + 174;
    }, 0)
    : 0;
  const contentHeight = 34 + 26 + titleLines * 17 + bodyLines * 17 + castLine * 24 + choicesLine * 24 + choiceFollowupLines * 23 + vaultFileHeight;
  return Math.round(clamp(contentHeight, minNodeHeight(node), maxNodeHeight(node)));
}

function getManualNodeWidth(node) {
  const value = Number(node?.width);
  return Number.isFinite(value) && value > 0 ? Math.round(clamp(value, minNodeWidth(node), maxNodeWidth(node))) : null;
}

function getManualNodeHeight(node) {
  const value = Number(node?.height);
  return Number.isFinite(value) && value > 0 ? Math.round(clamp(value, minNodeHeight(node), maxNodeHeight(node))) : null;
}

function getNodeLayoutSignature(node, manualWidth, manualHeight) {
  return [
    state.structureVersion,
    manualWidth || "",
    manualHeight || "",
    isFrameCollapsed(node) ? "collapsed" : "",
    getActiveInlineEditField(node) || "",
    node?.type || "",
    getNodeTypeLabel(node?.type),
    getNodeDisplayTitle(node, "Untitled"),
    getChoiceFollowupLabels(node).join("\n"),
    displayBody(node),
    parseChoiceLines(node?.choices).join("\n"),
    normalizeNodeCast(node?.cast).map((entry) => `${entry.role}:${entry.characterId}`).join("|"),
    getNodeVaultFiles(node).map((entry) => `${entry.path}:${entry.preview ? "preview" : "link"}`).join("|"),
    getNodeCustomFieldEntries(node).map((field) => `${field.key}:${field.value}`).join("|")
  ].join("\u001f");
}

function getNodeAutoSizeTextParts(node) {
  const customFields = getNodeCustomFieldEntries(node)
    .filter((field) => field.value !== "")
    .map((field) => `${field.label}: ${field.value}`);
  const cast = normalizeNodeCast(node?.cast).map((entry) => `${entry.characterId} ${entry.role}`);
  return [
    getNodeTypeLabel(node?.type),
    getNodeDisplayTitle(node, "Untitled"),
    displayBody(node),
    ...parseChoiceLines(node?.choices),
    ...customFields,
    ...cast
  ].filter((part) => String(part || "").trim() !== "");
}

function maxTextLineUnits(value) {
  return String(value || "")
    .split(/\r?\n/)
    .reduce((widest, line) => Math.max(widest, estimateTextUnits(line)), 0);
}

function estimateWrappedLineCount(value, width, unitPx) {
  const text = String(value || "");
  if (!text) return 0;
  const unitsPerLine = Math.max(8, Math.floor(Math.max(80, width) / unitPx));
  return text.split(/\r?\n/).reduce((count, line) => {
    const units = Math.max(1, estimateTextUnits(line));
    return count + Math.max(1, Math.ceil(units / unitsPerLine));
  }, 0);
}

function estimateTextUnits(value) {
  let units = 0;
  for (const char of String(value || "")) {
    if (char === "\t") {
      units += 4;
      continue;
    }
    const code = char.codePointAt(0);
    units += code > 0xffff || isWideTextCodePoint(code) ? 1.75 : 1;
  }
  return units;
}

function isWideTextCodePoint(code) {
  return (code >= 0x2e80 && code <= 0xa4cf)
    || (code >= 0xac00 && code <= 0xd7a3)
    || (code >= 0xf900 && code <= 0xfaff)
    || (code >= 0xff01 && code <= 0xff60);
}

function getNodeExportBody(node) {
  const propertyLines = getNodeCustomFieldEntries(node)
    .filter((field) => field.value !== "")
    .map((field) => `${field.label}: ${field.value}`);
  return [displayBody(node), ...propertyLines].filter(Boolean).join("\n");
}

function minNodeWidth(node) {
  return isFrameNode(node) ? 260 : 140;
}

function minNodeHeight(node) {
  return isFrameNode(node) ? 160 : 96;
}

function maxNodeWidth(node) {
  return isFrameNode(node) ? Number.POSITIVE_INFINITY : 860;
}

function maxNodeHeight(node) {
  // Nodes with several previews legitimately grow tall; the reader can always
  // resize smaller by hand.
  return isFrameNode(node) ? Number.POSITIVE_INFINITY : 1400;
}

// DOM-measuring size, for the few callers that want the actual rendered box
// (resize start, auto-layout, center view). Not used on the per-render cull path.
function nodeSize(node) {
  const element = getNodeElementById(node.id);
  if (element && element.offsetWidth > 0 && element.offsetHeight > 0) {
    return { width: element.offsetWidth, height: element.offsetHeight };
  }
  return nodeLayoutSize(node);
}

function linkPath(from, to) {
  const { c1, c2 } = getLinkControlPoints(from, to);
  return `M ${from.x} ${from.y} C ${c1.x} ${c1.y}, ${c2.x} ${c2.y}, ${to.x} ${to.y}`;
}

function midpoint(a, b) {
  return { x: (a.x + b.x) / 2, y: (a.y + b.y) / 2 };
}

function screenToBoard(clientX, clientY) {
  const rect = dom.viewport.getBoundingClientRect();
  return {
    x: (clientX - rect.left + dom.viewport.scrollLeft - state.view.x) / state.view.scale,
    y: (clientY - rect.top + dom.viewport.scrollTop - state.view.y) / state.view.scale
  };
}

function displayBody(node) {
  return node.body || "";
}

function getNodeIcon(node) {
  const meta = getNodeMeta(node?.type);
  return normalizeNodeTypeBadge(meta.badge) || getDefaultNodeTypeBadge(meta.label || node?.type || "Node");
}

function getNodeIconSize(icon) {
  const length = getTextGraphemes(icon).length;
  if (length <= 1) return "single";
  return length === 2 ? "double" : "wide";
}

function getNodeIconFontSize(icon) {
  const length = getTextGraphemes(icon).length;
  if (length <= 1) return 12;
  return length === 2 ? 10 : 8;
}

function firstGrapheme(value) {
  return getTextGraphemes(value)[0] || "";
}

function uppercaseIconGrapheme(value) {
  return firstGrapheme(String(value || "").toLocaleUpperCase()) || String(value || "");
}

function normalizeCustomIconText(value) {
  const graphemes = getTextGraphemes(String(value || "").toLocaleUpperCase());
  const accepted = [];
  let units = 0;
  for (const grapheme of graphemes) {
    const nextUnits = iconGraphemeUnits(grapheme);
    if (accepted.length && units + nextUnits > NODE_TYPE_ICON_MAX_UNITS) break;
    accepted.push(grapheme);
    units += nextUnits;
    if (units >= NODE_TYPE_ICON_MAX_UNITS) break;
  }
  return accepted.join("");
}

function iconGraphemeUnits(grapheme) {
  if (!grapheme) return 0;
  if (/[\u3400-\u4dbf\u4e00-\u9fff\uf900-\ufaff]/.test(grapheme)) return 2;
  if ((grapheme.codePointAt(0) || 0) > 0xffff) return 2;
  if (/[\u2600-\u27bf]/.test(grapheme)) return 2;
  return 1;
}

function getTextGraphemes(value) {
  const text = String(value || "").trim().replace(/\s+/g, "");
  if (!text) return [];
  if (graphemeSegmenter) {
    return [...graphemeSegmenter.segment(text)].map((part) => part.segment).filter(Boolean);
  }
  return Array.from(text);
}

function nodeMatches(node, query, options = {}) {
  if (getNodeSearchText(node).includes(query)) return true;
  const includeCharacterTerms = options.includeCharacterTerms ?? queryCanMatchCharacterTerms(query);
  return includeCharacterTerms && getNodeCharacterSearchText(node).includes(query);
}

function getNodeSearchText(node) {
  if (!node?.id) return "";
  const cache = getNodeSearchTextCache();
  if (cache.has(node.id)) return cache.get(node.id);
  const text = [node.type, node.title, node.body, ...(node.choices || []), ...Object.values(node.customFields || {})]
    .filter(Boolean)
    .map((value) => String(value).toLowerCase())
    .join("\n");
  cache.set(node.id, text);
  return text;
}

function getNodeSearchTextCache() {
  const cached = state.derived.nodeSearchText;
  if (cached?.dirtyVersion === state.dirtyVersion && cached?.structureVersion === state.structureVersion) return cached.map;
  const map = new Map();
  state.derived.nodeSearchText = { dirtyVersion: state.dirtyVersion, structureVersion: state.structureVersion, map };
  return map;
}

function getNodeCharacterSearchText(node) {
  if (!node?.id) return "";
  const castTerms = getNodeCharacterLinks(node, { includeEventAggregate: isEventSheetNode(node) })
    .flatMap((link) => [link.character?.name, link.role]);
  return castTerms.filter(Boolean).map((value) => String(value).toLowerCase()).join("\n");
}

function queryCanMatchCharacterTerms(query) {
  const text = String(query || "").trim().toLowerCase();
  if (!text) return false;
  if (CAST_RELATIONS.some((role) => role.toLowerCase().includes(text))) return true;
  return getCharacters().some((character) => String(character.name || "").toLowerCase().includes(text));
}

function getCanvasLayerItems() {
  return state.project.nodes
    .map((node, index) => ({ node, index, order: getNodeLayerOrder(node, index) }))
    .sort((a, b) => a.order - b.order || a.index - b.index);
}

function getNodeLayerOrder(node, index) {
  if (Number.isFinite(node.layerOrder)) return node.layerOrder;
  return (isFrameNode(node) ? EVENT_LAYER_BASE : REGULAR_LAYER_BASE) + index;
}

function isFrameNode(node) {
  return isFrameKind(getNodeMeta(node?.type).kind);
}

function isFrameKind(kind) {
  return kind === "frame";
}

function isEventSheetNode(node) {
  return isEventSheetTypeDef(getNodeMeta(node?.type));
}

function isEventSheetTypeDef(typeDef) {
  return Boolean(typeDef && isFrameKind(typeDef.kind) && !typeDef.eventSheetHidden);
}

function getNodeDisplayId(node) {
  if (!node) return "";
  return getNodeDisplayIdMap().get(node.id) || node.id;
}

function getNodeDisplayIdMap() {
  const cached = state.derived.displayId;
  if (derivedStructureUnchanged(cached)) return cached.map;
  const flowOrderMap = getNodeFlowOrderMap();
  const indexedNodes = state.project.nodes.map((node, index) => ({
    node,
    index,
    identityOrder: getNodeIdentityOrder(node, flowOrderMap)
  }));
  const counters = { node: 0, frame: 0 };
  const prefixes = { node: "n", frame: "f" };
  const displayMap = new Map();

  indexedNodes
    .sort((a, b) => compareIndexedNodeIdentityOrder(a, b))
    .forEach(({ node }) => {
      const category = getNodeDisplayCategory(node);
      counters[category] += 1;
      displayMap.set(node.id, `${prefixes[category]}${counters[category]}`);
    });

  state.derived.displayId = derivedStructureStamp(displayMap);
  return displayMap;
}

function compareIndexedNodeIdentityOrder(a, b) {
  if (a.identityOrder !== b.identityOrder) return a.identityOrder - b.identityOrder;
  if (a.node.y !== b.node.y) return a.node.y - b.node.y;
  if (a.node.x !== b.node.x) return a.node.x - b.node.x;
  const numberA = getNodeIdNumber(a.node?.id);
  const numberB = getNodeIdNumber(b.node?.id);
  if (numberA !== numberB) return numberA - numberB;
  return a.index - b.index;
}

function getNodeDisplayCategory(node) {
  if (isFrameNode(node)) return "frame";
  return "node";
}

function compareNodesByIdentity(a, b) {
  return compareNodeIdentityOrder({ node: a, index: state.project.nodes.indexOf(a) }, { node: b, index: state.project.nodes.indexOf(b) }, getNodeFlowOrderMap());
}

function compareNodeIdentityOrder(a, b, flowOrderMap = getNodeFlowOrderMap()) {
  const orderA = getNodeIdentityOrder(a.node, flowOrderMap);
  const orderB = getNodeIdentityOrder(b.node, flowOrderMap);
  if (orderA !== orderB) return orderA - orderB;
  if (a.node.y !== b.node.y) return a.node.y - b.node.y;
  if (a.node.x !== b.node.x) return a.node.x - b.node.x;
  const numberA = getNodeIdNumber(a.node?.id);
  const numberB = getNodeIdNumber(b.node?.id);
  if (numberA !== numberB) return numberA - numberB;
  return a.index - b.index;
}

function getNodeIdentityOrder(node, flowOrderMap) {
  if (!node) return Number.POSITIVE_INFINITY;
  const ownOrder = flowOrderMap.get(node.id) ?? Number.POSITIVE_INFINITY;
  if (!isFrameNode(node)) return ownOrder;
  const childOrder = getFrameChildFlowOrderMap(flowOrderMap).get(node.id) ?? Number.POSITIVE_INFINITY;
  return Math.min(ownOrder, childOrder);
}

function getFrameChildFlowOrderMap(flowOrderMap = getNodeFlowOrderMap()) {
  const cached = state.derived.frameChildFlowOrder;
  if (derivedStructureUnchanged(cached)) return cached.map;
  const frameIds = new Set(state.project.nodes.filter((node) => isFrameNode(node)).map((node) => node.id));
  const orderMap = new Map();
  state.project.nodes.forEach((node) => {
    const order = flowOrderMap.get(node.id) ?? Number.POSITIVE_INFINITY;
    let parentId = normalizeOptionalString(node.frameId).trim();
    const seen = new Set();
    while (parentId && frameIds.has(parentId) && !seen.has(parentId)) {
      seen.add(parentId);
      orderMap.set(parentId, Math.min(orderMap.get(parentId) ?? Number.POSITIVE_INFINITY, order));
      parentId = normalizeOptionalString(getNode(parentId)?.frameId).trim();
    }
  });
  state.derived.frameChildFlowOrder = derivedStructureStamp(orderMap);
  return orderMap;
}

function getNodeFlowOrderMap() {
  const cached = state.derived.flowOrder;
  if (derivedStructureUnchanged(cached)) return cached.map;
  const orderMap = new Map();
  let order = 0;
  // Iterative pre-order DFS (explicit stack) instead of recursion: a deep graph
  // (e.g. a long chain in a large project) would overflow the call stack. Children
  // are pushed in reverse sorted order so they pop in sorted order, matching the
  // previous recursive pre-order traversal.
  const visit = (startNode) => {
    if (!startNode) return;
    const stack = [startNode];
    while (stack.length) {
      const node = stack.pop();
      if (!node || orderMap.has(node.id)) continue;
      orderMap.set(node.id, order);
      order += 1;
      const children = getOutgoing(node.id)
        .map((link) => getNode(link.to))
        .filter(Boolean)
        .sort(compareRawNodePosition);
      for (let i = children.length - 1; i >= 0; i -= 1) stack.push(children[i]);
    }
  };
  state.project.nodes
    .filter((node) => node.type === "Entry")
    .sort(compareRawNodePosition)
    .forEach(visit);
  state.project.nodes
    .slice()
    .sort(compareRawNodePosition)
    .forEach(visit);
  state.derived.flowOrder = derivedStructureStamp(orderMap);
  return orderMap;
}

function compareRawNodePosition(a, b) {
  return a.y - b.y || a.x - b.x || getNodeIdNumber(a.id) - getNodeIdNumber(b.id) || String(a.id).localeCompare(String(b.id));
}

function getNodeIdNumber(id) {
  const match = String(id || "").match(/\d+/);
  return match ? Number(match[0]) : Number.POSITIVE_INFINITY;
}

function nextId(prefix, items) {
  const used = new Set(items.map((item) => item.id));
  let index = 0;
  while (used.has(`${prefix}${index}`)) index += 1;
  return `${prefix}${index}`;
}

function updateStatus() {
  if (!dom.statusText) return;
  if (!state.statusOverride) {
    if (state.activeFileId === "characters") {
      dom.statusText.textContent = `${getFileViewLabel("characters")} - ${t("{entries} library entries, {links} node links", { entries: getCharacters().length, links: getTotalCharacterLinkCount() })}`;
      return;
    }
    if (state.activeFileId === "variables") {
      dom.statusText.textContent = `${getFileViewLabel("variables")} - ${t("{count} variables", { count: Object.keys(state.project.variables || {}).length })}`;
      return;
    }
    if (state.activeFileId === "events") {
      dom.statusText.textContent = `${getFileViewLabel("events")} - ${t("{count} event rows", { count: getEventRows().length })}`;
      return;
    }
    const activeFrame = getActiveFrameCanvas();
    if (activeFrame && isCanvasFileActive()) {
      const nodeCount = getFrameDescendantNodes(activeFrame.id).length;
      const visibleIds = getFrameCanvasNodeIdSet(activeFrame.id) || new Set();
      const linkCount = state.project.links.filter((link) => visibleIds.has(link.from) && visibleIds.has(link.to)).length;
      dom.statusText.textContent = `${getNodeDisplayTitle(activeFrame, t("Frame"))} - ${t("{nodes} nodes, {links} links", { nodes: nodeCount, links: linkCount })}`;
      return;
    }
    const nodeCount = state.project.nodes.length;
    const linkCount = state.project.links.length;
    dom.statusText.textContent = `${state.project.title} - ${t("{nodes} nodes, {links} links", { nodes: nodeCount, links: linkCount })}`;
  }
}

function setStatus(message) {
  if (!dom.statusText) return;
  state.statusOverride = true;
  dom.statusText.textContent = translateStatusMessage(message);
  clearStatusTimer(false);
  state.statusTimer = window.setTimeout(() => {
    state.statusOverride = false;
    state.statusTimer = null;
    updateStatus();
  }, 1800);
}

const statusTranslationRules = [
  { pattern: /^Image export maximum set to (.+)\.$/, key: "Image export maximum set to {value}.", names: ["value"] },
  { pattern: /^Image exported at (.+)\.$/, key: "Image exported at {value}.", names: ["value"] },
  { pattern: /^(.+) sidebar (collapsed|expanded)\.$/, key: "{side} sidebar {state}.", names: ["side", "state"], translateValues: true },
  { pattern: /^(.+) sidebar resized\.$/, key: "{side} sidebar resized.", names: ["side"], translateValues: true },
  { pattern: /^(.+) applied\.$/, key: "{label} applied.", names: ["label"], translateValues: true },
  { pattern: /^(.+) failed\.$/, key: "{label} failed.", names: ["label"], translateValues: true },
  { pattern: /^Showing more (.+)\.$/, key: "Showing more {file}.", names: ["file"], translateValues: true },
  { pattern: /^(.+) hidden from Events Sheet\.$/, key: "{label} hidden from Events Sheet.", names: ["label"], translateValues: true },
  { pattern: /^(.+) shown in Events Sheet\.$/, key: "{label} shown in Events Sheet.", names: ["label"], translateValues: true },
  { pattern: /^(.+) renamed to (.+)\.$/, key: "{oldName} renamed to {newName}.", names: ["oldName", "newName"], translateValues: true },
  { pattern: /^(.+) column hidden\. Data kept\.$/, key: "{label} column hidden. Data kept.", names: ["label"], translateValues: true },
  { pattern: /^(.+) column shown\.$/, key: "{label} column shown.", names: ["label"], translateValues: true },
  { pattern: /^(.+) column deleted\.$/, key: "{label} column deleted.", names: ["label"], translateValues: true },
  { pattern: /^(\d+) nodes deleted and archived outside runtime\.$/, key: "{count} nodes deleted and archived outside runtime.", names: ["count"] },
  { pattern: /^(.+) opened\.$/, key: "{file} opened.", names: ["file"], translateValues: true },
  { pattern: /^(.+) node type added\.$/, key: "{label} node type added.", names: ["label"], translateValues: true },
  { pattern: /^(.+) is a system type and cannot be deleted\.$/, key: "{label} is a system type and cannot be deleted.", names: ["label"], translateValues: true },
  { pattern: /^(.+) node type deleted\.$/, key: "{label} node type deleted.", names: ["label"], translateValues: true },
  { pattern: /^(.+) hidden from Node Library\. Data kept\.$/, key: "{label} hidden from Node Library. Data kept.", names: ["label"], translateValues: true },
  { pattern: /^(.+) restored to Node Library\.$/, key: "{label} restored to Node Library.", names: ["label"], translateValues: true },
  { pattern: /^Updated (\d+) references?\.$/, key: "Updated {count} references.", names: ["count"] },
  { pattern: /^(.+) rule added from selected node\.$/, key: "{rule} rule added from selected node.", names: ["rule"], translateValues: true },
  { pattern: /^(.+) is a system rule\.$/, key: "{rule} is a system rule.", names: ["rule"], translateValues: true },
  { pattern: /^(.+) disabled\.$/, key: "{rule} disabled.", names: ["rule"], translateValues: true },
  { pattern: /^(.+) (enabled|disabled)\.$/, key: "{rule} {state}.", names: ["rule", "state"], translateValues: true },
  { pattern: /^(.+) focused for editing\.$/, key: "{label} focused for editing.", names: ["label"], translateValues: true },
  { pattern: /^(.+) focused\.$/, key: "{label} focused.", names: ["label"], translateValues: true },
  { pattern: /^Branch set: (.+)\.$/, key: "Branch set: {label}.", names: ["label"], translateValues: true },
  { pattern: /^New project created at (.+)\.$/, key: "New project created at {target}.", names: ["target"] },
  { pattern: /^Loaded (.+)\.$/, key: "Loaded {target}.", names: ["target"], translateValues: true },
  { pattern: /^Created (.+)\.$/, key: "Created {target}.", names: ["target"] },
  { pattern: /^(.+) reordered\.$/, key: "{label} reordered.", names: ["label"], translateValues: true },
  { pattern: /^Link created: (.+)\.$/, key: "Link created: {label}.", names: ["label"], translateValues: true },
  { pattern: /^(.+) added\.$/, key: "{label} added.", names: ["label"], translateValues: true },
  { pattern: /^(.+) deleted\.$/, key: "{label} deleted.", names: ["label"], translateValues: true }
];

function translateStatusMessage(message) {
  const text = String(message || "");
  const exact = t(text);
  if (exact !== text) return exact;
  for (const rule of statusTranslationRules) {
    const match = text.match(rule.pattern);
    if (!match) continue;
    const replacements = {};
    rule.names.forEach((name, index) => {
      const value = match[index + 1] || "";
      replacements[name] = rule.translateValues ? t(value) : value;
    });
    return t(rule.key, replacements);
  }
  return text;
}

function titleCase(value) {
  return `${value.charAt(0).toUpperCase()}${value.slice(1)}`;
}

function slugify(value) {
  return String(value).toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/^-|-$/g, "") || "narrative-canvas";
}

function clamp(value, min, max) {
  return Math.max(min, Math.min(max, value));
}

function escapeHtml(value) {
  return String(value ?? "")
    .replaceAll("&", "&amp;")
    .replaceAll("<", "&lt;")
    .replaceAll(">", "&gt;")
    .replaceAll('"', "&quot;")
    .replaceAll("'", "&#39;");
}

function escapeSvg(value) {
  return escapeHtml(value);
}

function escapeAttr(value) {
  return escapeHtml(value).replaceAll("\n", "&#10;");
}

function escapeRegExp(value) {
  return String(value).replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
}
